#!/usr/bin/env Rscript
# =============================================================================
# 自检脚本
# =============================================================================
#     Rscript selftest.R          # 在应用目录下跑
#
# 只做**离线**检查：不联网、不需要 API Key、不写真实数据目录。
# 目标是回答一个问题：「这次改动有没有把什么弄坏？」
#
# 为什么值得单独写一个：这个应用的很多行为没法靠"打开页面看一眼"验证 ——
# 比如流式增量读取、三种分析环境的提示词分流、模型名迁移。它们平时不出声，
# 坏了也不报错，只是结果不对。下面每一条都对应一个曾经踩过或差点踩到的坑。
#
# 部署脚本 deploy.sh --check 会顺带跑它。
# =============================================================================

suppressMessages(library(shiny))

ok_all <- TRUE
fail_n <- 0L

# ⚠️ 条件求值**出错**必须当成"这条没过"，不能让它冒出去。
#
#    原来的写法是直接 `if (isTRUE(cond))`：被检查的函数一抛异常，整个自检
#    当场中断（`Execution halted`），**后面的几百条一条都不跑**，而屏幕上
#    没有 ✗ —— 看起来像"全过了"。变异测试里真踩到过：把一个守卫拆掉，
#    函数对 NULL 抛错，harness 报的是"没抓到（这条断言是假的）"，实际是
#    自检崩在了那一行。方向完全反了，会让人去改一条根本没错的断言。
#
#    出错和"条件为假"都算 ✗，但要把错误信息打出来 —— 两者要修的地方不同。
# extra 是可选的：失败时把"当时到底是什么"打出来。✗ 只说了哪一条没过，
# 不说实际值的话，很多断言得回去加 print 再跑一遍才能定位（tests/ui_* 里的
# Chk 一直是这么做的，这边补齐）。
chk <- function(name, cond, extra = NULL) {
  res <- tryCatch(isTRUE(cond), error = function(e) e)
  if (isTRUE(res)) {
    cat(sprintf("  \033[32m✓\033[0m %s\n", name))
    return(invisible(TRUE))
  }
  ok_all <<- FALSE; fail_n <<- fail_n + 1L
  cat(sprintf("  \033[31m✗ %s\033[0m\n", name))
  if (inherits(res, "error")) {
    cat(sprintf("      \033[31m求值时出错：%s\033[0m\n",
                conditionMessage(res)))
  }
  if (!is.null(extra) && length(extra) && nzchar(paste(extra, collapse = ""))) {
    cat(sprintf("      \033[31m实际是：%s\033[0m\n",
                paste(utils::head(as.character(extra), 5), collapse = " | ")))
  }
  invisible(FALSE)
}

section <- function(t) cat(sprintf("\n\033[1m== %s ==\033[0m\n", t))

#' 从源码里抠出一个 observeEvent / renderUI 的整块
#'
#' ⚠️ 终止条件**必须**写成 `\n    \}(,|\))`，不能只写 `\n    \}\)`。
#'
#'    observeEvent 的收尾常常是 `}, ignoreNULL = TRUE)` —— 那个 `}` 后面跟的
#'    是逗号。只认 `})` 的话，正则一路吃到**下一个** observer 的结尾，把两段
#'    拼成一块。这不会报错，只会让断言永远为真：变异测试里把 env_pick 那个
#'    observer 里的 `state$exec_target <- "server"` 整行删掉，断言照样绿 ——
#'    因为抠出来的是隔壁 env_use 那个 observer（它也有同一行）。
#'
#'    所以这个函数在抠不到、或者抠出来的块里还有第二个同名调用时，返回 ""。
#'    调用方一律先 `chk("抠到了 …")` 再断言，否则下面每条都会静默通过。
#'
#' @param open 形如 `observeEvent\\(input\\$env_pick, \\{` 的开头（已转义）
#' @param once 块里必须**恰好出现一次**的标记（默认：只有一个 observeEvent）。
#'        出现两次就是两块拼的，一律当没抠到处理。
dsapp_pull <- function(src, open, once = "observeEvent\\(") {
  pat <- sprintf("(?s)%s.*?\\n    \\}(,|\\))", open)
  m <- regmatches(src, regexpr(pat, src, perl = TRUE))
  if (length(m) != 1 || !nzchar(m)) return("")
  if (length(gregexpr(once, m, perl = TRUE)[[1]]) != 1) return("")
  m
}

#' 同上，但收尾只认 `\n    }`，**不要求**后面跟着 `,` 或 `)`
#'
#' ⚠️ 为什么必须有这一个：dsapp_pull() 的收尾是 `\n    \}(,|\\))` —— 那是为
#'    `observeEvent(...)` / `renderUI({...})` 这类**当参数用**的块写的，它们
#'    收尾后面一定跟着 `)` 或 `,`。而 `hist_body <- function(...) { ... }` 是
#'    一条**普通赋值**语句，收尾的 `}` 后面什么都没有 —— 拿 dsapp_pull() 去抠
#'    它，返回的永远是空串，报出来是"（前置）抠到了…"那一条红。
#'    这个坑 2026-10-04 现踩了一次：断言名是"抠到了对话历史那个渲染函数"，
#'    看起来像"函数改名了"，其实只是收尾形状不同。
dsapp_pull_fn <- function(src, open, once = NULL) {
  pat <- sprintf("(?s)%s.*?\\n    \\}", open)
  m <- regmatches(src, regexpr(pat, src, perl = TRUE))
  if (length(m) != 1 || !nzchar(m)) return("")
  if (!is.null(once) &&
      length(gregexpr(once, m, perl = TRUE)[[1]]) != 1) return("")
  m
}

# ---- 当前进程有没有"绕过只读位"的特权（root / CAP_DAC_OVERRIDE）------------
#
# ⚠️ 这是**给 deploy.sh 用的**。deploy.sh 必须以 root 跑（要写 /srv/shiny-server），
#    而 root 会绕过一切只读位 —— 下面「只读保护」那组里有一条是「顺着软链覆盖
#    共享区文件**必须失败**」，它在 root 下必然失败。
#
#    2026-09-13 线上踩到：`sudo bash deploy.sh` 报「== 2 项失败 ==」，失败的正是
#    那一条和它后面的「原始内容没被改掉」。代码没问题 —— 是 root 本来就能改 0444。
#    而 deploy.sh 只 `tail -40`，那 40 行全是 ✓，真正的 ✗ 被截在屏幕外面。
#
#    处理方式不是删掉断言：应用**实际以 shiny 身份运行**，这条保护在真实运行环境
#    里依然成立、依然值得验。做法是探测到特权就**明说跳过**，探测不到就照旧严格
#    断言。跳过也要出声 —— 静默跳过和静默失败一样坏。
#
#    探测用"真的去写一个 0444 文件"，而不是看 uid/geteuid：判的是**能力**本身，
#    换容器、换 capabilities、换 sudo 配置都不会误判。
RO_PROBE <- local({
  p <- tempfile("dsapp_roprobe_")
  on.exit(unlink(p), add = TRUE)
  # 先确认普通文件写得动 —— 否则后面那次"写成功"什么都说明不了
  if (!isTRUE(tryCatch({ writeLines("x", p); TRUE }, error = function(e) FALSE))) {
    return(list(ok = FALSE, bypass = FALSE))
  }
  Sys.chmod(p, "0444")
  wrote <- tryCatch({ writeLines("y", p); TRUE },
                    error = function(e) FALSE, warning = function(w) FALSE)
  list(ok = TRUE, bypass = isTRUE(wrote))
})

# ---------------------------------------------------------------------------
section("源文件解析")
for (f in c(list.files("R", full.names = TRUE, pattern = "\\.R$"), "app.R")) {
  r <- tryCatch({ parse(f); TRUE }, error = function(e) conditionMessage(e))
  chk(basename(f), isTRUE(r))
  if (!isTRUE(r)) cat("      ", r, "\n")
}
if (!ok_all) { cat("\n解析都过不了，后面的检查没意义。\n"); quit(status = 1) }

# 应用代码本身要能用（子进程/后台任务都是这么 source 的）
tmp <- tempfile("dsapp_selftest_"); dir.create(tmp, recursive = TRUE)
Sys.setenv(DSAPP_DATA_ROOT = tmp)
for (f in list.files("R", full.names = TRUE)) {
  if (grepl("^mod_", basename(f))) next
  source(f, local = globalenv())
}
# ⚠️ mod_* 默认**不** source（模块的 server 里可能有在建会话时才该跑的东西），
#    但 dsapp_main_ui() 会调用各个模块的 *_ui()，所以渲染那几条断言依赖它们。
#    少 source 一个的表现是 "could not find function mod_xxx_ui" —— 写 V6 的
#    渲染断言时当场踩到（mod_model.R 是新加的，忘了加进来）。
#
#    顺序按 app.R 的 source 顺序（那里有一段注释解释为什么 mod_model 在
#    mod_settings 前面）。少一个的表现都是 `could not find function mod_xxx_ui`。
mod_ordered <- c("R/mod_chat.R", "R/mod_tasks.R", "R/mod_files.R", "R/mod_envs.R",
            "R/mod_model.R", "R/mod_settings.R", "R/mod_admin.R",
            "R/mod_welcome.R", "R/mod_skills.R",
            # V13.8 item 2。dsapp_main_ui() 在**平台管理员**那一支里会调
            # mod_htadmin_ui()，所以渲染断言依赖它 —— 少 source 一个的表现
            # 就是 "could not find function mod_htadmin_ui"。
            "R/mod_htadmin.R")
for (f in mod_ordered) {
  source(f, local = globalenv())
}

# ★ V13.11 item 5：上面那份是**顺序**清单，不是**完整**清单 —— 它只是保证
#   模块之间谁先谁后，而"新加一个模块要记得加进这里"这件事靠人是靠不住的。
#
#   加 R/mod_lit.R 的时候就漏了，症状值得记下来：报错的是 V6 那六条**渲染**
#   断言（"could not find function mod_lit_ui"），而那六条讲的是左侧栏外壳，
#   跟"文献速递"看起来毫无关系 —— 顺着报错往回找，很难联想到是这里漏了一行。
#   app.R 那份列表也有同样的毛病，所以那边专门有一条"覆盖 R/ 下每一个文件"
#   的断言盯着；这里从根上解决：**顺序照上面走，剩下的 mod_* 全部补上**。
#
#   ⚠️ 为什么敢无脑 source 所有 mod_*：source() 只是**定义**函数，模块的
#      server 体要等 app.R 真的调 moduleServer() 才跑。上面那 10 个本来就
#      是这么 source 的，多一个 mod_lit.R 不会多出任何副作用。
for (f in setdiff(list.files("R", pattern = "^mod_", full.names = TRUE),
                  mod_ordered)) {
  source(f, local = globalenv())
}
cfg <- dsapp_config(); dsapp_init_dirs(cfg)

# ★ V13 item 6：管理区不再是"一个共用目录"，而是每个账号一个（data/files/u<N>/）。
#   下面几百条文件相关的用例讲的都是"某个登录用户在自己的管理区里操作"，
#   所以把自检用的 cfg 钉到 1 号账号的区上 —— 这也正是线上跑起来时每一处
#   拿到的 cfg 该有的样子。
#
# ⚠️ 钉的是**自检自己**用的 cfg。被测代码内部一律是 `dsapp_config()` 现取，
#    拿到的是全局那个（files_dir 指向空的 _anon）—— 这正是要考的默认值，
#    别顺手把它也改了，否则"漏传账号会怎样"就再也测不出来了。
cfg <- dsapp_config_user(1L, cfg)
invisible(dsapp_files_ensure(1L, cfg))

# ---------------------------------------------------------------------------
# 造账号的两个帮手（V13.1 item 7 之后必须走它们）
# ---------------------------------------------------------------------------
# ⚠️ V13.1 item 7 把免密登录整条取消之后，`dsapp_user_create()` **必须**给密码，
#    不给就返回 ok = FALSE、**一行都不建**。
#
#    自检里绝大多数建账号只是为了拿到一个 user_id（归属、隔离、配额、团队），
#    根本不关心能不能登录。这些用例统一走 mkuser() —— 密码是同一个常量，
#    要改只改一处。**要测密码行为的用例自己直接调 dsapp_user_create**，
#    别用这个包装（包装会把"密码"这个变量藏起来，正是那几段要测的东西）。
#
#    这个坑的形状值得记一下：漏改的下场不是"这条红了"，而是**静默地什么都不建**
#    —— r1$user 是 NULL，后面几十条断言全在 NULL 上跑，有的碰巧还是绿的
#    （2026-09-16 就是这么红的：`注册成功` 报红，往下几十条报的是"甲看不到
#    自己的对话"这种离现场很远的话）。**改这类"突然必填"的规则时，要按调用点
#    全量扫一遍，不能只改报警的那一处。**
SELFTEST_PW <- "Pw-selftest-1"
mkuser <- function(nickname, email, phone, field, con) {
  dsapp_user_create(nickname, email, phone, field,
                    password = SELFTEST_PW, con = con)
}

#' 造一个「老库里躺着的无密码账号」（V13.1 之前注册的那种）
#'
#' ⚠️ 这种账号现在**建不出来**（正是 item 7 要的效果），所以只能直接 INSERT。
#'    拿 dsapp_user_create(..., "") 去造的话会得到 ok = FALSE 且什么都不建 ——
#'    于是"断言它登不进来"这条**永远绿**，测的却是 NULL 而不是那个账号。
mk_legacy_nopw <- function(email, con, nickname = "老账号") {
  invisible(DBI::dbExecute(con, paste(
    "INSERT INTO users (nickname, email, phone, field, pass_salt, pass_hash,",
    "token, status, is_admin, created_at) VALUES",
    "(?, ?, '13800000000', '（升级上来的老账号）', '', '', ?, 'active', 0, ?)"),
    params = list(nickname, email, dsapp_token(24), dsapp_now())))
  invisible(as.integer(dsapp_user_by_email(email, con)$id))
}

# ---------------------------------------------------------------------------
section("模型目录")

# 这条是 V3 的核心教训：V2 写死的两个模型名已经全部下线。
# 如果哪天有人把 deepseek-chat 加回 fallback，这里要拦住。
ds_fb <- dsapp_vendor_models("deepseek")
chk("deepseek 的 fallback 不含已下线的 deepseek-chat",
    !"deepseek-chat" %in% ds_fb)
chk("deepseek 的 fallback 不含已下线的 deepseek-reasoner",
    !"deepseek-reasoner" %in% ds_fb)
chk("deepseek 默认模型存在且非空", length(ds_fb) >= 1 && nzchar(ds_fb[[1]]))

# 每个进下拉框的厂商都必须有 label 和 base_url（自定义除外），
# 否则用户选中后请求会打到一个空地址上。
for (v in names(DSAPP_MODEL_CATALOG)) {
  e <- DSAPP_MODEL_CATALOG[[v]]
  chk(sprintf("%s：有 label", v), nzchar(e$label %||% ""))
  if (isTRUE(e$enabled %||% TRUE) && !identical(v, "custom")) {
    chk(sprintf("%s：有 base_url", v), nzchar(e$base_url %||% ""))
    chk(sprintf("%s：有申请 Key 的官网地址", v), nzchar(e$key_url %||% ""))
  }
}

chk("停服的厂商不进下拉框", !("yi" %in% dsapp_vendor_choices()))
chk("下拉框至少 5 家厂商", length(dsapp_vendor_choices()) >= 5)

# 迁移：旧名字必须能换成能用的新名字
mg <- dsapp_model_migrate("deepseek", "deepseek-chat")
chk("deepseek-chat 会被迁移", isTRUE(mg$changed) && nzchar(mg$model))
chk("迁移目标不是它自己", !identical(mg$model, "deepseek-chat"))
mg2 <- dsapp_model_migrate("deepseek", "deepseek-flash")
chk("正常模型名不会被乱改", !isTRUE(mg2$changed))
mg3 <- dsapp_model_migrate("deepseek", "")
chk("空模型名会兜底出一个可用值", nzchar(mg3$model))

# 温度是否生效：思考模式下应为 FALSE（官方文档明写 temperature 不生效）
chk("思考模式下温度不生效", !dsapp_temperature_active("deepseek", TRUE))
chk("非思考模式下温度生效", dsapp_temperature_active("deepseek", FALSE))
chk("不支持思考模式的厂商温度照常生效", dsapp_temperature_active("qwen", TRUE))

# ---------------------------------------------------------------------------
section("提示词分流")

# 关键性质：选定 conda 环境 / 远程 / 本地时，提示词**不能**再宣称
# "这台服务器上装了 Seurat" —— 否则模型会照着写，用户一执行就报错。
p_sys <- build_system_prompt("chat", cfg, target = list(kind = "server", env = "system"))
p_env <- build_system_prompt("chat", cfg, target = list(kind = "server", env = "zzz_env"))
p_rem <- build_system_prompt("chat", cfg,
  target = list(kind = "remote", remote = list(host = "1.2.3.4", port = 22, user = "u")))
p_loc <- build_system_prompt("chat", cfg, target = list(kind = "local"))

chk("系统环境：给出真实包清单", grepl("已安装的生信相关包", p_sys))
chk("conda 环境：点名了那个环境", grepl("zzz_env", p_env))
chk("conda 环境：不再宣称包已装好", !grepl("已安装的生信相关包", p_env))
chk("conda 环境：要求防御式写法", grepl("未安装", p_env))
chk("远程：写明是用户自己的机器", grepl("1.2.3.4", p_rem))
chk("远程：不宣称已装包", !grepl("已安装的生信相关包", p_rem))
chk("本地：说明不在服务器执行", grepl("不会在服务器上执行", p_loc))
chk("本地：要求相对路径", grepl("相对路径", p_loc))
chk("默认（不传 target）等同系统环境", identical(
  build_system_prompt("chat", cfg), build_system_prompt("chat", cfg,
    target = list(kind = "server", env = "system"))))

# ⚠️ 拼系统提示词是**每次发送消息**都要跑的，而且跑在 Shiny 主进程里。
# 探测已装包时如果用 requireNamespace()，那就是在**加载命名空间**：
# Seurat / Signac / ArchR / monocle3 / Giotto / DADA2 … 46 个重型包，
# 实测 18.3 秒、常驻内存 941 MB，R 一旦加载还不卸载。而本站是 Shiny
# Server 开源版 —— 一个应用一个 R 进程、所有访客共用，于是每个人每次
# 点发送，所有人一起卡 18 秒。这就是用户说的"响应速度很慢"。
# 换成 system.file() 只查安装目录，0.013 秒，结果完全一样。
# 下面两条盯死这个回归：它改回去不会报错，只会让整个应用慢 500 倍。
pkgs_before <- loadedNamespaces()
t0 <- Sys.time()
p_probe <- build_environment_section(cfg, list(kind = "server", env = "system"))
probe_secs <- as.numeric(Sys.time() - t0, units = "secs")
chk("拼提示词不加载任何包命名空间",
    length(setdiff(loadedNamespaces(), pkgs_before)) == 0)
chk(sprintf("拼提示词耗时 %.3f 秒（应远小于 1 秒）", probe_secs),
    probe_secs < 1)
chk("探测到的包清单非空（别为了快把结果弄丢了）",
    grepl("`", p_probe, fixed = TRUE))

# ---------------------------------------------------------------------------
section("agent 场景提示词（阶段 2.6）")

# 这一节盯的是一件事：agent 模式和手动模式**必须互相排斥**。
# DSPROMPT_EXECUTION 里写着「你生成的代码不会自动执行」「不要声称我已经
# 执行了」，这在自动循环里是反的 —— 模型会每轮都停下来等一个永远不会来的
# "用户确认"。所以 agent 场景是**换掉**它，不是往后追加。追加的写法不会
# 报错，只会在跑起来之后表现得莫名其妙，所以用测试钉死。
p_ag <- build_system_prompt("agent", cfg, target = list(kind = "server", env = "system"))
chk("agent：说明代码会被自动执行", grepl("自动执行模式已开启", p_ag, fixed = TRUE))
chk("agent：**没有**「代码不会自动执行」这种反话",
    !grepl("代码不会自动执行", p_ag, fixed = TRUE))
chk("agent：**没有**「不要声称我已经执行了」", !grepl("不要声称", p_ag, fixed = TRUE))
chk("agent：**没有**手动模式的「一次只给一个可执行单元」措辞",
    !grepl("一次只给一个可执行单元", p_ag, fixed = TRUE))
chk("agent：说明结果会以【执行结果 · 任务 #N】回传",
    grepl("执行结果 · 任务 #N", p_ag, fixed = TRUE))
chk("agent：一轮只跑第一个块，其余会被跳过",
    grepl("只执行**第一个**可执行块", p_ag, fixed = TRUE))
chk("agent：示意代码要标 text（否则会被当成可执行块抢走这一轮）",
    grepl("```text", p_ag, fixed = TRUE))
chk("agent：每轮换新文件名（重名会读到上一轮旧数据）",
    grepl("每一轮都要换", p_ag, fixed = TRUE))
chk("agent：报错先读 stderr 再改，不要盲目重试",
    grepl("先读 stderr", p_ag, fixed = TRUE))
chk("agent：变量不跨轮存活（跨轮只能靠落盘）",
    grepl("变量不跨轮存活", p_ag, fixed = TRUE))
chk("agent：说清了轮次上限，模型不会无限试探",
    grepl("最多 6 轮", p_ag, fixed = TRUE))
chk("agent：该停就停的情形都写了",
    grepl("该停就停", p_ag, fixed = TRUE) &&
      grepl("连续两次修不好", p_ag, fixed = TRUE))
# V11 item 8：「只有思路选择等场景需要用户做对应的反馈」—— 这条把"只有"钉死。
# 原来的清单里有一条「依赖缺失且需要用户去装」，正好是要去掉的那种转手。
chk("★ agent：点名了「只有需要用户做决定这一类才该停下来问」",
    grepl("只有这一类才该停下来问用户", p_ag, fixed = TRUE))
# 规则编号不能重号 —— 拆成 HEAD/TAIL 两半拼接时最容易出这个错
# （第一版就是 1,2,3,4 接 4,5,6,7,8）。
ag_rules <- grep("^### 规则", strsplit(p_ag, "\n")[[1]], value = TRUE)
ag_nums <- as.integer(sub("^### 规则 ([0-9]+).*", "\\1", ag_rules))
chk("agent：规则编号连续不重号",
    identical(ag_nums, seq_along(ag_nums)))
# 手动模式下这些必须原样保留（别为了 agent 把老路子改坏了）
p_ch <- build_system_prompt("chat", cfg, target = list(kind = "server", env = "system"))
chk("chat：手动模式的措辞没被改坏",
    grepl("代码不会自动执行", p_ch, fixed = TRUE) &&
      !grepl("自动执行模式已开启", p_ch, fixed = TRUE))
ch_rules <- grep("^### 规则", strsplit(p_ch, "\n")[[1]], value = TRUE)
chk("chat：规则编号同样连续不重号",
    identical(as.integer(sub("^### 规则 ([0-9]+).*", "\\1", ch_rules)),
              seq_along(ch_rules)))
chk("两种场景共用同一份规则 4-8（拆分后没走样）",
    grepl("用进度标记让用户看到进展", p_ag, fixed = TRUE) &&
      grepl("用进度标记让用户看到进展", p_ch, fixed = TRUE))

# ---------------------------------------------------------------------------
section("环境类失败的判定（V11 item 8）")

# 用户的原话：「因为环境配置等原因导致任务失败应该让 AI 自动调试，只有思路
# 选择等场景需要用户做对应的反馈」。
#
# ⚠️ 这一节必须同时盯**两头**，只盯一头等于没盯：
#   判据那头 —— 分类器认得准不准；
#   出口那头 —— dsapp_agent_tool_text() 有没有把那段话**真的拼进回喂里**。
#    分类器写得再准，出口没接上，模型看到的东西和改之前一模一样，而这一点
#    从界面上完全看不出来（tool 气泡里多一段少一段，没人会去逐字比对）。

e_pkg <- dsapp_env_failure(
  stderr = "Error in library(Seurat) : there is no package called 'Seurat'")
chk("★ 认出「缺少 R 包」",
    isTRUE(e_pkg$is_env) && identical(e_pkg$kind, "missing_pkg"))
chk("★ 包名进了标签（不是一句笼统的「环境有问题」）",
    grepl("Seurat", e_pkg$label, fixed = TRUE))
chk("缺包算可自修（retryable）", isTRUE(e_pkg$retryable))

e_py <- dsapp_env_failure(stderr = "ModuleNotFoundError: No module named 'scanpy'")
chk("★ 认出「缺少 Python 包」", isTRUE(e_py$is_env) &&
      grepl("scanpy", e_py$label, fixed = TRUE))

e_env <- dsapp_env_failure(
  msg = "conda 环境 r452 不存在（可能已被删除）。到「环境」页重新选择。")
chk("★ 认出「环境被删了」",
    isTRUE(e_env$is_env) && identical(e_env$kind, "missing_env"))
chk("★ 环境被删**不算**可自修（改运行环境是用户的事，别让模型空转）",
    !isTRUE(e_env$retryable))

chk("认出磁盘满", identical(
  dsapp_env_failure(stderr = "write error: No space left on device")$kind, "disk"))
chk("认出装包时的网络失败", identical(
  dsapp_env_failure(stderr = "Could not resolve host: cran.r-project.org")$kind,
  "network"))
chk("认出 conda 解依赖失败", isTRUE(dsapp_env_failure(
  stderr = "PackagesNotFoundError: The following packages are not available")$is_env))

# ⚠️ 反向：业务错误**不能**被算成环境问题。误判的代价是自动重跑一段本来
#    就跑不通的代码 —— 而它盖住的恰恰是用户要看的那个结论（"你的数据里
#    没有这一列"）。所以下面这两条和上面几条一样重要。
e_biz <- dsapp_env_failure(
  stderr = "Error in df$TP53 : object of type 'closure' is not subsettable")
chk("★★ 业务错误**不**算环境问题", !isTRUE(e_biz$is_env))
chk("★ 少写一个变量名也不算环境问题", !isTRUE(dsapp_env_failure(
  stderr = "Error: 找不到对象 'expr_matrix'")$is_env))
chk("成功且没有输出 = 不是环境问题",
    !isTRUE(dsapp_env_failure(stderr = "", status = "success")$is_env))
chk("★ 平台侧 error 且一个字报错都没有 = 算环境问题（总得有人背这个锅）",
    isTRUE(dsapp_env_failure(stderr = "", status = "error")$is_env))

# ---- 出口：回喂给模型的那条消息里，这段话真的在 --------------------------
t_env <- dsapp_agent_tool_text(
  task_id = 7L, status = "failed", lang = "R", exit_code = 1L,
  stderr = "Error in library(Seurat) : there is no package called 'Seurat'",
  stdout = "step 1 ok")
chk("★★ 环境类失败的回喂里带着「平台判定」那一段",
    grepl("平台判定", t_env, fixed = TRUE) && grepl("Seurat", t_env, fixed = TRUE))
chk("★★ 并且点名了**不要**把这件事转手给用户",
    grepl("不是用户该处理的事", t_env, fixed = TRUE) &&
      grepl("不要**只是把这段报错转述给用户", t_env, fixed = TRUE))
chk("★ 可自修的那套给出「先自己装」的具体动作",
    grepl("install.packages", t_env, fixed = TRUE))
chk("★ 那段排在 stdout 前面（模型从上往下读，别让它先读结果再读判定）",
    regexpr("平台判定", t_env, fixed = TRUE) <
      regexpr("step 1 ok", t_env, fixed = TRUE))

t_fix <- dsapp_agent_tool_text(task_id = 8L, status = "error", lang = "R",
                               stderr = "", stdout = "")
chk("★ 改不了的环境问题给的是另一套话（说清要用户做什么、能绕就绕）",
    grepl("平台判定", t_fix, fixed = TRUE) &&
      grepl("你改不了", t_fix, fixed = TRUE) &&
      !grepl("install.packages", t_fix, fixed = TRUE))

t_ok <- dsapp_agent_tool_text(task_id = 9L, status = "success", lang = "R",
                              exit_code = 0L, stdout = "done")
chk("★★ 成功的回喂里**没有**那段（不是无脑追加）",
    !grepl("平台判定", t_ok, fixed = TRUE))

# ⚠️⚠️ V13.10 item 4 改掉了这条的期待，**不是把断言放松了**。
#
#    原文是「业务错误的回喂里也**没有**那段」—— 它成立的前提是"只有环境
#    问题才配那一段"。V13.10 起多了一类：**AI 自己上一轮写的代码有问题**
#    （语法错、变量名写错、类型不对）。用户的原话是「语法错误不要交由用户
#    解决，请自行处理，甚至不用记录和提示信息」，所以这一类**必须**带一段
#    回喂 —— 不带的话，模型的默认反应就是把报错贴给用户、等他决定。
#
#    而 `object of type 'closure' is not subsettable` 正是这一类：它是把
#    一个函数当数据框取了子集，纯粹是代码写错。
#
#    所以现在钉两件事，一件都不许少：
#      1. 那段话**不许**用「环境问题」的口径 —— 环境根本没坏，模型会跑去
#         装包、换镜像，而真正该做的是改那一行；
#      2. 那段话**必须**点明"你自己改、别转述给用户"。
t_biz <- dsapp_agent_tool_text(
  task_id = 10L, status = "failed", lang = "R", exit_code = 1L,
  stderr = "Error in df$x : object of type 'closure' is not subsettable")
chk("★★★ 业务错误的回喂里不说「环境问题」（环境没坏，别让模型去装包）",
    grepl("平台判定", t_biz, fixed = TRUE) &&
      !grepl("这是**环境问题**", t_biz, fixed = TRUE))
chk("★★★ 但它必须点名「这是你自己代码的问题、别转述给用户」",
    grepl("上一轮代码自己的问题", t_biz, fixed = TRUE) &&
      grepl("不要**把原始报错贴给用户", t_biz, fixed = TRUE))

# 认不出来的失败照样**一句都不加**：加一段泛泛的话只会让模型以为
# "平台看过了、它也没辙"，反而更容易把锅转手。
t_unk <- dsapp_agent_tool_text(
  task_id = 11L, status = "failed", lang = "R", exit_code = 1L,
  stderr = "Error in my_own_thing() : 这一句谁也认不出来")
chk("★★ 认不出来的失败，回喂里一个字都不加（不是无脑追加）",
    !grepl("平台判定", t_unk, fixed = TRUE))

chk("★ 提示词里不再有「依赖缺失且需要用户去装」这种转手说法",
    !grepl("依赖缺失且需要用户去装", p_ag, fixed = TRUE))
chk("★ 提示词点名「环境类问题不算停下来的理由」",
    grepl("环境类问题", p_ag, fixed = TRUE) &&
      grepl("不要**把它转手给用户", p_ag, fixed = TRUE))
# ⚠️ 这一段不在 p_ag 里：包目录那节要**有对话**才拼得出来（build_lib_section
#    拿到 NULL 的 session_id 直接返回空串），而上面的 p_ag 是不带会话拼的。
#    所以这里显式拿一个假 session_id 再拼一遍 —— 断言落在**渲染出来的
#    提示词**上，而不是去 grep 源码里的字面量：后者在"函数没被调用"时
#    照样绿。
p_lib <- build_lib_section("s-selftest-item8", cfg)
chk("（前置）包目录那节拼得出来", nzchar(p_lib))
chk("★ 装包规则改成「换一个办法再试」，不是第一次失败就转手",
    grepl("换一个办法再试", p_lib, fixed = TRUE) &&
      !grepl("同一个包装不上就不要再试第二次。把报错原文贴给用户", p_lib,
             fixed = TRUE))
chk("★ 包目录那节说明了「环境问题是你处理的那一类」",
    grepl("环境问题本来就是你要处理的那一类", p_lib, fixed = TRUE))

# ---- 任务挂了之后，循环要不要自动接手（V13.5 item 1 重写）----------------
#
# 用户的原话：「报错需要AI自己解决，而不是用户自己确认」。
#
# ⚠️★ 这一段在 V13.5 被**反过来**了，读的时候别照着 V11 的印象看：
#    V11 立的规矩是"只有环境类失败、而且用户打开了自动执行，才接手"，
#    结果是这条功能在默认配置下**从来没触发过**（自动执行默认关）。现在
#    是"任何失败都接手，除非用户把「出错自动修」关掉"。
#
# 这里只验**闸门**（默认值、忙闲、频率），不真的起一轮生成 —— 那要联网、
# 要花 token，而"会不会自动接手"是纯逻辑，离线就能钉死。
ag_mk <- function() {
  hit <- new.env(); hit$n <- 0L; hit$msg <- character(0)
  # ★ V15.5 item 3：把写进对话的 tool 消息也记下来。循环的收尾行为（轮次用满
  #   之后到底有没有再喂一轮、有没有执行那个块）只能从这个记录里看出来 ——
  #   a$state 只能告诉你"结束了"，看不出"为什么结束"。
  hit$add <- character(0)
  hooks <- list(
    get_sid    = function() "s-selftest",
    get_target = function() list(kind = "server", env = "system"),
    begin_llm  = function(scene) { hit$n <- hit$n + 1L },
    running    = function() FALSE,
    add_msg    = function(role, txt) { hit$add <- c(hit$add, as.character(txt)); invisible(NULL) },
    refresh    = function() invisible(NULL))
  st <- new.env(); st$user_id <- 1L
  list(a = dsapp_agent_new(st, NULL, NULL, function(x) x, cfg, hooks,
                           max_iter = 3L),
       hit  = hit,
       # 界面上那条"AI 接手了"的通知。kick_env_fix 只**调用**它，不自己
       # 决定怎么显示 —— 模块那边传进来的是 showNotification。
       notify = function(msg, type = "message") hit$msg <- c(hit$msg, msg),
       msgs   = function() hit$msg)
}
ag_x <- ag_mk(); ag <- ag_x$a; ag_hooks <- ag_x$hit
chk("agent 有 kick_env_fix 方法", is.function(ag$kick_env_fix))

# ⚠️ 默认值本身就是要验的东西。"犯错自动修"默认开着是这一版的**需求**
#    （用户原话），它哪天被谁改回 FALSE，这一条会立刻红。
chk("★★ 「出错自动修」默认就是开着的（用户要的是不用自己确认）",
    isTRUE(ag$autofix))
chk("★★ 默认配置下（自动执行关着）环境类失败就把模型叫起来",
    isTRUE(ag$kick_env_fix(e_pkg, 1L, notify = ag_x$notify)) && ag_hooks$n == 1L)
chk("叫起来之后状态是 generating（剩下的交给心跳）",
    identical(ag$state, "generating"))
chk("轮次从头算（新开的一段，不占上一段的额度）", identical(ag$iter, 0L))

# ★★ 这是这一版**最关键**的一条：自动接手要把循环"武装"起来，否则模型
#    查完了也没有人照它说的去做 —— on_llm_done 和 mod_chat 流式结束那一段
#    问的都是 can_loop()，它为假的话那一轮回复就只是一条聊天消息。
chk("★★★ 自动接手会把循环武装起来（enabled 关着也能跑完一整圈）",
    isTRUE(ag$armed) && isTRUE(ag$can_loop()))
chk("★ 自动执行关着的时候，没被武装的循环不该动",
    !isTRUE(ag_mk()$a$can_loop()))

chk("★ 已经在跑的时候不插一脚（会打乱 iter 计数）",
    !isTRUE(ag$kick_env_fix(e_pkg, 1L, notify = ag_x$notify)) && ag_hooks$n == 1L)

# ---- 业务失败也接手（V11 时是"不接手"，V13.5 反过来）----------------------
ag$finish("测试收尾")
ag_x2 <- ag_mk(); ag2 <- ag_x2$a
chk("★★ 业务失败（列名写错这类）同样触发自动接手",
    isTRUE(ag2$kick_env_fix(e_biz, 1L, notify = ag_x2$notify)) && ag_x2$hit$n == 1L)
# ⚠️ V13.10 item 4：这里的期待也改了。`e_biz` 现在落在 self_fix 那一类，
#    note 从「任务 #N 失败了，AI 正在自己看这个报错」换成了更短的那句
#    「任务 #N 没跑通，AI 正在自动重试」—— 用户明确说了这一类"不用记录和
#    提示信息"，状态条只留一行小字（全静默会被当成"点了没反应"）。
#    不变的是**不许说「环境问题」**：环境没坏，说成环境问题会让用户跑去
#    环境页乱点（那正是这一类最不该被乱动的东西）。
chk("★ 但标签不许说成「环境问题」（环境没坏，别骗用户也别骗模型）",
    grepl("没跑通", ag2$note) && !grepl("环境问题", ag2$note))

# ---- 关得掉 ---------------------------------------------------------------
ag_x3 <- ag_mk(); ag3 <- ag_x3$a
ag3$autofix <- FALSE
chk("★★ 把「出错自动修」关掉之后，任何失败都不再接手",
    !isTRUE(ag3$kick_env_fix(e_pkg, 1L)) &&
      !isTRUE(ag3$kick_env_fix(e_biz, 1L)) && ag_x3$hit$n == 0L)
chk("★ 关掉之后状态还是 idle（没留下一段半死不活的循环）",
    identical(ag3$state, "idle") && !isTRUE(ag3$can_loop()))

# ---- 「自动执行」和「出错自动修」是两件事，不能互相带动 -------------------
ag_x4 <- ag_mk(); ag4 <- ag_x4$a
ag4$enabled <- TRUE      # 自动执行开着
ag4$autofix <- FALSE     # 出错自动修关着
chk("★★ 自动执行开着 ≠ 出错之后会接手（两个开关各管各的）",
    !isTRUE(ag4$kick_env_fix(e_pkg, 1L)) && ag_x4$hit$n == 0L)
chk("★ 自动执行开着时循环本来就是通的（can_loop 为真）",
    isTRUE(ag4$can_loop()))

# ---- ★★ V16.2 item 1：**默认**是不设上限 ----------------------------------
#
# 用户原话：「出错自动修也要默认没上限」。这条闸现在只在**用户自己设了
# 次数**的时候才拦，默认（哨兵 0）不拦。
#
# ⚠️ 这一段和下面那一段是**成对**的，缺一条就会有半边没人钉：
#    这一条钉"默认不拦"，下面那条钉"设了次数就拦住"。
#    只留下面那条的话，有人把默认值改回 3L 也照样全绿。
ag_x0 <- ag_mk(); ag0 <- ag_x0$a
chk("★★ 新会话的「出错自动修」上限默认就是不设上限（哨兵 0）",
    identical(as.integer(ag0$fix_max), as.integer(DSAPP_AGENT_AUTOFIX_UNLIM)) &&
      isTRUE(dsapp_autofix_is_unlimited(ag0$fix_max)))
# 连着来 3 倍于老上限的次数，一次都不许被拦。
n0 <- 0L
for (i in seq_len(DSAPP_AGENT_AUTOFIX_MAX * 3L)) {
  if (isTRUE(ag0$kick_env_fix(e_pkg, i, notify = ag_x0$notify))) n0 <- n0 + 1L
  ag0$finish("测试：跑完一轮就收尾，模拟下一轮失败")
}
chk(sprintf("★★★ 不设上限时，连着来 %d 次也一次都不拦（老上限是 %d）",
            DSAPP_AGENT_AUTOFIX_MAX * 3L, DSAPP_AGENT_AUTOFIX_MAX),
    n0 == DSAPP_AGENT_AUTOFIX_MAX * 3L)
chk("★ 而且不设上限时**一句「先停一下」都不许说**（说了就是在骗用户）",
    !any(grepl("先停一下", ag_x0$msgs())))
# ⚠️ 时刻表照记 —— 状态条和审计日志里"已经自动排查过几次"读的就是它。
#    不设上限只影响"拦不拦"，不影响"记不记"。
chk("★ 不设上限也要记时刻表（状态条/审计日志要报「已经排查过几次」）",
    length(ag0$fix_times) == DSAPP_AGENT_AUTOFIX_MAX * 3L)

# ---- 频率闸：滑动窗口，挡的是"改不好→再跑→再挂→再改" --------------------
#
# ⚠️ V16.2 item 1：这一段现在**必须先手动设一个次数**，因为默认已经不设
#    上限了（见上面那段）。设完之后它验的是"用户设了上限时，闸有效"。
ag_x5 <- ag_mk(); ag5 <- ag_x5$a
ag5$fix_max <- as.integer(DSAPP_AGENT_AUTOFIX_MAX)
n_ok <- 0L
for (i in seq_len(DSAPP_AGENT_AUTOFIX_MAX)) {
  if (isTRUE(ag5$kick_env_fix(e_pkg, i, notify = ag_x5$notify))) n_ok <- n_ok + 1L
  ag5$finish("测试：跑完一轮就收尾，模拟下一轮失败")
}
chk(sprintf("★ 设了次数之后，窗口内最多自动接手 %d 次", DSAPP_AGENT_AUTOFIX_MAX),
    n_ok == DSAPP_AGENT_AUTOFIX_MAX)
chk("★★ 超过之后不再接手（否则会无上限地烧 token 和机器时间）",
    !isTRUE(ag5$kick_env_fix(e_pkg, 99L, notify = ag_x5$notify)) &&
      ag_x5$hit$n == DSAPP_AGENT_AUTOFIX_MAX)
chk("★ 撞上频率闸时要**出个声**（静默拒绝 = 点了没反应，这个项目查过好几次）",
    length(ag_x5$msgs()) > 0)
# ★ V16.2 item 1：那句话里报的次数必须是**用户设的那个数**。
#   照抄常量报的话，用户设 10 次、界面上会说"已经排查过 3 次"——
#   而这句话的全部作用就是告诉他"为什么停了"。
chk(sprintf("★★ 「先停一下」那句里报的是**用户设的** %d 次，不是写死的常量",
            DSAPP_AGENT_AUTOFIX_MAX),
    any(grepl(sprintf("已经自动排查过 %d 次", DSAPP_AGENT_AUTOFIX_MAX),
              ag_x5$msgs(), fixed = TRUE)))
# 窗口滑过去之后又能接手了 —— 这条同时钉住"它是滑动窗口，不是永久拉黑"。
# 直接改时刻表而不等半小时：等的话自检要跑半小时。
ag5$fix_times <- ag5$fix_times - (DSAPP_AGENT_AUTOFIX_WINDOW + 60)
chk("★★ 窗口滑过去之后恢复正常（不是一旦撞上就永久失效）",
    isTRUE(ag5$kick_env_fix(e_pkg, 100L, notify = ag_x5$notify)))

# ---- 换一个次数，闸跟着走（上限住在 agent 对象上，不是常量）-------------
ag_x6 <- ag_mk(); ag6 <- ag_x6$a
ag6$fix_max <- 1L
chk("★ 把次数改成 1：第一次照样放行",
    isTRUE(ag6$kick_env_fix(e_pkg, 1L, notify = ag_x6$notify)))
ag6$finish("收尾")
chk("★★ 设成 1 之后第二次就被拦下了（上限住在 agent 对象上，不是写死的常量）",
    !isTRUE(ag6$kick_env_fix(e_pkg, 2L, notify = ag_x6$notify)))

