section("流式增量读取")

# ⚠️ 这条是 V2 带过来的真 bug：句柄曾经是 list，而 R 的 list 是值语义，
# `handle$read_pos <- size` 只改到函数内的副本 —— 于是每次轮询都从文件头
# 重读，界面上正文被反复叠加。句柄必须是 environment。
h <- dsapp_llm_start("sk-dummy", list(list(role = "user", content = "hi")),
                     model = "deepseek-flash", cfg = cfg)
chk("句柄是 environment（引用语义）", is.environment(h))
chk("句柄带 reason_file（思维链分流）", !is.null(h$reason_file))
dsapp_llm_abort(h)   # 立刻收掉，别真发请求

live <- callr::r_bg(function() Sys.sleep(60), supervise = TRUE)
mk <- function(tag) {
  o <- file.path(tmp, paste0(tag, ".out")); rr <- file.path(tmp, paste0(tag, ".reason"))
  file.create(o); file.create(rr)
  list2env(list(proc = live, out_file = o, status_file = file.path(tmp, paste0(tag, ".json")),
                reason_file = rr, read_pos = 0L, reason_pos = 0L), parent = emptyenv())
}
hh <- mk("t1")
cat("想一下", file = hh$reason_file, append = TRUE)
r1 <- dsapp_llm_poll(hh)
chk("思维链单独返回", r1$reasoning == "想一下" && r1$text == "")
cat("答案", file = hh$out_file, append = TRUE)
r2 <- dsapp_llm_poll(hh)
chk("正文只给增量", r2$text == "答案")
r3 <- dsapp_llm_poll(hh)
chk("不重复读旧内容", r3$text == "" && r3$reasoning == "")
writeLines('{"status":"done","error":null}', hh$status_file)
chk("读到 status 即结束", isTRUE(dsapp_llm_poll(hh)$done))
live$kill()

