up_src <- file.path(tmp, "up_src"); writeLines("gene,expr", up_src)
for (nm in c("expr.csv", "expr.csv", "../../../../tmp/dsapp_evil.csv",
             "/etc/passwd", "..\\..\\evil.txt", "....", "数据 (v2).h5ad")) {
  dsapp_file_save(list(name = nm, datapath = up_src), cfg)
}
landed <- list.files(cfg$files_dir)
