section("上下文按字符预算（阶段 2.9）")

# 这几条的背景：以前是 tail(hist, 20)，按**条数**取。agent 循环每轮要加
# 两条消息，第 4 轮就把用户最初那句需求挤出窗口了 —— 而模型不会说
# "我忘了"，它会接着编。所以必须有下面这条「原始需求永远在内」的保证。

chk("NA 被压成空串，不是报错（nzchar(NA) 是 TRUE，最容易踩）",
    identical(dsapp_ctx_trim(NA_character_, 100), ""))
chk("NULL 被压成空串", identical(dsapp_ctx_trim(NULL, 100), ""))
chk("短的原样返回", identical(dsapp_ctx_trim("hello", 100), "hello"))
long_s <- paste(rep("abcdefghij", 100), collapse = "")
tr <- dsapp_ctx_trim(long_s, 200)
chk("长的头尾都留着，中间省略", startsWith(tr, "abcdefghij") &&
      endsWith(tr, "abcdefghij") && grepl("省略", tr))
chk("多字节不会被切成半个字（substr 按字符切，但要确认）",
    validUTF8(dsapp_ctx_trim(paste(rep("生物信息学", 100), collapse = ""), 60)))

mkhist <- function(roles, contents) data.frame(role = roles, content = contents,
                                               stringsAsFactors = FALSE)
chk("空历史 → 空 list",
    identical(dsapp_build_context(mkhist(character(0), character(0))), list()))
chk("NULL → 空 list", identical(dsapp_build_context(NULL), list()))

hc <- dsapp_build_context(mkhist(c("user", "assistant", "user"),
                                 c("做差异分析", "代码如下", "接着做")))
chk("正常历史原样带过", length(hc) == 3 && identical(hc[[1]]$content, "做差异分析"))

# 这是本节存在的理由：旧写法会丢，新写法不会
roles_n <- c("user", rep(c("assistant", "tool"), 15))
cont_n <- c("原始需求：读 expr.csv 做差异分析然后画火山图",
            rep(c(paste(rep("x", 3000), collapse = ""),
                  paste(rep("y", 3000), collapse = "")), 15))
hn <- mkhist(roles_n, cont_n)
cn <- dsapp_build_context(hn, budget = 24000L)
has_req <- function(ctx) any(grepl("原始需求", vapply(ctx, function(m) m$content, "")))
chk("★ 原始需求在预算内被保住", has_req(cn))
chk("确实做了截取（不是全塞进去）", length(cn) < length(roles_n))
old_ctx <- lapply(utils::tail(seq_along(roles_n), 20),
                  function(i) list(role = roles_n[i], content = cont_n[i]))
chk("（对照）旧写法 tail(hist,20) 会把它丢掉", !has_req(old_ctx))

chk("tool 角色降级成 user（不带 tool_call_id 的 role:tool 会被厂商 400）",
    { h3 <- dsapp_build_context(mkhist(c("user", "tool"),
                                       c("hi", "【执行结果 · 任务 #3】status: success")))
      identical(h3[[2]]$role, "user") && !any(vapply(h3, function(m) m$role, "") == "tool") })
chk("单条超长不会吃光整个预算",
    { per <- 8000L
      h4 <- dsapp_build_context(mkhist(c("user", "assistant", "tool"),
                                       c("原始需求", "code", paste(rep("Z", 5e5), collapse = ""))),
                                per_msg = per)
      # 裁剪后会多出一句「此处省略 N 个字符」的说明，给点余量。
      nchar(h4[[length(h4)]]$content) <= per + 200 && has_req(h4) })

# ---- 单元粒度：配对不能拆、预算要真的生效（2026-09-14 二次修正）-----------
# 第一版按**轮**整段收，配对保住了，但"最后一段无条件保留"让预算彻底失效：
# agent 循环里最后一段正是最长的那段。下面两条把这两个约束一起钉住。
chk("★★ 预算真的生效：最后一段再长也不能整个塞进去", {
  roles_b <- c("user", rep(c("assistant", "tool"), 15))
  cont_b <- c("原始需求",
              rep(c(paste(rep("x", 3000), collapse = ""),
                    paste(rep("y", 3000), collapse = "")), 15))
  b <- dsapp_build_context(mkhist(roles_b, cont_b), budget = 24000L)
  total <- sum(vapply(b, function(m) nchar(m$content), numeric(1)))
  # 缺口说明本身也占字符，给一点余量（48000 预算下按 24K 验，余量给足）
  total <= 24000 + 2000
})
chk("★★ 不留下没有前因的执行结果（tool 前面那条 assistant 必须在）", {
  roles_b <- c("user", rep(c("assistant", "tool"), 15))
  cont_b <- c("原始需求",
              rep(c(paste(rep("x", 3000), collapse = ""),
                    paste(rep("y", 3000), collapse = "")), 15))
  b <- dsapp_build_context(mkhist(roles_b, cont_b), budget = 24000L)
  rl <- vapply(b, function(m) m$role, "")
  # 组装后 tool 已经降级成 user，认不出原来那个了；改成认**内容**：
  # 每一段 y（执行结果）前面必须紧跟着一段 x（提交它的助手消息）。
  ok <- TRUE
  for (i in seq_along(b)) {
    if (grepl("^y+$", b[[i]]$content) && (i == 1L || !grepl("^x+$", b[[i - 1L]]$content))) {
      ok <- FALSE
    }
  }
  ok && any(grepl("^y+$", vapply(b, function(m) m$content, "")))
})

# finish_reason 的父进程一侧。子进程那侧（SSE 解析，关键是 delta 为 null 的
# 那一拍也要收到）用假服务端单独验：Rscript /tmp/t_finish.R。
fr_h <- list2env(list(out_file = file.path(tmp, "fr.out"),
                      reason_file = NULL,
                      status_file = file.path(tmp, "fr.json"),
                      read_pos = 0L, reason_pos = 0L, proc = NULL),
                 parent = emptyenv())
file.create(fr_h$out_file)
writeLines('{"status":"done","error":null,"usage":null,"finish_reason":"length"}',
           fr_h$status_file)
p_fr <- dsapp_llm_poll(fr_h)
chk("poll 把 finish_reason 带出来", identical(p_fr$finish_reason, "length"))
# jsonlite 把 `{}` 解析成 list()，它跟 "length" 比永远不相等 —— 那正好是
# "截断被静默忽略"，最难查。所以非字符串一律当没有。
writeLines('{"status":"done","error":null,"usage":null,"finish_reason":{}}',
           fr_h$status_file)
chk("finish_reason 是 {} 时当没有，不是返回 list()",
    is.null(dsapp_llm_poll(fr_h)$finish_reason))
writeLines('{"status":"done","error":null,"usage":null,"finish_reason":""}',
           fr_h$status_file)
chk("空串也算没有", is.null(dsapp_llm_poll(fr_h)$finish_reason))

