section("启动清理（R/gc.R）")

# 这一段测的是**删数据的代码**，所以重点不在"删掉了该删的"，而在
# "没删不该删的"。下面每一条负向检查都对应一种会把用户成果删掉的方式。
mkws <- function(sid, mtime = NULL) {
  d <- file.path(cfg$ws_root, dsapp_ws_name(sid))
  dir.create(d, recursive = TRUE, showWarnings = FALSE)
  writeLines("x", file.path(d, "keep.txt"))
  if (!is.null(mtime)) Sys.setFileTime(d, mtime)
  d
}
# 年龄下限用的是目录 mtime，测试里要显式摆到"很旧"，否则会被跳过。
old <- Sys.time() - 3600

live_sid <- dsapp_id("s")
live_dir <- mkws(live_sid, old)
gone_dir <- mkws(dsapp_id("s"), old)

# 会话表里登记 live_sid，另一个不登记 → 后者才是孤儿。
ins_live <- function() {
  invisible(DBI::dbExecute(dsapp_db(cfg),
    "INSERT OR REPLACE INTO sessions (id, title, created_at, updated_at)
     VALUES (?, 't', '2026-01-01', '2026-01-01')", params = list(live_sid)))
}
ins_live()

g1 <- dsapp_gc_orphan_ws(cfg, min_age_mins = 10)
chk("★ 孤儿工作区被删掉", !dir.exists(gone_dir))
chk("★ 活着的对话的工作区**没被动**", dir.exists(live_dir))
chk("删掉的数量如实回报", g1$n == 1L)

# ⚠️ 这条是整段的重点。数据库读不出来时，会话集合会退化成"空"，
#    而"空"的含义是"每个工作区都是孤儿" —— 那就是把所有人的成果一次删光。
#    所以查库失败必须放弃整个动作，而不是"当作没有对话"继续。
#
# ⚠️ 模拟手法是**把表挪走**，不是换一个 db_path。dsapp_db() 会把连接缓存在
#    进程级状态里（db.R:27-31），换了 cfg 也还是拿到同一个连接 —— 一开始
#    就是那么写的，结果这条测试测的是"正常路径"，两次都绿，等于没测。
con <- dsapp_db(cfg)
invisible(DBI::dbExecute(con, "DROP TABLE sessions"))
survivor <- mkws(dsapp_id("s"), old)
g2 <- dsapp_gc_orphan_ws(cfg, min_age_mins = 10)
chk("★ 数据库读不出来时，一个工作区都不删", dir.exists(survivor))
chk("并且如实报告是读库失败，不是'没有孤儿'", isTRUE(g2$db_error))
# 收拾干净，后面的检查还要用这张表
dsapp_db_schema(con); ins_live()

# 年龄下限：刚动过的工作区不动。应用重启时旧进程可能还在收尾，
# 那会儿它的工作区 mtime 就是"刚刚"。
fresh <- mkws(dsapp_id("s"), Sys.time())
g3 <- dsapp_gc_orphan_ws(cfg, min_age_mins = 10)
chk("★ 刚被动过的工作区不删（可能还有进程在写）", dir.exists(fresh))
chk("跳过的数量如实回报", g3$skipped >= 1L)

# 只认 chat- 前缀。ws_root 下将来多出别的东西（比如有人手工放了个目录），
# 不该被当成孤儿清掉。
other <- file.path(cfg$ws_root, "notes")
dir.create(other, showWarnings = FALSE)
Sys.setFileTime(other, old)
invisible(dsapp_gc_orphan_ws(cfg, min_age_mins = 10))
chk("★ 非 chat- 前缀的目录一概不碰", dir.exists(other))

# 名字反解不能靠猜：目录名要经过 dsapp_ws_name() 的字符清洗，而清洗是有损的。
# 这里确认实现走的是"从库里的 id 重建期望名字"这条路 —— 真实 id 洗不出变化，
# 期望集合才能和磁盘上的名字对上。
chk("★ 真实对话号经清洗后名字不变（所以重建期望名是可靠的）",
    identical(dsapp_ws_name(live_sid), paste0("chat-", live_sid)))

# ---- 中转文件 ----
# llm 的中转文件是 <token>.out，token 本身以 llm- 开头（见 llm.R），
# 和 job-/bg- 的 <前缀>-<id>.<后缀> 形状不同。这两类都要被认出来。
jr <- file.path(cfg$run_dir, "job-77.json")
lr <- file.path(cfg$run_dir, "llm-1757654321-00042.out")
sr <- file.path(cfg$run_dir, "llm-1757654321-00042.json")
tr <- file.path(cfg$run_dir, "job-78.json.tmp")
# 有人手工放进 run/ 的东西：不是我们写的，不该删
br <- file.path(cfg$run_dir, "README.txt")
for (f in c(jr, lr, sr, tr, br)) writeLines("x", f)
# ⚠️ 要摆到**超过 max_age_hours（24 小时）**，不是超过孤儿工作区那个 10 分钟。
#    这个夹具一开始只回拨了 1 小时，于是四个文件一个都没被删，四条断言全红 ——
#    红得还很有道理：回收本来就是按 24 小时算的。夹具的时钟要和被测的阈值对齐。
for (f in c(jr, lr, sr, tr, br)) Sys.setFileTime(f, Sys.time() - 48 * 3600)
# 新的（别的会话正在用的）不能删
newf <- file.path(cfg$run_dir, "job-99.json")
writeLines("x", newf)

g4 <- dsapp_gc_scratch(cfg, max_age_hours = 24)
chk("★ job-*.json 被回收", !file.exists(jr))
chk("★ llm-*.out 被回收", !file.exists(lr))
chk("★ llm-*.json 被回收", !file.exists(sr))
chk("★ 写了一半的 .json.tmp 也回收", !file.exists(tr))
chk("★ run/ 里不是我们写的文件一概不碰", file.exists(br))
chk("★ 没过期的中转文件不删（可能正有人在读）", file.exists(newf))

# work/ 下的暂存目录
old2 <- Sys.time() - 48 * 3600
wd <- file.path(cfg$work_dir, "remote-123"); dir.create(wd, showWarnings = FALSE)
Sys.setFileTime(wd, old2)
# ⚠️⚠️ task-<id> 是**用户数据**，不是中转文件。它的路径写进了 tasks 表
#     （executor.R 的 workdir），任务页拿它列"产物"。删掉它，任务记录还在、
#     产物清单却空了 —— 而删除对话框上写着「不会删除已产出的文件」。
#     一开始我就是把它当中转文件收的，这条断言是那个错误的墓志铭。
wd2 <- file.path(cfg$work_dir, "task-456")
dir.create(wd2, showWarnings = FALSE)
writeLines("结果", file.path(wd2, "result.csv"))
Sys.setFileTime(wd2, old2)
wd3 <- file.path(cfg$work_dir, "task-abc"); dir.create(wd3, showWarnings = FALSE)
Sys.setFileTime(wd3, old2)
invisible(dsapp_gc_scratch(cfg, max_age_hours = 24))
chk("★ work/remote-<数字> 暂存目录被回收", !dir.exists(wd))
chk("★★ work/task-<数字> 一个字节都不能动（任务页还要读它的产物）",
    dir.exists(wd2) && file.exists(file.path(wd2, "result.csv")))
chk("work/task-abc 也不碰（任务号一定是数字）", dir.exists(wd3))
# 同上：产物文件本身也不能被 run/ 那套规则顺走
chk("★ 产物文件不在回收范围内", file.exists(file.path(wd2, "result.csv")))

