section("V5：归属隔离")

# 库表是幂等建的：dsapp_db_schema() 每次启动都跑一遍，不能第二次报错
# （SQLite 没有 CREATE TABLE IF NOT EXISTS 之外的花样，加列要靠 PRAGMA 探）
chk("users 表建出来了",
    "users" %in% DBI::dbListTables(dsapp_db(cfg)))
chk("file_owner 表建出来了",
    "file_owner" %in% DBI::dbListTables(dsapp_db(cfg)))
chk("sessions 有了 user_id 列",
    "user_id" %in% DBI::dbGetQuery(dsapp_db(cfg),
      "PRAGMA table_info(sessions)")$name)
chk("messages 有了 reasoning 列",
    "reasoning" %in% DBI::dbGetQuery(dsapp_db(cfg),
      "PRAGMA table_info(messages)")$name)
chk("schema 重跑一遍不报错（启动会跑很多遍）",
    isTRUE(tryCatch({ dsapp_db_schema(dsapp_db(cfg)); TRUE },
                    error = function(e) conditionMessage(e))))

con <- dsapp_db(cfg)
r1 <- mkuser("甲", "jia@example.com", "13800000001", "转录组", con = con)
r2 <- mkuser("乙", "yi@example.com",  "13800000002", "蛋白组", con = con)
chk("注册成功", isTRUE(r1$ok) && isTRUE(r2$ok))
chk("★ 第一个账号自动成为管理员（否则新部署没有管理员）",
    dsapp_user_is_admin(r1$user))
chk("第二个不是管理员", !dsapp_user_is_admin(r2$user))
chk("★ 同邮箱不能注册两次",
    !isTRUE(dsapp_user_create("丙", "jia@example.com", "138", "x", password = "pw123456", con = con)$ok))
chk("邮箱大小写不敏感（同一个账号）",
    identical(dsapp_user_by_email("JIA@Example.com", con)$id, r1$user$id))
# ⚠️ V11 item 4b 之后这里**不能**再拿裸令牌去调 dsapp_user_by_token：那个函数
#    现在要求值里带"这一端"（`<令牌>.<nonce>`，见 R/logins.R），裸令牌一律判否。
#    走真实的那条路 —— 恢复码登录是 dsapp_user_auth_token（邮箱 + 恢复码），
#    它比的仍然是 users.token，没受单端登录影响。
chk("恢复码能换回账号", {
  a <- dsapp_user_auth_token("jia@example.com", r1$token, con = con)
  isTRUE(a$ok) && identical(a$user$id, r1$user$id)
})
chk("★★ 裸恢复码**不能**直接当 cookie 用（能的话手写一个就绕开了单端限制）",
    is.null(dsapp_user_by_token(r1$token, con)) &&
      identical(dsapp_user_by_token_raw(r1$token, con)$id, r1$user$id))
chk("乱填的恢复码换不到账号", is.null(dsapp_user_by_token("deadbeef", con)))

s1 <- db_session_create("甲的对话", user_id = r1$user$id, con = con)
s2 <- db_session_create("乙的对话", user_id = r2$user$id, con = con)
db_message_add(s1, "user", "甲说的话", con = con)
db_message_add(s2, "user", "乙说的话", con = con)
# 显示名：文件页/环境页标题栏那句"对话「…」的工作区"。
# 这里守的是一个具体的错法 —— 对话号不是整数，as.integer() 会给出 NA，
# 界面上就是"对话 #NA 的工作区"，后台还跟着一行 coercion 警告。
chk("★ 对话显示名用标题，不是 as.integer(对话号)",
    identical(db_session_label(s1, con = con), "对话「甲的对话」"))
chk("对话已经没了也不会显示 NA", {
  lbl <- db_session_label("s-不存在", con = con)
  !grepl("NA", lbl, fixed = TRUE) && nzchar(lbl)
})
chk("没有选中的对话时显示空串（不是 NULL，也不是 #NA）", {
  lbl <- db_session_label(NULL, con = con)
  is.character(lbl) && length(lbl) == 1 && !nzchar(lbl)
})

# 任务归属：删对话 / 关页面时"只停本对话的任务"那道闸门。
# ⚠️ 夹具必须用**真实形状**的对话号。用整数夹具时 as.integer() 能转换，
#    "两边都变 NA → identical() 为 TRUE"这个错法测不出来（见 utils.R 里
#    chat-NA 那段同样的教训）。
trow_a <- list(session_id = s1)
chk("★ 任务归属：本对话的任务认得出来", dsapp_task_in_session(trow_a, s1))
chk("★ 任务归属：别的对话的任务不会被误认（这是删对话时杀错任务的那个 bug）",
    !dsapp_task_in_session(trow_a, s2))
chk("★ 任务归属：两个不同的对话号不能因为都转成 NA 而相等",
    !dsapp_task_in_session(list(session_id = s1), "s-20260101000000-1"))
chk("任务归属：没有对话的任务不算任何人的",
    !dsapp_task_in_session(list(session_id = NA_character_), s1))
chk("任务归属：查不到任务行 / 没有对话号时一律 FALSE",
    !dsapp_task_in_session(NULL, s1) && !dsapp_task_in_session(trow_a, NULL))

l1 <- db_sessions_list(user_id = r1$user$id, con = con)
l2 <- db_sessions_list(user_id = r2$user$id, con = con)
# ⚠️ 不能断言 nrow(l1) == 1：第一个账号注册时会**顺手认领此前所有无主对话**
#    （这个自检脚本前面几节建的那些），那正是我们要的行为。所以这里断言的是
#    归属关系本身，不是条数。
chk("甲看得到自己建的对话", s1 %in% l1$id)
chk("★ 乙看不到甲的那条", !(s1 %in% l2$id))
chk("乙看得到自己的", s2 %in% l2$id)
chk("★ 甲的列表里没有乙的", !(s2 %in% l1$id))
# 漏传 user_id 必须是"空"，不能是"全部" —— 这是最容易写错的地方：
# 一个忘了传身份的调用点，会把全站数据漏出去。
chk("★★ 漏传 user_id 时返回空集，而不是全站数据",
    nrow(db_sessions_list(con = con)) == 0)
chk("显式 all=TRUE 才拿到全部（管理页用）",
    nrow(db_sessions_list(all = TRUE, con = con)) >= 2)

t1 <- db_task_create("甲的任务", "print(1)", "r", session_id = s1, con = con)
t2 <- db_task_create("乙的任务", "print(2)", "r", session_id = s2, con = con)
tl1 <- db_tasks_list(user_id = r1$user$id, con = con)
chk("甲只看得到自己的任务", t1 %in% tl1$id && !(t2 %in% tl1$id))
chk("★ 漏传 user_id 时任务列表也是空的",
    nrow(db_tasks_list(con = con)) == 0)
chk("任务的归属是**顺着对话**判定的（tasks 表没有 user_id 列）",
    identical(DBI::dbGetQuery(con, "SELECT session_id FROM tasks WHERE id = ?",
                              params = list(t2))$session_id, s2))

# 停用：能登录的闸门在 dsapp_user_active()，不在密码校验里 ——
# 密码对但账号停用，一样进不来。
dsapp_user_set_status(r2$user$id, "disabled", con = con)
chk("停用后 dsapp_user_active 为 FALSE",
    !dsapp_user_active(dsapp_user_by_id(r2$user$id, con)))
chk("★ 停用后认证被拒（不是只把界面藏起来）",
    !isTRUE(dsapp_user_auth("yi@example.com", "", con = con)$ok))
chk("★ 停用后恢复码也进不来",
    !isTRUE(dsapp_user_auth_token("yi@example.com", r2$token, con = con)$ok))
dsapp_user_set_status(r2$user$id, "active", con = con)
chk("重新启用后恢复码又能用了",
    isTRUE(dsapp_user_auth_token("yi@example.com", r2$token, con = con)$ok))

# 密码登录。★ V13.1 item 7 之后这里只有一条规矩：**没有密码就进不来**。
# 原来是两条（设了密码的看密码、没设的空密码放行），那条旁路已经删了。
r3 <- dsapp_user_create("丙", "bing@example.com", "13800000003", "代谢组",
                        password = "hunter2", con = con)
chk("设了密码的账号，空密码进不来",
    !isTRUE(dsapp_user_auth("bing@example.com", "", con = con)$ok))
chk("设了密码的账号，错密码进不来",
    !isTRUE(dsapp_user_auth("bing@example.com", "wrong", con = con)$ok))
chk("★ 设了密码的账号，对密码能进",
    isTRUE(dsapp_user_auth("bing@example.com", "hunter2", con = con)$ok))

# ★★★ 这一组是 item 7 的核心：**老库里那些 pass_hash = '' 的账号**。
#     V13.0 及以前它们是靠"空密码放行"进来的（那条旁路现在删了）。
#
#     ⚠️ 这个夹具**必须用 mk_legacy_nopw() 直接 INSERT**，不能拿
#        dsapp_user_create(..., "") 去造 —— 后者现在会返回 ok = FALSE 且
#        **一行都不建**，于是下面三条断言测的是一个不存在的账号，
#        永远绿，而真正要防的那个洞一个都没覆盖到。
em_legacy <- "legacy_nopw@example.com"
invisible(try(DBI::dbExecute(con, "DELETE FROM users WHERE email = ?",
                             params = list(em_legacy)), silent = TRUE))
legacy_id <- mk_legacy_nopw(em_legacy, con, "免密时代的老账号")
chk("（前置）确实造出了一个 pass_hash 为空串的老账号",
    identical(DBI::dbGetQuery(con, "SELECT pass_hash FROM users WHERE email = ?",
                              params = list(em_legacy))$pass_hash[[1]], ""))

chk("★★★ 没设密码的账号，空密码**进不来**了（免密登录已整条取消）",
    !isTRUE(dsapp_user_auth(em_legacy, "", con = con)$ok))
chk("★★ 而且随便填个密码也进不来（不是「换个填法就进去了」）",
    !isTRUE(dsapp_user_auth(em_legacy, "whatever", con = con)$ok))
chk("★★ 提示要说清是什么事 + 下一步怎么办（出口是管理员重置或恢复码）", {
  m <- dsapp_user_auth(em_legacy, "", con = con)$msg %||% ""
  grepl("密码", m) && (grepl("管理员", m) || grepl("恢复码", m))
})
chk("★★ 无密码账号恢复码**仍然**能用（那是唯一的自助出口，不是免密）",
    isTRUE(dsapp_user_auth_token(em_legacy,
      dsapp_user_by_email(em_legacy, con)$token, con = con)$ok))
chk("★ 管理员给它设一个密码之后就能正常登录了（唯一的正规出口是通的）", {
  invisible(dsapp_user_set_password(legacy_id, "brand-new-pw",
                                    skip_old_check = TRUE, con = con))
  isTRUE(dsapp_user_auth(em_legacy, "brand-new-pw", con = con)$ok)
})

# ---- 补设 / 修改密码 ----
#
# 这一组盯的是**三条入口共用同一个函数**这件事：注册时补设、用户自己改、
# 管理员重置。散列和 salt 只在一个地方生成，salt 每次必须换新。
pid <- r3$user$id                       # 丙：已经设过 hunter2 的那个
old_row <- dsapp_user_by_id(pid, con)
chk("账号默认不带「必须改密」标记",
    !isTRUE(dsapp_user_pw_state(old_row)$must_change))
chk("已设密码的账号，状态里 has = TRUE",
    isTRUE(dsapp_user_pw_state(old_row)$has))

# 1) 当前密码不对 → 拒绝
bad <- dsapp_user_set_password(pid, "newpass1", old_password = "nope", con = con)
chk("★ 当前密码不对时不给改", !isTRUE(bad$ok))
chk("被拒时标出是「当前密码」的问题（界面靠它把焦点放到那一栏）",
    isTRUE(bad$wrong_old))
chk("★ 被拒之后旧密码仍然有效（没被改成新密码）",
    isTRUE(dsapp_user_auth("bing@example.com", "hunter2", con = con)$ok))

# 2) 不填当前密码 → 拒绝（不能靠"留空"绕过）
chk("★ 不填当前密码也改不了", !isTRUE(dsapp_user_set_password(pid, "newpass1", con = con)$ok))

# 3) 正确路径
ok <- dsapp_user_set_password(pid, "newpass1", old_password = "hunter2", con = con)
chk("当前密码对时能改", isTRUE(ok$ok))
chk("★ 改完新密码生效", isTRUE(dsapp_user_auth("bing@example.com", "newpass1", con = con)$ok))
chk("★ 改完旧密码失效", !isTRUE(dsapp_user_auth("bing@example.com", "hunter2", con = con)$ok))
new_row <- dsapp_user_by_id(pid, con)
chk("★ 改密码会换一个新的 salt（不换的话两个用同一密码的账号散列一模一样）",
    !identical(as.character(new_row$pass_salt), as.character(old_row$pass_salt)))
chk("salt 不是空串（空 salt 等于没有 salt）", nzchar(as.character(new_row$pass_salt)))
chk("密码在库里不是明文",
    !grepl("newpass1", as.character(new_row$pass_hash), fixed = TRUE))

# 4) 太短
chk("新密码太短会被拒",
    !isTRUE(dsapp_user_set_password(pid, "12345", old_password = "newpass1", con = con)$ok))
chk("刚好到下限可以（和注册用的是同一个数）",
    isTRUE(dsapp_user_set_password(pid, "123456", old_password = "newpass1", con = con)$ok))

# 5) 没设过密码的账号：直接补设，不需要当前密码
#
# ⚠️ 这个夹具**必须**是没有密码的老账号。原来是拿 jia（r1）当它的 ——
#    V13.1 修 item 7 时 jia 拿到了真密码，于是"不用旧密码就能补设"这条
#    变成了"拿一个有密码的账号去跳过旧密码校验"，断言红得莫名其妙。
#    所以这里现造一个 pass_hash = '' 的老账号，语义才对得上。
em_setpw <- "nopw_setpw@example.com"
invisible(try(DBI::dbExecute(con, "DELETE FROM users WHERE email = ?",
                             params = list(em_setpw)), silent = TRUE))
jid <- mk_legacy_nopw(em_setpw, con, "还没设过密码的")
chk("（前置）这个账号确实没有密码",
    identical(DBI::dbGetQuery(con, "SELECT pass_hash FROM users WHERE email = ?",
                              params = list(em_setpw))$pass_hash[[1]], ""))
chk("★ 没设密码的账号可以直接补设（此时没有旧密码可验）",
    isTRUE(dsapp_user_set_password(jid, "freshpw", con = con)$ok))
chk("★ 补设之后就不能空密码进了（原来那条路被关上）",
    !isTRUE(dsapp_user_auth(em_setpw, "", con = con)$ok))
chk("补设之后用新密码能进",
    isTRUE(dsapp_user_auth(em_setpw, "freshpw", con = con)$ok))
chk("★ 补设之后**再**想跳过旧密码校验就不行了（有了密码就得验）",
    !isTRUE(dsapp_user_set_password(jid, "another", con = con)$ok))

# 6) 管理员重置：打标记 + 旧密码失效 + 恢复码不受影响
adm <- dsapp_user_admin_reset_password(jid, "temppw123", con = con)
chk("管理员重置成功", isTRUE(adm$ok))
chk("★ 重置后打上「下次登录必须改密」的标记",
    isTRUE(dsapp_user_pw_state(dsapp_user_by_id(jid, con))$must_change))
# ⚠️ 这一组原来的账号是 jia（r1）。上面第 5 段把夹具换成了没有密码的老账号
#    em_setpw，所以这里也必须跟着换 —— 漏换的话「重置后原来的密码失效」
#    会**假绿**（jia 从来就没有过 freshpw 这个密码，当然登不进去）。
chk("★ 重置后用临时密码能登进来（否则用户被锁在门外，标记也没机会生效）",
    isTRUE(dsapp_user_auth(em_setpw, "temppw123", con = con)$ok))
chk("★ 重置后原来的密码失效",
    !isTRUE(dsapp_user_auth(em_setpw, "freshpw", con = con)$ok))
chk("重置密码**不动**恢复码（那是最后一条退路，不能被顺手换掉）",
    isTRUE(dsapp_user_auth_token(em_setpw,
      dsapp_user_by_email(em_setpw, con)$token, con = con)$ok))
chk("★ 认证结果里带出 must_change（登录后要靠它决定进不进得去主界面）",
    isTRUE(dsapp_user_auth(em_setpw, "temppw123", con = con)$must_change))

# 7) 用户自己改完，标记要清掉 —— 不清的话他每次登录都被拦一次
chk("★ 自己改完密码，标记清掉",
    isTRUE(dsapp_user_set_password(jid, "mypw1234", old_password = "temppw123",
                                   con = con)$ok))
chk("★ 改完之后 must_change 是 FALSE",
    !isTRUE(dsapp_user_pw_state(dsapp_user_by_id(jid, con))$must_change))
chk("改完之后认证结果里也不带标记了",
    !isTRUE(dsapp_user_auth(em_setpw, "mypw1234", con = con)$must_change))

# 8) 恢复码那条路：skip_old_check 只能由"已经验过恢复码"的调用方传
chk("★ skip_old_check 能跳过旧密码（恢复码入口用）",
    isTRUE(dsapp_user_set_password(jid, "viaToken1", skip_old_check = TRUE,
                                   con = con)$ok))
chk("跳过之后新密码生效",
    isTRUE(dsapp_user_auth(em_setpw, "viaToken1", con = con)$ok))
chk("★ 默认**不**跳过：同一个调用不传 skip_old_check 就会被旧密码挡住",
    !isTRUE(dsapp_user_set_password(jid, "sneaky1", con = con)$ok))

# 9) 重置密码同时清掉登录失败计数（重置的常见起因就是被锁在门外）
# ⚠️ 计数的邮箱和重置的账号**必须是同一个**。写成 jia 的话，下面那条会假绿：
#    jia 从头到尾没被计过数，当然"没被锁住"。
invisible(dsapp_login_fail(em_setpw, con))
chk("（前置）先确认它真的被计上数了（否则下面那条是空转）",
    !is.null(dsapp_login_row(em_setpw, con)))
invisible(dsapp_user_admin_reset_password(jid, "temppw999", con = con))
chk("★ 重置密码顺手解锁（否则用户拿到新密码还是进不来）",
    !isTRUE(dsapp_login_locked(em_setpw, con)$locked))

# 文件归属
#
# ★ V13 item 6 起，每个账号一个管理区（data/files/u<N>/），归属表的键也带上
#   了账号前缀（`u3/asv_table.csv`，见 users.R 的 dsapp_owner_key）。所以下面
#   每一条都要说清"这是在**谁的**管理区里问"—— 不带账号去问，查到的是
#   `_anon/` 那一段，永远查不到，返回的 NA 又会被 can_edit 解释成"无主"。
#
# ⚠️ 「甲不能动乙的文件」这条**已经不在这里测了**，不是删掉：跨账号现在压根
#    不会走到这个函数 —— 乙的文件在 data/files/u2/ 下，甲的界面永远列不出
#    来，路径也解析不过去（见下面「管理区隔离」那一节）。留在这一层测只会
#    测出"两个名字碰巧对不上"。
chk("本账号里没有归属行的文件可编辑（V5 之前传的，锁死会让谁都清不掉）",
    dsapp_file_can_edit("old.csv", r2$user, con = con))
dsapp_file_owner_set("mine.csv", r1$user$id, con = con)
dsapp_file_owner_set("yours.csv", r2$user$id, con = con)
chk("自己的文件可编辑", dsapp_file_can_edit("mine.csv", r1$user, con = con))
chk("★ 管理员可以动**任何**账号的文件（管理页要能清）",
    dsapp_file_can_edit("yours.csv", r1$user, con = con))
chk("没有身份时一律不可编辑（漏传 user 的兜底）",
    !dsapp_file_can_edit("mine.csv", NULL, con = con))
dsapp_file_owner_drop("mine.csv", con = con, user_id = r1$user$id)
chk("归属删掉之后又变回公共（本账号内）",
    isTRUE(dsapp_file_can_edit("mine.csv", r1$user, con = con)))

# ---- 管理区隔离（V13 item 6 的核心不变式）-------------------------------
# 这一节测的是"甲能不能够到乙的东西"。够不到**不是**靠界面少画一行，是靠
# 两条硬的：路径解析（dsapp_file_path）解析不到别人的根，以及归属键带账号
# 前缀（同名的两个文件在表里是两行，不会互相顶掉）。
c1 <- dsapp_config_user(1L, cfg)
c2 <- dsapp_config_user(3L, cfg)
chk("★ 两个账号的管理区是两个不同的目录",
    !identical(dsapp_files_root(1L, cfg), dsapp_files_root(3L, cfg)))
chk("★ `u3/x.csv` 这种写法只会落到**自己**区里的一个子目录（跳不到 3 号区）", {
  # must_exist = FALSE 才看得出来落点。用默认的 TRUE 的话，两个区里都没有
  # 这个文件，返回的都是 NULL —— 断言过了，但过的是"文件不存在"，跟越界
  # 一点关系都没有。
  p <- dsapp_file_path("u3/asv_table.csv", c1, must_exist = FALSE)
  !is.null(p) && startsWith(p, dsapp_files_root(1L, cfg)) &&
    !startsWith(p, dsapp_files_root(3L, cfg))
})
chk("★ 靠 `..` 爬到别的账号区里 —— 解析阶段就拒（连路径都不给）",
    is.null(dsapp_file_path("../u3/asv_table.csv", c1, must_exist = FALSE)) &&
    is.null(dsapp_file_path("u1/../u3/asv_table.csv", c1, must_exist = FALSE)))
chk("★ 漏传账号时用的是 _anon，它**不是任何一个账号的区**（所以什么也查不到）", {
  # 这是失败方向的设计：默认值取 `files_root` 自己的话，一个忘了传账号的
  # 调用方拿到的是"所有账号区的父目录"，`u3/xxx.csv` 这种相对路径会**正好
  # 解析成功**，甲就够到了乙的文件。取 `_anon` 的话同样的疏忽表现为一个
  # 空列表 —— 错得响亮，而且错在安全的那一侧。
  g <- dsapp_config()
  identical(basename(g$files_dir), "_anon") &&
    !normalizePath(g$files_dir, mustWork = FALSE) %in%
      vapply(c(1L, 3L),
             function(u) normalizePath(dsapp_files_root(u, g), mustWork = FALSE),
             character(1))
})
chk("★★ 同一个相对路径在两个账号下解析成两个不同的绝对路径", {
  # ⚠️ 先把两个区都建出来。dsapp_path_in 在 root 目录不存在时直接返回 NULL，
  #    不建的话 3 号那边解析回来是 NULL，断言挂在"is.null"上 —— 看着是路径
  #    隔离坏了，其实是测试自己少建了一个目录。
  invisible(dsapp_files_ensure(1L, cfg))
  invisible(dsapp_files_ensure(3L, cfg))
  p1 <- dsapp_file_path("asv_table.csv", c1, must_exist = FALSE)
  p3 <- dsapp_file_path("asv_table.csv", c2, must_exist = FALSE)
  !is.null(p1) && !is.null(p3) && !identical(p1, p3) &&
    startsWith(p1, dsapp_files_root(1L, cfg)) &&
    startsWith(p3, dsapp_files_root(3L, cfg))
})
# 同名文件在两个账号里各有一行归属 —— 键不带前缀的话主键会撞，撞了之后
# 后来者顶掉先来者，先来的那个账号就"删不掉自己的文件"（can_edit 认为
# 归属是别人的）。这条就是那个 bug 的回归测试。
dsapp_file_owner_set("asv_table.csv", 1L, con = con)
dsapp_file_owner_set("asv_table.csv", 3L, con = con)
chk("★★ 同名文件能在两个账号下各存一行归属（键带了账号前缀，主键不撞）",
    identical(dsapp_file_owner("asv_table.csv", con, 1L), 1L) &&
    identical(dsapp_file_owner("asv_table.csv", con, 3L), 3L))

# 无主数据认领：第一个账号注册时接管 V5 之前的对话
orphan <- db_session_create("V5 之前的对话", user_id = NULL, con = con)
claimed <- dsapp_user_claim_orphans(r1$user$id, con = con)
chk("★ 首个账号接管了无主对话", claimed >= 1)
chk("接管之后那条对话归到甲名下",
    orphan %in% db_sessions_list(user_id = r1$user$id, con = con)$id)

# 删除账号：对话 + **盘上那个管理区目录**都要一并消失。
#
# ★ V16.6 item 3 改的就是这一条。用户原话：「删除账户后，该账号对应的全部
#   历史记录和文件应该一并删除，而不是进入共享区」。
#   改前这里断言的是**反的**（"他传到共享区的文件还在，且变成公共的"），
#   而那个行为正是用户报的 bug：删号只删了 file_owner 的行，`data/files/u<N>/`
#   原地不动，下一次 dsapp_files_sync_owners() 扫到它又把文件补登记回来 ——
#   界面上看就是"删过的账号，文件进了共享区"。
#
# ⚠️ 先把**真文件**写进 r2 的管理区。只写归属行的话，整段测的是"表里那行
#    没了没有"，而盘上那个目录一直不存在 —— 就算删号的代码压根没碰盘，
#    这几条也全绿（本仓栽过：判据落在最容易满足的那一侧）。
r2_root <- dsapp_files_root(r2$user$id, cfg)
dir.create(r2_root, recursive = TRUE, showWarnings = FALSE)
writeLines(c("a,b", "1,2"), file.path(r2_root, "yours.csv"))
chk("前置：r2 的管理区里真的有一个文件",
    file.exists(file.path(r2_root, "yours.csv")) &&
    grepl("^u[0-9]+$", basename(r2_root)), r2_root)

# ★ 正面控制：同一趟补登记**必须**能把活账号的文件登记进来。少了这一条，
#   下面那个"0 行"有可能只是因为 dsapp_files_sync_owners 在这儿压根不干活
#   （判据没劲，两版给同一个数）。
r1_root <- dsapp_files_root(r1$user$id, cfg)
dir.create(r1_root, recursive = TRUE, showWarnings = FALSE)
writeLines(c("x,y", "3,4"), file.path(r1_root, "alive.csv"))
invisible(dsapp_files_sync_owners(con, cfg))
chk("★ 正面控制：活账号的文件**会**被补登记（判据不是空转的）",
    nrow(DBI::dbGetQuery(con, "SELECT 1 FROM file_owner WHERE name = ?",
                         params = list(dsapp_owner_key("alive.csv",
                                                       r1$user$id)))) == 1L)

n_del <- dsapp_user_delete(r2$user$id, cfg = cfg, con = con)
chk("删除账号返回删掉的对话数", isTRUE(n_del >= 1))
chk("★ 账号没了", is.null(dsapp_user_by_id(r2$user$id, con)))
chk("★ 他的对话也没了（不能留孤儿行）",
    nrow(DBI::dbGetQuery(con, "SELECT 1 FROM sessions WHERE user_id = ?",
                         params = list(as.integer(r2$user$id)))) == 0)
chk("★★★ 他的文件目录整个没了（不是只删了归属行）",
    !dir.exists(r2_root), r2_root)
chk("★★★ 归属行也没了",
    nrow(DBI::dbGetQuery(con, "SELECT 1 FROM file_owner WHERE user_id = ?",
                         params = list(as.integer(r2$user$id)))) == 0)
# ★★★ 这一条是「文件进了共享区」那个症状的**直接**回归测试：补登记那一趟
#     扫的是**盘上**有没有 u<N> 目录。目录还在的话，这一条必红。
#     ⚠️ 判据落在**带前缀的那一行**上，而不是 sync_owners 的返回值 ——
#        返回值是全平台的总数，别的账号的文件一变它就跟着变，
#        那种断言红起来指向的地方和真正的原因（这一行在不在）差着十万八千里。
chk("★★★ 再补登记一趟，他那份文件**不会**又冒出来（这就是「进了共享区」）", {
  invisible(dsapp_files_sync_owners(con, cfg))
  nrow(DBI::dbGetQuery(con, "SELECT 1 FROM file_owner WHERE name LIKE ?",
                       params = list(paste0(dsapp_owner_key("", r2$user$id),
                                            "%")))) == 0L
})
chk("★★ 没有对应的 users 行时，dsapp_files_orphans 也不该把它列出来（目录都没了）",
    !(r2$user$id %in% dsapp_files_orphans(cfg = cfg, con = con)$uid))

# ---- 磁盘用量（管理页的"磁盘满了先找谁"）----
# 造两个工作区，大小差得足够明显，再看统计能不能把它归到正确的人头上。
d1 <- dsapp_ws_dir(s1, cfg)
dir.create(d1, recursive = TRUE, showWarnings = FALSE)
writeBin(as.raw(rep(1, 20000)), file.path(d1, "big.bin"))
d2 <- dsapp_ws_dir(s2, cfg)
dir.create(d2, recursive = TRUE, showWarnings = FALSE)
writeBin(as.raw(rep(1, 3000)), file.path(d2, "small.bin"))
# 共享区里发一个文件，也算在他头上
writeLines("x", file.path(cfg$files_dir, "shared_by_b.csv"))
dsapp_file_owner_set("shared_by_b.csv", r1$user$id, con = con)
# ⚠️ 另外造一条**指向已删账号**的归属行（真实成因：dsapp_user_delete 里
#    "清 file_owner" 和 "删 users" 是两条语句，中间断掉就留下这种行）。
#    管理页不能因此冒出一个查不到名字的幽灵账号。
dsapp_file_owner_set("ghost.csv", r2$user$id, con = con)

sz <- dsapp_dir_sizes(c(d1, d2, file.path(cfg$ws_root, "chat-不存在")))
chk("量目录：存在的量得出大小", !is.na(sz[[dsapp_ws_name(s1)]]) &&
    sz[[dsapp_ws_name(s1)]] >= 20000)
# 不存在的目录**不出现在结果里**（不是返回 NA）。上层按名字取不到 →
# NA → 归 0，见 dsapp_user_disk_usage。约定写在这里，改实现时要一起改。
chk("★ 量目录：不存在的目录不出现在结果里（上层会把它当 0）",
    !(dsapp_ws_name("不存在") %in% names(sz)))
chk("★ 量目录：不存在的目录不会变成 NA 混进结果",
    !any(is.na(sz)))
chk("量目录：一次调用拿到多个目录", length(sz) >= 2)
chk("量目录：空输入返回空向量", length(dsapp_dir_sizes(character(0))) == 0)

du <- dsapp_user_disk_usage(cfg, con = con)
chk("每个账号一行", nrow(du) >= 1 && all(c("user_id","bytes") %in% names(du)))
b1 <- du$bytes[match(r1$user$id, du$user_id)]
chk(sprintf("★ 甲的用量对得上（工作区 20000 字节，统计到 %s）", b1),
    !is.na(b1) && b1 >= 20000)
# 这条曾经红过，根因不在统计里，在 dsapp_ws_name 只取第一个元素 ——
# 传进去一串对话号，量到的只是第一个对话的工作区。
chk("★ 名字函数是向量化的（否则统计只量第一个对话）",
    length(dsapp_ws_name(c("a", "b", "c"))) == 3 &&
    identical(dsapp_ws_name(c("a", "b")), c("chat-a", "chat-b")))
chk("★ 统计里不含已删的账号（含指向它的孤儿归属行）",
    !(as.integer(r2$user$id) %in% du$user_id))

st <- dsapp_platform_stats(cfg, con = con)
chk("平台统计结构完整",
    all(c("n_users", "n_chat", "n_task", "n_files") %in% names(st)))
# ⚠️ 这里原来写的是 `identical(as.integer(st$n_users), 2L)` —— 一个**写死的
#    数字**。它的意思是"甲乙丙三个账号里，乙被删了，所以是 2"。写死之后，
#    这个 section 之前只要多出**任何一个**账号（V13.1 修 item 7 时加了几个
#    老账号夹具），它就会红，而红出来的话是「账号数不对」—— 指向统计函数，
#    跟真正的原因（自检里多建了个夹具）隔了十万八千里。
#    改成"和 users 表里的实际行数一致"，这才是它真正要守的不变式。
chk("统计里的账号数不含已删的那个（和 users 表的行数一致）", {
  live <- as.integer(DBI::dbGetQuery(con, "SELECT COUNT(*) AS n FROM users")$n[[1]])
  gone <- nrow(DBI::dbGetQuery(con, "SELECT 1 FROM users WHERE id = ?",
                               params = list(as.integer(r2$user$id)))) == 0
  identical(as.integer(st$n_users), live) && gone
})

# 总入口：任何一步出错都不能拦住启动
g5 <- dsapp_gc(cfg)
chk("总入口返回结构完整",
    all(c("ws_n", "ws_bytes", "scratch_n", "scratch_bytes", "errors") %in% names(g5)))
chk("总入口不抛异常", is.list(g5))

# ===========================================================================
# 压缩包解压（item 1：把 V1 的文件管理搬过来）
# ===========================================================================
cat("\n== 压缩包 ==\n")

chk("认得 .zip", identical(dsapp_archive_kind("a.zip"), "zip"))
chk("认得 .tar.gz / .tgz", identical(dsapp_archive_kind("a.tar.gz"), "tar") &&
    identical(dsapp_archive_kind("a.TGZ"), "tar"))
# `x.gz` 的 file_ext 也是 gz —— 光看扩展名会把它和 x.tar.gz 混成一类
chk("★ 单个 .gz 不算压缩包（不是我们能解开的东西）",
    is.na(dsapp_archive_kind("expr.csv.gz")))
chk("普通文件不是压缩包", is.na(dsapp_archive_kind("expr.csv")))

# 条目名检查：挡住 zip-slip。这是解压唯一真正的攻击面。
chk("条目名：正常路径放行",
    dsapp_archive_entry_ok("GSE123/raw/a.fq.gz") &&
    dsapp_archive_entry_ok("a.txt"))
chk("★ 条目名：绝对路径拒绝", !dsapp_archive_entry_ok("/etc/passwd"))
chk("★ 条目名：.. 跳级拒绝",
    !dsapp_archive_entry_ok("../../.ssh/authorized_keys") &&
    !dsapp_archive_entry_ok("a/../../b"))
chk("条目名：Windows 盘符和反斜杠也要挡",
    !dsapp_archive_entry_ok("C:/windows/x") &&
    !dsapp_archive_entry_ok("..\\..\\x"))
chk("条目名：名字里带点不算跳级（a..b 是合法文件名）",
    dsapp_archive_entry_ok("a..b/c.txt") && dsapp_archive_entry_ok("./a.txt"))

# ---- 真解一个包 ----
ex_ws_sid <- db_session_create("解压用", user_id = r1$user$id, con = con)
ex_src <- file.path(tmp, "ex_src")
dir.create(file.path(ex_src, "sub"), recursive = TRUE, showWarnings = FALSE)
writeLines("A", file.path(ex_src, "a.txt"))
writeLines("B", file.path(ex_src, "sub", "b.txt"))
writeLines("L", file.path(ex_src, "..", "outside.txt"))

old_wd <- getwd(); setwd(ex_src)
utils::zip(file.path(cfg$files_dir, "bundle.zip"),
           files = c("a.txt", "sub/b.txt"), flags = "-rq")
setwd(old_wd)

r_zip <- dsapp_archive_extract("bundle.zip", ex_ws_sid, cfg)
chk(sprintf("★ zip 解压成功（%s）", r_zip$msg), isTRUE(r_zip$ok))
chk("★ 解出来的文件真的在工作区里", {
  d <- file.path(dsapp_ws_dir(ex_ws_sid, cfg), r_zip$dir)
  file.exists(file.path(d, "a.txt")) && file.exists(file.path(d, "sub", "b.txt"))
})
chk("解压后工作区列表里看得到解出来的目录",
    r_zip$dir %in% dsapp_ws_files(ex_ws_sid, cfg))
chk("★ 共享区里的原包还在（解压不该动它）",
    file.exists(file.path(cfg$files_dir, "bundle.zip")))
# 隔离目录必须是临时的：解完还在工作区里留着 .dsapp_extract_* 就是垃圾。
# ⚠️ 这里要用 all.files = TRUE 直接列，不能走 dsapp_ws_files —— 那个函数
#    按设计不列点开头的文件（.Rlib / .venv 就是靠这个藏起来的），拿它来
#    查一个点开头的目录，答案是"永远没有"，测试会假绿。
chk("★ 解压用的临时目录没有留在工作区里",
    !any(grepl("^\\.dsapp_extract_",
               list.files(dsapp_ws_dir(ex_ws_sid, cfg), all.files = TRUE,
                          no.. = TRUE))))

# ---- 软链必须被丢掉 ----
ex_src2 <- file.path(tmp, "ex_src2")
dir.create(ex_src2, recursive = TRUE, showWarnings = FALSE)
writeLines("ok", file.path(ex_src2, "real.txt"))
invisible(file.symlink("/etc/passwd", file.path(ex_src2, "link_to_etc")))
old_wd <- getwd(); setwd(ex_src2)
invisible(utils::tar(file.path(cfg$files_dir, "withlink.tgz"), files = ".", compression = "gzip"))
setwd(old_wd)

r_tar <- dsapp_archive_extract("withlink.tgz", ex_ws_sid, cfg)
chk(sprintf("★ tar 解压成功（%s）", r_tar$msg), isTRUE(r_tar$ok))
chk("★ 包里的符号链接被丢弃（工作区不能有穿出去的口子）", {
  d <- file.path(dsapp_ws_dir(ex_ws_sid, cfg), r_tar$dir)
  p <- list.files(d, recursive = TRUE, all.files = TRUE, no.. = TRUE,
                  full.names = TRUE)
  # 解出来的树里一个软链都不能有
  !any(dsapp_is_link(p))
})
chk("软链以外的文件照常解出来", {
  d <- file.path(dsapp_ws_dir(ex_ws_sid, cfg), r_tar$dir)
  any(grepl("real\\.txt$", list.files(d, recursive = TRUE)))
})

# ---- zip-slip：整个包都要拒绝 ----
old_wd <- getwd(); setwd(tmp)
invisible(system2("tar", c("czf", file.path(cfg$files_dir, "slip.tgz"),
                 "--transform=s,^,../,", "outside.txt"),
        stdout = FALSE, stderr = FALSE))
setwd(old_wd)
r_slip <- dsapp_archive_extract("slip.tgz", ex_ws_sid, cfg)
chk(sprintf("★ 带 .. 跳级的包被整个拒绝（%s）", r_slip$msg),
    !isTRUE(r_slip$ok) && grepl("不安全", r_slip$msg))
chk("★ 被拒绝时没有半个目录留在工作区（不做「解一半」）",
    !any(grepl("^\\.dsapp_extract_",
               list.files(dsapp_ws_dir(ex_ws_sid, cfg), all.files = TRUE,
                          no.. = TRUE))))
chk("★ 被拒绝时也没往工作区里放半个文件（没有 slip 目录）",
    !any(grepl("slip", dsapp_ws_files(ex_ws_sid, cfg))))

# ---- 上限 ----
# ⚠️ 上限要**按这个包实际有多少条**推出来，不能写死数字：包里到底算 2 条
#    还是 3 条（目录那条算不算）取决于 zip 的实现，写死的话某天会变成
#    "上限根本没踩到"，测试却只是安静地失败，看不出是夹具还是代码的问题。
n_entries <- nrow(utils::unzip(file.path(cfg$files_dir, "bundle.zip"), list = TRUE))
cfg_tiny <- cfg
cfg_tiny$extract <- list(max_bytes = 1e12, max_files = n_entries - 1L)
r_big <- dsapp_archive_extract("bundle.zip", ex_ws_sid, cfg_tiny)
chk(sprintf("★ 超过条目数上限时拒绝（%s）", r_big$msg),
    !isTRUE(r_big$ok) && grepl("条目", r_big$msg))

cfg_tiny2 <- cfg
cfg_tiny2$extract <- list(max_bytes = 1, max_files = 1e6)
r_big2 <- dsapp_archive_extract("bundle.zip", ex_ws_sid, cfg_tiny2)
chk(sprintf("★ 超过体积上限时拒绝（%s）", r_big2$msg),
    !isTRUE(r_big2$ok) && grepl("上限", r_big2$msg))

# ---- 没有对话 / 不是压缩包 ----
chk("★ 没打开对话时明确说要先开对话，而不是解到某个默认目录",
    {
      r <- dsapp_archive_extract("bundle.zip", NULL, cfg)
      !isTRUE(r$ok) && grepl("对话", r$msg)
    })
chk("不是压缩包时给的是人话",
    {
      r <- dsapp_archive_extract("expr.csv", ex_ws_sid, cfg)
      !isTRUE(r$ok) && !grepl("Error|error", r$msg)
    })
chk("压缩包不存在时不会抛异常",
    {
      r <- dsapp_archive_extract("没有这个包.zip", ex_ws_sid, cfg)
      !isTRUE(r$ok)
    })
chk("压缩包在文件类型里是 archive（不是 binary，否则界面只让下载）",
    identical(dsapp_file_kind("bundle.zip"), "archive") &&
    identical(dsapp_file_kind("x.tar.gz"), "archive") &&
    identical(dsapp_file_kind("expr.csv.gz"), "binary"))

# ===========================================================================
# 产物缩略图（V5 item 1：图要直接出现在对话里）
# ===========================================================================
cat("\n== 产物缩略图 ==\n")

# MIME 猜错的后果不是报错，是浏览器把图当二进制流下载 —— 对话里留一块空白。
# 所以这里逐条钉死，尤其是 svg（"image/svg" 是错的，必须 image/svg+xml）。
chk("png 的 MIME", identical(dsapp_image_mime("volcano.png"), "image/png"))
chk("jpg/jpeg 都是 image/jpeg",
    identical(dsapp_image_mime("a.jpg"), "image/jpeg") &&
      identical(dsapp_image_mime("a.JPEG"), "image/jpeg"))
chk("★ svg 的 MIME 是 image/svg+xml（不是 image/svg）",
    identical(dsapp_image_mime("umap.svg"), "image/svg+xml"))
chk("认不出来的扩展名不给一个假的图片类型",
    identical(dsapp_image_mime("expr.csv"), "application/octet-stream"))

# 缩略图只挑 kind == "image" 的产物，而 kind 是 dsapp_file_kind 给的 ——
# 这两处判断必须一致，否则界面上会出现"有缩略图槽位但取不到文件"的空框。
chk("dsapp_file_kind 认得这些图片扩展名（缩略图靠它筛）",
    all(vapply(c("a.png", "a.jpg", "a.jpeg", "a.gif", "a.bmp", "a.webp", "a.svg"),
               function(f) identical(dsapp_file_kind(f), "image"), logical(1))))
chk("★ 非图片不会被当成图片（pdf 尤其容易混进来）",
    !any(vapply(c("a.pdf", "a.csv", "a.rds", "a.txt", "a.zip"),
                function(f) identical(dsapp_file_kind(f), "image"), logical(1))))

# 挑图：UI 和渲染函数共用这一个函数。挑错的表现是界面上一个空框，
# 不报错、不写日志，所以这里逐条钉。
mk_art <- function(name, kind, size) data.frame(name = name, kind = kind,
                                                size = size, stringsAsFactors = FALSE)
art_mix <- mk_art(c("volcano.png", "umap.svg", "expr.csv", "heat.png"),
                  c("image", "image", "table", "image"),
                  c(1e5, 2e5, 1e3, 2e6))
chk("只挑图片，顺序照原样（槽位号靠它对齐）",
    identical(dsapp_thumb_pick(art_mix), c("volcano.png", "umap.svg", "heat.png")))
chk("没有产物时不挑出任何东西",
    length(dsapp_thumb_pick(mk_art(character(0), character(0), numeric(0)))) == 0)
chk("★ 空 df 不报错（新对话每 3 秒就会走一次这条路）",
    length(dsapp_thumb_pick(data.frame())) == 0)
chk("缺列不报错（宁可不出图，也不能让对话页整块渲染不出来）",
    length(dsapp_thumb_pick(data.frame(a = 1, b = 2))) == 0)

# 大小上限：Shiny 的 fileUrl 是把整张图读进内存再 base64 的，主进程
# 所有访客共用，一张几十兆的图能把整个应用拖垮 —— 炸的是别人的会话。
chk("★ 超过上限的图不给缩略图（保护主进程，不是省流量）",
    identical(dsapp_thumb_pick(
      mk_art(c("big.png", "ok.png"), c("image", "image"),
             c(DSAPP_THUMB_MAX_BYTES + 1, DSAPP_THUMB_MAX_BYTES))),
      "ok.png"))
chk("★ 被略过的图会被单独点出来（界面上要如实说一句）",
    identical(dsapp_thumb_too_big(
      mk_art(c("big.png", "ok.png"), c("image", "image"),
             c(DSAPP_THUMB_MAX_BYTES + 1, DSAPP_THUMB_MAX_BYTES))),
      "big.png"))
chk("上限之内的图不算「太大」",
    length(dsapp_thumb_too_big(art_mix)) == 0)
chk("非图片再大也不算「太大」（那是另一条路，不该在缩略图这里提示）",
    length(dsapp_thumb_too_big(
      mk_art("expr.csv", "table", DSAPP_THUMB_MAX_BYTES * 10))) == 0)
chk("槽位上限生效（注册了几个槽就只能出几张）",
    length(dsapp_thumb_pick(
      mk_art(paste0("p", 1:9, ".png"), rep("image", 9), rep(1e4, 9)),
      n_max = 4L)) == 4)
chk("★ 挑图顺序在截断前后一致（截的是前缀，槽位才不错位）",
    identical(dsapp_thumb_pick(
      mk_art(paste0("p", 1:9, ".png"), rep("image", 9), rep(1e4, 9)), 4L),
      paste0("p", 1:4, ".png")))

# ---------------------------------------------------------------------------
section("token 用量")

# 每条断言都对应一个"会在真实使用中静默给错数字"的场景 —— 用量统计最糟的
# 失败方式不是报错，是**照常显示一个错的数**，没人会去核对账单。
ucon <- dsapp_db(cfg)
mk_usage <- function(p = NULL, c = NULL, t = NULL) {
  l <- list()
  if (!is.null(p)) l$prompt_tokens <- p
  if (!is.null(c)) l$completion_tokens <- c
  if (!is.null(t)) l$total_tokens <- t
  l
}

# 厂商不报用量时不写行。写一行全 NULL 的记录，管理页合计就变成"用了 0 个
# token"—— 一个理直气壮的假数字，比空白更糟（同一理由见 dsapp_usage_text）。
chk("★ 厂商不给用量时不写行（不能记成 0）",
    isFALSE(db_usage_add(1L, "s-x", mk_usage(), con = ucon)))
chk("usage 是 NULL 同样不写行",
    isFALSE(db_usage_add(1L, "s-x", NULL, con = ucon)))
chk("确实一行都没写进去",
    DBI::dbGetQuery(ucon, "SELECT COUNT(*) AS n FROM usage_log")$n[[1]] == 0)

chk("正常一轮会写进去",
    isTRUE(db_usage_add(1L, "s-a", mk_usage(100, 20, 120),
                        scene = "chat", model = "m1", con = ucon)))
chk("只给 total 的一轮也写（有的厂商只报总数）",
    isTRUE(db_usage_add(1L, "s-a", mk_usage(t = 50),
                        scene = "agent", model = "m1", con = ucon)))
chk("另一个账号的一轮",
    isTRUE(db_usage_add(2L, "s-b", mk_usage(7, 3, 10),
                        scene = "chat", model = "m2", con = ucon)))

bu <- db_usage_by_user(con = ucon)
chk("按账号分开聚合（两个人不会并成一行）", nrow(bu) == 2)
u1 <- bu[bu$user_id == 1, , drop = FALSE]
u2 <- bu[bu$user_id == 2, , drop = FALSE]
chk("★ 账号 1 合计 170（120 + 50）", identical(as.numeric(u1$total), 170))
chk("轮数也数对了", identical(as.integer(u1$n_calls), 2L))
chk("账号 2 只有自己的 10", identical(as.numeric(u2$total), 10))

# 只有 total 的那一轮 prompt/completion 是 NULL。SQLite 的 SUM 会跳过 NULL，
# 但写成裸 SUM(prompt_tokens) 之后，只要哪天有人把聚合换成 R 里的 sum()，
# 整列立刻变 NA —— 而 NA 在页面上会被格式化成"—"，看起来只是"没数据"。
chk("★ 缺字段的轮次不会把整列污染成 NA",
    !is.na(u1$prompt[[1]]) && !is.na(u1$completion[[1]]))
chk("缺字段的那部分按 0 计（不是丢掉整轮）",
    identical(as.numeric(u1$prompt), 100) &&
      identical(as.numeric(u1$completion), 20))

bd <- db_usage_by_day(14, con = ucon)
chk("按天聚合有结果", !is.null(bd) && nrow(bd) >= 1)
chk("★ 日期列是 YYYY-MM-DD（管理页直接显示它）",
    all(grepl("^\\d{4}-\\d{2}-\\d{2}$", bd$day)))
chk("按天合计与按账号合计对得上",
    identical(as.numeric(sum(bd$total)), 180))
chk("按天里人数去重了（3 轮、2 个人）",
    identical(as.integer(sum(bd$n_users)), 2L))

chk("单账号累计 170", identical(db_usage_user_total(1L, con = ucon), 170))
chk("★ 从没用过的账号返回 0 而不是 NA（配额判断靠它）",
    identical(db_usage_user_total(999L, con = ucon), 0))
chk("user_id 为 NULL 时返回 0（不报错、也不返回全站数字）",
    identical(db_usage_user_total(NULL, con = ucon), 0))

ps <- dsapp_platform_stats(cfg, con = ucon)
chk("平台统计里有累计 token", identical(as.numeric(ps$tokens_total), 180))
chk("平台统计里有生成轮数", identical(as.integer(ps$n_llm), 3L))

# 管理页要 join 用户表拿昵称。账号被删了之后 usage_log 里的行还在
# （这是刻意的：账单不该随账号消失），这时不能报错，要显示成"已删除的账号"。
chk("★ 账号被删之后用量行仍然读得出来（不 join 用户表也能聚合）",
    isTRUE(db_usage_add(4242L, "s-gone", mk_usage(t = 5), con = ucon)) &&
      is.null(dsapp_user_by_id(4242L, con = ucon)) &&
      4242L %in% db_usage_by_user(con = ucon)$user_id)

# 写用量失败不能连带毁掉那一轮回复 —— 调用点用 tryCatch 包着，
# 这里验证"库坏了"这条路径确实抛的是可捕获的 R 条件而不是让进程崩掉。
try(DBI::dbDisconnect(ucon), silent = TRUE)
chk("★ 库断了时抛的是可捕获的错误（调用方 tryCatch 得住）",
    inherits(tryCatch(db_usage_add(1L, "s-a", mk_usage(t = 1), con = ucon),
                      error = function(e) e), "error"))
# 断掉的连接要清掉，否则后面 dsapp_db() 会一直还这个失效对象
st <- dsapp_state(); st$db <- NULL

# ---------------------------------------------------------------------------
section("登录节流")

# 这一节的每一条都关于"锁错了人"或"锁不住人" —— 两种都比没有节流更糟：
# 前者把账号主人挡在门外（而攻击者换个邮箱继续），后者给人一个安全的错觉。
lcon <- dsapp_db(cfg)
Sys.setenv(DSAPP_LOGIN_MAX_FAIL = "3", DSAPP_LOGIN_LOCK_SEC = "900",
           DSAPP_LOGIN_WINDOW_SEC = "900")

em_pw  <- "pw@x.com"      # 设了密码的账号
em_open <- "open@x.com"   # 没设密码的账号
for (e in c(em_pw, em_open)) invisible(DBI::dbExecute(lcon, "DELETE FROM login_fail WHERE email = ?", params = list(e)))
invisible(try(DBI::dbExecute(lcon, "DELETE FROM users WHERE email IN (?, ?)",
                   params = list(em_pw, em_open)), silent = TRUE))
invisible(dsapp_user_create("有密码", em_pw, "13800000001", "RNA", "secret123",
                            "secret123", con = lcon))
# ★ V13.1 item 7：这个账号现在**建不出来**了 —— dsapp_user_validate 必填密码，
#   传空串会返回 ok=FALSE。但"库里躺着一个 pass_hash='' 的账号"恰恰是这一节
#   要防的东西（V13.1 之前注册的账号全是这样），所以用 mk_legacy_nopw()
#   直接 INSERT 一个，模拟老库升级上来的真实形态。
invisible(try(DBI::dbExecute(lcon, "DELETE FROM users WHERE email = ?",
                             params = list(em_open)), silent = TRUE))
invisible(mk_legacy_nopw(em_open, lcon, "没密码"))
chk("（前置）造出来的确实是一个没有密码的老账号",
    identical(DBI::dbGetQuery(lcon, "SELECT pass_hash FROM users WHERE email = ?",
                              params = list(em_open))$pass_hash[[1]], ""))

chk("没被锁时 locked 是 FALSE", isFALSE(dsapp_login_locked(em_pw, lcon)$locked))

# 前 max_fail - 1 次只是提示，不该锁 —— 真人打错两三次很常见。
f1 <- dsapp_login_fail(em_pw, lcon)
f2 <- dsapp_login_fail(em_pw, lcon)
chk("第一次失败不锁", isFALSE(f1$locked))
chk("★ 未锁时会告诉用户还能试几次（f1 还有 2 次）", identical(f1$left, 2L))
chk("第二次失败还不锁，剩 1 次", isFALSE(f2$locked) && identical(f2$left, 1L))

f3 <- dsapp_login_fail(em_pw, lcon)
chk("★ 到第 max_fail 次才锁（不是提前一次）", isTRUE(f3$locked))

lk <- dsapp_login_locked(em_pw, lcon)
chk("★ 锁上之后 locked=TRUE", isTRUE(lk$locked))
chk("剩余时间在 (0, 900] 秒之间（页面按它算分钟）",
    lk$secs > 0 && lk$secs <= 900)

# 锁定期间**即使密码是对的**也不放行 —— 这正是锁的意义：攻击者手里
# 可能正好是那个猜中的密码，此时放行等于没锁。
a_locked <- dsapp_user_auth(em_pw, "secret123", con = lcon)
chk("★ 锁定期间正确的密码也进不去（否则锁等于没锁）", isFALSE(a_locked$ok))
chk("★ 被锁时给的是锁定提示，不是「密码不对」",
    grepl("锁定", a_locked$msg %||% "", fixed = TRUE))
chk("被锁时提示里带了解锁办法（找管理员）",
    grepl("管理员", a_locked$msg %||% "", fixed = TRUE))

# 恢复码那条路也要拦：恢复码印在屏幕上，可能被抄走或转发。
tk_locked <- dsapp_user_auth_token(em_pw,
  dsapp_user_by_email(em_pw, lcon)$token, con = lcon)
chk("★ 被锁之后恢复码登录同样进不去（两条路都要拦）",
    isFALSE(tk_locked$ok))

# 没设密码的账号（V13.1 之前注册的存量账号）：
# V13.0 及以前这里是"不能被锁"—— 因为密码留空就能进，锁它拦不住攻击者，
# 只会把账号主人挡在外面。V13.1 item 7 把免密登录整条取消之后，这条推理
# 反过来了：**没有密码 = 谁都进不去**，所以既不用锁、也不该锁 ——
# 锁它只会给主人一句"你被锁了"，而真正的原因（这个账号压根没有密码）
# 就再也说不出口了。所以：无密码 → 无条件拒绝，且**先于**锁定检查。
for (i in 1:5) invisible(dsapp_login_fail(em_open, lcon))
chk("★ 没设密码的账号：填什么都进不去（免密登录已在 V13.1 取消）", {
  a <- dsapp_user_auth(em_open, "", con = lcon)
  isFALSE(a$ok)
})
chk("★ 而且理由说的是「没有密码」，不是「被锁了」", {
  # 这一条是**顺序**测试：上面刚给 em_open 计了 5 次失败，它现在是"被锁"状态。
  # 如果实现里锁定检查排在了无密码检查前面，用户会看到"账号已锁定，请稍后再试"
  # —— 然后他等一辈子也进不去，因为真正的问题是这账号根本没有密码。
  a <- dsapp_user_auth(em_open, "", con = lcon)
  m <- a$msg %||% ""
  grepl("密码", m) && !grepl("锁定", m)
})
chk("★ 给没密码的账号填了密码 → 照样拒绝，而且**不计数**", {
  # 不计数是对的：无密码账号没有可爆破的凭据，试一万次也不会变得更不安全。
  # 计了反而会在管理页堆出一堆"被锁账号"，掩盖真正需要处理的账号。
  before <- dsapp_login_row(em_open, lcon)$n_fail
  r <- dsapp_user_auth(em_open, "whatever", con = lcon)
  after <- dsapp_login_row(em_open, lcon)$n_fail
  isFALSE(r$ok) && identical(as.integer(before), as.integer(after))
})
chk("★ 无密码账号的唯一自助出口是恢复码（那不是免密，是真凭据）", {
  # 恢复码这条路**也**受锁定管辖（见上面 em_pw 那条），所以先解锁 ——
  # 这也正是界面上给这类用户的出路：管理员解锁 / 用恢复码进来自设密码。
  invisible(dsapp_login_unlock(em_open, con = lcon))
  isTRUE(dsapp_user_auth_token(em_open,
    dsapp_user_by_email(em_open, lcon)$token, con = lcon)$ok)
})

# 成功登录要把计数清零，否则一个"偶尔手滑"的用户会长期顶着锁定倒计时。
invisible(dsapp_login_fail(em_pw, lcon))
invisible(dsapp_login_fail(em_pw, lcon))
invisible(DBI::dbExecute(lcon, "DELETE FROM login_fail WHERE email = ?", params = list(em_pw)))
chk("成功登录后计数行被清掉（不留下半截计数）",
    is.null(dsapp_login_row(em_pw, lcon)))

# 窗口：隔得比 window_sec 更久再错一次，要从 1 重新数。
invisible(DBI::dbExecute(lcon, "DELETE FROM login_fail WHERE email = ?", params = list(em_pw)))
invisible(dsapp_login_fail(em_pw, lcon))
invisible(dsapp_login_fail(em_pw, lcon))
invisible(DBI::dbExecute(lcon,
  "UPDATE login_fail SET last_at = ? WHERE email = ?",
  params = list(format(as.POSIXct(dsapp_now(), tz = "UTC") - 7200,
                       "%Y-%m-%d %H:%M:%S", tz = "UTC"), em_pw)))
f_again <- dsapp_login_fail(em_pw, lcon)
chk("★ 窗口外的旧失败不累计（三个月里错 3 次不该锁）",
    identical(f_again$n, 1L) && isFALSE(f_again$locked))

# 不存在的邮箱也计数：不记的话这个表单就是免费的账号枚举器。
invisible(DBI::dbExecute(lcon, "DELETE FROM login_fail WHERE email = ?",
               params = list("ghost@x.com")))
g <- dsapp_user_auth("ghost@x.com", "x", con = lcon)
chk("不存在的邮箱：第一次失败不锁", isFALSE(g$ok))
for (i in 1:2) invisible(dsapp_login_fail("ghost@x.com", lcon))
g2 <- dsapp_user_auth("ghost@x.com", "x", con = lcon)
chk("★ 不存在的邮箱反复试也会被挡住（挡住账号枚举）",
    grepl("锁定", g2$msg %||% "", fixed = TRUE))
chk("★ 错别人的邮箱锁不到自己（按邮箱分别计数）", {
  # 用 em_pw 探：它此刻计数为 1（上一段窗口测试留下的），没被锁。
  # ⚠️ V13.1 之前这里探的是 em_open（无密码账号，空密码必进）。那条路已经
  #    没了 —— 无密码账号现在**永远**进不去，拿它探什么都测不出来。
  r <- dsapp_user_auth(em_pw, "secret123", con = lcon)
  isTRUE(r$ok)
})

# 管理页
locks <- dsapp_login_locks(con = lcon)
chk("管理页能列出被锁的账号", !is.null(locks) && nrow(locks) >= 1)
chk("列出来的是邮箱", "email" %in% names(locks))
chk("★ 解锁之后立刻能进（管理员不用改数据库）", {
  invisible(dsapp_login_unlock(em_pw, con = lcon))
  isTRUE(dsapp_user_auth(em_pw, "secret123", con = lcon)$ok)
})
chk("全部解锁清空列表", {
  invisible(dsapp_login_unlock(NULL, con = lcon))
  is.null(dsapp_login_locks(con = lcon))
})

# 失败提示的拼装：三处共用一个函数，抽出来就是为了这里能一次验完。
chk("★ 提示里带剩余次数",
    grepl("还可以试 4 次",
          dsapp_login_fail_msg("密码不对",
                               list(locked = FALSE, left = 4L, n = 4L,
                                    secs = 0)), fixed = TRUE))
chk("★ 锁定提示按分钟说，不是甩一个秒数给用户",
    grepl("15 分钟",
          dsapp_login_fail_msg("密码不对",
                               list(locked = TRUE, left = 0L, n = 8L,
                                    secs = 900)), fixed = TRUE))
chk("剩余次数为 0 时不显示「还可以试 0 次」",
    !grepl("还可以试",
           dsapp_login_fail_msg("密码不对",
                                list(locked = FALSE, left = 0L, n = 8L,
                                     secs = 0)), fixed = TRUE))

Sys.unsetenv(c("DSAPP_LOGIN_MAX_FAIL", "DSAPP_LOGIN_LOCK_SEC",
               "DSAPP_LOGIN_WINDOW_SEC"))

# ---------------------------------------------------------------------------
section("操作审计日志")

# 这一节的每一条都在问同一个问题：**出事后翻日志，能不能查出是谁干的。**
# 所以检查的重点不是"函数返回了 TRUE"，而是"那一行真的躺在库里、字段对"。
acon <- dsapp_db(cfg)
invisible(try(DBI::dbExecute(acon, "DELETE FROM audit_log"), silent = TRUE))
au_rows <- function() DBI::dbGetQuery(acon,
  "SELECT * FROM audit_log ORDER BY id")
au_reset <- function() invisible(try(DBI::dbExecute(acon,
  "DELETE FROM audit_log"), silent = TRUE))

au_reset()
invisible(dsapp_audit("login", user_id = 1L, target = "a@x.com",
                      detail = "测试", cfg = cfg, con = acon))
r <- au_rows()
chk("★ 记一条就真的落库了（不是只返回 TRUE）", nrow(r) == 1)
chk("动作码存的是原样，不是标签", identical(r$action[1], "login"))
chk("user_id 存进去了", identical(as.integer(r$user_id[1]), 1L))
chk("ok 默认是 1（成功）", identical(as.integer(r$ok[1]), 1L))
chk("at 是 UTC 时间戳", grepl("^\\d{4}-\\d{2}-\\d{2} ", r$at[1]))

# ★ 只给 user_id、不给 user 行时，邮箱要**当场**查出来写进去。
#   等以后账号被删了再查就查不到了，而 emil 列的全部意义就是那一刻。
au_reset()
u1 <- dsapp_user_by_email(em_pw, acon)
invisible(dsapp_audit("login", user_id = u1$id, cfg = cfg, con = acon))
chk("★ 只给 user_id 时邮箱会当场补上（删号后仍能认出是谁）",
    identical(au_rows()$email[1], em_pw))

# 账号删掉之后，日志行必须还在 —— 这是"user_id 上不加外键 + 冗余 email"
# 两条设计的全部理由。
n_before <- nrow(au_rows())
invisible(try(DBI::dbExecute(acon, "DELETE FROM users WHERE id = ?",
                             params = list(as.integer(u1$id))), silent = TRUE))
r <- au_rows()
chk("★ 账号被删后日志行还在", nrow(r) == n_before)
chk("★ 而且还能看出是谁（email 没跟着没）", em_pw %in% r$email)
invisible(try(DBI::dbExecute(acon, "DELETE FROM audit_log"), silent = TRUE))

# 写日志失败不能把主操作带下去。这里用一个已经关掉的连接模拟"库不可用"。
dead <- DBI::dbConnect(RSQLite::SQLite(), tempfile(fileext = ".sqlite3"))
DBI::dbDisconnect(dead)
chk("★ 库不可用时 dsapp_audit 返回 FALSE 而不是抛异常（审计是旁路）",
    isFALSE(dsapp_audit("login", user_id = 1L, con = dead)))
chk("★ 主操作不会被它带崩：调用方拿到的是 FALSE，不是 error",
    !inherits(tryCatch(dsapp_audit("x", con = dead),
                       error = function(e) e), "error"))

# ---- 登录/注册/改密这些动作真的会写日志 ----
#
# 前面只验了 dsapp_audit 本身；这里验的是**接线**——users.R 里那些函数
# 有没有真的调它。接错线（比如只在成功那一路记）不会报错，只会让日志
# 缺最关键的那几行。
au_reset()
em_au <- "audit@x.com"
invisible(try(DBI::dbExecute(acon, "DELETE FROM users WHERE email = ?",
                             params = list(em_au)), silent = TRUE))
invisible(dsapp_user_create("审计", em_au, "13800000003", "RNA", "pw123456",
                            "pw123456", con = acon))
chk("注册记了一条 register",
    any(au_rows()$action == "register" & au_rows()$email == em_au))

au_reset()
invisible(dsapp_user_auth(em_au, "错的", con = acon))
r <- au_rows()
chk("★ 登录失败记了 login_fail（暴力破解的线索全靠它）",
    nrow(r) == 1 && identical(r$action[1], "login_fail"))
chk("失败的 ok 是 0", identical(as.integer(r$ok[1]), 0L))
chk("失败原因进了 detail", nzchar(r$detail[1]))

au_reset()
invisible(dsapp_user_auth(em_au, "pw123456", con = acon))
r <- au_rows()
chk("登录成功记的是 login（不是 login_fail）",
    nrow(r) == 1 && identical(r$action[1], "login"))
chk("★ 成功的登录不记密码、不记任何内容", !any(grepl("pw123456", unlist(r))))

# ★ 恢复码那条路要能和密码那条路分开：事后查"他是怎么进来的"时，
#   两者对应的风险完全不同。
au_reset()
invisible(dsapp_user_auth_token(em_au,
  as.character(dsapp_user_by_email(em_au, acon)$token), con = acon))
chk("★ 恢复码登录记的是 login_token（和密码登录分开）",
    identical(au_rows()$action[1], "login_token"))

# 改密码：成功、失败各一条，而且 detail 要能分辨"凭旧密码改的"和
# "用恢复码验证后改的"——后者绕过了一道检查，是审计上更该留痕的。
au_reset()
invisible(dsapp_user_set_password(
  as.integer(dsapp_user_by_email(em_au, acon)$id), "newpw123",
  old_password = "错的", con = acon))
chk("改密失败记 pw_fail", identical(au_rows()$action[1], "pw_fail"))

au_reset()
invisible(dsapp_user_set_password(
  as.integer(dsapp_user_by_email(em_au, acon)$id), "newpw123",
  old_password = "pw123456", con = acon))
r <- au_rows()
chk("改密成功记 pw_set", identical(r$action[1], "pw_set"))
chk("★ detail 说明了是怎么改的（凭旧密码 / 恢复码 / 首次设置）",
    grepl("凭当前密码", r$detail[1], fixed = TRUE))

au_reset()
invisible(dsapp_user_set_password(
  as.integer(dsapp_user_by_email(em_au, acon)$id), "newpw456",
  skip_old_check = TRUE, con = acon))
chk("★ 用恢复码跳过旧密码校验那条路，日志里看得出来",
    grepl("恢复码", au_rows()$detail[1], fixed = TRUE))

# 没设密码的老账号被拒这件事**必须留痕**。
# V13.1 之前这里测的是"凭邮箱进入也记一条 login"（免密那条路）。那条路没了，
# 但留痕的要求没变，反而更要紧：现在这类账号**一律进不去**，用户看到的只有
# 一句话，管理员事后要能查到"这个人今天试过、被挡在密码这一关"，才知道
# 该去给他重置密码，而不是让他自己反复试。
au_reset()
em_open2 <- "audit_open@x.com"
invisible(try(DBI::dbExecute(acon, "DELETE FROM users WHERE email = ?",
                             params = list(em_open2)), silent = TRUE))
# 同上：这种账号现在**建不出来**，只能直接 INSERT 模拟老库升级上来的形态。
invisible(mk_legacy_nopw(em_open2, acon, "无密码"))
au_reset()
invisible(dsapp_user_auth(em_open2, "", con = acon))
chk("★ 无密码账号被拒也记了一条，而且是 login_fail 不是 login",
    identical(au_rows()$action[1], "login_fail") &&
      identical(as.integer(au_rows()$ok[1]), 0L))
chk("★ 那条记录说清了拒绝的原因是「没有密码」（管理员据此才知道该做什么）",
    grepl("密码", au_rows()$detail[1] %||% ""))

# ---- 查询与筛选 ----
au_reset()
for (i in 1:7) {
  invisible(dsapp_audit(if (i %% 2 == 0) "file_upload" else "login",
                        user_id = if (i <= 4) 1L else 2L,
                        target = sprintf("f%d.csv", i),
                        ok = i != 3, cfg = cfg, con = acon))
}
q <- dsapp_audit_list(con = acon)
chk("不带条件时按时间**倒序**返回（最新的在最上面）",
    nrow(q) == 7 && identical(q$target[1], "f7.csv"))
chk("按账号筛", nrow(dsapp_audit_list(user_id = 1L, con = acon)) == 4)
chk("按动作筛", nrow(dsapp_audit_list(action = "file_upload", con = acon)) == 3)
chk("按多个动作筛", nrow(dsapp_audit_list(
  action = c("login", "file_upload"), con = acon)) == 7)
chk("★ 只看失败", {
  f <- dsapp_audit_list(only_fail = TRUE, con = acon)
  nrow(f) == 1 && identical(as.integer(f$ok[1]), 0L)
})
chk("关键词能匹配对象名", nrow(dsapp_audit_list(keyword = "f5", con = acon)) == 1)
chk("关键词能匹配邮箱", nrow(dsapp_audit_list(keyword = "f", con = acon)) == 7)
chk("★ 关键词匹配不到就是空集，不是全表", nrow(dsapp_audit_list(
  keyword = "绝不可能出现的字符串", con = acon)) == 0)
chk("limit 生效", nrow(dsapp_audit_list(limit = 3L, con = acon)) == 3)
chk("★ limit 有硬上限（防止一次把几十万行读进内存）", {
  q <- dsapp_audit_list(limit = 999999L, con = acon)
  nrow(q) == 7      # 数据只有 7 行，这里验的是它没有报错也没有全表扫
})
chk("days 筛掉太老的", {
  invisible(DBI::dbExecute(acon,
    "UPDATE audit_log SET at = '2020-01-01 00:00:00' WHERE target = 'f1.csv'"))
  q <- dsapp_audit_list(days = 7, con = acon)
  !("f1.csv" %in% q$target)
})
chk("days = NULL 时不过滤", "f1.csv" %in% dsapp_audit_list(con = acon)$target)

chk("★ 日志里出现过的动作能取出来（筛选下拉用）", {
  a <- dsapp_audit_actions(con = acon)
  all(c("login", "file_upload") %in% a)
})
chk("★ 动作码能翻成中文标签", identical(dsapp_audit_label("file_upload"),
                                        "上传文件"))
chk("★ 不认识的码原样显示（老日志不会变成空白）",
    identical(dsapp_audit_label("something_new"), "something_new"))

chk("统计里的失败条数对得上", {
  st <- dsapp_audit_stats(con = acon)
  identical(as.integer(st$total), 7L) && identical(as.integer(st$failed), 1L)
})

# ---- 保留期 ----
