# ---------------------------------------------------------------------------
section("远程节点名册")

# 这一节的重点是**凭据不落盘**和**不越权**。前者是用户反复强调过的要求，
# 后者是 id 用自增整数带来的必然问题：猜中别人的节点号就能读到别人的
# 机器名单（凭据不在库里，但"谁在用哪台服务器"本身就是信息）。
ncon <- dsapp_db(cfg)
invisible(try(DBI::dbExecute(ncon, "DELETE FROM ssh_nodes"), silent = TRUE))

nd1 <- list(name = "实验室 4090", host = "10.0.0.5", port = 2222,
            username = "bob", auth = "key", workdir = "~/runs",
            activate = "source ~/miniconda3/bin/activate bio",
            password = "", key_text = "-----BEGIN OPENSSH PRIVATE KEY-----\nSECRET\n")

r1 <- dsapp_node_save(1L, nd1, con = ncon)
chk("能保存一个节点", isTRUE(r1$ok))
chk("★ 第一个节点自动成为默认（不然界面永远没有默认项）",
    isTRUE(dsapp_node_get(r1$id, 1L, ncon)$is_default == 1L))

# 最关键的一条：凭据绝不能进库。这里直接扫全表所有文本列，
# 而不是只检查某几个列名 —— 以后有人加一列 "pass_hint" 也会被抓住。
row_txt <- paste(unlist(DBI::dbGetQuery(ncon,
  "SELECT * FROM ssh_nodes WHERE id = ?", params = list(r1$id))), collapse = "\n")
chk("★ 私钥原文没有写进数据库", !grepl("SECRET", row_txt, fixed = TRUE))
chk("★ 表里没有 pass/key/secret 之类的列（新增列也会被这条抓住）",
    !any(grepl("pass|key|secret|token|cred", names(
      DBI::dbGetQuery(ncon, "SELECT * FROM ssh_nodes LIMIT 1")),
      ignore.case = TRUE)))

# 机器身份该存的都存了 —— 名册的价值就在这里。
g <- dsapp_node_get(r1$id, 1L, ncon)
chk("主机名存下来了", identical(g$host, "10.0.0.5"))
chk("非默认端口存下来了（22 之外最容易丢）", identical(as.integer(g$port), 2222L))
chk("用户名存下来了", identical(g$username, "bob"))
chk("认证方式存下来了（决定载入后要填密码还是私钥）",
    identical(g$auth, "key"))
chk("远程工作目录存下来了", identical(g$workdir, "~/runs"))
chk("激活命令存下来了", identical(g$activate,
                                   "source ~/miniconda3/bin/activate bio"))

# 同名视为同一个节点：不然改完名字点保存会得到两个只差一个字的条目。
# ⚠️ 用 modifyList 而不是 c()：c(list(port=2222), list(port=22)) 得到的是
#    **两个** port 条目，$port 取第一个，于是"改成 22"根本没生效，
#    而测试还会以为自己在测更新。
 r1b <- dsapp_node_save(1L, utils::modifyList(nd1, list(port = 22)), con = ncon)
chk("★ 同名保存是更新而不是新增（免得攒出一堆近重名条目）",
    isTRUE(r1b$ok) && identical(as.integer(r1b$id), as.integer(r1$id)))
chk("更新确实写进去了", identical(as.integer(dsapp_node_get(r1$id, 1L, ncon)$port), 22L))
chk("★ 改动一个节点**不会**动它的默认标记（默认是显式选的）",
    isTRUE(dsapp_node_get(r1$id, 1L, ncon)$is_default == 1L))

# 越权：id 是自增整数，猜中别人的号就能读到别人的机器名单。
chk("★ 别人的节点读不到（带 user_id 过滤）",
    is.null(dsapp_node_get(r1$id, 2L, ncon)))
chk("★ 列表只列自己的", is.null(dsapp_nodes_list(2L, ncon)))
chk("★ 没登录（user_id = NULL）时列表为空，不是「所有人的」",
    is.null(dsapp_nodes_list(NULL, ncon)))
chk("★ 删不掉别人的节点", {
  invisible(dsapp_node_delete(r1$id, 2L, ncon))
  !is.null(dsapp_node_get(r1$id, 1L, ncon))
})
chk("★ 改不了别人的节点默认项", {
  invisible(dsapp_node_set_default(r1$id, 2L, ncon))
  isTRUE(dsapp_node_get(r1$id, 1L, ncon)$is_default == 1L)
})

# 第二个节点不会抢走默认位；显式设默认时**只会有一个**默认。
r2 <- dsapp_node_save(1L, list(name = "组里的集群", host = "hpc.lab.edu",
                               port = 22, username = "alice"), con = ncon)
chk("第二个节点不会自动变成默认",
    isTRUE(dsapp_node_get(r2$id, 1L, ncon)$is_default == 0L))
invisible(dsapp_node_set_default(r2$id, 1L, ncon))
dflt <- dsapp_nodes_list(1L, ncon)
chk("★ 任何时候只有一个默认项（两个都标默认，用户就不知道会载入哪个）",
    sum(as.integer(dflt$is_default)) == 1L)
chk("默认项确实换成了新的那个",
    identical(as.integer(dsapp_node_default(1L, ncon)$id), as.integer(r2$id)))
chk("列表按默认在前排序（界面第一行就是会用的那个）",
    identical(as.integer(dflt$id[[1]]), as.integer(r2$id)))

# 连通时间：让用户看得出"上次是什么时候连通的"。
chk("记录连通时间", {
  dsapp_node_touch_ok(r2$id, 1L, ncon)
  nzchar(dsapp_node_get(r2$id, 1L, ncon)$last_ok_at %||% "")
})

# 校验：这些是**安全**检查，不是格式检查 —— 每个字段都会拼进
# `ssh -p <port> <user>@<host>` 或远程 shell 命令里。
chk("★ 主机名里的空格被拒（能往 ssh 命令行里塞选项）",
    !is.null(dsapp_node_validate(list(name = "x", host = "evil -o ProxyCommand=sh",
                                      username = "u"))$error))
chk("★ 以横线开头的主机名被拒（会被当成选项）",
    !is.null(dsapp_node_validate(list(name = "x", host = "-oProxyCommand=x",
                                      username = "u"))$error))
chk("★ 用户名里的空格被拒",
    !is.null(dsapp_node_validate(list(name = "x", host = "h", username = "a b"))$error))
chk("★ 用户名里的 @ 被拒（会拼出 user@host@host）",
    !is.null(dsapp_node_validate(list(name = "x", host = "h", username = "a@b"))$error))
chk("★ 激活命令里的换行被拒（一条命令会变成两条）",
    !is.null(dsapp_node_validate(list(name = "x", host = "h", username = "u",
                                      activate = "a\nrm -rf /"))$error))
chk("端口越界被拒", !is.null(dsapp_node_validate(
  list(name = "x", host = "h", username = "u", port = 99999))$error))
chk("没名字被拒", !is.null(dsapp_node_validate(
  list(name = "", host = "h", username = "u"))$error))
chk("正常的 IPv6 地址能过", is.null(dsapp_node_validate(
  list(name = "x", host = "::1", username = "u", port = 22))$error))
chk("正常的主机名能过", is.null(dsapp_node_validate(
  list(name = "x", host = "hpc.lab.edu", username = "alice", port = 22))$error))

chk("★ 校验不过时不写库", {
  n_before <- nrow(dsapp_nodes_list(1L, ncon))
  bad <- dsapp_node_save(1L, list(name = "坏节点", host = "h h", username = "u"),
                         con = ncon)
  isFALSE(bad$ok) && nrow(dsapp_nodes_list(1L, ncon)) == n_before
})

# 节点 → 远程配置：转出来的结构要和设置页表单同构，否则 remote.R 读不到。
rem <- dsapp_node_to_remote(dsapp_node_get(r2$id, 1L, ncon))
chk("★ 转出来的远程配置字段齐（remote.R 直接读它）",
    all(c("host", "port", "user", "auth", "password", "key_text",
          "activate", "workdir") %in% names(rem)))
chk("★ 转出来的配置里凭据是空的（调用方从会话内存补）",
    identical(rem$password, "") && identical(rem$key_text, ""))
chk("username 映射成了 remote 认识的 user", identical(rem$user, "alice"))
chk("节点描述带上了端口（数据库行和转换后的配置都能喂给它）",
    grepl("alice@hpc.lab.edu:22", dsapp_node_label(rem), fixed = TRUE) &&
      grepl("alice@hpc.lab.edu:22",
            dsapp_node_label(dsapp_node_get(r2$id, 1L, ncon)), fixed = TRUE))

chk("删除自己的节点", {
  invisible(dsapp_node_delete(r2$id, 1L, ncon))
  is.null(dsapp_node_get(r2$id, 1L, ncon))
})
invisible(DBI::dbExecute(ncon, "DELETE FROM ssh_nodes"))

# ---------------------------------------------------------------------------
section("存储配额")

# 配额的失败方式有两种，都比"没有配额"更糟：
#   * 算少了 → 拦不住，磁盘照样满，而管理员以为已经管住了；
#   * 算多了 → 拦住了一个其实没超额的人，他看到的是自相矛盾的界面。
# 下面的断言分别盯这两头。核心手段是：**强制的算法和页面上显示的算法
# 必须是同一个函数**，这条用"两边读数一致"来验。
qcon <- ncon
quser <- 1L   # 复用上面注册过的账号 #1

chk("★ 没设配额时返回 0（0 = 不限，不是「一个字节都不许」）", {
  dsapp_user_set_quota(quser, 0, qcon)
  identical(dsapp_user_quota_bytes(quser, qcon), 0)
})
chk("★ 没设配额时任何上传都放行（默认不能挡住所有人）",
    isTRUE(dsapp_quota_check(quser, 10 * DSAPP_GB, cfg = cfg, con = qcon)$ok))

chk("设 1 GB 配额", {
  dsapp_user_set_quota(quser, 1, qcon)
  identical(as.numeric(dsapp_user_quota_bytes(quser, qcon)), as.numeric(DSAPP_GB))
})
chk("负数和 NA 都按不限处理（不留下一个「负配额」把账号锁死）", {
  dsapp_user_set_quota(quser, -5, qcon)
  a <- identical(dsapp_user_quota_bytes(quser, qcon), 0)
  dsapp_user_set_quota(quser, NA, qcon)
  b <- identical(dsapp_user_quota_bytes(quser, qcon), 0)
  a && b
})
chk("超过 1e6 GB 会被夹住（挡手滑多敲几个零）", {
  dsapp_user_set_quota(quser, 1e12, qcon)
  dsapp_user_quota_bytes(quser, qcon) == 1e6 * DSAPP_GB
})
chk("★ 没有这个账号时返回 0（不报错）",
    identical(dsapp_user_quota_bytes(999999L, qcon), 0))
chk("user_id 为 NULL 时返回 0（不越权成「全站不限」）",
    identical(dsapp_user_quota_bytes(NULL, qcon), 0))

# 现在用一个**很小**的配额来真的触发它。1 MB。
dsapp_user_set_quota(quser, 1 / 1024, qcon)   # 1 MB
chk("配额按 GB 换算对了（1/1024 GB = 1 MB）",
    abs(dsapp_user_quota_bytes(quser, qcon) - 1024^2) < 1)

used <- dsapp_quota_used(quser, cfg, qcon)
chk("能算出已用量（数值、非负）", is.numeric(used) && !is.na(used) && used >= 0)

# ---- 和页面上显示的口径必须一致 ----
dk <- dsapp_user_disk_usage(cfg, con = qcon)
dk_hit <- dk$bytes[match(quser, as.integer(dk$user_id))]
chk("★ 强制用的数字和「管理」页显示的数字出自同一口径",
    isTRUE(all.equal(used, as.numeric(dk_hit %||% 0), tolerance = 1e-6)))

# ---- 超了要拦 ----
q_over <- dsapp_quota_check(quser, 10 * 1024^2, what = "上传「big.bin」",
                            cfg = cfg, con = qcon)
chk("★ 明确超了要拒绝", isFALSE(q_over$ok))
chk("★ 拒绝的理由里要说清三件事：用了多少、上限多少、怎么办",
    grepl("已用", q_over$msg) && grepl("上限", q_over$msg) &&
      grepl("删掉", q_over$msg))
chk("理由里带上这次操作是什么（不然用户不知道是哪一步被拦的）",
    grepl("big.bin", q_over$msg, fixed = TRUE))
chk("★ 提示说的是「配额」而不是「磁盘满了」——两者该采取的行动不同",
    grepl("配额", q_over$msg) && !grepl("磁盘满", q_over$msg))

chk("刚好等于配额时放行（边界不能提前一格拦）", {
  left <- max(0, dsapp_user_quota_bytes(quser, qcon) - used)
  isTRUE(dsapp_quota_check(quser, left, cfg = cfg, con = qcon)$ok)
})
chk("★ 超出 1 个字节就拒绝（边界上不多不少）", {
  left <- max(0, dsapp_user_quota_bytes(quser, qcon) - used)
  isFALSE(dsapp_quota_check(quser, left + 1, cfg = cfg, con = qcon)$ok)
})

# ---- 第三道闸：已经超额时不许起新任务 ----
# incoming = 0 的那个调用就是"开始执行"这道闸的形状。
over_now <- dsapp_quota_check(quser, 0, what = "再跑一个任务",
                              cfg = cfg, con = qcon)
chk("★ 超额时「开始执行」这道闸会拦（incoming = 0）",
    isFALSE(over_now$ok) || used < dsapp_user_quota_bytes(quser, qcon))
chk("★ 已经超额时连 0 字节的新任务都拒绝", {
  # 把配额压到"比已用量还小"，制造"已经在配额之上"的状态
  dsapp_user_set_quota(quser, max(0, (used - 1)) / DSAPP_GB, qcon)
  q <- dsapp_quota_check(quser, 0, what = "再跑一个任务", cfg = cfg, con = qcon)
  isFALSE(q$ok) && grepl("已经在配额之上", q$msg)
})

# ---- 用量条 ----
chk("没配额时不显示用量条（不限的人看到条会以为自己也快满了）", {
