      identical(dsapp_session_role(7L, c(NA, 9L), 9L), "shared"))

chk("★★ shared 能看（不然共享就没意义）", isTRUE(dsapp_role_can_view("shared")))
chk("★★ shared 不能写（不然被共享的人能在 owner 的对话里跑代码、烧额度）",
    !isTRUE(dsapp_role_can_write("shared")))
chk("★ owner / admin 能看也能写", {
  all(vapply(c("owner", "admin"), dsapp_role_can_view, logical(1))) &&
    all(vapply(c("owner", "admin"), dsapp_role_can_write, logical(1)))
})
chk("★★ none 什么都不能（「看不到但改得动」是最糟的组合）", {
  !dsapp_role_can_view("none") && !dsapp_role_can_write("none")
})
chk("★ 空串 / NA / NULL 角色一律按无权处理（别默认放行）", {
  !dsapp_role_can_view("") && !dsapp_role_can_write("") &&
    !dsapp_role_can_view(NA_character_) && !dsapp_role_can_write(NA_character_) &&
    !dsapp_role_can_view(NULL) && !dsapp_role_can_write(NULL)
})

# ---- 真的建库跑一遍 ----
scon <- DBI::dbConnect(RSQLite::SQLite(), tempfile(fileext = ".sqlite3"))
dsapp_db_schema(scon)
sa <- mkuser("共享甲", "share-a@example.com", "13800000011", "RNA",
                        con = scon)
sb <- mkuser("共享乙", "share-b@example.com", "13800000012", "RNA",
                        con = scon)
sc <- mkuser("共享丙", "share-c@example.com", "13800000013", "RNA",
                        con = scon)
sid <- db_session_create("甲的对话", user_id = sa$user$id, con = scon)
db_message_add(sid, "user", "甲的私密问题", con = scon)
tid <- db_task_create("甲的任务", "print(1)", "r", session_id = sid, con = scon)

chk("★★ 还没共享时，乙看不了甲的对话",
    identical(db_session_role(sid, sb$user$id, con = scon), "none"))
chk("★★ 共享给乙之后，乙是 shared", {
  db_session_share_set(sid, sb$user$id, granted_by = sa$user$id, con = scon)
  identical(db_session_role(sid, sb$user$id, con = scon), "shared")
})
chk("★★ 共享给乙不会顺便让丙也能看（名单是名单，不是开关）", {
  identical(db_session_role(sid, sc$user$id, con = scon), "none")
})
chk("★ 甲自己始终是 owner（共享名单不影响归属）",
    identical(db_session_role(sid, sa$user$id, con = scon), "owner"))

# ⚠️ 授权行本身是**直接查库**验的。拿 db_sessions_list 当判据的话，
#    "写进去了"和"没写进去但恰好在别的路径上看得见"分不清。
s_rows <- function() DBI::dbGetQuery(scon,
  "SELECT user_id FROM session_share WHERE session_id = ?",
  params = list(sid))$user_id
chk("★ 授权行真的落库了", identical(as.integer(s_rows()), as.integer(sb$user$id)))
# 所有者不该被写进名单：他是 owner，判据在 sessions.user_id 上。写进去
# 只会让"这份名单"变成一句需要解释的话。
#
# ⚠️ 必须**把所有者混进输入名单**再验。只传乙的话，这个函数即使完全不做
#    owner 剔除也照样通过 —— 断言看着在验"名单里没有 owner"，实际验的是
#    "输入里没有 owner"。变异测试里就是这么漏过去的（把 setdiff 那行删掉，
#    全绿）。界面上"共享给自己"被前端排除了，但那是提示、不是闸门。
chk("★★ 所有者自己不会被写进共享名单（哪怕他自己出现在输入里）", {
  db_session_share_set(sid, c(sb$user$id, sa$user$id),
                       granted_by = sa$user$id, con = scon)
  !(as.integer(sa$user$id) %in% as.integer(s_rows())) &&
    identical(sort(as.integer(s_rows())), as.integer(sb$user$id))
})

chk("★★ 覆盖式写入：取消勾选 = 撤回（不是只能加不能减）", {
  db_session_share_set(sid, c(sb$user$id, sc$user$id), granted_by = sa$user$id,
                       con = scon)
  two <- setequal(as.integer(s_rows()), c(sb$user$id, sc$user$id))
  db_session_share_set(sid, sc$user$id, granted_by = sa$user$id, con = scon)
  two && identical(as.integer(s_rows()), as.integer(sc$user$id)) &&
    identical(db_session_role(sid, sb$user$id, con = scon), "none")
})
chk("★ 清空名单 = 撤回全部", {
  db_session_share_set(sid, character(0), granted_by = sa$user$id, con = scon)
  length(s_rows()) == 0 &&
    identical(db_session_role(sid, sc$user$id, con = scon), "none")
})

# ---- 列表：共享来的对话要出现在对方的列表里 ----
db_session_share_set(sid, sb$user$id, granted_by = sa$user$id, con = scon)
a_list <- db_sessions_list(user_id = sa$user$id, con = scon)
b_list <- db_sessions_list(user_id = sb$user$id, con = scon)
c_list <- db_sessions_list(user_id = sc$user$id, con = scon)
chk("★★ 共享给乙之后，这个对话出现在乙的列表里（不出现 = 用户以为共享没生效）",
    sid %in% b_list$id)
chk("★★ 丙的列表里没有它", !(sid %in% c_list$id))
chk("★★ 列表带 role 列，乙看到的是 shared、甲看到的是 owner", {
  "role" %in% names(b_list) && "role" %in% names(a_list) &&
    identical(as.character(b_list$role[match(sid, b_list$id)]), "shared") &&
    identical(as.character(a_list$role[match(sid, a_list$id)]), "owner")
})
# 共享来的对话要标出"这是谁的"，否则用户会以为自己建过一个同名的。
chk("★★ 共享来的对话带上了所有者的昵称",
    identical(as.character(b_list$owner_name[match(sid, b_list$id)]), "共享甲"))
chk("★ 三条取数路径都带 role / owner_name（漏一条就是界面上少一列）", {
  all3 <- list(db_sessions_list(user_id = sa$user$id, con = scon),
               db_sessions_list(all = TRUE, con = scon),
               db_sessions_list(con = scon))
  all(vapply(all3, function(d)
    all(c("role", "owner_name") %in% names(d)), logical(1)))
})
chk("★ 空 user_id 仍然是「什么都看不到」，不是「看到所有人的」",
    nrow(db_sessions_list(con = scon)) == 0)

# ---- 任务：共享对话里的任务也要列出来 ----
b_tasks <- db_tasks_list(user_id = sb$user$id, con = scon)
c_tasks <- db_tasks_list(user_id = sc$user$id, con = scon)
chk("★★ 共享对话里的任务出现在乙的任务页（共享最想看的恰恰是跑过什么）",
    tid %in% b_tasks$id)
chk("★★ 没被共享的丙看不到这条任务", !(tid %in% c_tasks$id))
chk("★★ 任务列表带 role 列，乙拿到的是 shared", {
  "role" %in% names(b_tasks) &&
    identical(as.character(b_tasks$role[match(tid, b_tasks$id)]), "shared")
})
chk("★ 三条取数路径都带 role（任务页要据此禁用重跑/删除）", {
  all3 <- list(db_tasks_list(user_id = sa$user$id, con = scon),
               db_tasks_list(all = TRUE, con = scon),
               db_tasks_list(con = scon))
  all(vapply(all3, function(d) "role" %in% names(d), logical(1)))
})

# ---- 撤回共享 / 删对话 ----
#
# ⚠️ 又是"删掉了没有"这一类断言，判据仍然必须**直接查库**：
#    db_session_role 先查 sessions，会话没了它恒返回 none ——
#    拿它验证"授权行被删干净了"是循环论证，"删了"和"留了一堆孤儿"长得一样。
s_orphans <- function() nrow(DBI::dbGetQuery(scon,
  "SELECT 1 FROM session_share WHERE session_id NOT IN (SELECT id FROM sessions)"))
chk("★★ 删对话会连共享授权行一起删（否则库里一直堆着看不见的授权）", {
  sid2 <- db_session_create("要删的对话", user_id = sa$user$id, con = scon)
  db_session_share_set(sid2, sb$user$id, granted_by = sa$user$id, con = scon)
  before <- nrow(DBI::dbGetQuery(scon,
    "SELECT 1 FROM session_share WHERE session_id = ?", params = list(sid2)))
  db_session_delete(sid2, con = scon)
  before == 1 && identical(s_orphans(), 0L)
})
chk("★ 删对话不会误伤别的对话的授权", {
  still <- nrow(DBI::dbGetQuery(scon,
    "SELECT 1 FROM session_share WHERE session_id = ?", params = list(sid)))
  still == 1 && identical(db_session_role(sid, sb$user$id, con = scon), "shared")
})
chk("★ 撤回之后乙立刻看不到（没有「导出过的旧副本」这回事）", {
  db_session_share_set(sid, character(0), granted_by = sa$user$id, con = scon)
  identical(db_session_role(sid, sb$user$id, con = scon), "none") &&
    !(sid %in% db_sessions_list(user_id = sb$user$id, con = scon)$id)
})
chk("★ 共享给不存在的对话不抛异常（界面上点得快会有这种时序）",
    !inherits(tryCatch(db_session_share_set("s-19700101000000-9", sb$user$id,
                                            con = scon),
                       error = function(e) e), "error"))
DBI::dbDisconnect(scon)

# ---- 界面接线 ----
# ⚠️ 这一节的重点是**闸门有没有接上**。上面的纯函数再对，没有调用点也是白搭
#    —— 而且"没接上"的表现是静默越权，不报错。
chat_src3 <- paste(readLines("R/mod_chat.R", warn = FALSE), collapse = "\n")
chk("★★ 点开对话前会查身份（data-sid 是前端传上来的任意字符串）", {
  m <- regmatches(chat_src3,
    regexpr("(?s)observeEvent\\(input\\$pick_session.*?\\n    \\}\\)",
            chat_src3, perl = TRUE))
  length(m) == 1 && grepl("db_session_role(", m, fixed = TRUE) &&
    grepl("dsapp_role_can_view(role)", m, fixed = TRUE)
})
chk("★★ 发送路径上有只读闸门（前端置灰只是提示，改一下 DOM 就没了）", {
  m <- regmatches(chat_src3,
    regexpr("(?s)dsapp_chat_send <- function\\(.*?\\n    \\}",
            chat_src3, perl = TRUE))
  length(m) == 1 && grepl("if (!can_write()", m, fixed = TRUE)
})
chk("★★ 删除有两个闸门：开弹窗前、以及真的删之前", {
  a <- regmatches(chat_src3,
    regexpr("(?s)observeEvent\\(input\\$del_chat, \\{.*?\\n    \\}\\)",
            chat_src3, perl = TRUE))
  b <- regmatches(chat_src3,
    regexpr("(?s)observeEvent\\(input\\$do_del_chat, \\{.*?\\n    \\}\\)",
            chat_src3, perl = TRUE))
  # ⚠️ 光查"这段里出现过 if (!can_write())"抓不到**阉割式**的破坏：把 if 的
  #    花括号留在原地、只删掉里面的 return，那句话照样在源码里，扫描照样绿，
  #    而闸门已经退化成"什么也不挡，落下去接着删"。所以查**位置关系**：
  #    闸门要排在第一个破坏性动作之前，而且闸门里面真的 return 了。
  #
  # ★ V16.1 item 3：闸门本身从 `if (!can_write())` 换成了 `g <- del_gate(sid)`。
  #   原因见 R/mod_chat.R 里 del_gate 那 15 行说明 —— can_write() 来自 sess_role()，
  #   而它把「对话真的不在了」「查库抛错」「确实是别人的」压成同一个 "none"，
  #   主账号在前两种处境下被告知的是"这是别人共享给你的对话"，于是怎么点都
  #   删不掉（用户原话：「删除会话时显示删除不掉」）。
  # ⚠️ 换掉的是**拒绝时说什么**，不是"还有没有闸门"。所以这一条查的东西一点
  #    没变：位置关系 + 闸门里真的 return。别把它简化成"源码里出现过 del_gate("。
  lt <- function(x, pat) regexpr(pat, x, fixed = TRUE)
  g  <- lt(a, "g <- del_gate(sid)")
  act  <- lt(a, "db_messages_get(")
  g2 <- lt(b, "g <- del_gate(sid)")
  act2 <- lt(b, "dsapp_chat_abort()")
  length(a) == 1 && length(b) == 1 &&
    g > 0 && act > g && grepl("return(", substr(a, g, act), fixed = TRUE) &&
    g2 > 0 && act2 > g2 && grepl("return(", substr(b, g2, act2), fixed = TRUE) &&
    # 那一处是**弹窗里**的第二道闸门：拒绝的同时必须把已经弹出来的框收掉，
    # 否则用户看到的是"点了删除、框没关、也什么都没说"。
    grepl("removeModal()", substr(b, g2, act2), fixed = TRUE)
})
# 让被共享的人再转手共享，等于授权链自己长出去，owner 完全不知道。
chk("★★ 共享入口只对 owner/admin 渲染（被共享的人不能再转手）", {
  m <- regmatches(chat_src3,
    regexpr("(?s)output\\$share_bar <- renderUI\\(\\{.*?\\n    \\}\\)",
            chat_src3, perl = TRUE))
  length(m) == 1 && grepl("dsapp_role_can_write(sess_role())", m, fixed = TRUE)
})
chk("★★ 保存共享名单前再查一次权限（渲染过 ≠ 现在还有权限）", {
  m <- regmatches(chat_src3,
    regexpr("(?s)observeEvent\\(input\\$do_share, \\{.*?\\n    \\}\\)",
            chat_src3, perl = TRUE))
  # ⚠️ 同上：查位置关系而不是"出现过没有"。只删 return、留下 if 的变异体
  #    能骗过字符串扫描（2026-09-13 变异 #16 实测就是这样漏的）。
  #
  # ⚠️ 锚点 2026-09-14 从 db_session_share_set( 换成了 dsapp_share_save(：
  #    写库那一步挪进了 R/share.R（任务页共用），这里只剩一个调用。
  #    锚点不跟着换的话，这条断言会变成扫一段已经不存在的代码 —— 恒为假。
  g <- regexpr("if \\(!dsapp_role_can_write\\(sess_role\\(\\)\\)\\) \\{", m)
  act <- regexpr("dsapp_share_save\\(", m)
  length(m) == 1 && g > 0 && act > g &&
    grepl("return(", substr(m, g, act), fixed = TRUE)
})
# ⚠️ 候选账号的筛选 2026-09-14 从 mod_chat.R 挪到了 R/share.R（任务页也要
#    用同一份）。断言跟着挪 —— 留在原地会变成"扫一段已经没有这段代码的
#    源码"，也就是一条**恒为假**的检查。
share_src <- paste(readLines("R/share.R", warn = FALSE), collapse = "\n")
chk("★ 候选账号里排除了自己（共享给自己会让人以为自己丢了所有权）",
    grepl("us$id != me", share_src, fixed = TRUE))
chk("★★ 只读的对话在输入框上方明说一句（不说 = 看起来像坏了）", {
  m <- regmatches(chat_src3,
    regexpr("(?s)output\\$readonly_note <- renderUI\\(\\{.*?\\n    \\}\\)",
            chat_src3, perl = TRUE))
  length(m) == 1 && grepl("is_readonly()", m, fixed = TRUE)
})
# 身份判定只能有一处。散着判的话，漏一处就是一个静默的越权。
chk("★★ 角色判定集中在 sess_role / can_write / is_readonly 三个 reactive 里",
    grepl("sess_role <- reactive({", chat_src3, fixed = TRUE) &&
      grepl("can_write <- reactive({ dsapp_role_can_write(sess_role()) })",
            chat_src3, fixed = TRUE))

tsk_src3 <- paste(readLines("R/mod_tasks.R", warn = FALSE), collapse = "\n")
chk("★★ 任务页的重跑被共享闸门挡住（重跑 = 在别人的工作区里再跑一遍）", {
  m <- regmatches(tsk_src3,
    regexpr("(?s)observeEvent\\(input\\$rerun, \\{.*?\\n    \\}\\)",
            tsk_src3, perl = TRUE))
  length(m) == 1 && grepl("dsapp_role_can_write(current_role())", m, fixed = TRUE)
})
# V7 item 6 起删除改成了**多选**，闸门也跟着从"查选中那一行"变成"逐条查"。
# 这一步是必须的：勾中的一批里完全可能既有自己的、又有共享来的（同一个
# 列表里），只查第一条就放行的话，后面那些会被顺带删掉，界面上毫无提示。
chk("★★ 任务页的删除被共享闸门挡住，而且是两道（开弹窗 + 真删）", {
  a <- regmatches(tsk_src3,
    regexpr("(?s)observeEvent\\(input\\$delete, \\{.*?\\n    \\}\\)",
            tsk_src3, perl = TRUE))
  b <- regmatches(tsk_src3,
    regexpr("(?s)observeEvent\\(input\\$do_delete, \\{.*?\\n    \\}\\)",
            tsk_src3, perl = TRUE))
  length(a) == 1 && length(b) == 1 &&
    grepl("delete_scope(ids)", a, fixed = TRUE) &&
    grepl("delete_scope(ids)", b, fixed = TRUE)
})
chk("★★ 删除的归属是**逐条**查的（只查第一条会顺带删掉别人共享给你的）", {
  m <- regmatches(tsk_src3,
    regexpr("(?s)delete_scope <- function\\(ids\\).*?\\n    \\}",
            tsk_src3, perl = TRUE))
  length(m) == 1 &&
    grepl("vapply(df$session_id[k]", m, fixed = TRUE) &&
    grepl("db_session_role(s, state$user_id", m, fixed = TRUE) &&
    grepl("dsapp_role_can_write(", m, fixed = TRUE)
})
# ⚠️ ids 和 match() 出来的下标必须**同步**筛。只去掉下标里的 NA、ids 原样
#    留着的话两个向量就错位了，按 can 取子集时取到的是**别的任务** ——
#    唯一的表现是"删掉了一条我没勾的记录"。
chk("★★ ids 和 match 下标同步筛（错位 = 删掉没勾的那条）", {
  m <- regmatches(tsk_src3,
    regexpr("(?s)delete_scope <- function\\(ids\\).*?\\n    \\}",
            tsk_src3, perl = TRUE))
  length(m) == 1 && grepl("ids <- ids[keep]", m, fixed = TRUE) &&
    grepl("k <- k[keep]", m, fixed = TRUE)
})
chk("★★ 正在跑的那条不许删（引擎还攥着它的 task_id，删了状态永远停在 running）", {
  m <- regmatches(tsk_src3,
    regexpr("(?s)observeEvent\\(input\\$delete, \\{.*?\\n    \\}\\)",
            tsk_src3, perl = TRUE))
  length(m) == 1 && grepl("engine$state$task_id", m, fixed = TRUE) &&
    grepl("正在执行，不能删除", m, fixed = TRUE)
})
chk("★★ 要删哪一批在开弹窗那一刻就钉住了（弹窗不挡表格，用户还能再勾）", {
  length(regmatches(tsk_src3,
    regexpr("(?s)observeEvent\\(input\\$delete, \\{.*?\\n    \\}\\)",
            tsk_src3, perl = TRUE))) == 1 &&
    grepl("pending_delete(sc$ok)", tsk_src3, fixed = TRUE) &&
    grepl("ids <- pending_delete()", tsk_src3, fixed = TRUE)
})
# ⚠️ db_task_get() 给的是原始任务行，里面没有角色 —— 归属只能从
#    session_id 反查。写成"默认放行"的话闸门形同虚设。
chk("★★ 任务页的归属是从 session_id 反查的，不是从任务行上读的", {
  m <- regmatches(tsk_src3,
    regexpr("(?s)current_role <- reactive\\(\\{.*?\\n    \\}\\)",
            tsk_src3, perl = TRUE))
  length(m) == 1 && grepl("db_session_role(t$session_id", m, fixed = TRUE)
})
chk("★ 任务表里标出哪些是共享来的（不标 = 点了没反应像坏了）",
    grepl('from = ifelse(as.character(df$role', tsk_src3, fixed = TRUE))

# ---- item 7：从任务页直接共享（不绕道文件共享区）-----------------------------
# 用户在这一页想做的事是"把刚跑出来的结果给谁看看"。以前只能把产物发布到
# 共享文件区 —— 那等于把一份脱离上下文的文件丢给全站，谁都能改。
chk("★★ 任务页有共享入口，而且开弹窗前查权限", {
  m <- regmatches(tsk_src3,
    regexpr("(?s)observeEvent\\(input\\$share, \\{.*?\\n    \\}\\)",
            tsk_src3, perl = TRUE))
  length(m) == 1 && grepl("actionButton(ns(\"share\")", tsk_src3, fixed = TRUE) &&
    grepl("dsapp_role_can_write(current_role())", m, fixed = TRUE)
})
chk("★★ 任务页保存共享名单前再查一次权限，且查的是**钉住的那段对话**", {
  m <- regmatches(tsk_src3,
    regexpr("(?s)observeEvent\\(input\\$do_share, \\{.*?\\n    \\}\\)",
            tsk_src3, perl = TRUE))
  # ⚠️ 这里必须查 share_sid()（开弹窗时钉住的那段对话），不能回头读
  #    current()：弹窗不挡左侧表格，用户点开弹窗之后随手换一行选中，
  #    current() 就是**另一条任务**了，保存下去的名单会落到别人的对话上，
  #    界面上一点异常都看不出来。所以下面这条顺带断言 do_share 里没有
  #    current()。
  g <- regexpr("if \\(!dsapp_role_can_write\\(role\\)\\) \\{", m)
  act <- regexpr("dsapp_share_save\\(", m)
  length(m) == 1 && grepl("sid <- share_sid()", m, fixed = TRUE) &&
    grepl("dsapp_share_role(sid,", m, fixed = TRUE) &&
    !grepl("current()", m, fixed = TRUE) &&
    g > 0 && act > g && grepl("return(", substr(m, g, act), fixed = TRUE)
})
# ⚠️ 上面那条是**扫源码**的，它查得到"闸门在不在、顺序对不对"，查不到
#    "查角色失败时返回的是什么"。后者只能靠行为测。
#
# ⚠️⚠️ 这道兜底有**两层**，而两层都要测到 —— 这是 2026-09-14 变异测试逼出来的：
#    ① 库查不动（表不存在、库文件坏了）：由 **db_session_role 内部**的
#       tryCatch（R/db.R）兜住并返回 none，**根本轮不到** dsapp_share_role
#       自己的兜底。拿一个空库去调，测到的全是内层。
#    ② 除查询之外的任何一步抛（比如 state$user 坏掉时 dsapp_user_is_admin()
#       里的 `user$is_admin` 会抛）：才轮到 dsapp_share_role 的 tryCatch。
#    只测 ① 的后果是：把 ② 的 "none" 改成 "owner"，断言照样绿 —— 变异 #2
#    一开始就是这么漏掉的。**夹具只够触发内层，等于这条断言是假的。**
chk("★★ 角色查不动时按**没权限**处理（数据库出错不能变成人人可写）", {
  # ⚠️ 变量名**不能叫 tmp**。chk 的第二个参数是个 promise，按 R 的语义在
  #    **调用方的环境**（也就是这个文件的全局）里求值 —— 在里面写
  #    `tmp <- tempfile()` 是给全局的 tmp 重新赋值，末尾那句 unlink 更是
  #    把整个自检共用的临时目录删掉。症状是几百条断言之后突然有一条
  #    "真实路径能采到（本机的 /tmp 一定在）"红掉，看着和共享毫无关系。
  #    这个坑是 2026-09-14 自检自己抓出来的。
  #
  # ① 空库（内层兜底）
  bad_db_file <- tempfile(fileext = ".sqlite3")
  bad_con <- DBI::dbConnect(RSQLite::SQLite(), bad_db_file)
  r1 <- tryCatch(
    dsapp_share_role("s-whatever", list(user_id = 1L, user = NULL), con = bad_con),
    error = function(e) paste("THREW:", conditionMessage(e)))
  DBI::dbDisconnect(bad_con)
  unlink(bad_db_file)

  # ② 库是好的（sessions 表在、查得到行），坏的是 state$user。
  #    查询这一关过了之后 is_admin 才会被真正求值 —— 这一步抛出来只有
  #    外层接得住。不用内存库是因为要真的把 sessions 表建出来。
  bad_con2 <- DBI::dbConnect(RSQLite::SQLite(), ":memory:")
  DBI::dbExecute(bad_con2,
    "CREATE TABLE sessions (id TEXT PRIMARY KEY, user_id INTEGER)")
  DBI::dbExecute(bad_con2,
    "CREATE TABLE session_share (session_id TEXT, user_id INTEGER)")
  DBI::dbExecute(bad_con2, "INSERT INTO sessions (id, user_id) VALUES ('s-x', 1)")
  r2 <- tryCatch(
    # state$user 给个原子向量：dsapp_user_is_admin() 里的 `user$is_admin`
    # 会抛 "$ operator is invalid for atomic vectors"。
    dsapp_share_role("s-x", list(user_id = 1L, user = "not-a-list"), con = bad_con2),
    error = function(e) paste("THREW:", conditionMessage(e)))
  DBI::dbDisconnect(bad_con2)

  identical(r1, "none") && identical(r2, "none")
})
# 共享的单位是**对话**（任务靠工作区接力，单给一条任务对方读不到输入）。
# 这是个替用户做的决定，必须写在弹窗第一句里 —— 不写就是替他做主还不告诉他。
chk("★★ 任务页的共享弹窗说清楚共享的是整个对话", {
  m <- regmatches(tsk_src3,
    regexpr("(?s)observeEvent\\(input\\$share, \\{.*?\\n    \\}\\)",
            tsk_src3, perl = TRUE))
  length(m) == 1 && grepl("整个对话", m, fixed = TRUE)
})
# 两份实现迟早分叉，而分叉的表现是"从任务页共享出去的人能改数据"。
# ⚠️ share.R 里那两处是**定义**（`dsapp_share_modal <- function(`），
#    两个 mod_*.R 里是**调用**（`dsapp_share_modal(`）—— 定义处不含那个
#    左括号连着的写法，拿"有没有 dsapp_share_modal(" 去查 share.R 会
#    恒为假。两边分开查。
chk("★★ 两个页面的共享走的是同一份实现（R/share.R）", {
  defined <- grepl("dsapp_share_modal <- function(", share_src, fixed = TRUE) &&
    grepl("dsapp_share_candidates <- function(", share_src, fixed = TRUE)
  calls <- function(f) grepl("dsapp_share_modal(", f, fixed = TRUE) &&
    grepl("dsapp_share_candidates(", f, fixed = TRUE)
  defined && calls(chat_src3) && calls(tsk_src3)
})
chk("★★ 候选账号的筛选只有一处实现（重复实现 = 改了一处漏另一处）",
    grepl("us$id != me", share_src, fixed = TRUE) &&
      !grepl("us$id != as.integer", chat_src3, fixed = TRUE) &&
      !grepl("us$id != as.integer", tsk_src3, fixed = TRUE))
chk("★★ 候选账号里排除了停用的账号（选了也登不进来，owner 会以为已经共享了）",
    grepl('as.character(us$status) == "active"', share_src, fixed = TRUE))
# 名单只该有一个写入口。多一条写库路径 = 多一处能绕过权限复查的地方，
# 而且两处的"撤回"语义迟早会分叉（一处删行、一处留着）。
chk("★★ 共享名单的写库只有一处（都在 R/share.R 的 dsapp_share_save 里）", {
  # gregexpr 没匹配到时返回的是 -1，不是长度为 0 的向量 —— 直接取 length()
  # 会得到 1，于是"一次都没调"被数成"调了一次"。这个坑让上面那句断言
  # 一开始假绿过一次。
  count_in <- function(s) {
    m <- gregexpr("db_session_share_set\\(", s)[[1]]
    if (length(m) == 1 && m[1] == -1L) 0L else length(m)
  }
  count_in(share_src) == 1 &&
    count_in(chat_src3) == 0 && count_in(tsk_src3) == 0
})

