                        con = tcon)$user$id
chk("★ 造得出三个测试账号（下面几条的前提）",
    length(unique(c(ta, tb, tc))) == 3 && !any(is.na(c(ta, tb, tc))))

r <- dsapp_team_save(NULL, "张老师课题组", "转录组这条线", by = ta, con = tcon)
chk("建组", isTRUE(r$ok), r$msg)
t1 <- r$id
chk("新组的成员数一开始是 0", {
  tl <- dsapp_teams_list(con = tcon)
  identical(as.integer(tl$n_members[tl$id == t1]), 0L)
})
