  r2 <- dsapp_team_save(NULL, "张老师课题组", con = tcon)
  !isTRUE(r2$ok) && grepl("已经有", r2$msg) &&
    !grepl("UNIQUE|constraint", r2$msg, ignore.case = TRUE)
})
