# ---------------------------------------------------------------------------
section("服务器健康监控（#47）")

# 这一块的特殊之处：它读的是**这台机器此刻的状态**，没法靠"打开页面看一眼"
# 验证对错 —— 数字都是真的，只是可能算错了。所以下面把解析函数掰开，喂
# 真实 /proc 内容和几种"别人机器上才有"的怪格式进去。

dsapp_health_reset_cache()

# ---- /proc/stat 与 CPU 使用率 ----
stat_real <- c(
  "cpu  1234567 890 345678 98765432 12345 0 6789 0 0 0",
  "cpu0 617283 445 172839 49382716 6172 0 3394 0 0 0",
  "intr 12345678 0 0",
  "ctxt 98765432")
s1 <- dsapp_parse_stat(stat_real)
chk("★ 解析 /proc/stat：认得出来", isTRUE(s1$ok))
chk("★ idle 里算进了 iowait（等磁盘不是 CPU 在干活）", {
  # 手算：user+nice+system+idle+iowait+irq+softirq+steal
  want_total <- 1234567 + 890 + 345678 + 98765432 + 12345 + 0 + 6789 + 0
  isTRUE(all.equal(s1$total, want_total)) && isTRUE(all.equal(s1$idle, 98765432 + 12345))
})
chk("★ 老内核没有 steal/guest 字段也不炸（按下标取，不写死长度）", {
  old <- "cpu  100 0 50 1000 10 0 5"
  r <- dsapp_parse_stat(old)
  isTRUE(r$ok) && isTRUE(all.equal(r$total, 1165))
})
chk("★ 没有 cpu 行 → 如实报 ok = FALSE（不是编一个 0）",
  identical(dsapp_parse_stat(c("intr 1 2 3"))$ok, FALSE))
chk("★ 字段太少 → ok = FALSE",
  identical(dsapp_parse_stat(c("cpu 1 2"))$ok, FALSE))

chk("★ 两次采样之间正好一半时间在忙 → 50%", {
  a <- dsapp_parse_stat("cpu  100 0 100 800 0 0 0 0")
  b <- dsapp_parse_stat("cpu  150 0 150 900 0 0 0 0")
  # dt = 100，di = 100 → (1 - 100/100)*100 = 0？手算：total 差 = 50+0+50+100 = 200
  isTRUE(all.equal(dsapp_cpu_percent(a, b), 50))
})
chk("★ 没有基线 → NA（不是 0：0 会被读成『完全空闲』）",
  is.na(dsapp_cpu_percent(NULL, s1)))
chk("★ 计数器没动（两次读到同一份）→ NA，不拿 0 除以 0",
  is.na(dsapp_cpu_percent(s1, s1)))
chk("★ 算出来的百分比夹在 [0,100]（多核计时抖动会给出 100 出头）", {
  a <- dsapp_parse_stat("cpu  0 0 0 1000")
  b <- dsapp_parse_stat("cpu  0 0 0 900")   # idle 倒退，纯属脏数据
  p <- dsapp_cpu_percent(a, b)
  is.na(p) || (p >= 0 && p <= 100)
})

# ---- /proc/meminfo ----
mi_real <- c(
  "MemTotal:       16316104 kB",
  "MemFree:         1234567 kB",
  "MemAvailable:    8123456 kB",
  "Buffers:          123456 kB",
  "Cached:          4567890 kB",
  "SwapCached:            0 kB",
  "SwapTotal:       2097152 kB",
  "SwapFree:        1048576 kB",
  "HugePages_Total:       0")
mi <- dsapp_parse_meminfo(mi_real)
chk("★ 解析 /proc/meminfo：认得出来", isTRUE(mi$ok))
chk("★ 值是字节（kB × 1024），不是原样的 kB", isTRUE(all.equal(mi$MemTotal, 16316104 * 1024)))
chk("★ 带括号的键名也算数（HugePages_Total 这类）", !is.null(mi$HugePages_Total))
chk("★ 空内容 → ok = FALSE", identical(dsapp_parse_meminfo(character(0))$ok, FALSE))
chk("★ 不认识的格式不会编出数字", identical(dsapp_parse_meminfo("随便一段话")$ok, FALSE))

ms <- dsapp_mem_snapshot(mi)
chk("★ 内存用 MemAvailable 而不是 MemFree（free 不含可回收的页缓存，永远很小）", {
  isTRUE(ms$ok) && identical(ms$source, "MemAvailable") &&
    isTRUE(all.equal(ms$used, 16316104 * 1024 - 8123456 * 1024))
})
chk("★ 百分比合理（0-100）", ms$percent > 0 && ms$percent < 100)
chk("★ 老内核没有 MemAvailable 时退回 MemFree（且标明是估的）", {
  old <- dsapp_parse_meminfo(c("MemTotal:  1000 kB", "MemFree:   400 kB"))
  s <- dsapp_mem_snapshot(old)
  isTRUE(s$ok) && identical(s$source, "MemFree") && isTRUE(all.equal(s$used, 600 * 1024))
})
chk("★ 拿不到内存信息时 ok = FALSE，不是充满 0", {
  s <- dsapp_mem_snapshot(list(ok = FALSE))
  identical(s$ok, FALSE) && is.na(s$percent)
})

# ---- 交换分区 ----
sw <- dsapp_swap_snapshot(mi)
chk("★ 交换分区：用了一半 → 50%",
  isTRUE(sw$ok) && isTRUE(all.equal(sw$percent, 50)))
chk("★ 没开交换分区是**正常配置**，不算采集失败（两者要分开）", {
  s <- dsapp_swap_snapshot(dsapp_parse_meminfo(c("MemTotal:  1000 kB",
                                                 "SwapTotal:    0 kB",
                                                 "SwapFree:     0 kB")))
  isTRUE(s$ok) && isTRUE(s$none) && s$percent == 0
})

# ---- 负载 / 运行时长 ----
ld <- dsapp_parse_loadavg("0.52 1.58 2.59 1/1234 56789")
chk("★ 解析 /proc/loadavg 的三个数",
  isTRUE(ld$ok) && ld$m1 == 0.52 && ld$m5 == 1.58 && ld$m15 == 2.59)
chk("★ 空 / 残缺的 loadavg → ok = FALSE", {
  identical(dsapp_parse_loadavg("")$ok, FALSE) &&
    identical(dsapp_parse_loadavg("0.52 1.58")$ok, FALSE)
})
chk("★ 解析 /proc/uptime", isTRUE(all.equal(dsapp_parse_uptime("123456.78 987654.32"), 123456.78)))
chk("★ 坏掉的 uptime → NA",
  is.na(dsapp_parse_uptime("")) && is.na(dsapp_parse_uptime("abc")) &&
    is.na(dsapp_parse_uptime("-5 0")))

chk("★ 时长说人话", {
  dsapp_fmt_duration(45) == "45 秒" &&
  dsapp_fmt_duration(600) == "10 分钟" &&
  dsapp_fmt_duration(7200) == "2.0 小时" &&
  dsapp_fmt_duration(86400 * 3 + 3600 * 4) == "3 天 4 小时" &&
  dsapp_fmt_duration(NA_real_) == "—"
})

# ---- df ----
df_real <- c(
  "Filesystem     1024-blocks      Used Available Capacity Mounted on",
  "/dev/sda1        103080888  45678901  52123456      47% /")
d1 <- dsapp_parse_df(df_real, "/data")
chk("★ 解析 df：跳过表头，取到数据行", isTRUE(d1$ok))
chk("★ 单位是 1024 字节块 → 乘 1024 得字节（-k 保证）",
  isTRUE(all.equal(d1$total, 103080888 * 1024)) &&
    isTRUE(all.equal(d1$used, 45678901 * 1024)))
chk("★ 挂载点、使用率、剩余百分比都对", {
  identical(d1$mount, "/") && d1$percent == 47 &&
    isTRUE(all.equal(d1$free_percent, round(100 * 52123456 / 103080888, 1)))
})
chk("★ 挂载点里有空格也切不错（不能按空白 strsplit）", {
  r <- dsapp_parse_df(c("Filesystem 1024-blocks Used Available Capacity Mounted on",
                        "/dev/sdb1 1000000 500000 500000 50% /media/My Data"), "/x")
  isTRUE(r$ok) && identical(r$mount, "/media/My Data")
})
chk("★ 文件系统名里有空格也一样", {
  r <- dsapp_parse_df(c("Filesystem 1024-blocks Used Available Capacity Mounted on",
                        "nas.local:/my pool 1000000 500000 500000 50% /mnt/nas"), "/x")
  isTRUE(r$ok) && identical(r$fs, "nas.local:/my pool")
})
chk("★ 只有表头（没有数据行）→ ok = FALSE，不是拿表头当数据", {
  r <- dsapp_parse_df("Filesystem 1024-blocks Used Available Capacity Mounted on", "/x")
  identical(r$ok, FALSE)
})
chk("★ 空输出 → ok = FALSE 并带上原因",
  identical(dsapp_parse_df(character(0), "/x")$ok, FALSE) &&
    nzchar(dsapp_parse_df(character(0), "/x")$reason %||% ""))
chk("★ df 报错文本 → ok = FALSE（不能把错误信息当挂载点）",
  identical(dsapp_parse_df("df: /gone: No such file or directory", "/gone")$ok, FALSE))

chk("★ 路径不存在 → ok = FALSE，且说明是目录没了（盘被卸载？）", {
  r <- dsapp_disk_snapshot(file.path(tmp, "no-such-dir-xyz"))
  identical(r$ok, FALSE) && grepl("不存在", r$reason %||% "")
})
chk("★ 路径为空 → ok = FALSE", identical(dsapp_disk_snapshot("")$ok, FALSE))
chk("★ 真实路径能采到（本机的 /tmp 一定在）", {
  r <- dsapp_disk_snapshot(tmp)
  isTRUE(r$ok) && r$total > 0 && nzchar(r$mount) && r$percent >= 0 && r$percent <= 100
})

# ---- 本进程 ----
sf <- dsapp_parse_self_status(c(
  "Name:\tR", "State:\tS (sleeping)", "VmSize:\t  1234567 kB",
  "VmRSS:\t    98765 kB", "Threads:\t3", "SigQ:\t0/12345"))
chk("★ 读本进程 RSS / 线程数（字节）",
  isTRUE(sf$ok) && isTRUE(all.equal(sf$rss, 98765 * 1024)) && isTRUE(all.equal(sf$threads, 3)))
chk("★ 拿不到 VmRSS → ok = FALSE", identical(dsapp_parse_self_status("Name:\tR")$ok, FALSE))

chk("★ 从库里的 UTC 时间戳算已过去多少秒", {
  t <- format(Sys.time() - 120, "%Y-%m-%d %H:%M:%S", tz = "UTC")
  s <- dsapp_since_seconds(t)
  !is.na(s) && s >= 115 && s <= 130
})
chk("★ 时间戳空 / 坏 / 未来 → NA（**不是 0** —— 0 会被读成『刚开始跑』）", {
  is.na(dsapp_since_seconds(NA_character_)) &&
  is.na(dsapp_since_seconds("")) &&
  is.na(dsapp_since_seconds("不是时间")) &&
  is.na(dsapp_since_seconds(format(Sys.time() + 600, "%Y-%m-%d %H:%M:%S", tz = "UTC")))
})

# ---- 告警判定 ----
# 造一个"哪儿都正常"的快照做基准，下面每条只改一个字段
mk_probe <- function(disk_free = 60, disk_used = 40, mem = 40, swap = 0,
                     swap_none = FALSE, load_per_core = 0.2, disk_ok = TRUE,
                     mount = "/", inst_mount = "/home", same_fs = FALSE) {
  list(
    cpu = list(ok = TRUE, percent = 5, primed = TRUE, cores = 8,
               load = list(ok = TRUE, m1 = load_per_core * 8, m5 = 1, m15 = 1),
               load_per_core = load_per_core),
    mem = list(ok = TRUE, total = 1e10, used = 1e10 * mem / 100,
               available = 1e10 * (100 - mem) / 100, percent = mem),
    swap = list(ok = TRUE, total = 1e9, used = 1e9 * swap / 100,
                percent = swap, none = swap_none),
    uptime = 123456, at = Sys.time(),
    disk = list(
      data = if (disk_ok) list(ok = TRUE, fs = "/dev/sda1", mount = mount,
                               total = 1e11, used = 1e11 * disk_used / 100,
                               available = 1e11 * disk_free / 100,
                               percent = disk_used, free_percent = disk_free)
             else list(ok = FALSE, path = "/data", reason = "目录不存在（盘被卸载了？）"),
      install = list(ok = TRUE, fs = "/dev/sda1", mount = inst_mount,
                     total = 1e11, used = 40e9, available = 60e9,
                     percent = 40, free_percent = 60),
      same_fs = same_fs),
    self = list(ok = TRUE, pid = 1, rss = 1e8, threads = 5, fds = 20))
}

h_ok <- dsapp_health_issues(mk_probe())
chk("★ 一切正常时 level = ok 且没有告警", identical(h_ok$level, "ok") && length(h_ok$issues) == 0)
chk("★ 磁盘剩余 < 5% → 严重", {
  h <- dsapp_health_issues(mk_probe(disk_free = 3, disk_used = 97))
  identical(h$level, "critical") && any(grepl("剩余空间不足", h$issues))
})
chk("★ 磁盘用满但还剩得多（% 算得对）→ 不误报", {
  # 剩 30% 用 70%：两条线都没到
  h <- dsapp_health_issues(mk_probe(disk_free = 30, disk_used = 70))
  identical(h$level, "ok")
})
chk("★ 磁盘使用率 ≥ 90% → 注意", {
  h <- dsapp_health_issues(mk_probe(disk_free = 8, disk_used = 92))
  identical(h$level, "warn") && any(grepl("使用率", h$issues))
})
chk("★ 内存 ≥ 90% → 注意，且说的是 OOM", {
  h <- dsapp_health_issues(mk_probe(mem = 95))
  identical(h$level, "warn") && any(grepl("OOM", h$issues))
})
chk("★ 交换分区 ≥ 90% → 注意（已经在换页了）", {
  h <- dsapp_health_issues(mk_probe(swap = 95))
  identical(h$level, "warn") && any(grepl("换页", h$issues))
})
chk("★ 没开交换分区不报警（正常配置，报了就是狼来了）",
  identical(dsapp_health_issues(mk_probe(swap_none = TRUE))$level, "ok"))
chk("★ 负载按核数折算：8 核 load 16 → 报", {
  h <- dsapp_health_issues(mk_probe(load_per_core = 2))
  identical(h$level, "warn") && any(grepl("负载", h$issues))
})
chk("★ 负载 8 核 load 8（折合 1.0）→ 不报（满核不等于过载）",
  identical(dsapp_health_issues(mk_probe(load_per_core = 1))$level, "ok"))

chk("★ 磁盘采集失败**要报**（看不见的盘不能当作没问题）", {
  h <- dsapp_health_issues(mk_probe(disk_ok = FALSE))
  identical(h$level, "warn") && any(grepl("采集失败", h$issues))
})
chk("★ 采集失败时标签退回**路径**而不是「（?）」（正需要知道该去看哪儿）", {
  h <- dsapp_health_issues(mk_probe(disk_ok = FALSE))
  any(grepl("/data", h$issues, fixed = TRUE)) && !any(grepl("（?）", h$issues, fixed = TRUE))
})
chk("★ 数据盘和程序目录同盘时只报一次（报两遍像是两块都满了）", {
  h <- dsapp_health_issues(mk_probe(disk_free = 2, disk_used = 98, same_fs = TRUE,
                                    inst_mount = "/"))
