if (!inherits(p1, "error")) {
  chk("★ 快照该有的字段都在",
    all(c("at", "cpu", "mem", "swap", "uptime", "disk", "self") %in% names(p1)))
  chk("★ 本机 CPU 核数采得到", isTRUE(p1$cpu$cores >= 1))
  chk("★ 本机内存采得到且为正", isTRUE(p1$mem$ok) && p1$mem$total > 0)
  chk("★ 本机数据盘采得到且为正", isTRUE(p1$disk$data$ok) && p1$disk$data$total > 0)
  chk("★ 本进程 RSS 采得到", isTRUE(p1$self$ok) && p1$self$rss > 0)
  chk("★ 第一次采集没有基线 → CPU 是 NA（**不是 0**）", is.na(p1$cpu$percent) || isTRUE(p1$cpu$primed))

  # 缓存：5 秒内两次调用是同一个对象（管理页每 10 秒刷、几个标签页各刷各的）
  p2 <- dsapp_health_probe(cfg)
  chk("★ 5 秒内重复采集走缓存（返回同一个对象）", identical(p1, p2))
  dsapp_health_reset_cache()
  p3 <- dsapp_health_probe(cfg)
  chk("★ 清掉缓存后是重新采的（对象不同）", !identical(p1, p3))

  chk("★ 汇总带上阈值，界面不用自己写死数字", {
    s <- dsapp_health_summary(cfg)
    all(c("disk_warn", "disk_critical_free", "mem_warn", "swap_warn") %in%
          names(s$thresholds)) && identical(s$thresholds$disk_warn, DSAPP_HEALTH_DISK_WARN_PCT)
  })
  chk("★ 汇总的 level 和 issues 自洽", {
    s <- dsapp_health_summary(cfg)
    length(s$issues) == 0 || !identical(s$level, "ok")
  })

  # ★ 走查时踩出来的：「立即刷新」清缓存时把 CPU 基线也清了，于是刷新一下
  #   CPU 就退回「首次采样中…」—— 按钮看起来像把页面弄坏了。基线不是缓存，
  #   它是上一次的测量结果。
  chk("★★ 清采集缓存**不能**把 CPU 基线一起清掉（否则一刷新 CPU 就没了）", {
    dsapp_health_reset_cache()
    a <- dsapp_health_probe(cfg)          # 这一趟采到基线
    dsapp_health_reset_cache()            # 「立即刷新」的动作
    b <- dsapp_health_probe(cfg)          # 再来一趟
    isTRUE(b$cpu$primed) && !is.na(b$cpu$percent)
  })
  chk("★ keep_cpu = FALSE 时才连基线一起清（留给测试用）", {
    dsapp_health_reset_cache(keep_cpu = FALSE)
    p <- dsapp_health_probe(cfg)
    !isTRUE(p$cpu$primed) && is.na(p$cpu$percent)
  })
}

