section("V6 item 1：模型设置按账号记住")

# ⚠️ 这一节要钉住的核心是**语义**，不是“函数能跑”：
#    · user_id 为 NULL 时**不许查库**也**不许写库** —— 没有身份的会话
#      （登录页、还没登录的那一拍）不能把设置写进“某个人的”行里；
#    · api_key = NULL 表示“不要动已经存的那把” —— 左栏的防抖保存每 800ms
#      就跑一次，粘贴 Key 的过程中会带着半截 Key 触发好几轮。要是空值也
#      照写，用户会得到一个“存了但永远是错的”的 Key，而且界面显示“已记住”。
#      这一条错了不会报任何错，只会让人反复登录失败。
v6con <- DBI::dbConnect(RSQLite::SQLite(), tempfile(fileext = ".sqlite3"))
dsapp_db_schema(v6con); dsapp_db_schema_users(v6con)
dsapp_db_schema_share(v6con); dsapp_db_schema_nodes(v6con)
v6u <- dsapp_user_create("V6甲", "v6-a@example.com", "13800000021", "RNA",
                         password = "password123", con = v6con)$user$id
v6v <- dsapp_user_create("V6乙", "v6-b@example.com", "13800000022", "ATAC",
                         password = "password123", con = v6con)$user$id
v6u <- as.integer(v6u); v6v <- as.integer(v6v)

# ⚠️ 取值的约定是：**名字永远在，值可以是 NULL**（NULL = 没存过）。
#    调用方一律 `s$vendor %||% "deepseek"` 这样兜。写成空串的话，
#    "没存过"和"存过但值是空"就分不开了 —— 而这两种情况在界面上要
#    显示不同的话（"Key 只在本次会话有效" vs "Key 已记住"）。
chk("★ 没存过时返回的是一份**结构完整**的默认值（名字齐、值为 NULL）", {
  s <- dsapp_settings_get(v6u, con = v6con)
  all(c("vendor", "model", "base_url", "api_key", "saved") %in% names(s)) &&
    isFALSE(s$saved) && is.null(s$api_key) && is.null(s$vendor)
})
chk("★ user_id 为 NULL 时不查库也返回完整默认值（登录页会用它渲染）", {
  s <- dsapp_settings_get(NULL, con = v6con)
  is.list(s) && is.null(s$api_key) && isFALSE(s$saved) &&
    all(c("vendor", "model", "base_url", "api_key", "saved") %in% names(s))
})
chk("★ NULL 账号保存设置**不写库**（否则会污染某个真实账号）", {
  before <- DBI::dbGetQuery(v6con,
    "SELECT COUNT(*) n FROM users WHERE llm_api_key IS NOT NULL")$n
  invisible(dsapp_settings_save(NULL, vendor = "openai", model = "gpt-4o",
                                base_url = "http://x", api_key = "sk-LEAK",
                                con = v6con))
  after <- DBI::dbGetQuery(v6con,
    "SELECT COUNT(*) n FROM users WHERE llm_api_key IS NOT NULL")$n
  identical(as.integer(before), as.integer(after)) &&
    !any(grepl("sk-LEAK", unlist(dsapp_settings_get(v6u, con = v6con)),
               fixed = TRUE))
})

invisible(dsapp_settings_save(v6u, vendor = "deepseek", model = "deepseek-chat",
                              base_url = "https://api.deepseek.com",
                              api_key = "sk-real-key", con = v6con))
chk("存进去之后读得回来", {
  s <- dsapp_settings_get(v6u, con = v6con)
  identical(s$vendor, "deepseek") && identical(s$model, "deepseek-chat") &&
    identical(s$api_key, "sk-real-key") && isTRUE(s$saved)
})
chk("★ 只动厂商/模型、api_key 传 NULL 时**已存的 Key 原样保留**", {
  invisible(dsapp_settings_save(v6u, vendor = "moonshot", model = "kimi-k2",
                                base_url = "https://api.moonshot.cn",
                                api_key = NULL, con = v6con))
  s <- dsapp_settings_get(v6u, con = v6con)
  identical(s$api_key, "sk-real-key") && identical(s$vendor, "moonshot")
})
# ⚠️ 这条是**真发生过**的失败模式：粘贴 Key 是逐字符触发的，防抖窗口里
#    每一次都带着更长的前缀。若空串被当成“清空”，最后存下的就是最后一次
#    触发的那个前缀 —— 界面显示“已记住”，但那个 Key 是错的。
# ⚠️ 空串和 NULL 都要挡住。只挡 NULL 是不够的：真正会踩到的调用方
#    （`input$api_key`）清空时给的是 **""**，不是 NULL —— 而 input 的
#    NULL 只出现在"这个控件还没渲染出来"的时候。挡错了那一个，等于没挡。
chk("★★ 空串 Key 不覆盖已存的（粘贴过程中的半截值会静默毁掉它）", {
  invisible(dsapp_settings_save(v6u, vendor = "moonshot", model = "kimi-k2",
                                base_url = "https://api.moonshot.cn",
                                api_key = "", con = v6con))
  identical(dsapp_settings_get(v6u, con = v6con)$api_key, "sk-real-key")
})
chk("★★ 空串也不清空厂商/模型（它是「不动」，不是「只动别的」）", {
  s <- dsapp_settings_get(v6u, con = v6con)
  identical(s$vendor, "moonshot") && identical(s$model, "kimi-k2")
})
chk("★ 清空 Key 的唯一入口是 forget_key（save 传空串不会清）", {
  before <- dsapp_settings_get(v6u, con = v6con)$api_key
  invisible(dsapp_settings_save(v6u, api_key = "", con = v6con))
  mid <- dsapp_settings_get(v6u, con = v6con)$api_key
  invisible(dsapp_settings_forget_key(v6u, con = v6con))
  after <- dsapp_settings_get(v6u, con = v6con)$api_key
  identical(before, "sk-real-key") && identical(mid, "sk-real-key") &&
    is.null(after)
})
chk("★ 按账号隔离：查乙拿到的是乙的（没存过就是 NULL）", {
  s <- dsapp_settings_get(v6v, con = v6con)
  is.null(s$api_key) && !isTRUE(s$saved)
})
chk("★ 清除 Key 只清 Key，厂商/模型/base_url 留着", {
  invisible(dsapp_settings_forget_key(v6u, con = v6con))
  s <- dsapp_settings_get(v6u, con = v6con)
  is.null(s$api_key) && isFALSE(s$saved) &&
    identical(s$vendor, "moonshot") && identical(s$model, "kimi-k2") &&
    identical(s$base_url, "https://api.moonshot.cn")
})
chk("清除 Key 不影响别的账号", {
  invisible(dsapp_settings_save(v6v, vendor = "deepseek", model = "m",
                                base_url = "u", api_key = "sk-b", con = v6con))
  invisible(dsapp_settings_forget_key(v6u, con = v6con))
  identical(dsapp_settings_get(v6v, con = v6con)$api_key, "sk-b")
})
chk("★ 库里读不到这一行时（账号已删）也返回完整默认值，不抛",
    {
      s <- tryCatch(dsapp_settings_get(999999L, con = v6con),
                    error = function(e) NULL)
      is.list(s) && is.null(s$api_key) && isFALSE(s$saved)
    })

