section("V6 item 4：按账号分配硬件资源")

chk("★ 没设过时三项都是 NULL（NULL 才有“跟着平台走”这个语义）", {
  l <- dsapp_user_limits(v6u, con = v6con)
  is.null(l$cpu_sec) && is.null(l$mem_mb) && is.null(l$max_procs)
})
chk("★ 合成时账号值盖平台、没设的项跟平台（不能整份替换）", {
  c2 <- list(exec = list(cpu_sec = 3600, mem_mb = 8192, max_procs = 64))
  invisible(dsapp_user_set_limits(v6u, cpu_sec = 600, con = v6con))
  k <- dsapp_limits_for_user(v6u, cfg = c2, con = v6con)
  identical(k$cpu_sec, 600) && identical(k$mem_mb, 8192) &&
    identical(k$max_procs, 64)
})
chk("★ NULL / NA / 0 都表示恢复默认（清空输入框 = 跟着平台走）", {
  # ⚠️ V15.6 item 14 把「负数」从这个列表里**拿掉了** —— 它现在表示
  #    「不限制」（见下面那条和 users.R 的 DSAPP_LIMIT_UNLIMITED）。
  #    这不是放宽，是把一格两义拆成两格：原来 -1 和 0 是同一个意思，
  #    而"不限制"根本没有表达方式，管理员只能靠填一个大数去近似。
  c2 <- list(exec = list(cpu_sec = 3600, mem_mb = 8192, max_procs = 64))
  res <- vapply(list(NULL, NA, 0), function(v) {
    invisible(dsapp_user_set_limits(v6u, cpu_sec = v, mem_mb = NULL,
                                    max_procs = NULL, con = v6con))
    k <- dsapp_limits_for_user(v6u, cfg = c2, con = v6con)
    is.null(dsapp_user_limits(v6u, con = v6con)$cpu_sec) &&
      identical(k$cpu_sec, 3600)
  }, logical(1))
  all(res)
})
# ---------------------------------------------------------------------------
# ★★ V15.6 item 14：管理员可以设「不限制使用」
#
# 用户原话：「配额和资源上限里需要可以让管理员直接设置，不限制使用」。
# 这一组断言盯的是**整条链路**，不是某一个函数 —— 这条链路上有五个地方
# 会把哨兵吃掉（写库的 norm、读库的 num、合成的 is.null、ulimit 的
# as.integer、提示词的 as.integer），少改一处就是"界面说不限制、跑起来
# 照样被杀"，而且全程不报错。
chk("★★★ 哨兵能存进去、能读回来（写库/读库两条路都不能吃掉它）", {
  invisible(dsapp_user_set_limits(v6u, cpu_sec = DSAPP_LIMIT_UNLIMITED,
                                  mem_mb = NULL, max_procs = NULL,
                                  con = v6con))
  # 直接读库：确认落下去的就是那个负数，不是被 norm() 夹成 60 或 NA
  raw <- DBI::dbGetQuery(v6con, "SELECT cpu_sec FROM users WHERE id = ?",
                         params = list(as.integer(v6u)))$cpu_sec[1]
  !is.na(raw) && raw < 0 &&
    identical(dsapp_user_limits(v6u, con = v6con)$cpu_sec, DSAPP_LIMIT_UNLIMITED)
})
chk("★★★ 合成之后是 Inf（不是 -1、不是 NULL、不是平台默认）", {
  c2 <- list(exec = list(cpu_sec = 3600, mem_mb = 8192, max_procs = 64))
  k <- dsapp_limits_for_user(v6u, cfg = c2, con = v6con)
  # ⚠️ 这里**必须**是 Inf 而不是 3600：写成 3600 的话，管理员设的"不限制"
  #    在读回来那一刻就退化成了平台默认，而界面上一路显示"不限制"。
  is.infinite(k$cpu_sec) && k$cpu_sec > 0 &&
    # 没设的两项照旧走平台默认（哨兵不许污染另外两项）
    identical(k$mem_mb, 8192) && identical(k$max_procs, 64)
})
chk("★★★ ulimit 那一行变成 unlimited（不是 -1、不是 NA、也不是干脆不写）", {
  w <- dsapp_wrapper_script("echo hi", cfg = cfg,
                            limits = list(cpu_sec = DSAPP_LIMIT_UNLIMITED,
                                          mem_mb = DSAPP_LIMIT_UNLIMITED,
                                          max_procs = DSAPP_LIMIT_UNLIMITED))
  grepl("ulimit -t unlimited", w, fixed = TRUE) &&
    grepl("ulimit -v unlimited", w, fixed = TRUE) &&
    grepl("ulimit -u unlimited", w, fixed = TRUE) &&
    # 反方向：不许把哨兵当数字格式化出去（`ulimit -v -1` 会被
    # `2>/dev/null || true` 吞掉 = 限制静默消失，看着也"对"）
    !grepl("ulimit -v -1", w, fixed = TRUE) &&
    !grepl("ulimit -v NA", w, fixed = TRUE) &&
    # 不限制时 `ps -eL` 那段不用生成了（它唯一的用途是算 _np）
    !grepl("ps -eL", w, fixed = TRUE) &&
    # 没被设成不限制的那条**照旧**要有限制（别把整份模板都放开）
    grepl("ulimit -f ", w, fixed = TRUE)
})
chk("★★ 提示词里写「不限制」，不写 NA / -1 / 一个假的大数", {
  txt_mem <- dsapp_limit_prompt_txt(Inf, " MB")
  txt_cpu <- dsapp_limit_prompt_txt(DSAPP_LIMIT_UNLIMITED, " 秒")
  txt_num <- dsapp_limit_prompt_txt(4096, " MB")
  identical(txt_mem, "不限制（管理员已放开，按任务实际需要来，不用为省额度而分块或降采样）") &&
    identical(txt_cpu, txt_mem) &&
    identical(txt_num, "4096 MB")
})
chk("★★ 两个管理入口都认这个哨兵（同一件事不许两种结果）", {
  # 入口一：后台管理页 → 配额与资源上限
  a <- strip_comments(paste(readLines("R/mod_admin.R", warn = FALSE),
                            collapse = "\n"))
  # 入口二：平台超管后台 → 资源限制
  h <- strip_comments(paste(readLines("R/mod_htadmin.R", warn = FALSE),
                            collapse = "\n"))
  all(vapply(list(a, h), function(src) {
    grepl('ns("lim_unlimited")', src, fixed = TRUE) &&
      grepl("DSAPP_LIMIT_UNLIMITED", src, fixed = TRUE) &&
      grepl("dsapp_limit_is_unlimited", src, fixed = TRUE)
  }, logical(1)))
})
chk("★ 往下夹到下限（把内存设成 1MB 会让所有任务立刻 OOM）", {
  invisible(dsapp_user_set_limits(v6u, cpu_sec = 1, mem_mb = 1,
                                  max_procs = 1, con = v6con))
  l <- dsapp_user_limits(v6u, con = v6con)
  identical(l$cpu_sec, 60) && identical(l$mem_mb, 256) &&
    identical(l$max_procs, 16)
})
chk("★ 往上夹到上限（1e15 秒不是“不限”，是一个看起来设过了的错觉）", {
  invisible(dsapp_user_set_limits(v6u, cpu_sec = 1e15, mem_mb = 1e15,
                                  max_procs = 1e15, con = v6con))
  l <- dsapp_user_limits(v6u, con = v6con)
  identical(l$cpu_sec, 86400) && identical(l$mem_mb, 4 * 1024 * 1024) &&
    identical(l$max_procs, 65536)
})
chk("★ NULL 账号合出来的是平台默认（无主任务不能越权拿到某人的配额）", {
  c2 <- list(exec = list(cpu_sec = 3600, mem_mb = 8192, max_procs = 64))
  k <- dsapp_limits_for_user(NULL, cfg = c2, con = v6con)
  identical(k$cpu_sec, 3600) && identical(k$mem_mb, 8192)
})
chk("不存在的账号：limits 读得出来（全 NULL），不抛",
    is.null(dsapp_user_limits(999999L, con = v6con)$cpu_sec))
chk("dsapp_user_set_limits 自己**不写**审计（操作者另有其人，记在调用方）", {
  n0 <- DBI::dbGetQuery(v6con, "SELECT COUNT(*) n FROM audit_log")$n
  invisible(dsapp_user_set_limits(v6u, cpu_sec = 100, con = v6con))
  identical(as.integer(n0),
            as.integer(DBI::dbGetQuery(v6con,
              "SELECT COUNT(*) n FROM audit_log")$n))
})
chk("★ 资源上限真的进了 wrapper 脚本（设了不生效等于没设）", {
  w <- dsapp_wrapper_script("echo hi", cfg = cfg,
                            limits = list(cpu_sec = 123, mem_mb = 456,
                                          max_procs = 78))
  grepl("ulimit -t 123", w, fixed = TRUE) &&
    grepl("ulimit -v 466944", w, fixed = TRUE) &&
    # ⚠️ 进程数那一条现在是 `ulimit -u "$_np"`，不再是把数字直接写进 ulimit ——
    #    _np 先被 max(请求值, 当前 uid 线程数 + 余量) 抬过一次，理由见
    #    dsapp_wrapper_script 里那段。所以这里断言的是两件事：
    #    ① 请求的 78 确实落到了 _np 的初值上（没被吃掉）；
    #    ② ulimit 用的是 $_np，而不是某个写死的数（改回写死就等于把闸门
    #       变成"必然失败"，那正是 2026-09-14 踩的坑）。
    grepl("_np=78", w, fixed = TRUE) &&
    grepl('ulimit -u "$_np"', w, fixed = TRUE)
})
chk("★★ 进程数上限会被抬到「当前线程数 + 余量」（不抬就是必然 fork 失败）", {
  w <- dsapp_wrapper_script("echo hi", cfg = cfg, limits = NULL)
  # 量当前 uid 的那条命令在（而且按 uid 过滤，不是数全系统）
  grepl("ps -eL -o uid=", w, fixed = TRUE) &&
    grepl("id -u", w, fixed = TRUE) &&
    grepl(sprintf("_amb + %d", DSAPP_PROC_HEADROOM), w, fixed = TRUE) &&
    # 量不出来时必须**保持原上限**，不能因为量不出来就干脆不设限
    grepl('""|*[!0-9]*) ;;', w, fixed = TRUE)
})
chk("★ limits = NULL 时回落到 cfg$exec，不会变成没有上限", {
  w <- dsapp_wrapper_script("echo hi", cfg = cfg, limits = NULL)
  grepl(sprintf("ulimit -t %d", as.integer(cfg$exec$cpu_sec)), w, fixed = TRUE) &&
    grepl(sprintf("_np=%d", as.integer(cfg$exec$max_procs)), w, fixed = TRUE)
})
chk("★ 执行时钉住 BLAS/OMP 线程数（不钉的话每个任务按核数开线程）", {
  e <- dsapp_exec_env("", NULL, threads = 3)
  all(vapply(c("OMP_NUM_THREADS", "OPENBLAS_NUM_THREADS", "MKL_NUM_THREADS",
               "BLIS_NUM_THREADS", "VECLIB_MAXIMUM_THREADS",
               "NUMEXPR_NUM_THREADS"),
             function(k) identical(e[[k]], "3"), logical(1)))
})
chk("★ 线程数上限来自配置，且默认远小于核数（这台机器 60 核）", {
  identical(as.integer(cfg$exec$threads), dsapp_default_threads()) &&
    dsapp_default_threads() >= 1L && dsapp_default_threads() <= 8L &&
    # 0 / 负数要夹到 1。"不给上限"不是这里的一个选项 —— 那正是要避免的事。
    identical(dsapp_exec_env("", NULL, threads = 0)[["OMP_NUM_THREADS"]], "1") &&
    identical(dsapp_exec_env("", NULL, threads = -5)[["OMP_NUM_THREADS"]], "1") &&
    # NA 走 `%||%` 的语义（NULL / 长度 0 / NA 都算"没给"），回落到配置值 ——
    # 不是"1"，也不是"不限"。这是全仓库统一的约定，别在这里搞特殊。
    identical(dsapp_exec_env("", NULL, threads = NA)[["OMP_NUM_THREADS"]],
              as.character(as.integer(cfg$exec$threads)))
})

