chk("★ 按**归属**取任务：共享给别人的对话里的任务不算他的", {
  a_sid <- db_session_create("甲的对话", user_id = v6u, con = v6con)
  b_sid <- db_session_create("乙的对话", user_id = v6v, con = v6con)
  ta <- db_task_create("甲的任务", "1+1", "r", session_id = a_sid, con = v6con)
  invisible(db_task_create("乙的任务", "1+1", "r", session_id = b_sid,
                           con = v6con))
  invisible(db_session_share_set(a_sid, v6v, granted_by = v6u, con = v6con))
