  nrow(seen) == 2 && nrow(own) == 1 && identical(as.character(own$title[1]),
                                                 "乙的任务") &&
    identical(as.integer(ta), as.integer(own$id[1])) == FALSE
})
chk("★ 任务行里带得出对话标题（管理页要显示“在哪个对话里跑的”）", {
  r <- db_tasks_by_owner(v6u, con = v6con)
