chk("★ body 里含 } 不会被截断（取的是最后一个 }，不是第一个）", {
  r <- dsapp_skill_parse_json('{"name":"n","summary":"s","tags":"t","body":"a } b } c"}')
  identical(r$body, "a } b } c")
})
chk("不是 JSON 时明确报错，而不是返回半截",
    inherits(tryCatch(dsapp_skill_parse_json("模型今天不想干活"),
                      error = function(e) e), "error"))
chk("空返回报错",
    inherits(tryCatch(dsapp_skill_parse_json(""), error = function(e) e), "error"))
chk("缺 name 的返回报错",
    inherits(tryCatch(dsapp_skill_parse_json('{"body":"只有正文"}'),
                      error = function(e) e), "error"))

# ---- 源码级：接线有没有接上 ----
#
# ⚠️ V13.7 item 5：这一段**搬家了**。原来「把技能塞进系统提示词」写在
#    mod_chat.R 的 dsapp_llm_begin() 里，现在归 R/llm.R 的
#    dsapp_scene_messages() —— 因为脱离会话的后台续跑要拼**同一份**上下文。
#    留在对话页里的话它只能再抄一遍，而抄出来的那份迟早跟这边分叉，分叉的
#    表现是「挂机跑一夜」和「盯着跑」得到两种结果 —— 那种差异没人会去比对。
#
#    断言跟着搬，而且**多钉一条**：搬家之后新冒出来的风险不是「没人查技能」
#    了（那个函数体里一目了然），是「抽出去了、但有一条路忘了改过来调它」。
#    两边各拼各的，源码上看起来都挺对。所以下面既钉共用函数里接没接，
#    也钉两条路是不是都走它。
# ⚠️ 这份源码在这里**现读**，不复用文件后面那个 src_llm_v131（它在 1 万行
#    开外，这会儿还不存在）。别为了省一行把它提到前面去：那个变量名带着
#    版本号，属于另一节，挪了会让两节的边界糊掉。
src_llm_sm <- paste(readLines("R/llm.R", warn = FALSE), collapse = "\n")
sm_blk <- dsapp_block_at(src_llm_sm,
                         regexpr("dsapp_scene_messages <- function", src_llm_sm))
chk("抠到了 dsapp_scene_messages 的函数体", nzchar(sm_blk))
# ⚠️ 原来是 `grepl("skills = dsapp_skills_prompt")` 一个整串 —— 搬过来时我在
#    中间套了一层 tryCatch（技能查不出来不该把整轮对话一起带走），那个整串
#    就再也匹配不上了，**而代码是对的**。所以拆成两条：有这个实参，且它的值
#    确实来自 dsapp_skills_prompt()。盯"接线接上了"用不着钉一整行字面串。
chk("★ 技能传给了 build_system_prompt",
    grepl("skills\\s*=", sm_blk) &&
      grepl("dsapp_skills_prompt(", sm_blk, fixed = TRUE))
# ⚠️ 这一条盯的是「每轮现查」。查询必须**在函数体里**（每次调用真的跑一次），
#    不能挪到形参默认值上、也不能在外面算一次再传进来 —— 那两种写法在源码上
#    都很像"接了线"，行为却差一整轮对话。
chk("★ 技能是每轮现查的，不是只在建会话时算一次",
    grepl("dsapp_skills_prompt(sid", sm_blk, fixed = TRUE))

src_chat <- paste(readLines("R/mod_chat.R", warn = FALSE), collapse = "\n")
chk("★★ 对话页拼上下文走的是 dsapp_scene_messages",
    grepl("dsapp_scene_messages(", src_chat, fixed = TRUE))
# ⚠️ 剥注释再比。这一条是**否定式**的，而搬家时我在对话页留了注释解释
#    "为什么这里不再调 build_system_prompt" —— 那种注释里必然写着这个函数名，
#    不剥的话，注释写得越清楚断言越红（这个坑在本文件里已经踩到第三次了）。
chk("★★ 对话页里不再自己调 build_system_prompt（自己拼=两份迟早长歪）",
    !grepl("build_system_prompt(", strip_comments(src_chat), fixed = TRUE))
src_detach <- paste(readLines("R/detach.R", warn = FALSE), collapse = "\n")
chk("★★ 脱离会话的后台续跑拼的是**同一份**上下文（这是本次抽函数全部的理据）",
    grepl("dsapp_scene_messages(", src_detach, fixed = TRUE))

src_skills <- paste(readLines("R/mod_skills.R", warn = FALSE), collapse = "\n")
# ⚠️ 这条盯的是本仓库踩过两次的坑：在 renderUI 里按行注册 observer，
#    Shiny 不会在下次重渲染时销毁上一次那批（mod_files.R:408 有详细说明）。
chk("★★ 技能页没在列表渲染里动态注册 observer",
    !grepl("observeEvent\\(input\\[\\[paste0\\(", src_skills))
chk("技能页走的是单一分派 input（sk_act）",
    grepl("input$sk_act", src_skills, fixed = TRUE))
chk("★ 行内动作的 id 来自浏览器，做了整数收敛",
    grepl("suppressWarnings\\(as\\.integer\\(parts\\[\\[2\\]\\]\\)\\)", src_skills))

# ⚠️ "按钮画出来了，但没人接" —— V8 item 1 的第一版就是这样：工具栏上
#    「新建」按钮画好了，`observeEvent(input$new)` 忘了写。点下去浏览器
#    确实把 input 发了上来，服务端一条日志都没有（没人接当然不报错），
#    界面上就是"点了没反应"。离线的功能断言**全绿**，只有真的去点才看得出来
#    （tests/ui_v8/skills.py 抓到的）。所以这里把"每个按钮都要有 handler"
#    变成一条源码级断言。
sk_btns <- regmatches(src_skills,
  gregexpr('actionButton\\(ns\\("[a-zA-Z0-9_]+"\\)', src_skills))[[1]]
sk_btns <- sub('^actionButton\\(ns\\("', '', sub('"\\)$', '', sk_btns))
sk_btns <- unique(sk_btns)
chk(sprintf("抠到了技能页的按钮（%d 个：%s）",
            length(sk_btns), paste(sk_btns, collapse = ", ")),
    length(sk_btns) >= 8)
sk_nohandler <- sk_btns[!vapply(sk_btns, function(b)
  grepl(paste0("observeEvent\\(input\\$", b, "[^a-zA-Z0-9_]"), src_skills),
  logical(1))]
chk(sprintf("★★ 每个按钮都有对应的 observeEvent（没接的：%s）",
            if (length(sk_nohandler)) paste(sk_nohandler, collapse = ", ") else "无"),
    length(sk_nohandler) == 0)

src_app <- paste(readLines("app.R", warn = FALSE), collapse = "\n")
# ★ V13.11 item 3：左栏改成从 DSAPP_NAV_ITEMS 渲染之后，这里不能再抠
#   app.R 里的字面量 —— 但"有没有这一项"这件事照样要钉（加新页时忘了往
#   表里加 = 页签在、入口不在，用户根本点不到）。
chk("★ 左栏有「技能」导航项",
    "skills" %in% vapply(DSAPP_NAV_ITEMS, function(x) x$value, character(1)))
chk("★ 导航项和 nav_panel 的 value 对得上",
    grepl('nav_panel\\("技能", value = "skills"', src_app))
chk("技能页的 server 注册了", grepl('mod_skills_server\\("skills"', src_app))
chk("mod_skills.R 在 source 列表里", grepl('"mod_skills.R"', src_app, fixed = TRUE))

section("任务区 ↔ 文件区互通（V8 item 5）")

# 这一节盯的是 2026-09-15 抓到的一个**静默错值**：
#
# mod_files.R 里 `for (k in 0:DSAPP_CRUMB_MAX)` 是写在 moduleServer 顶层的。
# R 的 for 循环变量落在**函数环境**里，循环跑完不消失 —— `k` 于是恒等于 12L，
# 而它在上百行之外是可见的。ws_group_ui() 里想取"这一组的任务号"，写的是 `k`：
#   · 每个分组上的链接都渲染成「任务 #12」（12 是面包屑的段数上限，不是任务号）；
#   · 点下去永远跳 12 号任务，界面上弹的是"没找到任务 #12"；
#   · "从任务页跳过来自动展开那一组"那条判断也拿 12 去比，从来没生效过。
#
# 它不报错、不告警，离线的功能断言全绿 —— 只有真的去点一下才看得出来
# （tests/ui_v8/crossnav.py）。下面这几条就是那次踩坑钉下来的。
src_files <- paste(readLines("R/mod_files.R", warn = FALSE), collapse = "\n")
chk("★★ 面包屑的循环变量不叫 k（顶层 for 的变量会漏出去给所有闭包看见）",
    grepl("for (crumb_lvl in 0:DSAPP_CRUMB_MAX)", src_files, fixed = TRUE) &&
      !grepl("for (k in", src_files, fixed = TRUE))
# ⚠️ 用 all.names(parse()) 而不是正则扫源码：上面那段说明里就写着一个
#    `k`（讲的就是这个坑），正则扫会把注释里的它算进来，这条断言就永远红。
#    parse() 丢掉注释，all.names() 递归取出所有符号名 —— 数的是**代码**。
chk("★★ mod_files.R 的代码里没有游离的 k（有就是又接到了那个漏出来的变量上）",
    !("k" %in% all.names(parse("R/mod_files.R"))))
# 分组上的「任务 #N」必须来自这一组自己的任务号。
grp_blk <- dsapp_pull(src_files, "ws_group_ui <- function\\(g, idx\\) \\{")
chk("抠到了 ws_group_ui", nzchar(grp_blk))
chk("★★ 分组上的任务链接用的是这一组自己的任务号（key = g$task_id）",
    grepl('sprintf("任务 #%d", key)', grp_blk, fixed = TRUE) &&
      grepl('"gotask", as.character(key)', grp_blk, fixed = TRUE))
chk("★★ 自动展开比的是同一组自己的任务号，不是别的变量",
    grepl("identical(as.integer(want$task_id), as.integer(key))", grp_blk,
          fixed = TRUE) &&
      grepl("key > 0", grp_blk, fixed = TRUE))

# ---------------------------------------------------------------------------
# 跳到任务页之后"把那条任务勾上"这一步，不能用 DT::selectRows()
# ---------------------------------------------------------------------------
#
# 任务表的 selection = "none"（勾选交给 Select 扩展，理由见 output$tbl 的
# 注释）。而 DT 的 methods.selectRows **整个定义在** datatables.js 的
# `if (inArray(selMode, ['single','multiple']))` 里面 —— mode 是 "none"
# 时这个函数压根没被定义，proxy 消息发到浏览器没人接。
#
# 这是最难受的一种坏法：R 那边不报错（它只是把消息发出去，而且发成功了）、
# try() 也 catch 不到、浏览器控制台一片安静 —— 表现就是"跳过来了，详情卡
# 还写着'在左侧选择一条记录查看详情'"。2026-09-15 浏览器实测抓到的就是它，
# 当时离线的功能断言全绿。所以下面这几条盯住"别再退回去"。
src_tasks <- paste(readLines("R/mod_tasks.R", warn = FALSE), collapse = "\n")
js_app <- paste(readLines("www/app.js", warn = FALSE), collapse = "\n")

# ⚠️ 只看**代码**，不看注释：上面那段说明里就写着 `DT::selectRows` 这个名字，
#    用正则扫源码会把讲解它的注释也算成"用了它"，这条断言就永远红。
#    parse() 丢注释，all.names() 取符号 —— 但它取不到 `DT::selectRows` 这种
#    带 :: 的调用名（会拆成 DT / selectRows 两个符号），所以这里按调用形态
#    在**去掉注释之后**的文本上找。
strip_comment_lines <- function(txt) {
  paste(grep("^\\s*#", strsplit(txt, "\n", fixed = TRUE)[[1]],
             invert = TRUE, value = TRUE), collapse = "\n")
}
tasks_code <- strip_comment_lines(src_tasks)
chk("★★ 没用 DT::selectRows / selectPage 去勾任务表（selection=\"none\" 下它们是空操作）",
    !grepl("selectRows", tasks_code, fixed = TRUE) &&
      !grepl("selectPage", tasks_code, fixed = TRUE) &&
      !grepl("dataTableProxy", tasks_code, fixed = TRUE))
chk("★★ 改用自定义消息，让前端走 Select 扩展自己的 API",
    grepl('session$sendCustomMessage("dsapp:dtselect"', tasks_code,
          fixed = TRUE) &&
      grepl('id = session$ns("tbl")', tasks_code, fixed = TRUE))
# 前端那一半：消息得有人接，而且必须落在 Select 扩展上（不是 DT 的选中）
chk("★★ app.js 里接了 dsapp:dtselect", grepl(
  'Shiny.addCustomMessageHandler("dsapp:dtselect"', js_app, fixed = TRUE))
chk("★★ 前端是调 Select 扩展的 rows().select()，不是自己加 class",
    grepl("api.rows(row).select()", js_app, fixed = TRUE))
# 翻页：目标在第 2 页往后时不翻页 = "勾上了但屏幕上根本看不到"
chk("★ 勾之前先翻到目标那一页（用表自己的页长，不写死 12）",
    grepl("api.page.info().length", js_app, fixed = TRUE) &&
      grepl("api.page(p).draw(false)", js_app, fixed = TRUE))
# 先清掉别的勾：详情卡认的是**行号最小的那条**，留着上面原有的勾，
# "跳到第 5 条"会变成详情卡还停在第 1 条上
chk("★ 勾之前先清掉别的勾（不然详情卡认的是行号最小的那条）",
    grepl("api.rows().deselect()", js_app, fixed = TRUE))

# =============================================================================
section("V10 item 2：库结构对账（no such table: consent_log 那个事故）")
# =============================================================================
#
# 2026-09-15 线上：用户点了「同意并继续」，界面回
#    没能记录你的确认，请重试。如果一直失败请联系管理员。（no such table: consent_log）
# 然后被须知闸门永久挡在应用外面。而**自检全绿**。
#
# 根因是两件单独看都对的事凑在一起：
#   ① dsapp_db() 把连接缓存在**进程级**的 .dsapp_state 里；
#   ② 建表只在**建连接那一刻**跑一次。
# 这台机器上改了 R/*.R 之后 R 进程**不重启**（Shiny Server 在同一进程里
# 重新求值），于是新代码手里攥着的是上一版代码建的连接。
#
# 所以下面这几条测的不是"建表语句写对了没"，而是**手里这个连接对不对**。
# 测试实例每次都是新进程，天然走不到那条路上 —— 必须在这里造出来。
db_src <- paste(readLines("R/db.R", warn = FALSE), collapse = "\n")

chk("★★ 有 DSAPP_SCHEMA_VERSION 这个常量（加表/加列必须 +1 的那个）",
    exists("DSAPP_SCHEMA_VERSION") &&
      is.numeric(DSAPP_SCHEMA_VERSION) && DSAPP_SCHEMA_VERSION >= 1)
chk("★ dsapp_db() 缓存命中时会对一次账（少了这句，事故原样复现）", {
  # ⚠️ 这里不能用 dsapp_pull()：它的终止条件是「4 空格缩进的 }」，那是
  #    observeEvent / renderUI 那种块的收尾。而 dsapp_db 里这个 if 收在
  #    2 空格缩进上 —— 抠出来是空串，断言永远红，且红得毫无道理。
  j <- regexpr("dsapp_db <- function", db_src, fixed = TRUE)[1]
  fn <- if (j > 0) substr(db_src, j, j + 1800L) else ""
  # 位置也要管：这一句必须排在 return(st$db) **之前**。写在后面等于没写，
  # 而且不会有任何症状 —— 正是这次事故的形态。
  m <- regexpr("dsapp_db_migrate(st$db)", fn, fixed = TRUE)[1]
  r <- regexpr("return(st$db)", fn, fixed = TRUE)[1]
  m > 0 && r > 0 && m < r
})
chk("★ 对账的稳态开销是内存比较（先比 st$schema_v，没变就返回）", {
  i <- regexpr("dsapp_db_migrate <- function", db_src, fixed = TRUE)[1]
  fn <- if (i > 0) substr(db_src, i, i + 900L) else ""
  g <- regexpr("identical(st$schema_v, DSAPP_SCHEMA_VERSION)", fn,
               fixed = TRUE)[1]
  l <- regexpr("PRAGMA user_version", fn, fixed = TRUE)[1]
  g > 0 && l > 0 && g < l          # 常量比对上就先走了，不查库
})

# ---- 造出「连接是上一版代码建的」那个现场 --------------------------------
mig_cfg <- cfg
mig_cfg$data_root <- file.path(tmp, "migroot")
mig_cfg$db_path   <- file.path(mig_cfg$data_root, "dsapp.sqlite3")

chk("★★ 连接缓存命中时，库里缺的表会被补齐（旧连接 + 新代码 = 自愈）", {
  dir.create(mig_cfg$data_root, showWarnings = FALSE, recursive = TRUE)
  dsapp_db(mig_cfg)                        # 建连接，全表都在
  con <- dsapp_db(mig_cfg)
  # 把现场倒回去：像 V8 那样——没有 consent_log，库头也没记版本
  DBI::dbExecute(con, "DROP TABLE IF EXISTS consent_log")
  DBI::dbExecute(con, "PRAGMA user_version = 0")
  st <- dsapp_state()
  st$schema_v <- NULL                      # 这个连接"还没按当前代码补过表"
  n_before <- nrow(DBI::dbGetQuery(con,
    "SELECT name FROM sqlite_master WHERE name = 'consent_log'"))
  con2 <- dsapp_db(mig_cfg)                # ← 就是线上那一次调用
  n_after <- nrow(DBI::dbGetQuery(con2,
    "SELECT name FROM sqlite_master WHERE name = 'consent_log'"))
  n_before == 0L && n_after == 1L
})

chk("★ 补齐之后库头记上了版本（下次不用再补）", {
  con <- dsapp_db(mig_cfg)
  identical(as.integer(DBI::dbGetQuery(con, "PRAGMA user_version")[[1]]),
            as.integer(DSAPP_SCHEMA_VERSION))
})

# ---- 第二层保险：常量忘了抬的时候 ----------------------------------------
# 主修那条路有个前提 —— 代码里的常量得变。真有人加表却忘了抬常量，
# 症状会和事故**一模一样**。所以 dsapp_tos_record 里还有一条：
# INSERT 报"表不存在"时补建一次再试。
chk("★★ 常量没变、表却不在时，写同意日志依然成功（第二层保险）", {
  con <- dsapp_db(mig_cfg)
  # schema_v 保持"已对过账"的样子，模拟"常量忘了抬"——对账不会救它
  DBI::dbExecute(con, "DROP TABLE IF EXISTS consent_log")
  ok <- tryCatch({
    dsapp_tos_record(1L, source = "weekly", version = "9.9", con = con)
    TRUE
  }, error = function(e) {
    cat("       写失败：", conditionMessage(e), "\n"); FALSE
  })
  n <- nrow(DBI::dbGetQuery(con,
    "SELECT id FROM consent_log WHERE user_id = 1"))
  ok && n == 1L
})
chk("★★ 只对「表/列不存在」重试；别的错误原样抛出去（不能拿重试掩盖真因）", {
  i <- regexpr("dsapp_tos_record <- function", db_src, fixed = TRUE)[1]
  # 函数在 R/tos.R，不在 db.R —— 换文件找
  tos_src <- paste(readLines("R/tos.R", warn = FALSE), collapse = "\n")
  j <- regexpr("dsapp_tos_record <- function", tos_src, fixed = TRUE)[1]
  fn <- if (j > 0) substr(tos_src, j, j + 2200L) else ""
  g <- regexpr('grepl("no such table|no such column"', fn, fixed = TRUE)[1]
  s <- regexpr("stop(e)", fn, fixed = TRUE)[1]
  g > 0 && s > 0 && s < g + 400L && grepl("dsapp_tos_schema(con)", fn,
                                          fixed = TRUE)
})

# 把连接换回主库，后面的检查都还要用它
st <- dsapp_state(); st$db <- NULL; st$db_path <- NULL
chk("★ 换回主库之后连接可用", DBI::dbIsValid(dsapp_db(cfg)))

# =============================================================================
section("V10 item 1：用户须知改成 Markdown 渲染")
# =============================================================================
#
# 用户的原话：「data/user_must_know_V1.txt 里有新的用户须知，更新下，注意
# markdown 标记要能正常渲染」。V9 那版把 `##` 和 `**` 原样打在屏幕上，
# 当时的注释还振振有词地说"须知要逐字读、不过渲染器" —— 那不是逐字，
# 那是没渲染。下面这几条钉住"真的渲染了"，而不是"渲染器的调用写对了"。
tos_src <- paste(readLines("R/tos.R", warn = FALSE), collapse = "\n")
# V11：渲染那三步（转义 → commonmark → 链接白名单）现在只有一份实现，
# 在 render.R 的 dsapp_md_html() 里，用户须知和文件预览都转调它。
md_src <- paste(readLines("R/render.R", warn = FALSE), collapse = "\n")

chk("★ 旧的分节结构没了（dsapp_tos_sections 是 V9 写死正文的写法）",
    !grepl("dsapp_tos_sections", tos_src, fixed = TRUE))
chk("★ 正文优先读数据目录里的文件（运维改条款不用改代码 + 重新部署）",
    grepl("dsapp_tos_file", tos_src, fixed = TRUE) &&
      # ⚠️ fixed = TRUE 下模式是**字面**的：R/tos.R 那一行源码里写的就是
      #    \\. （反斜杠 + 点，两个字符），所以这里要写四个反斜杠。
      #    不写 fixed 就更糟 —— 它变成正则，\\ 匹配一个反斜杠、. 匹配任意
      #    字符，等于在找 "V1\<任意>txt"，永远不命中。V9 已经踩过同一个坑
      #    （见 selftest 里 run_cid 那段注释），这次是第二次。
      grepl("^user_must_know_V[0-9]+\\\\.txt$", tos_src, fixed = TRUE) &&
      grepl("dsapp_tos_default_text()", tos_src, fixed = TRUE))
chk("★★ 渲染顺序是先转义再交给 commonmark（commonmark 会原样放行原始 HTML）", {
  # ⚠️ V11：这段逻辑从 dsapp_tos_html 搬到了 render.R 的 dsapp_md_html()，
  #    文件预览的 .md 分支、对话消息、用户须知现在共用同一份实现。断言的
  #    对象跟着搬 —— 守的还是同一件事（喂进渲染器的是转义之后的文本），
  #    只是从"守一处"变成了"守唯一那处"。
  #
  # ⚠️ V15.2 又搬了一次：转义那一步从 dsapp_md_html() 挪进了
  #    .dsapp_md_html_raw()，好让"内联图片"能插在渲染之后、消毒之前
  #    （理由写在那个函数头上）。断言再次跟着搬 —— 守的还是同一件事。
  #    再搬（或把转义挪出这个函数）的时候这条会红，那是**对的**：
  #    它要的就是"喂给 commonmark 的必须是转义过的文本"这个不变式有人在盯。
  i <- regexpr(".dsapp_md_html_raw <- function", md_src, fixed = TRUE)[1]
  fn <- if (i > 0) substr(md_src, i, i + 1600L) else ""
  # ⚠️ 不能比"谁在源码里出现得早"。调用写的是
  #        commonmark::markdown_html(
  #          dsapp_escape(txt), …)
  #    渲染器的名字**在前**，比位置必然红 —— 而代码是对的。
  #    要比的是"喂给它的到底是不是转义之后的文本"，那才是这条断言的意思。
  # ★ V15.3：转义和 commonmark 之间**多了一步** dsapp_md_allow_tags()（把
  #   白名单里的无属性排版标签从 &lt;x&gt; 还原回 <x>，理由见 R/render.R）。
  #   链变成 escape → allow_tags → commonmark，断言跟着改。
  #   ⚠️ 但**不许**放宽成"fn 里有 dsapp_escape 就行" —— 那样"转义被挪到
  #      commonmark 之后"也会绿，而那正是这条要挡的事。
  # ★ V15.4：中间又多了一步 dsapp_md_allow_img()（item 5，放行带属性的 <img>），
  #   而且这几步挪进了本地变量 `esc`（原来是一行套一行的写法）。
  #   ⚠️ 这条仍然是**形状**哨兵，所以形状变了就得跟着改 —— 但改的时候要盯住的
  #      东西没变：**`dsapp_escape(txt)` 必须排在那两步之前、commonmark 之前**。
  #      实测它就是靠"形状"在 V15.3 抓住过一次真实的错位（见上面那段注释）。
  nzchar(fn) &&
    grepl("esc\\s*<-\\s*dsapp_md_allow_tags\\(dsapp_escape\\(txt\\)\\)", fn) &&
    grepl("dsapp_md_allow_img\\(esc\\)", fn) &&
    grepl("markdown_html\\(esc", fn)
})

# 真的渲染一遍这个共用实现 —— 不只是"调用写对了"。
chk("★★ dsapp_md_html 挡住原始 HTML 但放行 Markdown", {
  h <- dsapp_md_html("# 标题\n\n**粗** 和 <script>alert(1)</script>\n")
  grepl("<h1", h, fixed = TRUE) &&
    grepl("<strong>粗</strong>", h, fixed = TRUE) &&
    grepl("&lt;script&gt;", h, fixed = TRUE) &&
    !grepl("<script", h, fixed = TRUE)
})

# 真的渲染一遍 —— 不验"调用了渲染器"，验**渲染出来的东西**。
chk("★★ 须知正文渲染出 <h2> 和 <ol>（真渲染，不是把标记打到屏幕上）", {
  h <- dsapp_tos_html()
  grepl("<h2", h, fixed = TRUE) && grepl("<ol", h, fixed = TRUE) &&
    grepl("<strong>", h, fixed = TRUE)
})
chk("★★ 渲染结果里没有残留的字面 '##' / '**'（V9 的界面就是这样）", {
  h <- dsapp_tos_html()
  !grepl("##", h, fixed = TRUE) && !grepl("**", h, fixed = TRUE)
})
chk("★★ 渲染出来的是**这份条款**，不是一段占位文字", {
  # ⚠️ 别用长度当判据。nchar() 数的是**字符**，而五千多字节的中文只有
  #    1986 个字符 —— 按字节写了 >2000，这条就永远红，而且红得看不出原因。
  #    认几个只在用户那份文件里出现的词，比认长度结实：渲染器接错了、
  #    回落到别处的文本、读到一半断了，都会在这里现形。
  h <- dsapp_tos_html()
  heads <- c("服务说明", "账号与密钥安全", "数据与隐私", "免责声明",
             "协议变更与联系我们", "Biomamba_zhushou")
  all(vapply(heads, function(k) grepl(k, h, fixed = TRUE), logical(1))) &&
    nchar(dsapp_tos_text()) > 1500
})
# ---- Test_V16.11 item 6：须知加一级分组标题 --------------------------------
#
# 用户的原话：「登录时用户需要确认的信息只有二级标题，请生成对应的一级标题」。
# 改之前正文里**一个 `#` 都没有** —— 十个章全是 `##`，屏幕上十个平级的标题。
# 改法是新增 4 个 `#` 把十章归纳成四块；"一、服务说明"这些汉字编号**一个字没动**，
# 只是语义上降了一级。
#
# ⚠️ 这条改动有个不显眼的连带后果：**正文指纹跟着变 ⇒ 所有人重新确认一次**。
#    用户是在看到这条警告之后选的做法，所以下面顺带把版本号也钉住 ——
#    不抬的话 mod_tos_gate 那句 sprintf 会打出「同意的是 2.1 版，当前是 2.1 版」
#    这种自相矛盾的话（理由写在 R/tos.R 顶部那段注释里）。
#
# ⚠️ 下面几条读的是**仓库里那份文件**（`data/user_must_know_V*.txt`），
#    不是 dsapp_tos_text()、也**不是** dsapp_tos_file()。分工是这样的：
#    dsapp_tos_text() 在文件缺失时回落到内嵌兜底，而"兜底那份和文件逐字一致"
#    是紧挨着的另一条断言；两条合起来才等于"屏幕上看到的就是这个结构"。
#
# ⚠️⚠️ 为什么不走 dsapp_tos_file()：**它在这个进程里永远返回 NULL**。
#    自检开头把 DSAPP_DATA_ROOT 指到一个**空的临时目录**（:136），而
#    dsapp_tos_file() 正是在数据根下找这个文件名。于是任何写成
#    `f <- dsapp_tos_file(); if (is.null(f)) TRUE else …` 的断言
#    **一次都不会真正比过**，却一直挂着绿勾 —— 底下"内嵌兜底逐字一致"
#    和"改一个字指纹就变"那两条 ★★ 就是这么来的，从 V11 摆到现在
#    （item 6 加断言时当场撞上：我这块原来也写成顶层 readLines()，
#     文件为 NULL → `'con' is not a connection` → **整个自检当场中断**，
#     后面的几百条一条没跑，而屏幕上 0 个 ✗，看着像"全过"）。
#    ⇒ 这两条一并改成读仓库文件，并且**读不到就算红**，不再静默跳过。
tos_ship <- local({
  fs <- list.files("data", pattern = "^user_must_know_V[0-9]+\\.txt$",
                   full.names = TRUE)
  if (!length(fs)) NULL
  else fs[order(as.integer(sub(".*_V([0-9]+)\\.txt$", "\\1", fs)),
                decreasing = TRUE)][1]
})
tos_lines <- if (is.null(tos_ship)) character(0) else
  readLines(tos_ship, warn = FALSE, encoding = "UTF-8")
# ⚠️ 只认**行首**的 `#`：`grep("^#\\s+[^#]")` 里那个 `[^#]` 是必须的，否则
#    `## 一、服务说明` 会被同一条模式吃进一级标题里（`^#\s+` 之后正好是个 `#`）。
tos_h1 <- sub("^#\\s+", "", grep("^#\\s+[^#]", tos_lines, value = TRUE))
tos_h2 <- sub("^##\\s+", "", grep("^##\\s", tos_lines, value = TRUE))

chk("★★ item 6：正文第一行就是 '# 用户须知'（CSS 靠 > h1:first-child 认文档题）", {
  # ⚠️ 这条不是洁癖。样式表里文档题那条规则写的是 `.dsapp-tos-md > h1:first-child`
  #    —— Markdown 写不出类名，只能按"是不是第一个孩子"来认。正文第一行要是
  #    不是 h1，那条规则**静默失效**（不报错、CSS 语法也合法），文档题就退化成
  #    和分组一个字号。而这个退化，除了这条之外自检里没有任何东西看得见。
  identical(trimws(tos_lines[1]), "# 用户须知")
})
chk("★★ item 6：一级标题正好 5 个 = 文档题 + 四个分组，顺序也对", {
  identical(tos_h1, c("用户须知", "第一部分　总则", "第二部分　使用与责任",
                      "第三部分　数据与隐私", "第四部分　终止与免责"))
})
chk("★★ item 6：十个二级章一个不少、顺序不变（归纳分组时最容易手滑吞掉一章）", {
  identical(tos_h2, c("一、服务说明", "二、账号与密钥安全", "三、使用规范",
                      "四、费用与计费", "五、数据与隐私", "六、服务可用性",
                      "七、账号与服务终止", "八、知识产权", "九、免责声明",
                      "十、协议变更与联系我们"))
})
chk("★★ item 6：渲染出来真的是 5 个 <h1> / 10 个 <h2>（不是只在文件里写了 `#`）", {
  # 真渲染一遍再数。commonmark 认不认那个 `#`（行首多一个空格就成了正文）、
  # 渲染管线有没有在哪一步把 h1 滤掉，只有数**渲染结果**才知道。
  # 顺带这条还把 9653 那条 `<h2` 的断言从"有没有"升级成"有几个"。
  h <- dsapp_tos_html()
  n_h1 <- length(regmatches(h, gregexpr("<h1", h, fixed = TRUE))[[1]])
  n_h2 <- length(regmatches(h, gregexpr("<h2", h, fixed = TRUE))[[1]])
  n_h1 == 5L && n_h2 == 10L
})
chk("★★ item 6：CSS 给三级**不同**的字号，而且是从大到小", {
  # ★ 这次改动的**实质**就是分层。正文里多两个 `#` 而屏幕上一样大，
  #   用户看到的就是"你没改"—— 一个不改变行为的改动等于没改。
  # ⚠️ 必须先把 /* */ 注释剥掉再找规则：上面那段说明里就写着 `> h1:first-child`
  #    和 `.dsapp-tos-md`，不剥的话"这条规则在不在"会被**注释**答成"在"
  #    （本仓在 R 源码上连踩三次同一个坑，见注释里的账）。
  #    ⚠️ strip_comments() 认的是 R 的 `#`，对 CSS 不管用，得自己写一个。
  css <- gsub("/\\*[\\s\\S]*?\\*/", "",
              paste(readLines("www/app.css", warn = FALSE), collapse = "\n"),
              perl = TRUE)
  # 从选择器取到**下一个 }**。这几条规则都很短，够用，而且不依赖
  # dsapp_block_at 那个"匹配必须正好停在 { 上"的约定。
  fs_of <- function(sel) {
    i <- regexpr(sel, css, fixed = TRUE)[1]
    if (i < 0) return(NA_character_)
    blk <- substring(css, i)
    j <- regexpr("}", blk, fixed = TRUE)[1]
    if (j < 0) return(NA_character_)
    blk <- substr(blk, 1L, j - 1L)
    k <- regexpr("font-size:\\s*[0-9.]+rem", blk)
    if (k[1] < 0) return(NA_character_)
    sub("^font-size:\\s*", "", regmatches(blk, k))
  }
  doc <- fs_of(".dsapp-tos-md > h1:first-child")   # 文档题
  grp <- fs_of(".dsapp-tos-md h1 {")               # 四个分组
  h2s <- fs_of(".dsapp-tos-md h2,")                # 十个章
  num <- function(x) suppressWarnings(as.numeric(sub("rem$", "", x)))
  !is.na(doc) && !is.na(grp) && !is.na(h2s) &&
    length(unique(c(doc, grp, h2s))) == 3L &&
    # ⚠️ 不能只判"互不相同" —— 文档题比分组**小**也是错的。
    identical(num(c(doc, grp, h2s)), sort(num(c(doc, grp, h2s)), decreasing = TRUE))
})
chk("★★ item 6：显示版本抬到了 2.1（指纹一定变了，版本号不抬会说胡话）", {
  # 指纹变了 ⇒ 所有人重新确认一次，这是**已知且用户同意**的后果。
  # 但要是只改正文不抬这个常量，闸门那句 sprintf 会打出
  # 「你同意的是 2.0 版，当前是 2.0 版」—— 自相矛盾，用户只会来问"那到底变没变"。
  identical(DSAPP_TOS_VERSION, "2.1")
})

chk("★★ 内嵌兜底那份和仓库里那份文件逐字一致", {
  # ⚠️⚠️ 原来写的是 `f <- dsapp_tos_file(); if (is.null(f)) TRUE else …`，
  #    而自检把 DSAPP_DATA_ROOT 指到了空临时目录（:136）⇒ **f 恒为 NULL**
  #    ⇒ 这条 ★★ 从 V11 起**一次都没真正比过**，却一直是绿勾。
  #    改成读仓库那份（= 生产数据目录那份，`.Renviron` 写的就是 <仓库>/data），
  #    并且读不到**算红** —— 静默跳过比断言写错更难发现。
  if (!length(tos_lines)) FALSE else
    identical(paste(tos_lines, collapse = "\n"), dsapp_tos_default_text())
})
chk("★★ 没有 commonmark 时退化成正文本，不是开天窗", {
  # V11：同上，兜底跟着实现搬到了 dsapp_md_html()。V15.2 再搬到
  # .dsapp_md_html_raw()（和上面那条同一个原因）。
  i <- regexpr(".dsapp_md_html_raw <- function", md_src, fixed = TRUE)[1]
  fn <- if (i > 0) substr(md_src, i, i + 1400L) else ""
  grepl('requireNamespace("commonmark"', fn, fixed = TRUE) &&
    grepl('collapse = "<br>"', fn, fixed = TRUE)
})

# ---- 版本：给人看的 / 存库比对的，是两个东西 ------------------------------
chk("★★ 存库比对用的是「显示版本 + 正文指纹」，不是裸版本号", {
  k <- dsapp_tos_version_key()
  grepl("^", k) && grepl("+", k, fixed = TRUE) &&
    identical(dsapp_tos_version_show(), DSAPP_TOS_VERSION)
})
chk("★★ 正文改一个字，指纹就变（改了条款又忘了抬版本号，也必须重问）", {
  # ⚠️ 同上面两条：原来走 dsapp_tos_file()，在自检里恒为 NULL ⇒ 从没比过。
  #
  # ⚠️ 现在改的是**临时数据根里的副本**，生产那份一个字节都不碰。要证的是
  #    "指纹是从正文算出来的"这个**机制**，机制跟文件在哪个目录无关；
  #    而"改生产文件再还原"多出来的那点保真度，换的是"自检可能会把线上
  #    条款改坏"的风险 —— 本仓在这上面栽过（自检把两行技能种进生产库）。
  if (is.null(tos_ship)) FALSE else {
    dst <- file.path(tmp, basename(tos_ship))
    # ⚠️ 必须用 tryCatch(finally=)，**不能**用 on.exit：这个 {} 是 chk() 的
    #    实参，惰性求值发生在 chk 内部，on.exit 挂到的是别人的栈帧，
    #    永远不会执行（本仓"顶层 { } 里的 on.exit 永远不执行"的同一类）。
    tryCatch({
      file.copy(tos_ship, dst, overwrite = TRUE)
      before <- dsapp_tos_version_key()          # 副本在位 → 算的是副本
      bak <- readLines(dst, warn = FALSE, encoding = "UTF-8")
      bak[length(bak)] <- paste0(bak[length(bak)], " 本行用于自检。")
      conw <- file(dst, open = "wb", encoding = "UTF-8")
      writeLines(bak, conw, useBytes = TRUE); close(conw)
      # ⚠️ 先确认"那个字真的改上去了"。不确认的话，写失败会让 before == after，
      #    这条就报"指纹没变"—— 而真正的问题是**变异没生效**。
      #    （本仓的账：一个不改变行为的改动证明的是零。）
      wrote <- grepl("本行用于自检。",
                     paste(readLines(dst, warn = FALSE, encoding = "UTF-8"),
                           collapse = "\n"), fixed = TRUE)
      after <- dsapp_tos_version_key()
      wrote && !identical(before, after)
    }, finally = unlink(dst))
  }
})
chk("★ 界面上只显示 '2.1'，不是 '2.1+7f3a2c1d'（指纹是给库看的）", {
  lbl <- dsapp_tos_version_label(dsapp_tos_version_key())
  identical(lbl, dsapp_tos_version_show())
})
chk("★★ 闸门比的是 key 不是常量（库里 V9 存的 '1.0' 必须被判成过期）",
    grepl("identical(ver, dsapp_tos_version_key())", tos_src, fixed = TRUE) &&
      !grepl("identical(ver, DSAPP_TOS_VERSION)", tos_src, fixed = TRUE))
chk("★ 界面上打出来的版本号会先剥掉指纹",
    grepl("dsapp_tos_version_label(g$version)", tos_src, fixed = TRUE))

# =============================================================================
section("V10 item 3：平台 logo")
# =============================================================================
app_src <- paste(readLines("app.R", warn = FALSE), collapse = "\n")
uti_src <- paste(readLines("R/utils.R", warn = FALSE), collapse = "\n")
wel_src <- paste(readLines("R/mod_welcome.R", warn = FALSE), collapse = "\n")
css_src <- paste(readLines("www/app.css", warn = FALSE), collapse = "\n")

chk("★ data/logo 目录进了配置，而且启动时会被创建",
    grepl("logo_dir", paste(readLines("R/config.R", warn = FALSE),
                            collapse = "\n"), fixed = TRUE))
chk("★ logo 走 addResourcePath 单独挂一路（不能塞进 www/，那目录随代码归档）",
    grepl('addResourcePath("dsapplogo", cfg$logo_dir)', app_src, fixed = TRUE))
chk("★ 三个用得到 logo 的地方都换掉了：标签页 / 登录页 / 左栏", {
  grepl("dsapp_favicon()", app_src, fixed = TRUE) &&
    grepl('dsapp_logo_box("dsapp-auth-logo"', wel_src, fixed = TRUE) &&
    grepl('dsapp_logo_box("dsapp-rail-logo"', app_src, fixed = TRUE)
})

chk("★★ 比例自适应：只给盒子、图按原比例缩放（不写死宽高比）", {
  i <- regexpr(".dsapp-logo-img {", css_src, fixed = TRUE)[1]
  rule <- if (i > 0) substr(css_src, i, i + 300L) else ""
  grepl("max-width: 100%", rule, fixed = TRUE) &&
    grepl("max-height: 100%", rule, fixed = TRUE) &&
    grepl("width: auto", rule, fixed = TRUE) &&
    grepl("height: auto", rule, fixed = TRUE) &&
    # ⚠️ width:100% + height:100% 会把长条形字标拉成正方形。
    #    这里**必须**用正则、不能 fixed：`max-width: 100%` 这个子串里
    #    就含着 "width: 100%"，用 fixed 找必然命中上一行自己写的那条，
    #    于是这条断言变成"永远为假"，而 CSS 是对的。
    !grepl("(^|[^-a-z])width: 100%", rule)
})
chk("★ 有真图时去掉原来那层「深色底 + 白图标」的徽章底色",
    grepl(".dsapp-auth-logo.is-img", css_src, fixed = TRUE) &&
      grepl(".dsapp-rail-logo.is-img", css_src, fixed = TRUE) &&
      grepl("background: none", css_src, fixed = TRUE))

chk("★★ 没有 logo 时落回原来的图标（全新部署没有 data/logo/ 也要能跑）", {
  empty <- file.path(tmp, "nologo")
  dir.create(empty, showWarnings = FALSE, recursive = TRUE)
  nc <- cfg; nc$data_root <- empty; nc$logo_dir <- file.path(empty, "logo")
  is.null(dsapp_logo_url(nc)) && is.null(dsapp_logo_file(nc)) &&
    is.null(dsapp_favicon(nc)) &&
    grepl("fa-", as.character(dsapp_logo_box("dsapp-auth-logo", "lock", nc)),
          fixed = TRUE)
})
chk("★★ 没有 logo 时不输出 <link rel=icon>（空 href 会让浏览器去请求根路径）",
    is.null(dsapp_favicon(list(logo_dir = file.path(tmp, "nope")))))
chk("★★ logo 的 URL 要 URL 编码（文件名是中文的，裸着塞进 href 就是 404）", {
  nc <- cfg
  if (is.null(dsapp_logo_file(nc))) TRUE else {
    u <- dsapp_logo_url(nc)
    # 非 ASCII 必须已经变成 %XX；同时 ?v= 要给上（换图不改名时靠它破缓存）
    !grepl("[^ -~]", u) && grepl("?v=", u, fixed = TRUE)
  }
})

section("★ 选项的「显示文本 / 回传值」方向（V11 排查 execute 用例时挖出来的）")

# 这一节的存在理由值得写清楚，因为它是一类**界面上看不出任何异常**的错。
#
# Shiny 的 selectInput/radioButtons/selectizeInput 认的是 `c(标签 = 值)`：
# 向量里的**值**变成 <option value="...">（回传给服务端的），**名字**变成
# 显示文本。shiny:::selectOptions 的实现是
#     mapply(choices, names(choices), function(choice, label)
#       sprintf('<option value="%s">%s</option>', choice, label))
# —— 值在前，名字在后。
#
# mod_chat.R 的「系统环境」下拉最早写的是 `c("system" = "系统环境")`，
# 正好反了。后果不是"显示得难看"：控件回传的是"系统环境"这四个字，
# observeEvent 顺手把它写进 state$exec_env，执行器拿它去查 conda 环境 ——
# **每一个任务**都报"选定的 conda 环境 系统环境 不存在"，包括模型自己发起的
# 那些。界面上选项文字看着完全正常（显示成 "system" 也没人盯着看），
# 只有"点了执行没反应"这一个症状，而它离真正的原因隔了三层。
#
# 所以这里用**行为**盯着，不是盯着源码里那行字怎么写：直接问 R 要这个控件
# 渲染出来的 HTML，看 <option value=...> 里到底是什么。

# ---- 1. dsapp_choices() 本身的方向 ------------------------------------------
.ch <- dsapp_choices(c("system", "scRNA"), c("系统环境", "单细胞（已就绪）"))
chk("★ dsapp_choices()：值进 value、标签进名字（方向不能反）", {
  identical(unname(.ch), c("system", "scRNA")) &&
    identical(names(.ch), c("系统环境", "单细胞（已就绪）"))
}, paste(names(.ch), unname(.ch), collapse = " | "))
chk("★ dsapp_choices()：长度对不上要报错，不能静默回收",
    inherits(tryCatch(dsapp_choices("a", c("x", "y")), error = function(e) e),
             "error"))

# ---- 2. 真的让 Shiny 渲染一遍，看 option 的 value ----------------------------
# 这是**唯一**能证明方向对了的断言：上面那条只证明 dsapp_choices 没写反，
# 证明不了调用点没用别的方式拼 choices。
.opt_values <- function(choices) {
  h <- as.character(shiny::selectInput("x", NULL, choices = choices))
  m <- regmatches(h, gregexpr('<option value="[^"]*"', h))[[1]]
  sub('^<option value="', "", sub('"$', "", m))
}
chk("★★ Shiny 渲染出来的 value 就是「值」，不是「标签」（c(标签 = 值) 的方向实证）",
    identical(.opt_values(dsapp_choices("system", "系统环境")), "system"),
    .opt_values(dsapp_choices("system", "系统环境")))

# ---- 3. 两个真正的调用点：抽出来跑一遍，看回传值 ----------------------------
# 这两处正是踩过的坑（mod_chat 的 env_slot、mod_envs 的 base_env_ui）。
# 断言落在"源码里没有裸的 c(\"system\" = ...)"上会漏掉换个写法的情况，
# 所以这里改从源码里把选项构造那段**抠出来**执行，再喂给 .opt_values。
.src_pick <- function(file, from, to) {
  ln <- readLines(file, warn = FALSE)
  # ⚠️ 必须跳过注释行。这些名字在注释里出现得**比代码更早** ——
  #    「见下面 observeEvent(input$target_env) 的说明」这种句子到处都是，
  #    从注释里起抠，抠出来的是一段解释文字，断言会永远为假，
  #    而失败信息说的是"守卫没装"，指向完全错误的地方。
  code <- !grepl("^\\s*#", ln)
  i <- which(code & grepl(from, ln, fixed = TRUE))[1]
  if (is.na(i)) return("")
  rest <- which(code[i:length(ln)] & grepl(to, ln[i:length(ln)], fixed = TRUE))[1]
  if (is.na(rest)) return("")
  paste(ln[i:(i + rest - 1)], collapse = "\n")
}
.chat_choices_src <- .src_pick("R/mod_chat.R", 'choices <- dsapp_choices("system"',
                               'selectInput(ns("target_env")')
chk("★ mod_chat 的 env_slot 用的是 dsapp_choices（不是裸 c()）",
    grepl("dsapp_choices", .chat_choices_src, fixed = TRUE) &&
      !grepl('c("system" =', .chat_choices_src, fixed = TRUE))

.env_choices_src <- .src_pick("R/mod_envs.R", 'choices <- dsapp_choices("system"',
                              'radioButtons(ns("env_pick")')
chk("★ mod_envs 的 base_env_ui 也用的是 dsapp_choices",
    grepl("dsapp_choices", .env_choices_src, fixed = TRUE) &&
      !grepl('c("system" =', .env_choices_src, fixed = TRUE))

# 整仓扫一遍：还有没有别处把"值"写成了名字。
# ⚠️ 已知的正确写法长这样：c("显示文本" = "value")。要抓的是反过来那种 ——
#    值是个英文标识符（system/id 之类）却当了名字。所以按"名字里没有中文
#    也没有空格、值里有中文"来判，而不是简单粗暴地禁止 c(a = b)。
.bad_choices <- character(0)
for (f in list.files("R", pattern = "\\.R$", full.names = TRUE)) {
  for (ln in readLines(f, warn = FALSE)) {
    # 注释行不算 —— 上面那段说明里**故意**原样引用了写反的那一行，
    # 不排除的话这条断言会被自己的注释绊倒（第一版就是这么红的）。
    if (grepl("^\\s*#", ln)) next
    m <- regmatches(ln, gregexpr('c\\(\\s*"[^"]*"\\s*=', ln))[[1]]
    if (!length(m)) next
    # 取 c( 后面第一个带名字的项，看名字和值各自长什么样
    mm <- regmatches(ln, regexec('c\\(\\s*"([^"]*)"\\s*=\\s*"([^"]*)"', ln))[[1]]
    if (length(mm) == 3 &&
        !grepl("[^ -~]", mm[2]) &&          # 名字是纯 ASCII（多半是标识符）
        grepl("[^ -~]", mm[3])) {           # 值里有非 ASCII（多半是给人看的）
      .bad_choices <- c(.bad_choices, sprintf("%s: %s", f, trimws(ln)))
    }
  }
}
chk("★★ 全仓没有第二处「显示文本当值」的 choices（方向写反是静默的）",
    length(.bad_choices) == 0,
    paste(.bad_choices, collapse = "\n       "))

# ---- 4. 守卫：写反了也进不了 state$exec_env ---------------------------------
# 方向上那两道修好之后，这一层仍然值得有 —— 它是"以后谁再写出一个反的
# choices 也不会把 state 污染掉"的那道保险。
chk("★ dsapp_env_selectable()：系统环境认", isTRUE(dsapp_env_selectable("system", cfg)))
chk("★ dsapp_env_selectable()：不存在的环境名不认",
    !isTRUE(dsapp_env_selectable("dsapp_不存在zzz", cfg)))
chk("★★ dsapp_env_selectable()：那句中文摘要（写反时的回传值）必须不认", {
  bad <- dsapp_env_summary("system", cfg)
  !isTRUE(dsapp_env_selectable(bad, cfg))
}, dsapp_env_summary("system", cfg))
chk("★ dsapp_env_selectable()：NULL / NA / 空串都不认（别把 NULL 当成一个选择）",
    !isTRUE(dsapp_env_selectable(NULL, cfg)) &&
      !isTRUE(dsapp_env_selectable(NA_character_, cfg)) &&
      !isTRUE(dsapp_env_selectable("", cfg)) &&
      !isTRUE(dsapp_env_selectable(c("a", "b"), cfg)))

# 三个写入点都得有这道守卫 —— 少一个就等于没装。
for (.w in list(
    # ⚠️ 终止串要选**守卫之后**的那一行。这个 observer 开头就有一句
    #    `if (...) return(invisible(NULL))`（挡 NULL/空串的那道锁），
    #    拿 "invisible(NULL)" 当终止串会停在它上面，抠出来的块里当然
    #    没有守卫 —— 报的是"守卫没装"，实际装了。
    list("R/mod_chat.R", "observeEvent(input$target_env", "state$exec_env <- v"),
    list("R/mod_envs.R", "observeEvent(input$env_pick", "invisible(NULL)"),
    list("R/mod_envs.R", "observeEvent(input$env_use", "invisible(NULL)"))) {
  .body <- .src_pick(.w[[1]], .w[[2]], .w[[3]])
  chk(sprintf("★ %s 写入前过了 dsapp_env_selectable()", .w[[2]]),
      grepl("dsapp_env_selectable", .body, fixed = TRUE),
      substr(.body, 1, 200))
}

section("V12 item 1/2：对话页的版面（输出框、动作条）")

# 这一节是**源码级**的护栏，几何那一半在 tests/ui_v12/layout.py 里 ——
# 位置关系（差几个像素、在不在同一排）只有浏览器量得准，离线判不出来。
# 这里挡的是另一类错：改 CSS / 改 UI 结构时把这次的结构悄悄改回去。
#
# ⚠️ 为什么"改回去"值得专门挡一道：V11 的版面目视上没问题、断言也全绿，
#    但整页比一屏高 56px —— 固定页脚压住最下面那排控件，用户要滚一下才
#    够得着输入框。根因是一个**魔数**（`.dsapp-chat-scroll` 的
#    `max-height: calc(100vh - 320px)`，320 比真实值小 54）。魔数这东西
#    改一次别的间距就会失准一次，而且失准了没有任何反馈。所以这里钉两条：
#    高度不许再回到魔数，输出框和输入框必须还是"上下贴着"的两块。

# ★★ Test_V15.3 item 4：这条动作条**拆掉了**，断言跟着**反过来写** ——
#    不是"这条不查了"，是"它不许回来"。
#
#    拆的理由是用户原话：「停止按钮重复了，可以把确认执行、补点建议、停止
#    按钮都挪到正在执行的会话里去」。当时屏幕上同时挂着三颗红停止按钮：
#    这条动作条一颗、实时卡片里「停止任务」一颗、后台横幅里「停止后台运行」
#    一颗。三颗 id 不同（chat-stop / chat-stop_task / chat-stop_detach），
#    所以按 id 去查"是不是只有一颗"永远查不出来 —— 用户看到的是**长得一样
#    的三颗红按钮**，不是同一个 id。
#
#    ⚠️ 为什么要留一条**否定**断言，而不是把这段直接删掉：
#      把这条动作条加回来是件很容易的事（"底部再放一排多方便"），而一加回来
#      就又有第二个"任何时刻都在那儿"的宿主了 —— 正是这一版拆掉的东西。
#      让它一加回来就红。
#    ⚠️ 扫的是 css_code，它在 5723 行已经**剥过注释**了。不剥的话下面那条
#      否定断言会被我们自己的说明文字（"这里原来有一条 .dsapp-output-bar"）
#      判成"还在"—— 连踩过三次的老坑，见 memory 的 scan-source-strip-comments。
chk("★★ app.css 里**没有** .dsapp-output-bar 了（V15.3 拆掉了那条动作条）",
    !grepl(".dsapp-output-bar", css_code, fixed = TRUE))
chk("★★ :root 里也没有 --dsapp-output-bar-h 了（常量跟着动作条一起删干净）",
    !grepl("--dsapp-output-bar-h", css_code, fixed = TRUE))
chk("★ app.css 里有 .dsapp-actions（三颗按钮搬进会话后用的那一套）",
    !is.null(dsapp_block_at(css_code,
                            regexpr("\\.dsapp-actions\\s*\\{", css_code))))

# ★ 这两条是"魔数没有了"的**行为级**证据：滚动区的高度由 flex 分配，
#   不再由 calc(100vh - Npx) 算出来。
scroll_block <- dsapp_block_at(
  css_code, regexpr("\\.dsapp-chat-scroll\\s*\\{", css_code))
chk("★★ .dsapp-chat-scroll 里**没有** max-height（V11 的 320px 魔数就是「间距过大」的根）",
    !is.null(scroll_block) && !grepl("max-height", scroll_block, fixed = TRUE),
    scroll_block)
chk("★★ .dsapp-chat-scroll 靠 flex 拿高度（flex: 1 1 auto + min-height: 0）",
    !is.null(scroll_block) && grepl("flex", scroll_block) &&
    grepl("min-height", scroll_block),
    scroll_block)

col_block <- dsapp_block_at(
  css_code, regexpr("\\.dsapp-chat-col\\s*\\{", css_code))
chk("★ .dsapp-chat-col 是 flex 列（消息区 + 动作条上下排）",
    !is.null(col_block) && grepl("flex-direction", col_block) &&
    grepl("column", col_block), col_block)
chk("★ .dsapp-chat-col 有一圈边框（用户说的「输出框」得真是个框）",
    !is.null(col_block) && grepl("border", col_block), col_block)

# ---- 破高度环：只有 :has() 能把「这一页」和别的页区分开 --------------------
# `.tabbable` / `.tab-pane` 是所有页共用的，settings/tasks 那几页必须能
# 自己撑高（codex.css 里特意留了 min-height: auto）。给所有页钉 height:100%
# 会把那两页压扁，所以这里只能按"里面装的是不是对话页"来分流。
# ⚠️ :has() 不被支持时整条规则被浏览器丢掉，退化成 V11 那样"页面能滚" ——
#    能用，只是没那么好。所以这条断言允许它退化，但不允许它**消失**：
#    写丢了就没人再记得这里为什么要 :has()。
codex_code <- paste(readLines("www/codex.css", warn = FALSE), collapse = "\n")
chk("★★ codex.css 里有 :has(.dsapp-chat-page) 的破环规则（写丢了会退回「页面能滚」）",
    grepl(":has(.dsapp-chat-page)", codex_code, fixed = TRUE))
chk("★ 破环规则给的是 height: 100% 且 min-height: 0（只写一个环还在）", {
  blk <- dsapp_block_at(codex_code,
    regexpr("\\.tabbable:has\\(\\.dsapp-chat-page\\)\\s*\\{", codex_code))
  !is.null(blk) && grepl("height\\s*:\\s*100%", blk) &&
    grepl("min-height\\s*:\\s*0", blk)
})

# ---- UI 结构：两颗按钮在输出框**内部**、在滚动区**外部** --------------------
#
# 用渲染出来的 tag 树判"谁包着谁"，不是比字符串下标 —— 下标比较在
# layout_sidebar 把侧栏也拼进同一段 HTML 之后就不再等价于嵌套关系了。
#
# ⚠️ 要 bslib：mod_chat_ui 里的 layout_sidebar 是它提供的。自检平时只
#    library(shiny)，缺了它这里会抛 "could not find function" —— 而被 chk
#    的 tryCatch 兜住之后，报出来的是"结构不对"，方向完全错了。所以先探一下。
has_bslib <- requireNamespace("bslib", quietly = TRUE)
chk("★ 装了 bslib（下面几条结构断言的前提）", has_bslib)

if (has_bslib) {
  dsapp_tag_walk <- function(x, f) {
    if (inherits(x, "shiny.tag")) {
      r <- f(x); if (!is.null(r)) return(r)
      for (ch in x$children) { r <- dsapp_tag_walk(ch, f); if (!is.null(r)) return(r) }
    } else if (is.list(x)) {
      for (ch in x) { r <- dsapp_tag_walk(ch, f); if (!is.null(r)) return(r) }
    }
    NULL
  }
  tag_by_class <- function(x, cls) dsapp_tag_walk(x, function(t) {
    if (cls %in% strsplit(as.character(t$attribs$class %||% ""), "\\s+")[[1]]) t else NULL
  })
  tag_by_id <- function(x, id) dsapp_tag_walk(x,
    function(t) if (identical(as.character(t$attribs$id %||% ""), id)) t else NULL)

  chat_ui <- mod_chat_ui("chat")
  col  <- tag_by_class(chat_ui, "dsapp-chat-col")
  comp <- tag_by_class(chat_ui, "dsapp-composer")
  scr  <- tag_by_class(chat_ui, "dsapp-chat-scroll")

  chk("★ 渲染出来的对话页里有：输出框 / 消息滚动区 / 输入区",
      !is.null(col) && !is.null(comp) && !is.null(scr))

  if (!is.null(col) && !is.null(scr) && !is.null(comp)) {
    # ★★ Test_V15.3 item 4 改写了这一节。
    #
    # 改之前查的是"动作条在输出框内部、滚动区外部、两颗槽在动作条里"——
    # 那几条断的正是**被拆掉的那个结构**，留着它们会永远为假。
    # 现在这一节查的是**新结构**：
    #   · UI 里已经没有任何动作条/按钮槽（按钮改由**服务端**按状态决定挂哪儿，
    #     UI 那一侧本来就该是空的 —— 挂载点是 renderUI 出来的）；
    #   · 按钮的唯一一份渲染是 run_actions_ui()，宿主由 action_host() 决定；
    #   · 输入区里那排控件照旧留着（item 1 说的是"排在最下方"，不是"搬出去"）。
    chk("★★ UI 里**没有**动作条了（按钮不再是「钉在某处的一排控件」）",
        is.null(tag_by_class(chat_ui, "dsapp-output-bar")) &&
        is.null(tag_by_class(chat_ui, "dsapp-actions")))
    chk("★★ UI 里**没有**任何按钮槽（chat-confirm_slot / chat-stop_slot 都已删）",
        is.null(tag_by_id(chat_ui, "chat-confirm_slot")) &&
        is.null(tag_by_id(chat_ui, "chat-stop_slot")))
    # 最下面那排控件（硬件/系统环境/技能/自动执行）留在输入区里 ——
    # item 1 说的是"这一行应该在最下方"，不是"搬出去"。
    chk("★ 硬件/系统环境那一排还在输入区里（只是排到了最下面）",
        !is.null(tag_by_class(comp, "dsapp-ctrl-bar")))

    # ---- V13.11 item 9：「总结并生成报告」「发送」必须永远一行 ----------
    #
    # 用户原话：「会在 token 使用的提示语句变长时换行，请固定按钮为一行」。
    #
    # ⚠️ 这一条**光有 CSS 是守不住的**：约束分两半 —— 类名在 R 里、规则在
    #    app.css 里。谁把 `div(class = "dsapp-composer-foot", ...)` 改回
    #    `d-flex justify-content-between`（看着更"标准"），CSS 那半就静默
    #    失配，按钮又开始换行，而且**不报任何错**。所以两边都要钉。
    foot <- tag_by_class(comp, "dsapp-composer-foot")
    chk("★★ 输入区那一排带着 dsapp-composer-foot（CSS 那一半靠它选中）",
        !is.null(foot))
    if (!is.null(foot)) {
      chk("★★ 提示语和按钮组都挂在自己的类上（不是 Bootstrap 工具类拼的）",
          !is.null(tag_by_class(foot, "dsapp-composer-hint")) &&
          !is.null(tag_by_class(foot, "dsapp-composer-actions")))
      # 那两颗按钮必须还在这一排里 —— 换类名时最容易顺手把它们挪走
      chk("★★ 两颗按钮仍在这个 nowrap 的排里",
          !is.null(tag_by_id(foot, "chat-report_btn")) &&
          !is.null(tag_by_id(foot, "chat-send")))
      # 反面：那一排上**不能**再出现 d-flex / justify-content-between。
      # 它们和 .dsapp-composer-foot 是两套写法，混着写会互相盖，
      # 而且 d-flex 那套给不了 min-width:0（上一版就是栽在这）。
      foot_cls <- as.character(foot$attribs$class %||% "")
      chk("★★ 那一排上不再混用 d-flex 工具类",
          !grepl("\\bd-flex\\b", foot_cls))
    }
    # CSS 那一半：三条缺一不可（见 app.css 里那段注释）
    css_txt <- paste(readLines("www/app.css", warn = FALSE), collapse = "\n")
    chk("★★ .dsapp-composer-foot 是 flex-wrap: nowrap（不许折行）", {
      blk <- dsapp_block_at(css_txt, regexpr("\\.dsapp-composer-foot\\s*\\{", css_txt))
      !is.null(blk) && grepl("flex-wrap:\\s*nowrap", blk)
    })
    chk("★★ .dsapp-composer-hint 能压下去（min-width: 0 + 省略号）", {
      blk <- dsapp_block_at(css_txt, regexpr("\\.dsapp-composer-hint\\s*\\{", css_txt))
      !is.null(blk) && grepl("min-width:\\s*0", blk) &&
        grepl("text-overflow:\\s*ellipsis", blk)
    })
    chk("★★ .dsapp-composer-actions 不许被压窄（flex: 0 0 auto）", {
      blk <- dsapp_block_at(css_txt, regexpr("\\.dsapp-composer-actions\\s*\\{", css_txt))
      !is.null(blk) && grepl("flex:\\s*0 0 auto", blk) && grepl("nowrap", blk)
    })
  }
}

# ---- V13.11 item 2：对话页左右留白不能又长回去 ------------------------------
#
# 用户原话：「对话框两侧留白过大，应该缩小一些」。
# 实测（1600px 视口）：改之前每侧 44px = bslib 的 24 + 滚动区的 20；
# 改之后每侧 20px 左右。这条**必须**两头一起量，只盯一头会出现
# "我把 24 收成 12 了呀怎么还是宽"（另一头还吃着 20）。
{
  css_txt2 <- paste(readLines("www/app.css", warn = FALSE), collapse = "\n")
  main_blk <- dsapp_block_at(css_txt2,
    regexpr("\\.dsapp-main-body \\.bslib-sidebar-layout > \\.main\\s*\\{", css_txt2))
  chk("★★ bslib 主区的 24px padding 被收窄了（选择器挂对了）",
      !is.null(main_blk) && grepl("padding:\\s*\\.75rem \\.625rem", main_blk))
  # ⚠️ 选择器不能写成 `.dsapp-chat-page .main`：.dsapp-chat-page 在 .main
  #    **里面**（layout_sidebar 是最外层），那样写永远匹配不到、也不报错。
  #    只认"行首的选择器位置"，免得注释里提一嘴这句坏写法就误报。
  chk("★★ 没有写成永远匹配不到的 .dsapp-chat-page .main",
      !grepl("(?m)^[ \t]*\\.dsapp-chat-page[ \t]+\\.main", css_txt2, perl = TRUE))
  scroll_blk <- dsapp_block_at(css_txt2, regexpr("\\.dsapp-chat-scroll\\s*\\{", css_txt2))
  chk("★★ 消息滚动区的左右 padding 也收了（.625rem）",
      !is.null(scroll_blk) && grepl("padding:\\s*\\.5rem \\.625rem", scroll_blk))
  # 折叠态那条还原不能丢：丢了正文会钻到折叠按钮底下
  chk("★★ 折叠态仍给折叠按钮让位（padding 用 --_padding-icon 还原）",
      grepl("sidebar-collapsed > \\.main", css_txt2) &&
        grepl("padding-left: var\\(--_padding-icon\\)", css_txt2))
}

# ---- 三颗按钮"灰着"的形态：灰的那颗得是**不可点**的 ------------------------
# 用户原话是「没有方案待确认时是一个灰度颜色」。只改颜色不禁用的话，
# 用户点下去什么都不会发生 —— 而"点了没反应"是这个项目踩过最多次的坑。
#
# ★ Test_V15.3 item 4：两颗 uiOutput 槽（confirm_slot / stop_slot）连同它们
#   所在的动作条一起拆了，三颗按钮现在只有**一份**渲染（run_actions_ui）。
#   断言跟着**搬家**，守的还是同一件事：每一颗的灰形态都带 disabled。
#   ⚠️ 数出来必须是**三颗**。只查"块里出现过 disabled"的话，两颗按钮漏了
#      disabled 也绿 —— 而用户点下去没反应时是不知道哪一颗的。
mod_chat_src <- paste(readLines("R/mod_chat.R", warn = FALSE), collapse = "\n")
chk("★★ 三颗按钮的灰形态都带 disabled（灰 ≠ 点得动）", {
  blk <- dsapp_block_at(mod_chat_src,
    regexpr('run_actions_ui <- function\\(host\\) \\{', mod_chat_src))
  if (!nzchar(blk)) return(FALSE)
  # ★ V15.6 item 13：判据从"整块里数出三个灰类名"换成"**每一颗按钮**都有灰
  #   形态、而且每个灰形态都带 disabled"。
  #   为什么换：那一版新加了一条灰形态 —— agent 停在等确认的卡上时，「确认执行」
  #   也要灰着（不然用户点第二颗会以为卡住了）。一个按钮**可以有多条灰分支**，
  #   数总数就把这件正经事记成了回归（实测 4 ≠ 3 报红，而代码是对的）。
  #   守的还是原来那件事：三颗按钮、颗颗有灰形态、灰的一律点不动。
  n_btn <- 0L; ok <- TRUE
  for (fn in c("confirm_btn", "suggest_btn", "stop_btn")) {
    fb <- dsapp_block_at(blk, regexpr(paste0(fn, " <- function() {"), blk,
                                      fixed = TRUE))
    if (!nzchar(fb)) { ok <- FALSE; next }
    n_btn <- n_btn + 1L
    n_grey <- length(gregexpr("dsapp-btn-run-off", fb, fixed = TRUE)[[1]])
    n_dis  <- length(gregexpr("disabled", fb, fixed = TRUE)[[1]])
    # `disabled` 每个灰形态出现两次（参数名 + 值），所以是 >=；用 == 会在
    # 将来把 `disabled = TRUE` 写成别的等价写法时假红。
    if (n_grey < 1L || n_dis < n_grey) ok <- FALSE
  }
  ok && n_btn == 3L
})

section("V12 item 3：任务产物的自动同步")

sync_con <- dsapp_db(dsapp_config())
sync_user <- dsapp_user_create("同步自检", "selftest_sync@example.com",
                               "13800000000", "生信",
                               "Pw-12345678", "Pw-12345678", con = sync_con)
sync_uid <- sync_user$user$id
chk("★ 造得出一个测试账号（下面几条的前提）", !is.null(sync_uid))

if (!is.null(sync_uid)) {
  sync_sid <- db_session_create("同步自检会话", user_id = sync_uid, con = sync_con)
  # 同 selftest 开头：文件区按账号分了，同步的落点也在这个账号的区里。
  sync_cfg <- dsapp_config_user(sync_uid, dsapp_config())

  # ---- 落点：一个对话一个文件夹，且**稳定** ----
  d1 <- dsapp_sync_dir(sync_sid, sync_cfg)
  d2 <- dsapp_sync_dir(sync_sid, sync_cfg)
  chk("★ 落点定得出来", nzchar(d1 %||% ""), d1)
  chk("★★ 同一个对话的落点是**稳定**的（重跑不会换个文件夹）",
      identical(d1, d2), sprintf("%s vs %s", d1, d2))

  # ★ 落点由 **sync_dirs 那张表**说了算，不是每次照标题现算的。
  #
  # ⚠️ 这里**故意绕过 db_session_rename 直接改标题**（原始 SQL）。V13.2
  #    item 6 之后，"改标题"有两条路，语义**不一样**：
  #      · 走 db_session_rename → 落点跟着改（用户自己改名，见下面那一段）
  #      · 绕过它只动库里那一列 → 落点必须纹丝不动
  #    这条钉的是后者的地基：盘上的文件夹跟的是表，不是标题。地基没了的话
  #    "文件夹跟着改名走"这件事就变成了"每次打开页面都换一个文件夹"。
  DBI::dbExecute(sync_con, "UPDATE sessions SET title = ? WHERE id = ?",
                 params = list("改过名的会话", sync_sid))
  chk("★★ 只改库里的标题（不走改名函数）时落点**不变** —— 落点认表不认标题",
      identical(dsapp_sync_dir(sync_sid, sync_cfg), d1), d1)

  sync_sid2 <- db_session_create("同步自检会话", user_id = sync_uid, con = sync_con)
  d3 <- dsapp_sync_dir(sync_sid2, sync_cfg)
  chk("★★ 同名对话拿到**不同**的文件夹（不许互相覆盖）",
      !identical(d3, d1), sprintf("%s vs %s", d3, d1))

  # ---- 写入：结构、覆盖、别人的东西不动 ----
  sws <- dsapp_ws_dir(sync_sid, sync_cfg, create = TRUE)
  dir.create(file.path(sws, "results"), recursive = TRUE, showWarnings = FALSE)
  writeLines("a,b\n1,2", file.path(sws, "de.csv"))
  writeLines("sub", file.path(sws, "results", "qc.csv"))
  writeLines("x", file.path(sws, ".dsapp_main.R"))
  dir.create(file.path(sws, ".Rlib"), showWarnings = FALSE)
  writeLines("x", file.path(sws, ".Rlib", "pkg"))

  sres <- dsapp_sync_artifacts(sync_sid,
    c("de.csv", "results/qc.csv", ".dsapp_main.R", ".Rlib/pkg"), cfg = sync_cfg)
  chk("★ 同步成功", isTRUE(sres$ok), sres$msg)
  chk("★ 搬了 2 个文件", identical(sres$n, 2L), sres$n)
  chk("★★ 内部文件（.dsapp_* / .Rlib）在这**一层**也被挡下（不靠调用方过滤）",
      identical(sres$skipped, 2L), sres$skipped)

  sdst <- file.path(sync_cfg$files_dir, d1)
  chk("★ 子目录结构保留（results/qc.csv）",
      file.exists(file.path(sdst, "results", "qc.csv")))
  chk("★ 内部文件没落过去",
      !file.exists(file.path(sdst, ".dsapp_main.R")) &&
      !dir.exists(file.path(sdst, ".Rlib")))

  # ★ 覆盖自己：共享区里落盘的文件是 0444（安全属性，软链会穿透写）。
  #   不先 chmod 回去，file.copy(overwrite = TRUE) 会**失败**，而且 R 只
  #   丢一句 warning、返回 FALSE —— 任务照样报成功，共享区里那份是旧的。
  writeLines("a,b\n1,2\n3,4", file.path(sws, "de.csv"))
  sres2 <- dsapp_sync_artifacts(sync_sid, "de.csv", cfg = sync_cfg)
  chk("★★ 重跑同步 ok", isTRUE(sres2$ok), sres2$msg)
  chk("★★ 内容是**新的**（0444 挡不住覆盖自己，这条以前真的坏过）",
      length(readLines(file.path(sdst, "de.csv"))) == 3L,
      paste(readLines(file.path(sdst, "de.csv")), collapse = " | "))
  chk("★★ 没有堆出 de(1).csv", !file.exists(file.path(sdst, "de(1).csv")))
  chk("★ 覆盖之后仍然只读（安全属性没被 chmod 永久拆掉）",
      identical(as.octmode(file.info(file.path(sdst, "de.csv"))$mode),
                as.octmode("0444")),
      as.character(as.octmode(file.info(file.path(sdst, "de.csv"))$mode)))

  # ★ 别人的同名文件绝不覆盖。共享区是**公开**的（所有用户可见），
  #   "重名就覆盖"会变成一条"任何人的任务都能改别人文件"的路。
  #
  #   落点文件夹本身也是共享区里的一个普通文件夹 —— 别人（或者用户自己
  #   手动上传）完全可以往里放一个同名文件。判据是**发布记录**：发布表里
  #   记着"这个位置是我们上一轮同步出去的"，没记录的就是别人的。
  #   所以这里先把 de.csv 的发布记录删掉，再在同一个位置放一个"别人的"。
  DBI::dbExecute(sync_con, "DELETE FROM ws_published WHERE session_id = ? AND name = ?",
                 params = list(sync_sid, "de.csv"))
  # 共享区里刚落过去的那份是 0444，先放开才写得进去 —— 顺便也正是
  # "共享区文件只读"这条安全属性在自检里的又一次实证。
  Sys.chmod(file.path(sdst, "de.csv"), mode = "0644")
  writeLines("别人传上来的", file.path(sdst, "de.csv"))
  writeLines("我们的新版本", file.path(sws, "de.csv"))
  sres3 <- dsapp_sync_artifacts(sync_sid, "de.csv", cfg = sync_cfg)
  chk("★★ 别人的同名文件**没被动**", isTRUE(sres3$ok) &&
      identical(readLines(file.path(sdst, "de.csv")), "别人传上来的"),
      paste(readLines(file.path(sdst, "de.csv")), collapse = " | "))
  chk("★★ 我们的版本另起了名字（不丢，也不覆盖别人）",
      length(list.files(sdst, pattern = "^de\\([0-9]+\\)\\.csv$")) >= 1L,
      paste(list.files(sdst), collapse = " | "))

  chk("★ 没有产物时不报错、也不建目录",
      isTRUE(dsapp_sync_artifacts(sync_sid, character(0), cfg = sync_cfg)$ok))

  # ---- ★★ 差集必须认得出"文件被**改写**了" ------------------------------
  # 这一条是 V12 item 3 真正的那颗雷：差集原来纯按**名字**算，重跑一遍
  # 脚本不产生任何新名字，于是产物清单是空的 —— 同步拿到空清单什么都不做，
  # 共享区里永远停在第一轮的结果上，而用户刚在对话里看到新的数。
  # 分析 agent 最常见的动作就是"改个参数再跑一遍"，所以这不是边角情况。
  diff_ws <- dsapp_ws_dir(sync_sid, sync_cfg, create = TRUE)
  writeLines("v1", file.path(diff_ws, "only_here.csv"))
  st1 <- dsapp_ws_stamp(diff_ws)
  chk("★ 带戳快照拍到了这个文件", "only_here.csv" %in% names(st1))
  chk("★ 什么都没动 → 差集空", length(dsapp_ws_diff(st1, dsapp_ws_stamp(diff_ws))) == 0L)
  Sys.sleep(1.1)   # 跨过 mtime 的秒级分辨率
  writeLines("v2-改写过的内容", file.path(diff_ws, "only_here.csv"))
  dif <- dsapp_ws_diff(st1, dsapp_ws_stamp(diff_ws))
  chk("★★ 改写过的文件在差集里（旧代码这里是空的）",
      "only_here.csv" %in% dif, paste(dif, collapse = " | "))

  # ---- 收尾那条路上**真的调了**它 -------------------------------------------
  # ★ 这个函数从 V3 被拿掉到 V12 之间一直是"函数在、没人调"的状态 ——
  #   离线怎么测都测不出这件事。所以离线至少钉住调用点在不在。
  #
  # ⚠️ V13.7 item 5：收尾那一段**搬家了**。原来整段写在 app.R 的 e$poll() 里，
  #    现在归 R/taskrun.R 的 dsapp_task_closeout() —— 因为脱离会话的后台续跑
  #    也要在任务跑完之后做同样的事（写任务状态、写产物清单、同步产物）。
  #    不搬的话后台那条路要么没同步、要么抄一份，而"抄一份"的下场和上面
  #    拼上下文那处一样：两边慢慢长歪，且看不出来。
  #
  #    所以现在钉**一整条链**，而不是一个点：
  #      app.R 的 e$poll() → taskrun.R 的 dsapp_task_closeout() → sync_artifacts
  #    只钉中间那一环的话，"函数在、没人调"这个老毛病会原样回来 ——
  #    closeout 写得好好的，只是没有任何人调它。
  app_src <- paste(readLines("app.R", warn = FALSE), collapse = "\n")
  poll_blk <- dsapp_block_at(app_src, regexpr("e\\$poll\\s*<-\\s*function", app_src))
  chk("抠到了 e$poll() 的函数体", nzchar(poll_blk))
  chk("★★ e$poll() 走的是 dsapp_task_closeout（收尾只有这一份实现）",
      grepl("dsapp_task_closeout(", poll_blk, fixed = TRUE))

  tr_src <- paste(readLines("R/taskrun.R", warn = FALSE), collapse = "\n")
  close_blk <- dsapp_block_at(tr_src,
                              regexpr("dsapp_task_closeout <- function", tr_src))
  chk("抠到了 dsapp_task_closeout 的函数体", nzchar(close_blk))
  chk("★★ 任务收尾那条路上**真的调了** dsapp_sync_artifacts（函数在没人调＝没做）",
      grepl("dsapp_sync_artifacts(", close_blk, fixed = TRUE))
  chk("★ 调用被 tryCatch 包着（同步失败不许把跑完的结果毁掉）",
      grepl("dsapp_sync_artifacts", close_blk, fixed = TRUE) &&
      grepl("error\\s*=\\s*function", close_blk))
  # ★ 两条路都得走同一个收尾。后台续跑那条要是漏了，症状是**最坏的一种**：
  #   任务明明跑完了、结果也写进对话了，产物却没进共享区 —— 用户以为东西
  #   丢了，而日志上一切正常（后台进程的日志他看不到）。
  det_src <- paste(readLines("R/detach.R", warn = FALSE), collapse = "\n")
  chk("★★ 脱离会话的后台续跑也走同一个收尾（不然产物不进共享区）",
      grepl("dsapp_task_closeout(", det_src, fixed = TRUE))

  # ===========================================================================
  # V13 item 2：历史产物补同步
  # ===========================================================================
  # 用户原话：「比如 brca_result 这个文件夹，我在文件管理区就看不到」。
  #
  # 上面那一整套（V12 item 3）只在**任务收尾那一刻**跑。上线之前跑出来的
  # 产物一直躺在对话工作区里，而工作区用户根本进不去 —— 从用户的角度看
  # 就是"东西没了"。实测生产库时 sync_dirs 表**一行都没有**，说明 V12 上线
  # 之后一次同步都没发生过。
  #
  # 这一节要钉死的是"补得回来"，以及**别补错**：
  #   · 判据是 sync_dirs 表，不是"管理区里没这个文件夹"
  #     （按盘判的话，用户删掉文件夹之后每次打开文件页都会给他重建一个）
  #   · 只补**这个账号**的
  #   · 再跑一次是幂等的
  bk_sid <- db_session_create("补同步用", user_id = sync_uid, con = sync_con)
  bws <- dsapp_ws_dir(bk_sid, sync_cfg, create = TRUE)
  dir.create(file.path(bws, "brca_result"), showWarnings = FALSE)
  writeLines("gene,logfc", file.path(bws, "brca_result", "deseq.csv"))
  writeLines("x", file.path(bws, ".dsapp_main.R"))

  # ⚠️ 顺序是有讲究的，而且**只有一种写法是对的**：
  #
  #     查前提（盘上有什么、sync_dirs 里有没有行） → 补同步 → 才去要落点
  #
  #   `dsapp_sync_dir()` **会写 sync_dirs 那一行** —— 它就是"第一次同步时
  #   记下落点"的那个函数。所以在补同步**之前**调它一次，这个对话在补同步
  #   眼里就已经"同步过了"，补同步什么也不做。这一节先后踩过两次：
  #   先是把 dsapp_sync_dir 写在前面，后是补同步写了两遍（第一遍把活干完，
  #   被断言的第二遍当然是 0）—— 两次的表现一模一样：文件明明搬过去了，
  #   红的却是"没搬"。所以现在补同步**只出现一次**，就在这三行的正中间。
  before_dirs <- list.dirs(sync_cfg$files_dir, recursive = FALSE)
  chk("★ 前提：这个对话还没同步过（sync_dirs 里没有它的行）",
      !(bk_sid %in% DBI::dbGetQuery(sync_con,
                                    "SELECT session_id FROM sync_dirs")$session_id))

  # ★ 传的是**全局** cfg（mod_files 就是这么调的），函数内部必须自己
  #   按账号重新定位一次。不重新定位的话，产物会落到 _anon 那个空目录上，
  #   而界面上什么都看不到 —— 补同步"跑了但没效果"。
  bkr <- dsapp_sync_backfill(sync_uid, dsapp_config())

  # 到这里 sync_dirs 里已经有行了，下面这次是**纯读**，不会改变任何状态。
  bk_dir <- dsapp_sync_dir(bk_sid, sync_cfg)
  chk("★ 前提：管理区里原先没有这个落点（补同步是新建出来的）",
      !(file.path(sync_cfg$files_dir, bk_dir) %in% before_dirs),
      paste(basename(before_dirs), collapse = " | "))

  chk("★★ 补同步真的搬了东西（跑完还是 0 个就是白跑）",
      bkr$n_sessions >= 1L && bkr$n_files >= 1L,
      sprintf("n_sessions=%s n_files=%s", bkr$n_sessions, bkr$n_files))
  chk("★★★ brca_result/deseq.csv 出现在管理区里（用户报的就是这个）",
      file.exists(file.path(sync_cfg$files_dir, bk_dir, "brca_result", "deseq.csv")))
  chk("★ 内部文件没跟着过去",
      !file.exists(file.path(sync_cfg$files_dir, bk_dir, ".dsapp_main.R")))
  chk("★ sync_dirs 里记了一行（下次不再重扫这个对话）",
      bk_sid %in% DBI::dbGetQuery(sync_con,
                                  "SELECT session_id FROM sync_dirs")$session_id)

  # ★ 幂等：第二次一个都不该再搬。不幂等的话，每次打开文件页都会给用户
  #   堆一批 de(1).csv / de(2).csv。
  bkr2 <- dsapp_sync_backfill(sync_uid, dsapp_config())
  chk("★★ 再跑一次是幂等的（一个都不搬，也不会堆出 (1)(2) 副本）",
      identical(bkr2$n_sessions, 0L) && identical(bkr2$n_files, 0L),
      sprintf("n_sessions=%s n_files=%s", bkr2$n_sessions, bkr2$n_files))
  chk("★ 幂等的那一次没留下 (1) 副本",
      !length(list.files(file.path(sync_cfg$files_dir, bk_dir),
                         pattern = "\\([0-9]+\\)")))

  # ★ 只补**这个账号**的。判据错了的话，任一账号打开文件页都会去扫全站
  #   所有对话的工作区 —— 慢，而且会把别人的产物搬进自己区里。
  bk_other <- dsapp_user_create("补同步别人", "selftest_sync2@example.com",
                                "13800000001", "生信",
                                "Pw-12345678", "Pw-12345678", con = sync_con)
  bk_ouid <- bk_other$user$id
  if (!is.null(bk_ouid)) {
    bk_osid <- db_session_create("别人的对话", user_id = bk_ouid, con = sync_con)
    bk_ocfg <- dsapp_config_user(bk_ouid, dsapp_config())
    ows <- dsapp_ws_dir(bk_osid, bk_ocfg, create = TRUE)
    writeLines("secret", file.path(ows, "别人的产物.csv"))
    # 同样先别调 dsapp_sync_dir —— 它会把这个对话标成"同步过了"（见上）。
    invisible(dsapp_sync_backfill(sync_uid, dsapp_config()))
    chk("★★★ 补同步不会搬别人的产物（判据错了就是跨账号搬运）", {
      # 我这边补完之后，别人的对话在 sync_dirs 里仍然应当**没有**行
      !(bk_osid %in% DBI::dbGetQuery(sync_con,
                                     "SELECT session_id FROM sync_dirs")$session_id)
    })

    invisible(dsapp_sync_backfill(bk_ouid, dsapp_config()))
    odir <- dsapp_sync_dir(bk_osid, bk_ocfg)
    chk("★ 别人补自己的那份是好的（不是把功能整个关掉）",
        file.exists(file.path(bk_ocfg$files_dir, odir, "别人的产物.csv")))
  }

  # ★ 没有账号时什么都别做。宁可不做，也不能落到 _anon 那个共用目录上 ——
  #   那是**所有人**都能看到的地方。
  chk("★★ user_id = NULL 时直接返回，不往 _anon 里搬东西",
      identical(dsapp_sync_backfill(NULL, dsapp_config())$n_files, 0L))

  # ★ 渲染路上的一次写盘，**不许抛异常**。抛出去就是文件页白屏。
  chk("★★ 库坏了也不抛（渲染路上的写盘，抛出去就是白屏）", {
    # db_path 指一个**目录** —— dbConnect 必失败，而且 dsapp_init_dirs
    # 建不出这个"文件"（目录已经在了，dir.create 会静默跳过）。
    # 用"指一个不存在的目录"来模拟是不行的：dsapp_init_dirs 会 recursive
    # 地把它建出来，然后一切正常 —— 断言绿了，但什么都没验到。
    bad <- dsapp_config()
    bad$data_root <- sync_cfg$data_root
    bad$db_path   <- tempdir()
    inherits(tryCatch(dsapp_sync_backfill(sync_uid, bad), error = function(e) e),
             "list")
  })
  # ⚠️ 上面那条会**顺手把单例连接换掉**：dsapp_db() 看到 cfg 的路径和当前
  #    连接对不上，会先把旧连接关掉再建新的 —— 而新的那个建不出来。
  #    自愈没问题（下一次 dsapp_db(cfg) 会重连），但 `sync_con` 这个变量
  #    握着的是**已经死掉的**那个句柄，后面谁再拿它写库就是
  #    "Invalid or closed connection"。现取一个，别把雷留给下一个人。
  sync_con <- dsapp_db(dsapp_config())
}

section("V13.2 item 6：改对话名 → 管理区里的同步文件夹跟着改")

# 用户原话：「目前改任务名称的时候，文件管理系统中的名称并不能一并修改」。
#
# ⚠️ 这一段每一条都要**同时**验盘上的目录名和库里的三本账（sync_dirs /
#    file_owner / ws_published）。只验目录名的话，改名"看起来成功了"，
#    但里面每个文件的归属行还指着旧前缀 —— 按 dsapp_file_can_edit 的规则
#    那就是"无主"，而**无主 = 人人可删**。那个后果离"文件夹叫什么"很远，
#    只测目录名的断言一辈子都测不出来。
#
# ⚠️ 用的账号必须和上面那个分开：上面那段会故意把库指向一个建不出来的路径
#    来验"不许抛异常"，`sync_con` 握着的是**已经死掉的**句柄。
rn_cfg  <- dsapp_config()
rn_con  <- dsapp_db(rn_cfg)
rn_user <- dsapp_user_create("改名自检", "selftest_rename@example.com",
                             "13800000001", "生信",
                             "Pw-12345678", "Pw-12345678", con = rn_con)
rn_uid <- rn_user$user$id
chk("★ 造得出改名自检的账号", !is.null(rn_uid))

if (!is.null(rn_uid)) {
  rn_ucfg <- dsapp_config_user(rn_uid, rn_cfg)
  # ⚠️ 先把这个账号的管理区目录建出来。dsapp_file_path 是**按真实路径**解析的
  #    （must_exist = FALSE 只表示"最后那一段可以不存在"，中间几级得在），
  #    区根不在的话它返回 NULL —— 而 NULL 一路传到 dir.create 才炸，
  #    报的还是 "invalid 'path' argument" 这种跟根因毫无关系的错。
  dsapp_files_ensure(rn_uid, rn_ucfg)

  # 产物**真的**走一遍自动同步（不手工往库里塞行）：下面要验的三本账
  # （sync_dirs / file_owner / ws_published）都是它写的，手工塞的话验的是
  # "我以为它写了什么"，而不是它实际写了什么。
  rn_sid <- db_session_create("改名前的标题", user_id = rn_uid, con = rn_con)
  rn_ws  <- dsapp_ws_dir(rn_sid, rn_ucfg, create = TRUE)
  dir.create(file.path(rn_ws, "results"), recursive = TRUE,
             showWarnings = FALSE)
  writeLines("a,b\n1,2", file.path(rn_ws, "de.csv"))
  writeLines("x", file.path(rn_ws, "results", "qc.csv"))

  rn_s1 <- dsapp_sync_artifacts(rn_sid, c("de.csv", "results/qc.csv"),
                                user_id = rn_uid, cfg = rn_ucfg)
  rn_d1 <- rn_s1$dir
  chk("★ 前提：产物同步出去了，落点带着旧标题",
      isTRUE(rn_s1$ok) && nzchar(rn_d1 %||% "") &&
        grepl("^改名前的标题-", rn_d1 %||% "") &&
        identical(rn_s1$n, 2L),
      sprintf("ok=%s dir=%s n=%s msg=%s", rn_s1$ok, rn_d1, rn_s1$n, rn_s1$msg))

  # ⚠️ `name` 是**相对管理区根**的路径，不是文件名 —— 产物落在
  #    `<同步文件夹>/de.csv`，键就是 `u<N>/<同步文件夹>/de.csv`。
  #    只写 "de.csv" 查的是 `u<N>/de.csv`，永远 NA，而断言会**绿着**骗人
  #    （"旧键已经没有了"在两边都查不到时同样是 NA，当然也绿）。
  #    第一版就是这么写的：新旧都是 NA，看起来"归属行搬走了"，其实根本没有。
  rn_own <- function(dir, rel) {
    dsapp_file_owner(paste0(dir, "/", rel), con = rn_con, user_id = rn_uid)
  }
  chk("★ 前提：归属行写进去了（不然下面「搬走了」验的是空气）",
      identical(rn_own(rn_d1, "de.csv"), as.integer(rn_uid)) &&
        identical(rn_own(rn_d1, "results/qc.csv"), as.integer(rn_uid)),
      sprintf("%s / %s", rn_own(rn_d1, "de.csv"),
              rn_own(rn_d1, "results/qc.csv")))

  # ---- 正题：走真正的改名函数 ----
  db_session_rename(rn_sid, "改名后的标题", con = rn_con)
  rn_d2 <- db_sync_dir_get(rn_sid, con = rn_con)
  chk("★★ 改完名，sync_dirs 里的落点跟着换了新名字",
      !identical(rn_d2, rn_d1) && grepl("^改名后的标题-", rn_d2 %||% ""),
      sprintf("%s → %s", rn_d1, rn_d2))

  rn_new <- tryCatch(dsapp_file_path(rn_d2, rn_ucfg, must_exist = TRUE),
                     error = function(e) NULL)
  rn_old <- tryCatch(dsapp_file_path(rn_d1, rn_ucfg, must_exist = TRUE),
                     error = function(e) NULL)
  chk("★★★ 新文件夹在盘上真的有，子目录结构和文件都跟过来了",
      !is.null(rn_new) && dir.exists(rn_new) &&
        file.exists(file.path(rn_new, "de.csv")) &&
        file.exists(file.path(rn_new, "results", "qc.csv")),
      rn_new)
  # ⚠️ 旧文件夹必须**没了**。rename 是原地改名，留着旧的就是复制 —— 而
  #    "两个文件夹各有一半文件"这种状态用户完全无从下手。
  chk("★★ 旧文件夹没了（是改名，不是复制一份）",
      is.null(rn_old) || !dir.exists(rn_old), rn_d1)

  chk("★★★ 归属行跟着搬了 —— 里面的文件还是这个人自己的，没变成「无主」",
      identical(rn_own(rn_d2, "de.csv"), as.integer(rn_uid)) &&
        identical(rn_own(rn_d2, "results/qc.csv"), as.integer(rn_uid)),
      sprintf("新: %s / %s", rn_own(rn_d2, "de.csv"),
              rn_own(rn_d2, "results/qc.csv")))
  chk("★★ 旧键下的归属行已经没有（留着的话，按老名字查归属会查到一条指向不存在路径的孤儿）",
      is.na(rn_own(rn_d1, "de.csv")) &&
        is.na(rn_own(rn_d1, "results/qc.csv")))

  rn_pub <- db_ws_pub_map(rn_sid, con = rn_con)$dest
  chk("★★★ 发布记录里的落点也换了前缀",
      length(rn_pub) == 2L && all(startsWith(rn_pub, paste0(rn_d2, "/"))),
      paste(rn_pub, collapse = " | "))

  # ★★★ 上面那条的**后果**：发布记录没跟着走的话，dsapp_sync_artifacts 会
  #      认不出"管理区里那个同名文件是我自己上一轮同步出去的"，于是
  #      另起一个名字（它绝不覆盖不是自己的东西 —— 那条规则本身没错），
  #      重跑一次任务管理区里就多一个 de(1).csv，跑几次多几个。
  #      用户看到的是"我每跑一次任务就多一份重复的文件"。
  rn_s2 <- dsapp_sync_artifacts(rn_sid, c("de.csv", "results/qc.csv"),
                                user_id = rn_uid, cfg = rn_ucfg)
  rn_list <- sort(list.files(rn_new, recursive = TRUE, all.files = FALSE))
  chk("★★★ 改名之后再跑一次同一个任务，**不产生重复文件**（覆盖自己上一轮）",
      isTRUE(rn_s2$ok) && identical(rn_list, c("de.csv", "results/qc.csv")),
      paste(rn_list, collapse = " | "))

  # ---- 撞车：算出来的名字已经被别的对话占着 ----
  #
  # ⚠️ **不能**靠"再建一个同名对话"来造撞车：文件夹名后面挂着对话 id 的
  #    尾 4 位，两个对话的 id 不一样，名字**天生**不会撞 —— 那样写出来的
  #    断言（"两个同名对话拿到不同文件夹"）恒真，撞车那条路一行都没走到。
  #    （上面 V12 那一段里的 sync_sid2 就是这么写的，一直没验到。）真要造，
  #    得让另一个对话**先占住**那个算出来的名字。
  rn_sid2 <- db_session_create("另一个会话", user_id = rn_uid, con = rn_con)
  rn_d3   <- dsapp_sync_dir(rn_sid2, rn_ucfg)     # 先让它自己有落点可改
  rn_base <- dsapp_sync_stem("改名后的标题", rn_sid2)
  rn_sid3 <- db_session_create("占位的会话", user_id = rn_uid, con = rn_con)
  db_sync_dir_set(rn_sid3, rn_base, con = rn_con)

  db_session_rename(rn_sid2, "改名后的标题", con = rn_con)
  rn_d4 <- db_sync_dir_get(rn_sid2, con = rn_con)
  chk("★★ 名字被别人占着时加序号（既不覆盖对方，也不安静地失败）",
      identical(rn_d4, paste0(rn_base, "(1)")),
      sprintf("%s → base=%s 拿到 %s", rn_d3, rn_base,
              rn_d4 %||% "(没落点：改名被跳过了)"))
  chk("★ 占位那个没被顺手改掉（它没改名）",
      identical(db_sync_dir_get(rn_sid3, con = rn_con), rn_base))
  chk("★★ 撞车判断把**自己**排掉（不排的话每改一次名就多一个 (1)、(2)）",
      identical(dsapp_sync_free_name(rn_con, rn_sid, rn_d2), rn_d2), rn_d2)

  # ---- 两条不该动盘的边界 ----
  rn_sid4 <- db_session_create("还没同步过", user_id = rn_uid, con = rn_con)
  db_session_rename(rn_sid4, "改了个名", con = rn_con)
  chk("★★ 没同步过的对话，改名**不建文件夹**（也不往 sync_dirs 里写行）",
      is.null(db_sync_dir_get(rn_sid4, con = rn_con)))
  rn_d5 <- dsapp_sync_dir(rn_sid4, rn_ucfg)
  chk("★ 它第一次同步时直接就用**改后**的标题算名字",
      grepl("^改了个名-", rn_d5 %||% ""), rn_d5)

  # 改成一个算出来**一模一样**的名字（只有首尾空格不同）→ 什么都不该发生
  rn_before <- db_sync_dir_get(rn_sid, con = rn_con)
  rn_res <- dsapp_sync_rename(rn_sid, "改名后的标题", con = rn_con)
  chk("★ 名字没变时直接返回，不动盘也不写库",
      isTRUE(rn_res$ok) && !isTRUE(rn_res$moved) &&
        identical(db_sync_dir_get(rn_sid, con = rn_con), rn_before),
      rn_res$msg)

  # ★ 整个函数挂在改名那条路上（标题已经改成功了），**不许抛异常**。
  chk("★★ 库坏了也不抛（抛出去就是「改名失败」，而标题其实已经改了）", {
    bad <- dsapp_config()
    bad$data_root <- rn_cfg$data_root
    bad$db_path   <- tempdir()
    inherits(tryCatch(dsapp_sync_rename(rn_sid, "再改一次", cfg = bad),
                      error = function(e) e), "list")
  })
  rn_con <- dsapp_db(dsapp_config())   # 上面那条会把单例连接换掉，见上
}

section("V13.2 item 5：面板宽高的用户自定义")

# 用户原话：「侧面导航栏，二级目录中，例如言出法随界面中的输出界面的宽高，
#           能不能支持用户自定义？记得做好自适应，不要相互堆叠」。
#
# ⚠️ 这一段测的是**数据层**（存哪儿、坏了怎么办、边界在哪儿）。"拖一下真的
#    变宽了吗"测不了 —— 那是浏览器里的事，在 tests/ui_v132/panels.py 里。
#    两边都要有：这里保证存对了，那里保证用对了，任何一边单独绿都不能说明
#    功能是好的。
#
# ⚠️ 这里**不碰**上面那段用的 rn_uid 那套配置：ups_con 是独立的。
ups_con <- dsapp_db(dsapp_config())

# ---- 收敛：脏输入不进口，也不留洞 ----
#
# ⚠️ 下面这几条用 ups_int() 只取那三个**像素**键来比。整份 norm 现在有五个
#    键（item 13 加了两个排序用的、V13.4 item 6 加了导航栏宽度），每条断言
#    都把五个写全会淹没重点 —— 而重点恰恰是"越界怎么夹"。排序那两个键的
#    断言在下面单独一段。
ups_int <- function(x) {
  p <- dsapp_uipref_norm(x)
  list(files_w = p$files_w, composer_h = p$composer_h, sess_w = p$sess_w,
       menu_w = p$menu_w, tasks_w = p$tasks_w, filespage_w = p$filespage_w)
}

# ⚠️ 期望值一律用 ups_want() 拼，**不要**在每条断言里把五个键手写一遍。
#    2026-09-16 就是手写的：V13.4 item 6 加 sess_w 时只改了本段开头两条，
#    下面七条没跟上，八条断言红了七条 —— 而红的原因和被测代码毫无关系，
#    纯粹是"抄了七份的期望值漏改了六份"。默认值现在只有 ups_def() 一处。
#
# ⚠️★ V13.5：这里**又**踩了同一个坑。上面那条"全键"断言里写死了一份键名
#    清单，V13.4 item 8 / V13.5 item 2 往 DSAPP_UIPREF_SPECS 里加了 menu_w
#    和 tasks_w 之后它就红了 —— 红的是清单，不是代码。现在键名清单直接从
#    DSAPP_UIPREF_SPECS 取（那才是唯一的事实来源），只有**默认值**还需要
#    在 ups_def() 里抄一份：抄漏的表现是"这几条断言量不到新加的那一格"，
#    而下面单有一条专门盯着两边对不对得上。
ups_def <- function() list(files_w = 320L, composer_h = 0L, sess_w = 260L,
                           menu_w = 264L, tasks_w = 520L,
                           filespage_w = 420L)
ups_want <- function(...) utils::modifyList(ups_def(), list(...))

chk("★ 什么都没设过 → 全套默认值（不是 NULL、不是少键）",
    identical(ups_int(NULL), ups_want()) &&
      identical(sort(names(dsapp_uipref_norm(NULL))),
                sort(names(DSAPP_UIPREF_SPECS))),
    paste(utils::capture.output(str(dsapp_uipref_norm(NULL))), collapse = " "))
# ★ 上面那条只保证"键齐全"，不保证 ups_def() 里抄的数字是对的（这五个数
#   每一个都在别处有第二份拷贝：app.css 的 var() fallback、mod_chat.R 的
#   sidebar(width=)、codex.css 的 grid-template-columns）。分开验，红了
#   能一眼看出是"漏了一格"还是"数字抄错了"。
ups_from_specs <- function() {
  p <- dsapp_uipref_norm(NULL)
  list(files_w   = as.integer(DSAPP_UIPREF_SPECS$files_w$def),
       composer_h = as.integer(DSAPP_UIPREF_SPECS$composer_h$def),
       sess_w    = as.integer(DSAPP_UIPREF_SPECS$sess_w$def),
       menu_w    = as.integer(DSAPP_UIPREF_SPECS$menu_w$def),
       tasks_w   = as.integer(DSAPP_UIPREF_SPECS$tasks_w$def),
       filespage_w = as.integer(DSAPP_UIPREF_SPECS$filespage_w$def))
}
chk("★★ ups_def() 抄的那几个和真实默认值一字不差（抄错 = 断言量的是虚的）",
    identical(ups_int(NULL), ups_from_specs()),
    sprintf("ups_def: %s  specs: %s",
            paste(unlist(ups_int(NULL)), collapse = ","),
            paste(unlist(ups_from_specs()), collapse = ",")))

chk("★★ 越界值夹回边界（有人在库里手填 99999 也不许把界面撑坏）",
    identical(ups_int(list(files_w = 99999, composer_h = -5, sess_w = 99999)),
              ups_want(files_w = 900L, composer_h = 0L, sess_w = 520L)))
chk("★ 非数字 / Inf / NA 一律回默认值，不是当成 0",
    identical(ups_int(list(files_w = "abc", composer_h = Inf)), ups_want()) &&
      identical(ups_int(list(files_w = NA, composer_h = NaN)), ups_want()))
chk("★ 小数取整", identical(dsapp_uipref_norm(list(files_w = 419.6))$files_w, 420L))
chk("★ 收到的本来就是 JSON 文本（从库里读出来就是这样）",
    identical(ups_int('{"files_w":420,"composer_h":300}'),
              ups_want(files_w = 420L, composer_h = 300L)))
chk("★ 坏 JSON 当空的用（不抛）",
    identical(ups_int("{坏"), ups_want()))

# ---- 排序那两个键（V13.2 item 13）----
chk("★ 排序方式只认白名单里那几个，别的一律回 custom",
    identical(dsapp_uipref_norm(list(skills_sort = "name"))$skills_sort, "name") &&
      identical(dsapp_uipref_norm(list(skills_sort = "按名称"))$skills_sort, "custom") &&
      identical(dsapp_uipref_norm(list(skills_sort = NULL))$skills_sort, "custom") &&
      identical(dsapp_uipref_norm(list(skills_sort = c("a", "b")))$skills_sort, "custom"))
chk("★★ 界面能选的排序值 = 查询认的排序值（分叉了就是「选了按名称、看到的还是拖拽序」）",
    identical(sort(DSAPP_UIPREF_SPECS$skills_sort$choices),
              sort(DSAPP_SKILLS_SORTS)))
chk("★ 正倒序认逻辑值和 0/1（浏览器发的是 0/1，库里存的是 true/false）",
    isTRUE(dsapp_uipref_norm(list(skills_desc = TRUE))$skills_desc) &&
      isTRUE(dsapp_uipref_norm(list(skills_desc = 1))$skills_desc) &&
      !isTRUE(dsapp_uipref_norm(list(skills_desc = 0))$skills_desc) &&
      !isTRUE(dsapp_uipref_norm(list(skills_desc = "yes"))$skills_desc))

# ---- 发到页面的那段 <style> ----
#
# ⚠️ 断言的是**拼出来的字符串**，不是"调了没报错"：这段最终要变成 CSS 变量，
#    少一个 `px`、变量名拼错一个字母，浏览器不会报任何错，只是那两条规则
#    静默失效 —— 页面看上去一切正常，就是拖不动。
ups_css <- as.character(dsapp_uipref_css(list(files_w = 420, composer_h = 300)))
chk("★★ 变量名和 app.css 里的 var() 对得上，单位没漏",
    grepl("--dsapp-files-w:420px", ups_css, fixed = TRUE) &&
      grepl("--dsapp-composer-h:300px", ups_css, fixed = TRUE), ups_css)
# ★ V13.4 item 6：导航栏那一条也必须发出来，而且**每次**都发（不是只在
#   "调过"的时候）—— 变量没发出去的表现是 codex.css 里那条 `var(--dsapp-sess-w,
#   260px)` 一直走 fallback，用户拖了、存了、刷新，还是 260。
chk("★ 导航栏宽度也发成变量了（漏了就是「拖了、存了、刷新还是原样」）",
    grepl("--dsapp-sess-w:260px",
          as.character(dsapp_uipref_css(list(sess_w = 260))), fixed = TRUE) &&
      grepl("--dsapp-sess-w:", ups_css, fixed = TRUE), ups_css)
chk("★ 服务端那段脚本把内联的导航栏变量也清掉（不清就一直压着设置页填的值）",
    grepl("removeProperty('--dsapp-sess-w')", ups_css, fixed = TRUE), ups_css)
# ★ V14 item 1：**通用**一条 —— 每一个"像素"类偏好都必须两处都有份：
#   发成 CSS 变量（少了 = 那条 var() 永远走 fallback，拖了白拖）、
#   以及出现在清内联变量的清单里（少了 = 设置页改了不生效，拖动留下的
#   内联值一直压着样式表，控制台一个错都没有）。
#
#   ⚠️ 故意写成"遍历 DSAPP_UIPREF_SPECS"而不是逐个键手写：手写的清单在
#      加新面板时不会红，只会少测一格 —— V13.5 加 menu_w/tasks_w 时正是
#      这么漏过去的（当时只补了断言里提到的那几个字面量）。
ups_px <- Filter(function(nm) identical(DSAPP_UIPREF_SPECS[[nm]]$kind, "int"),
                 names(DSAPP_UIPREF_SPECS))
ups_missing <- Filter(function(nm) {
  v <- sprintf("--dsapp-%s:", gsub("_", "-", nm, fixed = TRUE))
  !grepl(v, ups_css, fixed = TRUE) ||
    !grepl(sprintf("removeProperty('%s')", sub(":$", "", v)), ups_css, fixed = TRUE)
}, ups_px)
chk("★★ 每个像素偏好都既发变量、又在清内联的清单里（漏一个就是「拖完/填完不生效」）",
    length(ups_px) >= 6 && length(ups_missing) == 0,
    sprintf("像素键 %d 个；漏掉的：%s", length(ups_px),
            if (length(ups_missing)) paste(ups_missing, collapse = ",") else "（无）"))

chk("★★ 发的是 <style> + <script> 两件套（类必须跟着一起来）",
    grepl("<style", ups_css, fixed = TRUE) &&
      grepl("dsapp-fixed-composer", ups_css, fixed = TRUE) &&
      grepl("removeProperty", ups_css, fixed = TRUE), ups_css)
chk("★★ composer_h = 0 时类是 false（0 是「自动高度」，不是「高度为零」）",
    grepl("dsapp-fixed-composer',0>0",
          as.character(dsapp_uipref_css(list(composer_h = 0))), fixed = TRUE))

# ---- 落库 / 读回 ----
ups_user <- dsapp_user_create("面板自检", "selftest_uipref@example.com",
                              "13800000002", "生信",
                              "Pw-12345678", "Pw-12345678", con = ups_con)
ups_uid <- ups_user$user$id
chk("★ 造得出面板自检的账号", !is.null(ups_uid))

if (!is.null(ups_uid)) {
  chk("★ 新账号读出来是默认值（users.ui_prefs 是 NULL，不是没这列）",
      identical(ups_int(dsapp_uipref_get(ups_uid, con = ups_con)),
                ups_want()))

  dsapp_uipref_save(ups_uid, list(files_w = 420, composer_h = 280), con = ups_con)
  chk("★ 存进去、读回来是同一份",
      identical(ups_int(dsapp_uipref_get(ups_uid, con = ups_con)),
                ups_want(files_w = 420L, composer_h = 280L)))

  # ★ 这一条是"存档时脏输入永远进不了库"的保证：存的时候收敛，读的时候
  #   就不用再猜库里那份是什么形状。
  dsapp_uipref_save(ups_uid, list(files_w = 1e9, composer_h = "x"), con = ups_con)
  chk("★★ 存的时候收敛：越界值进库前就被夹住（下次读不用再猜）",
      identical(ups_int(dsapp_uipref_get(ups_uid, con = ups_con)),
                ups_want(files_w = 900L, composer_h = 0L)))

  # ★★ 只给一个键的时候，**另一个键必须保持原样**。
  #    设置页的 observer 和对话页的拖动都靠"读全量 → 改一个 → 写全量"这个
  #    写法（见 mod_settings.R 的 save_uipref）。这个写法一旦被改成"直接存
  #    收到的那一个键"，症状是"改完宽度，输入区高度自己变回自动了" ——
  #    而且只在用户**先调过高度**的情况下才复现。
  dsapp_uipref_save(ups_uid, list(files_w = 360, composer_h = 200), con = ups_con)
  ups_full <- dsapp_uipref_get(ups_uid, con = ups_con)
  ups_full$files_w <- 500
  dsapp_uipref_save(ups_uid, ups_full, con = ups_con)
  chk("★★ 只改宽度时高度还在（另一个键不许被顺手重置）",
      identical(ups_int(dsapp_uipref_get(ups_uid, con = ups_con)),
                ups_want(files_w = 500L, composer_h = 200L)))
  # ★ 同一个道理，换到 item 13 那两个键上：改排序**不能**把尺寸抹掉。
  ups_full2 <- dsapp_uipref_get(ups_uid, con = ups_con)
  ups_full2$skills_sort <- "name"
  dsapp_uipref_save(ups_uid, ups_full2, con = ups_con)
  ups_back <- dsapp_uipref_get(ups_uid, con = ups_con)
  chk("★★ 改排序不动尺寸（同一个「读全量 → 改一个 → 写全量」的写法）",
      identical(ups_back$skills_sort, "name") &&
        identical(ups_int(ups_back), ups_want(files_w = 500L, composer_h = 200L)))

  # ---- 不登录 / 库坏了，都不许抛 ----
  #
  # 读尺寸发生在**登录闸门写 state$user_id 之前**（首屏已经渲染过一次），
  # 那时候 user_id 是 NULL。这里要是抛，用户看到的是白屏。
  chk("★ 没登录（user_id = NULL）时给默认值，不查库",
      identical(ups_int(dsapp_uipref_get(NULL, con = ups_con)), ups_want()) &&
        identical(ups_int(dsapp_uipref_get(NA, con = ups_con)), ups_want()))
  chk("★★ 库是坏的也不抛（抛出去就是整个言出法随页渲染不出来）", {
    bad_cfg <- dsapp_config(); bad_cfg$db_path <- tempdir()
    bad_con <- tryCatch(dsapp_db(bad_cfg), error = function(e) NULL)
    res <- tryCatch(dsapp_uipref_get(ups_uid, con = bad_con),
                    error = function(e) e)
    # 上面那句会把进程内的单例连接换成坏的，**必须换回来** —— 否则后面所有
    # 断言都在一个连不上的库上跑，红一片，看起来完全不像这段引起的。
    dsapp_db(dsapp_config())
    identical(ups_int(res), ups_want())
  })
}

section("V13.2 item 11 + 13：技能列表的文件夹形态 / 排序 / 拖拽顺序")

# 用户原话：
#   item 11「skills界面只能打开看到文字，建议以文件夹的形式，这样能展示
#            skills的更多内置文件信息」
#   item 13「skills需要能够支持按照名称、时间等信息进行排序，并且可以拖拽
#            自定义顺序」
#
# ⚠️ 这一段测的是**数据层**：「展开之后那几行真的渲染出来了吗」在浏览器里，
#    见 tests/ui_v132/skills_tree.py。两边缺一不可。
#
# ⚠️ 用**新开的**账号（sk2_*），不复用上面 ups_uid：上面那段最后把单例连接
#    指向过一个坏库，虽然换回来了，但混在一起排查起来要多想一层。
sk2_con <- dsapp_db(dsapp_config())

# ---- item 11：内置技能的"文件信息"能查到 ----
#
# ★ 这些**不在库里**：repo / license 在 .md 的 frontmatter 里，文件名更是
#   只在盘上。所以查不到的时候要返回 NULL（少显示一块），不能瞎编。
sk2_bi <- dsapp_skill_builtin_info("学术论文写作与同行评审")
chk("★★ 按名字查得到内置技能的来源信息（repo / license / 文件名）",
    !is.null(sk2_bi) && identical(sk2_bi$file, "academic-research.md") &&
      identical(sk2_bi$meta[["repo"]], "Imbad0202/academic-research-skills") &&
      identical(sk2_bi$meta[["license"]], "CC-BY-NC-4.0"),
    if (is.null(sk2_bi)) "查不到" else paste(names(sk2_bi$meta), collapse = ","))
chk("★ 它有字节数（列表里显示的「50.1 KB」就是它）",
    !is.null(sk2_bi) && isTRUE(sk2_bi$bytes > 10000), sk2_bi$bytes %||% NA)
chk("★★ 查一条不存在的 → NULL，不是随便返回一条（那会显示成别人的文件名）",
    is.null(dsapp_skill_builtin_info("这条技能根本不存在")) &&
      is.null(dsapp_skill_builtin_info(NULL)) &&
      is.null(dsapp_skill_builtin_info("")))

# =============================================================================
section("V13.16 item 28：技能页整页渲染崩（frontmatter 少一个键就炸）")
# =============================================================================
# 用户原话：「技能界面有一个error：An error has occurred. Check your logs or
#           contact the app author for clarification.」
#
# ★ 那句英文不是这个应用写的 —— 是线上 sanitize_errors 把真实错误换掉之后的
#   文本（见 R/errhand.R 顶上那段）。真错误是：
#
#     Error in [[: subscript out of bounds
#       104: %||% [R/mod_skills.R#497]
#       103: FUN [R/mod_skills.R#497]
#       102: lapply
#       101: renderUI [R/mod_skills.R#378]
#        86: output$skills-list_ui
#
#   mod_skills.R:497 是 `binfo$meta[["repo"]] %||% ""`，而 dsapp_skill_parse
#   当时把 meta 造的是 **character(0)**。关键区别：
#
#     list()["repo"]        → NULL        ← 取不到就是 NULL
#     list()[["repo"]]      → NULL
#     character(0)[["repo"]]→ **subscript out of bounds**（硬错误）
#
#   前 12 篇内置技能的 frontmatter 都带 `repo:` / `license:`，所以一直没暴露；
#   V13.12 item 14 搬进来的 academic-search 和 deeppapernote 是上游 SKILL.md
#   原样拿过来的，frontmatter 只有 name/description —— 一进技能页就炸，
#   而炸的是**整个列表那一个 output**，所以页面上一条技能都没有。
#
# ⚠️ 下面第 2 条（遍历**全部**内置技能）才是真正防复发的那条。只测
#    academic-search 的话，下次搬进来一条少写别的键的技能，同一个坑照踩。
{
  # ---- 1) 不变量本身：取不存在的键返回 NULL，不抛 ----
  par28 <- dsapp_skill_parse("---\nname: 甲\n---\n\n# 甲\n正文\n", "甲.md")
  chk("★★★ meta 里取一个不存在的键返回 NULL（不是抛 subscript out of bounds）",
      is.null(tryCatch(par28$meta[["repo"]], error = function(e) stop("抛了：",
                                                                     conditionMessage(e)))) &&
        identical(par28$meta[["name"]], "甲") &&
        # 取不到时 %||% 要能兜住 —— 技能页那两行就靠这个
        identical(par28$meta[["license"]] %||% "", ""))
  chk("★ 连 frontmatter 都没有的文件同样不抛",
      identical(dsapp_skill_parse("# 无头\n正文\n")$meta[["repo"]] %||% "", "") &&
        identical(dsapp_skill_parse("")$meta[["repo"]] %||% "", ""))

  # ---- 2) ★★ 真正的那条：每一条内置技能都要能过技能页那一行 ----
  #    这里**照抄** mod_skills.R:496-500 的算法，不是"跟源码长得像"——
  #    那样改了两边会分叉。所以顺带断言那几行的形状没变（见第 3 条）。
  bi28 <- dsapp_skills_builtin_md(refresh = TRUE)
  chk("★ 前提：内置技能确实读到了一批（读不到的话下面几条是空转）",
      length(bi28) >= 12, length(bi28))

  src28 <- vapply(bi28, function(s) {
    tryCatch({
      repo <- s$meta[["repo"]] %||% ""
      lic  <- s$meta[["license"]] %||% ""
      paste(c(if (nzchar(repo)) repo else "内置",
              if (nzchar(lic)) lic else NULL), collapse = " · ")
    }, error = function(e) paste0("!! ", conditionMessage(e)))
  }, character(1))
  bad28 <- names(src28)[grepl("^!! ", src28)]
  chk("★★★ 每一条内置技能都渲染得出「来源」那一行（少写 frontmatter 键也不行）",
      length(bad28) == 0,
      if (length(bad28)) paste(bad28, src28[bad28], sep = " → ", collapse = "；") else "")

  # ---- 3) 踩坑现场：那两条没有 repo/license 的技能还在 ----
  #    它们**是**这条 bug 的现场。哪天有人"顺手给它们补上 repo"，
  #    第 2 条会变成在一条不会出问题的数据上空转 —— 这里先把它钉住。
  nm28 <- vapply(bi28, function(s) s$name, character(1))
  chk("★★ academic-search / deeppapernote 两条都在，且确实没有 repo / license",
      all(c("academic-search", "deeppapernote") %in% nm28) &&
        all(vapply(bi28[nm28 %in% c("academic-search", "deeppapernote")],
                   function(s) is.null(s$meta[["repo"]]) &&
                     is.null(s$meta[["license"]]), logical(1))),
      paste(nm28, collapse = ","))

  # ---- 4) 反向：不能为了"不抛"把 meta 整个清空 ----
  #    那样第 2 条会全绿，而技能页上 12 条内置技能全变成「内置」两个字。
  chk("★★ 有 repo 的那条还是原样（不是把所有 meta 都清掉了）",
      identical(sk2_bi$meta[["repo"]], "Imbad0202/academic-research-skills") &&
        identical(sk2_bi$meta[["license"]], "CC-BY-NC-4.0") &&
        sum(grepl(" · ", src28)) >= 10,
      paste(sum(grepl(" · ", src28)), "条带「来源 · 许可」"))

  # ---- 5) 技能页那两行的形状没变（第 2 条是照着它抄的）----
  #    ⚠️ 先过 strip_comments：`[[` 和 `%||%` 在注释里也出现过，不过滤的话
  #       源码里把这两行删掉、只留注释，这条照样绿。
  msk28 <- strip_comments(paste(readLines("R/mod_skills.R", warn = FALSE),
                                collapse = "\n"))
  chk("★★ 技能页确实还在用 meta[[\"repo\"]] / meta[[\"license\"]] 取来源",
      grepl('meta[["repo"]] %||% ""', msk28, fixed = TRUE) &&
        grepl('meta[["license"]] %||% ""', msk28, fixed = TRUE))
}

# =============================================================================
section("V13.16 item 29：新增内置技能 paper-reading")
# =============================================================================
# 用户原话：「添加这个文献阅读skills：https://github.com/huicod/paper-reading-skill/」。
#
# 上游是给 Gemini Code Assist 的 `.agents/skills/` 写的，按本平台的
# **文件夹形态**收进来（和 academic-search / deeppapernote 同一套）。
#
# ⚠️ 这一段测的是"收进来了、配套文件都在、适配说明写了没有"。
#    "模型读了它会不会照着做"不在自检能测的范围里。
{
  pr29 <- Filter(function(x) identical(x$name, "paper-reading"),
                 dsapp_skills_builtin_md(refresh = TRUE))
  chk("★★★ 内置技能里读得到 paper-reading（文件夹形态，不是丢了）",
      length(pr29) == 1 &&
        identical(pr29[[1]]$file, "paper-reading/SKILL.md"),
      if (length(pr29)) pr29[[1]]$file else "没读到")
  pr29 <- if (length(pr29)) pr29[[1]] else NULL

  if (!is.null(pr29)) {
    # ---- 配套文件：少一个，正文里写着的相对路径就断一条 ----
    p29 <- vapply(pr29$files, function(f) f$path, character(1))
    need <- c("scripts/mineru_convert.py", "scripts/quality_check.py",
              "templates/reading_guide_template.md",
              "templates/report_template.md", "README.md")
    chk("★★★ 上游那几个配套文件都在（正文是照着相对路径引用它们的）",
        all(need %in% p29), paste(setdiff(need, p29), collapse = ","))
    chk("★★ 配套文件都读到了内容（只有名字没有内容的等于没有）",
        all(vapply(pr29$files, function(f) !is.null(f$raw), logical(1))))

    # ---- ★★ Token 绝不能被带进仓库 ----
    # 上游把 Token 放在 `api_key/key.txt`（它的 .gitignore 排除了）。
    # 这里要断的是**盘上真没有这个文件**，不是"路径字符串里没有"——
    # 正文里本来就该提到 `api_key/key.txt`（要告诉用户往哪儿放），
    # 拿它当判据的话这条永远红。
    pr_dir <- dsapp_skills_builtin_dir()
    pr_files <- list.files(file.path(pr_dir, "paper-reading"),
                           recursive = TRUE, all.files = TRUE,
                           full.names = FALSE)
    chk("★★★ 仓库里没有 api_key/ 或 key.txt（Token 是用户的，不能跟着技能走）",
        !any(grepl("(^|/)api_key(/|$)", pr_files)) &&
          !any(grepl("\\.key$|key\\.txt$", pr_files, ignore.case = TRUE)),
        paste(pr_files[grepl("key", pr_files, ignore.case = TRUE)],
              collapse = ","))

    # ---- frontmatter：技能页那一行要显示的 ----
    chk("★★ 有 repo / license（技能页「来源」那一行靠它，缺了就只显示「内置」）",
        identical(pr29$meta[["repo"]], "huicod/paper-reading-skill") &&
          grepl("MIT", pr29$meta[["license"]] %||% ""),
        pr29$meta[["repo"]] %||% "(无)")
    chk("★★ summary 是压短过的（上游 description 两百多字，直接当简介会把列表撑成一面墙）",
        nzchar(pr29$summary) && nchar(pr29$summary, type = "chars") <= 120 &&
          !grepl("触发条件", pr29$summary, fixed = TRUE),
        nchar(pr29$summary, type = "chars"))

    # ---- ★★ 适配说明：不写清"宿主不一样"，模型会照着上游的路径跑 ----
    b29 <- pr29$body
    chk("★★★ 文首有「本平台的适配说明」",
        grepl("本平台的适配说明", b29, fixed = TRUE) &&
          regexpr("本平台的适配说明", b29, fixed = TRUE)[[1]] <
            regexpr("# Paper Reading Skill", b29, fixed = TRUE)[[1]],
        "适配说明必须在上游正文之前")
    chk("★★★ 说明了 MinerU Token 本平台没有预置（不然模型会让用户去翻 key.txt）",
        grepl("Token 本平台没有预置", b29, fixed = TRUE))
    chk("★★★ 给了没有 Token 时的替代路（pypdf 抽文本）",
        grepl("pypdf", b29, fixed = TRUE))
    chk("★★★ 而且要**如实说明丢了什么**（图 / 公式 / 表格）—— 不能说得像等价的",
        grepl("图片、公式、复杂表格全丢", b29, fixed = TRUE) ||
          (grepl("公式", b29, fixed = TRUE) && grepl("表格", b29, fixed = TRUE)))
    chk("★★ 写明了脚本路径相对技能目录（上游那些 .agents/skills/... 在这儿找不到）",
        grepl(".agents/skills/", b29, fixed = TRUE) &&
          grepl("不要运行", b29, fixed = TRUE))
    # ⚠️ 三条技能都会被"帮我读这篇论文"触发。不写分工的话，模型会挑一条
    #    顺手的 —— 而这条是最重的（4 个阶段、4 个文件），挑错了用户会
    #    莫名其妙等很久。
    chk("★★★ 写清了和 deeppapernote / 文献速递 的分工",
        grepl("deeppapernote", b29, fixed = TRUE) &&
          grepl("文献速递", b29, fixed = TRUE) &&
          grepl("该用哪条", b29, fixed = TRUE))

    # ---- 名字不撞车（撞了的话 dsapp_skills_seed 的 (user_id, name) 会认错）----
    nm29 <- vapply(dsapp_skills_builtin_md(), function(x) x$name, character(1))
    chk("★★ 名字在库里唯一（seed 是按 (user_id IS NULL, name) 配对的）",
        sum(nm29 == "paper-reading") == 1 && !anyDuplicated(nm29))
  }
}

# =============================================================================
section("V13.16 item 30：技能页「关于技能」换成新介绍")
# =============================================================================
# 用户原话：「关于技能的介绍换成以下内容：在 AI Agent 体系里，Skill（技能）
#           是封装好、可被 Agent 调用的独立能力单元……本平台支持自定义技能
#           并上传！」
#
# ⚠️ 用户说的是换**介绍**。这一页下面那几条是**操作说明**（按对话挂载 /
#    两个池 / 另存为我的），删掉的话用户会以为勾过的技能对所有对话生效，
#    也找不到自己建的技能。所以这里两个方向都要断：新的在，旧的介绍不在，
#    **而操作说明一条都没少**。
{
  sk30 <- strip_comments(paste(readLines("R/mod_skills.R", warn = FALSE),
                               collapse = "\n"))

  chk("★★★ 新介绍在（开头那句）",
      grepl("在 AI Agent 体系里", sk30, fixed = TRUE) &&
        grepl("可被 Agent 调用的独立能力单元", sk30, fixed = TRUE))
  chk("★★★ 三条「可以和 AI 约定」的例子都在",
      grepl("300 dpi", sk30, fixed = TRUE) &&
        grepl("必须由代码生成，不可由 AI 生成", sk30, fixed = TRUE) &&
        grepl("避免 AI 幻觉", sk30, fixed = TRUE))
  chk("★★★ 「本平台支持自定义技能并上传」这句在",
      grepl("自定义技能并上传", sk30, fixed = TRUE))

  # ---- 反向：老的介绍不许留半句（留一半会读成两段互相打架的话）----
  chk("★★★ 老的开头没了（「写给 AI 看的一段要求」那句）",
      !grepl("写给 AI 看的一段要求", sk30, fixed = TRUE))

  # ---- ★★ 反向的另一半：操作说明**一条都不能少** ----
  chk("★★★ 操作说明原样留着：按对话挂载 / 两个池 / 另存为我的",
      grepl("按对话挂载", sk30, fixed = TRUE) &&
        grepl("公共技能库", sk30, fixed = TRUE) &&
        grepl("另存为我的", sk30, fixed = TRUE))
  chk("★★ 「写一次、以后每次都能勾」那句也还在（它解释技能和随手打一句的区别）",
      grepl("写一次、以后每次都能勾", sk30, fixed = TRUE))

  # ---- 排版：原话里的 ASCII 直引号在中文里是"看着像少了个字"的那种不对 ----
  chk("★★ 「智能员工」用的是全角引号（原话里是 ASCII 直引号）",
      grepl("「智能员工」", sk30, fixed = TRUE) &&
        !grepl('"智能员工"', sk30, fixed = TRUE))
  chk("★ 「更高效地使用」（原话是「高效的」）",
      grepl("更高效地使用", sk30, fixed = TRUE))
}

# ---- item 11：目录（正文里的 ## 小节）----
chk("★ 从正文里抽得出骨架，而且抽的是 H2 不是别的",
    identical(dsapp_skills_outline("# 标题\n\n## 一、甲\n正文\n### 更深一层\n\n## 二、乙\n"),
              c("一、甲", "二、乙")))
chk("★ 没有小节、空正文、NULL —— 一律给空向量，不抛",
    identical(dsapp_skills_outline("就一行字"), character(0)) &&
      identical(dsapp_skills_outline(""), character(0)) &&
      identical(dsapp_skills_outline(NULL), character(0)))
chk("★ 小节特别多的时候截断（一篇几十节的正文不该把列表撑成一面墙）",
    length(dsapp_skills_outline(paste(sprintf("## 第%d节", 1:60), collapse = "\n"),
                                max_n = 40L)) == 41L)

# ---- item 13：排序 ----
sk2_user <- dsapp_user_create("技能排序自检", "selftest_skillorder@example.com",
                              "13800000003", "生信",
                              "Pw-12345678", "Pw-12345678", con = sk2_con)
sk2_uid <- sk2_user$user$id
chk("★ 造得出技能排序自检的账号", !is.null(sk2_uid))

if (!is.null(sk2_uid)) {
  mk <- function(nm, tags = "自检") {
    r <- dsapp_skill_save(user_id = sk2_uid, name = nm,
                          summary = paste0("简介 ", nm),
                          body = "## 甲\n正文\n## 乙\n更多",
                          tags = tags, con = sk2_con)
    if (isTRUE(r$ok)) r$id else NA_integer_
  }
  sk2_a <- mk("甲技能")
  sk2_b <- mk("乙技能")
  sk2_c <- mk("丙技能")
  chk("★ 前提：建得出三条自己的技能",
      !any(is.na(c(sk2_a, sk2_b, sk2_c))), paste(sk2_a, sk2_b, sk2_c))

  sk2_names <- function(...) dsapp_skills_list(sk2_uid, con = sk2_con, ...)$name

  # 默认（没拖过）= custom，而 custom 下没排过的按名称 —— 加上内置那一批，
  # 所以这里只检查"我建的那三条"的相对顺序，不假设整个列表长什么样。
  sk2_mine <- function(v) v[v %in% c("甲技能", "乙技能", "丙技能")]
  chk("★ 没有内置干扰时，三条自己的技能按名称排（默认就是 custom）",
      identical(sk2_mine(sk2_names()), c("丙技能", "乙技能", "甲技能")),
      paste(sk2_mine(sk2_names()), collapse = ","))

  chk("★ sort = name 正序 / 倒序",
      identical(sk2_mine(sk2_names(sort = "name")),
                c("丙技能", "乙技能", "甲技能")) &&
        identical(sk2_mine(sk2_names(sort = "name", desc = TRUE)),
                  c("甲技能", "乙技能", "丙技能")))
  chk("★ 认不出来的 sort 静默回落 custom（不抛、也不是「不排序」）",
      identical(sk2_names(sort = "啥"), sk2_names(sort = "custom")) &&
        identical(sk2_names(sort = NULL), sk2_names(sort = "custom")) &&
        identical(sk2_names(sort = c("name", "created")), sk2_names(sort = "custom")))
  chk("★ sort = created / updated 不抛，而且条数对得上",
      length(sk2_names(sort = "created")) == length(sk2_names()) &&
        length(sk2_names(sort = "updated", desc = TRUE)) == length(sk2_names()))

  # ★★ 核心：拖出来的顺序
  sk2_all <- dsapp_skills_list(sk2_uid, con = sk2_con)$id
  sk2_rev <- rev(sk2_all)          # 整个列表倒过来
  dsapp_skill_order_set(sk2_uid, sk2_rev, con = sk2_con)
  chk("★★★ 拖完之后列表就是那个顺序（custom 排在最前，全部被 pin 住）",
      identical(dsapp_skills_list(sk2_uid, con = sk2_con)$id, as.integer(sk2_rev)),
      paste(head(dsapp_skills_list(sk2_uid, con = sk2_con)$id, 5), collapse = ","))

  # ★★ 这一条是"顺序是每个人自己的看法"的**唯一**证明。
  #    内置技能是**全站共享的一行**（user_id IS NULL），顺序要是存在 skills
  #    表上，这里两个账号读到的就是同一份 —— 而用户根本不知道自己的拖动
  #    改了别人的界面。
  sk2_other <- dsapp_user_create("技能顺序旁人", "selftest_skillorder2@example.com",
                                 "13800000004", "生信",
                                 "Pw-12345678", "Pw-12345678", con = sk2_con)
  sk2_ouid <- sk2_other$user$id
  chk("★★★ 另一个账号看到的内置技能顺序**不受影响**（顺序是按账号存的）",
      !is.null(sk2_ouid) &&
        !identical(dsapp_skills_list(sk2_ouid, con = sk2_con)$id,
                   dsapp_skills_list(sk2_uid, con = sk2_con)$id),
      "两人一样 —— 顺序多半写到共享的那一行上去了")

  # ★★ 浏览器发上来的 id 不能信
  dsapp_skill_order_set(sk2_uid,
                        c(sk2_all, 999999L, -1L, sk2_all, NA), con = sk2_con)
  chk("★★ 上报里混进不存在的号 / 别人的号 / 重复的号 —— 一律丢掉，不抛",
      identical(sort(dsapp_skills_list(sk2_uid, con = sk2_con)$id),
                sort(as.integer(sk2_all))))
  chk("★ 上报里一个合法的都没有时什么都不写（不是把顺序清空）", {
    before <- dsapp_skills_list(sk2_uid, con = sk2_con)$id
    dsapp_skill_order_set(sk2_uid, c(999999L, "甲"), con = sk2_con)
    identical(dsapp_skills_list(sk2_uid, con = sk2_con)$id, before)
  })
  chk("★ user_id 是 NULL / NA 时直接返回 FALSE，不写行",
      identical(dsapp_skill_order_set(NULL, sk2_all, con = sk2_con), invisible(FALSE)) &&
        identical(dsapp_skill_order_set(NA, sk2_all, con = sk2_con), invisible(FALSE)))

  # ⚠️ 上面那两条"脏 id"的断言走的就是**写顺序**这条路，所以顺序已经被
  #    按 sk2_all（原始序）重写了一遍。这里重新拖一次再验下面两条，
  #    否则验的是"脏 id 那次写进去的东西"，而不是"拖出来的顺序会不会被
  #    别的操作抹掉"。
  dsapp_skill_order_set(sk2_uid, sk2_rev, con = sk2_con)

  # ★ 切到"按名称"之后，拖出来的顺序**不该**还在起作用（否则那个下拉
  #   看起来就是个摆设）。
  chk("★★ 切到按名称之后，拖出来的顺序让位",
      identical(sk2_mine(dsapp_skills_list(sk2_uid, con = sk2_con, sort = "name")$name),
                c("丙技能", "乙技能", "甲技能")))
  # 再切回 custom，拖出来的顺序还在（没有因为切过一次就被抹掉）
  chk("★★ 切回自定义，之前拖的顺序还在（切排序不会把拖出来的顺序抹掉）",
      identical(dsapp_skills_list(sk2_uid, con = sk2_con)$id, as.integer(sk2_rev)))

  # ★ 删掉一条之后，它的顺序行留着也无害（读的时候按 id 取不到就没了）。
  dsapp_skill_delete(sk2_c, user_id = sk2_uid, con = sk2_con)
  chk("★★ 删掉一条之后列表照样读得出来（不抛、也没少别人）",
      identical(sort(dsapp_skills_list(sk2_uid, con = sk2_con)$id),
                sort(as.integer(sort(sk2_all[sk2_all != sk2_c])))))

  # 拖完之后**新建**的技能没有 ord —— 它必须落在最后，而不是插到中间。
  sk2_d <- mk("丁技能")
  chk("★★ 拖完之后才建的那条落在最后（没有 ord 的排在有 ord 的后面）",
      !is.na(sk2_d) &&
        tail(dsapp_skills_list(sk2_uid, con = sk2_con)$id, 1) == sk2_d,
      paste(tail(dsapp_skills_list(sk2_uid, con = sk2_con)$id, 3), collapse = ","))
}

section("V12 item 4：环境配置上传 + 内置模板")

# 用户原话：「环境也要像 skills 一样可以自动上传配置，帮我预设单细胞/空转
# 环境」。这一段管的是**解析**那一半：模板在不在、能不能解析回原样、用户
# 传上来的各种形状认不认。界面那一半在 tests/ui_v12/envs.py 里 ——
# 那边的关键一条是"换模板真的会把文本灌进编辑器"，因为那一步走的是
# updateTextAreaInput + 模块 session，这个仓库对"模块 session 上哪些方法
# 能用"有过两种互相矛盾的说法（见 utils.R 的 dsapp_session）。

tpl <- dsapp_env_templates()
chk("★ 内置了「单细胞」「空转」两个模板",
    identical(names(tpl), c("单细胞", "空转")), paste(names(tpl), collapse = " | "))
chk("★ 两个模板的环境名合法（不合法的话一键建会在最后一步被拒）",
    all(vapply(tpl, function(t) !nzchar(dsapp_env_name_ok(t$name)), logical(1))),
    paste(vapply(tpl, function(t) t$name, character(1)), collapse = " | "))
chk("★ 两个模板都有实质内容（空模板＝预设了个寂寞）",
    all(vapply(tpl, function(t) length(t$packages) >= 10, logical(1))),
    paste(vapply(tpl, function(t) length(t$packages), integer(1)), collapse = " | "))

for (nm in names(tpl)) {
  txt <- dsapp_env_template_text(tpl[[nm]])
  s   <- dsapp_envspec_parse(txt)
  chk(sprintf("★ 模板「%s」渲染出来的文本能解析回去（看到的＝用的）", nm),
      isTRUE(s$ok), s$msg)
  chk(sprintf("模板「%s」往返之后包清单一字不差", nm),
      identical(sort(s$packages), sort(tpl[[nm]]$packages)),
      sprintf("解析 %d / 定义 %d", length(s$packages), length(tpl[[nm]]$packages)))
  chk(sprintf("★ 模板「%s」里没有残留的注释行被当成包名", nm),
      !any(grepl("^#", s$packages)), paste(s$packages, collapse = " "))
  # 模板里那些"要的时候再加"的包是以注释形式出现在文本里的（用户看得到、
  # 取消注释就能装）。它们**不能**被解析成要装的包 —— 真装上会让 solve 慢
  # 很多，而且 cellpose / napari 这类还要 torch 和 Qt。
  heavy <- c("celltypist", "infercnvpy", "cellpose", "napari-spatialdata",
             "cell2location", "velocyto", "stardist", "tangram-sc")
  in_txt <- heavy[vapply(heavy, function(p) grepl(p, txt, fixed = TRUE), logical(1))]
  if (length(in_txt)) {
    chk(sprintf("★★ 模板「%s」里注释掉的重包没被解析成要装的包", nm),
        !any(s$packages %in% in_txt),
        paste(intersect(s$packages, in_txt), collapse = " | "))
  }
}

# ---- 用户上传的各种形状 -----------------------------------------------------
spec_min <- dsapp_envspec_parse(
  "name: my_env\npython: 3.10\nchannels: conda-forge\npackages:\n  - numpy\n  - pandas\n")
chk("★ 手写的最小配置能解析", isTRUE(spec_min$ok) &&
    identical(spec_min$name, "my_env") && identical(spec_min$python, "3.10") &&
    identical(sort(spec_min$packages), c("numpy", "pandas")), spec_min$msg)

# conda env export 的输出。用户手上现成的多半是这一种，让他照着我们的格式
# 重打一份包清单不现实。
spec_exp <- dsapp_envspec_parse(paste(c(
  "name: base", "channels:", "  - conda-forge", "  - bioconda",
  "dependencies:", "  - python=3.11.7", "  - pip", "  - numpy=1.26.4",
  "  - pip:", "    - scanpy==1.10.0", "prefix: /home/x/miniconda3"),
  collapse = "\n"))
chk("★ conda env export 的输出能解析", isTRUE(spec_exp$ok), spec_exp$msg)
chk("★★ 从 `python=3.11.7` 里认出了解释器版本（而不是把 python 当成一个包）",
    identical(spec_exp$python, "3.11") && !("python" %in% spec_exp$packages),
    spec_exp$python)
chk("★ pip 子列表里的包也收进来了", "scanpy" %in% spec_exp$packages,
    paste(spec_exp$packages, collapse = " "))
# ★ 版本号必须去掉。pip 的 `==` conda 根本不认，原样传过去整条 solve 直接
#   失败；conda 自己的 `=1.26.4` 语法上能用，但那是**从另一台机器上导出**的
#   版本，在我们的频道组合下未必还在 —— 解不出来就是二十分钟后一句
#   UnsatisfiableError。去掉是有损的，所以 must 有一条 note 说出来。
chk("★★ 版本号一律去掉（留着会让依赖解不出来）",
    !any(grepl("[<>=]", spec_exp$packages)),
    paste(spec_exp$packages, collapse = " "))
chk("★ 去掉版本这件事**说出来**了（悄悄改用户的东西不行）",
    length(spec_exp$notes) >= 1, paste(spec_exp$notes, collapse = "; "))
chk("★ prefix: 那行被忽略", !any(grepl("prefix", spec_exp$packages)))

spec_json <- dsapp_envspec_parse(paste0(
  '{"name":"myjson","channels":["conda-forge"],',
  '"dependencies":["python=3.11.7","numpy",{"pip":["scanpy==1.10.0"]}]}'))
chk("★ conda env export --json 也能解析",
    isTRUE(spec_json$ok) && identical(spec_json$name, "myjson") &&
    identical(spec_json$python, "3.11"), spec_json$msg)
chk("★ JSON 里嵌在对象里的 pip 子列表也摊平了（直接 unlist 会丢）",
    all(c("scanpy", "numpy") %in% spec_json$packages),
    paste(spec_json$packages, collapse = " "))

# ★ 带 BOM 的文件：Windows 记事本存 UTF-8 就会带。它会让第一行的 `name:`
#   读不出来，而界面上完全看不出为什么。
chk("★★ 带 BOM 的配置第一行也认",
    identical(dsapp_envspec_parse("name: bomtest\npackages:\n  - numpy\n")$name,
              "bomtest"))

# ★ 解析器**永远不许抛异常**：入参是用户粘进来的文本，什么形状都可能，
#   而它挂在 renderUI 里 —— 抛出去的后果是整张卡片变成 Error，不是一句提示。
chk("★★ 解析器对任何输入都不抛异常（它挂在 renderUI 里）", {
  bad <- c("", "{{{{", "name:", "packages:", "- - -", "a:b:c:d",
           paste(rep("x", 20000), collapse = ""),
           "name: 中文名\npackages:\n - numpy\n", "\t\t\n\n", NA_character_)
  all(vapply(bad, function(b) {
    r <- tryCatch(dsapp_envspec_parse(b), error = function(e) NULL)
    is.list(r) && !is.null(r$ok)
  }, logical(1)))
})
chk("空文本 → 不 ok 且有一句人话",
    !isTRUE(dsapp_envspec_parse("")$ok) && nzchar(dsapp_envspec_parse("")$msg))
chk("一个包都没有 → 指路到 packages: 那一行",
    grepl("packages", dsapp_envspec_parse("name: x\n")$msg))

# ---- 上传文件的编码（V12 item 4 才发现的）----------------------------------
#
# 这一段是**真踩出来的**：GBK 的文件走 dsapp_read_text_file 出来还是乱码，
# 而且不报错。原因在 fallback 那一半 —— 原来的写法是
# `readLines(path, encoding = "GBK")`，而 readLines 的 encoding 参数只认得
# "latin1" 和 "UTF-8"：它的作用是给读进来的串**打上**编码标记，不是按这个
# 编码**转**一遍。传 "GBK" 不报错、也不转换，返回的还是同一串无效字节。
# 于是判据（iconv 出 NA）成立、fallback 也跑了、返回的还是乱码 —— 两次读
# 出来的东西一模一样。
#
# ⚠️ 这个探针**必须**带中文。纯 ASCII 的文件在 UTF-8 和 GBK 下字节完全
#    相同，"UTF-8 读失败 → 回退"这条路根本走不到，测试会绿着而 bug 还在。
# R 写不了 GBK，只能先 iconv 转、再把结果**当字节**写下去。
# 关键在 `Encoding(gbk) <- "latin1"`：iconv 返回的串在 R 里是按 UTF-8 记的，
# 直接 charToRaw 会把它重新编码回 UTF-8 —— 那就等于没转。
dsapp_write_gbk <- function(txt, path) {
  gbk <- iconv(enc2utf8(txt), "UTF-8", "GBK")
  if (is.na(gbk)) return(FALSE)
  # iconv 返回的串在 R 里仍然是"按字节看"的：用 charToRaw 之前先把它标成
  # latin1，这样 charToRaw 取到的就是 GBK 的原始字节，而不是被重新编码。
  Encoding(gbk) <- "latin1"
  con <- file(path, open = "wb")
  writeBin(charToRaw(gbk), con)
  close(con)
  TRUE
}
gbk_file <- file.path(tempdir(), "dsapp_gbk_probe.yaml")
has_gbk <- dsapp_write_gbk("name: 中文环境\n# 这是中文注释\npackages:\n  - numpy\n", gbk_file)
chk("（前置）造得出一份 GBK 文件", isTRUE(has_gbk))
if (isTRUE(has_gbk)) {
  g <- dsapp_read_text_file(gbk_file)
  chk("★★ GBK 文件读出来不是 NULL 且中文没错（UTF-8 失败会回退到 GBK）",
      !is.null(g) && grepl("这是中文注释", g),
      if (is.null(g)) "NULL" else g)
  chk("★★★ 读出来的确实是**有效的** UTF-8（不是「标记成 UTF-8 的乱码」）",
      !is.null(g) && !any(is.na(iconv(g, "UTF-8", "UTF-8"))),
      if (is.null(g)) "NULL" else "iconv 出 NA = 还是无效字节")
  # ★ 解析器得能把中文环境名读对 —— 名字读错了一键建会在最后一步被拒，
  #   而用户看到的是一份"看着没问题"的配置。
  chk("★★ GBK 的配置解析出来的环境名和注释都对",
      isTRUE(dsapp_envspec_parse(g)$ok) &&
      identical(dsapp_envspec_parse(g)$name, "中文环境"),
      dsapp_envspec_parse(g)$name)
  # 纯 ASCII：最常见的情况，不能被"回退"这条路弄坏
  ascii_file <- file.path(tempdir(), "dsapp_ascii_probe.yaml")
  writeLines(c("name: plain", "packages:", "  - numpy"), ascii_file)
  a <- dsapp_read_text_file(ascii_file)
  chk("★ 纯 ASCII 的文件照常读（回退分支不能被写成一读就歪）",
      !is.null(a) && grepl("numpy", a) && !grepl("�", a), a)
  # UTF-8 带中文：本机自己存的，走的是第一条路
  u8_file <- file.path(tempdir(), "dsapp_utf8_probe.yaml")
  writeLines(c("name: 中文", "# 注释", "packages:", "  - numpy"),
             u8_file, useBytes = FALSE)
  u <- dsapp_read_text_file(u8_file)
  chk("★ UTF-8 带中文的也照常读（回退分支不能抢在前面）",
      !is.null(u) && grepl("中文", u), u)
  chk("★ 文件不存在返回 NULL 而不是抛异常",
      is.null(dsapp_read_text_file(file.path(tempdir(), "dsapp_no_such_file"))))
}

