chk("⑦ ★★★ 删除确认框里不再写「文件不会被删除」，而且明说管理区一并删", {
  src <- paste(unlist(lapply(c("R/mod_admin.R", "R/mod_htadmin.R"), function(f)
    Filter(function(l) !grepl("^\\s*#", l), readLines(f, warn = FALSE)))),
    collapse = "\n")
  !grepl("文件不会被删除", src, fixed = TRUE) &&
    !grepl("变成「公共文件」", src, fixed = TRUE) &&
    grepl("也会一并删除", src, fixed = TRUE)
})

# ★★★ vapply 的 USE.NAMES 陷阱（V16.6 探针撞出来的老 bug，逐版回看到 V16.1
#     都是这个写法）。机理：vapply() 在 X 是 character 且结果还没名字时，会把
#     **X 的值本身**当成结果的名字。`users.last_seen_at` 是可空列、
#     `MAX(audit_log.at)`（last_act）对"一次都没动过"的账号是 NA —— 于是
#     「筛完只剩一行、那一行正好是 NULL」时 names() == NA_character_，
#     下游 data.frame() 抛 `row names contain missing values`，
#     整张 DT 表**直接消失**（htmlwidgets 的错误处理是 visibility:hidden，
#     旧 DOM 留着），而错误只进 data/logs/app_error.log。
#     ⚠️ 这正是「找出那个从没来过的号、把它删掉」这条最常用的路。
#
# 这一对断言是**两条一起才有劲**：前一条证明陷阱是真的（不带 USE.NAMES 必须
# 抛），后一条证明仓里的两处写法躲开了它。只留后一条的话，它就是个"源码里有没有
# 这几个字"的空转断言 —— 本仓栽过（变异不改变行为，探针全绿）。
chk("★★★ 这个陷阱是真的：同样的构造不带 USE.NAMES = FALSE 必须抛", {
  msg <- tryCatch({
    data.frame(x = vapply(NA_character_, dsapp_fmt_time, character(1)))
    ""
  }, error = function(e) conditionMessage(e))
  grepl("row names", msg, fixed = TRUE)
}, sprintf("报的是「%s」", tryCatch({
    data.frame(x = vapply(NA_character_, dsapp_fmt_time, character(1))); ""
  }, error = function(e) conditionMessage(e))))
# ⚠️ 匹配源码**一律 fixed = TRUE**（没转义的括号是空组，会静默走样），
#    而且先剥注释 —— 上面那段解释里就写着这几个字。
v166u_bad <- local({
  bad <- character(0)
  for (f in c("R/mod_htadmin.R", "R/mod_admin.R")) {
    src <- paste(Filter(function(l) !grepl("^\\s*#", l),
                        readLines(f, warn = FALSE)), collapse = "\n")
    for (pat in c("vapply(df$last_act, dsapp_fmt_time, character(1)",
                  "vapply(df$last_seen_at, dsapp_fmt_time, character(1)")) {
      from <- 1L
      repeat {
        p <- regexpr(pat, substring(src, from), fixed = TRUE)
        if (p < 0) break
        at <- from + as.integer(p) - 1L
        # 调用跨行，往后看 140 个字符够不够到 USE.NAMES
        if (!grepl("USE.NAMES = FALSE",
                   substr(src, at, at + 140L), fixed = TRUE)) {
          bad <- c(bad, sprintf("%s @%d", f, at))
        }
        from <- at + nchar(pat)
      }
    }
  }
  bad
})
chk("★★★ 两处 vapply 都带了 USE.NAMES = FALSE（漏一个 = 那张表整个消失）",
    length(v166u_bad) == 0L, paste(v166u_bad, collapse = " "))
chk("★★ 而且这两处**真的在仓里**（不然上面那条是在扫空气）", {
  src <- paste(unlist(lapply(c("R/mod_htadmin.R", "R/mod_admin.R"), function(f)
    Filter(function(l) !grepl("^\\s*#", l), readLines(f, warn = FALSE)))),
    collapse = "\n")
  grepl("vapply(df$last_act, dsapp_fmt_time, character(1)", src, fixed = TRUE) &&
    grepl("vapply(df$last_seen_at, dsapp_fmt_time, character(1)", src,
          fixed = TRUE)
})

invisible(dsapp_db(dsapp_config()))

# ⚠️ V13.2 起 **R/config.R 依赖 R/platform.R** —— dsapp_config() 里那行
#    `data_root <- dsapp_default_data_root(app_dir)$path` 调的函数住在
#    platform.R 里。
#
#    这是个「要么都加载、要么都别加载」的依赖，**不是顺序问题**：
#    dsapp_config() 是**运行时**才调用的，所以漏了 platform.R 的文件在
#    source 阶段一切正常（函数体不求值），等哪天真去算 data_root 才炸
#    「could not find function "dsapp_default_data_root"」。
#
#    app.R / deploy.sh / run_local.R 三份清单上面都查过了，都带了。
#    这里挡的是**第四种消费者**：测试脚本、运维小工具、以后新写的独立脚本
#    —— 它们不在那三份清单里，漏了没人管。tests/ui_v131/_common.py 就是
#    这么漏的（keys.py 2026-09-16 红了一次，才发现的）。
src_files <- list.files(".", recursive = TRUE, full.names = TRUE)
src_files <- sub("^\\./", "", src_files)
src_files <- src_files[grepl("\\.(R|r|py|sh|bat)$", src_files)]
src_files <- src_files[!grepl("^(history_Version|data|app_cache|DS_App_V1_python|\\.git|R)/",
                              src_files)]
cfg_re <- "source\\([\"']R/config\\.R[\"']\\)"
plt_re <- "source\\([\"']R/platform\\.R[\"']\\)"
hit_cfg <- character(0)
miss_plt <- character(0)
for (f in src_files) {
  txt <- tryCatch(paste(readLines(f, warn = FALSE), collapse = "\n"),
                  error = function(e) "")
  if (!grepl(cfg_re, txt)) next
  hit_cfg <- c(hit_cfg, f)
  if (!grepl(plt_re, txt)) miss_plt <- c(miss_plt, f)
}
chk("★ 找得到真的在 source R/config.R 的地方（不然下面那条是空转）",
    length(hit_cfg) >= 1)
chk("★★ 谁 source 了 R/config.R，就得同时 source R/platform.R（漏了是运行时才炸）", {
  if (length(miss_plt))
    cat("       漏了 platform.R：", paste(miss_plt, collapse = ", "), "\n")
  length(miss_plt) == 0
})

# =============================================================================
# V16.6 item 4：skills 纳入同步（用户原话：「skills、公告等有必要的功能，
#               都需要通过跳板来同步」）
# =============================================================================
#
#     「公告」不用做 —— 它是论坛的一个分类（R/forum.R 里那个
#     `list(value="notice", ...)`），数据就是 forum_threads/forum_posts，
#     V15 item 8 起已经在同步范围内了。**只剩 skills。**
#
# ---- 这一节真正要钉的是什么 ------------------------------------------------
#
# ★★★ **技能段不在 `.dsapp_sync_sig_payload` 里**，它有自己的签名。
#     这是整件事的兼容性核心：载荷的**顶层键集**一旦变了，已经发出去的老
#     客户端和新服务器之间**双向都验不过**（V15 那次往顶层加 `forum`，
#     V15↔V14 就是互死的，R/synckey.R:300 附近记着这个教训）。所以技能段
#     走的是和 `sig_ed` / `claim` 同一条路：**新的顶层键 + 自己的签名**。
#     下面第一条断言把键集**写死**在这里比 —— 不引用代码里的任何常量，
#     否则"代码改了、断言跟着改"就永远绿。
#
# ★★★ **附件是 BLOB**，而 BLOB 参数在 RSQLite 里必须写成 `list(raw)`。
#     裸 raw 进 `dbExecute` 报 `Parameter N does not have length 1`，被
#     `try(silent = TRUE)` 吞掉之后的表现是：「函数返回 2、表里 0 行」——
#     一个纯绿的假象。所以这里**必须量 `length(content)`**，只量行数的话
#     `stored = 0`（只登记不存内容）那种也能凑够行数。
#
# ★★ **技能墓碑不跟会话共用一条水位**。混在一起的话，会话推得快会把
#     `req_from_del` 一起顶上去，老的技能墓碑再也发不出去 —— 表现是
#     「删了技能，同步一下它又回来了」。
#
# ⚠️ 这一节用的是**自检自己那个临时数据根**（selftest 开头设的），不另起
#    一个：跨库那条路（真的两台机器）已经由 V16.6 item 1 那一节和两进程的
#    冒烟跑过，这里要钉的是**不变量**，同一个库上就能做完，少一层环境切换
#    就少一类"红得和真正的原因隔了十万八千里"的故障。
section("V16.6 item 4：skills 纳入同步（技能段 + 附件 BLOB + 独立水位）")
{
  v166s_con <- function() dsapp_db(dsapp_config())

  # ---- (a) 段的位置：在**冻结载荷之外** ----------------------------------
  # 期望值写死。改了载荷就要**明知故犯地**改这一行，而不是顺其自然。
  v166s_frozen <- c("v", "node", "sent_at", "user", "req_from", "req_from_del",
                    "req_from_forum", "data")
  v166s_pay <- .dsapp_sync_sig_payload(list())
  chk("★★★ 签名载荷的顶层键集与 V16.5 逐字相同（动它就是和老客户端互死）",
      identical(names(v166s_pay), v166s_frozen),
      sprintf("实际 %s", paste(names(v166s_pay), collapse = ",")))
  chk("★★★ 载荷 data 段的键集也逐字相同（skills **不在**里面）",
      identical(names(v166s_pay$data),
                c("sessions", "messages", "tombstones", "forum")),
      sprintf("实际 %s", paste(names(v166s_pay$data), collapse = ",")))
  v166s_sy <- paste(readLines("R/sync.R", warn = FALSE), collapse = "\n")
  v166s_sk <- paste(readLines("R/skills.R", warn = FALSE), collapse = "\n")
  chk("★★★ 技能段自带一个载荷函数，且只覆盖 skills 一个键（含上 skills_sig 就是签名盖住自己）",
      grepl(".dsapp_sync_skills_payload <- function", v166s_sk, fixed = TRUE) &&
        grepl("skills  = b[[\"skills\"]]", v166s_sk, fixed = TRUE))
  chk("★★★ 收端只在包**真的带了技能段**时才验那一段（老包没有段，不能被拦）",
      grepl('!is.null(b[["skills"]])', v166s_sy, fixed = TRUE))
  chk("★★ 两个签名键分开取名（发送端不知道收端能验哪一种）",
      grepl("b$skills_sig <- ss", v166s_sy, fixed = TRUE) &&
        grepl("b$skills_sig_ed <- ss_ed", v166s_sy, fixed = TRUE))

  # ---- (b) 段签名覆盖每一个字段（逐字段篡改）----------------------------
  # ⚠️ 逐字段而不是只挑一个：恰好挑到"签名本来就盖着的那个"就会全绿，
  #    claim 那边第一版正是这么漏的（签名算的是一份常量）。
  v166s_key <- "selftest-skills-key"
  v166s_mk <- function() {
    list(v = 2L, node = "n1", sent_at = "2026-10-05T00:00:00",
         user = list(email = "s@b.com"),
         skills = list(req_from = "", req_from_del = "",
                       items = list(list(origin_node = "peerA", origin_id = "7",
                                         name = "规范", summary = "s", body = "b",
                                         tags = "t", scope = "private",
                                         created_at = "2026-10-05 00:00:00",
                                         updated_at = "2026-10-05 00:00:00",
                                         files = list(list(path = "a.txt",
                                                           stored = 1L)))),
                       links = list(list(session_node = "peerA", session_id = "s1",
                                         skill_node = "peerA", skill_id = "7")),
                       dels = list(list(kind = "skill", node = "peerA", id = "7",
                                        at = "2026-10-05 00:00:00")),
                       high_water = "2026-10-05 00:00:00",
                       high_water_del = "2026-10-05 00:00:00"))
  }
  v166s_g <- v166s_mk()
  v166s_g$skills_sig <- dsapp_sync_skills_sign(v166s_g, v166s_key)
  chk("★★★ 正本验得过", dsapp_sync_skills_verify(v166s_g, v166s_key))
  for (fld in c("req_from", "req_from_del", "items", "links", "dels",
                "high_water", "high_water_del")) {
    bad <- v166s_g; bad$skills[[fld]] <- "TAMPERED"
    chk(sprintf("★★ 改 skills$%s 必须验不过", fld),
        !dsapp_sync_skills_verify(bad, v166s_key))
  }
  chk("★★ 改技能正文必须验不过", {
    bad <- v166s_g; bad$skills$items[[1]]$body <- "换掉"
    !dsapp_sync_skills_verify(bad, v166s_key)
  })
  chk("★★ 改附件路径必须验不过（不然能往用户盘上写任意文件名）", {
    bad <- v166s_g; bad$skills$items[[1]]$files[[1]]$path <- "hack.sh"
    !dsapp_sync_skills_verify(bad, v166s_key)
  })
  chk("★★ 改挂载关系必须验不过", {
    bad <- v166s_g; bad$skills$links[[1]]$skill_id <- "8"
    !dsapp_sync_skills_verify(bad, v166s_key)
  })
  chk("★★ 改墓碑必须验不过", {
    bad <- v166s_g; bad$skills$dels[[1]]$id <- "9"
    !dsapp_sync_skills_verify(bad, v166s_key)
  })
  chk("★ 段里多一个字段也验不过（宽松的话塞东西就没人管）", {
    bad <- v166s_g; bad$skills$extra <- "x"
    !dsapp_sync_skills_verify(bad, v166s_key)
  })
  chk("★ 换一条密钥必须验不过",
      !dsapp_sync_skills_verify(v166s_g, "another-key"))
  chk("★★ 有签名、却没有段 → 拒（这是「段被人删了」的形状，不是「老包」）", {
    # ⚠️ 这两件事要分开：**老包**是连 skills_sig 都没有（上面那条
    #    `!is.null(b[["skills"]])` 放行）；**有签名没段**是被人动过。
    bad <- v166s_g[names(v166s_g) != "skills"]
    !dsapp_sync_skills_verify(bad, v166s_key)
  })
  chk("★ 空段（三样都空）验得过 —— 空集合也是合法的段", {
    e <- v166s_mk()
    e$skills$items <- list(); e$skills$links <- list(); e$skills$dels <- list()
    e$skills_sig <- dsapp_sync_skills_sign(e, v166s_key)
    isTRUE(dsapp_sync_skills_verify(e, v166s_key))
  })
  # Ed25519 那条路（收端认不出 HMAC 密钥时用账号公钥验）
  v166s_ident <- dsapp_sync_identity_ensure(dsapp_config())
  v166s_ged <- v166s_mk()
  v166s_ged$skills_sig_ed <- dsapp_sync_skills_sign_ed(v166s_ged, v166s_ident$seed)
  chk("★★ 只给公钥、不给 HMAC 密钥，也验得过",
      isTRUE(dsapp_sync_skills_verify(v166s_ged, "", v166s_ident$pub)))
  chk("★★ 换一把公钥验不过",
      !dsapp_sync_skills_verify(v166s_ged, "", strrep("0", 64)))
  chk("★★ Ed25519 这条路也盖着正文", {
    bad <- v166s_ged; bad$skills$items[[1]]$body <- "改"
    !dsapp_sync_skills_verify(bad, "", v166s_ident$pub)
  })

  # ---- (c) 附件：BLOB 真的落库 -----------------------------------------
  v166s_u <- dsapp_user_create("技能同步用户", "v166skills@example.com",
                               "13900002222", "生信", "pw123456", "pw123456",
                               con = v166s_con())
  chk("★ 造一个账号", isTRUE(v166s_u$ok), v166s_u$msg %||% "")
  v166s_uid <- as.integer(v166s_u$user$id)
  v166s_sk1 <- dsapp_skill_save(user_id = v166s_uid, name = "规范甲",
                                summary = "s", body = "b", tags = "t",
                                con = v166s_con())
  v166s_sid <- as.integer(v166s_sk1$id)
  v166s_F1 <- list(
    list(path = "t/a.txt", kind = "text", bytes = 16L, stored = 1L,
         content = jsonlite::base64_enc(charToRaw("hello skill file")),
         created_at = "2026-10-05 00:00:00"),
    list(path = "t/b.bin", kind = "binary", bytes = 6L, stored = 1L,
         content = jsonlite::base64_enc(as.raw(c(0, 1, 2, 255, 0, 65))),
         created_at = "2026-10-05 00:00:00"))
  v166s_n <- dsapp_skills_files_apply(v166s_sid, v166s_F1, con = v166s_con())
  chk("★★★ 返回值是**真写进去的条数**（不是 length(files)）",
      identical(as.integer(v166s_n), 2L), sprintf("返回 %s", v166s_n))
  chk("★★★ 两行都在表里",
      nrow(dsapp_skill_files_list(v166s_sid, con = v166s_con())) == 2L)
  chk("★★★ 正文真的落库了（BLOB 参数绑定的判据；裸 raw 会静默变成 0 行）", {
    q <- DBI::dbGetQuery(v166s_con(),
      "SELECT path, length(content) AS clen FROM skill_files
        WHERE skill_id = ? ORDER BY path", params = list(v166s_sid))
    identical(as.integer(q$clen), c(16L, 6L))
  }, "两张附件的 content 字节数（期望 16 与 6）")
  chk("★★ 二进制内容逐字节相同", {
    g <- dsapp_skill_file_get(v166s_sid, "t/b.bin", con = v166s_con())
    identical(as.integer(g$raw %||% g[[1]]), c(0L, 1L, 2L, 255L, 0L, 65L))
  })
  dsapp_skills_files_apply(v166s_sid, v166s_F1[1], con = v166s_con())
  chk("★★ 整份替换：对端删掉的文件本地也删（不做差集就是永远留着）",
      identical(sort(as.character(
        dsapp_skill_files_list(v166s_sid, con = v166s_con())$path)), "t/a.txt"))
  dsapp_skills_files_apply(v166s_sid, list(
    list(path = "t/a.txt", kind = "text", bytes = 99999L, stored = 0L,
         created_at = "2026-10-05 00:00:00")), con = v166s_con())
  chk("★★★ stored=0 不抹掉本地已有的内容（抹了就是「同步一次附件就没了」）", {
    q <- DBI::dbGetQuery(v166s_con(),
      "SELECT length(content) AS clen FROM skill_files
        WHERE skill_id = ? AND path = 't/a.txt'", params = list(v166s_sid))
    nrow(q) == 1L && identical(as.integer(q$clen), 16L)
  }, "t/a.txt 的 content 字节数")

  # ---- (d) 段的应用 ------------------------------------------------------
  v166s_peer <- "peer-aaaa"
  v166s_sec <- list(req_from = "", req_from_del = "",
                    items = list(list(origin_node = v166s_peer, origin_id = "501",
                                      name = "同步来的规范", summary = "s2",
                                      body = "b2", tags = "t2", scope = "private",
                                      source = "manual",
                                      created_at = "2026-10-05 00:00:00",
                                      updated_at = "2026-10-05 00:00:00",
                                      files = v166s_F1[1])),
                    links = list(), dels = list(),
                    high_water = "2026-10-05 00:00:00", high_water_del = "")
  v166s_r <- dsapp_skills_apply(v166s_sec, v166s_peer, v166s_uid,
                                cfg = dsapp_config(), con = v166s_con())
  chk("★ 应用了一条技能", identical(as.integer(v166s_r$n), 1L),
      sprintf("n=%s skipped=%s", v166s_r$n, v166s_r$skipped))
  v166s_q <- DBI::dbGetQuery(v166s_con(),
    "SELECT id, user_id, builtin FROM skills WHERE name = '同步来的规范'")
  chk("★★ 落库、挂在对的用户名下、**不是内置**（同步过来的永远不是内置）",
      nrow(v166s_q) == 1L &&
        identical(as.integer(v166s_q$user_id), v166s_uid) &&
        identical(as.integer(v166s_q$builtin), 0L))
  chk("★★ 同步过来的技能**带上了附件**（BLOB 没修之前这条是红的）",
      nrow(dsapp_skill_files_list(as.integer(v166s_q$id), con = v166s_con())) == 1L)
  chk("★★ 身份是 (出身节点, 出身 id)，不是本地 id", {
    m <- DBI::dbGetQuery(v166s_con(),
      "SELECT local_id FROM sync_map
        WHERE peer = ? AND kind = 'skill' AND origin = '501'",
      params = list(v166s_peer))
    nrow(m) == 1L && identical(as.character(m$local_id), as.character(v166s_q$id))
  })
  chk("★★ 对端改了正文（updated_at 更新）→ 就地更新，不新建第二条", {
    s2 <- v166s_sec
    s2$items[[1]]$body <- "b2-改过"
    s2$items[[1]]$updated_at <- "2026-10-06 00:00:00"
    r2 <- dsapp_skills_apply(s2, v166s_peer, v166s_uid,
                             cfg = dsapp_config(), con = v166s_con())
    q2 <- DBI::dbGetQuery(v166s_con(),
      "SELECT COUNT(*) AS n, MAX(body) AS b FROM skills WHERE name = '同步来的规范'")
    identical(as.integer(q2$n), 1L) && identical(as.integer(r2$n), 1L) &&
      identical(as.character(q2$b), "b2-改过")
  })
  chk("★★ 同一个 updated_at 再应用一次 = 跳过（LWW 幂等，不重复写、也不报错）", {
    r3 <- dsapp_skills_apply(v166s_sec, v166s_peer, v166s_uid,
                             cfg = dsapp_config(), con = v166s_con())
    n <- DBI::dbGetQuery(v166s_con(),
      "SELECT COUNT(*) AS n FROM skills WHERE name = '同步来的规范'")$n[1]
    identical(as.integer(n), 1L) && identical(as.integer(r3$n), 0L)
  })
  chk("★ 水位如实回传（对端拿它当下一次的 since）",
      identical(as.character(v166s_r$high), "2026-10-05 00:00:00") &&
        identical(as.character(v166s_r$high_del), ""))
  chk("★★ 挂载关系：会话侧映射不在 → 跳过，不插一条指向空的行",
      identical(as.integer(dsapp_skills_links_apply(
        list(list(session_node = v166s_peer, session_id = "no-such",
                  skill_node = v166s_peer, skill_id = "501")),
        con = v166s_con())), 0L))
  chk("★★ 挂载关系：两个映射都在 → 建出 session_skills 行", {
    # ⚠️ db_session_create 回的是**裸的会话 id 字符串**，不是 list ——
    #    写 `sess$id` 会炸 "operator is invalid for atomic vectors"。
    sid2 <- as.character(db_session_create("技能挂载会话", v166s_uid,
                                           con = v166s_con()))
    .dsapp_sync_map_put(v166s_peer, "session", "s-777", sid2, con = v166s_con())
    r4 <- dsapp_skills_links_apply(
      list(list(session_node = v166s_peer, session_id = "s-777",
                skill_node = v166s_peer, skill_id = "501")), con = v166s_con())
    n <- DBI::dbGetQuery(v166s_con(),
      "SELECT COUNT(*) AS n FROM session_skills WHERE session_id = ? AND skill_id = ?",
      params = list(sid2, as.integer(v166s_q$id)))$n[1]
    identical(as.integer(r4), 1L) && identical(as.integer(n), 1L)
  })

  # ---- (e) 墓碑 ----------------------------------------------------------
  v166s_lid <- as.integer(v166s_q$id)
  # ⚠️⚠️ 量的是**这一次应用有没有新增**，不是"表里有没有"。
  #    自检跑到这里时，前面几节（V13.x 讲技能权限那一节）早就调过
  #    `dsapp_skill_delete`，而它现在会**正确地**记一条技能墓碑 —— 表里本来
  #    就躺着几条。写成 `COUNT(*) == 0` 的话，红/绿取决于**节的先后顺序**，
  #    和被测的行为没有半点关系（第一版就是这么红的：报告说"删技能记了
  #    墓碑"，而真正的问题是"表里本来就有别人的"）。
  #    "应用对端墓碑**不该**新增本地墓碑"才是这条要钉的东西。
  v166s_tb0 <- DBI::dbGetQuery(v166s_con(),
    "SELECT COUNT(*) AS n FROM sync_tombstone WHERE kind = 'skill'")$n[1]
  dsapp_skills_tombstones_apply(
    list(list(kind = "skill", node = v166s_peer, id = "501",
              at = "2026-10-06 00:00:00")), v166s_peer, "", con = v166s_con())
  chk("★★ 应用对端墓碑 = 本地删掉", {
    n <- DBI::dbGetQuery(v166s_con(), "SELECT COUNT(*) AS n FROM skills WHERE id = ?",
                         params = list(v166s_lid))$n[1]
    identical(as.integer(n), 0L)
  })
  chk("★★★ 但**不记**本地墓碑（记了就是两台机器之间来回弹，停不下来）", {
    n <- DBI::dbGetQuery(v166s_con(),
      "SELECT COUNT(*) AS n FROM sync_tombstone WHERE kind = 'skill'")$n[1]
    identical(as.integer(n), as.integer(v166s_tb0))
  }, sprintf("应用前 %s 条、应用后 %s 条（期望相等）", v166s_tb0,
             DBI::dbGetQuery(v166s_con(),
               "SELECT COUNT(*) AS n FROM sync_tombstone WHERE kind='skill'")$n[1]))
  chk("★ 墓碑把附件一起带走（不留孤儿 BLOB 吃盘）",
      DBI::dbGetQuery(v166s_con(),
        "SELECT COUNT(*) AS n FROM skill_files WHERE skill_id = ?",
        params = list(v166s_lid))$n[1] == 0L)
  chk("★★ 清掉之后 sync_map 里的映射也跟着没了（留着就是指一条不存在的行）",
      DBI::dbGetQuery(v166s_con(),
        "SELECT COUNT(*) AS n FROM sync_map WHERE kind = 'skill'")$n[1] == 0L)

  # ---- (f) 本地删除 → 墓碑能发出去，且水位不跟会话共用 -------------------
  v166s_sk3 <- dsapp_skill_save(user_id = v166s_uid, name = "本地建的",
                                summary = "s", body = "b", tags = "t",
                                con = v166s_con())
  v166s_sid3 <- as.integer(v166s_sk3$id)
  invisible(dsapp_skill_delete(v166s_sid3, v166s_uid, con = v166s_con()))
  chk("★★★ 本地删技能**要**记一条墓碑（不记的话对端永远删不掉）", {
    # ⚠️ 墓碑的**身份列是 `origin`**，不是 `id` —— `id` 是这张表自己的
    #    AUTOINCREMENT 主键。写成 `id = ?` 查的是"主键等于技能 id 的那一行"，
    #    永远查不到，症状是"删了技能没记墓碑"（一条假红）。
    n <- DBI::dbGetQuery(v166s_con(),
      "SELECT COUNT(*) AS n FROM sync_tombstone
        WHERE kind = 'skill' AND origin = ?",
      params = list(as.character(v166s_sid3)))$n[1]
    identical(as.integer(n), 1L)
  })
  chk("★★★ 技能墓碑能被单独采出来，出身节点是**我自己**（对端据此回查 sync_map）", {
    tsk <- .dsapp_sync_collect_tombstones("", con = v166s_con(), kinds = "skill")
    mine <- tryCatch(dsapp_sync_node_id(dsapp_config()), error = function(e) "")
    it <- Filter(function(i) identical(as.character(i$id), as.character(v166s_sid3)),
                 tsk$items)
    length(it) == 1L && identical(as.character(it[[1]]$kind), "skill") &&
      nzchar(mine) && identical(as.character(it[[1]]$node), mine)
  })
  chk("★★★ 会话那条水位捞不到技能墓碑（共用的话会话一推，技能墓碑永远发不出去）", {
    ses <- .dsapp_sync_collect_tombstones("", con = v166s_con())
    !any(vapply(ses$items, function(i) identical(as.character(i$kind), "skill"),
                logical(1)))
  })
  chk("★★ 技能墓碑的默认 kinds 是 session（不写就是原来的行为，老调用点一个字不用改）",
      length(.dsapp_sync_collect_tombstones("", con = v166s_con())$items) ==
        length(.dsapp_sync_collect_tombstones("", con = v166s_con(),
                                              kinds = "session")$items))

  # ---- (g) 采集：只收自己的、内置的不收 ---------------------------------
  dsapp_skills_files_apply(v166s_sid, list(
    list(path = "t/a.txt", kind = "text", bytes = 16L, stored = 1L,
         content = jsonlite::base64_enc(charToRaw("hello skill file")),
         created_at = "2026-10-05 00:00:00")), con = v166s_con())
  v166s_col <- dsapp_skills_collect(since_at = "", since_del = "",
                                    user_id = v166s_uid, cfg = dsapp_config(),
                                    con = v166s_con())
  chk("★ 采到的是自己的那一条", length(v166s_col$items) == 1L,
      sprintf("%d 条", length(v166s_col$items)))
  chk("★★★ 内置技能一条都没进来（内置是每台机器自己种的，跟着同步会两份）",
      !any(vapply(v166s_col$items,
                  function(i) isTRUE(i$builtin), logical(1))))
  chk("★★ 采集带上了附件正文（stored=1 的那种）", {
    f <- v166s_col$items[[1]]$files
    length(f) >= 1L &&
      any(vapply(f, function(x) isTRUE(as.integer(x$stored) == 1L), logical(1)))
  })
  chk("★★ since 推到未来 → 一条都不采（水位真的在过滤，不是装饰）", {
    c2 <- dsapp_skills_collect(since_at = "2099-01-01 00:00:00",
                               since_del = "2099-01-01 00:00:00",
                               user_id = v166s_uid, cfg = dsapp_config(),
                               con = v166s_con())
    length(c2$items) == 0L && length(c2$dels) == 0L
  })
  # ⚠️ 段的三个子键在**空状态**下也要在（少了的话对端读 `sec[["links"]]`
  #    拿到 NULL，链式 for 循环跑不起来 —— 和 in_skills 那两条同性质）。
  chk("★ 空段也有 items / links / dels 三个子键",
      all(c("items", "links", "dels") %in%
            names(dsapp_skills_collect(since_at = "2099-01-01 00:00:00",
                                       since_del = "2099-01-01 00:00:00",
                                       user_id = v166s_uid, cfg = dsapp_config(),
                                       con = v166s_con()))))
  chk("★★ sync_state 多了 in_skills / out_skills / in_del_skills / out_del_skills 四列",
      all(c("in_skills", "out_skills", "in_del_skills", "out_del_skills") %in%
            names(dsapp_sync_state_get("no-such-peer", con = v166s_con()))))
}


# =============================================================================
# V13.4 item 6：任务导航栏能拖着改宽
# =============================================================================
# 「言出法随界面的任务导航栏需要支持拖动改变大小」。
#
# ★ 这一条的全部风险都在**四份东西必须互相对得上**：
#
#     R/uiprefs.R 的 DSAPP_UIPREF_SPECS$sess_w   ← 存库、发变量
#     www/app.js   的 SPEC.sess_w                ← 拖动时现算边界
#     www/codex.css 的 var(--dsapp-sess-w, ...)  ← 真正决定栏宽
#     R/mod_chat.R  的 sidebar(width = 260)      ← 页面刚渲染、变量还没到时用它
#
#   它们分居四个文件、**没有一个共同的来源**，任何一处动了另外三处不动，
#   浏览器都不报错 —— 表现只是"拖起来怪怪的"或者"拖了没反应"。所以这里
#   逐个钉住。R 里的默认值就是上面那条 ups_int 断言里的 260L，这里查另外三处。
# =============================================================================

v134_chat <- paste(readLines("R/mod_chat.R", warn = FALSE), collapse = "\n")
v134_js   <- paste(readLines("www/app.js",   warn = FALSE), collapse = "\n")
v134_css  <- paste(readLines("www/codex.css", warn = FALSE), collapse = "\n")
v134_up   <- paste(readLines("R/uiprefs.R",  warn = FALSE), collapse = "\n")

# ⚠️ 匹配 mod_chat.R 那条要允许换行：那边写的是
#      sidebar = sidebar(
#        width = 260,
#    写成 `sidebar(width = 260` 这种连着的字面量是**匹配不上**的
#    （2026-09-16 试运行当场红在这里）。
v134_has_sb_w <- grepl("sidebar\\(\\s*width\\s*=\\s*260\\b", v134_chat)
chk("★ 导航栏的默认宽度四份拷贝一致（对不上的表现：没调过的人看到一个宽度，随手一拖又跳到另一个）",
    identical(DSAPP_UIPREF_SPECS$sess_w$def, 260L) &&
      v134_has_sb_w &&
      grepl("sess_w:     { def: 260,", v134_js, fixed = TRUE) &&
      grepl("var(--dsapp-sess-w, 260px)", v134_css, fixed = TRUE),
    sprintf("R=%s chat=%s js=%s css=%s",
            DSAPP_UIPREF_SPECS$sess_w$def, v134_has_sb_w,
            grepl("sess_w:     { def: 260,", v134_js, fixed = TRUE),
            grepl("var(--dsapp-sess-w, 260px)", v134_css, fixed = TRUE)))

chk("★ 边界两份拷贝一致（app.js 那份是拖动时现用的，对不上就是「拖到边界松手跳一格」）",
    grepl(sprintf("sess_w:     { def: 260, min: %d, max: %d }",
                  DSAPP_UIPREF_SPECS$sess_w$min, DSAPP_UIPREF_SPECS$sess_w$max),
          v134_js, fixed = TRUE),
    sprintf("R: min=%d max=%d", DSAPP_UIPREF_SPECS$sess_w$min,
            DSAPP_UIPREF_SPECS$sess_w$max))

# ★★ 这条是整件事的**技术核心**。bslib 把宽度写成行内样式，而它写的是
#    **私有变量 `--_sidebar-width`**（2026-09-16 拿 bslib 0.9.0 实际渲染的
#    HTML 对过：`style="--_sidebar-width:260px;"`）。所以：
#      · 样式表里写 `--bslib-sidebar-width` → 完全不生效（那只是那句
#        `var(--bslib-sidebar-width, 250px)` 的 fallback，而行内样式已经把
#        `--_sidebar-width` 定死了）；
#      · 样式表里写 `width` → 更不生效（列宽是 grid-template-columns 算的）；
#      · 唯一能赢的是 `!important` 的作者声明盖过行内声明。
#    这三句里任何一句写错，规则都**静默失效** —— 拖了没反应，控制台一个错
#    都没有，而这正是最难查的那种。
chk("★★ 栏宽那条规则用的是 --_sidebar-width + !important（少了任何一个都是条永远不生效的规则）",
    grepl("--_sidebar-width: var(--dsapp-sess-w, 260px) !important", v134_css,
          fixed = TRUE), "见 codex.css 的 .dsapp-main-body .bslib-sidebar-layout")
# ⚠️ 下面这条得**先把 CSS 注释去掉**再找。不去的话，codex.css 里那段解释
#    「为什么不能用 --bslib-sidebar-width」的文字本身就会命中 —— 一条因为
#    **注释里写了反面教材**而永远为红的断言（2026-09-16 试运行当场红在这）。
#    ⚠️ 正则要带 `(?s)`：CSS 注释是**跨行**的，而 `.` 默认不匹配换行 ——
#       只写 `.*?` 的话多行注释原封不动地留在那儿，等于没去。
v134_css_nc <- gsub("(?s)/\\*.*?\\*/", "", v134_css, perl = TRUE)
v134_n_hit  <- sum(gregexpr("--bslib-sidebar-width:", v134_css_nc, fixed = TRUE)[[1]] > 0)
chk("★ 没有真的去写 --bslib-sidebar-width（行内样式盖着，写了也没用）",
    v134_n_hit == 0, sprintf("去掉注释后还剩 %d 处", v134_n_hit))

# ★ 结构性断言：直接**渲染一次** UI，看那条把手长在哪儿。
#   ⚠️ 断言"它存在"是不够的 —— 放进 sidebar 里它也一样存在，但会被
#      `overflow: auto` 裁掉一半、剩下的一半压在列表滚动条上。
v134_ui  <- mod_chat_ui("v134")
v134_kid <- vapply(v134_ui$children,
                   function(ch) if (is.list(ch))
                     as.character(ch$attribs$class %||% NA_character_) else NA_character_,
                   "")
chk("★★ 分隔条是 .bslib-sidebar-layout 的**直接子元素**（放进 sidebar 里会被 overflow:auto 裁掉）",
    identical(v134_ui$name, "div") &&
      grepl("bslib-sidebar-layout", v134_ui$attribs$class, fixed = TRUE) &&
      sum(v134_kid == "dsapp-sess-handle", na.rm = TRUE) == 1L,
    paste(v134_kid, collapse = " | "))

v134_html <- as.character(v134_ui)
chk("★★ 分隔条上带着 data-dsapp-panel=\"sess_w\"（没有它 app.js 会去改文件区的宽度）",
    grepl('data-dsapp-panel="sess_w"', v134_html, fixed = TRUE) &&
      grepl('id="v134-split_s"', v134_html, fixed = TRUE), v134_html)
# ⚠️ 用"在 </aside> 之后"来判，不按下标取 children[[2]]：sidebar 那一个是
#    个 tagList（不是单个 tag），下标会随 bslib 版本变。
v134_aside <- regexpr("</aside>", v134_html, fixed = TRUE)[1]
v134_where <- regexpr("dsapp-sess-handle", v134_html, fixed = TRUE)[1]
chk("★ 分隔条长在 sidebar **外面**（在里面会被 overflow:auto 裁掉，只剩半条能点）",
    v134_aside > 0 && v134_where > v134_aside,
    sprintf("</aside> 在 %d，分隔条在 %d", v134_aside, v134_where))

# ★ report() 靠 id 的形状算出发给服务端的 input 名。正则里少一个 s 的
#   表现：拖导航栏松手**什么都不上报**（宽度当场是对的，一刷新就回去）——
#   而 id 不匹配时那句 `if (inputId === el.id) return;` 是**静默**返回的。
# ⚠️★ V13.5：这一条原来写死了 `split_[vhs]`，V13.5 item 2/8 加进来
#    tasks_w（t）和 menu_w（m）两个把手之后就红了 —— 红的是那串字符集，
#    不是代码。现在改成"字符集必须覆盖**当前用到的每一个**后缀"：从 R 那边
#    的 SPEC（app.js 里那张表）里把用到的 which 全取出来，逐个要求正则认。
#    这样以后再加面板，忘了改这里会红，而"只是多了一个字母"不会误报。
v135_suffix <- c(sess_w = "s", menu_w = "m", tasks_w = "t",
                 files_w = "v", composer_h = "h", filespage_w = "f")
# ⚠️ 这里**不能**去 grep `split_s"` 这种字面量：那五个字母只在字符集里出现过
#    一次（`/split_[vhstm]$/`），逐字母拼出来的字面量在源码里根本不存在 ——
#    写错的表现是"每条都为假"，于是红了看起来像代码坏了，其实是断言写错了。
#    改成"把字符集本身抠出来，要求它覆盖每一个用到的面板"。
v135_cls <- regmatches(v134_js,
  regexpr("replace\\(/split_\\[[^]]*\\]\\$/, \"panel_size\"\\)", v134_js,
          perl = TRUE))
v135_cls <- sub("^.*\\[([^]]*)\\]\\$.*$", "\\1", v135_cls)
chk("★★ app.js 上报时认得出每一个把手（不认的表现：拖完刷新打回原形，控制台无错）",
    nzchar(v135_cls) &&
      all(vapply(v135_suffix, function(s)
        s %in% strsplit(v135_cls, "", fixed = TRUE)[[1]], logical(1))),
    sprintf("字符集 = [%s]；需要的后缀 = %s", v135_cls,
            paste(unname(v135_suffix), collapse = "")))

# ★ 方向。★ 把手**左边**的那三栏，往右拖是变宽 —— 和右边那条文件区**相反**。
#   照抄文件区的话拖起来是反的，而代码上看不出任何异常。
#
# ⚠️★ 这里**不能**只 grep 一行字面量：dragDelta 现在是按组判的
#   （`which === "sess_w" || which === "menu_w" || which === "tasks_w"`），
#    V13.5 item 2 加 tasks_w 时正是这个形状。所以改成"把那个函数体抠出来，
#    逐个面板验它的**符号**"——顺手也就把"新加的面板漏进哪一组"钉住了。
# ⚠️ 这里**不能**用 dsapp_pull()：它是按 R 源的缩进（收尾那行 4 个空格 +
#    `}` 或 `)`）写的，而 app.js 里这两个函数的收尾是 2 个空格（函数）和
#    `  });`（事件处理器），一个都匹配不上 —— 匹配不上的表现是**抠到空串**，
#    于是下面每一条 grepl 都为假，红了还看不出是"抠错了"还是"代码错了"。
#    所以这里自己按"到第一个行首两个空格的收尾"截。
#'
#' @param must 可选。app.js 里有**三段** `document.addEventListener("keydown"`
#'   （输入框回车发送、分隔条方向键、别处一段），只按起点找会抠到**第一段**
#'   —— 抠错了的表现是"前置断言说没抠到"，而真正想验的那段根本没被看过。
#'   给了 must 就在每一段里找第一个满足它的，找不到才返回空串。
v135_slice <- function(src, start_pat, end_pat, must = NULL) {
  from <- 1L
  repeat {
    at <- regexpr(start_pat, substring(src, from), perl = TRUE)[1]
    if (at < 0) return("")
    at   <- from + at - 1L
    rest <- substring(src, at)
    # ⚠️ end_pat 里**要自己带行首缩进**。原来这里写死了 `\n  %s`（两个空格），
    #    只对"缩进两格的收尾"管用；document 上挂的事件处理器收尾是**顶格**的
    #    `});`，配不上就一路啃到下一段注释里去 —— 抠出来的片段里混进了别的
    #    代码，于是 `!grepl("selectRows", ...)` 这种**否定式**断言会莫名其妙
    #    地红（那片注释里正好提了一句 selectRows）。
    m    <- regexpr(sprintf("(?s)^.*?\\n%s", end_pat), rest, perl = TRUE)
    if (m[1] < 0) return("")
    out <- regmatches(rest, m)
    if (is.null(must) || grepl(must, out, perl = TRUE)) return(out)
    from <- at + 1L
  }
}
v135_delta <- v135_slice(v134_js, "function dragDelta\\(which, e\\) \\{", "  \\}")
chk("（前置）抠到了 dragDelta 的函数体", nzchar(v135_delta) && nchar(v135_delta) < 900,
    substr(v135_delta, 1, 200))
v135_left <- c("sess_w", "menu_w", "tasks_w", "filespage_w")  # 把手左边的：往右 = 变宽
chk("★★ 左边那几栏的拖动方向是「往右 = 变宽」（和对话页产物栏相反）",
    all(vapply(v135_left, function(w)
      grepl(sprintf('which === "%s"', w), v135_delta, fixed = TRUE), logical(1))) &&
      grepl("return e.clientX - drag.x;", v135_delta, fixed = TRUE),
    v135_delta)
chk("★★ 右边那栏（对话页产物栏）和输入区没有被顺手写成同一组",
    grepl("return drag.x - e.clientX;", v135_delta, fixed = TRUE) &&
      grepl("return drag.y - e.clientY;", v135_delta, fixed = TRUE) &&
      !grepl('which === "files_w"', v135_delta, fixed = TRUE),
    v135_delta)

# ★ 方向键是**第二份**符号表（和 dragDelta 分开写的）。V13.5 item 2 加
#   tasks_w 时漏了它，症状是"鼠标拖是对的、Tab 过去按方向键是反的"。
v135_key <- v135_slice(v134_js, "document.addEventListener\\(\"keydown\"",
                       "  \\}\\);", must = "c\\.which")
chk("（前置）抠到了键盘那段", nzchar(v135_key) && nchar(v135_key) < 3000,
    substr(v135_key, 1, 200))
chk("★★ 键盘方向键和 dragDelta 是同一套符号（漏一个就是「拖对、按键反」）",
    all(vapply(v135_left, function(w)
      grepl(sprintf('c.which === "%s"', w), v135_key, fixed = TRUE), logical(1))) &&
      grepl('grow = "ArrowRight"', v135_key, fixed = TRUE),
    v135_key)

# ★ 服务端那一个 observeEvent 要把三个键都收下。漏了 sess_w 的表现：
#   拖完松手，宽度弹回去 —— 因为写库用的 full 里 sess_w 还是库里那个旧值。
v134_lines <- strsplit(v134_chat, "\n", fixed = TRUE)[[1]]
v134_at    <- grep("observeEvent\\(input\\$panel_size", v134_lines)[1]
v134_obs   <- paste(v134_lines[v134_at:min(v134_at + 25L, length(v134_lines))],
                    collapse = "\n")
chk("★★ 服务端把 sess_w 也写回库里（漏了就是「拖完弹回去」）",
    grepl("full$sess_w     <- p$sess_w", v134_obs, fixed = TRUE) &&
      grepl("if (!is.null(p$sess_w))", v134_obs, fixed = TRUE), v134_obs)

# ★ 设置页那张卡片：拖不了的时候（键盘用户、想填个准确数的人）得有另一条路。
v134_set <- paste(readLines("R/mod_settings.R", warn = FALSE), collapse = "\n")
chk("★ 设置页也给了导航栏宽度一个数字框，而且有观察者",
    grepl('numericInput(ns("pref_sess_w")', v134_up, fixed = TRUE) &&
      grepl('observeEvent(input$pref_sess_w,     save_uipref("sess_w"',
            v134_set, fixed = TRUE), v134_set)
chk("★★ 「恢复默认」要把这个框也按回去（漏了的表现：另两个框都回去了，就它没回去）",
    grepl('updateNumericInput(session, "pref_sess_w",     value = def$sess_w)',
          v134_set, fixed = TRUE), v134_set)

# =============================================================================
# V14 item 1：文件页「文件管理区 ↔ 预览」能拖着改宽
# =============================================================================
# 用户原话：「文件管理区和预览之间应该可以拖动改变大小」。
#
# ★ 和 V13.5 item 2（历史任务页）**同一套机制**，风险也一样：四份东西必须
#   互相对得上，而它们分居四个文件、没有一个共同的来源 ——
#
#     R/uiprefs.R 的 DSAPP_UIPREF_SPECS$filespage_w  ← 存库、发变量、设置页
#     www/app.js   的 SPEC.filespage_w               ← 拖动时现算边界
#     www/app.css  的 var(--dsapp-filespage-w, 420px) ← 真正决定栏宽
#     R/mod_files.R 的结构（.dsapp-files-page / .dsapp-files-list / split_f）
#
#   任何一处对不上，浏览器都不报错 —— 表现只是"拖起来怪怪的"或者"拖了没反应"。
#
# ⚠️⚠️ 这一条最贵的错法是**跟 files_w 混用**：files_w 是「言出法随」页右边
#    的产物栏（.dsapp-files-col），filespage_w 是「文件」页左边那一栏
#    （.dsapp-files-list）。混用不报错，症状是"在文件页拖动，分隔条一碰就
#    跳到最小值（因为量的是另一个页面上 display:none 的列，宽度是 0），
#    而且顺手把对话页的栏宽也改了"。所以下面单有一条钉住两个页面互不串门。
v14_files <- paste(readLines("R/mod_files.R", warn = FALSE), collapse = "\n")
v14_css   <- paste(readLines("www/app.css",   warn = FALSE), collapse = "\n")

chk("★★ 文件页的骨架：外层 .dsapp-files-page、左栏 .dsapp-files-list、右栏 .dsapp-files-prev",
    grepl('class = "dsapp-files-page"', v14_files, fixed = TRUE) &&
      grepl('class = "dsapp-files-list"', v14_files, fixed = TRUE) &&
      grepl('class = "dsapp-files-prev"', v14_files, fixed = TRUE),
    v14_files)
# ⚠️ 这一条是"真的换掉了"的判据。留着 layout_columns 的话，外面那层 flex
#    容器里会塞进一个 .bslib-grid —— 宽度由 12 栅格的百分比说了算，变量
#    拖了也没人读，表现是"分隔条能拖、列表纹丝不动"。
# ⚠️ 查的是**去掉注释之后**的源码：本文件顶上那段说明里就原样引用了这一句
#    （"这一页原来是一句 layout_columns(col_widths = c(5, 7))"），不去注释
#    的话这条断言永远红，而红的原因和被测代码毫无关系。
v14_code <- paste(Filter(function(l) !grepl("^\\s*#", l),
                         strsplit(v14_files, "\n", fixed = TRUE)[[1]]),
                  collapse = "\n")
chk("★★ 那一句 layout_columns(col_widths = c(5, 7)) 已经拿掉了（留着就是「能拖但纹丝不动」）",
    !grepl("col_widths = c(5, 7)", v14_code, fixed = TRUE), v14_code)

# ★ 分隔条本身：id 结尾的字母（f）、指的量（filespage_w）、tabindex。
#   ⚠️ 和 V13.5 那三条同一个道理 —— report() 靠 id 的形状推 input 名，
#      推不出来是**静默**不上报（拖完刷新打回原形，控制台干干净净）。
chk("★★ 分隔条：id 以 split_f 结尾、data-dsapp-panel 指 filespage_w、tabindex=0",
    grepl('id = ns("split_f")', v14_files, fixed = TRUE) &&
      grepl('`data-dsapp-panel` = "filespage_w"', v14_files, fixed = TRUE) &&
      grepl('class = "dsapp-split-v"', v14_files, fixed = TRUE) &&
      grepl('tabindex = "0"', v14_files, fixed = TRUE),
    v14_files)

# ★ 两份边界拷贝（app.js 现用的 + R 里的）必须一致。
chk("★★ app.js 的 SPEC.filespage_w 和 R 里的边界一致（对不上就是「拖到边界松手跳一格」）",
    grepl(sprintf("filespage_w: { def: %d, min: %d, max: %d }",
                  DSAPP_UIPREF_SPECS$filespage_w$def,
                  DSAPP_UIPREF_SPECS$filespage_w$min,
                  DSAPP_UIPREF_SPECS$filespage_w$max),
          v134_js, fixed = TRUE),
    sprintf("R: def=%d min=%d max=%d", DSAPP_UIPREF_SPECS$filespage_w$def,
            DSAPP_UIPREF_SPECS$filespage_w$min,
            DSAPP_UIPREF_SPECS$filespage_w$max))
chk("★★ app.css 里那条 var() 的 fallback 和 R 的默认值一字不差（对不上的表现：没调过的人看到一个宽度，随手一拖又跳到另一个）",
    grepl("flex: 0 0 var(--dsapp-filespage-w, 420px)",
          v14_css, fixed = TRUE) &&
      identical(DSAPP_UIPREF_SPECS$filespage_w$def, 420L),
    v14_css[1])

# ★★ 两个页面互不串门。这一条查的是**文件名和类名**层面的隔离，
#    比"读一遍代码看看有没有写错"可靠。
chk("★★★ 文件页那个量叫 filespage_w，和对话页的 files_w 是两回事",
    grepl('`data-dsapp-panel` = "filespage_w"', v14_files, fixed = TRUE) &&
      !grepl('`data-dsapp-panel` = "files_w"', v14_files, fixed = TRUE) &&
      !grepl('class = "dsapp-files-col"', v14_files, fixed = TRUE) &&
      !grepl('dsapp-files-list', v134_chat, fixed = TRUE),
    sprintf("mod_chat 里有 .dsapp-files-list：%s",
            grepl('dsapp-files-list', v134_chat, fixed = TRUE)))
chk("★★ app.js 的 current() 量的是 .dsapp-files-list（量成 .dsapp-files-col 的话，文件页里那一列是隐藏的，宽度恒为 0）",
    grepl('var lp = document.querySelector(".dsapp-files-list");',
          v134_js, fixed = TRUE), v134_js[1])

# ★ 服务端那一个 observeEvent 要认下 filespage_w。漏了的表现：拖完松手，
#   宽度弹回去 —— 写库用的 full 里 filespage_w 还是库里那个旧值。
v14_lines <- strsplit(v14_files, "\n", fixed = TRUE)[[1]]
v14_at    <- grep("observeEvent\\(input\\$panel_size", v14_lines)[1]
v14_obs   <- paste(v14_lines[v14_at:min(v14_at + 25L, length(v14_lines))],
                   collapse = "\n")
chk("★★ 文件页服务端把 filespage_w 写回库里（漏了就是「拖完弹回去」）",
    !is.na(v14_at) && grepl("full$filespage_w <- p$filespage_w", v14_obs,
                            fixed = TRUE) &&
      grepl("if (!is.null(p$filespage_w))", v14_obs, fixed = TRUE), v14_obs)
# ⚠️ 反向：文件页那条 observer **不能**顺手写 files_w —— 写了的话在文件页
#    拖一下，对话页的产物栏跟着变，而用户完全不知道发生了什么。
chk("★★ 文件页那条 observer 不碰 files_w（碰了就是「拖文件页，对话页跟着变」）",
    !is.na(v14_at) && !grepl("full$files_w", v14_obs, fixed = TRUE), v14_obs)

# ★ 窄屏兜底：叠放之后宽度设置没有意义，分隔条必须藏掉。
chk("★ 窄屏下文件页两栏叠起来、分隔条藏掉（留着用户会拖半天没反应）",
    grepl(".dsapp-files-page { flex-direction: column; }", v14_css,
          fixed = TRUE) &&
      grepl(".dsapp-files-page > .dsapp-split-v { display: none; }", v14_css,
            fixed = TRUE), v14_css[1])
chk("★ 左栏的 max-width 兜底在（变量里那个数是用户在某个窗口大小下调的，换台小屏打开就能吃掉大半个屏幕）",
    grepl("max-width: 70%;", v14_css, fixed = TRUE), v14_css[1])

# ★ 设置页：键盘用户和"我就想精确填个 420"的人的另一条路。
chk("★ 设置页给了「文件管理区宽度」一个数字框，而且有观察者",
    grepl('numericInput(ns("pref_filespage_w")', v134_up, fixed = TRUE) &&
      grepl('observeEvent(input$pref_filespage_w, save_uipref("filespage_w"',
            v134_set, fixed = TRUE), v134_set)
chk("★★ 「恢复默认」要把这个框也按回去（漏了的表现：别的框都回去了，就它没回去）",
    grepl('updateNumericInput(session, "pref_filespage_w", value = def$filespage_w)',
          v134_set, fixed = TRUE), v134_set)

# =============================================================================
# V16.6 云工具：文档注册表 → 执行体 的映射层（README 那张表里管它叫 item 4）
# =============================================================================
# 用户原话：「云工具是有GUI的工具，而不是接入言出法随界面给提示词，请按新
#           逻辑制作云工具界面」。
#
# 改之前：TCGA / 单细胞那两块里点**任何一行**都是开个对话、把一段提示词发
# 出去。改之后：点一行出**参数表单**（字段定义在 R/cloudrun.R），填完真跑；
# 文档里注册了但还没接执行体的明说「未接入执行体」，不发任何提示词。
#
# ★★ 这一节能验什么、不能验什么，先说清楚（本仓规矩：自检全绿 ≠ 功能被验过）：
#   · 能验：映射关系对不对得上、参数怎么进脚本（注入）、生成的脚本骨架完不
#     完整、环境名怎么解析、那条"发提示词"的老路删干净没有、那十个 output
#     的挂起关没关且位置对不对。
#   · **不能验界面**：renderUI 的内容没有 Shiny 会话就求值不到 —— 工作台画不
#     画得出来、徽章数是几个、点一行会不会真跑出产物，全在
#     `tests/ui_v166/probe_cloudgui.py`（42 条）。两个的分工在 2026-10-05 拿
#     **真变异**校过：把工作台那四个 output 从 `suspendWhenHidden = FALSE`
#     那一串里摘掉，浏览器那 42 条当场红 5 条，而这一节**照样全绿**。
section("V16.6 云工具：工具 → 执行体（映射层 + 参数怎么进脚本）")
{
  v166x_cfg <- dsapp_config()

  # ---- (a) key 与文档注册表逐字对得上 --------------------------------------
  # 期望值**写死在这里**，不引用 R 那边的常量：引用的话"代码改了、断言跟着
  # 改"就永远绿，而这恰恰是最容易犯的错（文档里那个 key 打错一个字母，
  # 症状是"界面上那个工具永远点不到执行体"——没有报错、没有日志）。
  v166x_want <- list(
    sc   = c("sc_read_data", "sc_qc_filter", "sc_normalize_hvg",
             "sc_dimreduce_cluster", "sc_find_markers", "sc_deg"),
    tcga = c("tcga_expression", "tcga_deg", "tcga_km", "tcga_unicox"))
  chk("★★★ 首批接入执行体的就是这 10 个（加了就明知故犯地改这一行）",
      identical(dsapp_cloudx_keys("sc"), v166x_want$sc) &&
        identical(dsapp_cloudx_keys("tcga"), v166x_want$tcga),
      sprintf("实际 sc=%s / tcga=%s",
              paste(dsapp_cloudx_keys("sc"), collapse = ","),
              paste(dsapp_cloudx_keys("tcga"), collapse = ",")))
  v166x_orph <- list(sc = dsapp_cloudx_orphans("sc"),
                     tcga = dsapp_cloudx_orphans("tcga"))
  chk("★★★ 一个孤儿都没有（接了执行体、文档注册表里没有那个 key）",
      all(vapply(v166x_orph, function(o) length(o$extra) == 0L, logical(1))),
      paste(vapply(v166x_orph, function(o) paste(o$extra, collapse = ","),
                   character(1)), collapse = " / "))
  # ★ 反向：`missing` 得是**有数**的 —— 一个"永远返回两个空表"的实现能骗过
  #   上面那条。49-6 / 58-4 是从 README 那份冻结记录里抄来的数。
  chk("★★ 文档里还没接执行体的数得出来（单细胞 43 / TCGA 54）",
      identical(vapply(v166x_orph, function(o) length(o$missing), integer(1)),
                c(sc = 43L, tcga = 54L)),
      paste(vapply(v166x_orph, function(o) length(o$missing), integer(1)),
            collapse = " / "))

  # ---- (b) 环境名：exact 匹配（`sc` 不许部分匹配到 `scRNA`）----------------
  chk("★★★ 环境名走 exact 匹配：写「sc」绝不会部分匹配到「scRNA」",
      is.na(dsapp_cloudx_env_dir("sc", v166x_cfg)) &&
        identical(dsapp_cloudx_env_dir("R", v166x_cfg), "") &&
        is.na(dsapp_cloudx_env_dir("没这个环境", v166x_cfg)),
      sprintf("sc=%s R=%r 没这个环境=%s",
              dsapp_cloudx_env_dir("sc", v166x_cfg),
              dsapp_cloudx_env_dir("R", v166x_cfg),
              dsapp_cloudx_env_dir("没这个环境", v166x_cfg)))

  # ---- (c) ★★★ 参数只走环境变量：**真跑一遍**带 shell 注入的值 ------------
  # 这是整条链上最要紧的一条：生成的脚本是用户点一下就执行的 bash，而参数
  # 里全是用户自己填的字符串（文件名、基因名、正则）。要是哪个字段被直接拼
  # 进脚本文本，那就是"填个基因名就能在这台机器上执行任意命令"。
  #
  # 为什么是**真跑**而不是"看源码里有没有 shQuote"：后者只能证明那一行写了，
  # 证明不了引号真的兜得住（`shQuote` 之外还有一层：值是不是在 heredoc 里被
  # 二次展开）。跑完看两件事——① 那个 touch 出来的文件不存在；② 导出的变量
  # 一字节不差。
  v166x_d   <- file.path(tempdir(), "dsapp_cloudx_head")
  dir.create(v166x_d, showWarnings = FALSE, recursive = TRUE)
  v166x_pwn <- file.path(v166x_d, "pwned")
  v166x_evil <- sprintf("a'; touch %s; echo '", v166x_pwn)
  v166x_got <- file.path(v166x_d, "got.txt")
  v166x_sh  <- file.path(v166x_d, "head.sh")
  writeLines(c(
    dsapp_cloudx_head(v166x_d, "", list(name = v166x_evil), rscript = FALSE),
    sprintf("printf '%%s' \"$DSAPP_NAME\" > %s", shQuote(v166x_got)),
    ""), v166x_sh)
  v166x_rc <- suppressWarnings(
    system2("bash", shQuote(v166x_sh), stdout = FALSE, stderr = FALSE))
  chk("★★★ 参数里的 shell 注入原样当字符串——没有执行（那个文件不存在）",
      !file.exists(v166x_pwn),
      sprintf("退出码 %s；%s %s", v166x_rc,
              if (file.exists(v166x_pwn)) "**注入被执行了**" else "没有副作用",
              v166x_pwn))
  chk("★★★ 而且是一字节不差地传进去的（不是被转义成一坨别的）",
      file.exists(v166x_got) &&
        identical(readLines(v166x_got, warn = FALSE), v166x_evil),
      if (file.exists(v166x_got))
        paste(readLines(v166x_got, warn = FALSE), collapse = "") else "没写出 got.txt")

  # ---- (d) 十个执行体每一个都生成得出完整脚本 ------------------------------
  # 体检只看"文件在不在"，所以拿两个空文件就够 —— 这里判的是**生成**，
  # 不是"能不能跑"（那要 conda 环境，跑在探针和人工验收那边）。
  v166x_ws <- file.path(tempdir(), "dsapp_cloudx_ws")
  dir.create(v166x_ws, showWarnings = FALSE, recursive = TRUE)
  v166x_h5  <- file.path(v166x_ws, "dummy.h5ad"); writeLines("x", v166x_h5)
  v166x_csv <- file.path(v166x_ws, "dummy.csv")
  writeLines("gene,S1", v166x_csv)
  # scRNA 那个环境在这台机器上不一定建了；体检会因此拒绝生成。造一个空壳
  # 目录就够（`dsapp_cloudx_env_dir` 只看目录在不在）。
  dir.create(file.path(v166x_cfg$envs_root, "scRNA", "bin"),
             showWarnings = FALSE, recursive = TRUE)
  v166x_bad <- character(0); v166x_ok <- 0L
  for (v166x_k in c("sc", "tcga")) {
    for (v166x_key in dsapp_cloudx_keys(v166x_k)) {
      v166x_sp <- dsapp_cloudx_get(v166x_k, v166x_key)
      v166x_v  <- list()
      for (v166x_f in v166x_sp$fields) {
        v166x_v[[v166x_f$id]] <-
          if (identical(v166x_f$type, "file")) {
            if (identical(v166x_f$exts[1], ".h5ad")) v166x_h5 else v166x_csv
          } else v166x_f$def
      }
      v166x_b <- tryCatch(
        dsapp_cloudx_build(v166x_k, v166x_key, v166x_v, v166x_ws, v166x_cfg),
        error = function(e) list(ok = FALSE, msg = conditionMessage(e)))
      if (!isTRUE(v166x_b$ok)) {
        v166x_bad <- c(v166x_bad, sprintf("%s(%s)", v166x_key,
                                          v166x_b$msg %||% "?"))
        next
      }
      v166x_ok <- v166x_ok + 1L
      v166x_c  <- v166x_b$code
      # 骨架四件套：失败要能被引擎看见（pipefail + die）、产物要落在**这次
      # 运行自己的**目录里（ROOT + cd）、日志要留一份跟着这次运行走。
      for (v166x_need in c("set -o pipefail", "ROOT=", "die()", "need()",
                           "run.log", "export DSAPP_")) {
        if (!grepl(v166x_need, v166x_c, fixed = TRUE))
          v166x_bad <- c(v166x_bad, sprintf("%s(缺 %s)", v166x_key, v166x_need))
      }
      if (!dir.exists(v166x_b$root))
        v166x_bad <- c(v166x_bad, sprintf("%s(产物目录没建)", v166x_key))
    }
  }
  chk("★★★ 十个执行体每一个都生成得出完整脚本（骨架齐、产物目录也建了）",
      length(v166x_bad) == 0L && v166x_ok == 10L,
      paste(c(v166x_bad, sprintf("成功 %d/10", v166x_ok)), collapse = " · "))

  # ---- (e) 没接执行体的 key：生成不出来，而且**说得明白** ------------------
  # ⚠️ 先确认那个 key 真的在文档里 —— 不然这条测的是"key 打错了"，
  #    而它长得跟"没有执行体"一模一样（本仓老账：判据要和已知会红的样本对一次）。
  chk("★★ 文档里那个 key 确实在（否则下面那条测的是别的东西）",
      !is.null(dsapp_cloudreg_find("tcga", "tcga_lasso")))
  v166x_nb <- tryCatch(
    dsapp_cloudx_build("tcga", "tcga_lasso", list(), v166x_ws, v166x_cfg),
    error = function(e) list(ok = FALSE, msg = conditionMessage(e)))
  chk("★★ 没接执行体的 key 生成不出脚本，而且理由写的是「没有执行体」",
      identical(v166x_nb$ok, FALSE) &&
        grepl("执行体", v166x_nb$msg %||% "", fixed = TRUE),
      v166x_nb$msg %||% "（没给理由）")

  # ---- (f) 那条"发提示词"的老路：剥注释之后逐字扫，一个都不许剩 ----------
  # ⚠️ 先剥注释再扫：这些名字**恰恰**写在解释它们被删掉的注释里（连踩三次
  #    的老账）。`fixed = TRUE` 也是必须的（正则里没转义的 `(` 是空组，
  #    返回的是 -1 —— 静默走样）。
  v166x_src  <- readLines("R/mod_cloudtool.R", warn = FALSE)
  v166x_code <- v166x_src[!grepl("^\\s*#", v166x_src)]
  v166x_hit  <- c("lit_go", "cloud_go", "plan_go",
                  "tcga_go", "sc_go", "db_session_create", "db_message_add",
                  "dsapp_agent")
  v166x_left <- v166x_hit[vapply(v166x_hit,
                                 function(p) any(grepl(p, v166x_code,
                                                       fixed = TRUE)),
                                 logical(1))]
  chk("★★★ 云工具页里再没有「点一行就开个会话发提示词」那条路（剥注释后逐字扫）",
      length(v166x_left) == 0L, paste(v166x_left, collapse = ","))

  # ---- (f1b) sendCustomMessage：从"一个都不许有"收窄成"只许有那一个用途" ----
  # ⚠️ V16.7 item 4 给这一页加了**一个合法用途**：传完文件之后复位
  #    `<input type=file>` —— 输入框没复位的话，连传同一个文件第二次浏览器
  #    认为"没变化"、change 不触发，用户看到的是"点了上传没反应"
  #    （`R/mod_files.R` 里记过这条账）。走的是全站同一个 `dsapp:resetUpload`。
  #
  # ⚠️ 判据从"命中数 == 0"换成"**逐个报出消息名**"。理由不是"数个数有漏洞"
  #    （阈值 0 时没有：任何名字出现都是红的），而是"数个数**没法只放行一个
  #    名字**"—— 阈值只能整体抬，抬到 2 就等于连两条提示词消息一起放行。
  #    逐个认名字之后，除了 `dsapp:resetUpload` 之外的**任何**消息名出现
  #    仍然是红的（实测：把一处复位改成 `dsapp:lit_go` 当场变红）。
  #    ⚠️ 别退化成"命中数 <= 2"：那是在数个数，不是在认名字。
  v166x_call <- unlist(regmatches(paste(v166x_code, collapse = "\n"),
                                  gregexpr('sendCustomMessage\\("[^"]*"',
                                           paste(v166x_code, collapse = "\n"))))
  v166x_name <- unique(sub('.*"([^"]*)"$', '\\1', v166x_call))
  chk("★★★ 这一页的 sendCustomMessage **只有**复位上传框那一种（提示词那条路仍然没有）",
      length(setdiff(v166x_name, "dsapp:resetUpload")) == 0L,
      paste(v166x_name, collapse = ","))
  # ★ 反向对照：提取法在这一页上**确实抓得到东西**。没有这一条的话，上面
  #    那条在"提取法失效、永远回 character(0)"时也是绿的。
  chk("★ 反向对照：提取法抓得到 dsapp:resetUpload（证明上面那条不是空转）",
      "dsapp:resetUpload" %in% v166x_name, paste(v166x_name, collapse = ","))
  # ★ 反向：这一条得**不是真空的** —— 同一个扫法在旧版上是红的。上面那个
  #   列表里的名字在别处（对话页、文献页）**必须**还在，否则说明我扫错了文件。
  chk("★ 反向对照：同一个词在别的文件里照样扫得到（证明扫法有效）",
      any(grepl("sendCustomMessage",
                readLines("R/mod_lit.R", warn = FALSE), fixed = TRUE)) ||
        any(grepl("sendCustomMessage",
                  readLines("R/mod_chat.R", warn = FALSE), fixed = TRUE)))

  # ---- (f2) R/cloudtool.R 里那三个"拼提示词"的函数也必须没人调 ------------
  # 界面那边删干净了，但 `dsapp_cloudreg_prompt()`（拼单个工具的开场白）、
  # `dsapp_cloudreg_plan()`（拼一条路线）、`dsapp_cloudreg_skill_id()`
  # 是**内容侧**的同一套东西，它们还在 R/cloudtool.R 里活着。
  #
  # ⚠️ 现在它们**一个调用方都没有**（实测）。留着它们不是错（内容还能复用），
  #    错的是"哪天有人顺手接回去" —— 那等于把用户否掉的路又装上，而且
  #    界面看着一切正常。所以这里钉的是**调用方数目为 0**，不是"函数不存在"。
  #    ⚠️ 扫的是 R/ 下**除 cloudtool.R 自己**以外的文件 + www/ + app.R：
  #       cloudtool.R 里 `dsapp_cloudreg_prompt` 调 `dsapp_cloudreg_tail`
  #       这类**内部**调用不算"接回去了"。
  v166x_ui_src <- c(paste(readLines("app.R", warn = FALSE), collapse = "\n"),
                    vapply(list.files("R", "[.]R$", full.names = TRUE),
                           function(p) paste(readLines(p, warn = FALSE),
                                             collapse = "\n"), ""),
                    paste(readLines("www/app.js", warn = FALSE), collapse = "\n"))
  names(v166x_ui_src) <- c("app.R",
                           list.files("R", "[.]R$"), "www/app.js")
  v166x_ui_src <- v166x_ui_src[names(v166x_ui_src) != "cloudtool.R"]
  v166x_dec <- c("dsapp_cloudreg_prompt(", "dsapp_cloudreg_plan(",
                 "dsapp_cloudreg_skill_id(")
  v166x_called <- character(0)
  for (p in v166x_dec) {
    for (nm in names(v166x_ui_src)) {
      # 剥注释再扫：解释这条坑的注释里就写着这些函数名
      body_txt <- paste(v166x_ui_src[[nm]][
        !grepl("^\\s*#", strsplit(v166x_ui_src[[nm]], "\n", fixed = TRUE)[[1]])],
        collapse = "\n")
      if (any(grepl(p, body_txt, fixed = TRUE))) {
        v166x_called <- c(v166x_called, sprintf("%s→%s", p, nm))
      }
    }
  }
  chk("★★★ 那三个「拼提示词」的函数没有任何界面调用方（接回去 = 用户否掉的路复辟）",
      length(v166x_called) == 0L, paste(v166x_called, collapse = ", "))
  # ★ 而且它们**真的还在**（不然上一条是在验一个不存在的函数，白绿）
  chk("★ 前置：那三个函数确实还在 R/cloudtool.R 里（否则上一条是真空的）",
      all(vapply(c("dsapp_cloudreg_prompt <- function",
                   "dsapp_cloudreg_plan <- function",
                   "dsapp_cloudreg_skill_id <- function"),
                 function(p) any(grepl(p, readLines("R/cloudtool.R", warn = FALSE),
                                       fixed = TRUE)), logical(1))))

  # ---- (g) 十个新 output 的挂起关掉了，而且位置在**所有** output 之后 ------
  # `suspendWhenHidden = FALSE` 是这一页的命门：面板二/三是**一开始就
  # display:none** 的（前端切 class），不关挂起 = renderUI 永远不被调用 =
  # 一块永远空着的卡片，而控制台一个错都没有。
  # ⚠️ 而 `outputOptions()` 是**当场**去 output 表里找名字的，找不到就抛 ——
  #    写在 output 定义**前面** = server 起不来 = **整页白屏**。两个坑方向相反，
  #    所以位置和内容都要钉。
  v166x_loop <- grep('for (o in c("tcga_plan_area"', v166x_src, fixed = TRUE)
  v166x_lastdef <- max(grep("^\\s*output\\$(tcga_rows|sc_rows) <-", v166x_src))
  chk("★★★ 关挂起那一串在**所有** output 定义之后（写前面 = server 起不来 = 整页白屏）",
      length(v166x_loop) == 1L && v166x_loop > v166x_lastdef,
      sprintf("循环在第 %s 行，最后一个 output 定义在第 %s 行",
              paste(v166x_loop, collapse = ","), v166x_lastdef))
  v166x_blk <- paste(v166x_src[v166x_loop:min(v166x_loop + 12L,
                                               length(v166x_src))],
                     collapse = "\n")
  v166x_want_out <- c("tcga_plan_area", "sc_plan_area", "tcga_groupsel",
                      "sc_groupsel", "tcga_rows", "sc_rows",
                      "tcga_workbench", "sc_workbench",
                      "tcga_tool_status", "sc_tool_status")
  v166x_miss <- v166x_want_out[!vapply(v166x_want_out,
                                       function(o) grepl(o, v166x_blk,
                                                         fixed = TRUE),
                                       logical(1))]
  chk("★★★ 十个 output 一个不漏地关掉了挂起（少一个 = 那块永远不画）",
      length(v166x_miss) == 0L, paste(v166x_miss, collapse = ","))

  # ---- (h) 行上的两种徽章 + 两种按钮文案（界面的"能跑/不能跑"就靠它俩）----
  # ⚠️ 每条 grepl 都要套 any()：v166x_code 是**一行一条**的字符向量，
  #    不套的话 grepl 回的是长度 1205 的逻辑向量，而 R 4.3 起 `&&` 遇到
  #    长度 > 1 的右操作数**直接报错**（老版本是静默只取第一个 —— 那才是
  #    真危险：取到的那一个恰好是 FALSE 就假红、恰好 TRUE 就假绿）。
  chk("★★ 工具行分「可运行 / 未接入执行体」两档，按钮文案也跟着分两档",
      any(grepl('"可运行"', v166x_code, fixed = TRUE)) &&
        any(grepl('"未接入执行体"', v166x_code, fixed = TRUE)) &&
        any(grepl('"配置并运行"', v166x_code, fixed = TRUE)) &&
        any(grepl('"看看它要什么"', v166x_code, fixed = TRUE)))
}

# =============================================================================
section("V16.6 item 5：Windows / Mac 包的三个 mac 侧坑（du / locale / conda）")
# =============================================================================
# 用户原话：「同步给出windows版与Mac版……」。打包脚本是一回事，**应用本身
# 在 mac 上跑不跑得对**是另一回事 —— 这三处都是在 Linux 上永远看不出来的：
#
#   ① `du -sb` —— `-b` 是 GNU 专有选项，macOS 的 BSD du 没有。报错打到
#      stderr（调用方一直 stderr = FALSE 吞着），结果是 out 为空 → NA。
#      症状：**每一个"占用多少空间"都显示成「—」**，不报错。
#   ② `LANG=LC_ALL="C.UTF-8"` —— macOS 没有 `C.UTF-8` 这个 locale，
#      子进程会静默回退到 "C"，中文输出又变乱码，而"设过了"看着已经做了。
#   ③ conda 候选表缺 `/opt/homebrew/bin/conda` —— Apple Silicon 的
#      Homebrew 前缀，M 系列上"环境"页会说找不到 conda，而用户明明装了。
# =============================================================================
{
  # ---- ① 只剩一处 du，而且带 -sk 回退 --------------------------------
  # ⚠️ 这里必须先剥注释：解释这件事的那段 `#'` 文档注释里就**原样写着**
  #    `system2("du", c("-sb", ...))`。不剥的话数出来是 2，然后人就会去
  #    "修"一个不存在的问题。（第一版就是这么红的 —— 而同一个块里
  #    下面那条全仓扫描剥了注释、这条没剥，两条对不上才发现。）
  v166d_src <- readLines("R/utils.R", warn = FALSE)
  v166d_src_code <- v166d_src[!grepl("^\\s*#", v166d_src)]
  chk("★★★ 跨平台的 du 只有一份实现（原来四个地方各拼一遍，一起错且无声）",
      sum(grepl("system2\\(\"du\"", v166d_src_code)) == 1L,
      sprintf("R/utils.R 里 system2(\"du\") 出现 %d 次（剥注释后）",
              sum(grepl("system2\\(\"du\"", v166d_src_code))))
  # 剥注释后全仓扫：别处不许再有自己拼的 du（注释里提到不算）
  v166d_all <- unlist(lapply(list.files("R", "[.]R$", full.names = TRUE),
                             function(p) {
                               ln <- readLines(p, warn = FALSE)
                               ln[!grepl("^\\s*#", ln)]
                             }))
  v166d_du <- grep("system2\\(\"du\"", v166d_all, value = TRUE)
  chk("★★★ 除 R/utils.R 外没有任何地方自己拼 du（四份会分家）",
      length(v166d_du) == 1L,
      paste(utils::head(v166d_du, 4), collapse = " ｜ "))
  chk("★★★ 回退链写着 -sb → -sk（少了 -sk，mac 上永远是「—」）",
      any(grepl('c("-sb", "-sk")', v166d_src, fixed = TRUE)),
      "找 c(\"-sb\", \"-sk\")")
  # ★★★ 真跑一遍：拿一个**拒绝 -b** 的假 du 放到 PATH 最前面（等价于 mac）
  #      —— 上面两条都只是"源码里写了回退"，写没写对只有跑一次才知道。
  #      本仓栽过"变异是空转的"，所以这条判据必须是**行为**，不是字面。
  v166d_fake <- file.path(tempdir(), "fakedu")
  dir.create(v166d_fake, showWarnings = FALSE)
  v166d_exe <- file.path(v166d_fake, "du")
  writeLines(c("#!/bin/bash",
               "for a in \"$@\"; do case \"$a\" in -*b*)",
               "  echo 'du: illegal option -- b' >&2; exit 1;; esac; done",
               paste0("exec ", Sys.which("du"), " \"$@\"")), v166d_exe)
  Sys.chmod(v166d_exe, "0755")
  v166d_oldpath <- Sys.getenv("PATH")
  Sys.setenv(PATH = paste0(v166d_fake, ":", v166d_oldpath))
  v166d_dir <- file.path(tempdir(), "du_probe_dir")
  dir.create(v166d_dir, showWarnings = FALSE)
  writeBin(raw(50000), file.path(v166d_dir, "x"))
  v166d_got <- tryCatch(dsapp_du_bytes(v166d_dir), error = function(e) NA_real_)
  Sys.setenv(PATH = v166d_oldpath)          # 立刻还原，别影响后面的断言
  chk("★★★ 假 BSD du（拒绝 -b）下仍然量得出字节数 —— 回退真的会走",
      length(v166d_got) == 1L && !is.na(v166d_got) && v166d_got >= 4096,
      sprintf("拿到 %s（NA = 回退从没生效，mac 上就是「—」）",
              format(v166d_got)))
  # ★ 路径对不上时不许张冠李戴（老实现按 basename 配，同名就错位）
  v166d_a <- file.path(tempdir(), "sameA", "same")
  v166d_b <- file.path(tempdir(), "sameB", "same")
  dir.create(v166d_a, recursive = TRUE, showWarnings = FALSE)
  dir.create(v166d_b, recursive = TRUE, showWarnings = FALSE)
  writeBin(raw(1000),  file.path(v166d_a, "f"))
  writeBin(raw(40000), file.path(v166d_b, "f"))
  v166d_pair <- dsapp_du_bytes(c(v166d_a, v166d_b))
  chk("★★ 两个同名目录不会被配错（老实现按 basename 配 = 张冠李戴）",
      length(v166d_pair) == 2L && !anyNA(v166d_pair) &&
        v166d_pair[[1]] < v166d_pair[[2]],
      sprintf("%s / %s", format(v166d_pair[[1]]), format(v166d_pair[[2]])))
  chk("★ 不存在的路径回 NA，但**同批别的路径照样量得出来**（不是整批报废）",
      {
        v166d_mix <- dsapp_du_bytes(c(v166d_dir, "/no/such/dir/anywhere"))
        length(v166d_mix) == 2L && !is.na(v166d_mix[[1]]) && is.na(v166d_mix[[2]])
      })

  # ---- ② locale 不再硬写 C.UTF-8 --------------------------------------
  v166d_ex <- readLines("R/executor.R", warn = FALSE)
  v166d_ex_code <- v166d_ex[!grepl("^\\s*#", v166d_ex)]
  chk("★★★ executor.R 不再把 C.UTF-8 硬写进子进程环境（macOS 没这个 locale）",
      !any(grepl('"C.UTF-8"', v166d_ex_code, fixed = TRUE)) &&
        any(grepl("dsapp_utf8_locale()", v166d_ex_code, fixed = TRUE)),
      sprintf("代码里 \"C.UTF-8\" 出现 %d 次",
              sum(grepl('"C.UTF-8"', v166d_ex_code, fixed = TRUE))))
  # ★ 真调一次：返回的必须是一个**本机真的能用**的 locale（不是抄来的字符串）
  v166d_loc <- dsapp_utf8_locale()
  v166d_before <- Sys.getlocale("LC_CTYPE")
  v166d_ok <- suppressWarnings(tryCatch({
    got <- Sys.setlocale("LC_CTYPE", v166d_loc)
    suppressWarnings(tryCatch(Sys.setlocale("LC_CTYPE", v166d_before),
                              error = function(e) ""))
    nzchar(got)
  }, error = function(e) FALSE))
  chk("★★★ dsapp_utf8_locale() 返回的是本机**真的设得上**的 locale",
      is.character(v166d_loc) && nzchar(v166d_loc) && isTRUE(v166d_ok),
      sprintf("返回 %s，设得上=%s", v166d_loc, v166d_ok))
  # ⚠️ 而且它**不许**留下副作用（本仓铁律：绝不 Sys.setenv 影响别人）
  chk("★★★ 调它之后本进程的 locale 原样不变（只回答该给孩子用什么）",
      identical(Sys.getlocale("LC_CTYPE"), v166d_before),
      sprintf("调之前 %s / 调之后 %s", v166d_before,
              Sys.getlocale("LC_CTYPE")))

  # ---- ③ conda 候选表带上 macOS 的 Homebrew 前缀 -----------------------
  v166d_cfg <- readLines("R/config.R", warn = FALSE)
  chk("★★★ conda 候选表里有 Apple Silicon 的 /opt/homebrew（M 系列上否则找不到）",
      any(grepl('"/opt/homebrew/bin/conda"', v166d_cfg, fixed = TRUE)),
      "找 /opt/homebrew/bin/conda")
  chk("★ 候选表本身还是「先看环境变量、再看 Sys.which、最后逐个探」的形状",
      any(grepl("dsapp_find_conda <- function", v166d_cfg, fixed = TRUE)) &&
        any(grepl("file.access(candidates, 1)", v166d_cfg, fixed = TRUE)))
}

# =============================================================================
section("V16.6 item 5（续）：分发物本身 —— 字节码包 + 两个平台的启动器")
# =============================================================================
# 上一节钉的是"应用在 mac 上跑不跑得对"，这一节钉的是**发出去的那个包**。
# 用户原话：「同步给出windows版与Mac版……最好是一体式的程序文件，让用户无法
# 查看源码」。四条链路，每条坏掉的方式都是静默的：
#
#   ① 启动器（run_app.command）—— macOS 的 .command 和 Windows 的 .bat 在
#      **换行**上要求正好相反：.bat 必须 CRLF，.command 必须 LF。带 CR 的
#      shebang 会让内核去找一个叫 "/bin/bash\r" 的解释器，报的是
#      "bad interpreter" —— 看着像权限问题，实际是行尾。
#   ② 字节码的版本闸门（desktop/bytecode_app.R 里的 key()）—— R 遇到版本
#      不符的字节码是**静默回退解释执行**，不报错。闸门要是写空了，表现是
#      "包在错误的 R 上照跑，只是慢"，没有任何迹象。⚠️ 这个闸门 V16.6 真的
#      被写空过一次（下标没滤空串），所以下面既有行为判据也有"空转"判据。
#   ③ 打包脚本自己必须能在 macOS 上跑 —— 这个包就是要 Mac 用户（或者拿 Mac
#      的同事）打的，留在里面的 GNU 专有写法会当场失败，而错误信息指不到点。
#   ④ 打包时"清单 ↔ 磁盘"两个方向都要核 —— 只核一个方向时，新加的 R/*.R
#      忘了写进清单 = 源码模式和分发包**一起**坏，谁也不提示。
#
# ⚠️ 这台机器是 Linux。下面查的是"写法/结构对不对"，**不是**"在 Mac 和
#    Windows 上跑通了" —— 那两件事不一样，别把这一节全绿当成跨平台没问题。

# ---- ① 两个平台的启动器：换行要求正好相反 ------------------------------
{
  chk("★★ macOS 启动器 run_app.command 在（Mac 用户双击的就是它）",
      file.exists("run_app.command"))
  if (file.exists("run_app.command")) {
    v166e_cmd_raw <- readBin("run_app.command", "raw", file.size("run_app.command"))
    v166e_cmd_int <- as.integer(v166e_cmd_raw)
    # ★★★ 和 .bat 相反的判据。CR 在 shebang 后面 = 内核去找 "/bin/bash\r"。
    #      本仓踩过"判据没劲"：这条必须是**数出来**的，不能是"看着没毛病"。
    chk("★★★ run_app.command 是纯 LF（带 CR 会报 bad interpreter: /bin/bash^M）",
        sum(v166e_cmd_int == 13L) == 0L,
        sprintf("CR 出现 %d 次", sum(v166e_cmd_int == 13L)))
    chk("★★ run_app.command 第一行就是 bash shebang",
        identical(readLines("run_app.command", n = 1L, warn = FALSE), "#!/bin/bash"),
        paste(readLines("run_app.command", n = 1L, warn = FALSE), collapse = ""))
    v166e_cmd_src <- paste(readLines("run_app.command", warn = FALSE), collapse = "\n")
    # 双击时 cwd 是家目录，不 cd 到脚本所在目录就会去 ~ 底下找 runtime/。
    chk("★★ run_app.command 先 cd 到脚本自己所在目录（双击时 cwd 是 ~ 不是包目录）",
        grepl("dirname", v166e_cmd_src, fixed = TRUE) &&
          grepl("cd ", v166e_cmd_src, fixed = TRUE))
    chk("★★ run_app.command 优先用包里那份运行时（不是系统 R）",
        grepl("runtime/R/bin/Rscript", v166e_cmd_src, fixed = TRUE))
    # 用户第一次打开**一定**会被 Gatekeeper 拦（我们没买苹果签名证书）。
    # 说明书里不写清楚，用户看到的就是"双击没反应"，然后来问"是不是坏了"。
    v166e_how <- if (file.exists("desktop/HOWTO-macOS.txt"))
      readLines("desktop/HOWTO-macOS.txt", warn = FALSE) else character(0)
    chk("★★★ HOWTO-macOS.txt 写了 Gatekeeper 拦截怎么绕过（不写 = 用户以为文件坏了）",
        length(v166e_how) > 0L &&
          any(grepl("quarantine", v166e_how, fixed = TRUE)) &&
          any(grepl("右键", v166e_how, fixed = TRUE)),
        sprintf("quarantine=%s 右键=%s",
                any(grepl("quarantine", v166e_how, fixed = TRUE)),
                any(grepl("右键", v166e_how, fixed = TRUE))))
  }
}

# ---- ② 字节码版本闸门：行为判据 ----------------------------------------
{
  # 从源码里把那个 key() **抠出来真跑**。本仓栽过"自检只验源码不验行为"
  # （V13.17 那次），所以这里不查"有没有写 nzchar"，直接看它算出来是什么。
  v166e_bsrc <- readLines("desktop/bytecode_app.R", warn = FALSE)
  v166e_i <- grep("^\\s*key <- function", v166e_bsrc)
  v166e_key <- NULL
  if (length(v166e_i) == 1L) {
    v166e_j <- v166e_i + which(grepl("^\\s*\\}\\s*$", v166e_bsrc[-(1:v166e_i)]))
    if (length(v166e_j)) {
      v166e_key <- tryCatch({
        v166e_env <- new.env()
        eval(parse(text = paste(v166e_bsrc[v166e_i:min(v166e_j)] , collapse = "\n")),
             envir = v166e_env)
        v166e_env$key
      }, error = function(e) NULL)
    }
  }
  chk("★★★ 从 bytecode_app.R 里抠得出那个版本闸门的 key()（抠不出来下面三条全白搭）",
      is.function(v166e_key),
      sprintf("匹配到 %d 处 `key <- function`，解出来是 %s",
              length(v166e_i), class(v166e_key)[1]))
  if (is.function(v166e_key)) {
    v166e_kv <- function(s) tryCatch(as.character(v166e_key(s)),
                                     error = function(e) NA_character_)
    v166e_k442 <- v166e_kv("R version 4.4.2 (2024-10-31)")
    v166e_k443 <- v166e_kv("R version 4.4.3 (2025-02-28)")
    v166e_k450 <- v166e_kv("R version 4.5.0 (2025-04-11)")
    v166e_k500 <- v166e_kv("R version 5.0.0 (2026-04-01)")
    # 4.4.2 打、4.4.3 跑 —— 这是**实际在用的组合**（打包机 4.4.2，运行时 4.4.3）。
    # 这条要是红了，说明闸门把正常组合也拦了，用户那边直接起不来。
    chk("★★★ 闸门把补丁版当同一版本（4.4.2 打的包必须能在 4.4.3 上跑）",
        identical(v166e_k442, v166e_k443) && identical(v166e_k442, "4.4"),
        sprintf("4.4.2 -> %s ｜ 4.4.3 -> %s", v166e_k442, v166e_k443))
    # ★★★ 这条是**最准**的一条：闸门算出来的必须逐字是 major.minor。
    #       上面那条只说了"补丁版要相等"，这条连"等于什么"都钉住 ——
    #       一条只查"相等/不等"的判据挡不住"值整个错位但恰好自洽"的坏法。
    chk("★★★ 闸门算出来就是 major.minor（4.4.2->4.4 / 4.4.3->4.4 / 4.5.0->4.5 / 5.0.0->5.0）",
        identical(c(v166e_k442, v166e_k443, v166e_k450, v166e_k500),
                  c("4.4", "4.4", "4.5", "5.0")),
        sprintf("实际拿到 %s",
                paste(c(v166e_k442, v166e_k443, v166e_k450, v166e_k500), collapse = " / ")))
    # 跨 minor 必须拦住 —— 这才是这道闸存在的理由。
    chk("★★★ 闸门挡得住跨 minor（4.4 打的包在 4.5 上必须拒绝启动）",
        !identical(v166e_k442, v166e_k450),
        sprintf("4.4.2 -> %s ｜ 4.5.0 -> %s", v166e_k442, v166e_k450))
    chk("★★★ 闸门挡得住跨 major",
        !identical(v166e_k442, v166e_k500),
        sprintf("4.4.2 -> %s ｜ 5.0.0 -> %s", v166e_k442, v166e_k500))
    # ★★★ 防"空转的闸门"：老写法 `paste(v[1:2], collapse=".")` 不滤空串时，
    #       4.4.2 和 4.5.0 都算成 ".4" —— 闸门等于不存在，而上面几条里
    #       "补丁版相等"照样绿、"跨 minor"才红。V16.6 差点就这么发出去。
    # ⚠️ 样本**必须都在 major 4 之内**。第一版这里用的是 4.4.2 / 4.5.0 / 5.0.0，
    #    看着更全，其实**抓不住**：坏写法对 5.0.0 算出来是 ".5"（第 2 个数字
    #    正好是大版本），unique() 长度是 2，判据就绿了 —— 一条专门防假绿的
    #    判据自己假绿。（变异测试里实测：把 key() 换回坏写法，这条是 ✓。）
    #    只留 minor 不同的样本，才真正在问"你看见 minor 了吗"。
    v166e_k460 <- v166e_kv("R version 4.6.1 (2025-06-01)")
    v166e_k490 <- v166e_kv("R version 4.9.9 (2027-01-01)")
    chk("★★★ key() 看得见 minor（同为 major 4，4.4/4.5/4.6/4.9 必须算出不同的键）",
        length(unique(c(v166e_k442, v166e_k450, v166e_k460, v166e_k490))) == 4L,
        sprintf("4.4->%s ｜ 4.5->%s ｜ 4.6->%s ｜ 4.9->%s",
                v166e_k442, v166e_k450, v166e_k460, v166e_k490))
  }
  # 加载器是**薄**的：包里没有 R/ 树，它只能读 rds。⚠️ 先剥注释 ——
  # 这个文件的注释里就写着「Shiny 照常 source 的就是这个 app.R」，不剥会误判。
  v166e_bcode <- v166e_bsrc[!grepl("^\\s*#", v166e_bsrc)]
  chk("★★★ 加载器不去 source 任何 .R（包里根本没有 R/ 树）",
      !any(grepl("source(", v166e_bcode, fixed = TRUE)),
      paste(utils::head(grep("source(", v166e_bcode, value = TRUE, fixed = TRUE), 3),
            collapse = " ｜ "))
  chk("★★ 加载器读的是 app.rds 和 lib.rds 两份",
      any(grepl("app.rds", v166e_bcode, fixed = TRUE)) &&
        any(grepl("lib.rds", v166e_bcode, fixed = TRUE)))
}

# ---- ③ 打包脚本必须能在 macOS 上跑 -------------------------------------
# ⚠️ 必须先剥注释：这些脚本的注释里**原样写着** `grep -oP` / `find -printf` /
#    `python3`（就是在解释为什么不用它们）。不剥的话满屏命中，然后人就会去
#    "修"一段解释性文字。（本仓为这件事栽过三次。）
{
  v166e_gnu <- c("grep -oP", "grep -qP", "grep -U", "-printf", "sort -V", "python3")
  for (v166e_sh in c("desktop/build_windows_bundle.sh",
                     "desktop/build_macos_bundle.sh")) {
    if (!file.exists(v166e_sh)) {
      chk(sprintf("★ 打包脚本 %s 在", basename(v166e_sh)), FALSE)
      next
    }
    v166e_lines <- readLines(v166e_sh, warn = FALSE)
    v166e_code <- v166e_lines[!grepl("^\\s*#", v166e_lines)]
    v166e_hit <- unlist(lapply(v166e_gnu, function(g) {
      h <- grep(g, v166e_code, fixed = TRUE, value = TRUE)
      if (length(h)) sprintf("%s -> %s", g, trimws(h[[1]])) else character(0)
    }))
    # ★★★ 为什么这条重要：`! grep -qP ...` 在 BSD grep 上会以退出码 2（用法
    #       错误）失败，"取反"把**错误**变成了**通过** —— 在 Mac 上打包时
    #       这条会永远绿，哪怕真的混进了中文。所以是"一个都不许有"。
    chk(sprintf("★★★ %s 里没有 GNU 专有写法（BSD grep/find 上会失败，还可能**假绿**）",
                basename(v166e_sh)),
        length(v166e_hit) == 0L,
        paste(utils::head(v166e_hit, 4), collapse = " ｜ "))
  }
  # 两个平台的运行时 R 版本必须同源。不一致的后果不是"包坏了"，而是
  # "关于 Built 的那套推理只在一边成立"，而它是我写在注释里的依据。
  v166e_rver <- function(p) {
    ln <- readLines(p, warn = FALSE)
    m <- regmatches(ln, regexec("DSAPP_RUNTIME_RVER:-([0-9]+\\.[0-9]+\\.[0-9]+)", ln))
    got <- vapply(m, function(x) if (length(x) >= 2L) x[[2]] else NA_character_, "")
    got <- got[!is.na(got)]
    if (length(got)) got[[1]] else NA_character_
  }
  v166e_win_r <- v166e_rver("desktop/build_windows_bundle.sh")
  v166e_mac_r <- v166e_rver("desktop/build_macos_bundle.sh")
  chk("★★★ 两个平台的运行时 R 版本默认值一致（不一致 = 两边的包行为不同源）",
      !is.na(v166e_win_r) && identical(v166e_win_r, v166e_mac_r),
      sprintf("Windows=%s ｜ macOS=%s", v166e_win_r, v166e_mac_r))
  # RMINOR 必须是**从 RVER 推**出来的，不能再写一个字面量 —— 抄一份 = 两份会分家
  # （CRAN 的仓库路径是 contrib/<minor>，写死了就会出现"下了 4.4 的包配 4.5 的
  #   运行时"这种不报错、只在使用时才炸的组合）。
  for (v166e_sh in c("desktop/build_windows_bundle.sh",
                     "desktop/build_macos_bundle.sh")) {
    v166e_code <- readLines(v166e_sh, warn = FALSE)
    v166e_code <- v166e_code[!grepl("^\\s*#", v166e_code)]
    chk(sprintf("★★ %s 的 RMINOR 是从 RVER 推出来的（不是另写一个字面量）",
                basename(v166e_sh)),
        any(grepl('RMINOR="${RVER%.*}"', v166e_code, fixed = TRUE)),
        paste(utils::head(grep("RMINOR=", v166e_code, value = TRUE), 2), collapse = " ｜ "))
  }

  # ★★ 收尾那句「另一种架构怎么打」的提示必须是**算出来的**，不能写死。
  #
  #    原来那行写死的是 `…另跑一次 … <输出目录> x86_64`：打 arm64 包时它对，
  #    打 **x86_64** 包时它变成「要另跑一次 x86_64」—— 自己指自己，而真正缺的
  #    arm64 一个字没提。（V16.6 真跑 x86_64 那次就是这么发现它的。）
  #    ⚠️ **消息写错不会有任何东西变红** —— 自检查的是"包对不对"，不是"提示
  #       对不对"，所以只能靠人读。这里补三条把它钉住。
  {
    v166e_mac <- drop_comment_lines(readLines("desktop/build_macos_bundle.sh",
                                              warn = FALSE))
    v166e_cmd <- grep("build_macos_bundle\\.sh .*<输出目录>", v166e_mac, value = TRUE)
    chk("★★ 收尾那条「另跑一次」的命令真的在脚本里（取不到 = 下面两条在扫空气）",
        length(v166e_cmd) >= 1L,
        paste(utils::head(v166e_cmd, 3L), collapse = " ｜ "))
    chk("★★★ 那条命令里的架构是变量（$OTHER），不是写死的字面量",
        length(v166e_cmd) >= 1L && all(grepl("$OTHER", v166e_cmd, fixed = TRUE)),
        paste(utils::head(v166e_cmd, 3L), collapse = " ｜ "))
    chk("★★★ $OTHER 两个分支给的正好是两种架构（少了分支 = 另一种机器上提示打空串）", {
      m <- regmatches(v166e_mac, regexec('OTHER="([a-z0-9_]+)"', v166e_mac))
      got <- vapply(m, function(x) if (length(x) >= 2L) x[[2]] else NA_character_, "")
      setequal(got[!is.na(got)], c("arm64", "x86_64"))
    }, paste(utils::head(grep("OTHER=", v166e_mac, value = TRUE), 4L), collapse = " ｜ "))
  }
}

# ---- ④ 打包时必须双向核对「清单 ↔ 磁盘」--------------------------------
# ★★★ 这条是**行为**判据，不是查源码里有没有写 setdiff：拿一个迷你仓库真跑
#       一遍 build_bytecode.R，先造"R/ 里有文件没写进清单"（必须失败），
#       再把清单补全（必须成功）。两个方向都要试 —— 只验"会失败"的话，
#       一个**永远失败**的守卫也能全绿。
# ⚠️ 子进程一律 `--no-environ`：Rscript 否则会读 cwd 的 .Renviron，而它
#    **盖掉**继承来的环境变量（本仓栽过：自检的子进程把东西写进了生产库）。
{
  v166e_bc <- normalizePath("desktop/build_bytecode.R", mustWork = FALSE)
  if (!file.exists(v166e_bc)) {
    chk("★★★ desktop/build_bytecode.R 在（打包链的核心）", FALSE)
  } else {
    v166e_t <- file.path(tempdir(), "v166e_mini")
    dir.create(file.path(v166e_t, "R"), recursive = TRUE, showWarnings = FALSE)
    writeLines(c('fa <- function(x) x + 1'), file.path(v166e_t, "R", "a.R"))
    writeLines(c('fb <- function(x) x * 2'), file.path(v166e_t, "R", "b.R"))
    v166e_mkapp <- function(files) {
      writeLines(c(sprintf('files <- c(%s)', files),
                   'app_ui <- "ui"',
                   'server <- function(input, output, session) NULL'),
                 file.path(v166e_t, "app.R"))
    }
    v166e_run <- function() {
      o <- suppressWarnings(system2("Rscript",
             c("--no-environ", shQuote(v166e_bc), shQuote(v166e_t),
               shQuote(file.path(v166e_t, "out"))),
             stdout = TRUE, stderr = TRUE))
      list(status = if (is.null(attr(o, "status"))) 0L else as.integer(attr(o, "status")),
           out = paste(o, collapse = "\n"))
    }
    v166e_mkapp('"a.R"')                       # b.R 故意不写进清单
    v166e_neg <- v166e_run()
    chk("★★★ 磁盘上有、清单里没有的 R/*.R —— 打包必须当场失败（两个方向都要）",
        v166e_neg$status != 0L && grepl("b.R", v166e_neg$out, fixed = TRUE),
        sprintf("退出码 %d，输出末行：%s", v166e_neg$status,
                utils::tail(strsplit(v166e_neg$out, "\n")[[1]], 1)))
    v166e_mkapp('"a.R", "b.R"')                # 补全之后必须能过
    v166e_pos <- v166e_run()
    v166e_pos_ok <- v166e_pos$status == 0L &&
      file.exists(file.path(v166e_t, "out", "lib.rds")) &&
      file.exists(file.path(v166e_t, "out", "app.rds")) &&
      file.exists(file.path(v166e_t, "out", "built_with_R.txt"))
    chk("★★★ 清单补全后同一条链要能跑通（守卫不是「永远失败」）",
        v166e_pos_ok,
        sprintf("退出码 %d，产物：%s", v166e_pos$status,
                paste(basename(list.files(file.path(v166e_t, "out"))), collapse = " ")))
  }
}

# =============================================================================
section("V16.6 item 6：版本号后面的「获取最新版」")
# =============================================================================
# 用户原话：「我的APP后续会发布在这个网址 https://github.com/Biomamba/YCFS_APP，
#          版本号后面加一个『获取最新版』，就用这个链接作为超链接」。
#
# ★★ 这一节是**渲染级**的（`renderTags(dsapp_footer_ui())` 真跑一遍），不是
#    查源码里有没有那几行字。本仓栽过四次的那条：源码对 ≠ 用户看得见 ——
#    页脚是每个页面（含登录页）都画的东西，写错了没人会去看。
{
  v166f_url <- "https://github.com/Biomamba/YCFS_APP"
  v166f_has <- exists("DSAPP_RELEASE_URL", inherits = TRUE)
  chk("★★★ R/config.R 里的 DSAPP_RELEASE_URL 就是用户给的那个仓库",
      v166f_has && identical(get("DSAPP_RELEASE_URL", inherits = TRUE), v166f_url),
      sprintf("实际：%s", if (v166f_has) get("DSAPP_RELEASE_URL", inherits = TRUE)
              else "（没有这个常量）"))
  chk("★ 发行地址是 https（http 会被浏览器标成不安全内容）",
      v166f_has && grepl("^https://", get("DSAPP_RELEASE_URL", inherits = TRUE)))

  # ---- 渲染 -----------------------------------------------------------------
  v166f_h <- paste(as.character(htmltools::renderTags(dsapp_footer_ui())$html),
                   collapse = "")
  chk("★★★ 页脚里真的有这个链接，href 就是那个仓库（渲染级）",
      grepl(sprintf('href="%s"', v166f_url), v166f_h, fixed = TRUE),
      substr(v166f_h, 1L, 240L))
  chk("★★★ 文案是用户指定的「获取最新版」",
      grepl("获取最新版", v166f_h, fixed = TRUE))
  chk("★★ 新窗口打开 + rel=noopener noreferrer（旁边那条注释说了这不是摆设）",
      grepl('target="_blank"', v166f_h, fixed = TRUE) &&
        grepl('rel="noopener noreferrer"', v166f_h, fixed = TRUE))
  chk("★★★ 位置：链接在版本号**后面**（用户指定的就是版本号后面）", {
    a <- regexpr("dsapp-footer-ver", v166f_h, fixed = TRUE)
    b <- regexpr("dsapp-footer-getver", v166f_h, fixed = TRUE)
    a > 0L && b > a
  })
  chk("★ 窄屏那段短文案也在（只留长的那段 = 窄屏没有可点的字）",
      grepl("dsapp-footer-getver-short", v166f_h, fixed = TRUE) &&
        grepl("最新版", v166f_h, fixed = TRUE))

  # ---- CSS ------------------------------------------------------------------
  # ⚠️⚠️ 扫 CSS 和扫 R 一样，**必须先剥注释**（拿 `.R` 那套 `^\\s*#` 不行 ——
  #    CSS 是 `/* ... */`，而且可以跨行）。这一节写第一版时就是没剥，于是
  #    "只许 skins.css 定义 --dsapp-footer-h" 那条**当场红了**：红的原因不是
  #    代码错了，是我在 app.css 的注释里**引用了**那句被删掉的声明
  #    （`这里原来也写了一份 :root { --dsapp-footer-h: 2.6rem; }`）。
  #    本仓的"扫源码前先剥注释"栽过三次，这是第四次，只是换了个语言。
  #    ★★ 这一节最初自己写了个 `gsub("/\\*.*?\\*/", ..., perl = TRUE)`，两次没剥掉：
  #    ① `gsub` 是**逐元素**的，而 CSS 注释可以跨行 —— 按行传进去等于一行都剥不掉。
  #    ② 就算先 paste 成整块还是剥不掉：`perl = TRUE` 时 `.` **默认不匹配换行**，
  #       所以那个模式只能匹配**写在同一行里**的注释。实测 `"a /*x*/ b"` 剥得掉、
  #       `"a /*x\ny*/ b"` 原样留着 —— 于是断言照旧红，而"我明明剥了注释"这句
  #       话看上去完全成立。危险在于它在"注释恰好没跨行"时**表现得完全正常**。
  #    结论不是"记得加 (?s)"，而是：**别再写第四份剥注释**（本仓已有 `strip_comments`
  #    和这个 `strip_js_comments`）。app.css 的剥完版本上面（6011 行）本来就算好了。
  # ⚠️ 再把所有空白压成一个空格：CSS 里那几行是**对齐着写的**（`-long  {`
  #    两个空格），照原样比会在改对齐时莫名其妙变红。
  v166f_css <- gsub("\\s+", " ", css_code)
  # ⚠️ 抠规则体走现成的 `css_rule()`（它按花括号配对）—— 别自己写"从选择器到
  #    下一个 `}`"，那种写法在规则体里有嵌套（媒体查询、`:is()`）时会截错。
  v166f_base <- css_rule(".dsapp-footer-getver")
  chk("★★★ CSS 里有 .dsapp-footer-getver 且带 white-space: nowrap（没它链接会从中间断开 = 页脚折两行 = 盖住页面底部）",
      grepl("white-space: nowrap", v166f_base, fixed = TRUE),
      if (nzchar(v166f_base)) v166f_base else "（没有这条规则）")
  # 长短两段二选一：默认藏短的，窄屏那条 @media 里反过来。两半缺一条，
  # 症状都是"某个宽度下文案不对"（而不是报错）。
  # ⚠️ 抠这一块**必须按花括号配对**（`dsapp_block_at`），不能"从 @media 到下一个
  #    @media"：第一版就是那么写的，变异测试时打出窗口内容才发现它**越过了媒体
  #    查询自己的 `}`**，把后面一串顶层规则（`.dsapp-footer-gpu { … }`）也圈了进来。
  #    后果不是报错，是这条断言**变松**：把那对长短规则整个搬到媒体查询**外面**
  #    （= 宽屏也被换成短文案，真的坏），窗口里照样找得到它，断言照样绿。
  v166f_mq <- dsapp_block_at(v166f_css, regexpr(
    "@media \\(max-width: 767\\.98px\\)\\s*\\{", v166f_css))
  chk("★★★ 窄屏那条 @media 里切的是「获取最新版」这一对（不切 = 窄屏照样可能折两行）",
      grepl(".dsapp-footer-getver-long { display: none; }", v166f_mq, fixed = TRUE) &&
        grepl(".dsapp-footer-getver-short { display: inline; }", v166f_mq, fixed = TRUE),
      substr(trimws(v166f_mq), 1L, 260L))

  # ---- ★★★ 页脚高度那个变量「定义在哪个文件里」-----------------------------
  # V16.6 实打实栽在这里：`--dsapp-footer-h` 在 app.css 和 skins.css 里**各定义了
  # 一份**，而 skins.css **后加载**，同权重后写的赢 —— app.css 那份一直是**死的**。
  # 于是在 app.css 里加了一条窄屏 @media 覆盖，量出来 360px 下 padding-bottom
  # 照旧 41.6px（探针红了，但红得完全指不到原因，查了半天才想到加载顺序）。
  # 现在两份合成一份（只在 skins.css），并钉住"只许它定义"。
  {
    v166f_cssf <- list.files("www", "[.]css$", full.names = TRUE)
    v166f_owner <- v166f_cssf[vapply(v166f_cssf, function(f)
      grepl("--dsapp-footer-h:",
            strip_js_comments(paste(readLines(f, warn = FALSE), collapse = "\n")),
            fixed = TRUE),
      logical(1))]
    chk("★★★ --dsapp-footer-h 只由 skins.css 定义（在 app.css 里定义 = 被盖掉、静默无效）",
        identical(sort(basename(v166f_owner)), "skins.css"),
        if (length(v166f_owner))
          sprintf("定义在：%s", paste(basename(v166f_owner), collapse = ", "))
        else "全仓没有任何一处定义它（那就更不对了）")
    chk("★ 而且『看得见』这个变量确实有定义（上面那条不是靠扫空气绿掉的）",
        length(v166f_owner) >= 1L && "skins.css" %in% basename(v166f_owner))
    v166f_skin <- strip_js_comments(paste(readLines("www/skins.css", warn = FALSE),
                                         collapse = "\n"))
    chk("★★★ 窄屏放大预留高度那条覆盖写在 skins.css（写在 app.css = 被盖掉）",
        grepl(":root { --dsapp-footer-h: 4.4rem; }", v166f_skin, fixed = TRUE),
        "（手机竖屏上页脚折两行，预留高度不放大就会压住页面内容）")
  }

  # ---- 一处定义 -------------------------------------------------------------
  # 地址抄成两份的后果不是报错，是**改了一处另一处还绿着**，而它错的表现是
  # 用户点进一个 404（或者更糟：别人的仓库）。所以钉"只有 config.R 里有它"。
  # ⚠️ 这个 loop 写在 chk **外面**：chk 的两个参数都是惰性求值的，把 `hits`
  #    留在第一个参数的花括号里、第二个参数再去读它，就是赌 chk 先求哪一个。
  v166f_hits <- character(0)
  for (v166f_f in list.files("R", "[.]R$", full.names = TRUE)) {
    v166f_ln <- drop_comment_lines(readLines(v166f_f, warn = FALSE))
    if (any(grepl("github.com/Biomamba/YCFS_APP", v166f_ln, fixed = TRUE)))
      v166f_hits <- c(v166f_hits, v166f_f)
  }
  chk("★★ 这个地址在 R/ 下只写在 config.R 一处（别处再抄一份 = 两份会分家）",
      identical(sort(v166f_hits), "R/config.R"),
      sprintf("出现过的文件：%s", paste(v166f_hits, collapse = ", ")))
}

# =============================================================================
section("V15 item 8：论坛（公共段同步）")
# =============================================================================
# 用户原话：「加一个论坛页面，用户能交流自己使用过程中的经验或遇到的问题。
# 你需要考虑好同步问题，现有的账户体系是靠什么为枢纽进行同步的？」
#
# 最后那句是**考据题**，答案：枢纽是 `users.email`（归一化小写）那一列，
# 不是 users.id（AUTOINCREMENT，每台机器各自从 1 开始，撞号）。下面第一组
# 断言就是把这件事钉死 —— 论坛整层都建在它上面，它要是错了，论坛会以
# "跨机认不出同一个人"的形式坏掉，而且**一句报错都没有**。
#
# ⚠️ 这一段故意**不放进子进程**：它不需要两个 data_root 来回切（那是同步
#    那一节的事），所有断言都在**同一个库**上做完。真正跨库的那几条
#    （收端按 email 认人、LWW、删除传播）走的是 `dsapp_forum_apply()` ——
#    它收的就是一个 list，不需要第二个库也能构造出来。
#
# ⚠️ 每条断言都冲着"**不报错、数据不对**"这个形态去。论坛这一层的失败方式
#    全是这一种：软删没发出去、水位推过头、被隐藏的行从列表里消失。
{
  v15_td <- file.path(tempdir(), "v15_forum_selftest")
  unlink(v15_td, recursive = TRUE)
  dir.create(v15_td, showWarnings = FALSE, recursive = TRUE)
  old_root <- Sys.getenv("DSAPP_DATA_ROOT", unset = NA)
  Sys.setenv(DSAPP_DATA_ROOT = v15_td)
  # ⚠️⚠️ 这里原来挂的是 `on.exit({...}, add = TRUE)`，想表达"块结束就还原"。
  #    **它从来没执行过。** 顶层 `{ }` 不是一个函数帧，R 会老老实实收下这个
  #    on.exit 然后永远不跑它 —— 两行就能证：块里 `Sys.setenv(FOO="inside")`
  #    加一句 on.exit 还原，块外读回来还是 "inside"（2026-09-28 实测）。
  #
  #    代价在这一天现形：本节把 DSAPP_DATA_ROOT 指到 v15_td，第 (h) 段又指到
  #    v15_apply_td，两次"还原"都没发生。于是跑到 Test_V15.2 那一节时，
  #    环境变量指的是 /tmp/.../v15_forum_apply，而自检开头建的全局 `cfg`
  #    指的是 tmp —— **同一个进程里同时活着两个库**：
  #    `dsapp_db(cfg)` 打开 tmp 那个，`dsapp_user_create()` 内部现取
  #    `dsapp_config()` 打开另一个，账号建在 A、查在 B，查回来是 NULL，
  #    最后红的是"ref 去重没生效"，和真正的原因隔了十万八千里。
  #
  #    所以还原改成**显式写在块的末尾**（见本节 `}` 之前那几行），和 V14 GPU
  #    那一节同一个写法 —— 那里早就是这么做的，理由写在 13930 行附近。
  v15_cfg <- dsapp_config()
  dsapp_init_dirs(v15_cfg)
  v15_con <- dsapp_db(v15_cfg)

  # ---- (a) 枢纽是 email，不是 id ----------------------------------------
  #
  # 这一组查的是**源码**而不是行为：行为上"两个库的 7 号是两个人"要造两个库
  # 才看得出来（同步那一节已经验过）。这里钉的是"论坛这一层是不是也照这个
  # 规矩写的"—— 论坛有三处会写"这个人是谁"，任何一处写成本地 id 都是静默的
  # 跨机错认。
  # ⚠️⚠️ 扫源码的这几条**必须剥掉整行注释**再查，而且这里查的还多半是
  #     "**不许出现**某个写法" —— 那种写法往往正好写在解释"为什么不能这么写"
  #     的注释里。这一版连踩两次：`p.status = 'ok'`（我自己的注释里就写了
  #     它）和 `state$is_admin`（mod_forum.R 里有一整段在说别这么写）。
  #     症状是同一条断言永远红，而红得毫无信息量。
  #     同一个教训在下面 sync.R 的 `.dsapp_sync_user_ensure` 那条上也写着。
  v15_forum_src <- paste(drop_comment_lines(readLines("R/forum.R", warn = FALSE)),
                         collapse = "\n")
  v15_mod_src   <- paste(drop_comment_lines(readLines("R/mod_forum.R", warn = FALSE)),
                         collapse = "\n")
  chk("★★ 论坛认账号走的是 email（和 .dsapp_sync_user_find 那把尺子同源）", {
    # 写完写全的那个函数体里，必须出现 lower/tolower 的归一化
    i <- regexpr("dsapp_forum_author <- function", v15_forum_src, fixed = TRUE)
    i > 0 && grepl("tolower(", substr(v15_forum_src, i, i + 400), fixed = TRUE)
  })
  chk("★★ 论坛的跨机身份里**没有** users.id 这一列（author_uid 不过网）", {
    # 取包那三段的 SELECT：不许出现 author_uid / user_id。
    # ⚠️ 段的范围掐在 collect 到 apply 之间（理由见下面 views 那条）。
    i <- regexpr("dsapp_forum_collect <- function", v15_forum_src, fixed = TRUE)
    j <- regexpr("dsapp_forum_apply <- function", v15_forum_src, fixed = TRUE)
    blk <- if (i > 0 && j > i) substr(v15_forum_src, i, j) else ""
    nzchar(blk) && !grepl("author_uid", blk, fixed = TRUE) &&
      !grepl("user_id", blk, fixed = TRUE)
  })
  chk("★★★ 三张表里没有一处本地外键指向 users（id 会撞号，指过去就是认错人）", {
    # forum_threads / forum_posts / forum_marks 的建表语句里不许有 REFERENCES
    i <- regexpr("dsapp_db_schema_forum <- function", v15_forum_src, fixed = TRUE)
    blk <- if (i > 0) substr(v15_forum_src, i, i + 6000) else ""
    nzchar(blk) && !grepl("REFERENCES", blk, fixed = TRUE)
  })

  # ---- (b) 建表 ----------------------------------------------------------
  v15_tb <- DBI::dbGetQuery(v15_con,
    "SELECT name FROM sqlite_master WHERE type='table'")$name
  chk("★ schema v12：论坛三张表都建出来了",
      all(c("forum_threads", "forum_posts", "forum_marks") %in% v15_tb),
      paste(setdiff(c("forum_threads", "forum_posts", "forum_marks"),
                    v15_tb), collapse = ","))
  chk("★★★ (origin_node, origin_id) 上有 UNIQUE 索引（幂等的**全部**依据）", {
    ix <- DBI::dbGetQuery(v15_con,
      "SELECT name FROM sqlite_master WHERE type='index'")$name
    all(c("idx_forum_th_oid", "idx_forum_po_oid") %in% ix)
  })
  chk("★ 那个索引真的是 UNIQUE（不是普通索引 —— 普通索引拦不住重复投递）", {
    uq <- v15_con_uniq <- tryCatch(DBI::dbGetQuery(v15_con,
      "SELECT name, sql FROM sqlite_master WHERE type='index'
        AND name IN ('idx_forum_th_oid','idx_forum_po_oid')"),
      error = function(e) NULL)
    !is.null(uq) && nrow(uq) == 2 &&
      all(grepl("UNIQUE", toupper(uq$sql), fixed = TRUE))
  })
  chk("★ 楼层索引在（显示路径上每开一条帖都要跑，缺了就是全表扫）",
      "idx_forum_po_thread" %in% DBI::dbGetQuery(v15_con,
        "SELECT name FROM sqlite_master WHERE type='index'")$name)
  chk("★★ sync_state 多了 in_forum / out_forum 两列（论坛的水位要独立）", {
    cn <- DBI::dbGetQuery(v15_con, "PRAGMA table_info(sync_state)")$name
    all(c("in_forum", "out_forum") %in% cn)
  })
  # ⚠️ 这条**不能**写成"读出来的 in_at 和 in_forum 不相等" —— 两个都是空串时
  #    它恒为假（第一版就是这么红的）。要真的写两组不同的值再读回来。
  chk("★★★ 论坛水位和会话水位是**两列**（共用一列的话，论坛会把会话的挤没）", {
    dsapp_sync_state_set("v15probe", con = v15_con,
                         in_at = "2026-01-01 00:00:00",
                         in_forum = "2026-06-06 06:06:06")
    z <- dsapp_sync_state_get("v15probe", con = v15_con)
    identical(as.character(z$in_at), "2026-01-01 00:00:00") &&
      identical(as.character(z$in_forum), "2026-06-06 06:06:06")
  })

  # ---- (c) 发帖 / 回复 ---------------------------------------------------
  # ⚠️ 手机号和方向都**必须**给：dsapp_user_validate() 里 `nchar(phone) < 5`
  #    和"请填研究方向"都是硬校验，留空的话 dsapp_user_create() 返回 ok=FALSE
  #    且**一行都不建** —— 于是下面几十条断言全在 NULL 上跑（红的是"发帖
  #    成功"，报的却是"认不出当前账号"，离现场很远）。这和 V13.1 item 7
  #    那个"密码突然必填"是同一类坑，连症状都一模一样。
  v15_u1 <- mkuser("论坛甲", "v15_a@example.com", "13900000001", "RNA", v15_con)
  v15_u2 <- mkuser("论坛乙", "v15_b@example.com", "13900000002", "RNA", v15_con)
  # ⚠️ `dsapp_user_create()` 的返回值里**已经带了** user 那一行（`$user`），
  #    没有 `dsapp_user_get()` 这个函数 —— 建号失败时 `$user` 是 NULL，
  #    于是下面几十条断言全在 NULL 上跑，有的碰巧还是绿的。所以先钉死它。
  chk("★ 两个账号建出来了（建不出来下面全在 NULL 上跑）",
      isTRUE(v15_u1$ok) && isTRUE(v15_u2$ok) &&
        !is.null(v15_u1$user) && !is.null(v15_u2$user),
      paste(v15_u1$msg %||% "", v15_u2$msg %||% ""))
  v15_ua <- v15_u1$user
  v15_ub <- v15_u2$user
  chk("★ 两张账号的邮箱归一成了小写（论坛那一层全靠它认人）",
      identical(as.character(v15_ua$email), "v15_a@example.com") &&
        identical(as.character(v15_ub$email), "v15_b@example.com"),
      paste(v15_ua$email, v15_ub$email))

  v15_t1 <- dsapp_forum_thread_new("GC 内容物怎么导出", "如题，想导出成 csv。",
                                   category = "ask", tags = "报错, R语言,报错",
                                   user = v15_ua, cfg = v15_cfg, con = v15_con)
  chk("发帖成功", isTRUE(v15_t1$ok), v15_t1$msg %||% "")
  chk("★★ origin_id 写完是**本地 id**（两步写法的第二步跑到了）", {
    z <- DBI::dbGetQuery(v15_con,
      "SELECT origin_id, id FROM forum_threads WHERE id = ?",
      params = list(as.integer(v15_t1$id)))
    nrow(z) == 1 && nzchar(z$origin_id[1]) &&
      identical(as.character(z$origin_id[1]), as.character(z$id[1]))
  })
  chk("★★ 标签去重了（同一条写两遍只留一个）", {
    z <- DBI::dbGetQuery(v15_con,
      "SELECT tags FROM forum_threads WHERE id = ?",
      params = list(as.integer(v15_t1$id)))$tags[1]
    identical(z, "报错,R语言")
  }, DBI::dbGetQuery(v15_con, "SELECT tags FROM forum_threads")$tags)
  chk("★ 新帖的 views 是 0、status 是 open",
      identical(as.integer(DBI::dbGetQuery(v15_con,
        "SELECT views, status FROM forum_threads WHERE id = ?",
        params = list(as.integer(v15_t1$id)))$views[1]), 0L))

  # ★ 限流：紧接着再发一条应当被挡住
  v15_t2 <- dsapp_forum_thread_new("紧接着再发一条", "应当被限流。",
                                   user = v15_ua, cfg = v15_cfg, con = v15_con)
  chk("★ 10 秒内连着发第二条被挡下来（按住回车刷屏防不住的话，论坛就没法看了）",
      !isTRUE(v15_t2$ok) && grepl("太快", v15_t2$msg %||% ""), v15_t2$msg %||% "")

  chk("★ 公告只有管理员能发（界面不给选项是体验，这里才是规则）", {
    r <- dsapp_forum_thread_new("一条公告", "正文。", category = "notice",
                                user = v15_ua, is_admin = FALSE,
                                cfg = v15_cfg, con = v15_con)
    !isTRUE(r$ok) && grepl("公告", r$msg %||% "")
  })
  chk("★ 空标题 / 空正文都挡得住", {
    r1 <- dsapp_forum_thread_new("   ", "正文。", user = v15_ua,
                                 cfg = v15_cfg, con = v15_con)
    r2 <- dsapp_forum_thread_new("标题", "\n\r\n ", user = v15_ua,
                                 cfg = v15_cfg, con = v15_con)
    !isTRUE(r1$ok) && !isTRUE(r2$ok)
  })

  # ---- (d) 楼层的身份是帖子的全局身份，不是本地 id ------------------------
  v15_key <- dsapp_forum_key(
    DBI::dbGetQuery(v15_con, "SELECT origin_node FROM forum_threads WHERE id = ?",
                    params = list(as.integer(v15_t1$id)))$origin_node[1],
    as.character(v15_t1$id))
  chk("★ 帖子的 key 拼得出来（拼不出来下面几条是空转）",
      !is.na(v15_key) && grepl(":", v15_key, fixed = TRUE), v15_key)
  v15kk <- dsapp_forum_unkey(v15_key)
  # 限流是按人的，换个账号发回复
  v15_p1 <- dsapp_forum_post_new(v15kk[["node"]], v15kk[["id"]],
                                 "我也想知道。", user = v15_ub,
                                 cfg = v15_cfg, con = v15_con)
  chk("回复成功", isTRUE(v15_p1$ok), v15_p1$msg %||% "")
  chk("★★ 回复挂的是帖子的**全局身份**（存的是 origin 那两列，不是本地 id）", {
    z <- DBI::dbGetQuery(v15_con,
      "SELECT thread_onode, thread_oid FROM forum_posts WHERE id = ?",
      params = list(as.integer(v15_p1$id)))
    nrow(z) == 1 && identical(z$thread_onode[1], v15kk[["node"]]) &&
      identical(z$thread_oid[1], v15kk[["id"]])
  })
  chk("★★★ 回复先到、帖子后到也挂得上（挂靠不看帖子在不在，这就是不用外键的全部理由）", {
    # 直接 apply 一个"帖子还没来"的回复行
    r <- dsapp_forum_apply(
      list(posts = list(list(origin_node = "n_other_node", origin_id = "77",
                             thread_onode = "n_never_seen", thread_oid = "9",
