    identical(DBI::dbGetQuery(v15_con,
      "SELECT body FROM forum_threads WHERE id = ?",
      params = list(as.integer(v15_t1$id)))$body[1], "改过的正文。")
  })

  # ---- (e) 浏览不过网 ----------------------------------------------------
  chk("★★★ 浏览 +1 **不碰 updated_at**（碰了的话「有人看了一眼」= 一次全站同步）", {
    b4 <- DBI::dbGetQuery(v15_con,
      "SELECT views, updated_at FROM forum_threads WHERE id = ?",
      params = list(as.integer(v15_t1$id)))
    dsapp_forum_view(v15kk[["node"]], v15kk[["id"]], con = v15_con)
    af <- DBI::dbGetQuery(v15_con,
      "SELECT views, updated_at FROM forum_threads WHERE id = ?",
      params = list(as.integer(v15_t1$id)))
    as.integer(af$views[1]) == as.integer(b4$views[1]) + 1L &&
      identical(af$updated_at[1], b4$updated_at[1])
  })
  # ⚠️ 段的范围必须掐在 `dsapp_forum_collect` 到 `dsapp_forum_apply` **之间**。
  #    掐到 `dsapp_forum_section_high` 的话会把 apply 也圈进来，而 apply 的
  #    INSERT 列表里**有** views（落地时写 0）—— 于是这条断言恒红，而红的
  #    理由跟"views 进没进包"毫无关系（第一版就是这么错的）。
  chk("★★ views 也不在收集段的列里（不进包，对端也不会因此重发）", {
    i <- regexpr("dsapp_forum_collect <- function", v15_forum_src, fixed = TRUE)
    j <- regexpr("dsapp_forum_apply <- function", v15_forum_src, fixed = TRUE)
    blk <- if (i > 0 && j > i) substr(v15_forum_src, i, j) else ""
    nzchar(blk) && !grepl("views", blk, fixed = TRUE)
  })

