    col2 <- dsapp_forum_collect(col$high_water, con = v15_con)
    key <- function(sec) c(
      vapply(sec$threads, function(x) paste0(x$origin_node, ":", x$origin_id), ""),
      vapply(sec$posts,   function(x) paste0(x$origin_node, ":", x$origin_id), ""))
    k1 <- key(col); k2 <- key(col2)
    # col2 必须是 col 的子集（多出来的就是漏水，少的是正常的 —— 水位挡住了）
    all(k2 %in% k1) && length(k1) > 0
  })
  chk("★★★ 截断时**水位不推进**（推进了的话剩下那些永远发不出去，且不报错）", {
