  # ---- (i) 可见性 / 列表 ------------------------------------------------
  chk("★★ 纯函数和 SQL 是同一件事的两份表达（必须一起改）", {
    # 隐藏的：作者看得见、管理员看得见、别人看不见
    dsapp_forum_visible("hidden", is_mod = FALSE, is_mine = FALSE) == FALSE &&
