  chk("★★ LIKE 的通配符转义了（搜 `100%` 不该返回全部帖子）", {
    i <- regexpr("dsapp_forum_list <- function", v15_forum_src, fixed = TRUE)
    blk <- if (i > 0) substr(v15_forum_src, i, i + 3500) else ""
    nzchar(blk) && grepl("ESCAPE", blk, fixed = TRUE)
  })
  chk("★ 排序键每一条都带 origin_node, origin_id 兜底（两端要算出同一个顺序）", {
    i <- regexpr("ord <- switch(sort", v15_forum_src, fixed = TRUE)
    blk <- if (i > 0) substr(v15_forum_src, i, i + 900) else ""
    nzchar(blk) && grepl("t.origin_node, t.origin_id", blk, fixed = TRUE)
  })
  chk("★ 帖子取回复的排序也带那两列兜底（楼层号两端必须一致）", {
    i <- regexpr("dsapp_forum_posts <- function", v15_forum_src, fixed = TRUE)
    j <- regexpr("dsapp_forum_list <- function", v15_forum_src, fixed = TRUE)
    blk <- if (i > 0 && j > i) substr(v15_forum_src, i, j) else ""
    nzchar(blk) &&
      grepl("ORDER BY p.created_at, p.origin_node, p.origin_id", blk, fixed = TRUE)
  })
  # ★★★ 这一条是"楼层号"这个概念的**全部依据**：行数必须对谁都一样。
  #     按状态过滤行 = 每个人的楼层号都不一样，而"你看 3 楼说的"就成了
  #     每屏一个的局部编号 —— 它读起来完全合理，不报错，只在两个人对不上
  #     话的时候才被发现。写这一页时**真的就是过滤的**（`p.status = 'ok' OR
  #     作者 OR 管理员`），是写浏览器探针时顺着"乙该看到几层"算出来的。
  chk("★★★ 取回复时**不过滤 status**（行数=楼层号，谁看都一样）", {
    i <- regexpr("dsapp_forum_posts <- function", v15_forum_src, fixed = TRUE)
    j <- regexpr("dsapp_forum_list <- function", v15_forum_src, fixed = TRUE)
    blk <- if (i > 0 && j > i) substr(v15_forum_src, i, j) else ""
    nzchar(blk) && !grepl("p.status = 'ok'", blk, fixed = TRUE)
  })
  # ⚠️⚠️ 这一条必须用 **v15_acon**（section (h) 换了 data_root 之后那个连接），
  #     不能用 v15_con。`dsapp_db()` 是**按 db_path 缓存的进程单例**：换根
  #     的时候它会把上一个连接 `dbDisconnect` 掉（R/db.R:114-118）。拿着那个
  #     已经死掉的对象继续用**不会**报"连接失效"——它报成业务错误
  #     （"发帖失败：Invalid or closed connection"），看起来像论坛坏了。
  # ⚠️ 发帖/回帖有 10 秒限流（DSAPP_FORUM_COOLDOWN，按 author_email 在两张表
  #     里的 MAX(created_at) 算）。这一条要连写 4 行，所以每写一行之前先把
  #     **已有行**的时间往回拨 5 分钟。限流是给真人用的，断言不该在这儿
  #     sleep 40 秒；副作用是三层楼时间戳一样 —— 那正好把排序里的
  #     `origin_id` 兜底也顺带验了。
  v15_age_forum <- function() {
    DBI::dbExecute(v15_acon,
      "UPDATE forum_threads SET created_at = datetime('now', '-5 minutes')")
    DBI::dbExecute(v15_acon,
      "UPDATE forum_posts SET created_at = datetime('now', '-5 minutes')")
    invisible(TRUE)
  }
  chk("★★★ 拿真的跑一遍：已删的楼层**别人也数得到**（否则号会错位）", {
    # 一条帖 + 三层楼，删掉中间那层，然后从**别人的视角**取
    v15_age_forum()
    r <- dsapp_forum_thread_new("楼层号一致性", "正文", user = v15_ua,
                                cfg = v15_acfg, con = v15_acon)
    if (!isTRUE(r$ok)) FALSE else {
      nd <- DBI::dbGetQuery(v15_acon,
        "SELECT origin_node FROM forum_threads WHERE id = ?",
        params = list(as.integer(r$id)))$origin_node[1]
      kk2 <- dsapp_forum_unkey(dsapp_forum_key(nd, as.character(r$id)))
      mkfloor <- function(body, who) {
        v15_age_forum()
        dsapp_forum_post_new(kk2[["node"]], kk2[["id"]], body,
                             user = who, cfg = v15_acfg, con = v15_acon)
      }
      # 三层楼**必须都写进去**才算数：限流要是没绕过，这里会静默少几行，
      # 而少行和"号错了"在行数上长得一模一样 —— 分开报才好查。
      floors <- list(mkfloor("第一层", v15_ub),
                     mkfloor("第二层", v15_ua),
                     mkfloor("第三层", v15_ub))
      if (!all(vapply(floors, function(z) isTRUE(z$ok), logical(1)))) FALSE else {
        pk <- DBI::dbGetQuery(v15_acon,
          "SELECT origin_node, origin_id FROM forum_posts WHERE body = '第二层'")
        dsapp_forum_post_status(pk$origin_node[1], pk$origin_id[1], "deleted",
                                user = v15_ua, con = v15_acon)
        # 甲（删人的那个）和乙（旁人）看到的行数必须一样
        n_a <- nrow(dsapp_forum_posts(kk2[["node"]], kk2[["id"]],
                                      viewer_email = "v15_a@example.com",
                                      con = v15_acon))
        n_b <- nrow(dsapp_forum_posts(kk2[["node"]], kk2[["id"]],
                                      viewer_email = "v15_b@example.com",
                                      con = v15_acon))
        n_a == 3L && n_b == 3L
      }
    }
  })

  # ---- (j) 界面安全面 ----------------------------------------------------
  chk("★★★ 论坛正文一律走 dsapp_md_html（全应用唯一的 XSS 面就在这里）", {
    # mod_forum.R 里不许出现裸 HTML( 拼接用户文本；每一处 HTML( 都必须是
    # dsapp_md_html(...) 的返回值
    hs <- gregexpr("HTML\\(", v15_mod_src)[[1]]
    hs <- hs[hs > 0]
    length(hs) >= 2 &&
      all(vapply(hs, function(i)
        grepl("dsapp_md_html", substr(v15_mod_src, i, i + 60), fixed = TRUE),
        logical(1)))
  })
  chk("★★★ 转义 + 链接白名单真的拦得住（拿真函数跑一遍，不是看源码）", {
    h <- dsapp_md_html("<script>alert(1)</script>\n\n[点我](javascript:alert(2))")
    !grepl("<script", h, fixed = TRUE) &&
      !grepl("javascript:", h, fixed = TRUE)
  })
  # ⚠️ 查 `state$is_admin` **必须先剥注释** —— 那个写法本身就出现在解释
  #    "为什么不能这么写"的注释里，不剥的话这条永远红，而且红得毫无信息量
  #    （同一个教训在下面 sync.R 的 .dsapp_sync_user_ensure 那条上写着）。
  chk("★★ 管理员判据是 dsapp_user_is_admin（state 里**没有** is_admin 这个字段）", {
    code <- drop_comment_lines(readLines("R/mod_forum.R", warn = FALSE))
    any(grepl("dsapp_user_is_admin(state$user)", code, fixed = TRUE)) &&
      !any(grepl("state$is_admin", code, fixed = TRUE))
  })
  chk("★★ 行内动作走**一个**共用 input（每行注册一个 observer 会留下永不回收的）", {
    grepl('ns("act")', v15_mod_src, fixed = TRUE) &&
      length(gregexpr("observeEvent(input$act", v15_mod_src, fixed = TRUE)[[1]]) == 1L
  })
  chk("★★★ 搜索框防抖了（不防抖的话每敲一个字重画整页）",
      grepl("debounce(", v15_mod_src, fixed = TRUE))
  chk("★ 破坏性动作的确认框**不用** easyClose（点旁边就关掉的话，用户分不出点没点中）", {
    i <- regexpr('identical(act, "del")', v15_mod_src, fixed = TRUE)
    blk <- if (i > 0) substr(v15_mod_src, i, i + 900) else ""
    nzchar(blk) && grepl("easyClose = FALSE", blk, fixed = TRUE)
  })
  # ⚠️ 这条**一直是假绿**，剥注释才露出来：它查的 `该回复已被删除` 只存在于
  #    mod_forum.R 的**头部注释**里（"画成「该回复已被删除」"），代码里真正
  #    渲染的是 `（该回复已删除）`。也就是说它验的是我的设计说明，不是实现。
  # ⚠️ 剥完注释后这条**只能做源码级**确认：占位块在、而且楼层 div 本身是
  #    按 status 加 `is-gone` 类**照样渲染**的（不是整层被 if 抽掉）。
  #    "删了之后楼下号没动"这件事源码扫不出来，归浏览器探针
  #    tests/ui_v15/probe_v15.py 第 5 组；那边是真删真读。
  chk("★★★ 软删的楼层在列表里保留占位（抽掉的话楼下楼层号会变，「5 楼说的」就指错了）", {
    i <- regexpr("dsapp-forum-floor-gone", v15_mod_src, fixed = TRUE)
    blk <- if (i > 0) substr(v15_mod_src, i, i + 80) else ""
    nzchar(blk) && grepl("已删除", blk, fixed = TRUE) &&
      grepl('if (deleted || hidden) "is-gone" else ""', v15_mod_src, fixed = TRUE)
  })
  chk("★★ 楼层号用「有没有 reply_to_oid」判顶楼，**不是**查父层在不在", {
    i <- regexpr("top <- which", v15_mod_src, fixed = TRUE)
    blk <- if (i > 0) substr(v15_mod_src, i, i + 200) else ""
    nzchar(blk) && grepl("reply_to_oid", blk, fixed = TRUE)
  })
  # ★★★ 这三条是**浏览器探针抓出来的那个 bug**的源码级哨兵。
  #     详情视图当时没读 bump()，于是：库里写进去了（自检那条
  #     `dsapp_forum_mark()` 的断言照样绿），页面上按钮一个字都不变。
  #     "谁在什么时候重画"这件事自检看不见，但"有没有建立那个依赖"看得见。
  chk("★★★ 详情视图**也**读 bump()（不读的话点按钮/发回复页面上毫无反应）", {
    i <- regexpr("detail_view <- function", v15_mod_src, fixed = TRUE)
    j <- regexpr("output$body <- renderUI", v15_mod_src, fixed = TRUE)
    blk <- if (i > 0 && j > i) substr(v15_mod_src, i, j) else ""
    nzchar(blk) && grepl("bump()", blk, fixed = TRUE)
  })
  chk("★★ 详情**故意不**读 tick()（读了的话用户正在打的回复会每 60 秒被冲掉）", {
    i <- regexpr("detail_view <- function", v15_mod_src, fixed = TRUE)
    j <- regexpr("output$body <- renderUI", v15_mod_src, fixed = TRUE)
    blk <- if (i > 0 && j > i) substr(v15_mod_src, i, j) else ""
    nzchar(blk) && !grepl("tick()", blk, fixed = TRUE)
  })
  chk("★★ 回复框的草稿读的时候 isolate（不 isolate 就每敲一个字重画一次）", {
    grepl("value = isolate(draft())", v15_mod_src, fixed = TRUE)
  })
  chk("★★ 楼层号是**一个**字符串节点（写成 `span(\"#\", n)` 取出来是「# 1」）", {
    i <- regexpr("dsapp-forum-floor-no", v15_mod_src, fixed = TRUE)
    blk <- if (i > 0) substr(v15_mod_src, i, i + 90) else ""
    nzchar(blk) && grepl('paste0("#", label)', blk, fixed = TRUE)
  })

  # ---- (k) 接线 ----------------------------------------------------------
  v15_uip_src <- paste(readLines("R/uiprefs.R", warn = FALSE), collapse = "\n")
  v15_app_src <- paste(readLines("app.R", warn = FALSE), collapse = "\n")
  chk("★★ 论坛进了导航清单（漏了的话页面在但点不到）",
      grepl('value = "forum"', v15_uip_src, fixed = TRUE))
  chk("★★★ 导航清单里的 value 在 app.R 里真有对应的 nav_panel（反了就是点不动、不报错）", {
    grepl('nav_panel("论坛", value = "forum"', v15_app_src, fixed = TRUE) &&
      grepl('mod_forum_ui("forum")', v15_app_src, fixed = TRUE) &&
      grepl('mod_forum_server("forum", state)', v15_app_src, fixed = TRUE)
  })
  chk("★★ 论坛的导航项**没有** role 限制（所有账号都该看得见）", {
    i <- regexpr('value = "forum"', v15_uip_src, fixed = TRUE)
    # 往前找到这一项的 list( 开头，往后 200 字符里不许有 role =
    st <- max(1, i - 200)
    blk <- substr(v15_uip_src, st, i + 200)
    !grepl("role =", blk, fixed = TRUE)
  })
  chk("★ 论坛的样式在 app.css 里（不在的话页面能开、就是裸奔）", {
    css <- paste(readLines("www/app.css", warn = FALSE), collapse = "\n")
    grepl(".dsapp-forum-row", css, fixed = TRUE) &&
      grepl(".dsapp-forum-floor", css, fixed = TRUE)
  })
  chk("★ 正文复用 .dsapp-preview-md，没有抄第二份 markdown 排版", {
    grepl("dsapp-preview-md dsapp-forum-detail-body", v15_mod_src, fixed = TRUE) &&
      grepl("dsapp-preview-md dsapp-forum-floor-body", v15_mod_src, fixed = TRUE)
  })
  chk("★★★ 论坛在**三处清单**里（app.R / deploy.sh / selftest 自动捡）", {
    # ⚠️ app.R 那份清单写的是**裸文件名**（"forum.R"），deploy.sh 那份带
    #    `R/` 前缀。写成同一个模式的话总有一边恒为假 —— 第一版就是这么红的。
    #    （selftest 那边不用管：它把所有非 mod_ 的全 source，剩下的 mod_*
    #      走兜底循环，新文件自己会被捡起来。）
    dep <- paste(readLines("deploy.sh", warn = FALSE), collapse = "\n")
    grepl('"forum.R"', v15_app_src, fixed = TRUE) &&
      grepl('"mod_forum.R"', v15_app_src, fixed = TRUE) &&
      grepl("R/forum.R", dep, fixed = TRUE) &&
      grepl("R/mod_forum.R", dep, fixed = TRUE)
  })

  # ---- (l) 同步协议：签名载荷 -------------------------------------------
  v15_key_src <- paste(readLines("R/synckey.R", warn = FALSE), collapse = "\n")
  v15_sync_src <- paste(readLines("R/sync.R", warn = FALSE), collapse = "\n")
  # ⚠️ 查的是**载荷里那一行**（`forum = b$forum`），不是随便哪个 "forum"
  #    字面量 —— 注释里也写着 forum，只查字面量的话这条是空转。
  chk("★★★ 签名载荷里有 forum（不在的话论坛段可以被人随便改，而验签照样通过）",
      grepl("forum      = b$forum", v15_key_src, fixed = TRUE))
  chk("★★★ 签名载荷里有 req_from_forum（回包要按它过滤，不然服务器整库回一遍）",
      grepl("req_from_forum", v15_key_src, fixed = TRUE))
  chk("★★★ 建包时论坛段进了 data、req_from_forum 进了信封", {
    grepl("forum = list(", v15_sync_src, fixed = TRUE) &&
      grepl("req_from_forum = req_from_forum", v15_sync_src, fixed = TRUE)
  })
  chk("★★ 应用包里论坛段的返回计数接上了（n_forum）",
      grepl("n_forum", v15_sync_src, fixed = TRUE))
  chk("★★ 论坛段被截断时整包算截断（不算的话水位会推过头，剩下的永远发不出去）",
      grepl("isTRUE(frm$truncated)", v15_sync_src, fixed = TRUE))
  chk("★ 空状态里带上了 in_forum / out_forum 两个字段", {
    i <- regexpr("dsapp_sync_state_get <- function", v15_sync_src, fixed = TRUE)
    blk <- if (i > 0) substr(v15_sync_src, i, i + 2000) else ""
    nzchar(blk) && grepl('in_forum = ""', blk, fixed = TRUE) &&
      grepl('out_forum = ""', blk, fixed = TRUE)
  })

  # ---- 还原来宾口径的环境变量 ------------------------------------------
  # ⚠️ 这一段的必要性见本节开头：on.exit 在顶层 `{ }` 里**不执行**，所以
  #    还原只能这样显式写。两处改动（本节开头的 v15_td、第 (h) 段的
  #    v15_apply_td）都由这一句收口。
  # ⚠️ 放在**块的最后**，中间任何一条断言红了也要走到这里 —— chk() 自己吞异常，
  #    所以它红了不会跳过这一段（这一点和 V14 GPU 那一节一致）。
  if (is.na(old_root)) Sys.unsetenv("DSAPP_DATA_ROOT")
  else Sys.setenv(DSAPP_DATA_ROOT = old_root)
  unlink(v15_td, recursive = TRUE)
}

# =============================================================================
# V14 item 3/4：把图片内联进 HTML（单文件分发 + 预览不再裂图）
# =============================================================================
# 用户原话：「生成的全部 html 文件需要把图片写进 html 文件里……保障用户单独
# 分发 html 文件时，其它人也能正常查看」（item 3）、「最新的分析报告预览时，
# html 里的图片是裂的」（item 4）。
# 这两条走的是**同一段** dsapp_html_inline()：item 3 是"改完落盘"，
# item 4 是"读进来改一遍再发出去"。所以下面按"改出来的那段 HTML 对不对"断言，
# 而不是分别去测两个入口 —— 入口各测各的，中间那一段坏了照样全绿。
#
# ⚠️⚠️ 这一段是**事后补的**，补的原因值得写下来：V14 当初交上来的时候，
#    `dsapp_html_inline()` 一条直接断言都没有，而它正好在这段空档里错了一处
#    —— 换 src 时末尾写的是 a[[5]]（闭引号）而不是 a[[6]]（标签剩余部分，
#    含结尾的 `>`）。于是 `<img src='a.png' id='x'>` 被换成
#    `<img src='data:...'`：id/class/style 全丢，**连 `>` 都没了**，后面那个
#    `<` 被浏览器当成属性名的一部分吃掉（实测 `</body>` 会变成 img 上的
#    `body=""`）。
#    ⚠️ 它**躲过了当时所有的测试**：src 本身是对的，图照样显示，所以
#    "图裂了没有"这一类断言全绿；坏掉的是属性、以及图后面那一小段标记，
#    而那两样没有任何一条断言在看。
#    和 V13.17 的 wall_limit 是同一个教训：**没断言的功能等于没改**，
#    "自检全绿"不构成任何保证。
section("V14 item 3/4：图片内联进 HTML")

{
  v14i_td <- file.path(tempdir(), "v14_inline_selftest")
  unlink(v14i_td, recursive = TRUE)
  dir.create(v14i_td, showWarnings = FALSE, recursive = TRUE)

  v14i_png <- file.path(v14i_td, "a.png")
  writeBin(openssl::base64_decode(paste0(
    "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8",
    "z8BQDwAEhQGAhKmMIQAAAABJRU5ErkJggg==")), v14i_png)
  v14i_sz <- file.size(v14i_png)

  # 一份"像真的"的报告：两种引号、src 后面跟别的属性、一处读不到的图、
  # 一处外部地址。**每种写法都要有一条断言**，因为下面那条正则把
  # 引号、无引号分成了几个分支，改坏一个分支只有对应的那条会红。
  v14i_html <- paste0(
    "<!doctype html>\n<html><body>\n<h1>报告</h1>\n",
    "<img src='a.png' id='theimg' class='hero' style='width:9px'>\n",
    "<p>后面的正文</p>\n",
    "<img src=\"a.png\" alt=\"双引号那种\">\n",
    "<img src='nope.png' id='missing'>\n",
    "<img src='https://example.com/x.png' id='ext'>\n",
    "</body></html>\n")

  v14i_r <- dsapp_html_inline(v14i_html, v14i_td)
  v14i_o <- v14i_r$html

  chk("★ 两处本地引用都换成了 data: URI（item 3 的最低要求）",
      identical(as.integer(v14i_r$n), 2L) &&
        grepl("data:image/png;base64,", v14i_o, fixed = TRUE), v14i_r$n)

  # ★★★ 这是这次真正修的那一处。断言写成**整段标签的字面量**：只要重建时
  #     少拼了哪一部分（属性、闭引号、结尾的 `>`），这一条就会红。
  chk("★★★ ★ 换完之后**整个标签**还是原来那个（这是修掉的那处 bug：少拼了 a[[6]] 的话 id/class/style 和结尾的 `>` 全没了）",
      grepl("<img src='data:image/png;base64,[^']*' id='theimg' class='hero' style='width:9px'>",
            v14i_o), v14i_o)

  chk("★★ 双引号那一处的写法也要保住（两种引号走的是同一个分支的两半，改坏一半只有这条会红）",
      grepl("<img src=\"data:image/png;base64,[^\"]*\" alt=\"双引号那种\">",
            v14i_o), v14i_o)

  # ⚠️ 这条防的是"标签没闭合"的**连带伤害**：`>` 丢了之后，图后面那段标记
  #    会被浏览器当成属性吃掉 —— 看起来像"报告少了一段"，很难联想到是内联
  #    干的。所以单独盯一下 img 之后紧跟的那段正文。
  chk("★★ 图后面那段正文还在（`>` 丢了的话它会被当成 img 的属性吃掉）",
      grepl("<p>后面的正文</p>", v14i_o, fixed = TRUE), v14i_o)

  chk("★★ 读不到的图**原样留着**（改不了就别动它 —— 宁可是裂图，也不能把报告改坏）",
      grepl("<img src='nope.png' id='missing'>", v14i_o, fixed = TRUE) &&
        identical(as.integer(v14i_r$miss), 1L), v14i_r$miss)

  chk("★ 外部地址不内联、也不算 miss（它是故意的外链，不是「报告坏了」）",
      grepl("<img src='https://example.com/x.png' id='ext'>", v14i_o,
            fixed = TRUE) &&
        identical(as.integer(v14i_r$skipped), 1L), v14i_r$skipped)

  # ★ 同一个文件被引两次只读一次（报告里同一张 logo 出现几十次是常态，
  #   不去重的话一个 1MB 的图能撑出几十 MB 的 data:）。
  chk("★ 同一个文件引两次，字节只算一次（不然一张 logo 能把报告撑爆）",
      identical(as.numeric(v14i_r$bytes), as.numeric(v14i_sz)), v14i_r$bytes)

  # ---- 两条真实入口：预览（不落盘）和分发（落盘） ----------------------
  v14i_f <- file.path(v14i_td, "report.html")
  writeLines(v14i_html, v14i_f, useBytes = TRUE)

  v14i_rd <- dsapp_html_read_inlined(v14i_f, v14i_td)
  chk("★★ item 4 那条路（预览：读进来改一遍再发）里，src 之后的属性也还在",
      isTRUE(v14i_rd$ok) && grepl("id='theimg'", v14i_rd$html, fixed = TRUE) &&
        grepl("class='hero'", v14i_rd$html, fixed = TRUE), v14i_rd$msg)
  # ⚠️ 反向：预览这条路**不许**动盘上那份文件（"有人看了一眼"不该改文件）。
  # ⚠️ 这一条自己踩过三个 R 的坑，都写在这儿免得下次再踩：
  #    · writeLines 写完**会再补一个结尾换行**，所以盘上比原文多一行（空的）
  #      —— 期待值末尾要显式补一个 ""。
  #    · **strsplit 会把结尾那个空字段吃掉**（?strsplit：末尾匹配等于"把匹配
  #      去掉"），`strsplit("a\nb\n","\n")` 只给 c("a","b") 两个。所以不能
  #      指望它替你把上面那个空行补出来，得自己写 `c(..., "")`。
  #    · 别用 identical()，它连 Encoding 属性一起比：readLines 读回来的中文
  #      会带 UTF-8 标记，而拼出来的字面量是 unknown，内容一模一样也判 FALSE。
  #      `==` 会把两边归到同一种编码再比，这才是这里想比的。
  v14i_expect <- c(strsplit(v14i_html, "\n", fixed = TRUE)[[1]], "")
  v14i_now <- readLines(v14i_f, warn = FALSE)
  chk("★★ 预览不落盘（看一眼就把用户的报告改了的话，mtime 会在没人动它的时候跳）",
      length(v14i_now) == length(v14i_expect) &&
        all(v14i_now == v14i_expect),
      sprintf("%d 行 vs %d 行", length(v14i_now), length(v14i_expect)))

  v14i_sc <- dsapp_html_selfcontain_file(v14i_f, v14i_td)
  v14i_disk <- paste(readLines(v14i_f, warn = FALSE), collapse = "\n")
  chk("★★★ item 3 那条路（收尾时落盘）写出来的那份里，id/class/style 也还在 —— 用户拿去单独分发的就是这一份",
      isTRUE(v14i_sc$ok) && isTRUE(v14i_sc$n > 0L) &&
        grepl("id='theimg'", v14i_disk, fixed = TRUE) &&
        grepl("class='hero'", v14i_disk, fixed = TRUE) &&
        grepl("style='width:9px'", v14i_disk, fixed = TRUE), v14i_sc$msg)
  chk("★★ 落盘那份里不再有指向 a.png 的裸引用（还留着 = 发出去的人看到的还是裂图）",
      !grepl("src='a.png'", v14i_disk, fixed = TRUE) &&
        !grepl("src=\"a.png\"", v14i_disk, fixed = TRUE), v14i_disk)
  chk("★★ 落盘那份里「读不到的图」仍然是原样（内联不是「把报告重写一遍」）",
      grepl("<img src='nope.png' id='missing'>", v14i_disk, fixed = TRUE),
      v14i_disk)

  # ★★ 幂等：第二次跑已经自包含了，n=0，于是**一个字节都不该动**。
  #    不然每跑一次任务这个文件的 mtime 就跳一下，界面按时间排序会莫名其妙
  #    地重排，同步那边也会以为它变了。
  v14i_mt <- as.numeric(file.info(v14i_f)$mtime)
  v14i_sc2 <- dsapp_html_selfcontain_file(v14i_f, v14i_td)
  chk("★★ 已经自包含的文件第二次跑不动它（n=0 才落盘；否则 mtime 每次任务都跳）",
      isTRUE(v14i_sc2$ok) && identical(as.integer(v14i_sc2$n), 0L) &&
        identical(as.numeric(file.info(v14i_f)$mtime), v14i_mt),
      v14i_sc2$n)
}

# =============================================================================
# V14 item 3 下半句：md 下载要把依赖的文件一起打包
# =============================================================================
# 用户原话是两件事：「html 要把图片写进去」**和**「对应的 md 文件下载时需要把
# 依赖的文件一起打包下载」。上一节管前半句，这一节管后半句。
#
# ⚠️ 这一段同样是**事后补的**：上半句（内联）和下半句（打包）当时一条断言都
#    没有，所以下半句有没有真的接上，交上来的时候**无从知道**。
#    markdown 走不了"内联"那条路（图片变成 base64 文本墙就不是 markdown 了），
#    它只能打包 —— 也就是说这里的 `kind` 判断错了，用户拿到的东西是错的，
#    而页面上不会报任何错。
section("V14 item 3：md 下载连依赖一起打包")

{
  v14m_td <- file.path(tempdir(), "v14_md_selftest")
  unlink(v14m_td, recursive = TRUE)
  dir.create(file.path(v14m_td, "figures"), showWarnings = FALSE,
             recursive = TRUE)
  dir.create(file.path(v14m_td, "sub"), showWarnings = FALSE, recursive = TRUE)

  v14m_w <- function(rel, txt) {
    writeLines(txt, file.path(v14m_td, rel), useBytes = TRUE)
    file.path(v14m_td, rel)
  }
  writeBin(as.raw(c(0x89, 0x50, 0x4e, 0x47)), file.path(v14m_td,
                                                         "figures/a.png"))
  writeBin(as.raw(c(0x89, 0x50, 0x4e, 0x47)), file.path(v14m_td,
                                                         "sub/a.png"))
  v14m_r  <- v14m_w("report.md",  "正文\n\n![图](figures/a.png)\n")
  v14m_s  <- v14m_w("sub/deep.md", "正文\n\n![图](a.png)\n")
  v14m_n  <- v14m_w("nodep.md",  "只有文字，没有任何引用。\n")
  v14m_e  <- v14m_w("evil.md",   "![坏](../..%2F..%2Fetc/passwd)\n")
  v14m_x  <- v14m_w("ext.md",    "![外链](https://example.com/x.png)\n")
  v14m_h  <- v14m_w("report.html", "<html><body>hi</body></html>\n")
  v14m_c  <- v14m_w("data.csv",  "a,b\n1,2\n")

  # ---- 依赖是怎么找出来的 ----
  chk("★★ md 里的相对图片算依赖（item 3 下半句的最低要求）",
      identical(dsapp_md_deps(v14m_r, v14m_td), "figures/a.png"),
      dsapp_md_deps(v14m_r, v14m_td))
  # ⚠️ 先在 **md 自己那一层**找，找不到才退回 root。报告写在子目录、图放在
  #    自己旁边是常态；只认 root 的话那种报告算出来是 0 个依赖（静默）。
  chk("★★ 子目录里的 md 先在自己的目录里找图（只认 root 的话算出来是 0 个依赖）",
      identical(dsapp_md_deps(v14m_s, v14m_td), "sub/a.png"),
      dsapp_md_deps(v14m_s, v14m_td))
  chk("★ 没有引用的 md 算出来 0 个依赖（不能凭空凑一个）",
      identical(dsapp_md_deps(v14m_n, v14m_td), character(0)),
      dsapp_md_deps(v14m_n, v14m_td))
  # ★★★ zip slip：`../..` 爬出工作区的那种必须被丢掉。它要是进了依赖，
  #      用户下载的包里就有工作区外的文件 —— 这是安全问题，不只是脏数据。
  chk("★★★ 爬出工作区的引用**不能**变成依赖（zip slip）",
      identical(dsapp_md_deps(v14m_e, v14m_td), character(0)),
      dsapp_md_deps(v14m_e, v14m_td))
  chk("★★ 外部地址不是依赖（它不占包，也不该被当成「本地缺文件」）",
      identical(dsapp_md_deps(v14m_x, v14m_td), character(0)),
      dsapp_md_deps(v14m_x, v14m_td))

  # ---- 点下载时到底给什么 ----
  v14m_p <- dsapp_dl_plan(v14m_r, v14m_td)
  chk("★★★ 有依赖的 md → zip，而且包里是「md + 图」两份",
      identical(v14m_p$kind, "zip") && identical(as.integer(v14m_p$n), 2L) &&
        all(c("report.md", "figures/a.png") %in% v14m_p$rel),
      paste(v14m_p$kind, v14m_p$n, paste(v14m_p$rel, collapse = ",")))
  # ★★★ 这一条盯的是"名字和内容对不上"：下载名是 filename() 单独算的，
  #      内容是 content() 单独写的，两边各判一次 kind 就会对不上 ——
  #      用户拿到一个叫 `报告.md` 的 zip，双击打不开，而且看不出是谁的错。
  chk("★★★ zip 的名字必须以 .zip 结尾（名字叫 .md、内容是 zip 那种文件双击打不开）",
      grepl("\\.zip$", v14m_p$name) && grepl("含依赖", v14m_p$name),
      v14m_p$name)
  chk("★★ 没有依赖的 md 给的就是那个 md 本身（不能塞个空 zip 给用户）",
      identical(dsapp_dl_plan(v14m_n, v14m_td)$kind, "file"),
      dsapp_dl_plan(v14m_n, v14m_td)$kind)
  chk("★★ html 走「内联」那条路（不是 zip）",
      identical(dsapp_dl_plan(v14m_h, v14m_td)$kind, "html"),
      dsapp_dl_plan(v14m_h, v14m_td)$kind)
  chk("★ 普通文件原样给（不要给谁都想打包）",
      identical(dsapp_dl_plan(v14m_c, v14m_td)$kind, "file"),
      dsapp_dl_plan(v14m_c, v14m_td)$kind)
}

# =============================================================================
# V14 item 7：GPU 开关（「配额与资源」里按账号放行/禁止）
# =============================================================================
# 用户原话：「在「配额与资源」上限中加一个设置用户是否能够使用 GPU 资源的
# 开关按钮」。这一条**跨了四层**，每一层单独看都是对的，少一层就静默失效：
#   users 表 gpu_enabled（1/0/NULL 三态） → dsapp_limits_for_user()$gpu
#   → dsapp_run_code 把设备屏蔽掉 → 提示词如实转述给模型 → 管理界面能改。
# 所以下面按层断言，不写"改了一处就算过"的那种弱检查。
section("V14 item 7：GPU 开关")

# ---- 第 1 层：三态存取 + 合成 -------------------------------------------
# ⚠️ 用**临时库**，绝不碰真库：这里要写 gpu_enabled，跑在线上数据上就是
#    一次真实的管理员操作（memory: 仓库 .Renviron 会把实例接到生产库）。
#
# ⚠️ 改环境变量写成"改 → 断言 → 改回来"三段直线代码，**不用 on.exit** ——
#    理由见下面 V13.6 那段（chk 的条件是 promise，on.exit 挂到哪一帧不直观，
#    挂错了就是"改完没还原"而且不报错）。chk() 自己吞异常，所以中间红了也会
#    走到还原那一行。
{
  v14g_td  <- file.path(tempdir(), "v14_gpu_selftest")
  dir.create(v14g_td, showWarnings = FALSE, recursive = TRUE)
  v14g_env <- Sys.getenv("DSAPP_DATA_ROOT")
  Sys.setenv(DSAPP_DATA_ROOT = v14g_td)

  v14g_cfg <- dsapp_config()
  v14g_con <- dsapp_db(v14g_cfg)

  chk("★★ users 表有 gpu_enabled 这一列（老库靠 dsapp_db 的迁移补上）",
      "gpu_enabled" %in% DBI::dbListFields(v14g_con, "users"),
      paste(DBI::dbListFields(v14g_con, "users"), collapse = ", "))

  v14g_u <- dsapp_user_create("GPU自检", "v14gpu@selftest.invalid",
                              "13900000001", "生信", password = "pw123456",
                              con = v14g_con)
  v14g_id <- if (isTRUE(v14g_u$ok)) v14g_u$user$id else NA_integer_
  chk("★ 自检能建一个临时账号（下面三态的载体）", !is.na(v14g_id), v14g_u$msg)

  if (!is.na(v14g_id)) {
    # 三态：NA（没设过）→ TRUE → FALSE → NA
    chk("★★ 没设过时是 NA（不是 FALSE）—— 「跟着平台」和「明确禁止」必须分得开",
        isTRUE(is.na(dsapp_user_gpu_enabled(v14g_id, con = v14g_con))),
        dsapp_user_gpu_enabled(v14g_id, con = v14g_con))

    dsapp_user_set_gpu(v14g_id, TRUE, con = v14g_con)
    chk("★★ set_gpu(TRUE) 之后存下来的是 TRUE，不是被 num() 吃成 NULL",
        identical(dsapp_user_gpu_enabled(v14g_id, con = v14g_con), TRUE) &&
          identical(dsapp_limits_for_user(v14g_id, v14g_cfg, con = v14g_con)$gpu,
                    TRUE),
        dsapp_user_gpu_enabled(v14g_id, con = v14g_con))

    # ★★★ 这一条是最容易挂的：0 是**有意义的值**（明确禁止），而
    #     dsapp_user_limits() 那套 num() 归一化会把 0 变成 NULL —— 一旦
    #     gpu 被塞进那个循环，"禁止"和"没设过"会重新混成一个。
    dsapp_user_set_gpu(v14g_id, FALSE, con = v14g_con)
    chk("★★★ set_gpu(FALSE) 存下来的是 FALSE（不是 NULL）—— 0 不能被归一化吃掉",
        identical(dsapp_user_gpu_enabled(v14g_id, con = v14g_con), FALSE) &&
          identical(dsapp_limits_for_user(v14g_id, v14g_cfg, con = v14g_con)$gpu,
                    FALSE),
        dsapp_user_gpu_enabled(v14g_id, con = v14g_con))

    dsapp_user_clear_gpu(v14g_id, con = v14g_con)
    chk("★★ clear_gpu() 回到 NA，并且合成值跟着**平台默认**走",
        isTRUE(is.na(dsapp_user_gpu_enabled(v14g_id, con = v14g_con))) &&
          identical(dsapp_limits_for_user(v14g_id, v14g_cfg, con = v14g_con)$gpu,
                    isTRUE(v14g_cfg$exec$gpu)),
        dsapp_user_gpu_enabled(v14g_id, con = v14g_con))

    # ⚠️ set_gpu(FALSE) 必须是"禁止"，不能因为 FALSE 长得像"空"就被当成恢复默认。
    #    这条是针对"用 %||% 或 isTruthy 去解析入参"那种写法的。
    dsapp_user_set_gpu(v14g_id, "垃圾值", con = v14g_con)
    chk("★★ 认不出来的入参按**禁止**落库（安全的那一边），不是恢复默认",
        identical(dsapp_user_gpu_enabled(v14g_id, con = v14g_con), FALSE),
        dsapp_user_gpu_enabled(v14g_id, con = v14g_con))
    dsapp_user_clear_gpu(v14g_id, con = v14g_con)
  }

  # ---- 平台默认：DSAPP_EXEC_GPU 读得进来 --------------------------------
  chk("★★ 平台默认 exec$gpu 是**确定的逻辑值**（NULL 会让 executor 那层失效）",
      is.logical(v14g_cfg$exec$gpu) && length(v14g_cfg$exec$gpu) == 1L &&
        !is.na(v14g_cfg$exec$gpu),
      v14g_cfg$exec$gpu)
  chk("★ 平台默认取的是 FALSE（GPU 是最稀缺的资源，默认不敞开）",
      identical(v14g_cfg$exec$gpu, FALSE), v14g_cfg$exec$gpu)

  # ⚠️★ 这条盯着一个**真踩过的坑**：dsapp_gpu_allowed() 早先写成
  #    `con = NULL` 再 `con %||% dsapp_db(cfg)`，而连接是 S4 对象 ——
  #    `%||%` 最后一步算 is.na(a[1]) 会抛错，被 tryCatch 吞掉之后变成
  #    "读不出来" → **恒返回 FALSE**。管理员开了也没用，而且一声不吭。
  #    所以这里显式传 con，并且断言结果真的是 TRUE。
  if (!is.na(v14g_id)) {
    dsapp_user_set_gpu(v14g_id, TRUE, con = v14g_con)
    chk("★★★ dsapp_gpu_allowed(传了 con) 能读回 TRUE —— %||% 碰到 S4 连接会静默变成恒 FALSE",
        identical(dsapp_gpu_allowed(v14g_id, v14g_cfg, con = v14g_con), TRUE),
        dsapp_gpu_allowed(v14g_id, v14g_cfg, con = v14g_con))
    dsapp_user_clear_gpu(v14g_id, con = v14g_con)
  }

  # 无主任务（user_id = NULL）走平台默认，不能默认放行
  chk("★★ user_id 为 NULL 时 dsapp_gpu_allowed 走平台默认（不是恒 TRUE）",
      identical(dsapp_gpu_allowed(NULL, v14g_cfg, con = v14g_con),
                isTRUE(v14g_cfg$exec$gpu)),
      dsapp_gpu_allowed(NULL, v14g_cfg, con = v14g_con))

  # ★ 环境变量改回来。**必须在块内最后一件事**：留在临时目录上的话，后面
  #   所有碰数据库的断言写的都是这个一次性库 —— 而它们**照样全绿**，
  #   因为它们本来就只关心"写进去又读出来"。这类污染要到很久以后才现形。
  if (nzchar(v14g_env)) Sys.setenv(DSAPP_DATA_ROOT = v14g_env)
  else Sys.unsetenv("DSAPP_DATA_ROOT")
}

# ---- 第 2 层：执行层真的把设备屏蔽掉了 ---------------------------------
{
  v14g_off <- dsapp_exec_env("", NULL, threads = 2L, gpu = FALSE)
  v14g_nul <- dsapp_exec_env("", NULL, threads = 2L, gpu = NULL)
  v14g_one <- dsapp_exec_env("", NULL, threads = 2L, gpu = TRUE)

  chk("★★ gpu = FALSE 时四个设备变量**全部**置空（少一个就能绕过去）",
      all(c("CUDA_VISIBLE_DEVICES", "NVIDIA_VISIBLE_DEVICES",
            "ROCR_VISIBLE_DEVICES", "HIP_VISIBLE_DEVICES") %in% names(v14g_off)) &&
        all(v14g_off[c("CUDA_VISIBLE_DEVICES", "NVIDIA_VISIBLE_DEVICES",
                       "ROCR_VISIBLE_DEVICES", "HIP_VISIBLE_DEVICES")] == ""),
      paste(names(v14g_off), collapse = ", "))

  # ⚠️★ NULL = **不干预**：remote.R 起 ssh 客户端、自检自己跑代码都走这条，
  #    在那里顺手屏蔽掉等于改变了和 GPU 无关的路径的行为。
  chk("★★★ gpu = NULL 时**一个变量都不设**（不干预），不是设成空串",
      !any(c("CUDA_VISIBLE_DEVICES", "NVIDIA_VISIBLE_DEVICES",
             "ROCR_VISIBLE_DEVICES", "HIP_VISIBLE_DEVICES") %in% names(v14g_nul)),
      paste(names(v14g_nul), collapse = ", "))
  chk("★★ gpu = TRUE 时也不设变量（放行 = 什么都不敢动）",
      !"CUDA_VISIBLE_DEVICES" %in% names(v14g_one),
      paste(names(v14g_one), collapse = ", "))

  # ⚠️ 判据必须是 `identical(gpu, FALSE)`。写成 `!isTRUE(gpu)` 的话，
  #    NA（库读失败）也会被当成"屏蔽"—— 那就分不清"明确关"和"没问到"了。
  #    这条钉住的是**调用方**：executor.R 里必须把三态收成确定值再传下去。
  v14g_exec_src <- paste(readLines("R/executor.R", warn = FALSE), collapse = "\n")
  chk("★★★ executor.R 把 limits 收成**确定的逻辑值**再传给 dsapp_exec_env",
      grepl("gpu_ok <- isTRUE((limits %||% list())$gpu)", v14g_exec_src,
            fixed = TRUE),
      v14g_exec_src)
  chk("★★★ 两处 dsapp_exec_env 调用都把 gpu 传下去了（漏一处 = 那条语言不受管）",
      length(gregexpr("gpu = gpu_ok", v14g_exec_src, fixed = TRUE)[[1]]) == 2L,
      length(gregexpr("gpu = gpu_ok", v14g_exec_src, fixed = TRUE)[[1]]))
}

# ---- 第 3 层：提示词如实转述（否则模型会瞎写 cuda）---------------------
{
  v14g_l_off <- dsapp_gpu_prompt_line(FALSE)
  v14g_l_on  <- dsapp_gpu_prompt_line(TRUE)
  chk("★★ 提示词的「不可用」那一支说清了**是管理员没开**，不是代码写错了",
      grepl("管理员", v14g_l_off, fixed = TRUE) &&
        grepl("配额与资源", v14g_l_off, fixed = TRUE), v14g_l_off)
  # ⚠️★ 放行那一支**必须**带"先探测"：开关管的是权限，机器上有没有卡是
  #     另一回事。少了这句，模型会拿"允许"当"可用"，用户照做还是失败。
  chk("★★★ 提示词的「可用」那一支要求**先探测**（放行 ≠ 有卡）",
      grepl("探测", v14g_l_on, fixed = TRUE) &&
        grepl("nvidia-smi", v14g_l_on, fixed = TRUE), v14g_l_on)

  # 两个分支必须**真的不同** —— 复制粘贴写错时两边一模一样，而断言只看
  # "包含某个词"的话照样全绿。
  chk("★★ 两支不是同一段文字（写反了这里会红）",
      !identical(v14g_l_off, v14g_l_on), "")

  # 提示词正文里真的插进去了（函数写好了但没接到 sprintf 上是最常见的漏）
  v14g_psrc <- paste(readLines("R/prompts.R", warn = FALSE), collapse = "\n")
  chk("★★★ 系统提示词的「资源限额」里真的有 GPU 那一行",
      grepl("- GPU：%s", v14g_psrc, fixed = TRUE) &&
        grepl("gpu_line <- dsapp_gpu_prompt_line(ex$gpu)", v14g_psrc,
              fixed = TRUE), v14g_psrc)
  chk("★★ 账号的 GPU 值是从 dsapp_limits_for_user 取的（和说出来的口径一致）",
      grepl("ex$gpu     <- isTRUE(lim$gpu)", v14g_psrc, fixed = TRUE), v14g_psrc)
  # conda 环境也在本机跑，同一个开关一样管得着
  chk("★★ conda 环境那一支也带上了 GPU（不能只在系统环境里说）",
      grepl("dsapp_gpu_prompt_line(dsapp_gpu_allowed(user_id, cfg))", v14g_psrc,
            fixed = TRUE), v14g_psrc)
}

# ---- 第 4 层：两个管理界面都能改 --------------------------------------
{
  v14g_adm <- paste(readLines("R/mod_admin.R", warn = FALSE), collapse = "\n")
  v14g_ht  <- paste(readLines("R/mod_htadmin.R", warn = FALSE), collapse = "\n")

  v14g_uis <- list("R/mod_admin.R" = v14g_adm, "R/mod_htadmin.R" = v14g_ht)
  for (v14g_f in names(v14g_uis)) {
    # local()：循环变量在断言里被引用，不套一层的话最后一条断言读到的是
    # 循环结束后的值 —— 两条都跑，但第二条查的是第一个文件。
    local({
      f   <- v14g_f
      src <- v14g_uis[[f]]
      # 三选一，不是勾选框：存储是三态的，勾选框表达不了"跟着平台默认"
      chk(sprintf("★★ %s：GPU 用三选一（default/allow/deny），不是勾选框", f),
          grepl('radioButtons(ns("lim_gpu")', src, fixed = TRUE) &&
            grepl('"allow"', src, fixed = TRUE) &&
            grepl('"deny"', src, fixed = TRUE) &&
            grepl('"default"', src, fixed = TRUE) &&
            !grepl('checkboxInput(ns("lim_gpu")', src, fixed = TRUE), src)
      chk(sprintf("★★★ %s：清空走 clear_gpu，不是 set_gpu(NULL)（后者 = 禁止）", f),
          grepl("dsapp_user_clear_gpu(", src, fixed = TRUE), src)
      chk(sprintf("★★ %s：GPU 改动单独记一条 admin_gpu 审计", f),
          grepl('audit("admin_gpu"', src, fixed = TRUE), src)
      chk(sprintf("★★ %s：界面上如实说了机器上有没有卡（免得管理员以为开关没生效）",
                  f),
          grepl("dsapp_host_gpu()", src, fixed = TRUE), src)
    })
  }

  # 平台管理员那个「恢复平台默认」按钮的语义是"这个人身上单独设过的**全部**
  # 撤销"。漏掉 GPU 的话，按钮按下去 GPU 那一栏没动 —— 而按钮上写着"恢复
  # 平台默认"，用户会以为已经恢复完了。
  chk("★★★ mod_htadmin 的「恢复平台默认」连 GPU 一起清（use_inputs = FALSE 那条）",
      grepl('if (use_inputs) as.character(input$lim_gpu %||% "default")[1]\n                 else "default"',
            v14g_ht, fixed = TRUE), v14g_ht)
}

# 「本机有没有卡」的判据：看设备节点，**不是**看 nvidia-smi 在不在
# （这台机器上 nvidia-smi 装着但没有 /dev/nvidia*，只看命令会答"有卡"）
{
  v14g_hg <- dsapp_host_gpu()
  chk("★★ dsapp_host_gpu() 返回结构完整、判据是设备节点",
      is.list(v14g_hg) && !is.null(v14g_hg$ok) && !is.null(v14g_hg$detail) &&
        v14g_hg$kind %in% c("nvidia", "amd", "none"), v14g_hg$detail)
  # ★★★ 判据必须是**设备节点**。这台机器上 /usr/bin/nvidia-smi 是装着的
  #      （跟着驱动包一起），但 /dev/nvidia* 一个都没有 —— 只看"命令在不在"
  #      的实现会答"有卡"，管理员于是打开开关、用户照样报 no CUDA device。
  chk("★★★ 没有 /dev/nvidia* 时结论必须是没卡（不能因为 nvidia-smi 装着就说有）",
      if (length(Sys.glob("/dev/nvidia[0-9]*")) == 0L &&
            length(Sys.glob("/dev/kfd")) == 0L) !isTRUE(v14g_hg$ok) else TRUE,
      v14g_hg$detail)
}

# =============================================================================
# V13.5 item 3：列表不换行 + 整表横向滚
# =============================================================================
# 三件事**缺一不可**，而且缺哪一件都不报错，只是"看起来没生效"：
#   1. `white-space: nowrap`（www/app.css 的 .dsapp-dt-nowrap）
#   2. `width: auto` —— DT 自带的 `table.dataTable { width: 100% }` 会把表
#      钉死在容器宽度上，列被压窄、文字糊到隔壁，**永远不溢出**；
#   3. `overflow-x: auto` 的滚动容器。
# 再加上 R 那边的 `autoWidth = FALSE`（DT 的默认 TRUE 会自己算列宽再写死）。
#
# ⚠️ 断言里查的是**整套**：只查 CSS 的话，两张表忘了 `autoWidth = FALSE`
#    照样全绿，而用户看到的就是"没变化"。
v135_css <- paste(readLines("www/app.css", warn = FALSE), collapse = "\n")
# ⚠️ 这**不是一个** CSS 块，是六条同族的规则（容器本身、table.dataTable、
#    th/td、复选框列、按钮列、按钮 hover）。只抠"第一个 `{...}`"的话拿到的
#    是容器那一条，里面没有 nowrap、也没有 width:auto —— 三条里缺两条，
#    断言红得莫名其妙。所以从**第一条**规则抠到**最后一条**规则的收尾。
v135_hit  <- gregexpr("\\.dsapp-dt-nowrap", v135_css, perl = TRUE)[[1]]
v135_a    <- v135_hit[1]
v135_b    <- v135_hit[length(v135_hit)]
v135_tail <- substring(v135_css, v135_b)
v135_nowrap <- substring(
  v135_css, v135_a,
  v135_b + attr(regexpr("(?s)^.*?\\n\\}", v135_tail, perl = TRUE),
                "match.length") - 1L)
chk("★★ 不换行的滚动容器三条都在（nowrap / width:auto / overflow-x）",
    grepl("overflow-x: auto", v135_nowrap, fixed = TRUE) &&
      grepl("white-space: nowrap", v135_nowrap, fixed = TRUE) &&
      grepl("width: auto", v135_nowrap, fixed = TRUE) &&
      grepl("min-width: 100%", v135_nowrap, fixed = TRUE),
    v135_nowrap)
# 容器只包 DataTables 那张表，不包分页条 —— 用户要的是"整个列表的滑动条"，
# 分页条跟着一起飘反而是干扰。所以这两张表都必须是**表**套在里面。
for (.f in c("R/mod_tasks.R", "R/mod_files.R")) {
  local({
    f   <- .f
    src <- paste(readLines(f, warn = FALSE), collapse = "\n")
    chk(sprintf("★★ %s：表格套进了滚动容器，而且 autoWidth = FALSE", f),
        grepl('div(class = "dsapp-dt-nowrap", DT::dataTableOutput(ns("tbl")))',
              src, fixed = TRUE) &&
          grepl("autoWidth = FALSE", src, fixed = TRUE), src[1])
  })
}
# ⚠️ 别改成 DT 自带的 scrollX = TRUE：它把表头克隆进另一张 <table>，
#    dsapp_dt_select_all 往表头塞的"全选"方框会塞错地方，而且 cloneNode
#    出来的那份不带事件监听（看得见、点不动）。
# ⚠️ 这里**必须先把注释去掉再查**：两个文件里都写着 `scrollX = TRUE`，
#    但它出现在解释「**为什么不用**它」的那段注释里。按字面 grep 的话，
#    那两句说明本身就会被当成违规 —— 而这类"注释里提了一句"的假红最难判，
#    因为改代码解决不了，只能改断言。
v135_nc <- function(src) {
  src <- gsub("(?s)/\\*.*?\\*/", "", src, perl = TRUE)
  paste(Filter(function(l) !grepl("^\\s*#", l),
               strsplit(src, "\n", fixed = TRUE)[[1]]), collapse = "\n")
}
chk("★★ 没有顺手改成 DT 的 scrollX（改了的话表头全选框会失灵，且不报错）",
    !grepl("scrollX\\s*=", v135_nc(v135_css), perl = TRUE) &&
      !grepl("scrollX\\s*=",
             v135_nc(paste(readLines("R/mod_tasks.R", warn = FALSE),
                           collapse = "\n")), perl = TRUE),
    "scrollX =")

# =============================================================================
# V13.5 item 4：勾选方块 → 「去预览」按钮
# =============================================================================
# ⚠️ 这一段最容易被"改回去"：`selection = "none"` + Select 扩展这两样看着
#    像多余的，其实是必须的（DT 自带行选中和 Select 是两套实现，同时开互相抢）。
#    而它俩同时成立时，`DT::selectRows(proxy, i)` **不会被定义** —— 代理发出
#    去的消息落到 `console.log("Unknown method")` 那一支，是 log 不是 error，
#    控制台不红、只看 error 的断言全绿，表现是"点了没反应"。
#    所以按钮的勾选**必须在浏览器里**用 Select 扩展自己的 API 做。
v135_files <- paste(readLines("R/mod_files.R", warn = FALSE), collapse = "\n")
chk("★★ 第 0 列是「去预览」文字，且不再挂 select-checkbox（挂着会和文字叠一个空方框）",
    grepl('sel      = rep("去预览", nrow(df))', v135_files, fixed = TRUE) &&
      grepl('className = "dsapp-dt-btn", targets = 0', v135_files, fixed = TRUE) &&
      !grepl('className = "select-checkbox"', v135_files, fixed = TRUE),
    v135_files[1])
chk("★★ 「去预览」的点击走 cell_clicked 的 col == 0（走 actionButton 在 server = FALSE 的 DT 里点不动，还不报错）",
    grepl("if (identical(as.integer(cl$col), 0L))", v135_files, fixed = TRUE) &&
      grepl("if (!identical(as.integer(cl$col), 1L)) return()", v135_files,
            fixed = TRUE),
    v135_files[1])
# 多选**没有丢**：拿掉方框就必须补一个勾选入口，否则"下载选中/删除(N 项)"
# 会永远停在 0 项，而且不报错。selector 从第一列放宽到整行。
chk("★★ 勾选入口补回来了（selector 放宽到整行），否则批量按钮永远「0 项」",
    grepl('select = list(style = "multi", selector = "td")', v135_files,
          fixed = TRUE), v135_files[1])
# 浏览器那一半。★ V13.9 item 10 把这一段**反过来了**，所以下面两条也跟着反：
#
#   V13.5 当时写的是"先全清再选这一行"（`api.rows().deselect(); row.select();`），
#   为的是让预览读到刚点的那一行 —— 那时预览读的是 `selected()`，"行号最小的
#   那条"。代价是**每点一次「去预览」就把用户攒的勾选清光**：勾了三项准备打包，
#   看一眼其中一项的内容，回来只剩一项，而且不报错。
#
#   现在预览在服务端有自己的指针（R/mod_files.R 的 pv_pick），没有理由再动
#   勾选。所以这两条查的是**相反**的东西：清空的那句必须不在、把被 Select 扩展
#   切掉的那一行按回原状的那段必须在。
#
# ⚠️ 依然**不能**用 DT::selectRows（理由见上面那段：selection = "none" 时它
#    压根没被定义，消息落到 log 分支，不报错也不生效）。
v135_btn <- v135_slice(v134_js, "document.addEventListener\\(\"click\"",
                       "\\}\\);", must = "dsapp-dt-btn")   # 顶格收尾，见 v135_slice
chk("（前置）抠到了「去预览」的点击处理器",
    # ⚠️ 上限从 2000 放到 4000：V13.9 在这段里补了"为什么不能动勾选"和
    #    "为什么要在 pointerdown 里记状态"两段注释，代码只多了十来行。
    #    这个上限本来只是防"抠歪了啃到别的地方去"，不是拿它量注释长短。
    nzchar(v135_btn) && nchar(v135_btn) < 4000, substr(v135_btn, 1, 200))
#
# ⚠️ 下面这几条查的是**代码**，所以必须先把注释剥掉再找 —— 这段注释本身就在
#    解释"deselect 为什么不能留""为什么不能比 api"，原样去 grep 的话，
#    注释里的那两个字面量会把每一条否定式断言都判红（2026-09-21 实测：
#    两条断言红的都是自己的注释）。同一个坑在 codex.css 那几条上也踩过
#    （见上面「先把 CSS 注释去掉再找」那段）。
v135_btn_code <- strip_js_comments(v135_btn)
chk("★★★ 点「去预览」不再清空勾选（清空的那句必须不在）",
    !grepl("api.rows().deselect()", v135_btn_code, fixed = TRUE) &&
      !grepl("selectRows", v135_btn_code, fixed = TRUE), v135_btn_code)
chk("★★★ 而且要把 Select 扩展刚切换掉的那一行按回点击之前的状态", {
  # 只删掉 deselect 是不够的：V13.4 把 Select 扩展的 selector 放宽到了整行
  # （"点行内任意位置 = 勾选这一行"），「去预览」这一格也在行内，所以扩展
  # 会照常把这一行**切换**一下 —— 实测勾三行点一次会变成两行。
  # 修法是"记住点击前的状态、点完按回去"，状态只能在 pointerdown 里记
  # （click 冒泡到 document 时扩展已经切完了）。
  grepl("__dsappPreClickSel", v135_btn, fixed = TRUE) &&
    grepl("pointerdown", v134_js, fixed = TRUE) &&
    grepl("api.rows({ selected: true }).indexes().toArray()", v134_js,
          fixed = TRUE)
})
chk("★★ 比的必须是 <table> 元素，不是 api 包装对象（DataTable() 每次都 new 一个）", {
  # `$(tbl).DataTable()` 每调一次就 new 一个 Api，写 `before.api === api` 永远
  # 为假 —— 整段会静悄悄地跳过，看起来"改了但没效果"。2026-09-21 白跑一轮。
  # ⚠️ 否定那半边同样要去注释查（理由见上面 v135_btn_code 那段）。
  grepl("before.tbl === tbl", v135_btn_code, fixed = TRUE) &&
    !grepl("before.api === api", v135_btn_code, fixed = TRUE)
})

# =============================================================================
# V13.5 item 5：conda 包缓存目录的权限崩溃
# =============================================================================
# 崩的是 libmamba：
#   critical libmamba filesystem error: cannot set permissions:
#   Operation not permitted [/data3/biomamba/analysis/DS_App/data/conda_pkgs/cache]
# 根因是**所有运行身份共用一份**包缓存：开发目录的属主是 biomamba，线上跑在
# shiny 下，shiny 去 chmod 别人建的 cache 目录就被拒。
# 所以这一格改成**按运行身份分**（u<uid>/），每个身份一份、互不干扰。
v135_cfg <- paste(readLines("R/config.R", warn = FALSE), collapse = "\n")
chk("★★ conda 包缓存按运行身份分（共用的那格就是这次崩的那个）",
    grepl('file.path(data_root, "conda_pkgs", paste0("u", dsapp_run_id()))',
          v135_cfg, fixed = TRUE) &&
      grepl("conda_pkgs_dir = Sys.getenv(", v135_cfg, fixed = TRUE),
    v135_cfg[1])
# ⚠️ 只改路径是不够的：**旧的那一份还在**，而且可能是 0700/别的属主。
#    建环境之前必须先把它准备好（能建就建、建不了就给一句人话），
#    否则症状从"崩在 libmamba"变成"崩在 prepare"，用户看到的还是一样的红字。
v135_envs <- paste(readLines("R/envs.R", warn = FALSE), collapse = "\n")
chk("★★ 建环境之前先 prepare 包缓存目录（没这一步，路径改了照样崩）",
    grepl("dsapp_conda_pkgs_prepare <- function(cfg = dsapp_config())",
          v135_envs, fixed = TRUE) &&
      grepl("CONDA_PKGS_DIRS        = dsapp_conda_pkgs_dir(cfg)", v135_envs,
            fixed = TRUE),
    v135_envs[1])
# ★ V13.7 item 2：原来这里钉的是 `= cfg$conda_pkgs_dir`。现在两处都必须走
#   dsapp_conda_pkgs_dir()，因为那一层会在配置指向**别人**的缓存时自动换成
#   默认那份。各读各的就会分叉：prepare 认的是 A、真正传给 mamba 的是 B，
#   而 mamba 报错时说的是 B —— 查起来要绕很久。
chk("★★★ 传给 conda 的包缓存目录必须走同一个函数（不许各读各的）",
    !grepl("CONDA_PKGS_DIRS        = cfg$conda_pkgs_dir", v135_envs,
           fixed = TRUE) &&
      grepl("dsapp_conda_pkgs_dir(cfg)", v135_envs, fixed = TRUE),
    v135_envs[1])
chk("★★ prepare 失败时给的是人话，不是把 libmamba 那串英文原样甩给用户",
    grepl("cannot set permissions: Operation not permitted", v135_envs,
          fixed = TRUE), v135_envs[1])

# =============================================================================
# V13.5 item 6：基础环境那排单选按钮不许换行（+ 两个预置环境要露出来）
# =============================================================================
# ⚠️ 根因不是文案太长，是 shiny 的 `.shiny-input-container { width: 300px }`
#    —— radioButtons() 不传 width 就是这个宽度。所以**两处**都要有：
#    R 那边传 width = "100%" 放开钳制，CSS 那边兜住"标签比卡片还宽"的极端情况。
v135_mod_envs <- paste(readLines("R/mod_envs.R", warn = FALSE), collapse = "\n")
chk("★★ 基础环境那排单选：width 放开了 + 套了不换行的容器（少一个就还是折行）",
    grepl('div(class = "dsapp-radio-nowrap"', v135_mod_envs, fixed = TRUE) &&
      grepl('width = "100%")', v135_mod_envs, fixed = TRUE) &&
      grepl(".dsapp-radio-nowrap .radio label {", v135_css, fixed = TRUE) &&
      grepl("white-space: nowrap", v135_css, fixed = TRUE), v135_mod_envs[1])
# ★ 内置的两个模板（单细胞 / 空转）原来**压根没露出来** —— 只能从"新建环境"
#   那个下拉里选。现在在基础环境卡片里直接给按钮，点一下就开始装。
chk("★★ 单细胞 / 空转两个预置环境有按钮，而且点了真的会开始装",
    grepl("dsapp_env_templates_pending(cfg, have = as.character(df$name))",
          v135_mod_envs, fixed = TRUE) &&
      grepl("dsapp_env_create_from_template(hit[[1]], cfg)", v135_mod_envs,
            fixed = TRUE) &&
      grepl('actionButton(ns(paste0("tpl_mk_", nm))', v135_mod_envs,
            fixed = TRUE),
    v135_mod_envs[1])
# ⚠️ 两个卡片的进度条是**两个** output。只看环境名分不开（从"新建环境"那边
#    建的可以重名），所以另记了一个来源标记 create_from。
chk("★★ 进度条只出现在发起的那张卡片里（按 create_from 分，不是按环境名分）",
    grepl('if (is.null(nm) || !identical(create_from(), "panel")) return(NULL)',
          v135_mod_envs, fixed = TRUE) &&
      grepl('if (is.null(nm) || !identical(create_from(), "base")) return(NULL)',
            v135_mod_envs, fixed = TRUE) &&
      grepl('create_from("base")', v135_mod_envs, fixed = TRUE),
    v135_mod_envs[1])

# =============================================================================
# V13.5 item 7：设置页的二级导航
# =============================================================================
# 7 张卡片两栏铺开 = 用户原话的「太乱了」。分成 界面 / 执行 / 账号 三组。
# ⚠️ 用 navset_underline 而**不是** navset_hidden，也不用 tabsetPanel：
#    navset_hidden 没有可见的标签条，用户不知道还有别的内容；tabsetPanel 不吃
#    bslib 的皮肤变量。理由写在 R/mod_settings.R 那段注释里。
#
# ⚠️ 原来是**四**组（多一个「帮助」）。V13.14 item 23 把它搬去左栏独立成页了，
#    所以这里从 4 改成 3，并且**反向**钉一条"它不许回来"（在下面 item 23
#    那一节里，因为"搬走了"和"搬回来"是同一件事的两面）。
chk("★★ 设置页是三个 nav_panel 的二级导航（原来的两栏 7 卡片就是「太乱」）",
    grepl("navset_underline(", v134_set, fixed = TRUE) &&
      length(gregexpr("nav_panel(", v134_set, fixed = TRUE)[[1]]) == 3L &&
      grepl('nav_panel("界面", value = "ui"', v134_set, fixed = TRUE) &&
      grepl('nav_panel("执行", value = "exec"', v134_set, fixed = TRUE) &&
      grepl('nav_panel("账号", value = "account"', v134_set, fixed = TRUE),
    v134_set[1])
# ⚠️ 原来那七张卡片是靠 layout_columns(col_widths = c(7, 5), ...) 分成两栏的。
#    改成导航之后**必须**把那一处拆掉 —— 留着的话卡片还在两栏里，只是变矮了，
#    等于没改。
# ⚠️ 但**不能**直接查"文件里还有没有 layout_columns"：这个文件里另有一处
#    （「远程机器」那张卡片里的主机/端口/用户名一行三个输入框）是**卡片内部**
#    的排版，和 item 7 说的"七张卡片两栏铺开"不是一回事，留着是对的。
#    所以查的是"有没有哪一个 layout_columns 在排卡片"。旧写法里 card( 紧跟其后
#    几十个字符，这里给 200 字符的窗口 —— 三行输入框那处远远不到。
chk("★★ 设置页没有留下「用 layout_columns 排卡片」的旧结构（留着的话卡片还在两栏里，等于没改）",
    !grepl("(?s)layout_columns\\(.{0,200}?card\\(", v134_set, perl = TRUE),
    v134_set[1])
# ⚠️ 四个 nav_panel 的标题和 value 都是**常量**，不要读 state：bslib 的 navset
#    把没选中的面板也留在 DOM 里，读一次 state 就等于多注册一个依赖，
#    换页时会莫名其妙重渲整个外壳。
chk("★ 二级导航的标签是常量（没在里面读 state）",
    !grepl("nav_panel(state", v134_set, fixed = TRUE), v134_set[1])

# =============================================================================
# dsapp_md_inline() 的两个陷阱（2026-09-16 当场各踩了一次）
# =============================================================================
# item 3「markdown 加粗要真渲染」那一批改了 17 处，其中 models.R 的两处是错的
# ——而且**两种错法都不会报错**，只会让用户看到一段丑东西或者让自检整个起不来：
#
#   陷阱一：把 dsapp_md_inline() 塞进 paste0()/sprintf() 的**参数**里。
#           它返回的是 htmltools 的 HTML 对象，而 paste0 会 as.character()
#           把每个参数压成普通字符串 —— **类就没了**，最后渲染时被转义，
#           用户看到的是一对字面尖括号 `<strong>…</strong>`。
#           正确写法是**反过来**：先把整句拼好，再整体过 dsapp_md_inline()
#           （share.R 的 dsapp_share_notify 就是这么写的，那里的注释也说了）。
#
#   陷阱二：在**顶层**调它。DSAPP_MODEL_CATALOG 这种 source 时就求值的常量
#           属于顶层。而 models.R 在 app.R 的清单里排在 utils.R 后面没问题，
#           在 list.files() 的**字母序**里却排在 utils.R **前面** ——
#           selftest 第 120 行和后台子进程走的正是字母序那条路，症状是
#           `could not find function "dsapp_md_inline"`，自检连第一条断言都
#           跑不到。
#
# 所以下面这两条扫的是**全仓**的结构，不只是今天改过的那两处。
v134_md_wrap <- character(0)
v134_md_top  <- character(0)
v134_walk <- function(e, f, top) {
  if (!is.call(e)) return(invisible())
  fn <- tryCatch(as.character(e[[1]])[1], error = function(x) "")
  if (fn %in% c("paste0", "paste", "sprintf")) {
    for (i in seq_along(e)[-1]) {
      a <- e[[i]]
      if (is.call(a) && identical(as.character(a[[1]])[1], "dsapp_md_inline"))
        v134_md_wrap <<- c(v134_md_wrap,
                           sprintf("%s: %s", f, substr(paste(deparse(a), collapse = ""), 1, 60)))
    }
  }
  if (fn == "dsapp_md_inline" && top)
    v134_md_top <<- c(v134_md_top,
                      sprintf("%s: %s", f, substr(paste(deparse(e), collapse = ""), 1, 60)))
  # function(...) 的函数体不是顶层：那要等调用时才求值，顺序无所谓
  nt <- top && fn != "function"
  for (i in seq_along(e)) if (!is.null(e[[i]])) v134_walk(e[[i]], f, nt)
  invisible()
}
for (f in list.files("R", full.names = TRUE, pattern = "\\.R$")) {
  ex <- tryCatch(parse(f), error = function(e) NULL)
  if (is.null(ex)) next
  for (i in seq_along(ex)) v134_walk(ex[[i]], f, TRUE)
}
chk("★★ dsapp_md_inline() 的结果没被 paste0/sprintf 吃掉（吃了 → 界面上是一对尖括号，还不报错）",
    length(v134_md_wrap) == 0, paste(v134_md_wrap, collapse = " ;; "))
chk("★★ 没有 R/*.R 在**顶层**调 dsapp_md_inline()（models.R 在字母序里排在 utils.R 前面）",
    length(v134_md_top) == 0, paste(v134_md_top, collapse = " ;; "))

