section("V13.10 item 6：token 上限的滑块 + 输入栏 + 建议值")
# ===========================================================================
#
# 用户原话：「单次回复 token 上限需要同时有滑块和输入栏，并在滑块上设置
# 几个建议值」。

chk("★★★ 三件东西都在：滑块、输入栏、建议值", {
  src <- paste(readLines("R/mod_model.R", warn = FALSE), collapse = "\n")
  grepl('sliderInput(ns("max_tokens_slider")', src, fixed = TRUE) &&
    grepl('numericInput(ns("max_tokens")', src, fixed = TRUE) &&
    grepl("maxtok_pick", src, fixed = TRUE) &&
    grepl("dsapp_maxtok_suggestions", src, fixed = TRUE)
})
chk("★★★ 滑块和输入栏**不共用** inputId", {
  # 共用的话两个控件抢同一个 input，最后一个是 NULL（谁后渲染谁说话），
  # 而参数区是 renderUI 每次重建的 —— 表现是"有时候滑块没了，有时候
  # 数字框没了"。
  src <- paste(readLines("R/mod_model.R", warn = FALSE), collapse = "\n")
  grepl('ns("max_tokens_slider")', src, fixed = TRUE) &&
    grepl('ns("max_tokens")', src, fixed = TRUE)
})
chk("★★★ 真值只有一个：input$max_tokens（滑块和建议值都只是改它的手段）", {
  # 两份状态迟早会不一致，而不一致的表现是"我明明拖到 32K 了，发出去的
  # 还是 8K"，用户完全无从判断该信哪一个。
  src <- paste(readLines("R/mod_model.R", warn = FALSE), collapse = "\n")
  grepl("唯一真值仍然是 input$max_tokens", src, fixed = TRUE) &&
    grepl('updateNumericInput(session, "max_tokens"', src, fixed = TRUE)
})
chk("★★★ 双向同步有防回环的闸（不然拖滑块手感发涩、松手回跳一格）", {
  src <- paste(readLines("R/mod_model.R", warn = FALSE), collapse = "\n")
  grepl("syncing <- reactiveVal(FALSE)", src, fixed = TRUE) &&
    grepl("if (isTRUE(syncing())) return()", src, fixed = TRUE)
})
chk("★★★ 建议值按当前模型的量程过滤后才画", {
  # 摆一个模型不支持的 32K 出来，点下去会被夹回 8192 —— 用户看到的是
  # "我点的 32K，它给我 8K「，而不是」这个模型不支持 32K「。
  kr <- list(min = 512, max = 8192, step = 512)
  sug <- dsapp_maxtok_suggestions(kr)
  length(sug) > 0 && all(sug >= kr$min & sug <= kr$max) &&
    all(sug %% kr$step == 0)
})
chk("★★★ 建议值的生成要经过参数范围的钳制（越界的直接不出现）", {
  sug <- dsapp_maxtok_suggestions(list(min = 100, max = 200, step = 1))
  all(sug >= 100 & sug <= 200)
})
chk("★ 量程本身不合法时给空的，不是给一串错的", {
  identical(dsapp_maxtok_suggestions(list(min = 100, max = 50, step = 1)),
            numeric(0))
})
chk("★★ token 数的短写法（4096 → 4K，其余带千分位）", {
  identical(dsapp_fmt_tokens_short(4096), "4K") &&
    identical(dsapp_fmt_tokens_short(65536), "64K") &&
    identical(dsapp_fmt_tokens_short(1500), "1,500") &&
    identical(dsapp_fmt_tokens_short(NA), "—")
})
chk("★★★ 选中态的选择器是 `.dsapp-sug-chip.on`，和 R 里拼的类名对得上", {
  # ⚠️ 写成 `.dsapp-sug-chip-on` 的话永远不会命中，而且**不报错** ——
  #    表现只是「点了没有任何反馈」，看起来像 JS 没跑。
  css <- paste(readLines("www/app.css", warn = FALSE), collapse = "\n")
  r   <- paste(readLines("R/mod_model.R", warn = FALSE), collapse = "\n")
  grepl(".dsapp-sug-chip.on {", css, fixed = TRUE) &&
    grepl('if (isTRUE(all.equal(as.numeric(v),', r, fixed = TRUE)
})

# ===========================================================================
# 文献速递（V13.11 item 5）
# ===========================================================================
# 用户的原话：「加一个"文献速递"版块，请帮我写好内置提示词，并且可以关联
# 一些文献整理的开源 skills，可以通过输入一系列关键词，自动返回最相关的
# n 篇文献精读/略读」。
#
# 这一页**不做检索** —— 用户选的是「交给 agent 用命令行检索」。所以这里验的
# 是"条件收对了没有、提示词拼对了没有、活交出去了没有"，不验检索结果。
chk("★★★ 关键词按四种分隔符切，且**不按空格切**", {
  # ⚠️ 按空格切是这条路上最容易犯、也最不容易发现的错：
  #    "single cell RNA" 是一个概念，切成三个词之后检索式变成
  #    single AND cell AND RNA，召回的东西完全不是一回事 —— 而用户
  #    看不出来哪里错了，只会觉得"搜出来的东西不相关"。
  k <- dsapp_lit_keywords("空间转录组，肝癌\n免疫微环境、single cell RNA; PD-1")
  identical(k, c("空间转录组", "肝癌", "免疫微环境", "single cell RNA", "PD-1"))
})
chk("★ 关键词去重、去空白，全空时返回空向量（不是 NULL）", {
  identical(dsapp_lit_keywords("  a , a ,, b  "), c("a", "b")) &&
    identical(dsapp_lit_keywords("   \n  ,  "), character(0)) &&
    identical(dsapp_lit_keywords(NULL), character(0))
})
chk("★★★ 提示词带上了关键词和篇数", {
  p <- dsapp_lit_prompt(c("单细胞", "肝癌"), 3, 5)
  grepl("单细胞", p, fixed = TRUE) && grepl("肝癌", p, fixed = TRUE) &&
    grepl("3 篇精读", p, fixed = TRUE) && grepl("5 篇略读", p, fixed = TRUE)
})
chk("★★ 没填关键词时返回空串（调用方据此拦住提交）",
    identical(dsapp_lit_prompt(character(0)), "") &&
      identical(dsapp_lit_prompt(NULL), "") &&
      identical(dsapp_lit_prompt("   "), ""))
chk("★★ 提示词里的三条红线都在（不许编 / 摘要≠全文 / 接口出问题照实说）", {
  # 这三条不是凑数的：文献检索是幻觉重灾区，而"照着摘要把方法段补出来"
  # 是最难被发现的那类错（补出来的方法学又具体又像真的）。
  p <- dsapp_lit_prompt("x", 1, 1)
  grepl("不许编", p, fixed = TRUE) &&
    grepl("摘要不等于全文", p, fixed = TRUE) &&
    grepl("照实说", p, fixed = TRUE)
})
chk("★★★ DSAPP_LIT_SOURCES 恰好四条，每条是一个完整字符串", {
  # ⚠️ 踩过：原来写成 c("A前半", "A后半", ...) 那种"用 c() 拼行"的形式，
  #    它是 **12 个元素**，下面 seq_along() 于是给每一**行**编号 ——
  #    提示词里印出来是 1..12、每个接口被拆成三行各带一个号，排版全乱。
  #    而它不会报任何错。
  length(DSAPP_LIT_SOURCES) == 4L &&
    all(nzchar(DSAPP_LIT_SOURCES)) &&
    !any(grepl("\n", DSAPP_LIT_SOURCES))
})
chk("★★ 提示词里那四个库都列了出来，且编号是 1..4", {
  p <- dsapp_lit_prompt("x", 1, 1)
  # ⚠️ 「编号到 4 为止」这半句必须**只在入口表那一段里**查。原来写的是
  #    整段提示词的 `!grepl("\n5. ", p)` —— V13.16 item 27 把产出的结构
  #    改成 5 节之后，第 5 节那行「5. **附：检索记录**」正好以 "\n5. " 开头，
  #    这条断言当场变红，而入口表本身一个字都没动。
  #    （判据的范围比被测的东西大，就会在别处长出东西时误报 —— 和红线里
  #      "拿通用词当判据"是同一类毛病，只是这次范围是空间上的。）
  #    「怎么检索」到「产出什么」之间就是那张表。
  #
  # ★ V15.5 item 2：范围又收窄了一次。新汇编的提示词在入口表**前面**加了
  #   「## 怎么筛」一节（六条，编号 1..6），"整段到产出为止"的范围里于是
  #   多出一串 1..6 —— 老判据里 `!grepl("\n5. ", head_part)` 那半句当场
  #   变红，而入口表一个字都没动。这次直接**只取那张表本身**（从
  #   "1. Europe PMC" 到下一个 "## " 之间），不再靠"前面没有别的东西"。
  #   同一个坑踩第二次了，所以这次把范围钉到最小。
  head_part <- strsplit(p, "## 产出什么", fixed = TRUE)[[1]][1]
  tbl <- regmatches(head_part, regexpr("1\\. Europe PMC[\\s\\S]*?(?=\n\n)",
                                       head_part, perl = TRUE))
  tbl <- if (length(tbl)) tbl else ""
  grepl("Europe PMC", p, fixed = TRUE) &&
    grepl("PubMed E-utilities", p, fixed = TRUE) &&
    grepl("bioRxiv", p, fixed = TRUE) &&
    grepl("Crossref", p, fixed = TRUE) &&
    grepl("\n4. Crossref", tbl, fixed = TRUE) &&
    !grepl("\n5. ", tbl, fixed = TRUE)
})
chk("★ 精读/略读都是 0 时提示词里写明「这次不要」", {
  p <- dsapp_lit_prompt("x", 0, 0)
  grepl("这次不要精读", p, fixed = TRUE) &&
    grepl("这次不要略读", p, fixed = TRUE)
})
chk("★★ 年份是两段时才会加进提示词，且标点不重复", {
  with_yr <- dsapp_lit_prompt("x", 1, 1, years = c(2021, 2026))
  no_yr   <- dsapp_lit_prompt("x", 1, 1, years = NULL)
  # ⚠️ 判据必须是**那一句**，不能是"年份"两个字。提示词的「产出什么」那一段
  #    里写着"再附上标题、期刊、**年份**、作者" —— 于是**每一段**提示词都含
  #    "年份"，`!grepl("年份", no_yr)` 恒为假。第一版就是这么写的：它跟被测
  #    的行为毫无关系，只是在测"提示词里有没有出现过这两个字"，永远红。
  #    于是换成"只看" —— **还是错的**：三条红线里的第 3 条写着"**只看**到摘要时"，
  #    同样每段都有，`!grepl("只看", no_yr)` 依旧恒为假。第二次才找对：
  #    认"年发表的"这三个字，实测两段=TRUE / 无=FALSE / 单年=FALSE。
  #    （教训：拿一个**通用词**当判据，它迟早会在别处出现。判据得是这一句独有的。）
  yr_line <- "年发表的"
  grepl("2021", with_yr, fixed = TRUE) && grepl("2026", with_yr, fixed = TRUE) &&
    grepl(yr_line, with_yr, fixed = TRUE) &&
    !grepl(yr_line, no_yr, fixed = TRUE) &&
    # 「条件，；更早的」这种连着的两个标点不会报错，但用户第一眼就看见它
    !grepl("，；", with_yr, fixed = TRUE) &&
    # 只给一个年份不算区间，不能当成"只看这一年"
    !grepl(yr_line, dsapp_lit_prompt("x", 1, 1, years = 2021), fixed = TRUE)
})
chk("★ 补充要求会拼进去；没填就不留空段", {
  a <- dsapp_lit_prompt("x", 1, 1, extra = "不要综述")
  b <- dsapp_lit_prompt("x", 1, 1, extra = "")
  grepl("不要综述", a, fixed = TRUE) && !grepl("另外的要求", b, fixed = TRUE)
})

chk("★★★ 文献速递技能文件在 skills_builtin/ 下，且解析得出正文", {
  # 提示词让 agent"关联文献整理的开源 skills"，那一条就是它。
  md <- dsapp_skills_builtin_md(refresh = TRUE)
  hit <- Filter(function(s) identical(s$name, "文献速递"), md)
  length(hit) == 1L &&
    nzchar(trimws(hit[[1]]$body)) &&
    # 内置技能每篇都要写清楚上游和许可（见 skills.R 顶上那段）
    grepl("来源与许可", hit[[1]]$body, fixed = TRUE) &&
    grepl("repo:", paste(readLines("skills_builtin/literature-digest.md",
                                   warn = FALSE), collapse = "\n"),
          fixed = TRUE)
})
chk("★★ 默认挂上的那条按**名字**找得到", {
  # ⚠️ 内置技能在库里没有别的身份（user_id IS NULL + name），见 dsapp_skills_seed。
  ch <- data.frame(id = c(1L, 7L), name = c("别的", "文献速递"),
                   stringsAsFactors = FALSE)
  identical(dsapp_lit_default_skill(ch), 7L) &&
    # 找不到时返回空，**不报错** —— 老库升级的那个瞬间这条技能还没种进去，
    # 那时候"挂不上技能"不该让人用不了这一页。
    identical(dsapp_lit_default_skill(
      data.frame(id = 1L, name = "别的", stringsAsFactors = FALSE)),
      integer(0)) &&
    identical(dsapp_lit_default_skill(NULL), integer(0))
})

# =============================================================================
section("V13.16 item 27：产出是「文献阅读汇报」，不是检索过程的画外音")
# =============================================================================
# 用户原话：「文献阅读的报告不应该是检索文献过程的画外音，而应该是文献阅读
# 汇报，把这条准则在文献阅读模块内置」。
#
# ★ 这里盯的是**结构**，不是"有没有劝一句"。老提示词把「检索概况」排成
#   **第 1 节** —— 结构摆在那儿，模型就照着结构填：实测 data/workspaces/ 里
#   那两份真实产出，正文前三分之一全是"用了哪个库 / 检索式原文 / 各命中多少条 /
#   筛选流程"，「精读」要到 60 行开外才开始。所以判据是**节的顺序**，
#   外加反向：老的第 1 节不许换个名字回来。
{
  p27 <- dsapp_lit_prompt(c("单细胞", "肝癌"), 3, 5)

  # (a) 准则本身在，而且是**说给模型听**的一句可执行的话
  chk("★★★ 提示词里明写这是「文献阅读汇报」、不是「检索过程的画外音」",
      grepl("文献阅读汇报", p27, fixed = TRUE) &&
        grepl("不是检索过程的画外音", p27, fixed = TRUE) &&
        grepl("**不要**出现「我先检索了…」", p27, fixed = TRUE))

  # (b) ★ 节的顺序：内容在前、过程在最后
  # ⚠️ 路标取的是**结构那一节里的编号行**（"1. **这批文献讲了什么**"），
  #    不是「附：检索记录」这个词 —— 后者在 ★ 说明块和红线里都出现过，
  #    拿它当路标量到的是**第一次提及**的位置，也就是在内容节**前面**，
  #    顺序断言会当场变红，而结构其实是对的。
  #    （判据得挑**只在这一处出现**的写法，这条在 V13.12 的年份断言上踩过。）
  #
  # ★ V15.5 item 2：第 4 节从「一句话总览」改名成「合起来说明了什么」。
  #   改名的原因是**它已经不是一句话了** —— 新汇编的提示词把用户那份
  #   「多篇综合」并了进来（五个问题 + 四条规矩），留着"一句话总览"这个
  #   标题会让模型只写一句。位置没动，仍然是"精读略读之后、附录之前"。
  marks <- c("1. **这批文献讲了什么**", "2. **精读**（3 篇）",
             "3. **略读**（5 篇）", "4. **合起来说明了什么**",
             "5. **附：检索记录**")
  ipos <- vapply(marks, function(m) regexpr(m, p27, fixed = TRUE)[[1]], 1L)
  chk("★★★ 五节按「内容 → 精读 → 略读 → 综合 → 附：检索记录」排（过程在最后）",
      all(ipos > 0) && all(diff(ipos) > 0), ipos)

  # (c) 附录必须**写明"短"**。只挪位置不写死篇幅的话，那一大段过程信息会被
  #     原封不动搬到文末 —— 画外音换个地方放，仍然是画外音。
  chk("★★★ 附录写明了「放在全文最后 / 几行就够」",
      grepl("放在全文最后", p27, fixed = TRUE) &&
        grepl("几行就够", p27, fixed = TRUE))

  # (d) 反向：老的第 1 节「检索概况」不许再出现（换个名字回来也算）
  chk("★★★ 老的「检索概况」不再出现（挪个位置、换个名字回来也算）",
      !grepl("检索概况", p27, fixed = TRUE))

  # (e) 红线 4（接口出问题照实说）现在指向附录，不再写进正文
  chk("★★ 红线里的「接口打不开要照实说」指向附录，不是正文",
      grepl("照实说", p27, fixed = TRUE) &&
        grepl("写在最后那节「附：检索记录」里", p27, fixed = TRUE))

  # (f) 三个落点要一起改。只说一处模型会挑着听；而技能那条是老库升级时的
  #     **退路**（新技能还没种进去时默认挂的就是它），两边说法不一致会互相拆台。
  md27 <- paste(readLines("skills_builtin/literature-digest.md",
                          warn = FALSE), collapse = "\n")
  # ⚠️ 这个文件是 **markdown**（`#` 是标题不是注释），**不能**过 strip_comments
  #    —— 剥完整个文件就空了，两条断言会变成在空字符串上比对（"恒绿"）。
  i_over <- regexpr("## 一句话总览", md27, fixed = TRUE)[[1]]
  i_app  <- regexpr("## 附：检索记录", md27, fixed = TRUE)[[1]]
  chk("★★ 自撰的那条内置技能里是同一套体例（老库升级时它是退路）",
      grepl("不是检索过程的画外音", md27, fixed = TRUE) &&
        !grepl("## 检索概况", md27, fixed = TRUE) &&
        i_over > 0 && i_app > i_over)

  lit27 <- strip_comments(paste(readLines("R/mod_lit.R", warn = FALSE),
                                collapse = "\n"))
  chk("★★ 页面上也写了这条（给人看的：先说清会拿到什么）",
      grepl("只作为文末的一小段附录", lit27, fixed = TRUE) &&
        grepl('tags$b("文献阅读汇报")', lit27, fixed = TRUE))
}

# ---- V13.12 item 14：文献检索 / 文献阅读改用上游那两条技能 ----------------
chk("★★★ item 14：默认挂的是 academic-search + deeppapernote，**顺序按声明来**", {
  # ⚠️ 这里把库里 id 的顺序（19/20）和声明的顺序**故意写反**：断言值一次
  #    才有意义 —— 用 which(%in%) 写的话返回的是库的顺序，哪天别人调换
  #    DSAPP_LIT_SKILL_NAMES 两行，勾选框里的次序变了却没有任何测试会红。
  ch <- data.frame(id = c(30L, 19L, 20L, 7L),
                   name = c("别的", "deeppapernote", "academic-search",
                            "文献速递"),
                   stringsAsFactors = FALSE)
  identical(dsapp_lit_default_skill(ch), c(20L, 19L))
})
chk("★★★ item 14：两条新技能一条都没种上时退回「文献速递」，不是空手", {
  # 老库升级的那个瞬间：新技能还没 seed 进去。这一页至少还得挂上一条
  # 讲检索的技能，否则用户点了「开始检索」，模型的系统提示词里一条
  # 技能都没有 —— 而他明明勾着。
  ch <- data.frame(id = c(1L, 7L), name = c("别的", "文献速递"),
                   stringsAsFactors = FALSE)
  identical(dsapp_lit_default_skill(ch), 7L) &&
    # 只有一条新技能在时**不**退回：退回等于默认挂两条检索说法
    identical(dsapp_lit_default_skill(
      data.frame(id = c(7L, 20L), name = c("文献速递", "academic-search"),
                 stringsAsFactors = FALSE)),
      20L)
})
chk("★★★ item 14：挂了 academic-search 时提示词让它**先读技能**，没挂时不留这句", {
  with_sk <- dsapp_lit_prompt("x", 1, 1, skills = "academic-search")
  without <- dsapp_lit_prompt("x", 1, 1)
  grepl(".skills/academic-search/SKILL.md", with_sk, fixed = TRUE) &&
    !grepl("academic-search", without, fixed = TRUE) &&
    # 入口表两边都得在：挂了技能时它是"省你翻一次文件"的备份，
    # 技能库没种上的时候它就是全部的检索说明。
    grepl("Europe PMC", with_sk, fixed = TRUE) &&
    grepl("Europe PMC", without, fixed = TRUE) &&
    # 而且必须是**同一个**四条的编号（别为了加那段把表挤掉了）
    grepl("\n4. Crossref", with_sk, fixed = TRUE)
})
chk("★★★ item 14：挂了 deeppapernote 时精读按它的证据要求写，且**明说只有一个产物**", {
  p <- dsapp_lit_prompt("x", 2, 1, skills = "deeppapernote")
  q <- dsapp_lit_prompt("x", 2, 1)
  grepl("deeppapernote", p, fixed = TRUE) &&
    # 不写"不要另外生成笔记"的话，这条技能自己的说明里写着产物叫
    # `精读笔记-<论文短名>.md`，2 篇精读就会多出 2 个文件，而用户在
    # 对话页等的是**一份**《文献速递》。
    grepl("**一个**文件", p, fixed = TRUE) &&
    grepl("不要", p, fixed = TRUE) &&
    !grepl("deeppapernote", q, fixed = TRUE)
})
chk("★★ item 14：skills 里混进空串 / NA / 不认识的名字都不炸（走通用说明）", {
  base <- dsapp_lit_prompt("x", 1, 1)
  identical(dsapp_lit_prompt("x", 1, 1, skills = character(0)), base) &&
    identical(dsapp_lit_prompt("x", 1, 1, skills = NULL), base) &&
    identical(dsapp_lit_prompt("x", 1, 1,
                               skills = c("", NA, "别人分享的技能")), base)
})
# ---- V13.12 item 16：已勾的技能排在最上面 --------------------------------
chk("★★★ item 16：勾上的技能排到最前面，没勾的保持库里的原序", {
  ids <- c("7", "3", "9", "11", "19", "20")
  # 用户遇到的就是这个：默认勾的两个新技能 id 最大，排在 19 条列表的最底下，
  # 而这块高度是封顶的 —— 不往上提就得先滚动才看得见自己挂了什么。
  identical(dsapp_lit_skill_order(ids, c("20", "19")),
            c("20", "19", "7", "3", "9", "11")) &&
    # ⚠️ 勾上的那批内部保持**送进来的那个序**（不是库里的序，更不是点击先后）。
    #    送进来的是 DOM 序，也就是"用户此刻看到的那一列"—— 于是"勾一条，
    #    它往上一格"和"列表在光标底下重排"这两件事不会同时发生。
    #
    #    ⚠️ 这条断言原来写的是"保持库里的原序"（期望 c(7,9,…)），**是错的**：
    #       函数不排序，只做分组。当时它没红是因为前半个用例（20,19）恰好
    #       两种口径结果一样，而这半个用例从来没被单独跑过。
    #       要不要改成"勾上的按库序排"是个产品判断，不是 bug —— 现在的口径
    #       是"别在光标底下动"，改之前先想清楚这一点。
    identical(dsapp_lit_skill_order(ids, c("9", "7")),
              c("9", "7", "3", "11", "19", "20")) &&
    # 勾上的那批**原样**带出来，一条不多一条不少（多一条就是"点了技能就消失"）
    identical(intersect(dsapp_lit_skill_order(ids, c("9", "7")), c("9", "7")),
              c("9", "7"))
})
chk("★★★ item 16：顺序变了，**集合**没变（少一条就是「点了技能就消失」）", {
  # ⚠️ 这里不能用 `for (...) return(FALSE)` 提前退出：return() 会把整个
  #    chk() 顶掉、连 ✗ 都不打（见 chk 定义那段：cond 是个 promise，
  #    求值时的 return 落回 chk 自己的调用上下文）。一律写成向量化的 all()。
  ids <- c("7", "3", "9", "11", "19", "20")
  all(vapply(list(NULL, character(0), "9", c("20", "19"), ids),
             function(on) {
               got <- dsapp_lit_skill_order(ids, on)
               identical(sort(got), sort(ids)) && !anyDuplicated(got)
             }, TRUE))
})
chk("★★ item 16：NULL（还没点过）和 character(0)（全取消了）不是一回事", {
  ids <- c("7", "3", "9")
  # 两条都保持原序 —— 关键是"全取消"不能退回默认勾选（那样用户会发现
  # 自己取消不掉，一刷新又回来了）。
  identical(dsapp_lit_skill_order(ids, NULL), ids) &&
    identical(dsapp_lit_skill_order(ids, character(0)), ids) &&
    identical(dsapp_lit_skill_order(character(0), "7"), character(0))
})
chk("★★ item 16：库里已经没有的技能 id（下架了）不会把渲染带崩", {
  # 前端送上来的是**当时**的勾选。勾上之后管理员把那条技能下架，再点一次
  # 勾选框，这个 id 就出现在 picked() 里而库里没有 —— 直接拿来排的话
  # ord 里会多一个对不上名字的 id，match() 返回 NA，名字渲染成空。
  got <- dsapp_lit_skill_order(c("7", "3"), c("99", "3"))
  identical(got, c("3", "7")) && !anyNA(got)
})
chk("★★★ item 16：勾选框的 choices 和 selected 用的是同一批 id", {
  # ⚠️ 只改 choices（排序）不改 selected 的话，重画之后勾选状态会被 DOM 的
  #    默认值顶掉 —— 表现是"点一下，勾全没了"。
  src <- strip_comments(
    paste(readLines("R/mod_lit.R", warn = FALSE), collapse = "\n"))
  grepl("ord <- dsapp_lit_skill_order(ids, on)", src, fixed = TRUE) &&
    grepl("sel <- intersect(ord, on)", src, fixed = TRUE) &&
    grepl("selected = sel", src, fixed = TRUE) &&
    # 重排的触发源只能是勾选框本身。跟着 choices() 一起变的话，每次
    # 重新种技能都会把列表重画一遍。
    grepl("observeEvent(input$skills,", src, fixed = TRUE) &&
    grepl("ignoreNULL = FALSE", src, fixed = TRUE) &&
    # ⚠️⚠️ ignoreInit = TRUE 必须写。observeEvent 默认**启动时先跑一次**，
    #    那一刻 input$skills 还是 NULL，picked() 会被立刻写成 character(0)，
    #    第一次 renderUI 读到的就是"用户什么都没勾" —— 默认那两条不勾上，
    #    整张表一条都没有勾。实测就是这样（这台机器上跑出来的：
    #    DBG render: picked= def=13,14 on= sel=），而且页面不报任何错。
    grepl("ignoreInit = TRUE", src, fixed = TRUE)
})

# ---- V13.12 item 17 的那个预览：★ V15.5 item 4 已按用户要求**整条撤掉** ----
#
# 原来这里有四条断言（滚进视野 / 只开不关 / 没填关键词给明白话 / 说不发起
# 检索），盯的都是「看看会发什么」那颗按钮和它底下的提示词预览卡。
#
# 用户 V15.5 原话：「"看看会发生什么"换成"关联技能"即可」，追问之后选的是
# 「那颗按钮改名+改功能」—— 也就是说那颗按钮**不再预览提示词**。功能没了，
# 断言不能留着：留着的话它们会一直红，而"一直红的断言"下一步就是被整段
# 注释掉，连带把真正该守的东西一起埋掉。
#
# ⚠️ 但"删干净"本身要有人守 —— 半截的删除（按钮删了、output$peek_box 还在）
#    是最难查的那种：代码看着像还在用，实际永远进不去。所以这里换一条
#    **反向哨兵**，正主在下面 V15.5 那一节里，两处一起看才完整。
chk("★★★ V15.5 item 4：item 17 那套预览（peek / peek_box / 星号预览样式）撤干净了", {
  src <- strip_comments(
    paste(readLines("R/mod_lit.R", warn = FALSE), collapse = "\n"))
  !grepl("peek", src, fixed = TRUE) &&
    !grepl("dsapp-lit-preview", src, fixed = TRUE) &&
    # 滚进视野那条**通道本身**没被拆掉 —— 它现在归「关联技能」和
    # 「定时订阅」两颗按钮用（V15.5 item 4），通道拆了那两颗就哑了。
    grepl('sendCustomMessage("dsapp:flash"', src, fixed = TRUE)
})

# ---- V13.12 item 18：「告诉 AI 注意事项」--------------------------------
chk("★★★ item 18：界面标题改成了「告诉 AI 注意事项」", {
  # ⚠️ 查"旧文案还在不在"必须**剥注释**：用户的原话（「还想让它注意什么」）
  #    正躺在这一段的注释里交代改了什么，用整份源码查的话，这条会因为
  #    "注释里提到了旧说法"而红 —— 而它红的样子像"标题没改"。
  src <- strip_comments(
    paste(readLines("R/mod_lit.R", warn = FALSE), collapse = "\n"))
  grepl("告诉 AI 注意事项", src, fixed = TRUE) &&
    # 旧的问法（用户明确说要换掉的那句）
    !grepl("还想让它注意什么", src, fixed = TRUE)
})
chk("★★★ item 18：勾的预设**一条一行**写进提示词，不是挤成一段", {
  p <- dsapp_lit_prompt("x", 1, 1,
                        extra = c("不要综述，只要原始研究", "优先近三年的工作"))
  # 挤成一段（paste(collapse=" ")）的话模型很容易只兑现第一条 —— 而用户
  # 勾了五条，他会以为五条都生效了。
  grepl("- **另外的要求**", p, fixed = TRUE) &&
    grepl("  - 不要综述，只要原始研究\n  - 优先近三年的工作", p,
          fixed = TRUE)
})
chk("★★★ item 18：只留一个 textInput 的旧路径不变（向后兼容）", {
  # dsapp_lit_prompt(extra=) 别的调用点（selftest 里就有一处）传的是单字符串。
  a <- dsapp_lit_prompt("x", 1, 1, extra = "不要综述")
  grepl("  - 不要综述", a, fixed = TRUE) &&
    # 空 / NA / 空白都不该留下一条光秃秃的 "- "
    !grepl("- **另外的要求**", dsapp_lit_prompt("x", 1, 1, extra = ""),
           fixed = TRUE) &&
    !grepl("- **另外的要求**",
           dsapp_lit_prompt("x", 1, 1, extra = c(NA, "", "   ")), fixed = TRUE) &&
    identical(dsapp_lit_prompt("x", 1, 1, extra = c(NA, "A", "")),
              dsapp_lit_prompt("x", 1, 1, extra = "A"))
})
chk("★★ item 18：预设都写成「对 AI 说的话」，不是名词短语", {
  # ⚠️ 这些句子是**原样**拼进提示词的（prompts.R 那边不再加工），写成
  #    名词短语（"综述"、"公开数据"）模型只能猜用户想让它干嘛。
  length(DSAPP_LIT_NOTE_PRESETS) >= 3L &&
    !anyDuplicated(DSAPP_LIT_NOTE_PRESETS) &&
    all(nzchar(trimws(DSAPP_LIT_NOTE_PRESETS))) &&
    all(vapply(DSAPP_LIT_NOTE_PRESETS,
               function(s) grepl("不要|优先|把|必须", s), TRUE))
})
chk("★★★ item 18：自定义那栏送来的预设要过白名单，手写那句原样带进去", {
  # 值是前端送上来的，改 DOM 就能往提示词里塞任意文字 —— 和技能 id 一样
  # 属于"浏览器发来的一律当不可信"。
  src <- strip_comments(
    paste(readLines("R/mod_lit.R", warn = FALSE), collapse = "\n"))
  grepl("pre <- pre[pre %in% DSAPP_LIT_NOTE_PRESETS]", src, fixed = TRUE) &&
    grepl("notes_now()", src, fixed = TRUE) &&
    # 预设在前、手写在后（通用约束在前，更具体的那条在后）
    grepl("c(pre, own)", src, fixed = TRUE)
})
chk("★★★ item 18：预设勾选框**没有**默认勾选（额外要求默认应该是空的）", {
  # 这一栏的语义是"额外的要求"，默认全空 = 不额外约束，和原来那个空
  # textInput 一致。哪天有人给它加个 selected=，默认行为就悄悄变了。
  src <- strip_comments(
    paste(readLines("R/mod_lit.R", warn = FALSE), collapse = "\n"))
  # ⚠️ 必须 fixed = TRUE。这条原来当正则用，而模式里有**没转义的括号和引号**
  #    （checkboxGroupInput( … ns("…")），regexpr 直接抛
  #    「invalid regular expression, reason 'Missing ')'」—— chk 把它记成
  #    这一条失败，读日志的人看到的是"预设默认勾选了"，和真正的原因
  #    （断言自己写坏了）八竿子打不着。凡是**定位源码原文**的匹配一律 fixed。
  # ⚠️ 认的是 `ns("extra_presets")` 这个锚点、然后**往前多取一截**，
  #    而不是去拼 `checkboxGroupInput(\n     ns(...)` 那种带缩进的整串：
  #    缩进一改（这行就改过一次）整条断言就抠不到，而抠不到等于后面
  #    两条白查。往前 200 字符足够盖住 `checkboxGroupInput(` 那个头。
  i <- regexpr('ns("extra_presets")', src, fixed = TRUE)
  call <- if (i > 0) substr(src, max(1L, i - 200L), i + 300L) else ""
  # ⚠️ 抠不到就**必须**红，不能因为 call 是空串而"后面两条正好也过"。
  nzchar(call) && !grepl("selected", call, fixed = TRUE) &&
    grepl("DSAPP_LIT_NOTE_PRESETS", call, fixed = TRUE)
})

chk("★★★ item 14：两条技能真的在 skills_builtin/ 下，正文和配套文件都解析得出来", {
  md <- dsapp_skills_builtin_md(refresh = TRUE)
  hit <- Filter(function(s) s$name %in% c("academic-search", "deeppapernote"),
                md)
  length(hit) == 2L &&
    all(vapply(hit, function(s) nzchar(trimws(s$body)), TRUE)) &&
    # 上游戏这两条技能的**价值**大半在 references/ 和 scripts/ 里，
    # 只解析出正文等于挂了个目录页
    all(vapply(hit, function(s) length(s$files %||% list()) >= 10L, TRUE)) &&
    # 内置技能每篇都要写清上游和许可（见 skills.R 顶上那段）
    all(vapply(hit, function(s) grepl("github.com/", paste(s$body, collapse = ""), fixed = TRUE), TRUE)) &&
    all(vapply(hit, function(s) grepl("MIT", paste(s$body, collapse = ""), fixed = TRUE), TRUE))
})

chk("★★★ 左栏有「文献速递」，且 value 和 navset 对得上", {
  # 这条和 item 3 那条表驱动的断言是**两件事**：那条保证"表 ↔ navset 一致"，
  # 这条保证"这一版真的把这一项加进去了"（表里漏了它就自动一致了）。
  "lit" %in% DSAPP_NAV_VALUES &&
    any(vapply(DSAPP_NAV_ITEMS,
               function(x) identical(x$value, "lit") &&
                 identical(x$label, "文献速递"), logical(1)))
})
chk("★★★ 文献速递那一页住在 R/ 下，并且 app.R 真的把它接上了", {
  # 判据见 app.R 里那段长注释：app.R 的顶层不在 globalenv，而 R/*.R 在。
  # mod_lit 里调了 dsapp_lit_prompt()（R/prompts.R）、dsapp_db()（R/db.R）、
  # dsapp_skills_*（R/skills.R）—— 全是 globalenv 里的东西，所以它自己
  # 也必须住在 R/ 下；放进 app.R 就成了"env_app.R 够不着 globalenv"。
  #
  # ⚠️ 第一版把这里写成了 `!grepl("mod_lit_ui", app.R)` —— **自相矛盾**：
  #    app.R 要是不提 mod_lit_ui，这一页根本就没接上去（nav_panel 里那一行
  #    和 mod_lit_server 那一行都在 app.R）。那条断言测的是"没接上"，
  #    而需求要的正是"接上"。写成这样它永远红，而且红得毫无道理。
  #    真正该测的是：**定义**在 R/ 下，**接线**在 app.R 里。
  a <- paste(readLines("app.R", warn = FALSE), collapse = "\n")
  file.exists("R/mod_lit.R") &&
    # 接线：UI 进 nav_panel、server 进 server 函数，两处都要有
    grepl('mod_lit_ui("lit")', a, fixed = TRUE) &&
    grepl('mod_lit_server("lit", state)', a, fixed = TRUE) &&
    # 定义只许在 R/mod_lit.R：app.R 里不许再出现一遍函数定义
    !grepl("mod_lit_ui <- function", a, fixed = TRUE) &&
    !grepl("mod_lit_server <- function", a, fixed = TRUE)
})
chk("★★★ 对话模块能收 lit_go，而且那条路走的是**同一条**发送路径", {
  # 不自己实现一遍发送，是为了不把「正在生成/只读共享/没 Key/没选模型」
  # 那几道闸门在第二个地方再写一遍 —— 重复实现的闸门总有一天会漏掉一条，
  # 而漏掉的那条正好可能是"不能往别人的对话里写"。
  src <- paste(readLines("R/mod_chat.R", warn = FALSE), collapse = "\n")
  grepl("observeEvent(input$lit_go", src, fixed = TRUE) &&
    grepl("dsapp_chat_send(extra = prompt)", src, fixed = TRUE)
})
chk("★★★ dsapp_chat_send 会报告到底发没发出去", {
  # ⚠️ 它原来每个 return() 都是裸的，调用方无从知道结果。文献速递那条路
  #    会**先建好对话再发**，被闸门拦下时那个刚建的空对话必须收回去 ——
  #    不收的话用户点一次就多一个空对话，点几次攒一串。
  src <- paste(readLines("R/mod_chat.R", warn = FALSE), collapse = "\n")
  i <- regexpr("dsapp_chat_send <- function", src, fixed = TRUE)
  j <- regexpr("dsapp_llm_begin <- function", src, fixed = TRUE)
  body <- substr(src, i, j)
  grepl("return(FALSE)", body, fixed = TRUE) &&
    grepl("invisible(TRUE)", body, fixed = TRUE)
})
chk("★★★ 发不出去时把刚建的对话收回去（且只收**刚建的**那个）", {
  src <- paste(readLines("R/mod_chat.R", warn = FALSE), collapse = "\n")
  i <- regexpr("observeEvent(input$lit_go", src, fixed = TRUE)
  j <- regexpr("observeEvent(input$new_chat", src, fixed = TRUE)
  body <- substr(src, i, j)
  grepl("db_session_delete(sid, con = con, cfg = cfg())", body, fixed = TRUE) &&
    # 放回原来那个对话，而不是把用户扔进空白页
    grepl("rv$session_id <- prev_sid", body, fixed = TRUE)
})
chk("★★★ 标题不会被那段提示词覆盖掉", {
  # ⚠️ dsapp_chat_send() 里有"第一条消息顺手当标题"的逻辑，而这条路发出去的
  #    正是几百字的检索提示词 —— 不补一次 rename 的话，会话标题会变成
  #    「做一次**文献速递**：围绕下面的关键词检索，给」，关键词一个字都看不见。
  src <- paste(readLines("R/mod_chat.R", warn = FALSE), collapse = "\n")
  i <- regexpr("observeEvent(input$lit_go", src, fixed = TRUE)
  j <- regexpr("observeEvent(input$new_chat", src, fixed = TRUE)
  body <- substr(src, i, j)
  # 发送**之后**还有一次 rename（if (isTRUE(ok) && nzchar(ttl))）
  grepl("isTRUE(ok) && nzchar(ttl)", body, fixed = TRUE)
})
chk("★★★ 前端把 lit_go 发到**下发下来的**那个 id，没有硬编码命名空间", {
  # 硬编码 "chat-lit_go" 的话，改一次模块 id 就静默失效（点了没反应，
  # 且没有任何报错）—— 这正是 dsappIds 这套东西存在的理由。
  # ⚠️ 查"有没有写死"之前**必须剥注释**。app.js 里那段说明**正着**写了
  #    这个名字（"**不要**在这里写死 `"chat-lit_go"`"）—— 不剥的话，注释里
  #    的这五个字符就把 `!grepl` 顶成假，断言永远红，而代码是对的。
  #    同 app.css 那几条：说明文字里出现被禁的写法，是很正常的事。
  js <- strip_js_comments(
    paste(readLines("www/app.js", warn = FALSE), collapse = "\n"))
  grepl('addCustomMessageHandler("dsapp:lit_go"', js, fixed = TRUE) &&
    grepl("dsappIds.litGo", js, fixed = TRUE) &&
    !grepl('"chat-lit_go"', js, fixed = TRUE)
})
chk("★★ mod_chat 把 litGo 的名字下发给了前端", {
  src <- paste(readLines("R/mod_chat.R", warn = FALSE), collapse = "\n")
  grepl('litGo         = ns("lit_go")', src, fixed = TRUE)
})
chk("★★★ 技能勾选框用的是 Shiny 自带的绑定，不是手写的 checkbox", {
  # ⚠️ 手写过一版：手写的 <input type="checkbox"> Shiny **不会**自动收成
  #    一个 input，得自己挂 JS 去 setInputValue，还要处理"renderUI 重画
  #    之后监听器没了"和"HTML 上写死的 checked 服务端并不知道"两件事。
  #    而且 checkboxGroupInput() **没有 `...`** —— 多传一个 class= 就是
  #    "unused argument"，renderUI 当场报错、整块渲染成空（技能列表一条
  #    都没有，页面上还看不出为什么）。踩过。
  src <- paste(readLines("R/mod_lit.R", warn = FALSE), collapse = "\n")
  grepl("checkboxGroupInput(", src, fixed = TRUE) &&
    !grepl('tags$input(type = "checkbox"', src, fixed = TRUE)
})
chk("★★★ 没有给 checkboxGroupInput 传 class（它没有 `...`，传了就是报错）", {
  # ⚠️ checkboxGroupInput() 的签名里**没有 `...`**（selectInput 有）。
  #    多传一个 class= 是 "unused argument"，renderUI 当场抛错、整块
  #    uiOutput 渲染成空 —— 表现是"技能列表一条都没有"，而页面上看不出
  #    为什么。要加类名就自己包一层 div（本文件就是这么做的）。
  #    对照：selectInput / textInput 那几处传 width=、placeholder= 是合法的，
  #    所以这条只盯 checkboxGroupInput 这一个调用点。
  # ⚠️ 剥注释。上一条断言（"技能勾选框用的是 Shiny 自带的绑定"）的说明里
  #    就写着 checkboxGroupInput() 没有 `...`、多传 class= 会怎样；而
  #    mod_lit.R 里那段 ⚠️ 注释也**正着**举了 `class = "dsapp-lit-skills"`
  #    这个反例。不剥的话，`substr(...)` 从**注释里**那个调用开始截，
  #    截到的 400 字里当然有 class —— 断言永远红，代码却是对的。
  src <- strip_comments(
    paste(readLines("R/mod_lit.R", warn = FALSE), collapse = "\n"))
  # 取这个调用开头往后 400 字，再看里面有没有 class=
  i <- regexpr("checkboxGroupInput(", src, fixed = TRUE)
  call <- substr(src, i, i + 400L)
  i > 0 && !grepl("class", call, fixed = TRUE)
})
chk("★ 年份留空写的是空串，不是 NA", {
  # ⚠️ value = NA 会被渲染成 value="NA"，<input type="number"> 解析不了，
  #    浏览器每次渲染都报一句 'The specified value "NA" cannot be parsed'。
  #    不致命，但每开一次这页就刷一条，真出问题时会被埋掉。
  #
  # ⚠️ 同样要剥注释：那段 ⚠️ 说明里**正着**写了 "不能写 `value = NA`"。
  src <- strip_comments(
    paste(readLines("R/mod_lit.R", warn = FALSE), collapse = "\n"))
  grepl('numericInput(ns("year_from"), NULL, value = ""', src, fixed = TRUE) &&
    !grepl("value = NA", src, fixed = TRUE)
})

# =============================================================================
section("V13.11 item 7：服务端不应答时前端要能自己发现")
# =============================================================================
#
# 用户原话：「刚才页面卡住了，刷新后正常了，看一下是程序的问题还是浏览器的
# 问题，请debug」。
#
# 复现（tests/ui_v1311/probe_wedge.py，`kill -STOP` 冻住 R worker）：修之前
# isConnected() 一直是 true、Shiny 自带遮罩不出现、shiny:disconnected 也不
# 触发、控制台一条报错都没有 —— 二十秒里页面看着完全正常，点什么都石沉大海。
#
# 根因：所有断线检测都挂在 socket 的 close 事件上，而"对端没了/进程冻住"时
# TCP 根本不发 FIN/RST，close 永远不来。所以判据只能是"它多久没吭声"。
#
# 下面这一组盯的就是这条心跳链路的**两端对得上**：服务端按点发、前端按点判，
# 而且判死的那个数必须明显大于发送间隔。
{
  a <- paste(readLines("app.R", warn = FALSE), collapse = "\n")
  js <- paste(readLines("www/app.js", warn = FALSE), collapse = "\n")
  jsc <- strip_js_comments(js)

  chk("★★★ app.R 里有一条按 DSAPP_PING_MS 发 dsapp:ping 的心跳", {
    grepl('sendCustomMessage("dsapp:ping"', a, fixed = TRUE) &&
      grepl("invalidateLater(DSAPP_PING_MS", a, fixed = TRUE)
  })

  chk("★★★ 心跳那条 observe **不读任何 reactive**（读了就是自失效，定时器会瞬间烧穿）", {
    # 取那条 observe 的整段，看它有没有读 input$ / 某个 reactiveVal()。
    # ⚠️ 同一个坑在本仓库踩过不止一次（见 R/uiprefs.R 顶部那条）：
    #    症状不是"卡死"，是定时器连着跑几拍然后**静默停掉**。
    #
    # ⚠️ 这里**不能**用 `return(FALSE)` 提前退出。chk() 是把 cond 当 promise
    #    在**调用方**的 frame 里求值的（tryCatch(isTRUE(cond))），而这里是
    #    脚本顶层 —— 没有函数可返回，return() 会抛 "no function to return
    #    from"，被 tryCatch 接住、报成一条**带错误信息**的失败。断言红得
    #    莫名其妙，而真正的原因只是写法不对。用 if/else 给值。
    i <- regexpr("observe\\(\\{\\s*\\n\\s*invalidateLater\\(DSAPP_PING_MS",
                 a, perl = TRUE)
    if (i < 0) {
      FALSE
    } else {
      blk <- substr(a, i, i + 500L)
      # 只留 observe 体：截到第一个收尾的 "})" 为止（后面是别的 observe，
      # 不切掉的话它们的注释也可能带 input$ / state$，那就测错对象了）
      blk <- sub("\n\\s*\\}\\)[\\s\\S]*$", "", blk, perl = TRUE)
      !grepl("input\\$", blk) &&
        # state$xxx 也可能是 reactiveVal —— 这一条只许碰 session
        !grepl("state\\$", blk)
    }
  })

  chk("★★★ DSAPP_PING_MS 在 config.R 里，是个正经的正整数", {
    file.exists("R/config.R") &&
      # ⚠️ `(?m)` 不能省：PCRE 里不带它时 ^ $ 锚的是**整个字符串**的头尾，
      #    而这里是把整个文件拼成一行再匹配的 —— 那样永远匹配不上，断言恒假。
      grepl("(?m)^DSAPP_PING_MS <- [0-9]+L?$",
            paste(readLines("R/config.R", warn = FALSE), collapse = "\n"),
            perl = TRUE) &&
      is.numeric(DSAPP_PING_MS) && length(DSAPP_PING_MS) == 1L &&
      DSAPP_PING_MS >= 1000 && DSAPP_PING_MS <= 30000
  })

  chk("★★★ 前端判死时间**明显大于**服务端心跳间隔（否则网络抖一下就误报一片遮罩）", {
    m <- regmatches(jsc, regexpr("DSAPP_PING_DEAD_MS = [0-9]+", jsc))
    if (!length(m)) {
      FALSE
    } else {
      dead <- as.numeric(sub(".*= ", "", m))
      # 至少要能连着丢两拍才算数；现在是 30s vs 4s（丢 7 拍）。
      # 也不能大到用户都以为页面死了它还不吭声。
      # ⚠️ 2026-10-07：16s → 30s（用户反馈"提示别这么频繁"）。判死线现在
      #    只管"要不要出小条"，铺整页卡片是 DSAPP_OFFLINE_CARD_MS 的事 ——
      #    所以这个上限（10 拍）仍然是"多久之后总该有人说话"的意思。
      dead >= DSAPP_PING_MS * 2 && dead <= DSAPP_PING_MS * 10
    }
  })

  chk("★★★ 前端记心跳用的是**单调**的时刻，而且收到的每一拍都刷新它", {
    grepl("dsappLastPing = Date.now()", jsc, fixed = TRUE) &&
      # 收到心跳那一支必须刷新时刻，否则第一拍之后就一直判死
      grepl('addCustomMessageHandler("dsapp:ping"', jsc, fixed = TRUE)
  })

  chk("★★★ 看门狗在标签页切到后台时不计时（后台定时器被降频，会误报）", {
    # Chrome 会把后台标签页的定时器降到分钟级、还会整个冻结/丢弃 ——
    # 那时候"没收到心跳"什么都说明不了，用户切回来第一眼就是一块遮罩。
    grepl("document.hidden", jsc, fixed = TRUE)
  })

  chk("★★★ 遮罩有「服务端没有响应」这一版，而且**只在原因变了**的时候重画", {
    # 不判原因就每 2 秒重画一次的话，用户的鼠标会停在正在被删掉的按钮上。
    # ⚠️ 2026-10-07：判死那一支改调 dsappOfflineWarn（只出小条），卡片由
    #    「详情」/ 自愈 / 撑够时间三条路铺 —— 所以这里钉的是"有 silent 这一档
    #    的文案"，不再是"看门狗直接调 Show"（那条现在是**反向**断言，
    #    见下面「判死那一支只出小条」）。
    grepl('dsappOfflineWarn("silent")', jsc, fixed = TRUE) &&
      grepl("服务端没有响应", jsc, fixed = TRUE) &&
      grepl('getAttribute("data-kind") === kind', jsc, fixed = TRUE)
  })

  chk("★★ 恢复之后遮罩要能**自己消失**（不许变成「必须刷新」）", {
    # 一个"提醒"变成"锁死"是最糟的结果。心跳回来就撤掉 silent 那一块。
    #
    # ⚠️ V16.11 item 1：这条原来 grep 的是 `getAttribute("data-kind") === "silent"`,
    #    也就是"心跳处理器在读**那块卡片**在不在"。加了「先等一下」的小条之后
    #    那个写法本身就是 bug（卡片被收起来 ⇒ 拿到 null ⇒ 服务端活过来了小条
    #    却永远撤不掉），判据必须改成读**状态**。字面量跟着换，语义不变：
    #    仍然是"心跳回来 → 撤掉 silent"。
    grepl('window.dsappNet.state === "silent") dsappOfflineHide()',
          jsc, fixed = TRUE) &&
      grepl("dsappOfflineHide()", jsc, fixed = TRUE)
  })

  chk("★★ 只撤 silent，不碰 disconnected（连接真断了时心跳可能还在管道里）", {
    # ⚠️ 判据必须**钉在心跳处理器那一段里面**。V16.11 item 1 之后
    #    `kind === "silent"` 这个字面量在别处也出现了（dsappOfflineMini 的文案、
    #    dsappOfflineShow 的 silent 形参），全文件 grep 它恒为真 —— 一条永远
    #    通过的检查比没有检查更糟，它会训练人忽略红色输出。所以先抠出
    #    `dsapp:ping` 那个 handler 的**函数体**，再在里面找。
    m <- regexpr('addCustomMessageHandler\\("dsapp:ping",\\s*function\\s*\\([^)]*\\)\\s*\\{',
                 jsc)
    seg <- dsapp_block_at(jsc, m)
    if (!nzchar(seg)) cat("       抠不出 dsapp:ping 的 handler 体\n")
    nzchar(seg) &&
      grepl('window.dsappNet.state === "silent"', seg, fixed = TRUE) &&
      # 反向：这一段里**不许**出现 down —— 连接真断了时心跳也可能正好还有
      # 一个在管道里，撤掉就骗人了。
      !grepl('"down"', seg, fixed = TRUE)
  })

  # ---- V16.11 item 1：「先等一下」那个洞 ------------------------------------
  #
  # ⚠️⚠️ 下面这几条一律先抠出**函数本体**再查，不用 `substr(jsc, i, i+600L)`
  #    这种定长窗口。第一版就是定长窗口，当场两处假红：窗口越过了函数结尾，
  #    把**下一个**函数里的 `dsappNetSet` / `"down"` 算了进来 —— 报的是
  #    "Dismiss 碰了状态"、"ping 里出现了 down"，而源码里根本没有。
  #    定长窗口在本仓栽过一次（见 [[regex-on-source-silently-shifts]]）：
  #    窗口大小是跟着注释长度走的，改了注释它就悄悄指向别处。
  js_fn <- function(nm) {
    m <- regexpr(paste0("function ", nm, "\\s*\\([^)]*\\)\\s*\\{"), jsc)
    dsapp_block_at(jsc, m)
  }
  # 那颗按钮原来接 dsappOfflineHide() —— 把遮罩**整个删掉**、状态归 up、页面
  # 看着完好，而 socket 还死着。用户接着打字点发送，全打进那个没人排空的池子
  # （`$pendingMessages` 只在 socket.onopen 里 flush，而本应用从没调过
  # session$allowReconnect）。**"提醒"于是变成了"骗人"** —— 比一开始就挡住
  # 他更糟，因为他以为没事了。
  chk("★★★「先等一下」接的是 Dismiss，**不是** Hide（这是那个洞的本体）", {
    # 找那颗按钮那一行（onclick 里写的就是这个函数名），逐字比对。
    # ⚠️ 不能只 grep "dsappOfflineDismiss" 就算过：那个名字在注释和函数定义里
    #    都有，源码扫注释是本仓栽过三次的坑，而且**注释里写着一句话不代表
    #    按钮接的就是它**。
    hit <- grepl("onclick=\"dsappOfflineDismiss()\">先等一下", jsc, fixed = TRUE)
    back <- grepl("onclick=\"dsappOfflineHide()\">先等一下", jsc, fixed = TRUE)
    if (back) cat("       那个洞被改回去了：按钮又接回 dsappOfflineHide()\n")
    hit && !back
  })

  chk("★★★ 收到 Dismiss 之后**状态不许改成 up**（改了就等于骗人）", {
    body <- js_fn("dsappOfflineDismiss")
    if (!nzchar(body)) cat("       抠不出 dsappOfflineDismiss 的函数体\n")
    nzchar(body) &&
      grepl("dsappOfflineMini", body, fixed = TRUE) &&     # 收成小条
      !grepl("dsappNetSet", body, fixed = TRUE)            # 但**不碰状态**
  })

  chk("★★ 两个指示不会同时挂出来（大卡片回来时先把小条撤掉）", {
    body <- js_fn("dsappOfflineShow")
    if (!nzchar(body)) cat("       抠不出 dsappOfflineShow 的函数体\n")
    nzchar(body) && grepl("dsappOfflineMiniClear()", body, fixed = TRUE)
  })

  chk("★★ 真的好了（Hide）的时候小条也要撤掉", {
    body <- js_fn("dsappOfflineHide")
    if (!nzchar(body)) cat("       抠不出 dsappOfflineHide 的函数体\n")
    nzchar(body) && grepl("dsappOfflineMiniClear()", body, fixed = TRUE)
  })

  # ⚠️ 小条**常驻**在页面上。吃掉鼠标的话，左下角那块区域（左侧栏底部、
  #    状态栏）会莫名点不动 —— 又一个"看起来是页面坏了"。它是指示，不是遮罩。
  chk("★★★ 小条不吃鼠标（pointer-events: none），只有「详情」那一颗例外", {
    blk <- css_rule("#dsapp-offline-mini")
    has_none <- grepl("pointer-events: none", blk, fixed = TRUE)
    # 详情按钮自己那条规则里要把点击还回来（选择器里带 -mini-btn）
    btn <- css_rule("#dsapp-offline-mini .dsapp-offline-mini-btn")
    if (!has_none) cat("       小条没关掉 pointer-events，会挡住左下角的点击\n")
    if (!grepl("pointer-events: auto", btn, fixed = TRUE)) {
      cat("       「详情」按钮没把点击要回来，那颗按钮点不动\n")
    }
    has_none && grepl("pointer-events: auto", btn, fixed = TRUE)
  })

  chk("★ 小条的 z-index 也压得过 Shiny 自带的断线遮罩（99998）", {
    blk <- css_rule("#dsapp-offline-mini")
    zi <- suppressWarnings(as.numeric(sub(".*z-index\\s*:\\s*([0-9]+).*", "\\1",
            grep("z-index", strsplit(blk, "\n")[[1]], value = TRUE))))
    if (length(zi) != 1L || is.na(zi) || zi <= 99998) {
      cat("       小条的 z-index =", if (length(zi)) zi[1] else "取不到", "\n")
    }
    length(zi) == 1L && !is.na(zi) && zi > 99998
  })

  chk("★★ 心跳看门狗也不许读卡片（读状态，且 down 不许被降级成 silent）", {
    # 原来读 `document.getElementById("dsapp-offline")`：用户"先等一下"之后
    # 卡片不在 ⇒ 每 2 秒把大卡片重新弹回来一次，那颗按钮等于白点。
    m <- regexpr("if \\(Date\\.now\\(\\) - dsappLastPing > DSAPP_PING_DEAD_MS\\)\\s*\\{",
                 jsc)
    seg <- dsapp_block_at(jsc, m)
    if (!nzchar(seg)) cat("       抠不出心跳看门狗那个 if 块\n")
    nzchar(seg) &&
      grepl("dsappNet.state", seg, fixed = TRUE) &&
      # 反向：这一段里**不许**再出现 `getElementById("dsapp-offline")`
      !grepl('getElementById("dsapp-offline")', seg, fixed = TRUE) &&
      # 而且 down 那一档必须显式排除掉（写 `!== "up"` 就是同一类错：
      # silent 也没恢复，只是换个说法）
      grepl('st !== "down" && st !== "silent"', seg, fixed = TRUE)
  })

  # ★★★ 2026-10-07 用户反馈：「服务器现在还是经常未响应，这个提示能不能显示的
  #     不要这么频繁，即使真的断了，也请间隔一段时间再提示」。
  #     改法是**分两档出场**：判死只出左下角小条（不遮页面、不挡点击），
  #     再撑 DSAPP_OFFLINE_CARD_MS 才铺那张盖住整页的卡片。
  #     ⚠️ 这几条全是**反向**断言 —— 要修掉的正是"一判死就盖住整页"那个形状。
  chk("★★★ 判死那一支**只出小条**，不许直接铺整页卡片", {
    m <- regexpr("if \\(Date\\.now\\(\\) - dsappLastPing > DSAPP_PING_DEAD_MS\\)\\s*\\{",
                 jsc)
    seg <- dsapp_block_at(jsc, m)
    if (!nzchar(seg)) cat("       抠不出心跳看门狗那个 if 块\n")
    nzchar(seg) &&
      grepl('dsappOfflineWarn("silent")', seg, fixed = TRUE) &&
      # 反向：这一段里出现 dsappOfflineShow 就是"一判死就盖住整页"，
      # 正是用户抱怨的那个形状（改之前就是这样）。
      !grepl("dsappOfflineShow(", seg, fixed = TRUE)
  })

  chk("★★★ 整页卡片的出场时间 DSAPP_OFFLINE_CARD_MS 是个正经的间隔", {
    m <- regmatches(jsc, regexpr("DSAPP_OFFLINE_CARD_MS = [0-9]+", jsc))
    if (!length(m)) {
      FALSE
    } else {
      d <- as.numeric(sub(".*= ", "", m))
      # 下限：至少得比**一拍心跳**长，否则等于没延迟。
      # 上限 5 分钟：再长就等于真断了也不告诉人。
      # ⚠️ 不需要比判死线大 —— 它计的是"离开 up 之后又过了多久"，
      #    和判死线（"多久没收到心跳"）是两个量，起算点都不一样。
      d >= DSAPP_PING_MS && d <= 300000
    }
  })

  chk("★★★ 铺卡片那条路**必须**问过「先等一下」（不然那颗按钮白点）", {
    m <- regexpr("function dsappOfflineEscalate(st) {", jsc, fixed = TRUE)
    seg <- dsapp_block_at(jsc, m)
    if (!nzchar(seg)) cat("       抠不出 dsappOfflineEscalate\n")
    nzchar(seg) && grepl("dsappCardDismissed", seg, fixed = TRUE) &&
      grepl("DSAPP_OFFLINE_CARD_MS", seg, fixed = TRUE)
  })

  chk("★★★ 用户点「先等一下」要真的记下来", {
    m <- regexpr("function dsappOfflineDismiss() {", jsc, fixed = TRUE)
    seg <- dsapp_block_at(jsc, m)
    if (!nzchar(seg)) cat("       抠不出 dsappOfflineDismiss\n")
    nzchar(seg) && grepl("dsappCardDismissed = true", seg, fixed = TRUE)
  })

  chk("★★★ 回到 up 时断电时钟和「先等一下」都归零（不然下一轮哑火）", {
    # 这一条盯的是"收尾只写在状态那个唯一入口里"：归零写在别处的话，
    # 下一次断线会带着上一轮的时钟（卡片一上来就超时）和上一轮的"别弹了"。
    m <- regexpr("function dsappNetSet(state, why) {", jsc, fixed = TRUE)
    seg <- dsapp_block_at(jsc, m)
    if (!nzchar(seg)) cat("       抠不出 dsappNetSet\n")
    nzchar(seg) &&
      grepl("dsappOutageSince = Date.now()", seg, fixed = TRUE) &&
      grepl("dsappOutageSince = 0", seg, fixed = TRUE) &&
      grepl("dsappCardDismissed = false", seg, fixed = TRUE)
  })

  chk("★★★ 自愈有话要说时，卡片**必须**先在（那几句话不能写进空气里）", {
    # 卡片现在是延迟出现的，而自愈第一次开口在 DSAPP_HEAL_GRACE_MS 之后 ——
    # 那一刻卡片多半还没铺。少了这句，"它一回来这页会自己刷新"就没人看见。
    m <- regexpr("function dsappHealNote(msg) {", jsc, fixed = TRUE)
    seg <- dsapp_block_at(jsc, m)
    if (!nzchar(seg)) cat("       抠不出 dsappHealNote\n")
    nzchar(seg) && grepl('getElementById("dsapp-offline")', seg, fixed = TRUE) &&
      grepl("dsappOfflineShow(", seg, fixed = TRUE)
  })

  # ★★ 这条是踩出来的：Shiny.addCustomMessageHandler() 注册时就在查
  #    `handler.length !== 1`，写成 function () 会**加载时同步抛**，
  #    于是文件里排在它后面的每一个 handler / 事件绑定都不再注册 ——
  #    症状是"左侧栏点了不切页、下载点了没反应"，而报错内容跟这些毫不相干。
  #    写心跳的时候就是这么写的，测试当场抓到（心跳压根没注册上）。
  chk("★★★ 所有 addCustomMessageHandler 都声明了**恰好一个**参数", {
    bad <- character(0)
    for (ln in strsplit(jsc, "\n")[[1]]) {
      if (!grepl("addCustomMessageHandler\\(", ln)) next
      m <- regmatches(ln, regexpr(
        "addCustomMessageHandler\\([^,]+,\\s*function\\s*\\(([^)]*)\\)", ln))
      if (!length(m)) next
      args <- trimws(sub(".*\\(([^)]*)\\)$", "\\1", m))
      if (!nzchar(args)) bad <- c(bad, trimws(ln))
    }
    if (length(bad)) cat("       0 个参数的：", paste(bad, collapse = " | "), "\n")
    length(bad) == 0
  })

  chk("★★ 遮罩文案里没有漏出来的 Markdown 星号（那是 HTML 不是 Markdown）", {
    # 这里是拼 HTML 字符串，写 **这样** 会原样显示成带星号的字。
    # （第一版就是这么写的，渲染出来是"浏览器这边**分不出来**"。）
    i <- regexpr("function dsappOfflineShow", jsc, fixed = TRUE)
    if (i < 0) {
      FALSE
    } else {
      !grepl("**", substr(jsc, i, i + 1600L), fixed = TRUE)
    }
  })
}

section("V13.11 item 8：更新按钮置底 + 离开时提醒未确认的改动（判据见 V13.12 item 19）")

{
  # ⚠️ jsc 是上面那个块里的局部变量，这里拿不到 —— 自己再剥一遍。
  #    两个块都在读同一个文件，但共享变量会让"上面那块挪走了"变成这里的
  #    静默失效（拿不到 jsc 就直接报错，至少是响的；拿不到的是上个版本的
  #    快照才是真的糟）。
  jsc  <- strip_js_comments(paste(readLines("www/app.js", warn = FALSE),
                                  collapse = "\n"))
  mdl  <- strip_comments(paste(readLines("R/mod_model.R", warn = FALSE),
                               collapse = "\n"))
  appc <- strip_comments(paste(readLines("app.R", warn = FALSE), collapse = "\n"))

  # ---- (a) 按钮挪到最底部 --------------------------------------------------
  # 判据是**位置**，不是"存不存在"：这个按钮一直都在，item 8 要的就是它换个位置。
  # 拿"生成参数"那一块和 base_url 当两个路标 —— 按钮必须排在它俩**后面**。
  #
  # ⚠️ 路标在 V13.15 item 26 换过一次写法。原来这里 grep 的是内联字面量
  #    `actionButton(ns("commit"))`，item 26 把底部那颗也改成 `commit_btn()`
  #    画出来的（头尾两颗必须共用一份 markup，否则改一处忘一处），字面量就
  #    没了 —— 路标返回 -1，下面三条"排在……之后"**全部**变成 -1 > 正数 = FALSE，
  #    红是红了，但红的是路标、不是位置，容易看反。
  #    所以这里改成认**调用点** `commit_btn("commit", ...)`；顺带补一条反向断言，
  #    免得哪天有人把内联写法又抄回来（那就是两份 markup，头尾会各改各的）。
  i_commit <- regexpr('commit_btn\\("commit", "commit_hint"\\)', mdl)
  i_params <- regexpr('dsapp-model-params', mdl)
  i_base   <- regexpr('textInput\\(ns\\("base_url"\\)', mdl)
  chk("★★ 底部那颗是 commit_btn() 画的（内联 actionButton 写法没有偷偷回来）",
      !grepl('actionButton\\(ns\\("commit"\\)', mdl))
  chk("★ 三个路标都找得到（找不到的话下面几条会静默通过）",
      i_commit > 0 && i_params > 0 && i_base > 0)
  chk("★★★ 更新/确认按钮排在「生成参数」**之后**（用户原话「可以在最底部」）",
      i_commit > i_params)
  chk("★★ 也排在「接口地址」之后（原来它夹在地址和参数中间）",
      i_commit > i_base)
  # 那块 div 到 tagList 结束之间不该还有别的控件 —— 有的话按钮就不在底部了。
  tailmod <- substr(mdl, i_commit, nchar(mdl))
  chk("★★ 按钮后面没有别的输入控件了（否则只是「挪了挪」、没到底）",
      !grepl("textInput\\(|selectInput\\(|selectizeInput\\(|passwordInput\\(",
             tailmod))

  # ---- (b) 「离开」这个信号：V13.12 item 19 之后是**切页** ---------------
  #
  # ⚠️ 这一小节整段换过。V13.11 那会儿模型服务是左栏一块常驻的 <details>，
  #    "离开"只能是把它收起，于是前端要捕获阶段监听 toggle、要用递增计数
  #    上报、还要屏蔽服务端自己那一次收起（不然是个关不掉的循环）。
  #    搬成独立页之后这**一整套都不需要了** —— 切页本来就有一条现成的信号
  #    （input$nav），而那几段前端代码连同那块 <details> 一起删掉了。
  #    所以下面这些断言是**反着**写的：它们盯的是"那套东西没有偷偷回来"。
  chk("★★★ 那块 <details> 和它的前端上报都删干净了（没有半截留着）",
      !grepl("dsapp-rail-model", jsc, fixed = TRUE) &&
      !grepl("dsappRailSeq", jsc, fixed = TRUE) &&
      !grepl("dsappRailQuiet", jsc, fixed = TRUE) &&
      !grepl("rail_model_closed", jsc, fixed = TRUE) &&
      !grepl("dsapp-rail-model", appc, fixed = TRUE))
  chk("★★★ 那三个删掉的按钮不再发 dsapp:rail-model（发了也没人接）",
      !grepl('"dsapp:rail-model"', mdl, fixed = TRUE) &&
      # 但摘要行那一条**保留**，只是改名成 dsapp:rail-sub
      grepl('sendCustomMessage("dsapp:rail-sub"', mdl, fixed = TRUE) &&
      grepl('addCustomMessageHandler("dsapp:rail-sub"', jsc, fixed = TRUE))

  # ---- (c) 顶层把当前页转给模块（模块读不到顶层 input）---------------------
  # ⚠️ 模块里的 input$xxx 会自动加命名空间前缀，前端又不知道前缀是什么 ——
  #    所以必须由顶层收下再经 state 转过去。少了这一环，模块永远不知道
  #    用户切走了，提醒就成了哑炮（不报错、什么都不发生）。
  #
  # ⚠️ 顺带一条：这条 state$nav 必须发布在**既有的**那个 input$nav observer
  #    里，不能新开一个 —— 新开的那个也要 `ignoreNULL = FALSE`，漏了的话
  #    启动时那一次（input$nav 还是 NULL）不触发，第一次切页的"上一页"
  #    就丢了。查法：nav observer 那一块里同时有 state$nav 和 dsapp:nav。
  blk_nav <- regmatches(appc, regexpr(
    "(?s)observeEvent\\(input\\$nav, \\{.*?\\n  \\}, ignoreNULL = FALSE\\)",
    appc, perl = TRUE))
  chk("★★★ app.R 把当前页发布进 state（模块读不到顶层 input$nav）",
      length(blk_nav) == 1 && nzchar(blk_nav) &&
      grepl("state$nav <- v", blk_nav, fixed = TRUE) &&
      grepl('sendCustomMessage("dsapp:nav"', blk_nav, fixed = TRUE) &&
      # 前端高亮用的还是同一个值，两处不能各算各的
      grepl('as.character(input$nav %||% "chat")', blk_nav, fixed = TRUE))
  chk("★★ mod_model 那边盯着 state$nav，而且是**记上一次值**来判离开",
      grepl("observeEvent(state$nav, {", mdl, fixed = TRUE) &&
      grepl("nav_seen <- reactiveVal(NULL)", mdl, fixed = TRUE) &&
      # ⚠️ 直接拿 state$nav 跟 "model" 比是错的：别的页之间互切也会进这个
      #    observer，"离开模型服务页"和"在别的页之间跳"分不开。
      grepl('if (!identical(prev, "model")) return()', mdl, fixed = TRUE))

  # ---- (d) 判据：快照对比，不是"跟库里的值比" ------------------------------
  # ⚠️ 这一条是这版最容易写错的地方。库里的值要过一轮归一化才进控件
  #    （厂商停用→回落 deepseek；模型不在清单→补一组；空模型名→取第一个），
  #    拿控件直接跟库比，一个**从没配过**的用户一打开就是"脏"的 —— 每收一次
  #    面板弹一次框。快照比的是控件值 vs 控件值，躲开全部归一化。
  chk("★★★ 判据用的是快照（snap），不是直接跟库里的值比",
      grepl("snap <- reactiveVal(NULL)", mdl, fixed = TRUE) &&
      grepl("changed_fields <- function()", mdl, fixed = TRUE))
  chk("★★ 快照在**保存成功之后**会刷新（不刷的话刚点完更新就被问「还没确认」）",
      grepl("snap(list(vendor   = input$vendor", mdl, fixed = TRUE))
  # ⚠️ 记快照那个 observe 必须**先读完四个 input 再判空**：读才是建立依赖，
  #    把判空写前面的话第一次跑就直接返回、一个依赖都没建，以后值到了也不会
  #    再跑 —— 快照永远 NULL，提醒永远不响（而且不报任何错）。
  i_obs  <- regexpr("snap(list(vendor", mdl, fixed = TRUE)
  i_lead <- regexpr("v <- input\\$vendor", mdl)
  i_guard <- regexpr("is.null(isolate(snap()))", mdl, fixed = TRUE)
  chk("★★★ 记快照的 observe 先读 input 再判空（顺序反了就永远不记）",
      i_lead > 0 && i_guard > 0 && i_lead < i_guard && i_guard < i_obs)
  chk("★★ 密码框被**程序**清空时也刷快照（那不是用户的改动，不该弹框）",
      grepl('api_key  = ""', mdl, fixed = TRUE))

  # ---- (d2) 服务端自己写进控件的值，不算用户的改动（V13.12 item 20）--------
  #
  # 现场（是**跑出来的**，不是想出来的）：填好 Key 和接口地址 → 点「更新」→
  # 界面说"已保存，可直接用" → 切到对话页，却被问「模型改了还没确认」。
  # 用户一个字都没动。
  #
  # 成因：点「更新」会顺手拉一次厂商的模型清单（start_verify），清单回来时
  # 选中的名字不在里面（静态清单的默认名 vs 中转站只认自己那几个），
  # observeEvent(model_choices()) 就把它换成了清单头一个 —— 而快照还停在
  # 旧名字上。changed_fields() 只看"控件当前值 vs 快照"，分不清那值是谁写的。
  #
  # ⚠️ 判据是"**每一个**程序式写入点都跟着刷了快照"，不是"有没有 snap_one
  #    这个函数"—— 函数在、少调一处，就漏一处误报。
  chk("★★★ 服务端程序式写控件时会同步快照（snap_one）",
      grepl("snap_one <- function(key, value)", mdl, fixed = TRUE) &&
      # ⚠️ 读快照那一下必须 isolate：裸读 = 自己写、自己失效、自己再跑一轮
      grepl("s0 <- isolate(snap())", mdl, fixed = TRUE))
  chk("★★★ 六个程序式写入点一个不落（漏一处就是一处误报）",
      grepl('snap_one("api_key", rec$api_key %||% "")', mdl, fixed = TRUE) &&
      grepl('snap_one("base_url", rec$base_url)', mdl, fixed = TRUE) &&
      grepl('snap_one("model", rec$model)', mdl, fixed = TRUE) &&
      grepl('snap_one("model", mg$model)', mdl, fixed = TRUE) &&
      grepl('snap_one("model", after)', mdl, fixed = TRUE) &&
      # ⚠️ 这一处（换厂商时把厂商默认地址填上去）是**实测**补上的：漏了它，
      #    只是换了个厂商，提醒框里就多出一条「接口地址」。
      grepl('snap_one("base_url", b2)', mdl, fixed = TRUE))
  # ⚠️ 换厂商那一次**只刷三格，不刷厂商那一格**：厂商确实是用户改的，提醒该
  #    不该弹就看它。一起刷掉的话，换了厂商反而不提醒了 —— 那正是这个功能
  #    存在的理由（换了厂商，左栏那行小字要等点了「更新」才跟着变）。
  chk("★★ 换厂商只刷它带过来的三格，厂商那一格留着（不然就不提醒了）",
      !grepl('snap_one("vendor"', mdl, fixed = TRUE))
  # ⚠️ 清单刷新那一处的判据是"**推下去之后控件里会是什么值**"，不是"cur 有没有
  #    被改过"。这两个不等价，也是实测出来的：有一类厂商（中转站那种）静态目录
  #    里一个模型都没有，flat 是空的 —— cur 原样留着旧名字，但新选项里没有它，
  #    selectize 把值**丢掉**，控件变空。按"cur 变没变"判的话这里什么都不做，
  #    而控件已经从 mock-slow 变成空了，切页照样是一句「模型改了还没确认」。
  chk("★★ 清单刷新按「控件里最终会是什么值」判，不是「cur 变没变」",
      grepl('after <- if (cur %in% flat) cur else ""', mdl, fixed = TRUE) &&
      grepl("if (!identical(after, isolate(input$model) %||% \"\")) {",
            mdl, fixed = TRUE))
  # ⚠️ 快照的定义 + 首次记快照，必须注册在"状态同步到会话"那个 observe
  #    **之前**：那个 observe 会按 dsapp_model_migrate() 把旧模型名改写后推给
  #    浏览器，两者同一轮触发 —— 晚注册的话快照记的是改写**前**的值，浏览器
  #    随后报上改写后的值，于是"什么都没动却被问了一句模型改了还没确认"。
  #    （这里拿那个 observe 的首行当锚，别拿中文小标题：小标题在注释里出现过）
  #    ⚠️ Test_V15.4 item 1 换了锚：那一行原来是
  #       `v <- input$vendor %||% "deepseek"`，现在拆成了"先读、再判空
  #       return"两行（`%||%` 挡不住空串，见 R/utils.R）。拿旧字面量当锚的话
  #       i_sync 恒为 -1，这条断言会**永远为假** —— 而它报出来是"顺序反了"，
  #       把人指到完全无关的地方。改用那个 observe 里唯一的一行。
  i_def  <- regexpr("snap <- reactiveVal(NULL)", mdl, fixed = TRUE)
  i_sync <- regexpr("supports <- dsapp_vendor_supports_thinking(v)", mdl,
                    fixed = TRUE)
  chk("★★★ 快照的定义排在「状态同步到会话」之前（晚注册 = 首次快照记错值）",
      i_def > 0 && i_sync > 0 && i_def < i_sync)
  # ⚠️ 只能定义**一次**。留个重复定义在后面的话，前面那个 observer 往第一个
  #    里写、changed_fields() 读第二个（永远是 NULL）—— 提醒**永远不响**，
  #    而且不报任何错。
  chk("★★★ snap 只定义一次（重复定义会让提醒永远不响，还不报错）",
      length(gregexpr("snap <- reactiveVal(NULL)", mdl, fixed = TRUE)[[1]]) == 1L)

  # ---- (e) 提醒本身 --------------------------------------------------------
  chk("★★★ 有未确认改动时弹确认框", grepl("showModal(modalDialog(", mdl,
                                            fixed = TRUE))
  # ⚠️ 这条以前是"弹框前先把面板摊开"（那会儿它是个能折起来的 <details>）。
  #    搬成独立页之后没有"摊开"这回事了，等价的承诺变成"弹框里那颗按钮
  #    一键跳回那一页" —— 用户看到提醒时人已经在别的页上了，光弹个框
  #    让他自己找回去，等于没提醒。
  chk("★★ 那颗「回去继续编辑」真的会跳回模型服务页（不是只关掉弹框）",
      grepl("dsapp_nav_to(state, \"model\")", mdl, fixed = TRUE) &&
      # ⚠️ 必须走 dsapp_nav_to（顶层 session），不能用模块 session ——
      #    模块 session 上跳页是静默失效的，按钮看着能点、点了没反应。
      !grepl("nav_select(\"nav\", \"model\", session = session)",
             mdl, fixed = TRUE))
  chk("★★ 说清楚**改了哪几样**（只说「有未保存的改动」等于让用户自己回去找）",
      grepl('changed_fields', mdl, fixed = TRUE) &&
      grepl('paste(ch, collapse', mdl, fixed = TRUE))
  # ⚠️ 这两条盯的是**文案跟行为对不对得上**，不是"有没有写够字"。
  #    第一版这里写的是「「更新」之前这些不会生效」—— 假话：四个框都由
  #    observeEvent(pending(), …) 防抖 800ms 自动落库，什么都不点照样生效。
  #    所以判据是"必须承认会自动保存"，并且**不许**出现"不会生效"这种
  #    跟真实行为相反的承诺。
  chk("★★★ 文案说的是真话：承认改动会自动保存（第一版这里写反了）",
      grepl("改动会自动保存", mdl, fixed = TRUE))
  chk("★★★ 不许出现「不会生效」这类跟真实行为相反的承诺",
      !grepl("不会生效", mdl, fixed = TRUE))
  # ⚠️ V13.12 item 19 措辞跟着改了：不再叫"摘要行"，叫"左栏「模型服务」
  #    下面那行小字"（那一项现在在导航栏里，说"摘要行"用户对不上号）。
  #    这两件事仍然是**只有点了「更新」才会发生**的，必须点名。
  # ⚠️ 这里**不能**查 "试一次能不能用" 这种跨行的整句：mdl 是逐行读进来
  #    再用 "\n" 拼起来的，而 R 的字符串字面量在这一行正好断在中间 ——
  #    源码里是 `…去试一次",\n  "能不能用。`，拼出来的文本中间隔着
  #    引号、逗号和一个换行。查整句的写法会红，而它红的样子像"文案没写
  #    这句话"。查两截，各自都在一个字面量里。
  chk("★★ 说清楚点了「更新」才会发生的两件事（导航栏小字 + 试一次 Key）",
      grepl("下面那行小字", mdl, fixed = TRUE) &&
      grepl("要等你点了", mdl, fixed = TRUE) &&
      grepl("去试一次", mdl, fixed = TRUE) &&
      grepl("能不能用", mdl, fixed = TRUE))
  # ⚠️ 文案改叫"小字"了，就得确认**真的有那行小字** —— 否则这句提醒
  #    是在指一个不存在的东西，用户会盯着导航栏找半天。
  chk("★★ 导航栏那一项底下确实有那行小字（文案不能指空）",
      grepl("dsapp-rail-sub", appc, fixed = TRUE) &&
      grepl("data-nav", appc, fixed = TRUE))
  # ⚠️ 承诺必须跟行为一致：这个按钮**只收起、不回滚**（回滚要 updateSelectInput
  #    vendor，会触发"切厂商带 base_url 过去"的观察者，把地址又改掉 —— 点"放弃"
  #    反而多出一次改动）。所以文案里不许出现"放弃"。
  chk("★★★ 那个按钮说的是「收起来」，不是「放弃改动」（文案不许超出行为）",
      !grepl("放弃", mdl, fixed = TRUE))
}

section("V13.11 item 10：以疑问句结尾时要给一颗能点的「继续」")

{
  # ---- (a) 判据本身：纯函数，直接喂字符串 ----------------------------------
  # 用户原话里的那一句，原样拿来当第一条用例。
  ys <- c(
    "我可以直接基于它跑建模，跳过数据准备。要不要继续？",
    "已经跑完质控了。接下来做差异分析吗？",
    "**下一步做富集分析，可以吗？**",
    "方案写好了。需要我继续执行的话说一声。",
    "确认后我就开始跑。"
  )
  ns_ <- c(
    "分析已经完成，结果存在 results/ 目录下。",
    "要不要做批次校正？这取决于你的实验设计，我建议先做。",
    # ⚠️ 这一段是这块最容易写错的地方：代码块里的问号（三元、正则、注释里的
    #    反问）都不是在问用户。不抠掉的话，一段纯代码回复也会亮「继续」。
    paste0("这里是三元表达式：\n```r\nx <- if (a) 1 else 2  # 查 ?mean\n```\n",
           "已经写好了。"),
    "",
    "```python\nprint('hi')\n```",
    # 结尾是交代、问号在很远的地方 —— 只看结尾才拦得住它
    paste0(strrep("这一段是分析说明。", 30), "\n上面提到过要不要加参数。")
  )
  bad_pos <- ys[!vapply(ys, dsapp_asks_confirmation, logical(1))]
  bad_neg <- ns_[vapply(ns_, dsapp_asks_confirmation, logical(1))]
  chk("★★★ 该亮的都亮了（含用户原话那一句）", length(bad_pos) == 0)
  if (length(bad_pos)) cat("       漏了:", paste(substr(bad_pos, 1, 34),
                                                 collapse = " | "), "\n")
  chk("★★★ 不该亮的一个都不亮（代码块里的问号、讲道理的反问、远处的问题）",
      length(bad_neg) == 0)
  if (length(bad_neg)) cat("       误报:", paste(substr(bad_neg, 1, 34),
                                                 collapse = " | "), "\n")
  chk("★ 边界：NULL / NA / 非字符都不许炸", {
    r <- tryCatch(c(dsapp_asks_confirmation(NULL), dsapp_asks_confirmation(NA),
                    dsapp_asks_confirmation(character(0))),
                  error = function(e) "炸了")
    identical(r, c(FALSE, FALSE, FALSE))
  })
  # ⚠️ 这一条钉的是引擎：那个剥尾缀的正则在默认的 TRE 下**一个字符都不剥**
  #    （花括号表达式不认 `\]`，整个类被截断），于是"……可以吗？**"这种
  #    最常见的写法会漏掉。换成 perl 才对。第一版就是这么漏的。
  chk("★★ 结尾的 Markdown 收尾符能剥掉（TRE 下这条会漏）",
      isTRUE(dsapp_asks_confirmation("**下一步做富集分析，可以吗？**")))

  # ---- (b) 接在哪儿：和代码那颗同一个槽位 ---------------------------------
  ch <- strip_comments(paste(readLines("R/mod_chat.R", warn = FALSE),
                             collapse = "\n"))
  chk("★★★ 确认槽位里加了 pending_ask 这条判据",
      grepl("pending_ask <- reactive({", ch, fixed = TRUE))
  # ⚠️ 定位一律用 fixed = TRUE。这个模式里有 ( 和 )，R 默认的正则引擎（TRE）
  #    把裸括号当分组 —— 括号不配对时是**编译失败**（invalid regular
  #    expression, reason 'Missing )'），不是匹配不上。第一版这里写的是
  #    grepl('actionButton(\n … ns("confirm_go"), "继续"')，那个 ( 开了组却
  #    永远闭不上，整条断言直接炸，连"红"都算不上 —— 是运行中断。
  #
  # ⚠️ 取 pending_ask 那一支的窗口再判，不要在全文件里找 "继续"：
  #    这个文件里别处本来就有 `class = "dsapp-btn-run-off"`（那条灰的老路），
  #    全文件搜的话最后那条否定断言恒为假。
  #
  # ⚠️ 窗口的右边界是**下一支**（tags$button 那条灰的老路），不是"往后数
  #    N 个字符"。数 N 的话 N 一大就把老路那句 class = "dsapp-btn-run-off"
  #    圈进来，下面那条否定断言恒为假 —— 而它看起来只是在说"这条没过"。
  i_ask <- as.integer(regexpr("a <- pending_ask()", ch, fixed = TRUE))
  i_next <- if (i_ask > 0L) {
    as.integer(regexpr("tags$button(", substr(ch, i_ask, nchar(ch)),
                       fixed = TRUE))
  } else -1L
  ask_blk <- if (i_ask > 0L && i_next > 1L) {
    substr(ch, i_ask, i_ask + i_next - 2L)
  } else ""
  chk("★★★ 找得到 pending_ask 那一支（找不到的话下面两条会静默通过）",
      nzchar(ask_blk))
  chk("★★★ 没有代码可跑、但它在问话时，渲染的是**能点**的按钮",
      nzchar(ask_blk) &&
        grepl('ns("confirm_go"), "继续"', ask_blk, fixed = TRUE) &&
        !grepl("dsapp-btn-run-off", ask_blk, fixed = TRUE))
  chk("★★ 按钮文字是「继续」不是「确认执行」（不然用户以为要跑一段找不到的代码）",
      grepl('"继续"', ch, fixed = TRUE))
  chk("★ 还是灰着的那条老路没被改坏（没代码也没问句时仍是 disabled 的确认执行）",
      grepl('class = "dsapp-btn dsapp-btn-run dsapp-btn-run-off"', ch,
            fixed = TRUE))
  # ⚠️ 走 dsapp_chat_send 而不是 dsapp_llm_begin：前者有全部闸门
  #    （正在生成中 / 只读共享 / 没配 Key / 没选模型），后者一个都没有 ——
  #    而只读共享那条一旦绕过，就是往 owner 的对话里插消息。
  # ⚠️ 取"这个处理器那一段"再判，不要在全文件里找 dsapp_llm_begin ——
  #    文件里别处本来就有它（正常路径），全文件搜恒为真。
  #    定位用的正则里括号要转义：R 默认是 ERE，裸 ( 是分组，
  #    "observeEvent(input$confirm_go" 里那个没闭合的 ( 会让 TRE 直接报错
  #    （不是匹配不上，是编译失败）。
  i_go <- regexpr("observeEvent\\(input\\$confirm_go", ch)
  go_blk <- if (i_go > 0) substr(ch, i_go, i_go + 200L) else ""
  chk("★★★ 找得到「继续」的处理器（找不到的话下面两条会静默通过）",
      nzchar(go_blk))
  chk("★★★ 点「继续」走的是 dsapp_chat_send（和用户自己打字同一条路）",
      grepl('dsapp_chat_send(extra = "继续")', go_blk, fixed = TRUE))
  chk("★★★ 没有绕过闸门直接开一轮生成",
      nzchar(go_blk) && !grepl("dsapp_llm_begin", go_blk, fixed = TRUE))
  # ⚠️ 生成中不许亮：模型正吐字吐到一半，那条消息的结尾随时会变，
  #    这时候点「继续」等于往一个正在生成的轮次里插话。
  chk("★★★ 正在生成 / 正在跑的时候不给点",
      grepl("isTRUE(rv$streaming) || isTRUE(rv$sending)", ch, fixed = TRUE))
  # ⚠️ 只看最后一条助手消息，不回头翻 —— 翻了就是"永远亮着但不知道指哪句"。
  chk("★★ 只看**最后一条**助手消息（不回头翻历史）",
      grepl("i <- asst[length(asst)]", ch, fixed = TRUE))
  chk("★ 「继续」那颗在 CSS 里有图标对齐的样式（inline-flex，同补点建议）",
      grepl(".dsapp-ask-go", paste(readLines("www/app.css", warn = FALSE),
                                  collapse = "\n"), fixed = TRUE))
}

section("V13.11 item 11：执行历史按「对话 → 里面的每一步」两级展示")

{
  # ---- (a) 重排本身：纯函数，直接喂数据框 ----------------------------------
  # 用户原话：「历史任务也按任务标题名称和内部执行的具体任务进行分级展示」。
  #
  # 先把 DB 真实给的形状摆出来：**ORDER BY id DESC**（新的在上）。会话之间
  # 是交错的 —— 这正是要重排的原因。
  mk <- function(ids, sids) {
    data.frame(id = ids, session_id = sids,
               title = paste0("t", ids), stringsAsFactors = FALSE)
  }
  df <- mk(c(10, 9, 8, 7, 6, 5), c("A", "B", "A", "B", "A", "C"))
  g  <- dsapp_group_tasks(df)

  chk("★★★ 重排后行数不变（少一行就是「有条任务凭空没了」）",
      nrow(g) == nrow(df), sprintf("%d -> %d", nrow(df), nrow(g)))
  # ⚠️ 这条是整块里最重要的。mod_tasks.R 的 selected_ids()/current() 拿
  #    input$tbl_rows_selected 直接去 df$id 取 —— 重排要是顺手去个重、
  #    或者把谁弄丢了，表现是"点第 3 行删掉的是第 4 条"，真的会删错东西。
  chk("★★★ 而且每条都还在（重排不是筛选，一条都不能丢）",
      identical(sort(g$id), sort(df$id)))
  chk("★★★ 同一个会话的行是挨着的（重排的全部意义）",
      length(rle(as.character(g$session_id))$lengths) ==
        length(unique(g$session_id)))
  # 组间按组里最新那条倒序：A 最新是 10、B 是 9、C 是 5 → A, B, C
  # 组内按 id **升序**（执行顺序）。倒着排读起来像倒放。
  chk("★★★ 组间按最新一条倒序、组内按执行顺序升序",
      identical(g$id, c(6, 8, 10, 7, 9, 5)),
      paste(g$id, collapse = ","))
  chk("★ 会话名也一起跟过来了（不是按 id 排完就不管了）",
      identical(as.character(g$session_id), c("A","A","A","B","B","C")))

  # 边界：这几种都不能报错，也不能变形
  chk("★ 空表原样返回", nrow(dsapp_group_tasks(df[0, ])) == 0)
  chk("★ NULL 原样返回", is.null(dsapp_group_tasks(NULL)))
  chk("★ 没有 session_id 这一列时原样返回（不能让它掉进 ave 里报长度不等）",
      identical(dsapp_group_tasks(df[, c("id", "title")])$id, df$id))
  # NA 的 session_id：老库里可能有。当成"同一组"处理，不许把行弄丢。
  dfna <- mk(c(3, 2, 1), c(NA, NA, "Z"))
  gna  <- dsapp_group_tasks(dfna)
  chk("★ session_id 是 NA 时不报错、也不丢行",
      identical(sort(gna$id), c(1, 2, 3)))
  # 单条任务：原样
  one <- dsapp_group_tasks(mk(7, "S"))
  chk("★ 只有一条任务时不动它", identical(one$id, 7))

  # ---- (b) 标题去尾：只在确实是会话名后缀时才去 ----------------------------
  sess <- "帮我做一下ANGPTL2"
  chk("★★ 正常情况：把尾巴上的会话名去掉，只留这一步在干什么",
      identical(dsapp_task_short_title(paste0("跑差异分析_", sess), sess),
                "跑差异分析"))
  # 拼进去的是会话名的**前 24 字**（见 dsapp_task_title），所以长名字要
  # 按 24 字比 —— 拿全名去比永远不相等，表现是"长名字的对话一个都没去尾"。
  long_sess <- strrep("会", 30)
  chk("★★ 会话名超过 24 字时按前 24 字比（拼进去的就是前 24 字）",
      identical(dsapp_task_short_title(paste0("富集分析_", substr(long_sess, 1, 24)),
                                       long_sess),
                "富集分析"))
  # dsapp_task_title 在"功能名和会话名一模一样"时**整条不拼后缀**，
  # 那种标题强行按 _ 切会把功能名切掉一块。
  chk("★★★ 标题就是会话名本身时不许乱切（切了会缺字）",
      identical(dsapp_task_short_title(sess, sess), sess))
  chk("★ 对不上后缀的原样留着（宁可在分组视图里重复一遍，也不能缺字）",
      identical(dsapp_task_short_title("另一个功能", sess), "另一个功能"))
  chk("★ 功能那半截是空的时不许切出一个空单元格",
      identical(dsapp_task_short_title(paste0("_", sess), sess), paste0("_", sess)))
  # NA：nchar(NA) 是 2、endsWith(NA, x) 是 NA，而 if(NA) 直接抛
  # "missing value where TRUE/FALSE needed"。老库里有没标题的任务行。
  chk("★★ NA 标题不报错、也不留 NA 在单元格里（DT 会原样显示「NA」）",
      identical(dsapp_task_short_title(c(NA, paste0("a_", sess)), c(sess, sess)),
                c("", "a")))
  chk("★ 长度不一致时按 titles 的长度补齐，不报错",
      length(dsapp_task_short_title(c("a", "b", "c"), sess)) == 3)
  chk("★ 空输入返回空（renderDataTable 里那一支会走到）",
      length(dsapp_task_short_title(character(0), character(0))) == 0)

  # ---- (c) 接线：分组必须做在 tasks() 里，不能做在渲染那一步 ----------------
  mt <- strip_comments(paste(readLines("R/mod_tasks.R", warn = FALSE),
                             collapse = "\n"))
  i_filter <- as.integer(regexpr("dsapp_filter_tasks(df, input$f_status",
                                 mt, fixed = TRUE))
  i_group  <- as.integer(regexpr("dsapp_group_tasks(df)", mt, fixed = TRUE))
  i_tbl    <- as.integer(regexpr("output$tbl <- DT::renderDataTable", mt,
                                 fixed = TRUE))
  chk("★★★ 三个路标都找得到（找不到的话下面两条会静默通过）",
      i_filter > 0L && i_group > 0L && i_tbl > 0L)
  chk("★★★ 重排做在 tasks() 里、排在筛选之后（行号才是同一套编号）",
      i_group > i_filter && i_group < i_tbl)
  chk("★★ 开关默认开着（用户要的就是这个视图）",
      grepl('checkboxInput(ns("f_group"), "按对话分组", value = TRUE)',
            mt, fixed = TRUE))
  # ⚠️ 这条盯的是**设计决定**，不是实现细节：曾经想过"插一行分组标题"，
  #    那样最好看，但这一页所有批量操作都按行号回查 tasks()，插一行就会
  #    让"点第 3 行删掉第 4 条"。所以组标题由每组第一条任务**兼任**。
  i_end <- as.integer(regexpr("}, server = FALSE)", mt, fixed = TRUE))
  tbl_blk <- if (i_tbl > 0L && i_end > i_tbl) substr(mt, i_tbl, i_end) else ""
  chk("★★★ 没往表里插假行（rbind）：插了行号整体错位，会删错东西",
      nzchar(tbl_blk) && !grepl("rbind(", tbl_blk, fixed = TRUE))

  # ---- (d) 渲染：对话列 + 行 class 的载体 ----------------------------------
  i_id   <- as.integer(regexpr("id = df$id,", mt, fixed = TRUE))
  i_conv <- as.integer(regexpr("conv = conv,", mt, fixed = TRUE))
  i_done <- as.integer(regexpr("done = vapply(", mt, fixed = TRUE))
  i_grp  <- as.integer(regexpr("grp = grp,", mt, fixed = TRUE))
  chk("★★★ 四个列位置都找得到", i_id > 0L && i_conv > 0L &&
        i_done > 0L && i_grp > 0L)
  chk("★★ 「对话」列排在 ID 之后、标题之前",
      i_conv > i_id && i_conv < i_done)
  chk("★★★ 行 class 的载体列排在**最后**（rowCallback 按下标取它）",
      i_grp > i_done)
  chk("★ 表头里有「对话」这一列",
      grepl('"对话"', mt, fixed = TRUE))
  chk("★★ 载体列对用户不可见（visible = FALSE）",
      grepl("visible = FALSE, targets = ncol(show) - 1L", mt, fixed = TRUE))
  # ⚠️ 写死数字的话，哪天中间插一列就会静默失效：取到一列空字符串，
  #    不报错，只是分组样式全没了。
  chk("★★★ rowCallback 和 columnDefs 都按 ncol(show) 现算下标，不写死",
      grepl("rowCallback = DT::JS(sprintf(", mt, fixed = TRUE) &&
        length(gregexpr("ncol(show) - 1L", mt, fixed = TRUE)[[1]]) == 2L)
  chk("★ rowCallback 挂到 tr 的 className 上（DT 没有按行加类的接口）",
      grepl("row.className", mt, fixed = TRUE))
  chk("★★ 只有分组视图下才去标题尾巴（平铺视图里会话名没别处显示）",
      grepl("if (grouping) ttl <- dsapp_task_short_title(", mt, fixed = TRUE))

  # ---- (e) 两条取数路径的列必须一致 ---------------------------------------
  dbr <- strip_comments(paste(readLines("R/db.R", warn = FALSE),
                              collapse = "\n"))
  m_st <- gregexpr("AS session_title", dbr, fixed = TRUE)[[1]]
  n_st <- if (m_st[1] == -1L) 0L else length(m_st)
  chk("★★★ db_tasks_list 三条取数路径都带上了 session_title（少一条那一条就取不到）",
      n_st >= 3L, sprintf("%d 处", n_st))
  # ⚠️ all=TRUE 那一支原来走的是不带 t. 前缀的 cols（FROM tasks 没有别名）。
  #    加 JOIN 之后 id 在两张表里都有，不加前缀 SQLite 直接报
  #    "ambiguous column name" —— 所以那一支必须改用 tcols。
  # ⚠️ 窗口卡在**这一支到下一支之间**，不是"往后数 N 个字符"：数 N 的话会
  #    圈进下面那一支（它也用 tcols），断言就永远是绿的 —— 而 all=TRUE 那
  #    一支恰恰是唯一需要 JOIN、唯一会 ambiguous 的那条路。
  #
  # ⚠️⚠️ 而且必须先**定位到 db_tasks_list 这个函数**再找那两支。
  #    regexpr() 找的是**全文第一个**命中，而 `if (isTRUE(all))` 在 db.R 里
  #    有两处、`if (is.null(user_id)` 有六处 —— 全文搜会拿到**另一个函数**
  #    里的那两个位置，于是 i_uid < i_all、窗口是空的，报出来的是
  #    「找不到 all=TRUE 那一支」。第一版就是这么写的，当场红在这里。
  #    这类"锚点在别的函数里也有一份"的坑，只看这段代码是看不出来的。
  i_fn <- as.integer(regexpr("db_tasks_list <- function", dbr, fixed = TRUE))
  rest <- if (i_fn > 0L) substr(dbr, i_fn, nchar(dbr)) else ""
  chk("★★★ 找得到 db_tasks_list 的定义（找不到的话下面两条会静默通过）",
      nzchar(rest))
  i_all  <- as.integer(regexpr("if (isTRUE(all))", rest, fixed = TRUE))
  i_uid  <- as.integer(regexpr(
    "if (is.null(user_id) || length(user_id) == 0 || is.na(user_id))",
    rest, fixed = TRUE))
  all_blk <- if (i_all > 0L && i_uid > i_all) {
    substr(rest, i_all, i_uid - 1L)
  } else ""
  chk("★★★ 找得到 all=TRUE 那一支（找不到的话下面两条会静默通过）",
      nzchar(all_blk))
  chk("★★★ all=TRUE 那一支用的是带 t. 前缀的 tcols（不然 JOIN 之后 ambiguous）",
      nzchar(all_blk) && grepl("tcols", all_blk, fixed = TRUE) &&
        grepl("LEFT JOIN sessions s", all_blk, fixed = TRUE))
  chk("★★ 空 user_id 那一支也带 tcols（两条路径的列必须完全一致）",
      grepl("FROM tasks t WHERE 1 = 0", dbr, fixed = TRUE))

  # ---- (f) 样式 -------------------------------------------------------------
  css <- paste(readLines("www/app.css", warn = FALSE), collapse = "\n")
  chk("★★ 组标题那个类有样式（加粗 + 浅底 + 上面一条粗线）",
      grepl("tr.dsapp-task-grp-head > td", css, fixed = TRUE))
  chk("★★ 组员那个类有样式（一条很淡的分隔线）",
      grepl("tr.dsapp-task-grp-sub > td", css, fixed = TRUE))

  # ★★★ 颜色必须走皮肤变量，一个十六进制都不许写死。
  #
  # 这条是**真抓到过 bug** 才补的：第一版写的是 `background: #f6f8fa`，
  # 浅色皮肤下看着完全正常 —— 因为那恰好就是 light 皮肤这个变量的值。
  # 但 dark 皮肤是 body-bg #0d1117 + 文字 #e6edf3，于是组标题变成
  # **白底白字、一个字都看不见**。而写代码时用的正是浅色皮肤，肉眼验收
  # 撞不上；五个皮肤里坏一个，不专门量就发现不了。
  #
  # ⚠️ 判据是"这两个规则块里没有 # 开头的颜色"，不是"写了 var(--bs-"：
  #    后者对着一个 `var(--bs-tertiary-bg)` 后面再跟一句 `#fff` 的实现
  #    照样绿。
  grp_rules <- regmatches(
    css, gregexpr("\\.dsapp-dt-nowrap table\\.dataTable > tbody > tr\\.dsapp-task-grp-[a-z]+ > td \\{[^}]*\\}",
                  css, perl = TRUE))[[1]]
  chk("★★★ 找得到那两条规则（找不到的话下面两条会静默通过）",
      length(grp_rules) >= 2L, sprintf("%d 条", length(grp_rules)))
  hexes <- unlist(regmatches(grp_rules, gregexpr("#[0-9a-fA-F]{3,8}\\b", grp_rules,
                                                 perl = TRUE)))
  chk("★★★ 分组那两条规则里没有写死的颜色（写死了会在某一款皮肤下变成白底白字）",
      length(hexes) == 0L, paste(unique(hexes), collapse = " "))
  chk("★★ 而且确实用了皮肤变量（--bs- 开头）",
      all(grepl("var(--bs-", grp_rules, fixed = TRUE)))
}

# =============================================================================
# V13.12 新机制的回归（item 6 / 8 / 11 / 12）
# =============================================================================
cat("\n\033[1m-- V13.12 新机制 --\033[0m\n")

# ---- item 6：渲染管线缓存 ----------------------------------------------------
#
# ⚠️ 这里断言的是"**缓存不许改变结果**"，不是"缓存命中了"。命中率靠性能测，
#    单元测试测不了；而缓存改结果是最要命的那种 bug（症状是"刷新一下又对了"，
#    和 session proxy 那类问题长得一模一样，极难查）。所以同一段正文跑两次、
#    第三次把缓存清空再跑，三者必须逐字节相同。
{
  md <- paste0("# 标题\n\n中文正文一段，带 `代码` 和 **加粗**。\n\n",
               "```r\nx <- c(1, 2, 3)\ncat(\"中文\")\n```\n\n",
               "结尾再来一行中文，够长才走得进那条 UTF-8 慢路径。\n")
  a <- dsapp_split_segments(md)
  b <- dsapp_split_segments(md)                       # 这一发应当命中缓存
  # ⚠️ 必须写成两行。`dsapp_state()$memo <- NULL` 走的是复杂赋值语法糖，
  #    R 会去找 `dsapp_state<-` 这个替换函数，报「invalid (NULL) left side
  #    of assignment」—— 报错信息完全指不到真正的原因。
  .st <- dsapp_state(); .st$memo <- NULL              # 清干净
  c3 <- dsapp_split_segments(md)                      # 这一发是冷的
  chk("★★ dsapp_split_segments：命中缓存与冷算的结果逐字节相同",
      identical(a, b) && identical(a, c3))
  # 缓存"确实在缓存"这件事也要单独验一下，否则上面那条在缓存整个失效的
  # 情况下照样绿 —— 而缓存失效正是这次性能修复唯一依赖的东西。
  chk("★★ 缓存真的命中了（第二次没有再算一遍）", {
    cnt <- new.env(); cnt$n <- 0L
    f <- function() { cnt$n <- cnt$n + 1L; "值" }
    dsapp_memo("selftest_probe", "k1", f)
    dsapp_memo("selftest_probe", "k1", f)
    identical(cnt$n, 1L)
  })
  chk("★ 换了 key 就要重算（key 撞了会把别人的结果端上来）", {
    cnt <- new.env(); cnt$n <- 0L
    f <- function() { cnt$n <- cnt$n + 1L; "值" }
    dsapp_memo("selftest_probe2", "a", f)
    dsapp_memo("selftest_probe2", "b", f)
    identical(cnt$n, 2L)
  })
  chk("★★ 围栏被正确切出来了（type/lang/code 三项）",
      length(a) == 3L && identical(a[[2]]$type, "code") &&
        identical(a[[2]]$lang, "R") &&   # dsapp_norm_lang 归一成大写
        identical(a[[2]]$code, "x <- c(1, 2, 3)\ncat(\"中文\")"))
  chk("★ 空输入返回空 list（不是 NULL —— NULL 会被当成缓存未命中）",
      identical(dsapp_split_segments(""), list()) &&
        identical(dsapp_split_segments(NULL), list()))
}

# ---- item 8：产物体检 --------------------------------------------------------
{
  d <- file.path(tmp, "artcheck"); dir.create(d, showWarnings = FALSE)
  writeLines(c("gene,logFC", "TP53,1.2"), file.path(d, "good.csv"))
  writeLines("gene,logFC", file.path(d, "header_only.csv"))
  writeLines(character(0), file.path(d, "empty.csv"))
  writeLines("[]", file.path(d, "empty.json"))
  writeLines("{\"a\":1}", file.path(d, "ok.json"))
  writeLines(c("", "", "gene,logFC", "TP53,1.2"), file.path(d, "leading_blank.csv"))

  bad <- dsapp_artifact_check(
    c("good.csv", "header_only.csv", "empty.csv", "empty.json", "ok.json",
      "leading_blank.csv", "does_not_exist.csv"), d)
  one <- function(p) any(grepl(p, bad))
  chk("★★★ 只有表头的 CSV 被点出来", one("header_only\\.csv：只有表头"))
  chk("★★ 0 字节文件被点出来", one("empty\\.csv：0 字节"))
  chk("★★ 空 JSON 数组被点出来", one("empty\\.json：内容是空的"))
  chk("★★★ 有数据的 CSV **不**被误报（误报会把正常任务说成有问题）",
      !one("good\\.csv") && !one("leading_blank\\.csv") && !one("ok\\.json"))
  chk("★★ 不存在的文件不参与体检（历史产物早被清掉了，报它就是纯噪声）",
      !one("does_not_exist"))
  chk("★ 目录不是文件，跳过", {
    dir.create(file.path(d, "sub"), showWarnings = FALSE)
    !any(grepl("sub", dsapp_artifact_check("sub", d)))
  })
  chk("★ 工作区不存在时安静返回 character(0)，不抛",
      identical(dsapp_artifact_check("x.csv", file.path(tmp, "nope")), character(0)))
  # 上限：超了要**说出来**，不能静默截断（静默截断读起来像"全都查过了"）
  for (i in 1:65) writeLines("gene,logFC", file.path(d, sprintf("h%02d.csv", i)))
  capped <- dsapp_artifact_check(sprintf("h%02d.csv", 1:65), d)
  chk("★★ 超过 max_check 时明说漏了几个（不许静默截断）",
      any(grepl("另有 5 个本次产出的文件没有体检", capped)))
}

