# ---- 轮次用满时的最后一次收尾机会（第 ② 条）--------------------------------
chk("★★★ V15.5 item 3：收尾轮的提示说清了「只写结论、代码不再执行」", {
  lc <- dsapp_agent_last_chance_text(6L)
  grepl("最后一次收尾机会", lc, fixed = TRUE) &&
    grepl("不会再执行任何代码", lc, fixed = TRUE) &&
    # 轮数和滑块同源（写死 6 的话，用户把额度拉到 12 之后这句话就是假的）
    grepl("用满了这次给的轮数（6 轮）", lc, fixed = TRUE) &&
    grepl("不要**再给可执行代码块", lc, fixed = TRUE)
})
chk("★★★ V15.5 item 3：收尾轮提示里点名了「中间数据不是交付物」",
    grepl("哪些只是中间数据", dsapp_agent_last_chance_text(6L), fixed = TRUE))

# ---- 把状态机真推一遍：撞上限 → 收尾轮 → 无论交回什么都停 -------------------
#
# ⚠️ 这是这一版**最容易改出死循环**的地方（收尾轮本身就是一次新的生成），
#    所以不能只靠"函数写对了"和源码 grep：真喂一轮进来，看它到底停不停。
#    离线能这么测是因为 a$feed_result / a$on_llm_done 都是纯状态机方法，
#    hooks 全是我们自己给的假函数（见上面 ag_mk）。
#
#   用到的两个状态位：
#     a$final —— 轮到收尾轮了吗（feed_result 撞上限时置上，一次性）
#     a$prod  —— 这一趟落盘的产物（feed_result 每轮追加）
{
  fa_mk <- function() {
    fx <- ag_mk(); a <- fx$a
    a$enabled <- TRUE        # 会话里由「自动执行」开关给，这里直接开
    a$sid <- "s-selftest"
    a$t0 <- Sys.time()       # 时间闸没到（不置的话它在 feed_result 里是 NULL）
    a$iter <- a$max_iter     # 已经跑满
    a$state <- "generating"
    a$prod <- c("lit_search/step6_candidate_audit.json")   # 全是中间产物
    a$task_id <- 4242L
    fx
  }
  fa_row <- list(status = "success", lang = "R", exit_code = 0L,
                 stdout = "ok", stderr = "",
                 started_at = "2026-09-30 10:00:00",
                 finished_at = "2026-09-30 10:00:05",
                 session_id = "s-selftest", workdir = NA_character_)

  fx1 <- fa_mk(); f1 <- fx1$a; fh1 <- fx1$hit
  n0 <- fh1$n
  f1$feed_result(fa_row, 4242L)
  chk("★★★ V15.5 item 3：轮次用满时不再当场结束，而是再喂一轮收尾", {
    # 老行为是这里直接 finish，模型连最后一个任务的结果都看不到（用户报的那次）。
    identical(f1$state, "generating") && isTRUE(f1$final) &&
      fh1$n == n0 + 1L &&
      any(grepl("最后一次收尾机会", fh1$add, fixed = TRUE))
  })
  chk("★★★ V15.5 item 3：收尾轮里模型再写代码块也不会被执行（终止性的唯一保证）", {
    n1 <- fh1$n
    f1$on_llm_done("```r\ncat(2)\n```", message_id = 910002L)
    # 没再起一轮生成 = 那个块连提交都没提交，循环停在 idle。
    identical(f1$state, "idle") && fh1$n == n1
  })
  chk("★★★ V15.5 item 3：收尾轮结束时补一条「没有人类可读的交付物」", {
    # 这条是写给**用户**的：清单换了措辞他未必看，得有人明确告诉他
    # "这次没有能看的东西"。
    any(grepl("没有人类可读的交付物", fh1$add, fixed = TRUE))
  })
  chk("★★★ V15.5 item 3：收尾开关是一次性的（粘住的话下一段循环会被它吃掉）", {
    isFALSE(f1$final) && identical(f1$prod, character(0))
  })

  # 收尾轮交回纯文字（正常路径）也一样停
  fx2 <- fa_mk(); f2 <- fx2$a
  f2$feed_result(fa_row, 4242L)
  f2$on_llm_done("结论：这次做到了 X，关键数字 Y。", message_id = 910003L)
  chk("★★ 收尾轮给纯文字 → 循环结束（正常路径）",
      identical(f2$state, "idle"))

  # 没撞上限时老行为一个字不变：模型给结论就结束，不给收尾轮
  #
  # ⚠️ state 要置成 generating（"循环跑到一半"），不能留着 idle ——
  #    idle 那一支是"用户新开了一轮"，它会把 a$prod 清空（那是**这一趟**的
  #    产物，新一趟当然要从零算），于是这条断言测的就成了"没产出文件的对话
  #    不发提示"，红得莫名其妙。
  fx3 <- ag_mk(); f3 <- fx3$a; fh3 <- fx3$hit
  f3$enabled <- TRUE; f3$sid <- "s-selftest"; f3$t0 <- Sys.time()
  f3$state <- "generating"
  f3$prod <- c("a.json", "b.rds")
  f3$on_llm_done("结论……", message_id = 910004L)
  chk("★★★ V15.5 item 3：没撞上限时照旧结束，且三条收尾提示一个都不多",
      identical(f3$state, "idle") &&
        !any(grepl("最后一次收尾机会", fh3$add, fixed = TRUE)))
  chk("★★ 模型自己收尾那条路也会发「没有人类可读的交付物」",
      any(grepl("没有人类可读的交付物", fh3$add, fixed = TRUE)))

  # ★ V15.5 item 3 第 ④ 条：时间闸也是"循环结束"的一种。挂机两小时被时间闸
  #   叫停的那一趟，用户手里可能同样只有一堆 json —— 漏掉这两条的话，
  #   最需要这句提示的那个场景（人不在、跑了很久）恰好一个字都不说。
  fx4 <- fa_mk(); f4 <- fx4$a; fh4 <- fx4$hit
  f4$wall_limit <- 10          # 已超时：t0 是假的过去时间
  f4$t0 <- Sys.time() - 100
  f4$feed_result(fa_row, 4242L)
  chk("★★ V15.5 item 3：时间闸在回喂那一支叫停时也发交付提示", {
    identical(f4$state, "idle") &&
      any(grepl("没有人类可读的交付物", fh4$add, fixed = TRUE))
  })

  fx5 <- fa_mk(); f5 <- fx5$a; fh5 <- fx5$hit
  f5$wall_limit <- 10
  f5$t0 <- Sys.time() - 100
  f5$iter <- 0L                # 轮次没到，走的是时间闸那一支
  f5$on_llm_done("结论……", message_id = 910005L)
  chk("★★ V15.5 item 3：时间闸在生成结束那一支叫停时也发交付提示", {
    identical(f5$state, "idle") &&
      any(grepl("没有人类可读的交付物", fh5$add, fixed = TRUE))
  })
}

# ⚠️ 上面几条验的是"函数写对了"。按本仓库的教训（自检全绿 ≠ 功能被验过），
#    还得确认循环**真的会调**它们 —— 函数写得再对，没人调就是两个死函数。
#    扫源码前先剥注释：这几段说明本身就在解释这个写法，不剥会扫到注释里的
#    字面量（这个坑踩过三次）。匹配一律 fixed = TRUE。
agent_src <- strip_comments(paste(readLines("R/agent.R", warn = FALSE),
                                  collapse = "\n"))
chk("★★★ V15.5 item 3：轮次用满那一支真的改成了「再喂一轮 + 收尾提示」", {
  grepl("a$final <- TRUE", agent_src, fixed = TRUE) &&
    grepl("hooks$add_msg(\"tool\", dsapp_agent_last_chance_text(a$max_iter))",
          agent_src, fixed = TRUE)
})
chk("★★★ V15.5 item 3：收尾轮在 on_llm_done 里被无条件吃掉（这是终止性的唯一保证）", {
  # 少这一支的话，模型在收尾轮里再写一个代码块就会被执行，上限被撑开 ——
  # 而 a$final 每轮都会重新置上，变成真正的死循环。
  grepl("if (isTRUE(a$final)) {", agent_src, fixed = TRUE) &&
    grepl("a$final <- FALSE", agent_src, fixed = TRUE)
})
chk("★★★ V15.5 item 3：四个「这一趟结束了」的出口都调了交付提示（2 收尾 + 2 时间闸）", {
  m <- gregexpr("a$deliver_note()", agent_src, fixed = TRUE)[[1]]
  # ⚠️ 找不到时 gregexpr 返回 -1，length() 仍然是 1 —— 写成 length(...) >= 2
  #    会永远绿（"没调到"和"调了"分不出来）。
  # ⚠️ 这里用 `==` 而不是 `>=`：漏掉一个出口是静默的（那个出口的用户一个字都
  #    看不到），多出一个（比如以后给"用户点停止"也加）应当被迫回来看一眼
  #    这句提示在那个场合说不说得通。两个时间闸出口的位置由下一条单独钉。
  sum(m > 0) == 4L
})
chk("★★ V15.5 item 3：两个时间闸出口也发了交付提示（数两处 + 位置在 finish 之前）", {
  # 只数个数不够 —— 提示发在 finish **之后**等于没发（finish 已经把
  # a$prod 清空了，那一条会变成静默的空消息）。逐个往回收 120 字里找。
  m <- gregexpr("return(a$finish(dsapp_agent_wall_note(", agent_src,
                fixed = TRUE)[[1]]
  sum(m > 0) == 2L &&
    all(vapply(m[m > 0], function(i)
      grepl("a$deliver_note()", substr(agent_src, i - 120L, i), fixed = TRUE),
      logical(1)))
})
chk("★★ V15.5 item 3：收尾开关在每个复位点都清了，且包含「用户新开一轮」那一支", {
  # ⚠️ 光数个数是不够的（这正是"自检全绿 ≠ 验过"的经典形状）：`a$finish()`
  #    确实会清它，但**不是每条路都经过 finish** —— 收尾轮生成回来时用户
  #    正好把循环关掉，on_llm_done 第一行 `!a$can_loop()` 就 return 了，
  #    开关留在 TRUE 上；用户再开一轮、说第一句话，就会撞上"收尾轮"那一支：
  #    循环在"用户刚开口"时静默结束，还附一句「轮次已用满」。
  #    所以这里钉死"新请求那一支里必须有一处"。
  n <- gregexpr("a$final <- FALSE", agent_src, fixed = TRUE)[[1]]
  req <- regmatches(agent_src, regexpr(
    "(?s)if \\(identical\\(a\\$state, \"idle\"\\)\\) \\{.*?\\n    \\}",
    agent_src, perl = TRUE))
  length(req) == 1 && nzchar(req) &&
    grepl("a$final <- FALSE", req, fixed = TRUE) &&
    sum(n > 0) >= 5   # 1 处初始化 + 4 处复位
})

