        is.null(dsapp_skill_path_norm("../secret.md")))
  chk("★★★ 绝对路径 / 盘符不会穿透（Windows 的反斜杠也算）",
      is.null(dsapp_skill_path_norm("/etc/passwd")) &&
        is.null(dsapp_skill_path_norm("C:\\Windows\\x")) &&
        is.null(dsapp_skill_path_norm("\\\\srv\\share\\x")))
  chk("★★ 正常路径原样保留（中文、空格、点目录）",
      identical(dsapp_skill_path_norm("templates/R语言教程/a b.rmd"),
                "templates/R语言教程/a b.rmd") &&
        identical(dsapp_skill_path_norm("./a/./b.md"), "a/b.md") &&
        identical(dsapp_skill_path_norm("a\\b.md"), "a/b.md"))
  chk("★ 空路径 / 全是点段返回 NULL，超深超长也拒",
      is.null(dsapp_skill_path_norm("")) &&
        is.null(dsapp_skill_path_norm("./")) &&
        is.null(dsapp_skill_path_norm(paste(rep("d", 13), collapse = "/"))) &&
        is.null(dsapp_skill_path_norm(paste(rep("aaaaaaaaaa", 41), collapse = "/"))))
}

