# 上限：超单文件上限的**只登记不存内容**，且大小要记真实的
{
  big <- raw(DSAPP_SKILL_FILE_MAX + 10L)
  .con <- dsapp_db(cfg)
  .sid <- 90001L
  try(DBI::dbExecute(.con, "DELETE FROM skill_files WHERE skill_id = ?",
                     params = list(.sid)), silent = TRUE)
  st <- dsapp_skill_files_set(.sid, list(
    list(path = "ok.md", raw = charToRaw("你好")),
    list(path = "big.bin", raw = big),
    # 上传侧对超限文件是**不读**的（raw = NULL + bytes 提示）
    list(path = "huge.html", raw = NULL, bytes = 20948759),
    list(path = "../evil.md", raw = charToRaw("x"))
  ), con = .con)
  chk("★★★ item 13：超单文件上限的**不存内容**，但路径和真实大小要留下",
      {
        fl <- dsapp_skill_files_list(.sid, con = .con)
        identical(nrow(fl), 3L) &&                    # ../evil.md 被拒
          identical(fl$stored[fl$path == "ok.md"], 1L) &&
          identical(fl$stored[fl$path == "big.bin"], 0L) &&
          identical(fl$stored[fl$path == "huge.html"], 0L) &&
          # ⚠️ 这一条是关键：raw = NULL 时如果不看 bytes 提示，
          #    这里会记成 0，界面上那个 20 MB 的文件显示"0 B"。
          identical(as.numeric(fl$bytes[fl$path == "huge.html"]), 20948759)
      })
  # ⚠️ skipped 计的是"没存进内容的"：**路径被拒的**和**超过上限的**都算。
  #    这条断言上写着 3 而不是 1，是因为 big.bin（超单文件上限）和
  #    huge.html（raw = NULL）也各计一次 —— 它们确实"没存内容"。
  chk("★ 没存进内容的都计入 skipped，不是静默丢掉",
      identical(st$skipped, 3L) && identical(st$n, 1L))

  # 往返：文本解得回来，二进制不试图解成文本
  g1 <- dsapp_skill_file_get(.sid, "ok.md", con = .con)
  chk("★★ 文本附件能原样读回（中文不乱码）",
      identical(g1$kind, "text") && identical(g1$text, "你好"))
  dsapp_skill_files_set(.sid, list(
    list(path = "p.pdf", raw = charToRaw("%PDF-1.4")),
    list(path = "huge.html", raw = NULL, bytes = 20948759)), con = .con)
  g2 <- dsapp_skill_file_get(.sid, "p.pdf", con = .con)
  g3 <- dsapp_skill_file_get(.sid, "huge.html", con = .con)
  chk("★★★ 没存内容的附件读回来 text 必须是 NULL（不是空串、不是乱码）",
      is.null(g3$text) && is.null(g3$raw) && isFALSE(g3$stored) &&
        identical(as.numeric(g3$bytes), 20948759))
  chk("★★ 二进制附件有 raw 但没有 text（不能对它调 rawToChar）",
      identical(g2$kind, "binary") && is.raw(g2$raw) && is.null(g2$text))

  # list() = 清空（save 的约定）。这里曾经因为"空列表提前 return"而整条跳过 DELETE。
  st2 <- dsapp_skill_files_set(.sid, list(), con = .con)
  chk("★★★ item 13：`files = list()` 是**清空**，不是「什么都不做」",
      identical(nrow(dsapp_skill_files_list(.sid, con = .con)), 0L) &&
        identical(st2$n, 0L))
  chk("★ append = TRUE 时空列表才是真的什么都不做", {
    dsapp_skill_files_set(.sid, list(list(path = "a.md", raw = charToRaw("a"))),
                          con = .con)
    dsapp_skill_files_set(.sid, list(), con = .con, append = TRUE)
    identical(nrow(dsapp_skill_files_list(.sid, con = .con)), 1L)
  })
  try(DBI::dbExecute(.con, "DELETE FROM skill_files WHERE skill_id = ?",
                     params = list(.sid)), silent = TRUE)
}

# 内置技能的文件夹形态：扫得出来、种得进去、正文里那张清单说得对
{
  bs <- dsapp_skills_builtin_md(refresh = TRUE)
  folder <- Filter(function(s) length(s$files %||% list()) > 0, bs)
  chk("★★ item 13：`skills_builtin/<目录>/SKILL.md` 被认成**一条**技能（不是平铺）",
      length(folder) >= 2L &&
        all(vapply(folder, function(s) grepl("/SKILL.md$", s$file), TRUE)))
  chk("★★ 文件夹形态的 `file` 显示成 `目录/SKILL.md`（一屏里好几条都叫 SKILL.md 就分不清了）",
      all(vapply(folder, function(s) identical(s$file,
                                               paste0(basename(dirname(s$file)),
                                                      "/SKILL.md")), TRUE)))
  chk("★★ 内置技能的配套文件路径全部能通过安全归一（有一个不过就是扫错了东西）",
      all(vapply(folder, function(s)
        all(vapply(s$files, function(f) !is.null(dsapp_skill_path_norm(f$path)),
                   TRUE)), TRUE)))
  # ⚠️ 二进制附件**是要存内容的**（PNG 模板得能铺进工作区），
  #    要守的不是"别存"，而是"存了之后别把它当文本解" ——
  #    rawToChar() 碰到二进制不会返回错误结果，它会给出乱码或者直接抛
  #    「embedded nul in string」。所以这里挑一个真的二进制附件走一趟全程。
  # ★ V14 item 5：用户把三份 `.html` 蒸馏笔记放进了 skills_builtin/ 顶层，
  #   要求"更新到 skill 库里去"。顶层那份扫描只认 `\.md$`，所以它们**一直
  #   没进过技能库** —— 界面上一片正常，只是"这三条技能不存在"。
  #
  #   落法是文件夹形态：SKILL.md 是正文（怎么用这份笔记），HTML 是配套文件
  #   （完整成品）。这样正文能进提示词、附件能铺进工作区，两边都不丢。
  #
  #   ⚠️ 断言查的是**技能名**而不是文件名：技能在库里认的是 (user_id, name)，
  #      文件名改了不影响它是哪一条，名字改了就成了另一条技能。
  v14_want <- c("教程代码结构化蒸馏", "文献结构化精读", "生信基地内容地图")
  v14_have <- vapply(bs, function(s) s$name, character(1))
  chk("★★★ V14 item 5：三份蒸馏笔记都进了技能库（顶层直接放 .html 是扫不到的）",
      all(v14_want %in% v14_have),
      sprintf("缺：%s", paste(setdiff(v14_want, v14_have), collapse = ",")))
  chk("★★ 三份笔记各自挂在一条技能下当配套文件，而且带得动（HTML 是文本，不是二进制）",
      {
        hit <- Filter(function(s) s$name %in% v14_want, bs)
        length(hit) == 3L &&
          all(vapply(hit, function(s) {
            fs <- s$files %||% list()
            length(fs) == 1L && grepl("\\.html$", fs[[1]]$path) &&
              !is.null(fs[[1]]$raw)
          }, logical(1)))
      })
  chk("★ 顶层已经没有裸的 .html 了（留着就是同一份内容在盘上有两份，改哪份说不清）",
      length(list.files(dsapp_skills_builtin_dir(), pattern = "\\.html$")) == 0L)

  chk("★★ 二进制附件存得进、取得回，且 text 一定是 NULL",
      {
        bin <- NULL
        for (s in folder) for (f in s$files) {
          if (is.null(bin) && !is.null(f$raw) &&
              identical(dsapp_skill_file_kind(f$path, f$raw), "binary")) {
            bin <- list(s = s, f = f)
          }
        }
        !is.null(bin) &&
          identical(dsapp_skill_file_kind(bin$f$path, bin$f$raw), "binary")
      })
}

# 端到端：seed → 库里 → 铺进工作区
{
  .con <- dsapp_db(cfg)
  dsapp_skills_seed(.con)
  sid <- tryCatch(DBI::dbGetQuery(.con,
    "SELECT id FROM skills WHERE user_id IS NULL AND builtin = 1
      AND name = 'academic-search'")$id[[1]], error = function(e) NA_integer_)
  chk("★★★ item 13：文件夹形态的内置技能 seed 进库时**连附件一起**",
      !is.na(sid) && nrow(dsapp_skill_files_list(sid, con = .con)) > 10)
  chk("★★ 二次 seed 不重写附件（清单没变就不该动 BLOB）", {
    before <- DBI::dbGetQuery(.con,
      "SELECT created_at FROM skill_files WHERE skill_id = ? LIMIT 1",
      params = list(as.integer(sid)))$created_at[[1]]
    dsapp_skills_seed(.con)
    after <- DBI::dbGetQuery(.con,
      "SELECT created_at FROM skill_files WHERE skill_id = ? LIMIT 1",
      params = list(as.integer(sid)))$created_at[[1]]
    identical(before, after)
  })
  sk_src <- paste(readLines("R/skills.R", warn = FALSE, encoding = "UTF-8"),
                  collapse = "\n")
  chk("★★★ item 13：提示词里要说清附件铺在 `.skills/<技能名>/` 下，否则模型只会瞎猜路径",
      any(grepl(".skills/", sk_src, fixed = TRUE)) &&
        any(grepl("dsapp_skill_files_stat(", sk_src, fixed = TRUE)) &&
        dsapp_skill_files_stat(sid, con = .con)$n > 10)

  # ★ item 14 的**线上那条路径**：文献速递页上默认勾中的那两条，就是
  #   seed 进库的这两条。上面那几条断言用的是手工造的 data.frame，
  #   它们保证不了"库里真有这两条、而且名字对得上"。
  chk("★★★ item 14：种进库之后，文献速递页默认勾的正是那两条（端到端）", {
    ch <- dsapp_lit_skill_choices(con = .con)
    got <- dsapp_lit_default_skill(ch)
    length(got) == 2L &&
      identical(sort(as.character(ch$name[ch$id %in% got])),
                c("academic-search", "deeppapernote"))
  })
  chk("★★ item 14：这两条在库里带够附件（挂上去才有东西铺进工作区）", {
    ids <- DBI::dbGetQuery(.con,
      "SELECT id FROM skills WHERE user_id IS NULL AND builtin = 1
        AND name IN ('academic-search', 'deeppapernote')")$id
    length(ids) == 2L &&
      all(vapply(ids, function(i)
        dsapp_skill_files_stat(as.integer(i), con = .con)$n >= 10L, TRUE))
  })
}

# 界面：树必须真的渲染出来，而且不该给"没存内容"的文件一个可点链接
{
  mk <- readLines("R/mod_skills.R", warn = FALSE, encoding = "UTF-8")
  mk_src <- mk[!grepl("^\\s*#", mk)]
  mk_src <- sub("\\s*#.*$", "", mk_src)
  chk("★★ item 13：技能列表里渲染了配套文件树（不是只有正文那几行）",
      any(grepl("dsapp-skill-tree", mk_src, fixed = TRUE)) &&
        any(grepl("dsapp_skill_tree(", mk_src, fixed = TRUE)))
  chk("★★★ 只有 stored 且 kind == text 才给可点链接（二进制点开是一屏乱码）",
      any(grepl("stored && identical(kind, \"text\")", mk_src, fixed = TRUE)))
  chk("★★ 上传文件夹时按 SKILL.md 认领整个目录",
      any(grepl("make_folder_skill", mk_src, fixed = TRUE)) &&
        any(grepl("is_skill_main", mk_src, fixed = TRUE)))
  chk("★★ 「另存为我的」要把配套文件一起复制（只复制正文的话副本会指向不存在的模板）",
      any(grepl("dsapp_skill_files_copy", mk_src, fixed = TRUE)))
  css <- paste(readLines("www/app.css", warn = FALSE, encoding = "UTF-8"),
               collapse = "\n")
  chk("★ 树有配套样式（没有的话层级完全看不出来）",
      grepl(".dsapp-skilldir", css, fixed = TRUE) &&
        grepl(".dsapp-skill-leaf", css, fixed = TRUE) &&
        grepl(".dsapp-skill-tree", css, fixed = TRUE))
}

# ---- item 15：登录页三个控件宽度一致 ------------------------------------------
#
# 症状是"继续"按钮比两个输入框**宽 52px**。根因不在我们写的样式里，
# 而在 Shiny 自带的那条 `.shiny-input-container:not(...-inline){width:300px}`：
# 它落在外面那层 form-group 上，于是输入框的 100% = 300px，
# 而按钮的 100% = 列宽 352px。两边都没写错，错在参照物不是同一个。
{
  css <- paste(readLines("www/app.css", warn = FALSE, encoding = "UTF-8"),
               collapse = "\n")
  chk("★★★ item 15：把 Shiny 的 .shiny-input-container 拉成整列宽",
      grepl(".dsapp-auth .shiny-input-container:not(.shiny-input-container-inline)",
            css, fixed = TRUE))
  chk("★ 但行内的（勾选框/radio 组）**不能**跟着拉满，否则「我已阅读并同意」会撑成整行",
      grepl(":not(.shiny-input-container-inline)", css, fixed = TRUE))
  chk("★ 认证页三个界面的表单结构还在（改了选择器没把布局改塌）", {
    w <- readLines("R/mod_welcome.R", warn = FALSE, encoding = "UTF-8")
    any(grepl("dsapp_auth_shell", w, fixed = TRUE)) &&
      any(grepl('ns("login_email")', w, fixed = TRUE)) &&
      any(grepl('ns("login_password")', w, fixed = TRUE)) &&
      any(grepl('ns("do_login")', w, fixed = TRUE))
  })
}

# ---- item 19：模型服务搬成独立页 ---------------------------------------------
#
# 用户原话：「把模型服务换成和其它几个侧面导航栏一样的单独页面吧」。
#
# 「和其它几个一样」是这一条的**判据**，不是修辞：它必须走别的页走的那套
# 东西（DSAPP_NAV_ITEMS → dsapp_rail_link → navset_hidden/nav_panel），
# 而不是在旁边另起一套。另起一套的表现是"看着像一页，但拖动排序、当前项
# 高亮、切页标题、键盘可达全都跟别人不一样" —— 每一项单看都不算错，
# 合起来就是"这一项有点怪"。
#
# 渲染层面那几条（控件在主区、只渲染一套、sub 挂在导航项上）在 V6 那一节，
# 这里查的是**登记与接线**：有没有真的挂进导航表、切页 value 对不对得上、
# 那行小字三条分支对不对、以及前端改字的那条消息认的是不是 data-nav。
{
  appc19 <- strip_comments(paste(readLines("app.R", warn = FALSE), collapse = "\n"))
  jsc19  <- strip_js_comments(paste(readLines("www/app.js", warn = FALSE),
                                    collapse = "\n"))
  css19  <- paste(readLines("www/codex.css", warn = FALSE), collapse = "\n")

  # (a) 登记进导航表 ---------------------------------------------------------
  vals19 <- vapply(DSAPP_NAV_ITEMS, function(x) x$value, character(1))
  # ⚠️ 数出来必须是**一个**：重复登记的表现是左栏出现两个「模型服务」，
  #    两个都指向同一页（点哪个都跳过去，看起来只是"多了一项"）。
  chk("★★★ item 19：模型服务进了导航表，且只登记了一次",
      sum(vals19 == "model") == 1L)
  it19 <- Filter(function(x) identical(x$value, "model"), DSAPP_NAV_ITEMS)[[1]]
  chk("★ 图标和标签都对得上（标签写错了用户在左栏根本找不到这一项）",
      identical(it19$label, "模型服务") && identical(it19$icon, "robot"))
  # ⚠️ value 必须是小写字母：左栏那条"导航项与页签 value 一一对应"的断言、
  #    以及前端 dsappNav() 传的字符串，用的都是这个值。写成 "modelService"
  #    的表现是"点得动但页面不换"。
  chk("★ value 是全小写（大写/中文会让前端那条 data-nav 对不上）",
      identical(it19$value, tolower(it19$value)) &&
        grepl("^[a-z]+$", it19$value))
  # ⚠️ 它是**配置页**，排在「环境」之后、「设置」之前；紧跟工作页会让左栏
  #    的语义分组乱掉（用户特意说了"和其它几个侧面导航栏一样"）。
  chk("★ 排位在「环境」和「设置」之间（配置页归配置页那一段）",
      match("model", vals19) > match("envs", vals19) &&
        match("model", vals19) < match("settings", vals19))
  chk("★ 原来的左栏折叠块没有被顺手留下（留着就是同一套 id 渲染两遍）",
      !grepl("dsapp-rail-model", appc19, fixed = TRUE) &&
        length(gregexpr("mod_model_ui(", appc19, fixed = TRUE)[[1]]) == 1L)

  # (b) 页签那一侧：nav_panel 的 value 必须和导航表里那个**同一个字符串** ----
  # ⚠️ 这条**必须**用正则、不能用固定串：nav_panel 那几行是折行的
  #    （`nav_panel("模型服务", value = "model",` 换行到
  #    `mod_model_ui("model", user_id = …)`），固定串一折行就永远匹配不上，
  #    而它红的样子跟"真的没接上"一模一样，白查半天。
  chk("★★★ item 19：nav_panel 的 value 就是 \"model\"（错一个字符就切不过去）",
      grepl('nav_panel\\("模型服务", value = "model"', appc19))
  chk("★★ 而且它渲染的确实是模型模块（不是搬了个空壳过去）",
      grepl('(?s)nav_panel\\("模型服务", value = "model".{0,120}?mod_model_ui\\("model"',
            appc19, perl = TRUE))

  # (c) 导航项底下那行小字 ---------------------------------------------------
  # ⚠️ 三条分支的口径必须和 V7 item 8 那会儿**逐字一致**：mod_model.R 保存
  #    成功后发回来的也是这套字。两处口径不一致的表现是"改完顺手刷新一下，
  #    那行字变了" —— 用户会以为保存没生效。
  chk("★★★ 小字三条分支：配过且有模型名 → 显示模型名",
      grepl('if (nzchar(st$model %||% "")) st$model else "已配置"',
            appc19, fixed = TRUE))
  chk("★★★ 没配过 → 「未配置」，而且读的是**当前用户**的设置",
      grepl('} else "未配置"', appc19, fixed = TRUE) &&
        grepl("dsapp_settings_get(user$id %||% NULL)", appc19, fixed = TRUE))
  # ⚠️ 这一整段必须包在 tryCatch 里：它跑在**渲染外壳**的那条路上，库一卡
  #    或者这张表还没建，整页都出不来（为了左栏一行小字把整个应用打不开，
  #    是最不划算的一种失败）。
  chk("★★ 读设置失败不许拖垮整个外壳（渲染路上的一行小字，兜底就行）",
      grepl('msub <- tryCatch({', appc19, fixed = TRUE) &&
        grepl('error = function(e) "未配置"', appc19, fixed = TRUE))
  chk("★★ 只有模型服务那一项带 sub（每一项都带的话左栏高度参差不齐）",
      grepl('sub = if (identical(v, "model")) msub', appc19, fixed = TRUE))
  # ⚠️ 没有 sub 时不能渲染一个空 span：多的那个空行会让所有导航项的间距
  #    看起来不一样（用户看到的是"这几项没对齐"，不会想到是模型那一项干的）。
  chk("★★ 没有 sub 时**不渲染**空的第二行（渲染了就是一行空白占位）",
      grepl("if (is.null(sub)) {", appc19, fixed = TRUE))

  # (d) 保存成功后改那行字：认的必须是 data-nav，不是位置 --------------------
  chk("★★★ item 19：前端改小字认的是 data-nav=\"model\"，不是第几项",
      grepl('document.querySelector(\'.dsapp-rail-link[data-nav="model"]\')',
            jsc19, fixed = TRUE) &&
        # 用户可以把导航项拖成任意顺序（V13.11 item 3），按位置找必然错位
        !grepl(":nth-child", jsc19, fixed = TRUE))
  chk("★★ 改的是内容 + title 一起改（长了会被省略号截掉，title 里要留全的）",
      grepl("sub.textContent = m.sub;", jsc19, fixed = TRUE) &&
        grepl("sub.title = m.sub;", jsc19, fixed = TRUE))
  chk("★ 话题那一项找不到就算了，不报错（删过导航项的用户不该看到红字）",
      grepl("if (!a) return;", jsc19, fixed = TRUE) &&
        grepl("if (!sub) return;", jsc19, fixed = TRUE))

  # (e) CSS：文字得是**竖排的两行**，不能跟标签并排 --------------------------
  # ⚠️ 左栏最窄 180px，模型名（还带厂商前缀）跟标签并排必然溢出 ——
  #    而溢出的表现是盖住旁边的内容，不是换行。
  txt19 <- regmatches(css19, regexpr("\\.dsapp-rail-txt \\{[^}]*\\}", css19))
  chk("★★★ item 19：那行小字是竖着排在标签下面的（flex 列）",
      length(txt19) == 1 &&
        grepl("flex-direction: column", txt19, fixed = TRUE) &&
        # flex 子项默认 min-width:auto，不给 0 的话省略号截不断
        grepl("min-width: 0", txt19, fixed = TRUE))
  sub19 <- regmatches(css19, regexpr("\\.dsapp-rail-sub \\{[^}]*\\}", css19))
  chk("★★ 小字要能截断（超长模型名会把这一项撑高、和别的项对不齐）",
      length(sub19) == 1 &&
        grepl("text-overflow: ellipsis", sub19, fixed = TRUE) &&
        grepl("overflow: hidden", sub19, fixed = TRUE))
  # ⚠️ 品牌那行副标题原来叫 .dsapp-rail-sub，名字腾给小字了 —— 两边撞名的
  #    表现是"改小字的样式，顶上的副标题跟着变"（或者反过来）。
  chk("★ 品牌副标题让了名字（.dsapp-rail-brand-sub），没有和小字撞名",
      grepl(".dsapp-rail-brand-sub {", css19, fixed = TRUE) &&
        length(gregexpr(".dsapp-rail-sub {", css19, fixed = TRUE)[[1]]) == 1L)
}

section("V13.12 item 20：分析进行时不许再「白刷」")

{
  # 用户原话：「分析进行时页面还是会刷新，取消这个机制，实时更新蹦出新结果
  # 就好」。浏览器实测（挂 shiny:outputinvalidated 数重画、再拿 outerHTML
  # 做指纹）：一段 24 秒的生成里 chat-hint 被重画 145 次，其中 95 次画出来
  # **一个字都没变**（66%）—— 那 95 次就是用户嘴里的"刷新"。
  #
  # 所以这一节查的不是"有没有轮询"，是**轮询有没有顺手重画**。判据统一是
  # 同一个形状：定时器照转，但写进 reactiveVal 之前先跟上一拍比一次。
  chc <- strip_comments(paste(readLines("R/mod_chat.R", warn = FALSE),
                              collapse = "\n"))
  rnd <- strip_comments(paste(readLines("R/render.R", warn = FALSE),
                              collapse = "\n"))
  tsk <- strip_comments(paste(readLines("R/mod_tasks.R", warn = FALSE),
                              collapse = "\n"))
  jsc <- strip_js_comments(paste(readLines("www/app.js", warn = FALSE),
                                 collapse = "\n"))

  # ---- (a) 秒数交给前端自己走 ----------------------------------------------
  #
  # ⚠️ 服务端的绝对时间戳**不能**用：两边钟不一定对得上，秒数会当场跳。
  #    传的必须是"画这一格时的秒数"，前端再叠本地流逝。
  chk("★★★ app.js 有前端秒表（不然计时只能靠服务端每 200ms 重画那一格）",
      grepl("function dsappElapsedTick()", jsc, fixed = TRUE) &&
        grepl("setInterval(dsappElapsedTick, 1000);", jsc, fixed = TRUE) &&
        grepl("function dsappFmtDuration(sec)", jsc, fixed = TRUE))
  chk("★★★ 秒表认的是 data-secs + 本地流逝，不是服务端时间戳",
      grepl('.dsapp-elapsed[data-secs]', jsc, fixed = TRUE) &&
        grepl("performance.now()", jsc, fixed = TRUE) &&
        grepl("data-t0", jsc, fixed = TRUE))
  # 两边的分档必须逐字一致，否则用户会看到文字在「45 秒」和「0.8 分钟」
  # 之间来回跳。查三个阈值 + 四个单位词。
  js_fmt <- substr(jsc, regexpr("function dsappFmtDuration", jsc, fixed = TRUE),
                   regexpr("function dsappFmtDuration", jsc, fixed = TRUE) + 420L)
  hl <- strip_comments(paste(readLines("R/health.R", warn = FALSE),
                             collapse = "\n"))
  r_fmt <- substr(hl, regexpr("dsapp_fmt_duration <- function", hl, fixed = TRUE),
                  regexpr("dsapp_fmt_duration <- function", hl, fixed = TRUE) + 420L)
  chk("★★ 前端秒表的格式和服务端 dsapp_fmt_duration() 分档一致",
      grepl("60", js_fmt) && grepl("3600", js_fmt) && grepl("86400", js_fmt) &&
        grepl("60", r_fmt) && grepl("3600", r_fmt) && grepl("86400", r_fmt) &&
        grepl("秒", js_fmt) && grepl("分钟", js_fmt) && grepl("小时", js_fmt) &&
        grepl("天", js_fmt))

  # ---- (b) 对话页：rv$tick 那条 200ms 的重画线整个拆掉 ---------------------
  chk("★★★ `rv$tick` 拆干净了（它当初只有一个用处：顶着「已用 N 秒」走）",
      !grepl("rv$tick", chc, fixed = TRUE) &&
        !grepl("tick = 0", chc, fixed = TRUE))
  chk("★★ 那一格改成带 data-secs 的 .dsapp-elapsed（秒级，data-fmt = secs）",
      grepl('`data-fmt` = "secs"', chc, fixed = TRUE) &&
        grepl('class = "dsapp-elapsed"', chc, fixed = TRUE))
  # ⚠️ 流式那个 observe **不能**跟着删：它不只是计时器，是流式输出的泵
  #    （dsapp_llm_poll(h) 就在那一拍里把子进程吐出来的文本收进来）。
  chk("★★★ 200ms 那个 observe 还在（它是泵，删了会一个字都不流）",
      grepl("invalidateLater(200)", chc, fixed = TRUE) &&
        grepl("dsapp_llm_poll(h)", chc, fixed = TRUE))
  # ★★ 拆 tick 时**真的踩到过**的坑：「已输出 N 字符」跟着定格了。
  #    st 是 new.env()，`st$acc` 读起来没有依赖 —— 那一格原来能走字，靠的
  #    就是被删掉的 rv$tick 每 200ms 强推一次。所以指纹不是"顺手加的"，
  #    是那一格的**唯一**唤醒源。
  chk("★★★ 「已输出 N 字符」有自己的内容指纹（少了它那一格会定格）",
      grepl('stream_sig <- reactiveVal("")', chc, fixed = TRUE) &&
        grepl("if (!identical(sig, isolate(stream_sig()))) stream_sig(sig)",
              chc, fixed = TRUE) &&
        grepl('sprintf("%d|%d|%s", nchar(st$acc %||% ""), nchar(st$reason %||% ""),',
              chc, fixed = TRUE))
  chk("★★ output$hint 读的就是这个指纹（写了没人读等于没写）",
      {
        i <- regexpr("output$hint <- renderUI({", chc, fixed = TRUE)
        rest <- substr(chc, i, nchar(chc))
        j <- regexpr("已输出 %s 字符", rest, fixed = TRUE)
        i > 0 && j > 0 &&
          grepl("stream_sig()", substr(rest, 1L, j), fixed = TRUE)
      })

  # ---- (c) 对话页：两处定时重画改成内容指纹 --------------------------------
  chk("★★★ 循环状态那格用 loop_sig 指纹，不再每 2 秒无条件重画",
      grepl('loop_sig <- reactiveVal("")', chc, fixed = TRUE) &&
        grepl('if (!identical(cur, isolate(loop_sig()))) loop_sig(cur)',
              chc, fixed = TRUE) &&
        !grepl("invalidateLater(2000)", chc, fixed = TRUE))
  # ⚠️ 读的一侧必须 isolate（reactiveval-self-invalidation）：不隔离的话
  #    observer 自己触发自己，定时器变成自激空转。
  chk("★★ ★ loop_sig 的读是 isolate 的（同时读又写同一个值会自激）",
      grepl("isolate(loop_sig())", chc, fixed = TRUE))
  chk("★★★ 实时任务面板走 live_run_data 指纹（原来是每 2 秒重画整张卡）",
      grepl("live_run_data <- reactiveVal(NULL)", chc, fixed = TRUE) &&
        grepl("if (!identical(payload, isolate(live_run_data()))) live_run_data(payload)",
              chc, fixed = TRUE) &&
        grepl("p <- live_run_data()", chc, fixed = TRUE))
  # ⚠️ 光看上面那三条不够：老的 live_run **也可以**是"里面自己 invalidateLater"
  #    的 renderUI，两边都改一半的话，断言全绿而页面照旧每 2 秒重画一次。
  #    所以这里直接翻 output$live_run 自己那块，查两件事：它画的确实是
  #    live_run_data()，而且它自己**没有**定时器。
  chk("★★★ output$live_run 自己不挂定时器，只画 live_run_data()",
      {
        i <- regexpr("output$live_run <- renderUI({", chc, fixed = TRUE)
        if (i < 0) {
          FALSE
        } else {
          rest <- substr(chc, i, nchar(chc))
          j <- regexpr("\n    })", rest, fixed = TRUE)
          blk <- if (j > 0) substr(rest, 1L, j + 5L) else rest
          grepl("live_run_data()", blk, fixed = TRUE) &&
            !grepl("invalidateLater", blk, fixed = TRUE) &&
            !grepl("dsapp_llm_poll", blk, fixed = TRUE)
        }
      })
  chk("★★ 轮询频率仍然是分档的（跑的时候 2 秒、闲着 10 秒）",
      grepl("invalidateLater(if (run) 2000 else 10000)", chc, fixed = TRUE))
  # ⚠️ invalidateLater 必须**无条件**排在最前面：条件式注册会让 observer
  #    再也醒不过来（R/agent.R 顶部有整段说明）。
  chk("★★ ★ live_run_data 的定时器在 return 之前无条件注册",
      {
        i <- regexpr("live_run_data <- reactiveVal(NULL)", chc, fixed = TRUE)
        blk <- substr(chc, i, i + 1200L)
        j_inv <- regexpr("invalidateLater(", blk, fixed = TRUE)
        j_ret <- regexpr("return(", blk, fixed = TRUE)
        j_inv > 0 && (j_ret < 0 || j_inv < j_ret)
      })

  # ---- (d) 实时任务卡片：耗时那一格 --------------------------------
  chk("★★★ 卡片上的耗时也交给前端走（dur 档，分钟级的事用秒读着累）",
      grepl('`data-fmt` = "dur"', rnd, fixed = TRUE) &&
        grepl('class = "dsapp-elapsed"', rnd, fixed = TRUE))
  # ⚠️ 文案承诺必须跟行为一致。原来那句「每 2 秒刷新」在改完之后是**假的**
  #    ——用户会盯着一个不动的卡片等它"刷新"，而它其实只在有新输出时才动。
  chk("★★★ 卡片小字不再承诺「每 2 秒刷新」（那是旧机制的话）",
      grepl("有新输出就往下接", rnd, fixed = TRUE) &&
        !grepl("每 2 秒刷新", rnd, fixed = TRUE) &&
        !grepl("每 2 秒刷新", chc, fixed = TRUE))

  # ---- (e) 任务页：表格也不许每 1.5 秒重画一遍 ------------------------------
  #
  # 这一页原来 1.5 秒 refresh 加一 → tasks() 重查 → DT 整张重画。用户正看
  # 第 80 行的时候每 1.5 秒被弹回表头。
  chk("★★★ 任务页改成内容指纹：一模一样就不写，没人被叫醒就没有重画",
      grepl("tasks_data <- reactiveVal(NULL)", tsk, fixed = TRUE) &&
        grepl("sync_tasks <- function(force = FALSE)", tsk, fixed = TRUE) &&
        grepl("if (!force && identical(df, isolate(tasks_data()))) return(invisible(FALSE))",
              tsk, fixed = TRUE))
  # ⚠️ 这条是这块最容易写回去的地方：tasks() 一旦重新读 refresh()，那个
  #    "唤醒详情栏"的 refresh 加一就又把表格叫醒，白刷绕一圈原样回来。
  chk("★★★ tasks() 不再读 refresh()（读了就等于没改）",
      {
        i <- regexpr("tasks <- reactive({", tsk, fixed = TRUE)
        # 到它自己的 `})` 为止 —— 别用固定长度窗口，那样改几行注释就
        # 会把后面 output$count 的地盘圈进来，红的理由和要查的事无关。
        rest <- substr(tsk, i, nchar(tsk))
        j <- regexpr("})", rest, fixed = TRUE)
        i > 0 && j > 0 && !grepl("refresh()", substr(rest, 1L, j + 1L),
                                 fixed = TRUE)
      })
  # 状态翻转那一拍必须**无条件**写：引擎置假和落库是两步，最后一拍很可能
  # 赶在落库之前，指纹一比"没变化"—— 而那是最后一次轮询，这一页就永远
  # 停在"运行中"了。
  chk("★★★ 状态翻转那一拍强制刷（否则终结状态永远不显示）",
      grepl("flip <- !identical(running, isolate(was_running()))", tsk,
            fixed = TRUE) &&
        grepl("sync_tasks(force = flip)", tsk, fixed = TRUE))
  chk("★★ 手动那几下（刷新/删完/停完/重跑完）都走 force，不再写 refresh",
      length(gregexpr("sync_tasks(force = TRUE)", tsk, fixed = TRUE)[[1]]) == 4L &&
        !grepl("refresh(refresh() + 1)", tsk, fixed = TRUE))
  # ⚠️ 详情栏（current()）**必须**继续跟着 refresh 走：选中那条正在跑时，
  #    实时输出就是在那一格里长出来的。表格不刷 ≠ 日志不刷。
  chk("★★★ 详情栏仍然跟着 refresh 走（表格不刷不等于日志不刷）",
      grepl("identical(engine$state$task_id, id)) refresh()", tsk, fixed = TRUE))

  # ---- (f) 顺手清掉的重复 input id -----------------------------------------
  #
  # 「保存并返回对话」那张卡在**三个**设置页签底部各挂一份，三份原来共用
  # `back_to_chat` 一个 input id。功能上是通的（三个都绑同一个 input，点哪个
  # 都跳），所以一直没人发现 —— 但 Shiny 每次重新绑定都打一条
  # `Duplicate input ID was found ... 3 inputs`，实测跑一轮生成刷出 156 条。
  # 那是**噪音**，长得却像真出了事：这一版就是被它带着查了半天。
  #
  # ⚠️ 同一个函数里的**徽章 output** 早就按 key 分开了（V13.9 item 11 的注释
  #    里写着理由），按钮漏了 —— 所以这两条要成对查，只修一个不算修完。
  stg <- strip_comments(paste(readLines("R/mod_settings.R", warn = FALSE),
                              collapse = "\n"))
  chk("★★★ 三份「保存并返回对话」各用各的 input id（不再重复绑定）",
      grepl('actionButton(ns(paste0("back_to_chat_", key))', stg, fixed = TRUE) &&
        !grepl('actionButton(ns("back_to_chat")', stg, fixed = TRUE) &&
        !grepl("input$back_to_chat", stg, fixed = TRUE))
  chk("★★ 三个 key 各不相同，且每个都调了一次",
      all(vapply(c('dsapp_back_card(ns, key = "ui")',
                   'dsapp_back_card(ns, key = "exec")',
                   'dsapp_back_card(ns, key = "account")'),
                 function(s) length(gregexpr(s, stg, fixed = TRUE)[[1]]) == 1L,
                 logical(1))))
  # 徽章那边同理：output id 重了的话 Shiny 只更新第一个，另外两页是空的，
  # 而且**不报错** —— 比 input 那半边更难发现。
  chk("★★ 三份徽章的 output id 也跟着 key 分开（老规矩，别改回去）",
      grepl('uiOutput(ns(paste0("ready_badge_", key)))', stg, fixed = TRUE) &&
        grepl('paste0("ready_badge_", kk)', stg, fixed = TRUE) &&
        grepl('observeEvent(input[[paste0("back_to_chat_", kk)]], goto_chat())',
              stg, fixed = TRUE))
  # ⚠️ 跳转逻辑只写一份。抄三遍的话，以后改只会改到其中一个，症状是
  #    "在「界面」页点它跳得动、到「账号」页点了没反应"。
  # ⚠️ 判据落在**跳转动作**上，不落在 goto_chat 这个名字上：名字是随手起的，
  #    而 `dsapp_nav_to(state, "chat")` 才是"跳回对话页"这件事本身 ——
  #    它出现两次就是有人抄了一份（另一份多半是原来那个 `input$back_to_chat`
  #    的 handler 没删干净，那一份永远不会被触发）。
  chk("★★ 三个按钮共用同一个 goto_chat()（不抄三遍）",
      length(gregexpr('goto_chat <- function()', stg, fixed = TRUE)[[1]]) == 1L &&
        length(gregexpr('dsapp_nav_to(state, "chat")', stg, fixed = TRUE)[[1]]) == 1L)
}

# =============================================================================
section("V13.13 item 21：点「生成报告」先选格式")
# =============================================================================
# 用户原话：「点击生成报告时可以选格式：html、ppt、word或其它用户自己填写
# 的内容」。
#
# 这一条的判据分三层，缺一层就有一种"看着对、其实是坏的"：
#   (a) **格式表**只有一份，界面 / 提示词 / 报错都从它推导 —— 抄成两份的话
#       两边会慢慢分叉，而症状是"界面上有这个选项、点了却按另一种格式生成"；
#   (b) **归一化**把脏输入兜住：不认识的 key 退回 html，而不是让
#       `[[` 取到 NULL 再被 paste0 静默变成空文件名（那样模型会自己编一个）；
#   (c) **内容要求那几条不许被格式块挤掉** —— 它们是"只写跑过的""图别现编"
#       这些红线，加格式时最省事的改法就是再抄一串编号，抄的过程里掉一条
#       谁也不会发现。
{
  fmt_all <- dsapp_report_format_choices()

  # ⚠️⚠️ radioButtons 的 choices 里，**名字是显示出来的标签、值是送到服务端的
  #    东西**（`c(标签 = 值)`）。写反过一次：送出去的是 "HTML 网页" 这个中文串，
  #    `dsapp_report_format()` 一个都不认识 → 静默退回 html → "选了 Word、
  #    出来的是 HTML"，全程不报错。所以这两条要**分别**钉住名字和值。
  # ⚠️ `c(标签 = 值)` —— 所以 **names() 是标签、unname() 是值**，别读反。
  chk("★★★ 界面上显示的标签是三种预设 + 一个「其它」",
      length(fmt_all) == 4L &&
        identical(names(fmt_all)[1:3],
                  c("HTML 网页", "Word 文档", "PPT 演示")) &&
        identical(names(fmt_all)[4], "其它（自己填）"),
      paste(names(fmt_all), collapse = " / "))
  chk("★★★ 送到服务端的是 html/docx/pptx/other（不是把中文标签当值发出去）",
      identical(unname(fmt_all), c("html", "docx", "pptx", "other")),
      paste(unname(fmt_all), collapse = " / "))
  # 这两条合起来才叫"选项是对的"：只有标签对 = 点了没反应（中文串谁也认不得、
  # 静默退回 html），只有值对 = 界面上一串英文。所以再加一条**端到端**的：
  # 界面送出来的那个值，拿去归一化必须回到它自己。
  chk("★★★ 界面选项的每个值都认得出自己（写反了就会全部退回 html）",
      all(vapply(unname(fmt_all),
                 function(k) identical(dsapp_report_format(k)$key, k),
                 logical(1))),
      paste(unname(fmt_all),
            vapply(unname(fmt_all), function(k) dsapp_report_format(k)$key,
                   character(1)),
            sep = "->", collapse = " "))

  # ---- (b) 归一化 --------------------------------------------------------
  norm <- function(f, c = "") dsapp_report_format(f, c)
  chk("★★★ 三种预设各自对到自己的文件名",
      identical(norm("html")$file, "分析报告.html") &&
        identical(norm("docx")$file, "分析报告.docx") &&
        identical(norm("pptx")$file, "分析报告.pptx"))
  # ⚠️ 不认识的 key 必须**退回 html**。直接拿去 `[[` 会得到 NULL，然后
  #    `f$file` 是 NULL、paste0 把它变成空串 —— 提示词里就成了"文件名 ``"，
  #    模型会自己编一个，而这一路**不报任何错**。
  chk("★★★ 不认识的格式退回 html（不是留下一个空文件名让模型自己编）",
      identical(norm("wat")$key, "html") &&
        identical(norm("")$key, "html") &&
        identical(norm(NULL)$key, "html") &&
        nzchar(norm("wat")$file))
  chk("★★ 格式值两端有空格也认（界面回传里出现过 `\" docx \"` 这种）",
      identical(norm("  docx  ")$key, "docx"))
  # ⚠️ 向量进来只取第一个。input 偶尔会是长度 >1 的（同 id 的元素不止一个），
  #    不取第一个的话 `%in%` 会给出一串 TRUE/FALSE，下面的 if 直接报错。
  chk("★★ 传进来一个向量时不炸，取第一个",
      identical(norm(c("pptx", "docx"))$key, "pptx"))

  # ---- 选了「其它」却没填 -------------------------------------------------
  # ⚠️ 这一条是**故意不退回 html** 的：用户明确说了"不要那几种"，静默给他
  #    一份 html 是把他没要的东西塞给他。正确行为是让模型先问清楚。
  o_empty <- norm("other", "   ")
  chk("★★★ 选了「其它」但没填 → 不生成、也不偷偷退回 html，而是先问清楚",
      identical(o_empty$key, "other") &&
        !nzchar(o_empty$file) &&
        grepl("不要", o_empty$spec) && grepl("问他", o_empty$spec),
      substr(o_empty$spec, 1, 40))
  o_txt <- norm("other", "一份可以直接贴进公众号的图文")
  chk("★★★ 「其它」把用户那句话原样带进提示词",
      identical(o_txt$key, "other") &&
        grepl("一份可以直接贴进公众号的图文", o_txt$spec, fixed = TRUE) &&
        identical(o_txt$label, "一份可以直接贴进公众号的图文"))

  # ---- (a) 只有一份格式表 ------------------------------------------------
  pr_src <- paste(readLines("R/prompts.R", warn = FALSE), collapse = "\n")
  chk("★★★ 格式表只在 prompts.R 里定义一次（界面不许自己抄一份 choices）",
      length(gregexpr("DSAPP_REPORT_FORMATS <- list(", pr_src, fixed = TRUE)[[1]]) == 1L &&
        !grepl("HTML 网页", paste(readLines("R/mod_chat.R", warn = FALSE),
                                  collapse = "\n"), fixed = TRUE))

  # ---- (c) 内容要求那几条一条都不能少 -------------------------------------
  #
  # ⚠️ 逐条按**关键词**查，不查编号：编号在重排里会变，而这几句话是判据。
  for (fm in c("html", "docx", "pptx", "other")) {
    p <- dsapp_report_prompt("（事实清单占位）", fm,
                             if (fm == "other") "Markdown 源码" else "")
    miss <- character(0)
    # 1 排版照技能来 + 六段结构；2 只写跑过的；3 图要真实存在；
    # 4 失败照实写；5 问要不要改
    if (!grepl("Biomamba教程制作规则", p, fixed = TRUE)) miss <- c(miss, "技能排版")
    if (!grepl("只写真的跑过的东西", p, fixed = TRUE)) miss <- c(miss, "不许编")
    if (!grepl("真实存在", p, fixed = TRUE))          miss <- c(miss, "图别现编")
    if (!grepl("不是宣传材料", p, fixed = TRUE))      miss <- c(miss, "失败照实写")
    if (!grepl("要不要改", p, fixed = TRUE))          miss <- c(miss, "生成后再询问")
    if (!grepl("（事实清单占位）", p, fixed = TRUE))  miss <- c(miss, "事实清单")
    chk(sprintf("★★★ %s 那一版把五条内容红线全带上了", fm),
        !length(miss), paste(miss, collapse = "、"))
  }

  # ⚠️ 事实清单必须在**格式块之前**。倒过来的话模型先读到"写成 docx"，
  #    再读到一大段执行清单，它会拿清单当正文直接开写 —— 顺序是有用的。
  p_h <- dsapp_report_prompt("（事实清单占位）", "html")
  chk("★★ 事实清单排在「产物格式」之前（顺序反了模型会拿清单当正文）",
      regexpr("（事实清单占位）", p_h, fixed = TRUE)[1] <
        regexpr("产物格式", p_h, fixed = TRUE)[1])

  # ---- 每种格式的落盘做法要说清楚 ----------------------------------------
  #
  # ⚠️ 这一组查的是"提示词里到底有没有那条**可执行**的做法"。只写"请生成一个
  #    docx"而不说用什么转，模型会去挑一个这台机器上没有的工具
  #    （python-docx / python-pptx 都没装），失败一轮再试下一轮。
  p_d <- dsapp_report_prompt("x", "docx")
  p_p <- dsapp_report_prompt("x", "pptx")
  chk("★★★ Word 那条给了 pandoc 的确切命令和输出文件名",
      grepl("pandoc 报告正文.md -o 分析报告.docx", p_d, fixed = TRUE))
  chk("★★★ PPT 那条也是，而且**带上了 --slide-level=2**",
      grepl("pandoc 报告正文.md -o 分析报告.pptx --slide-level=2", p_p,
            fixed = TRUE))
  # 这句是实测出来的：不加 --slide-level=2 时只有 `#` 分页，一份报告只出
  # 五六页；加了之后 `#` 和 `##` 都分页。提示词里必须交代，否则模型会写出
  # 六页的"报告 PPT"，而且它自己看不出来少了。
  chk("★★ PPT 那条解释了为什么要加 --slide-level=2（默认只按一级标题分页）",
      grepl("默认只有", p_p, fixed = TRUE) &&
        grepl("都**分页", p_p, fixed = TRUE))
  # ⚠️ 三条都要**点名禁掉**没装的那两个库：不禁的话模型第一步就写
  #    `import docx`，报错之后再自己找路 —— 白烧一轮，还可能干脆改个后缀交差。
  chk("★★★ Word / PPT 两条都点名禁掉了没装的 python 库",
      grepl("python-docx", p_d, fixed = TRUE) &&
        grepl("python-pptx", p_p, fixed = TRUE))
  chk("★★★ HTML 那条仍然要求**自包含**（不许引 CDN）",
      grepl("自包含", p_h, fixed = TRUE) && grepl("CDN", p_h, fixed = TRUE))
  # 「其它」那一格的红线：做不了就说做不了，**不许改后缀冒充**。
  p_o <- dsapp_report_prompt("x", "other", "PDF")
  chk("★★★ 自填那一格说清了 PDF 出不来（这台机器没有 LaTeX）",
      grepl("PDF 出不来", p_o, fixed = TRUE))
  chk("★★★ 而且明令禁止「偷偷换格式 / 只改后缀名冒充」",
      grepl("偷偷换", p_o, fixed = TRUE) && grepl("后缀名", p_o, fixed = TRUE))
  chk("★★ 自填那一格给了工具清单（pandoc / officer / rmarkdown）",
      grepl("pandoc", p_o, fixed = TRUE) && grepl("officer", p_o, fixed = TRUE))

  # ---- mod_chat.R 那一侧 -------------------------------------------------
  chat_src <- paste(readLines("R/mod_chat.R", warn = FALSE), collapse = "\n")
  chk("★★★ 点按钮先弹窗，不再直接发（report_btn 里不许出现 dsapp_chat_send）",
      {
        i <- regexpr('observeEvent(input$report_btn,', chat_src, fixed = TRUE)[1]
        j <- regexpr('observeEvent(input$report_go,', chat_src, fixed = TRUE)[1]
        i > 0 && j > i && !grepl("dsapp_chat_send", substr(chat_src, i, j - 1),
                                 fixed = TRUE)
      })
  chk("★★★ 确认那一刻才算执行清单（弹窗期间清单会过期）",
      grepl('dsapp_report_digest(sid, con = dsapp_db(cfg()))',
            substr(chat_src,
                   regexpr('observeEvent(input$report_go,', chat_src,
                           fixed = TRUE)[1],
                   regexpr('observeEvent(input$send_key,', chat_src,
                           fixed = TRUE)[1]), fixed = TRUE))
  chk("★★★ 确认时把格式和自填内容一起传下去",
      grepl("dsapp_report_prompt(digest, fmt, custom)", chat_src, fixed = TRUE))
  # ⚠️ 没填就拦，且**不关弹窗** —— 关掉的话用户得从头再点一遍，他只是漏填一格。
  #
  # ⚠️ 「不关弹窗」这件事是**语言语义**保证的（那是个 `return()`，后面的
  #    `removeModal()` 到不了），不是"位置比较"保证的。所以判据就钉在
  #    **那句 return 上** —— 别写成"提示出现在 removeModal 之前"，那句在
  #    源码里恒为真（if 块后面就跟着一个 removeModal），查了等于没查。
  #    真正会坏的方式是有人把 `return()` 去掉：那时弹窗会关、而且带着空的
  #    自填内容直接发出去 —— 正好是这条断言要挡的。
  chk("★★★ 选了「其它」却没填 → 弹提示，而且是 `return(showNotification(...))`",
      {
        i <- regexpr('observeEvent(input$report_go,', chat_src, fixed = TRUE)[1]
        blk <- substr(chat_src, i, i + 2600)
        p_warn <- regexpr("选了「其它」，先写一句", blk, fixed = TRUE)[1]
        p_dig  <- regexpr("digest <- tryCatch", blk, fixed = TRUE)[1]
        p_warn > 0 && p_dig > p_warn &&
          grepl('return(showNotification("选了「其它」', blk, fixed = TRUE)
      })
  chk("★★ 自填那一格是 renderUI（不是 conditionalPanel：条件串要手写命名空间，写错不报错）",
      grepl('output$report_custom_slot <- renderUI', chat_src, fixed = TRUE) &&
        !grepl('conditionalPanel(condition = "input[', chat_src, fixed = TRUE))
  chk("★★ 默认仍然是 html（item 21 加的是「能选」，不是改默认值）",
      grepl('selected = "html"', chat_src, fixed = TRUE))
}

# =============================================================================
section("V13.14 item 22：单次回复上限的最右一格 = 「不设上限」")
# 用户原话：「22、单次回复上限的最右侧应该是"不设上限"」。
#
# ⚠️ 这一条的危险**不在"加一格"**，而在那一格是不是真的。分三层：
#   (a) 那一格得真的**停得住** —— 滑块只会停在 min + k×step 这些点上。格子
#       算错（顺手写成 `r$max * 1.01` 之类）的表现是"拖到头还是 10,000,000"，
#       看起来像这次改动没生效，其实是滑块自己吸附回去了；
#   (b) 停到那一格必须**真的**把上限交回给厂商 —— 请求体里不带 max_tokens。
#       任何我们填得出来的数字都是一个上限（10485760 也是），只有"不发"
#       才是真的不设；
#   (c) **下游不许把它悄悄换回来**。这条最容易漏，而且漏了不报错：R/detach.R
#       里有一条 `max_tokens < 512 → 65536` 的兜底，0 会被它换成 64K ——
#       于是"页面开着跑"和"关掉页面挂机跑"结果不一样，且哪儿都不报错。
{
  mr   <- dsapp_param_range("", NULL, "max_tokens")
  smax <- dsapp_maxtok_slider_max(mr)

  # ---- (a) 那一格真的停得住 ----------------------------------------------
  chk("★★★ 「不设上限」落在滑块的整数格点上（落不上就永远拖不过去）",
      isTRUE(all.equal((smax - mr$min) %% mr$step, 0)) && smax > mr$max,
      sprintf("min=%s max=%s step=%s → 滑块最右=%s", mr$min, mr$max, mr$step,
              smax))
  chk("★★★ 最右那格塌成哨兵 0；**倒数第二格还是真的 10485760**（不是整条右端都废了）",
      identical(dsapp_maxtok_from_slider(smax, mr), DSAPP_MAXTOK_UNLIMITED) &&
        isTRUE(all.equal(dsapp_maxtok_from_slider(smax - mr$step, mr), mr$max)))
  chk("★★★ 哨兵 0 回到滑块上就是最右那一格（存了 0、界面却显示 8K 的话就是假的）",
      isTRUE(all.equal(dsapp_maxtok_to_slider(DSAPP_MAXTOK_UNLIMITED, mr), smax)))
  # 往返：有限值原样回来，无限值认得出自己。少任何一半都会出现"用户设的值
  # 在一次界面重建之后变成另一个值"。
  chk("★★ 有限值在 值↔滑块 之间往返不变形",
      all(vapply(c(1024, 8192, 65536, 1048576, 10485760),
                 function(v) isTRUE(all.equal(
                   dsapp_maxtok_from_slider(dsapp_maxtok_to_slider(v, mr), mr),
                   v)), logical(1))))

  # ---- 判据本身 ----------------------------------------------------------
  chk("★★ 0 / 负数 / 空串 / NA 都是「不设上限」",
      dsapp_maxtok_is_unlimited(0) && dsapp_maxtok_is_unlimited(0L) &&
        dsapp_maxtok_is_unlimited(-1) && dsapp_maxtok_is_unlimited("") &&
        dsapp_maxtok_is_unlimited(NA) && dsapp_maxtok_is_unlimited("0"))
  # ⚠️⚠️ NULL 必须是 FALSE。NULL 是"还没设过"（控件刚建起来、设置还没载入），
  #    那时候该用默认档 65536，而不是替用户做一个"以后都不设上限"的决定 ——
  #    那个决定会让每一次请求都变成"厂商默认上限"，用户完全不知道发生了什么。
  chk("★★★ NULL 不算「不设上限」（那是「还没设过」，不是用户的选择）",
      !dsapp_maxtok_is_unlimited(NULL) &&
        !dsapp_maxtok_is_unlimited(numeric(0)) &&
        !dsapp_maxtok_is_unlimited(1024) && !dsapp_maxtok_is_unlimited(65536))
  # 这三条是实测踩出来的崩溃：`NULL[1]` 是 NULL、`as.numeric(NULL)` 是
  # numeric(0)、`if (!is.finite(numeric(0)))` 报 **argument is of length zero**
  # —— 报错指着那个 if，和"滑块没给值"看不出任何关系。
  chk("★★ 传 NULL 不炸（`if (!is.finite(numeric(0)))` 是 argument is of length zero）",
      isTRUE(all.equal(dsapp_fmt_maxtok(NULL), "—")) &&
        is.null(dsapp_maxtok_from_slider(NULL, mr)) &&
        isTRUE(all.equal(dsapp_maxtok_to_slider(NULL, mr), mr$min)))

  # ---- 显示 --------------------------------------------------------------
  # ★ V15.5 item 6：这四个字从「不设上限」改成了「跟随模型」。
  #   ⚠️ 不是换个说法：0 的下游含义变了 —— 原来它只是"请求体里不带
  #      max_tokens"，现在它是"这一次的可用总量 = 这个模型自己的上下文
  #      窗口"（见 dsapp_ctx_limit）。用户看到的判据还是这四个字。
  chk("★★★ 0 显示成「跟随模型」，其余照旧（这四个字就是用户看到的判据）",
      identical(dsapp_fmt_maxtok(DSAPP_MAXTOK_UNLIMITED), "跟随模型") &&
        identical(dsapp_fmt_maxtok(0), "跟随模型") &&
        identical(dsapp_fmt_maxtok(65536), "65,536") &&
        identical(dsapp_fmt_maxtok(65536, short = TRUE), "64K"))

  # ---- 「为什么 state 那条路要绕开 clamp」的理由是真的 --------------------
  # ⚠️ 这两条不是在测新功能，是在**钉住注释里的理由**。理由不成立了（clamp
  #    不再夹 0、或者 %||% 哪天学会挡 NA），绕开它的那段代码就该被重新审视 ——
  #    否则它会以"历史遗留"的形式永远留着，而没人知道它当初防的是什么。
  chk("★★ dsapp_param_clamp 确实会把 0 夹成 min（所以 state 那条路必须绕开它）",
      isTRUE(all.equal(
        dsapp_param_clamp("", NULL, "max_tokens", DSAPP_MAXTOK_UNLIMITED,
                          default = 65536), mr$min)))
  # ★★ 这一条**写反过一次**，值得留着：我原来在 mod_model.R 里写的是
  #    「`%||%` 只挡 NULL、不挡 NA（NA %||% x 还是 NA）」—— 那是**错的**。
  #    本仓的 `%||%`（R/utils.R）第 4 行就是 `if (is.na(a[1])) return(b)`，
  #    NA **会**走 fallback。（把 Shiny 自带的 `%||%` 或者 rlang 那个记成
  #    这个仓的行为了 —— 那两个确实只挡 NULL。）
  #    ⚠️ 所以这一条钉的是**真实行为**，不是我以为的行为：清空输入栏给的是
  #       NA，`input$max_tokens %||% rv$maxtok` 于是返回 rv$maxtok。
  #       那句话之所以仍然对，是因为 rv$maxtok 在它自己那条 observer 里
  #       已经归一成哨兵 0 了（ignoreNULL = TRUE 挡不住 NA，NA 不是 NULL）——
  #       两条路殊途同归。**别把这条断言改回"NA 挡不住"**，那样它会红，
  #       而红的意思看起来像"清空输入栏坏了"，差得很远。
  chk("★★ `%||%` 在这个仓里**挡得住 NA**（清空输入栏时 mt_want 走 rv$maxtok）",
      isTRUE(all.equal(NA %||% 65536, 65536)) &&
        isTRUE(all.equal(NULL %||% 65536, 65536)))
  # ⚠️ 而真正保证"清空 = 不设上限"的是这一条：rv 那条 observer 的 ignoreNULL
  #    是 TRUE —— **它挡不住 NA**（NA 不是 NULL），所以清空会正常触发并把
  #    rv$maxtok 写成哨兵。哪天有人把这里改成 `if (is.null(...)) return()` 之外
  #    的花样、或者给 input 加一个把 NA 转成 NULL 的清洗，这条会先红。
  mm22 <- strip_comments(paste(readLines("R/mod_model.R", warn = FALSE),
                               collapse = "\n"))
  chk("★★★ 清空输入栏真的会走到 rv（ignoreNULL 挡不住 NA，所以它是通的）",
      grepl(paste0("observeEvent(input$max_tokens, {\n",
                   "      if (is.null(input$max_tokens)) return()\n",
                   "      rv$maxtok <- if (dsapp_maxtok_is_unlimited(input$max_tokens))"),
            mm22, fixed = TRUE))

  # ---- (c) 下游不许把 0 悄悄换回来 ---------------------------------------
  # ⚠️⚠️ 这里**必须**先剥注释再查。`max_tokens < 512L` 这个旧形状就写在上面
  #     那段 ⚠️ 说明里（"原来那条兜底是 `max_tokens < 512L → 65536L`"）——
  #     不剥的话，那条**反向**断言命中的是注释，永远红，而红的意思看起来像
  #     "旧形状还在代码里"，差得很远。（写完当场踩到。）
  det22_src <- strip_comments(paste(readLines("R/detach.R", warn = FALSE),
                                  collapse = "\n"))
  # ⚠️ 这条兜底是 V13.7「离开页面之后 AI 接着把活干完」加的，原来的形状是
  #    `max_tokens < 512L → 65536L`。0 会被它吃掉。
  # ★ V15.5 item 6：快照里带的那一格换成了 ctx_limit（单次使用上限），
  #   兜底值也从 65536 换成了 DSAPP_CTX_FOLLOW（0）—— 因为 0 现在是
  #   "跟随模型"这个**合法选择**，不再是"坏值"。原判据（不许把 0 换掉）
  #   没变，变的是它落在哪个变量上。
  chk("★★★ 脱离会话那一份快照不把 0 当成「坏值」换成 65536",
      grepl("ctx_limit <- suppressWarnings(as.numeric(p$ctx_limit)[1])",
            det22_src, fixed = TRUE) &&
        grepl("if (!is.finite(ctx_limit) || ctx_limit < 0) ctx_limit <- DSAPP_CTX_FOLLOW",
              det22_src, fixed = TRUE) &&
        !grepl("max_tokens < 512L", det22_src, fixed = TRUE))

  # ⚠️ 「思考吃光了额度、一个字正文都没有」时给的建议。选了不设上限的人再去
  #    "把上限调大"是没有出路的 —— 那时候上限是厂商那一侧的默认值，我们能调
  #    的只有思考强度。指错方向的提示比没有提示更消耗人。
  chk_src <- paste(readLines("R/mod_chat.R", warn = FALSE), collapse = "\n")
  # ★ V15.5 item 6：判据从 `mt_now` 改成 `state$ctx_limit`。
  #   ⚠️⚠️ 这一条现在钉的是一个**差点写错**的地方：mt_now 是推导出来的回复
  #      额度，永远是个正数，拿它去判 `dsapp_maxtok_is_unlimited()` 恒 FALSE
  #      ——「跟随模型」那一段建议会变成走不到的死代码，而界面上看不出来。
  #      所以这里不仅要求 `unlim` 读 state$ctx_limit，还要求那句建议里
  #      不许再出现 `state$max_tokens`（那一格已经不存在了）。
  chk("★★★ 选了「跟随模型」时，那句建议不再叫人「把上限调大」",
      grepl("unlim <- dsapp_maxtok_is_unlimited(state$ctx_limit)",
            chk_src, fixed = TRUE) &&
        grepl("dsapp_fmt_maxtok(mt_now)", chk_src, fixed = TRUE) &&
        !grepl("state$max_tokens", chk_src, fixed = TRUE))

  # ---- 源码层：判据一律在**父进程**算好再传给 callr 子进程 ---------------
  llm_src <- paste(readLines("R/llm.R", warn = FALSE), collapse = "\n")
  chk("★★★ 请求体里发不发 max_tokens 由 omit_max_tokens 决定（和 temperature 同一个套路）",
      grepl("if (!isTRUE(omit_max_tokens)) body$max_tokens <- max_tokens",
            llm_src, fixed = TRUE))
  chk("★★★ 这个判断是在**父进程**算好传进去的（子进程里没有 DS_App 的函数）",
      grepl("omit_max_tokens = dsapp_maxtok_is_unlimited(max_tokens)",
            llm_src, fixed = TRUE))
  chk("★★ 短任务那条路（起标题）也判了",
      grepl("if (!dsapp_maxtok_is_unlimited(max_tokens)) body$max_tokens <- max_tokens",
            llm_src, fixed = TRUE))
  # ⚠️ 超时是拿 max_tokens 折算的。不设上限时那个数不能参与折算 —— 否则
  #    0/20 = 0，`max(60, 0)` 还是 60 秒：一次不设上限的长回答会在第 60 秒
  #    被掐断，而界面上的表现是"答到一半停了"。
  chk("★★★ 不设上限时不拿它折算超时（不然 max(60, 0/20) = 60 秒就掐断）",
      grepl("mt_timeout <- if (dsapp_maxtok_is_unlimited(max_tokens)) 65536 else max_tokens",
            llm_src, fixed = TRUE))

  mm_src <- paste(readLines("R/mod_model.R", warn = FALSE), collapse = "\n")
  # ★ V15.5 item 6：写进 state 的那一格换成了 ctx_limit（单次使用上限），
  #   绕开 clamp 的理由一字不改（clamp 会把 0 夹成 min，而 0 是合法哨兵）。
  chk("★★★ 写进 state 的哨兵不过 dsapp_param_clamp（过了就被夹成 1024）",
      grepl("state$ctx_limit <- if (dsapp_maxtok_is_unlimited(mt_want)) {",
            mm_src, fixed = TRUE) &&
        grepl("DSAPP_CTX_FOLLOW", mm_src, fixed = TRUE) &&
        !grepl("state$max_tokens <- ", mm_src, fixed = TRUE))
  # ⚠️ 清空输入栏是**一个动作**，要按一个动作去接。这里原来有个
  #    `if (!is.finite(v)) return()`，清空恰好让 v 变成 NA —— 那个 return 的
  #    行为是"用户清空输入栏，界面一动不动"，看着就是这个框坏了。
  chk("★★★ 输入栏清空时滑块跟着走到最右（不许在 v 不是有限数时 return）",
      {
        i <- regexpr('observeEvent(input$max_tokens, {\n      if (isTRUE(syncing())) return()',
                     mm_src, fixed = TRUE)[1]
        i > 0 &&
          grepl("target <- if (dsapp_maxtok_is_unlimited(v)) dsapp_maxtok_slider_max(r)",
                substr(mm_src, i, i + 1400), fixed = TRUE)
      })
  chk("★★★ 滑块到最右时把输入栏**清空**（updateNumericInput(value = NA)，实测能清空）",
      grepl("updateNumericInput(session, \"max_tokens\", value = NA)",
            mm_src, fixed = TRUE))

  # ---- ★★★ 真的发一次请求，看请求体里到底有没有这个字段 -------------------
  #
  # 上面查的全是"源码里写了什么"。这一条把请求**真的**发出去 —— 打到本机一个
  # 临时 HTTP 服务上，再把它收到的那个 JSON 读回来。这是唯一能证明"请求里
  # **真的**没带这个字段"的办法：源码里那行守卫写对了、却在后面被另一行覆盖
  # 掉，源码级断言是看不见的（body$max_tokens 只要在函数后面再出现一次就完
  # 了，而且写的人多半是无意的）。
  mt_bodies <- tryCatch(.chk_llm_body(list(
    list(model = "kimi-k3",         max_tokens = 8192),
    list(model = "deepseek-v4-pro", max_tokens = DSAPP_MAXTOK_UNLIMITED))),
    error = function(e) {
      cat("       （临时 HTTP 服务起不来：", conditionMessage(e), "）\n"); NULL
    })
  mt_of <- function(m) Find(function(b) identical(b$model, m), mt_bodies)
  b_lim <- mt_of("kimi-k3")
  b_inf <- mt_of("deepseek-v4-pro")

  chk("★★★ 假服务收到了这两条请求（下面两条的前提）",
      length(mt_bodies) >= 2, extra=sprintf("收到 %d 条", length(mt_bodies)))
  if (length(mt_bodies) >= 2) {
    chk("★★★ 对照组：给了 8192 的请求体里**带着** max_tokens = 8192（不是把所有人都掐了）",
        !is.null(b_lim) && isTRUE(all.equal(b_lim$max_tokens, 8192)),
        extra=paste(names(b_lim), collapse = ","))
    chk("★★★ 不设上限的请求体里**没有** max_tokens 这个键（不是发了 0、也不是发了 10485760）",
        !is.null(b_inf) && !("max_tokens" %in% names(b_inf)),
        extra=paste(names(b_inf), collapse = ","))
    chk("★★ 两条都照常带着 model / messages / stream（不是整个请求都残了）",
        !is.null(b_inf) && identical(b_inf$model, "deepseek-v4-pro") &&
          isTRUE(b_inf$stream) && length(b_inf$messages) >= 1)
  }
}

# =============================================================================
section("V13.14 item 23：帮助页独立到左侧导航栏")
# 用户原话：「23、帮助页面独立到左侧导航栏」。
#
# 它原来是**设置页的第四个页签**。这一节盯的是"搬干净了没有"——搬一半是
# 这类改动最典型的坏法，而且两种坏法都不报错：
#   · 左栏加了项、旧页签没删 → 两个入口，用户点哪个都对，但设置页那排页签
#     多一个不该在那儿的（它和"改设置"不是一类事，见 mod_help.R 顶部）；
#   · 旧页签删了、左栏没加 → 帮助页**整个消失**，没有任何报错，界面上一切正常。
{
  # ⚠️⚠️ 一律先 **strip_comments**。这一节里有好几条是"某个字符串**不许**
  #     出现"的反向断言，而 mod_help.R / app.R 的注释里恰恰**要**提到那些
  #     字符串（"这一页没有 server，所以没有 mod_help_server()"、
  #     "这张卡原来长着「保存并开始使用」"）—— 不剥注释的话，这些反向断言
  #     命中的是注释，永远红，而红的意思看起来像"搬页没搬干净"。
  #     这个坑这一节踩了两次（写完当场红的），所以统一剥。
  mod23 <- strip_comments(paste(readLines("R/mod_help.R", warn = FALSE),
                                collapse = "\n"))
  set23 <- strip_comments(paste(readLines("R/mod_settings.R", warn = FALSE),
                                collapse = "\n"))
  uip23 <- strip_comments(paste(readLines("R/uiprefs.R", warn = FALSE),
                                collapse = "\n"))
  app23 <- strip_comments(paste(readLines("app.R", warn = FALSE),
                                collapse = "\n"))

  # ---- (a) 左栏那一项 -----------------------------------------------------
  chk("★★★ 左栏导航表里有 value = \"help\" 这一项",
      "help" %in% vapply(DSAPP_NAV_ITEMS, function(x) x$value, character(1)))
  # ⚠️ 不给 role：帮助是给**用户**的，藏起来它就没用了。写成 role = "admin"
  #    的话普通账号看不到这一页，而需求是让所有人都够得着。
  chk("★★★ 而且它对所有人可见（没写 role —— 写了 role 普通账号就看不到帮助了）",
      {
        it <- Find(function(x) identical(x$value, "help"), DSAPP_NAV_ITEMS)
        !is.null(it) && !nzchar(it$role %||% "") && identical(it$label, "帮助")
      })
  # ⚠️ value 只能是小写字母：selftest 里「左栏导航项与 navset 的 value
  #    一一对应」那条用的正则是 `[a-z]+`，带大写/连字符会让那一条**静默失效**
  #    （抠不到 → 两边都少一项 → setequal 照样成立）。
  chk("★★ help 是小写字母（那条一一对应的断言用的正则是 [a-z]+）",
      grepl('value = "help"', uip23, fixed = TRUE))

  # ---- (b) 搬到左栏那一层了 ----------------------------------------------
  chk("★★★ app.R 里有了这一页，而且 value 和导航表里那个逐字相同",
      grepl('nav_panel("帮助", value = "help", mod_help_ui("help"))', app23,
            fixed = TRUE))
  # ⚠️ 这一页**没有 server**（整页静态、一个 input 都没有）。写一个空的
  #    mod_help_server 也行，但那样 app.R 里会多一行看不出用途的调用 ——
  #    这一条钉住"确实没有"，将来真加了 server 就必须连这条一起改，
  #    改的时候会看见上面这段说明。
  chk("★ 帮助页没有 server（整页静态，一个 input 都没有）",
      !grepl("mod_help_server", app23, fixed = TRUE) &&
        !grepl("mod_help_server", mod23, fixed = TRUE))

  # ---- (c) 旧页签真的走了 -------------------------------------------------
  chk("★★★ 设置页里**没有**帮助页签了（搬一半 = 两个入口）",
      !grepl('nav_panel("帮助"', set23, fixed = TRUE) &&
        !grepl("dsapp-help-img", set23, fixed = TRUE) &&
        !grepl("Biomamba_zhushou", set23, fixed = TRUE))
  chk("★★ 设置页剩三个页签（界面 / 执行 / 账号）",
      length(gregexpr("nav_panel(", set23, fixed = TRUE)[[1]]) == 3L)
  # ⚠️ 「保存并开始使用」V13.9 item 11 就从帮助页赶走了（用户原话：「不应该
  #    出现在帮助页面」）。搬页时最容易顺手把整块内容一起搬过去，那一条就
  #    白做了 —— 所以在新家再钉一遍。
  chk("★★★ 新家也没有「保存并开始使用」（V13.9 item 11 的结论不许被搬页冲掉）",
      !grepl("保存并开始使用", mod23, fixed = TRUE) &&
        !grepl("back_to_chat", mod23, fixed = TRUE))

  # ---- (d) 内容一个字都没丢 ----------------------------------------------
  chk("★★★ 客服二维码那张卡在新家里（item 12 的结论也不许被搬页冲掉）",
      grepl("dsapp-help-img", mod23, fixed = TRUE) &&
        grepl('dsapp_asset("help-wx.png")', mod23, fixed = TRUE) &&
        grepl("Biomamba_zhushou", mod23, fixed = TRUE))
  chk("★★ 使用说明那几条也在（含 V13.1 item 8 那个「按账号隔离」的说法）", {
    # ⚠️ 逐条按关键词查。搬页时漏掉一条 `<li>` 是完全静默的。
    all(vapply(c("第一次提交任务时", "这个对话自己的环境", "按账号隔离"),
               function(k) grepl(k, mod23, fixed = TRUE), logical(1)))
  })
  chk("★★ 版本号和平台限制那两块也在（出事了第一句话就是问版本）",
      grepl('sprintf("应用版本：V%s", DSAPP_VERSION)', mod23, fixed = TRUE) &&
        grepl("dsapp_platform_note()", mod23, fixed = TRUE))
  # ⚠️ 模块的 UI 必须带命名空间。这一页现在一个 input 都没有，所以命名空间
  #    只用在一个容器 id 上 —— 但**不能因此把 NS(id) 删掉**：删了之后，
  #    以后有人往这里加 textInput("foo")，就会和别的页撞 id，而 Shiny 撞 id
  #    不报错，只是那个 input 永远拿不到值。
  chk("★★ mod_help_ui 是带命名空间的模块（不然以后加 input 会撞 id，且不报错）",
      grepl("mod_help_ui <- function(id) {", mod23, fixed = TRUE) &&
        grepl("ns <- NS(id)", mod23, fixed = TRUE))

  # ---- (e) 三处清单都加了这个新文件 --------------------------------------
  # ⚠️ 这三处漏任何一处都是**静默失效**，理由写在 app.R 那段注释里。
  #    （deploy.sh 那一处另有「部署清单与 app.R 的 source 列表一致」和
  #     「app.R 的列表覆盖 R/ 下每一个文件」两条兜着，这里只钉自检自己。）
  chk("★★★ mod_help.R 在三处清单里（app.R / deploy.sh / selftest）",
      grepl('"mod_help.R"', app23, fixed = TRUE) &&
        grepl("R/mod_help.R",
              paste(readLines("deploy.sh", warn = FALSE), collapse = "\n"),
              fixed = TRUE) &&
        length(list.files("R", pattern = "^mod_help\\.R$")) == 1L)
  chk("★ mod_help_ui 真的定义得出来（上面那些渲染断言依赖它）",
      is.function(mod_help_ui) && is.function(NS))
}

# =============================================================================
section("V13.14 item 24：「还没有 Key和URL？」挪到厂商下面")
# 用户原话：「"还没有 Key？去 中转站大全 官网申请"这个条目应该直接显示在
# 厂商下面，换成"还没有 Key和URL？去 中转站大全 官网申请"」。
#
# 两件事，缺一件都不算做完：
#   (a) **文案**改成「还没有 Key和URL？」——多出来的「和URL」是有实义的：
#       中转站那几家发的不只是一把 Key，**接口地址也从它那儿拿**；
#   (b) **位置**挪到「厂商」正下方。只改文案的话，一个还没注册的人仍然要
#       往下走三步（接口地址 / Key / 获取模型）才看见这句话。
{
  mdl24 <- strip_comments(paste(readLines("R/mod_model.R", warn = FALSE),
                                collapse = "\n"))
  css24 <- paste(readLines("www/app.css", warn = FALSE), collapse = "\n")

  chk("★★★ 文案是「还没有 Key和URL？去 」（不是原来那句「还没有 Key？」）",
      grepl('" 还没有 Key和URL？去 "', mdl24, fixed = TRUE) &&
        !grepl("还没有 Key？", mdl24, fixed = TRUE))

  # 位置：用「厂商」和「接口地址」两个路标夹。key_help 必须落在它们之间。
  i_vendor <- regexpr('selectInput\\(ns\\("vendor"\\)', mdl24)
  i_help   <- regexpr('uiOutput\\(ns\\("key_help"\\)', mdl24)
  i_base   <- regexpr('textInput\\(ns\\("base_url"\\)', mdl24)
  i_verify <- regexpr('actionButton\\(ns\\("verify"\\)', mdl24)
  chk("★ 四个路标都找得到（找不到的话下面几条会静默通过）",
      i_vendor > 0 && i_help > 0 && i_base > 0 && i_verify > 0)
  chk("★★★ key_help 排在「厂商」**之后**、「接口地址」**之前**（即厂商正下方）",
      i_help > i_vendor && i_help < i_base)
  # ⚠️ 反向那一半：它**不能**再出现在「获取模型」下面。只查"在厂商后面"
  #    的话，把这一块**复制**一份到老位置也照样绿 —— 那正是"改了一半"。
  chk("★★★ 而且不再有第二处（老位置没有留一个副本）",
      length(gregexpr('uiOutput\\(ns\\("key_help"\\)', mdl24)[[1]]) == 1L)

  # ⚠️ 整块搬（申请链接 / key_note / 聚合平台说明 / 厂商 note），不是只搬
  #    那行链接：这几段说的都是"你选的这一家是什么情况"。只搬链接的话，
  #    同一件事的说明会散在两个地方，而第二处（现在孤零零挂在「获取模型」
  #    下面）讲的是别家的 note，读起来像在说这把 Key 有问题。
  chk("★★ 整块一起搬（key_note / 聚合平台说明 / 厂商 note 跟着走）",
      grepl('div(class = "dsapp-key-help",', mdl24, fixed = TRUE) &&
        grepl("dsapp_md_inline(v$key_note)", mdl24, fixed = TRUE) &&
        grepl("dsapp_vendor_is_aggregator(input$vendor)", mdl24, fixed = TRUE) &&
        grepl("dsapp_md_inline(v$note)", mdl24, fixed = TRUE))
  # ⚠️ 这个钩子是给 CSS 用的，而那段 CSS **是必需的**：selectInput 的
  #    .form-group 只有 margin-bottom、没有 margin-top，不补的话这块文字
  #    离上面 1rem、离下面 0，看起来像「接口地址」的说明而不是厂商的。
  chk("★★ .dsapp-key-help 那段上下边距还在（不补的话它看着像接口地址的说明）",
      grepl(".dsapp-key-help {", css24, fixed = TRUE) &&
        grepl("margin-top: -.5rem", css24, fixed = TRUE))

  # ⚠️ 链接那一半一个字都不能动：V13.1 item 1/3 定的规矩是"申请走 invite_url、
  #    控制台走 key_url"（"注册入口"和"控制台"是两个页面，智谱的邀请链接
  #    点进去是注册页）。搬位置时最容易顺手把 apply_url 那几行"简化"掉。
  chk("★★★ 申请 / 控制台那两条链接的规矩没在搬动里被简化掉",
      grepl("if (!nzchar(apply_url)) apply_url <- url", mdl24, fixed = TRUE) &&
        grepl("v$invite_url", mdl24, fixed = TRUE) &&
        grepl('"已有账号去控制台 "', mdl24, fixed = TRUE))
}

# =============================================================================
section("V13.15 item 25：「还没填 Key」的按钮跳到模型服务页（不是设置页）")
# 用户原话：「现在显示没有填 key 的时候，会跳到设置页面，而不是模型页面，
# 这个跳转更新一下」。
#
# 根因值得单独记：V13.12 item 19 把「模型服务」从设置页拆成左栏独立一页时，
# **这个弹窗里上面那三条说明都改成了「模型服务」，下面那颗按钮没改** ——
# 文案说"打开左栏的「模型服务」页"，按钮把人送到设置页，而设置页上根本
# 没有填 Key 的地方。只改文案、没顺着手指数落点，就是这么坏掉的。
{
  # ⚠️ 必须 strip_comments：本版在 mod_chat.R 里**故意写了**「去设置」
  #    和 `dsapp_goto("settings")` 这两串字（就在解释这个 bug 的注释里）。
  #    直接对原文断言"不许出现"，会被自己的注释打红。
  cht25 <- strip_comments(paste(readLines("R/mod_chat.R", warn = FALSE),
                                collapse = "\n"))
  app25 <- strip_comments(paste(readLines("app.R", warn = FALSE),
                                collapse = "\n"))
  allr25 <- strip_comments(paste(vapply(
    list.files("R", pattern = "\\.R$", full.names = TRUE),
    function(f) paste(readLines(f, warn = FALSE), collapse = "\n"), ""),
    collapse = "\n"))

  # ---- (a) 跳转目标 --------------------------------------------------------
  chk("★★★ 那颗按钮的 observer 现在跳的是 model",
      grepl('observeEvent(input$goto_model, {', cht25, fixed = TRUE) &&
        grepl('dsapp_goto("model")', cht25, fixed = TRUE))
  # ⚠️ 反向那一半才是这条反馈的正文。只查"有 dsapp_goto(\"model\")"的话，
  #    把新 observer 加在旁边、老的那个留着，照样绿 —— 而两个 observer
  #    都在时是"点了跳两次"，谁后到谁说了算。
  chk("★★★ 而且**不再**跳设置页了（老 observer 没有留一份）",
      !grepl('dsapp_goto("settings")', cht25, fixed = TRUE))

  # ---- (b) 标签 / id / 函数名，三处一致 -----------------------------------
  # ⚠️ 这一条是**文案和落点一致**的机器版：弹窗里说去哪一页，按钮就得把
  #    人送到哪一页。分开写的话两边会各自漂走 —— 这次漂的就是它们。
  chk("★★★ 按钮标签、input id、observer 三处是同一件事",
      grepl('actionButton(ns("goto_model"), "去模型服务"', cht25, fixed = TRUE) &&
        grepl('observeEvent(input$goto_model,', cht25, fixed = TRUE) &&
        !grepl("goto_settings", cht25, fixed = TRUE))
  chk("★★ 函数名也跟着改了（dsapp_prompt_settings → dsapp_prompt_model）",
      grepl("dsapp_prompt_model <- function(", cht25, fixed = TRUE) &&
        grepl("dsapp_prompt_model()", cht25, fixed = TRUE) &&
        !grepl("dsapp_prompt_settings", allr25, fixed = TRUE))
  # ⚠️ 弹窗正文里那句"打开左栏的「模型服务」页"必须还在 —— 它和按钮现在
  #    指的是同一页，两边一起看才对得上。
  chk("★★ 弹窗正文说的也是「模型服务」（和按钮同一页）",
      grepl('tags$b("「模型服务」")', cht25, fixed = TRUE))

  # ---- (c) value 真的存在（对不上就是"点了没反应"）-------------------------
  # ⚠️ 跳转认的是 nav_panel 的 **value**，不是标题。写成 "模型服务" 的话
  #    bslib 找不到那一页，**不报错、不跳转**，用户只看到弹窗关掉了。
  chk("★★★ 跳的 value 在 app.R 里真的有对应的 nav_panel",
      grepl('nav_panel("模型服务", value = "model"', app25, fixed = TRUE))

  # ---- (d) ★ 同类落点：全仓库还有没有把人往设置页指的 --------------------
  # 这一条是这次真正的收获 —— 用户报的是**一处**，顺着手指数出**四处**。
  # 判据：Key / 模型 / 单次回复上限这三样 V13.12 起全在「模型服务」页，
  # 所以任何一句话**指路到设置页**同时又在说这三样之一，就是错的。
  #
  # ⚠️ "指路"这个条件是必须的，光看"设置"+关键词会误伤 —— 第一版就是这么
  #    写的，报出来两条假问题：
  #      · `dsapp_err_user(r, "保存这套模型设置", …)` —— "模型设置"是个名词
  #      · `showNotification("设置已保存。还没填 API Key …")` —— "设置已保存"
  #    两句里一个"设置页"都没提，用户照着做也不会走错路。判据松一格，
  #    假问题就会盖住真问题（而这一条的作用恰恰是找真问题）。
  #    真正指路的写法只有三种：「设置」/ 设置页 / 设置 →。
  bad25 <- character(0)
  for (f in list.files("R", pattern = "\\.R$", full.names = TRUE)) {
    txt <- strip_comments(paste(readLines(f, warn = FALSE), collapse = "\n"))
    for (ln in strsplit(txt, "\n", fixed = TRUE)[[1]]) {
      pointer <- grepl("「设置」", ln, fixed = TRUE) ||
        grepl("设置页", ln, fixed = TRUE) ||
        grepl("设置 →", ln, fixed = TRUE)
      if (!pointer) next
      # 远程服务器 / 硬件选择 / AI 怎么干活 确实还在设置页，那些是对的
      if (grepl("远程", ln, fixed = TRUE) ||
          grepl("硬件选择", ln, fixed = TRUE) ||
          grepl("怎么干活", ln, fixed = TRUE)) next
      if (grepl("API Key", ln, fixed = TRUE) ||
          grepl("单次回复上限", ln, fixed = TRUE) ||
          grepl("模型", ln, fixed = TRUE)) {
        bad25 <- c(bad25, sprintf("%s: %s", f, trimws(ln)))
      }
    }
  }
  chk("★★★ 没有别的地方还把 Key / 模型 / 单次回复上限指向「设置」页了",
      length(bad25) == 0L,
      paste(utils::head(bad25, 4), collapse = " | "))

  # ⚠️ 反向的反向：上面那条不能靠**把所有「设置」字样删光**来变绿。
  #    远程服务器 / 硬件选择 / AI 怎么干活 这三样 V13.12 起确实还在设置页，
  #    把它们一起"改"成模型服务就是用力过猛 —— 那种改法会让上面那条变绿，
  #    却把三条**本来是对的**说明改错。所以这里逐句钉住原话。
  chk("★★ 而真正还在设置页的那三样没有被误改（远程 / 硬件选择 / AI 怎么干活）",
      grepl("去「设置」页填 IP / 账号并测试连接", allr25, fixed = TRUE) &&
        grepl("请到「设置 → 硬件选择」重新选一个", allr25, fixed = TRUE) &&
        grepl("「设置 → 执行 → AI 怎么干活」", allr25, fixed = TRUE))
}

# =============================================================================
section("V13.15 item 26：「确认 / 更新」按钮头尾各一颗，宽度同「获取模型」")
# 用户原话：「更新按钮请在头部和尾部各设置一个，和获取模型按钮一样设置的
# 宽一些，防止用户看不到」。
#
# 三件事，缺一件都不算做完：
#   (a) 头部**新增**一颗（底部那颗 V13.11 item 8 留着，不许挪回去）；
#   (b) 两颗**一样宽**，而且和「获取模型」同宽（它是这一页的主按钮）；
#   (c) 两颗做的是**同一件事** —— 共用一个处理函数、共用一套标签和提示。
#       (c) 是最容易漏的：抄两遍也不报错，表现只是"点哪颗结果不太一样"。
{
  mdl26 <- strip_comments(paste(readLines("R/mod_model.R", warn = FALSE),
                                collapse = "\n"))

  # ---- (a) 两颗都在，而且都出自同一个 commit_btn() ------------------------
  chk("★★★ 头尾各一颗，且两颗都是 commit_btn() 画出来的（不是抄一份 markup）",
      grepl('commit_btn("commit_top", "commit_hint_top")', mdl26, fixed = TRUE) &&
        grepl('commit_btn("commit", "commit_hint")', mdl26, fixed = TRUE))
  # ⚠️ 这一条防的是"两颗按钮各写一份 markup"：那样也能长得一样，但改一处
  #    样式另一处不跟着变。判据是 markup 只有一份（commit_btn 里那处
  #    `actionButton(ns(id), …)`，id 是**参数**），而不是出现两次字面量。
  chk("★★ 按钮 markup 只有一份（commit_btn 里那处，id 是参数）",
      !grepl('actionButton(ns("commit', mdl26, fixed = TRUE) &&
        length(gregexpr('actionButton\\(ns\\(id\\)', mdl26)[[1]]) == 1L)

  # ---- (b) 位置：头部那颗在「厂商」之前，底部那颗在「生成参数」之后 -------
  i_top    <- regexpr('commit_btn\\("commit_top"', mdl26)
  i_vendor <- regexpr('selectInput\\(ns\\("vendor"\\)', mdl26)
  i_btm    <- regexpr('commit_btn\\("commit",', mdl26)
  i_params <- regexpr('dsapp-model-params|生成参数', mdl26)
  chk("★ 三个路标都找得到（找不到的话下面两条会静默通过）",
      i_top > 0 && i_vendor > 0 && i_btm > 0 && i_params > 0)
  chk("★★★ 头部那一颗在「厂商」**之前**（进来不用滚动就看得见）",
      i_top < i_vendor)
  # ⚠️ 这一条是**防回退**：V13.11 item 8 用户明确要求"更新按钮可以在最底部"，
  #    item 26 只是在头部又加了一颗，不是把它挪回去。挪回去的话那条要求
  #    就又被违反了，而界面上看起来"按钮还在啊"。
  chk("★★★ 底部那一颗仍然在「生成参数」**之后**（V13.11 item 8 的结论没被推翻）",
      i_btm > i_params)

  # ---- (b2) 宽度：和「获取模型」用同一组 class ---------------------------
  # ⚠️ 从「获取模型」那一行里**取**它的 class，再要求按钮那段里有同一组，
  #    不是把 "btn-sm w-100" 写死在断言里 —— 写死的话，哪天「获取模型」
  #    改成别的宽度，这一条会继续绿，而两颗按钮已经和它不一样宽了。
  verify_cls <- regmatches(
    mdl26, regexpr('actionButton\\(ns\\("verify"\\),[^)]*class = "[^"]*"',
                   mdl26))
  chk("★★★ 按钮的 class 和「获取模型」逐字一致（同宽）",
      length(verify_cls) == 1L &&
        grepl('class = "btn-outline-primary btn-sm w-100"', verify_cls,
              fixed = TRUE) &&
        grepl('class = "btn-primary btn-sm w-100"', mdl26, fixed = TRUE),
      verify_cls)

  # ---- (c) 两颗是同一件事 ------------------------------------------------
  # ⚠️ 这是本条的**承重墙**。抄两遍处理函数也能让上面全绿，而后果是：
  #    改了一颗忘了另一颗，用户点哪颗都"看起来生效了"，报都报不清楚。
  chk("★★★ 处理函数只有一份（do_commit），两条 observer 接同一份",
      length(gregexpr("do_commit <- function\\(", mdl26)[[1]]) == 1L &&
        grepl("observeEvent(input$commit,     do_commit())", mdl26,
              fixed = TRUE) &&
        grepl("observeEvent(input$commit_top, do_commit())", mdl26,
              fixed = TRUE))
  chk("★★★ 标签是**两颗一起**刷的（只刷一颗会并排出现「确认」和「更新」）",
      grepl('COMMIT_BTNS <- c("commit", "commit_top")', mdl26, fixed = TRUE) &&
        grepl("for (b in COMMIT_BTNS) updateActionButton(session, b, label = lab)",
              mdl26, fixed = TRUE))
  chk("★★ 提示行两个 output 都挂了（不然从头部按下去的人不知道成没成）",
      grepl("output$commit_hint     <- renderUI(commit_hint_ui())", mdl26,
            fixed = TRUE) &&
        grepl("output$commit_hint_top <- renderUI(commit_hint_ui())", mdl26,
              fixed = TRUE))

  # ---- (d) 底部那颗的 id 没被改名 ---------------------------------------
  # ⚠️ `#model-commit` 有外部引用（tests/ui_v1312 的 probe_dirty /
  #    probe_quiet / probe_model 直接点它）。为了"看着对称"改成
  #    commit_bottom 的话，那三个探针会**静默点空**，报出来的是超时。
  chk("★★ 底部那颗仍然是 id `commit`（改了会让几个探针静默点空）",
      grepl('commit_btn("commit", "commit_hint")', mdl26, fixed = TRUE) &&
        !grepl("commit_bottom", mdl26, fixed = TRUE))
}

# =============================================================================
section("Test_V15.2：邮件通道 + 文献速递定时订阅")
# =============================================================================
#
# 用户原话：
#   「1、企业微信邮箱是 biomamba@biomamba.com.cn …… 请帮我把文献速递的内容
#     以邮件的形式发送给用户
#    2、言出法随界面开启一个让用户勾选邮件提醒的功能，开启后能把任务运行
#     成功完成/失败的信息发送到用户的邮箱
#    3、以上功能做好后，发送给 wchcpu2019@163.com 邮箱做测试」
#    「只手动发，给用户一个界面或者按钮，可以按照关键词设置定时发送任务」
#
# ⚠️⚠️ 这一节里**绝对不许**真的发信，也不许出现那个客户端专用密码。
#    selftest 的铁律是从不联网（它是 deploy --check 的一部分，会在用户的
#    部署机上跑）。真发信那条路在 tests/real_mail.R，凭据只从环境变量读。
#    所以下面全是**纯函数**和**源码哨兵**，没有一次 send_mail。
{
  v152_mail <- paste(readLines("R/mail.R", warn = FALSE), collapse = "\n")
  v152_lit  <- paste(readLines("R/litsub.R", warn = FALSE), collapse = "\n")
  v152_mlit <- drop_comment_lines(readLines("R/mod_lit.R", warn = FALSE))
  v152_mlit <- paste(v152_mlit, collapse = "\n")

  # ---- (a) MIME 组装：整条路里唯一能离线验的部分 ------------------------
  # 这是 D2 的全部理由 —— 把报文拼装做成纯函数，字节级正确性才测得到；
  # 发信那一步薄到只剩一次 send_mail。
  chk("★★ 中文主题走 RFC 2047 编码（不然收件人看到乱码）", {
    m <- dsapp_mime_build(to = "a@b.com", subject = "文献速递",
                          text = "hi", from = "c@d.com")
    grepl("=?UTF-8?B?", m, fixed = TRUE) &&
      !grepl("Subject: 文献速递", m, fixed = TRUE)
  })
  chk("★ ASCII 主题不编码（编了也能收，但没必要，而且不好搜）", {
    m <- dsapp_mime_build(to = "a@b.com", subject = "Digest",
                          text = "hi", from = "c@d.com")
    grepl("Subject: Digest", m, fixed = TRUE)
  })
  chk("★★ 全程 CRLF，没有裸 LF（裸 LF 会被某些服务器当成行尾截断）", {
    m <- dsapp_mime_build(to = "a@b.com", subject = "x", text = "hi",
                          from = "c@d.com")
    !grepl("(?<!\r)\n", m, perl = TRUE)
  })
  chk("★★ 有附件时是 multipart/mixed 且 boundary 首尾配对", {
    f <- file.path(tmp, "att.txt")
    writeLines("hello", f)
    m <- dsapp_mime_build(to = "a@b.com", subject = "x", text = "hi",
                          from = "c@d.com",
                          attach = list(list(path = f, name = "att.txt")))
    b <- sub('.*boundary="([^"]+)".*', "\\1", m)
    nzchar(b) && b != m &&
      grepl("multipart/mixed", m, fixed = TRUE) &&
      # 结尾那一行必须是 --boundary--
      grepl(paste0("--", b, "--"), m, fixed = TRUE) &&
      # 出现次数：头一次 + 每段开头一次 + 结尾一次
      length(gregexpr(paste0("--", b), m, fixed = TRUE)[[1]]) >= 3L
  })
  chk("★ 附件 base64 每行不超过 76 列（RFC 2045 的硬要求）", {
    f <- file.path(tmp, "big.bin")
    writeBin(as.raw(rep(1:200, 20)), f)
    m <- dsapp_mime_build(to = "a@b.com", subject = "x", text = "hi",
                          from = "c@d.com",
                          attach = list(list(path = f, name = "big.bin")))
    # 只看 base64 那一段：Content-Transfer-Encoding: base64 之后到下一个
    # boundary 之前
    body <- sub("(?s).*Content-Transfer-Encoding: base64\r\n\r\n", "", m,
                perl = TRUE)
    body <- sub("(?s)\r\n--.*$", "", body, perl = TRUE)
    lines <- strsplit(body, "\r\n", fixed = TRUE)[[1]]
    all(nchar(lines) <= 76L)
  })
  chk("★★ 没有附件时省掉 mixed 那一层（少一层就少一处能拼错的地方）", {
    m <- dsapp_mime_build(to = "a@b.com", subject = "x", text = "hi",
                          from = "c@d.com")
    !grepl("multipart/mixed", m, fixed = TRUE)
  })

  # ---- (b) 配没配齐 —— 这是唯一的开关（D4）------------------------------
  chk("★★ 四个关键项缺一个就不算配好", {
    base <- list(host = "h", user = "u", pass = "p", from = "f")
    all(vapply(c("host", "user", "pass", "from"), function(k) {
      b <- base; b[[k]] <- ""
      !isTRUE(dsapp_mail_ready(list(mail = b)))
    }, logical(1))) &&
      isTRUE(dsapp_mail_ready(list(mail = base)))
  })
  chk("★ 全空时是 FALSE（没配的部署上界面整个不出现）",
      !isTRUE(dsapp_mail_ready(list(mail = list(host = "", user = "",
                                                pass = "", from = "")))))

  # ---- (c) next_at 纯函数：边界最多的一块 -------------------------------
  tz <- "Asia/Shanghai"
  chk("★★ from 恰好等于目标时刻时必须取**严格大于**（否则那一分钟反复触发）", {
    # 2026-09-28 是周一，08:00 正好是目标
    n <- dsapp_lit_next_at("daily", 1L, 1L, 8L, 0L,
                           from = "2026-09-28 08:00:00", tz = tz)
    !is.na(n) && n > "2026-09-28 08:00:00"
  })
  chk("★ 每天：推到的还是 08:00，只是换了一天", {
    n <- dsapp_lit_next_at("daily", 1L, 1L, 8L, 0L,
                           from = "2026-09-28 09:00:00", tz = tz)
    identical(n, "2026-09-29 08:00:00")
  })
  chk("★ 每周：推到下一个周一", {
    n <- dsapp_lit_next_at("weekly", 1L, 1L, 8L, 0L,
                           from = "2026-09-28 09:00:00", tz = tz)
    identical(n, "2026-10-05 08:00:00")
  })
  chk("★★ 每月 31 号在小月顺延到当月最后一天（2 月尤其）", {
    n <- dsapp_lit_next_at("monthly", 1L, 31L, 8L, 0L,
                           from = "2026-01-31 09:00:00", tz = tz)
    # 2026 年 2 月只有 28 天
    identical(n, "2026-02-28 08:00:00")
  })
  chk("★ 跨年：12 月之后是次年 1 月", {
    n <- dsapp_lit_next_at("monthly", 1L, 5L, 8L, 0L,
                           from = "2026-12-10 00:00:00", tz = tz)
    identical(n, "2027-01-05 08:00:00")
  })
  chk("★ next_at 一律是本地时间串（界面上写的就是它）", {
    n <- dsapp_lit_next_at("daily", 1L, 1L, 8L, 0L,
                           from = "2026-09-28 09:00:00", tz = tz)
    grepl("^\\d{4}-\\d{2}-\\d{2} \\d{2}:\\d{2}:\\d{2}$", n) &&
      substr(n, 12, 16) == "08:00"
  })

  # ---- (d) 队列去重：ref 唯一索引真的挡得住第二次 ----------------------
  chk("★★ ref 去重靠唯一索引，重复入队不会发两封", {
    # ⚠️⚠️ **现取一份 cfg，不能用自检开头那个全局 `cfg`。**
    #    两者不一定指同一个库：全局 cfg 是开头 DSAPP_DATA_ROOT=tmp 那一刻建的，
    #    而自检中途有整节会改这个环境变量（V15 论坛那一节 —— 它原本想用
    #    on.exit 还原，而那个 on.exit 在顶层块里根本不执行，见那边的说明）。
    #    混用两个来源的后果不是报错，是**同时打开两个库**：
    #    dsapp_db(cfg) 连 A，dsapp_user_create() 内部现取 dsapp_config() 连 B，
    #    账号建在 B、查在 A，`u` 是 NULL，`as.integer(u$id)` 变成 integer(0)，
    #    最后红的是"ref 去重没生效"，跟真正的原因隔了十万八千里
    #    （2026-09-28 实测，查了半天）。
    #
    #    规矩：**凡是和"内部现取 config"的函数（dsapp_user_create 等）打交道
    #    的断言块，自己也得现取。** 这一条比"记得还原环境变量"可靠 ——
    #    它不依赖别的节守规矩。
    v152_cfg <- dsapp_config()
    con2 <- dsapp_db(v152_cfg)
    # ⚠️ 邮箱先算好存成变量。上一版在三处各调了一次 Sys.time() ——
    #    跨过一秒就会「建的地址」和「查的地址」不是同一个，得到 NULL，
    #    然后在 as.integer(NULL$id) 上以一句看不出所以然的话炸掉。
    v152_em <- sprintf("v152selftest%d@x.invalid", as.integer(Sys.time()))
    u <- dsapp_user_by_email(v152_em, con = con2)
    if (is.null(u)) {
      dsapp_user_create("自检账号", v152_em,
                        sprintf("139%08d", as.integer(Sys.time()) %% 1e8),
                        "测试", password = "test-only-1234")
      u <- dsapp_user_by_email(v152_em, con = con2)
    }
    ref <- sprintf("selftest:%d", as.integer(Sys.time()))
    a <- dsapp_mail_enqueue(to = "a@b.invalid", subject = "s1", body_md = "x",
                            kind = "task", ref = ref,
                            user_id = as.integer(u$id), cfg = v152_cfg)
    b <- dsapp_mail_enqueue(to = "a@b.invalid", subject = "s2", body_md = "y",
                            kind = "task", ref = ref,
                            user_id = as.integer(u$id), cfg = v152_cfg)
    n <- DBI::dbGetQuery(con2, "SELECT COUNT(*) AS n FROM mail_queue
                                 WHERE ref = ?", params = list(ref))$n
    isTRUE(as.integer(n) == 1L) && !identical(a, b)
  })
  chk("★ ref 留空时不去重（测试信可以反复发）", {
    r1 <- dsapp_mail_enqueue(to = "a@b.invalid", subject = "t", body_md = "x",
                             kind = "test", ref = "", cfg = cfg)
    r2 <- dsapp_mail_enqueue(to = "a@b.invalid", subject = "t", body_md = "x",
                             kind = "test", ref = "", cfg = cfg)
    !is.na(r1) && !is.na(r2) && !identical(r1, r2)
  })

  # ---- (e) 源码哨兵 -----------------------------------------------------
  chk("★★ 收尾钩子里的发信整段包在 tryCatch 里（抛错不能把收尾链带崩）", {
    tr <- paste(readLines("R/taskrun.R", warn = FALSE), collapse = "\n")
    # 那个函数里出现了 dsapp_mail_enqueue 就必须同时有 tryCatch
    grepl("dsapp_mail_enqueue", tr, fixed = TRUE) &&
      grepl("tryCatch", tr, fixed = TRUE)
  })
  chk("★★ R/mail.R 里没有同步发信的函数名（发信只能在子进程里）",
      !grepl("dsapp_mail_send_raw", v152_mail, fixed = TRUE) ||
        grepl("dsapp_mail_drain", v152_mail, fixed = TRUE))
  chk("★★ 密码不进日志 / 通知 / 异常消息", {
    # ⚠️ 先剥注释：那个变量名在解释它的注释里出现过（这个坑踩过三次）
    srcs <- c("R/mail.R", "R/litsub.R", "R/config.R", "run_scheduler.R",
              "R/mod_lit.R", "R/mod_settings.R", "R/mod_chat.R",
              "R/taskrun.R")
    bad <- character(0)
    for (f in srcs) {
      if (!file.exists(f)) next
      txt <- paste(drop_comment_lines(readLines(f, warn = FALSE)),
                   collapse = "\n")
      # 允许出现的只有：读环境变量、拼进 smtp 选项、判空。
      # 任何 message/stop/showNotification/cat 里出现 mail$pass 都不行。
      hits <- regmatches(txt, gregexpr(
        "(message|stop|warning|showNotification|cat)\\([^)]*\\$pass",
        txt))[[1]]
      if (length(hits)) bad <- c(bad, paste0(f, ": ", hits[1]))
    }
    length(bad) == 0L
  })
  chk("★★ 日志里不打印整个 cfg$mail（排空进程的日志也不打）", {
    bad <- FALSE
    for (f in c("R/mail.R", "run_scheduler.R")) {
      if (!file.exists(f)) next
      txt <- paste(drop_comment_lines(readLines(f, warn = FALSE)),
                   collapse = "\n")
      if (grepl("cat\\([^)]*\\$mail", txt) ||
          grepl("message\\([^)]*\\$mail", txt)) bad <- TRUE
    }
    !bad
  })

  # ---- (f) 四份依赖清单必须互相一致，且都含 curl -----------------------
  # ⚠️ 这四份**从来没有交叉断言**过。漏一份的症状是"Windows 包能跑、
  #    但一发信就起不来"，而且只在那一台机器上出现。
  chk("★★★ 四份依赖清单都含 curl（少一份就是某个平台上发信起不来）", {
    dep <- readLines("deploy.sh", warn = FALSE)
    rl  <- readLines("run_local.R", warn = FALSE)
    wp  <- readLines("desktop/fetch_win_pkgs.R", warn = FALSE)
    wb  <- readLines("desktop/build_windows_bundle.sh", warn = FALSE)
    has <- function(lines, pkg) any(grepl(pkg, lines, fixed = TRUE))
    all(vapply(list(dep, rl, wp, wb), has, logical(1), pkg = "curl"))
  })
  chk("★★ 两种 Linux 清单里都有 openssl（R/crypto.R 用了它却一直不在清单里）", {
    has <- function(f, pkg) any(grepl(pkg, readLines(f, warn = FALSE),
                                      fixed = TRUE))
    has("deploy.sh", "openssl") && has("run_local.R", "openssl")
  })

  # ---- (g) 调度器单元名不能撞上 V1 那三个遗留单元 ----------------------
  # ⚠️ 这一条第一版写成「全文里不许出现 dsapp-web.service」—— 假红。
  #    那个名字**本来就该出现**：deploy_link.sh 第 2 段要 disable 掉 V1
  #    （Shiny for Python 时代）留下的那三个单元。真正要守的是**撞名**：
  #    新单元如果叫成了清理名单里的名字，部署脚本会把它刚装好的东西
  #    自己停掉，而且顺序上先装后停，报出来是"装好了但没在跑"。
  chk("★★★ 新单元名不在 V1 那个清理名单里（撞名就被自己的部署脚本停掉）", {
    sh <- paste(readLines("deploy_link.sh", warn = FALSE), collapse = "\n")
    m <- regmatches(sh, regexpr("for u in [^;]+;", sh))
    ok_name <- length(m) == 1L && !grepl("dsapp-lit", m, fixed = TRUE)
    ok_name &&
      grepl("LIT_UNIT=/etc/systemd/system/dsapp-lit.service", sh,
            fixed = TRUE) &&
      grepl("LIT_TIMER=/etc/systemd/system/dsapp-lit.timer", sh,
            fixed = TRUE)
  })
  chk("★★ 定时器带 WorkingDirectory（子进程靠 cwd 读 .Renviron）", {
    sh <- paste(readLines("deploy_link.sh", warn = FALSE), collapse = "\n")
    grepl("WorkingDirectory=", sh, fixed = TRUE)
  })
  chk("★★ 定时器是 oneshot + Persistent（不是常驻进程）", {
    sh <- paste(readLines("deploy_link.sh", warn = FALSE), collapse = "\n")
    grepl("Type=oneshot", sh, fixed = TRUE) &&
      grepl("Persistent=true", sh, fixed = TRUE)
  })

  # ---- (h) 文献速递页那两张卡的几条硬规矩 ------------------------------
  chk("★★ 扫速递清单没有挂定时器（那是遍历磁盘的重活）",
      !grepl("invalidateLater", v152_mlit, fixed = TRUE))
  chk("★★ 送信前核对路径在这个账号的清单里", {
    i <- regexpr("p %in% d$path", v152_mlit, fixed = TRUE)[1]
    j <- regexpr("dsapp_lit_mail_queue(", v152_mlit, fixed = TRUE)[1]
    i > 0 && j > 0 && i < j
  })
  chk("★★ 手册里那张表只画一个「选中」控件（每行一个 = 后面的行点不动）", {
    n <- length(gregexpr('selectInput(ns("sub_pick")', v152_mlit,
                         fixed = TRUE)[[1]])
    n == 1L
  })
}

# =============================================================================
section("Test_V15.5：提示词汇编 + 速递页三颗按钮 / 学术前沿子页面")
# =============================================================================
#
# 用户原话：
#   「1、规则8是稳健性而不是健壮性吧
#    2、我新加了一版提示词在：…/skills_builtin/note/，汇编合并原来的提示词
#      和已有的生成一份更规范、更准确、简洁的，并应用于新版本中
#    3、"定时订阅"中的加粗语法没有被正常渲染
#    4、定时订阅按钮可以直接显示在开始检索按钮旁边，点击后显示设置页面，
#      提供选项直接加载文献速递页面的配置。"看看会发生什么"换成"关联技能"即可
#    5、在文献速递里加"学术前沿订阅"子页面」
#
# ⚠️ 提示词内容那几条（item 1 / 2）在**上面**跟着 DSPROMPT_* 一起断言，
#    不重复。这里管的是后三条。
# ⚠️ 几何/交互（按钮点下去卡片到底展没展开、flash 有没有滚到东西、加粗
#    到底是不是 <strong>）只有浏览器量得准，那一半在 tests/ui_v155/。
{
  v155_lit <- paste(drop_comment_lines(readLines("R/litsub.R", warn = FALSE)),
                    collapse = "\n")
  v155_ml  <- paste(drop_comment_lines(readLines("R/mod_lit.R", warn = FALSE)),
                    collapse = "\n")
  v155_ui  <- paste(drop_comment_lines(readLines("R/mod_lit.R", warn = FALSE)),
                    collapse = "\n")

  # ---- (a) item 3：界面上的粗体必须是标签，不是星号 -----------------------
  #
  # ⚠️⚠️ 这条判据**必须剥注释**（v155_* 已经是剥过的）。不剥的话，
  #    "这里的 `p()` 是纯文本、星号会原样显示"这句解释本身就带着 `**`，
  #    断言会**因为注释而红** —— 这个仓库在"扫源码前先剥注释"上栽过三次。
  chk("★★★ item 3：mod_lit 的界面文案里不再出现 markdown 星号粗体", {
    # 只扫"会被渲染成纯文本"的那几种标签调用里的字符串。
    bad <- character(0)
    for (tag in c("p(", "tags$div(", "tags$span(", "helpText(",
                  "card_header(", "numericInput(", "textInput(",
                  "actionButton(", "checkboxInput(", "tags$b(")) {
      # 找到 `tag ... "…**…**…"` 这种：标签调用之后到下一个 `)` 之间
      hits <- regmatches(v155_ui, gregexpr(
        paste0("\\Q", tag, "\\E[^)]*\\*\\*[^)]*"), v155_ui))[[1]]
      if (length(hits)) bad <- c(bad, hits)
    }
    length(bad) == 0L
  })
  chk("★★ item 3：原来那处重点改成了 strong()", {
    # ⚠️ 定时订阅卡里原本有**两**处星号；V15.5 item 4 把第二处那段文案
    #    整段换掉了（"条件取的是上面…现在填的…" → 「这条订阅用什么条件」
    #    那个单选），所以现在只剩一处。断言跟着改，别去追一个已经不在的
    #    句子 —— 第一版就是照着老文案写的，红得毫无意义。
    grepl('strong("自己跑一遍新的检索")', v155_ml, fixed = TRUE)
  })
  # 同一类错在别的页也有（管理页的权限说明、论坛页的顶栏说明），一起盯住。
  chk("★★ item 3：别的页里那种「纯文本里写星号」也一并清了", {
    bad <- character(0)
    for (f in c("R/mod_htadmin.R", "R/mod_forum.R")) {
      if (!file.exists(f)) next
      txt <- paste(drop_comment_lines(readLines(f, warn = FALSE)),
                   collapse = "\n")
      hits <- regmatches(txt, gregexpr(
        "(helpText|tags\\$div|tags\\$p|p)\\([^)]*\\*\\*[^)]*", txt))[[1]]
      if (length(hits)) bad <- c(bad, paste0(f, ": ", hits[1]))
    }
    length(bad) == 0L
  })
  # 同步提示是**变量**送进 div() 的，上面的字面量扫描看不见它 ——
  # 单独盯一句：它必须过 dsapp_md_inline()。
  chk("★★ item 3：同步回执里的 msg 过了 dsapp_md_inline（它是变量，扫不到）", {
    s <- paste(drop_comment_lines(readLines("R/mod_settings.R", warn = FALSE)),
               collapse = "\n")
    grepl("dsapp_md_inline(v$msg", s, fixed = TRUE)
  })

  # ---- (b) item 4：三颗按钮 + 关联技能那颗不复制清单 ----------------------
  chk("★★★ item 4：提交卡上是「开始检索 / 关联技能 / 定时订阅」三颗", {
    grepl('actionButton(ns("go"), "开始检索"', v155_ui, fixed = TRUE) &&
      grepl('actionButton(ns("skills_btn"), "关联技能"', v155_ui, fixed = TRUE) &&
      grepl('actionButton(ns("sub_btn"), "定时订阅"', v155_ui, fixed = TRUE)
  })
  chk("★★★ item 4：旧那颗「看看会发什么」和它的预览整条路都删干净了", {
    # ⚠️ 只删按钮不删 output 的话，peek_box 那个 renderUI 还挂在那儿，
    #    永远没人能把 peek 置 TRUE —— 死代码，但下次改的人会以为它还在用。
    !grepl('"看看会发什么"', v155_ui, fixed = TRUE) &&
      !grepl('ns("peek")', v155_ui, fixed = TRUE) &&
      !grepl("peek <- reactiveVal", v155_ml, fixed = TRUE) &&
      !grepl("output$peek_box", v155_ml, fixed = TRUE)
  })
  chk("★★ item 4：「关联技能」是滚到清单那张卡，**不是**再长一份清单", {
    # 判据是"flash 的选择器 == 那张卡的类名"，两边任改一处都会红。
    grepl('list(sel = ".dsapp-lit-skills-card")', v155_ml, fixed = TRUE) &&
      grepl('div(class = "dsapp-lit-skills-card"', v155_ui, fixed = TRUE) &&
      # 而且这张卡里的清单仍然只有一份（skill_sums 只出现一次）
      length(gregexpr('uiOutput(ns("skill_sums"))', v155_ui,
                      fixed = TRUE)[[1]]) == 1L
  })
  chk("★★★ item 4：定时订阅卡默认收着，由按钮打开", {
    grepl("sub_open <- reactiveVal(FALSE)", v155_ml, fixed = TRUE) &&
      grepl("if (!isTRUE(sub_open())) return(NULL)", v155_ml, fixed = TRUE)
  })
  chk("★★★ item 4：flash 找的是**只在展开时存在**的那个类名", {
    # ⚠️ 选常驻外壳（.dsapp-lit-subwrap）的话，dsapp:flash 会立刻滚到一个
    #    还是空的盒子上，卡片随后才渲染 —— 表现是"点了按钮，滚了，没有东西"。
    grepl('list(sel = ".dsapp-lit-subopen")', v155_ml, fixed = TRUE) &&
      grepl('div(class = "dsapp-lit-subopen"', v155_ml, fixed = TRUE) &&
      # 而这个类名**只**出现在展开分支里（在 sub_open 守卫之后）
      {
        i <- regexpr("if (!isTRUE(sub_open())) return(NULL)", v155_ml,
                     fixed = TRUE)[1]
        j <- regexpr('div(class = "dsapp-lit-subopen"', v155_ml,
                     fixed = TRUE)[1]
        i > 0 && j > i
      }
  })
  chk("★★ item 4：按钮上的字跟着开合走（不然没法知道再点一下会收起来）", {
    grepl('if (isTRUE(sub_open())) "收起订阅设置"', v155_ml, fixed = TRUE)
  })

  # ---- (c) item 4：订阅自己的条件 + 「加载文献速递页面的配置」-------------
  chk("★★★ item 4：订阅有「跟随上面 / 单独填一套」两条路，默认仍是跟随", {
    grepl('choices = c("跟随上面「检索条件」" = "page"', v155_ml,
          fixed = TRUE) &&
      grepl('"单独填一套" = "own"', v155_ml, fixed = TRUE)
  })
  chk("★★★ item 4：保存时**按选的那条路**取条件，不混着读", {
    # 判据：own 分支里读的是 sub_* 那一组，page 分支里读的是页面那一组。
    # 混读的典型错法是"关键词取了订阅的、篇数取了页面的" —— 存进去之后
    # 表格里只显示关键词，这种错要等下次跑到点才暴露。
    i <- regexpr('own <- identical(sub_src_now(), "own")', v155_ml,
                 fixed = TRUE)[1]
    j <- regexpr("dsapp_litsub_add(", v155_ml, fixed = TRUE)[1]
    ok_pos <- i > 0 && j > i
    seg <- if (ok_pos) substr(v155_ml, i, j) else ""
    ok_pos &&
      grepl("dsapp_lit_keywords(input$sub_kw)", seg, fixed = TRUE) &&
      grepl("input$sub_n_read", seg, fixed = TRUE) &&
      grepl("input$n_read", seg, fixed = TRUE)
  })
  chk("★★ item 4：「会存下」那句在两条路下都读对来源（回执不能说假话）", {
    i <- regexpr("output$sub_new_summary", v155_ml, fixed = TRUE)[1]
    j <- regexpr("act_on_sub <- function", v155_ml, fixed = TRUE)[1]
    i > 0 && j > i &&
      grepl("dsapp_lit_keywords(input$sub_kw)",
            substr(v155_ml, i, j), fixed = TRUE)
  })
  chk("★★★ item 4：「加载文献速递页面的配置」那颗按钮真的把五样都抄过来", {
    # ⚠️ 少抄一样（最常漏的是年份）的表现是"点了加载，年份还是空的"，
    #    而页面上没有任何提示 —— 用户会以为自己页面上就没填年份。
    s <- v155_ml
    i <- regexpr("load_page_cfg <- function()", s, fixed = TRUE)[1]
    j <- regexpr("observeEvent(input$sub_load", s, fixed = TRUE)[1]
    i > 0 && j > i && {
      seg <- substr(s, i, j)
      all(vapply(c('updateTextAreaInput(session, "sub_kw"',
                   'updateNumericInput(session, "sub_n_read"',
                   'updateNumericInput(session, "sub_n_skim"',
                   'updateNumericInput(session, "sub_yfrom"',
                   'updateNumericInput(session, "sub_yto"'),
                 function(p) grepl(p, seg, fixed = TRUE), logical(1)))
    }
  })
  chk("★★★ item 4：「单独填一套」那几个框的初值走 isolate（不 isolate = 打一半被清空）", {
    # ⚠️⚠️ 不 isolate 的话这个 renderUI 会依赖页面上那张表的输入，用户
    #    在下面填订阅条件时上面一动，整块被重建、刚敲的东西打回初值 ——
    #    这张卡上已经栽过一次同样的事（框和表格分成两个 output 那条注释）。
    i <- regexpr("output$sub_own_fields", v155_ml, fixed = TRUE)[1]
    j <- regexpr("output$sub_new_summary", v155_ml, fixed = TRUE)[1]
    i > 0 && j > i &&
      grepl("isolate(page_cfg())", substr(v155_ml, i, j), fixed = TRUE)
  })
  chk("★ item 4：收起时那个「✕」也接得上", {
    grepl("observeEvent(input$sub_close, sub_open(FALSE)",
          v155_ml, fixed = TRUE) &&
      grepl('actionButton(ns("sub_close")', v155_ml, fixed = TRUE)
  })

  # ---- (d) item 5：学术前沿子页面 ----------------------------------------
  chk("★★★ item 5：前沿预设每一组都有词、组内没有分隔符（带逗号会被劈成两个）", {
    p <- DSAPP_LIT_FRONTIER_PRESETS
    length(p) >= 4L &&
      all(nzchar(names(p))) &&
      all(vapply(p, function(v) length(v) >= 2L && all(nzchar(v)), logical(1))) &&
      all(!grepl("[,，;；、]", unlist(p, use.names = FALSE)))
  })
  chk("★★ item 5：预设词里不含中文（这几个库主要收英文文献）", {
    # 中文关键词会被模型翻一遍再用 —— 那是给"用户自己填"兜底的路径。
    # 预设没必要绕这一道，直接给英文更准。
    !any(grepl("[一-鿿]", unlist(DSAPP_LIT_FRONTIER_PRESETS,
                                         use.names = FALSE)))
  })
  chk("★★★ item 5：时间窗换算（0 = 不限 → NA，不能变成 0 年）", {
    y <- dsapp_lit_frontier_years
    d <- as.Date("2026-09-30")
    identical(y(1L, d), c(2026L, 2026L)) &&
      identical(y(3L, d), c(2024L, 2026L)) &&
      identical(y(0L, d), c(NA_integer_, NA_integer_)) &&
      # ⚠️ 脏输入（NULL / NA / 负数）一律当"不限"，绝不能算出个负数年份
      identical(y(NULL, d), c(NA_integer_, NA_integer_)) &&
      identical(y(-5L, d), c(NA_integer_, NA_integer_))
  })
  chk("★★ item 5：两个子页面是 radioButtons（选中态由 Shiny 管，不靠 JS 切 class）", {
    grepl('radioButtons(ns("mode")', v155_ui, fixed = TRUE) &&
      grepl('"学术前沿订阅" = "frontier"', v155_ui, fixed = TRUE) &&
      grepl('"关键词检索" = "kw"', v155_ui, fixed = TRUE)
  })
  chk("★★★ item 5：前沿面板只把预设**填进共用输入**，没有另开一套表单", {
    # ⚠️ 判据是"三样都 update 到了**页面那几个 id** 上"：kw / year_from /
    #    year_to / skills。少一样，前沿模式就只填了一半条件，而页面上
    #    看不出来（填进去的那半看起来很正常）。
    s <- v155_ml
    i <- regexpr("apply_frontier <- function()", s, fixed = TRUE)[1]
    j <- regexpr("observeEvent(input$fr_dirs", s, fixed = TRUE)[1]
    i > 0 && j > i && {
      seg <- substr(s, i, j)
      all(vapply(c('updateTextAreaInput(session, "kw"',
                   'updateNumericInput(session, "year_from"',
                   'updateNumericInput(session, "year_to"',
                   'updateCheckboxGroupInput(session, "skills"'),
                 function(p) grepl(p, seg, fixed = TRUE), logical(1)))
    }
  })
  chk("★★★ item 5：切到前沿模式时**自动**填一遍（不然面板是摆设）", {
    # 面板一渲染，浏览器就把 selected 那一项报上来 —— 那是真实的 input
    # 变化，正好触发 apply_frontier。两条 observeEvent 缺一条，对应的
    # 那半（勾方向 / 换时间窗）就会"改了没反应"。
    grepl("observeEvent(input$fr_dirs, apply_frontier(), ignoreInit = TRUE)",
          v155_ml, fixed = TRUE) &&
      grepl("observeEvent(input$fr_window, apply_frontier(), ignoreInit = TRUE)",
            v155_ml, fixed = TRUE)
  })
  chk("★★ item 5：「不限年份」时 year_from 送的是 \"\"，不是 NA", {
    # NA 会被渲染成 value="NA"，<input type="number"> 解析不了，控制台
    # 每渲染一次报一句 —— 和上面 year_from 那个输入框同一个坑。
    i <- regexpr("apply_frontier <- function()", v155_ml, fixed = TRUE)[1]
    j <- regexpr("observeEvent(input$fr_dirs", v155_ml, fixed = TRUE)[1]
    i > 0 && j > i &&
      grepl('if (is.na(yr[1])) "" else yr[1]',
            substr(v155_ml, i, j), fixed = TRUE)
  })
  chk("★★ item 5：填进去的关键词**去重**（两个方向共用一个词时不然会出现两遍）", {
    i <- regexpr("apply_frontier <- function()", v155_ml, fixed = TRUE)[1]
    j <- regexpr("observeEvent(input$fr_dirs", v155_ml, fixed = TRUE)[1]
    i > 0 && j > i &&
      grepl("unique(unlist(DSAPP_LIT_FRONTIER_PRESETS[dirs]",
            substr(v155_ml, i, j), fixed = TRUE)
  })
  chk("★★ item 5：前沿模式走的还是同一条检索/订阅链路（没有第二套发送代码）", {
    # 页面上只该有一次 dsapp:lit_go，且「开始检索」那颗按钮还是原来那颗。
    length(gregexpr('sendCustomMessage("dsapp:lit_go"', v155_ml,
                    fixed = TRUE)[[1]]) == 1L &&
      length(gregexpr('observeEvent(input$go', v155_ml,
                      fixed = TRUE)[[1]]) == 1L
  })
  chk("★ item 5：litsub.R 里没多出联网/写库的东西（那一段还是纯函数）", {
    !grepl("dsapp_db(", v155_lit, fixed = TRUE) ||
      grepl("dsapp_litsub_list", v155_lit, fixed = TRUE)
  })
}

# =============================================================================
section("Test_V15.3：六个界面/渲染问题")
# =============================================================================
#
# 用户原话：
#   「1、论坛界面左侧需要有一定留白
#    2、运行时关于模型设置的问题报错"HTTP 400：Field 'max_tokens' must be at
#       most 65536"能不能直接亮一个按钮"直接帮我设置"，然后用户点击后就可以
#       自动更改并应用新的模型服务配置
#    3、现在对话框思考时还是会闪，不要闪，正常往外输出思考过程就行了
#    4、停止按钮重复了，可以把确认执行、补点建议、停止按钮都挪到正在执行的
#       会话里去
#    5、言出法随界面选择技能时需要能对技能的内容进行查看
#    6、演出法随界面输出的md似乎很多标记语言未能正常渲染，再试一下图片是否
#       也能正常渲染」
#
# ⚠️ 下面全是**离线**能判的：纯函数 + 源码哨兵。几何（左留白差几像素、按钮
#    到底可不可见、图有没有真的解码出来）只有浏览器量得准，那一半在
#    tests/ui_v153/ 里。真 400 端到端在 tests/v153_maxtok_fix.R。
{
  v153_chat <- paste(drop_comment_lines(readLines("R/mod_chat.R", warn = FALSE)),
                     collapse = "\n")
  v153_mdl  <- paste(drop_comment_lines(readLines("R/mod_model.R", warn = FALSE)),
                     collapse = "\n")
  v153_rnd  <- paste(drop_comment_lines(readLines("R/render.R", warn = FALSE)),
                     collapse = "\n")
  v153_app  <- paste(drop_comment_lines(readLines("app.R", warn = FALSE)),
                     collapse = "\n")
  v153_js   <- paste(readLines("www/app.js", warn = FALSE), collapse = "\n")

  # ---- (a) item 2：从 400 原文里读上限 -----------------------------------
  #
  # ⚠️ 这一节钉的是**判据的方向**，不是"能不能解析出一个数"。
  #    dsapp_maxtok_advice() 的契约是"宁可不给按钮，也不给一个错的"：
  #    解析不出来一律 NULL。给一个错的数比不给按钮坏得多 —— 用户会以为
  #    已经修好了，然后一模一样地再撞一次。
  chk("★★ 真 400 原文能解析出 65536（用户贴的那句）", {
    a <- dsapp_maxtok_advice(
      "HTTP 400: Field 'max_tokens' must be at most 65536")
    is.list(a) && identical(a$param, "max_tokens") && a$max == 65536
  })
  chk("★★ 千分位写法（65,536）也认", {
    a <- dsapp_maxtok_advice("max_tokens: no more than 65,536")
    is.list(a) && a$max == 65536
  })
  # ★★ 这一条是整节里最重要的：context length 类报错里**同样有**
  #    "maximum ... 65536"，照样能过那些模式 —— 但那个 65536 是**总上下文**
  #    （提示词 + 回复），不是 max_tokens 的上限。拿它去设 max_tokens 的结果
  #    是：提示词已经占了两万，设成 65536 照样 400，而界面上写着"已按厂商的
  #    上限调好了"。**给一个错的按钮比不给按钮坏得多。**
  chk("★★★ 上下文长度类报错**必须**返回 NULL（那个 65536 是总上下文，不是上限）", {
    is.null(dsapp_maxtok_advice(paste(
      "This model's maximum context length is 65536 tokens.",
      "However, you requested 70000 tokens."))) &&
      is.null(dsapp_maxtok_advice(
        "Error code: 400 - context_length_exceeded, maximum context is 65536")) &&
      is.null(dsapp_maxtok_advice("输入过长，超出模型上下文窗口"))
  })
  chk("★★ 提到 max_tokens 但**没说上限** → NULL（宁可少一颗按钮）", {
    is.null(dsapp_maxtok_advice("Invalid value for max_tokens")) &&
      is.null(dsapp_maxtok_advice("max_tokens is required")) &&
      is.null(dsapp_maxtok_advice("boom")) &&
      is.null(dsapp_maxtok_advice("")) &&
      is.null(dsapp_maxtok_advice(NULL))
  })
  # ★ 「哪一句里的数才算数」：整段一起找的话会先命中左边那个 2（温度上限），
  #   而它跟 max_tokens 一点关系都没有。
  chk("★★★ 同一句里两个上限时，取**提到 tokens 的那一句**里的数", {
    a <- dsapp_maxtok_advice(
      "temperature must be at most 2. max_tokens must be at most 65536")
    is.list(a) && a$max == 65536
  })
  # ★ range 参数的存在意义：让"返回非 NULL"和"点了按钮真的会变"是同一件事。
  #   不判这一条的话，用户点完按钮什么也没发生，而后端提示"已设置"。
  chk("★★ 不比现在的上限更紧就不给按钮（点了也不会变 = 别给）", {
    rng <- list(min = 1024, max = 10485760, step = 1024)
    tight <- dsapp_maxtok_advice("max_tokens must be at most 32768", range = rng)
    same  <- dsapp_maxtok_advice("max_tokens must be at most 10485760", range = rng)
    wider <- dsapp_maxtok_advice("max_tokens must be at most 99999999", range = rng)
    (is.list(tight) && tight$max == 32768) && is.null(same) && is.null(wider)
  })

  # ---- (b) item 6a：HTML 白名单 ------------------------------------------
  #
  # ★★ 白名单必须守住两条，任何一条松了都是 XSS 入口：**全小写**、**无属性**。
  #    下面逐条钉死。这不是"防御性编程"——这一版确实松动了"先转义"那条铁律
  #    的一角（见 R/render.R 顶部），松动的边界在哪必须写清楚。
  chk("★★ <h4> 渲染成真标签（用户报的「HTML 标签变字面文字」）", {
    h <- dsapp_md_html("<h4>小标题</h4>")
    grepl("<h4>", h, fixed = TRUE) && !grepl("&lt;h4&gt;", h, fixed = TRUE)
  })
  chk("★ <br> / <details> / <summary> 也放行（线上真实消息里都有）", {
    grepl("<br>", dsapp_md_html("a<br>b"), fixed = TRUE) &&
      grepl("<details>", dsapp_md_html("<details><summary>s</summary>t</details>"),
            fixed = TRUE)
  })
  chk("★★★ <script> / <iframe> / <style> **照样转义**（不在白名单里）", {
    for (t in c("script", "iframe", "style", "object", "embed")) {
      h <- dsapp_md_html(sprintf("<%s>alert(1)</%s>", t, t))
      if (grepl(sprintf("<%s>", t), h, fixed = TRUE)) return(FALSE)
    }
    TRUE
  })
  # ★ <a> / <img> 尤其不能放：它们的危害全在属性上，而"无属性"这条规则恰恰是
  #   放行它们的唯一理由 —— 干脆别放。
  chk("★★★ <a> / <img> 不在白名单里（它们的危害全在属性上）", {
    !grepl("<a ", dsapp_md_html("<a href=\"javascript:alert(1)\">x</a>"),
           fixed = TRUE) &&
      !grepl("<img ", dsapp_md_html("<img src=x onerror=alert(1)>"),
             fixed = TRUE)
  })
  # ★★ 带属性的排版标签**一个都不放行**。没有属性就没有 on* 事件、
  #    没有 style、没有 href/src —— 这一层不引入任何新的可执行面。
  chk("★★★ 带属性的一个都不放行（<h4 onclick=…> 必须还是字面文字）", {
    h <- dsapp_md_html("<h4 onclick=\"alert(1)\">a</h4>")
    !grepl("<h4 onclick", h, fixed = TRUE) &&
      grepl("&lt;h4 onclick", h, fixed = TRUE)
  })
  # ★★ 大小写敏感在这一版里**不是随手写的严格，是这条白名单的关键**：
  #    线上那些 <Error><Code>NoSuchKey</Code>（S3 报错原文）和
  #    <html><head><meta><title>（模型在描述一个文件长什么样）**必须**保持
  #    字面文字 —— 渲染出来它们会从屏幕上消失，而那正是用户要看的字。
  chk("★★★ 大写标签一律不认（<Error>/<H4> 必须保持字面文字）", {
    h1 <- dsapp_md_html("<Error><Code>NoSuchKey</Code></Error>")
    h2 <- dsapp_md_html("<H4>a</H4>")
    grepl("&lt;Error&gt;", h1, fixed = TRUE) &&
      grepl("&lt;H4&gt;", h2, fixed = TRUE)
  })
  chk("★ 白名单本身：全小写、无重复、不含 script/iframe/a/img", {
    # ⚠️⚠️ 变量名**不能**叫 `tags`。自检的顶层（以及 chk 的 { } 块里）赋值
    #    写进的是 globalenv，而所有 mod_*.R 正是 source 到 globalenv 的 ——
    #    于是这个赋值会**永久遮住** `htmltools::tags`，之后任何一条渲染断言
    #    里的 `tags$input` 都会报 "$ operator is invalid for atomic vectors"，
    #    报错信息完全指不到这一行。
    #    2026-09-29 实测踩到：item 7 那 4 条渲染断言集体变红，查了半天是这里。
    #    同一类坑还有下面那几处（img / css / br / p / a 都是标签函数名）。
    safe_tags <- DSAPP_MD_SAFE_TAGS
    all(safe_tags == tolower(safe_tags)) && !anyDuplicated(safe_tags) &&
      !any(c("script", "iframe", "a", "img", "style") %in% safe_tags)
  })
  chk("★ commonmark 开了 tagfilter（第二层兜底）",
      "tagfilter" %in% DSAPP_MD_EXTENSIONS)

  # ---- (c) item 6b：图片的包含性校验 --------------------------------------
  #
  # ★★ 这一节是整个改动里**唯一一处安全边界**。模型输出是彻头彻尾的不可信
  #    输入（提示注入、它读到的文件内容都会变成它写的话）。没有包含性校验的话，
  #    模型写一句 ![](/etc/shadow) 就能让服务端把任意文件读出来、以图片的
  #    名义发进浏览器 —— 而界面上看不出任何异常，只是一张"加载失败"的图。
  v153_sid <- "11111111-2222-3333-4444-555555555555"
  v153_ws  <- dsapp_ws_dir(v153_sid, cfg, create = TRUE)
  dir.create(file.path(v153_ws, "figures"), showWarnings = FALSE,
             recursive = TRUE)
  writeBin(as.raw(c(0x89, 0x50, 0x4E, 0x47)),
           file.path(v153_ws, "figures", "v153.png"))

  chk("★★ 工作区里的相对路径能解析成真路径", {
    p <- dsapp_md_image_path("figures/v153.png", v153_sid, cfg)
    is.character(p) && length(p) == 1L && !is.na(p) && file.exists(p)
  })
  chk("★★ 带查询串/锚点的写法也算（![](a.png?v=2) 是合法 Markdown）",
      !is.null(dsapp_md_image_path("figures/v153.png?v=2", v153_sid, cfg)))
  chk("★★★ `../../etc/passwd` 一律 NULL（目录穿越）",
      is.null(dsapp_md_image_path("../../etc/passwd", v153_sid, cfg)) &&
        is.null(dsapp_md_image_path("figures/../../../../etc/passwd",
                                    v153_sid, cfg)))
  chk("★★★ 工作区**之外**的绝对路径一律 NULL", {
    outside <- tempfile("v153_out_"); writeBin(as.raw(1:4), outside)
    is.null(dsapp_md_image_path(outside, v153_sid, cfg)) &&
      is.null(dsapp_md_image_path("/etc/passwd", v153_sid, cfg))
  })
  chk("★★ 非图片扩展名一律 NULL（不能让任意文件以图片名义出去）", {
    writeLines("secret", file.path(v153_ws, "notes.txt"))
    is.null(dsapp_md_image_path("notes.txt", v153_sid, cfg))
  })
  chk("★★ 带协议头的（http/data/协议相对）不归这里管，一律 NULL", {
    is.null(dsapp_md_image_path("https://x/a.png", v153_sid, cfg)) &&
      is.null(dsapp_md_image_path("data:image/png;base64,AAAA",
                                  v153_sid, cfg)) &&
      is.null(dsapp_md_image_path("//evil/a.png", v153_sid, cfg))
  })
  chk("★★ 会话 id 无效时 NULL（dsapp_ws_dir 给的是 NA_character_，不是 NULL）",
      is.null(dsapp_md_image_path("figures/v153.png", "nope", cfg)) &&
        is.null(dsapp_md_image_path("figures/v153.png", NULL, cfg)))
  # ★ 没抓到图时 srcs 为空，且 HTML 原样返回（不能把正文弄丢）。
  chk("★ 没有 <img> 时原样返回，srcs 为空", {
    r <- dsapp_md_inline_images("<p>纯文字</p>", NULL, v153_sid, cfg)
    identical(r$html, "<p>纯文字</p>") && !length(r$srcs)
  })

  # ---- (c2) 渲染链的顺序（顺序错了图就是裂的）-----------------------------
  #
  # ★★ 这条钉的是**顺序**：inline_images 必须在 sanitize **之前**。
  #    反过来的话相对路径已经被剥成空串，拿到手时已经没有 src 可以换 ——
  #    而且不报错，只是一张裂图。（Test_V15.2 的邮件路径踩过一模一样的坑。）
  # ⚠️ 锚在 `dsapp_md_chat_html <- function(` 那个块里找，不是全文找：
  #    `.dsapp_md_html_raw(txt` 在 `dsapp_md_html()` 里也出现一次（208 行），
  #    全文找的话三个下标全部前移，断言照样为真 —— 但它证明的是**别的函数**
  #    的顺序。这种"碰巧为真"的哨兵比没有更坏。
  # ★ V15.4：链上多了一步 `dsapp_md_limit_data_imgs()`（item 5 的体积闸门），
  #   位置是**内联之后、消毒之前**。顺序反了的后果各不一样、都不报错：
  #   放在内联之前 → 挡不到 `![](data:…,` 那种（commonmark 渲染出来的）；
  #   放在消毒之后 → 那时 src 已经被剥掉了，闸门量的是空串。
  chk("★★★ dsapp_md_chat_html 的四步顺序：raw → inline_images → 体积闸门 → sanitize", {
    i <- regexpr("dsapp_md_chat_html <- function(", v153_rnd, fixed = TRUE)[1]
    if (i < 0) return(FALSE)
    body <- substr(v153_rnd, i, i + 1600L)
    j <- regexpr(".dsapp_md_html_raw(txt", body, fixed = TRUE)[1]
    k <- regexpr("dsapp_md_inline_images(html", body, fixed = TRUE)[1]
    n <- regexpr("dsapp_md_limit_data_imgs(r$html", body, fixed = TRUE)[1]
    m <- regexpr("dsapp_sanitize_links(html", body, fixed = TRUE)[1]
    j > 0 && k > 0 && n > 0 && m > 0 && j < k && k < n && n < m
  })
  # ★ 缓存键必须是**会话 token**，不是会话 id：同一个对话可以开在两个标签页里，
  #   它们各是一个 Shiny session、各有各的 token —— 按会话 id 缓存的话，
  #   甲标签页拿到的地址在乙标签页里是无效的（那个 token 不是它的）。
  chk("★★ 图片地址的缓存键用的是 session$token（不是 session id）",
      grepl("session$token", v153_rnd, fixed = TRUE))
  # ★ memo 的 digest 必须把 **sid** 一起算进去：预览地址里带会话 token 和
  #   一次性 nonce，跨会话复用缓存会把别的会话的地址发给这一会话。
  chk("★★ 正文 memo 的 key 里有 img_sid（跨会话复用缓存会发错地址）", {
    i <- regexpr("dsapp_memo(\"segtext\"", v153_rnd, fixed = TRUE)[1]
    j <- regexpr("dsapp_linkify_files(html", v153_rnd, fixed = TRUE)[1]
    i > 0 && j > 0 && grepl("img_sid", substr(v153_rnd, i, j), fixed = TRUE)
  })

  # ---- (d) item 2：学到的上限（第四层）-----------------------------------
  #
  # ★★ 这一层会改变 dsapp_param_range() 的输出，而它被模型页、agent 循环、
  #    起标题那次短请求**共同使用**。所以第一条断言必须是：
  #    **learned 为空时，输出和没有这一层时逐字节相同** —— 零行为变化。
  chk("★★★ learned 为空时，dsapp_param_range() 零行为变化", {
    dsapp_param_learned_clear()
    r <- dsapp_param_range("deepseek", "deepseek-chat", "max_tokens")
    identical(r, DSAPP_PARAM_DEFAULTS[["max_tokens"]])
  })
  chk("★★ 学到 max=65536 之后量程收紧、clamp 把 1M 夹成 65536", {
    dsapp_param_learned_put("deepseek", "deepseek-chat", "max_tokens",
                            max_value = 65536)
    r <- dsapp_param_range("deepseek", "deepseek-chat", "max_tokens")
    v <- dsapp_param_clamp("deepseek", "deepseek-chat", "max_tokens", 10485760)
    ok <- isTRUE(r$max == 65536) && isTRUE(v == 65536)
    dsapp_param_learned_clear()
    ok
  })
  # ★ 层与层之间是按 (厂商, 模型) 分的：学到 A 家的话不能管到 B 家。
  chk("★★ 学到的是**某个模型**的上限，别的模型不受影响", {
    dsapp_param_learned_put("deepseek", "deepseek-chat", "max_tokens",
                            max_value = 65536)
    other <- dsapp_param_range("deepseek", "deepseek-reasoner", "max_tokens")
    ok <- isTRUE(other$max == DSAPP_PARAM_DEFAULTS[["max_tokens"]]$max)
    dsapp_param_learned_clear()
    ok
  })
  # ★★ 脏数据（min > max）**不许**让整条退回默认档 —— 那等于把学到的上限
  #    静默丢掉。症状是"点了「直接帮我设置」、提示成功、下一轮一模一样地再
  #    400 一次"，而解析、写库、缓存三处各自看都对。
  chk("★★★ 学到的一条 min>max 的脏记录**不会**把上限静默丢掉", {
    dsapp_param_learned_put("deepseek", "deepseek-chat", "max_tokens",
                            max_value = 2048, min_value = 9999999)
    r <- dsapp_param_range("deepseek", "deepseek-chat", "max_tokens")
    ok <- is.finite(r$min) && is.finite(r$max) && r$min <= r$max &&
      isTRUE(r$max == 2048)            # ← 关键：上限没被退回默认的 10485760
    dsapp_param_learned_clear()
    ok
  })
  # ★ 「只收不放」：一条学到的**宽**值不许把厂商档/模型档放松掉 ——
  #   那两层存在的意义正是"有人确认过这家就是这个数"。
  chk("★★ 学到的宽值不会放松已有量程（只收不放）", {
    dsapp_param_learned_put("deepseek", "deepseek-chat", "max_tokens",
                            max_value = 99999999)
    r <- dsapp_param_range("deepseek", "deepseek-chat", "max_tokens")
    ok <- isTRUE(r$max <= DSAPP_PARAM_DEFAULTS[["max_tokens"]]$max)
    dsapp_param_learned_clear()
    ok
  })
  chk("★★ 清空之后完全复原（不是「少了一点」）", {
    dsapp_param_learned_clear()
    identical(dsapp_param_range("deepseek", "deepseek-chat", "max_tokens"),
              DSAPP_PARAM_DEFAULTS[["max_tokens"]])
  })
  # ★ 空厂商/空模型名**一律不记**：一条"没有厂商"的记录会套到所有厂商头上，
  #   那是拿 A 家的话去管 B 家，而 B 家的真实上限可能高得多。
  chk("★★ dsapp_param_learn() 空厂商/空模型/未知参数一律拒收", {
    !isTRUE(dsapp_param_learn("", "m", "max_tokens", max_value = 100,
                              con = dsapp_db(cfg))) &&
      !isTRUE(dsapp_param_learn("v", "", "max_tokens", max_value = 100,
                                con = dsapp_db(cfg))) &&
      !isTRUE(dsapp_param_learn("v", "m", "nope", max_value = 100,
                                con = dsapp_db(cfg))) &&
      # 比参数自己的最低可填值还小的"上限"盖不住量程下限，存进去只会让
      # min/max 打架 —— 宁可不记。
      !isTRUE(dsapp_param_learn("v", "m", "max_tokens", max_value = 1,
                                con = dsapp_db(cfg)))
  })
  # ★★ 落库 + 读回：学习发生在**别的会话进程**里，只放内存的话用户刷新一下
  #    页面就是空缓存，同一个 400 再来一遍。
  chk("★★★ dsapp_param_learn() 落库，_load() 能读回来（跨进程的唯一通道）", {
    ok <- FALSE
    try({
      dsapp_param_learned_clear()
      con <- dsapp_db(cfg)
      # 用一个**只属于自检**的名字，绝不碰真实厂商的记录
      dsapp_param_learn("zzselfvendor", "zzselfmodel", "max_tokens",
                        max_value = 65536, source = "selftest",
                        note = "selftest 造的行，跑完就删", con = con)
      n <- DBI::dbGetQuery(con,
        "SELECT COUNT(*) AS n FROM model_param_limits
          WHERE vendor = 'zzselfvendor'")$n
      dsapp_param_learned_clear()               # 模拟"换了一个 R 进程"
      empty <- is.null(dsapp_param_learned_get("zzselfvendor", "zzselfmodel",
                                               "max_tokens"))
      dsapp_param_learned_load(con)             # 等价于 app.R 启动时那一次
      r <- dsapp_param_range("zzselfvendor", "zzselfmodel", "max_tokens")
      ok <- n == 1L && isTRUE(empty) && isTRUE(r$max == 65536)
      # 收拾干净：自检**不许**在库里留行（何况这条走的是临时库）
      DBI::dbExecute(con,
        "DELETE FROM model_param_limits WHERE vendor = 'zzselfvendor'")
      dsapp_param_learned_clear()
    }, silent = TRUE)
    ok
  })
  chk("★★ app.R 启动时灌一次学到的上限（不然新会话量程又回到 1M）",
      grepl("dsapp_param_learned_load(", v153_app, fixed = TRUE))

  # ---- (e) item 4：三颗按钮「一处渲染、一处出现」-------------------------
  #
  # ★★ 这一版最大的结构改动：动 3 个 id、4 个挂载点。判据不是"看着只有一颗"，
  #    是**只有一份渲染函数**、**每个宿主只渲染一次**、**停止入口只有一个**。
  chk("★★★ 三颗按钮只有**一份**渲染（run_actions_ui 只定义一次）", {
    n <- length(gregexpr("run_actions_ui <- function(", v153_chat,
                         fixed = TRUE)[[1]])
    n == 1L
  })
  chk("★★★ action_host() 只定义一次（宿主判据是一处真相）",
      length(gregexpr("action_host <- reactive(", v153_chat,
                      fixed = TRUE)[[1]]) == 1L)
  chk("★★★ 全应用只剩**一颗** actionButton(ns(\"stop\"))", {
    n <- length(gregexpr('actionButton(ns("stop")', v153_chat, fixed = TRUE)[[1]])
    n == 1L
  })
  chk("★★★ 旧的第二、第三颗停止按钮（stop_task / stop_detach）已彻底删掉",
      !grepl('ns("stop_task")', v153_chat, fixed = TRUE) &&
        !grepl('ns("stop_detach")', v153_chat, fixed = TRUE) &&
        !grepl('input$stop_task', v153_chat, fixed = TRUE) &&
        !grepl('input$stop_detach', v153_chat, fixed = TRUE))
  # ★★ "任何时刻只有一处可见"的**全部实现**就是这一句守卫。它比"数一数
  #    有几处调用"重要得多 —— 挂载点可以有多个（同一个 renderUI 的两条分支
  #    里各写一次是正常的），守卫一丢就是几处同时亮。
  chk("★★★ run_actions_ui 开头就是宿主守卫（「一处可见」的全部实现）", {
    i <- regexpr("run_actions_ui <- function(host)", v153_chat, fixed = TRUE)[1]
    if (i < 0) return(FALSE)
    body <- substr(v153_chat, i, i + 400L)
    grepl("if (!identical(action_host(), host)) return(NULL)", body,
          fixed = TRUE)
  })
  chk("★★★ 四个宿主每一个都真的有挂载点（少一个 = 那种状态下按钮凭空消失）", {
    for (h in c("stream", "live", "hist", "detach")) {
      n <- length(gregexpr(sprintf('run_actions_ui("%s")', h), v153_chat,
                           fixed = TRUE)[[1]])
      if (n < 1L) return(FALSE)
    }
    TRUE
  })
  # ★★ 停止按钮是**一条** handler、按状态分派。四个分支缺一个的症状：
  #    某个状态下按下停止什么也不发生（或更糟：停错了东西）。
  # ⚠️ 分支的**判据必须和 action_host() 同序**（stream → live → hist →
  #    detach）。顺序反了的症状不是报错，是"点了停止，停的是另一件事" ——
  #    比如正在生成时有个后台任务也在跑，先判 detach 就会去停后台、
  #    而屏幕上正在吐的那段字还在吐。
  chk("★★★ input$stop 是一条按状态分派的 handler（四个分支都在，且同序）", {
    i <- regexpr("observeEvent(input$stop,", v153_chat, fixed = TRUE)[1]
    if (i < 0) return(FALSE)
    body <- substr(v153_chat, i, i + 9000L)
    j1 <- regexpr("dsapp_chat_abort(", body, fixed = TRUE)[1]     # ① 正在生成
    j2 <- regexpr("live_here()", body, fixed = TRUE)[1]           # ② 本会话的任务
    j3 <- regexpr("dsapp_arun_stop(", body, fixed = TRUE)[1]      # ③ 后台续跑
    j4 <- regexpr("当前没有正在生成的内容", body, fixed = TRUE)[1]  # ④ 都没
    j1 > 0 && j2 > 0 && j3 > 0 && j4 > 0 && j1 < j2 && j2 < j3 && j3 < j4
  })
  # ★ 实时卡片和后台横幅都得**收下**调用方递进来的 actions，不能自己再长一颗。
  chk("★★ 实时卡片 / 后台横幅都是收 actions，不是自己画停止按钮", {
    for (fn in c("dsapp_live_card", "dsapp_detach_banner")) {
      i <- regexpr(paste0(fn, " <- function("), v153_rnd, fixed = TRUE)[1]
      if (i < 0) return(FALSE)
      head <- substr(v153_rnd, i, i + 700L)
      if (!grepl("actions", head, fixed = TRUE)) return(FALSE)
      if (grepl("stop_input", head, fixed = TRUE)) return(FALSE)
    }
    TRUE
  })

  # ---- (f) item 3：思考过程是「追加」出来的，不是每拍重画 ---------------
  #
  # ★★ 根因：流式泵每 200ms 无条件写 rv$thinking <- TRUE，而**写 reactiveVal
  #    就算值没变也失效下游** —— output$thinking_box 因此每 200ms 重画一次，
  #    用户展开的 <details> 被折回去、<pre> 的滚动位置归零。
  #    不是动画问题，是 **DOM 节点每 200ms 被换掉**。
  chk("★★★ 泵里不再**无条件**写 rv$thinking（这一条单独就能消掉绝大部分闪烁）", {
    i <- regexpr("rv$thinking <- TRUE", v153_chat, fixed = TRUE)[1]
    if (i < 0) return(TRUE)                    # 一次都不写才是理想情况
    # 允许的写法只有带条件的：if (!isTRUE(rv$thinking)) rv$thinking <- TRUE
    left <- substr(v153_chat, max(1L, i - 60L), i)
    grepl("if (!isTRUE(rv$thinking))", left, fixed = TRUE)
  })
  chk("★★★ 增量走 sendCustomMessage(\"dsapp:think\")，正文由前端 append",
      grepl('sendCustomMessage("dsapp:think"', v153_chat, fixed = TRUE) &&
        grepl("dsapp_think_append", v153_chat, fixed = TRUE))
  # ★★ 用 createTextNode 而不是 innerHTML：模型输出是**纯文本**，
  #    天然免转义 —— 用 innerHTML 拼就是在给模型一个注入点。
  chk("★★★ app.js 用 createTextNode 追加（不是 innerHTML，模型输出不可信）", {
    i <- regexpr('addCustomMessageHandler("dsapp:think"', v153_js,
                 fixed = TRUE)[1]
    if (i < 0) return(FALSE)
    body <- substr(v153_js, i, i + 1600L)
    grepl("createTextNode", body, fixed = TRUE) &&
      !grepl("innerHTML", body, fixed = TRUE)
  })
  # ★ 骨架必须在**独立的 uiOutput** 里，不能长在 output$streaming 里面：
  #   后者会因为 action_host() 读到 agent_ver() 而每秒重算一次，
  #   一重算 <pre> 就是新节点 —— 追加进去的字全丢。
  chk("★★★ 思考骨架有自己的 uiOutput，不在 output$streaming 里", {
    grepl('uiOutput(ns("thinking_box"))', v153_chat, fixed = TRUE) &&
      grepl("output$thinking_box <- renderUI", v153_chat, fixed = TRUE)
  })
  # ★ 骨架只依赖**粗粒度**的 think_gen。依赖细粒度的东西（正文、字数）就
  #   等于又回到"每拍重画"。
  chk("★★ output$thinking_box 只依赖粗粒度的 think_gen", {
    i <- regexpr("output$thinking_box <- renderUI", v153_chat, fixed = TRUE)[1]
    if (i < 0) return(FALSE)
    body <- substr(v153_chat, i, i + 900L)
    grepl("think_gen()", body, fixed = TRUE) &&
      !grepl("rv$thinking", body, fixed = TRUE) &&
      !grepl("rv$stream_text", body, fixed = TRUE)
  })
  chk("★ 每一轮新生成时重置已发送计数（reason_sent），否则第二轮一个字都不出", {
    i <- regexpr("dsapp_llm_begin <- function(", v153_chat, fixed = TRUE)[1]
    if (i < 0) return(FALSE)
    body <- substr(v153_chat, i, i + 2500L)
    # ⚠️ Test_V15.7 item 2：这一行从 `st$reason_sent` 变成了 `r$reason_sent`
    #    （st 现在是"显示中的那个 run"这个别名，run 内部一律认 r）。
    #    钉的是**哪个前缀**就没意义了 —— 钉"这个计数器被归零"这件事本身。
    #    窗口只有 llm_begin 这一小段，所以不会误配到 show_run() 里那句。
    grepl("reason_sent <- 0L", body, fixed = TRUE) &&
      grepl("think_gen(think_gen() + 1L)", body, fixed = TRUE)
  })

  # ---- (g) item 5：技能内容查看 ------------------------------------------
  #
  # ★★ 「查看」那颗链接在勾选行**里面**，所以必须 stopPropagation ——
  #    不然点它会顺手把那一行的勾选框翻掉（用户以为自己在看内容，
  #    实际上改了这一轮要挂哪些技能）。
  chk("★★★ 技能「查看」链接有 stopPropagation + preventDefault", {
    i <- regexpr("dsapp-skillpick-peek", v153_chat, fixed = TRUE)[1]
    if (i < 0) return(FALSE)
    seg <- substr(v153_chat, i, i + 700L)
    grepl("stopPropagation", seg, fixed = TRUE) &&
      grepl("preventDefault", seg, fixed = TRUE) &&
      grepl("priority:'event'", seg, fixed = TRUE)
  })
  # ★ 用户明确选的是「只显示渲染后的」—— 所以走 dsapp_md_html，不摆 Markdown 原文。
  chk("★★ 技能正文渲染后再显示（用户选的是「只显示渲染后的」）", {
    i <- regexpr("output$skill_peek <- renderUI", v153_chat, fixed = TRUE)[1]
    if (i < 0) return(FALSE)
    body <- substr(v153_chat, i, i + 2200L)
    grepl("dsapp_md_html(body)", body, fixed = TRUE)
  })
  # ★ 收起那颗要把 input 设成 **null**（不是 ""）：空串是个合法值，
  #   设成空串的话 observeEvent 的 ignoreNULL 分不出"没点过"和"收起了"。
  chk("★ 「收起」把 skill_view 设成 null（空串会被当成一次选中）", {
    i <- regexpr("dsapp-skillpeek-x", v153_chat, fixed = TRUE)[1]
    if (i < 0) return(FALSE)
    grepl("Shiny.setInputValue(%s,null", substr(v153_chat, i, i + 500L),
          fixed = TRUE)
  })

  # ---- (h) item 1：论坛页的左留白 ----------------------------------------
  #
  # ★★ `.dsapp-page` 这个类**一条规则都没有**（它只是个记号）；别的页面靠
  #    card() → .card-body 自带的 1rem 拿到留白，论坛页是唯一一个不套 card
  #    的整页。几何判据（两侧 x 坐标必须相等）在 tests/ui_v153/ 里。
  chk("★★ 论坛页挂上了 dsapp-page-flush（没有 card 外壳的那一页才挂）", {
    v153_forum <- paste(readLines("R/mod_forum.R", warn = FALSE),
                        collapse = "\n")
    grepl('"dsapp-page dsapp-page-flush"', v153_forum, fixed = TRUE)
  })
  chk("★★ app.css 里有 .dsapp-page-flush 的左右 padding", {
    blk <- dsapp_block_at(css_code,
                          regexpr("\\.dsapp-page-flush\\s*\\{", css_code))
    nzchar(blk) && grepl("padding-left", blk, fixed = TRUE) &&
      grepl("padding-right", blk, fixed = TRUE)
  })
  # ★ 带 card 的页面**不能**挂这个类 —— 那就是双份缩进，症状是"这一页和
  #   别的页面对不齐"，而且只在这一页看得出来。
  chk("★★ 挂了 flush 的只有**没有 card 外壳**的那些页面", {
    # ⚠️ 必须**剥注释**再扫。mod_forum.R 里就有一段解释这个类的注释，
    #    而它写的正是这个类名 —— 不剥的话扫出来的是"这一页和自己解释
    #    自己"，看起来完全正常。（连踩三次的老坑。）
    hits <- character(0)
    for (f in list.files("R", pattern = "^mod_.*[.]R$", full.names = TRUE)) {
      txt <- paste(drop_comment_lines(readLines(f, warn = FALSE)),
                   collapse = "\n")
      if (grepl("dsapp-page dsapp-page-flush", txt, fixed = TRUE)) {
        hits <- c(hits, basename(f))
      }
    }
    identical(sort(hits), "mod_forum.R")
  })

  # ---- (i) 几处接线 -------------------------------------------------------
  chk("★★ 错误气泡上的「直接帮我设置」按钮接的是真解析结果 + 真写库", {
    grepl('actionButton(ns("maxtok_fix")', v153_chat, fixed = TRUE) &&
      grepl("dsapp_maxtok_advice(rv$error)", v153_chat, fixed = TRUE) &&
      grepl("dsapp_param_learn(", v153_chat, fixed = TRUE)
  })
  chk("★★ 模型页收得下 maxtok_force，并**直接写 state$max_tokens**", {
    # ★★ V15.5 item 6 把这一条**反过来了**，这是故意的、不是放宽：
    #    V15.3 item 2 当时的做法（把厂商报的 max_tokens 上限直接写进用户
    #    那一格）在新语义下是**有害的** —— 那一格现在是「单次使用上限」
    #    （一次请求合计多少 token），把 8192 写进去等于把整个上下文窗口
    #    砍到 8192，历史会被静默丢掉一大截，而界面还说"已经帮你设好了"。
    #    它真正的归宿是第四层（学到的上限），自动夹住推导出来的 max_tokens。
    #    ⚠️ v153_mdl 已经剥过注释了（见上面 drop_comment_lines），所以
    #       "不许再出现"这一条是真的在查代码，不是在查解释它的那段话。
    !grepl("observeEvent(state$maxtok_force$rev", v153_mdl, fixed = TRUE) &&
      !grepl("state$max_tokens <- vv", v153_mdl, fixed = TRUE) &&
      # 学过的东西照旧要能当场生效（发送端调它）
      grepl("dsapp_param_learn(", v153_chat, fixed = TRUE)
  })
  chk("★★ app.css 里那一排动作条相关的类都在", {
    needed <- c(".dsapp-actions", ".dsapp-fix-row", ".dsapp-fix-note",
                ".dsapp-skillpeek", ".dsapp-think-pre")
    all(vapply(needed, function(k) grepl(k, css_code, fixed = TRUE),
               logical(1)))
  })
  chk("★★ 助手气泡里的图片封了顶（不封顶会把气泡撑破）",
      grepl(".dsapp-msg-assistant .dsapp-bubble > img", css_code, fixed = TRUE) &&
        grepl("max-width: 100%", css_code, fixed = TRUE))
}

# =============================================================================
section("Test_V15.4 item 6：代码区渲染回归（这一版最要紧的一节）")
# =============================================================================
#
# ★★★ 这一节存在的理由：V15.3 的渲染**自己引入了回归**，而当时的自检全绿。
#
# 现场是线上 messages.id = 391（会话「绘制国旗」）。模型把**开围栏粘在正文
# 行尾**了 —— `…内存低于 500 MB。```python`，中间没有换行。CommonMark 的规矩
# 是围栏必须自成一行，所以那三个反引号只是普通文字，**整段 Python 被当成散文
# 渲染**。而 dsapp_md_allow_tags() 当时是全局 gsub、不看围栏，于是
# `parts.append("<h2>实际静态图</h2>")` 里的 `&lt;h2&gt;` 被还原成了活的
# `<h2>` 元素 —— 用户在气泡里看到的就是「完全没渲染」的那一片乱码。
#
# ⚠️⚠️ **V15.3 的自检为什么没拦住**（这是本仓第三次栽在同一个坑上）：
#    · selftest.R 里那条断言钉的是**管线形状**（字符串
#      `markdown_html\(\s*dsapp_md_allow_tags\(dsapp_escape\(txt\)\)`）；
#    · 逐条断标签那批用的全是**不带围栏**的用例。
#    「围栏里含白名单标签」这个形状**从来没写过** —— 而它就是线上真实的样子。
#    所以下面第一条断言用的是**线上那条消息的原文片段**，不是我编的例子。
#
# ⚠️ 记一下这两条断言在**改之前**是什么样（先跑一次确认它是红的，再改代码）：
#      围栏那一条：`<h2` 命中 3 次、`&lt;h2&gt;` 命中 0 次、`<pre>` 4 个
#      粘围栏那一条：渲染成 `<p>先说一句。```python x = "<h2>t</h2>"</p>`
#                    —— 正文和代码糊在一个段落里，还带一个活的 `<h2>`
{
  # ⚠️ 用「」而不是 ASCII 引号：这个文件里已经有中文串里嵌双引号的语法错误
  #    前科（一次报三个）。
  v154_fence <- paste0(
    "看这段代码：\n\n",
    "```python\n",
    "parts.append(\"<h2>实际静态图</h2>\")\n",
    "```\n\n完事。")

  chk("★★★ 围栏里的白名单标签**不许**变成活元素（V15.3 回归的正面用例）", {
    h <- dsapp_md_chat_html(v154_fence, NULL, NULL, cfg)
    !grepl("<h2", h, fixed = TRUE) &&
      grepl("&lt;h2&gt;", h, fixed = TRUE) &&
      lengths(regmatches(h, gregexpr("<pre", h, fixed = TRUE))) == 1L
  })
  chk("★★★ 围栏**外**的同一个标签照旧要渲染（V15.3 的能力不能退化）", {
    h <- dsapp_md_chat_html(paste0(v154_fence, "\n\n<h4>小标题</h4>"),
                            NULL, NULL, cfg)
    grepl("<h4>小标题</h4>", h, fixed = TRUE) &&
      !grepl("<h2", h, fixed = TRUE)
  })

  # ---- (a) 粘在正文行尾的围栏：线上 msg 391 的形状 --------------------------
  #
  # ★★★ 这一条是**真正**抓得住线上那个 bug 的那一条。上面那条（围栏自成一行）
  #     在改之前的代码上**也是绿的** —— 因为 commonmark 拿到 `<h2>` 之后在代码块
  #     里会把它重新转义一遍。所以"围栏里含标签"这个形状本身不构成 bug，
  #     **围栏没被 commonmark 认出来**才构成 bug。
  v154_glued <- paste0(
    "我会修正 GIF 帧转换，内存低于 500 MB。```python\n",
    "import base64\n",
    "parts.append(\"<h2>实际静态图</h2>\")\n",
    "    \"<img alt='五星红旗 PNG' src='data:image/png;base64,\"\n",
    "```")
  chk("★★★ 粘在正文行尾的围栏要能渲染成**代码块**（线上 msg 391 的形状）", {
    h <- dsapp_md_chat_html(v154_glued, NULL, NULL, cfg)
    one_pre <- lengths(regmatches(h, gregexpr("<pre", h, fixed = TRUE))) == 1L
    # 正文那一句还在外面（夹在 <p> 里），代码在里面
    one_pre && grepl("<p>我会修正", h, fixed = TRUE)
  })
  chk("★★★ 而且代码里那一行标签**没有**变成活元素", {
    h <- dsapp_md_chat_html(v154_glued, NULL, NULL, cfg)
    !grepl("<h2", h, fixed = TRUE) &&
      !grepl("<img", h, fixed = TRUE) &&
      grepl("&lt;h2&gt;", h, fixed = TRUE)
  })
  chk("★★★ 代码里的双引号显示成引号，不是 `&quot;` 那五个字符", {
    h <- dsapp_md_chat_html(v154_glued, NULL, NULL, cfg)
    # ★ 这条抓的是"转义了两遍"：dsapp_escape 先把 `"` 变成 `&quot;`，
    #   commonmark 再把 `&` 变成 `&amp;`。浏览器把 `&amp;quot;` 显示成
    #   `&quot;` —— 用户在代码块里看到的就是满屏的 &quot;。
    grepl("&quot;", h, fixed = TRUE) &&
      !grepl("&amp;quot;", h, fixed = TRUE) &&
      !grepl("&amp;lt;", h, fixed = TRUE) &&
      !grepl("&amp;gt;", h, fixed = TRUE)
  })

  # ---- (b) repair 的边界：已经在围栏里的那些反引号一个字都不能碰 ------------
  #
  # ⚠️ 线上 msg 156 / 215 / 247 里模型写的是**生成代码的代码**，里面有
  #    `"```",` / `A("```text")` 这种行。它们已经在围栏里了，要是被"粘围栏修复"
  #    拆到行首，会**提前闭合**当前围栏，把后面的代码全放出来 —— 症状是"那条
  #    消息的渲染从中间裂开"，而不会报任何错。
  chk("★★★ 围栏**里**的反引号行不许被拆（拆了会提前闭合围栏）", {
    inside <- paste0("```python\n",
                     "A(\"```text\")\n",
                     "B = \"```\"\n",
                     "```\n")
    identical(dsapp_md_repair_fences(inside), inside)
  })
  chk("★★★ 没有粘围栏的文本，repair 必须**逐字节**不变（含结尾空行）", {
    same <- c("",
              "一段普通的话。\n",
              "带尾部空行的话。\n\n",
              "```r\nx <- 1\n```\n",
              "no trailing newline",
              "行内代码 `a` 和 `b`\n")
    all(vapply(same, function(s) identical(dsapp_md_repair_fences(s), s),
               logical(1)))
  })
  # ---- (b2) ★ V15.6：**行中间**的落单反引号不是围栏，一个字都不许动 --------
  #
  # 起因是探针 C2 红了一条，查下去发现是真 bug（不是探针的）：模型写一句
  #   这一段用 ``` 包起来就行，不用给我代码。
  # 旧的判据只问"有没有不在行内代码段里的 3+ 串"。这一串是**落单**的（配不成
  # 对），于是被判成"粘在正文里的围栏"，拆到行首 —— commonmark 把后半句整个
  # 当成 info string 吃掉，屏幕上只剩「这一段用」，剩下那半句变成一个**空代码
  # 块**。库里、日志里都好好的，只有界面少了半句话。
  chk("★★★ 行中间的落单 ``` 不许被当成围栏拆开（拆了会吃掉后半句）", {
    mention <- "这一段用 ``` 包起来就行，不用给我代码。\n"
    h <- dsapp_md_chat_html(mention, NULL, NULL, cfg)
    identical(dsapp_md_repair_fences(mention), mention) &&
      grepl("包起来就行，不用给我代码。", h, fixed = TRUE) &&
      # 反面：不许出现"语言标注是半句中文"的空代码块
      !grepl("language-包起来", h, fixed = TRUE)
  })
  chk("★★★ 但行**尾**粘着的真围栏照样要拆（别把上一条修过头）", {
    # 正反对照：同一个函数，只差围栏的位置。这条红了说明判据收得太紧，
    # V15.4 item 6 要修的那个形状又回来了。
    glued <- "首次检索预计耗时 1 分钟。```python\nprint(1)\n```\n"
    r <- dsapp_md_repair_fences(glued)
    h <- dsapp_md_chat_html(glued, NULL, NULL, cfg)
    grepl("耗时 1 分钟。\n```python", r, fixed = TRUE) &&
      grepl("<pre", h, fixed = TRUE) &&
      grepl("language-python", h, fixed = TRUE) &&
      grepl("耗时 1 分钟。", h, fixed = TRUE)
  })
  chk("★★ 判据逐条：行尾型才算围栏，后面多一个字的都不算", {
    ok <- vapply(c("```", "```python", "``` r", "````python"),
                 function(t) .dsapp_md_glued_tail_ok(t), logical(1))
    no <- vapply(c("``` 包起来就行", "```python 这种方式不行",
                   "```python\n", "``` 后面还有字"),
                 function(t) !.dsapp_md_glued_tail_ok(t), logical(1))
    all(ok) && all(no)
  })
  chk("★★ 成对提到的行内代码段照旧不拆（V15.4 那条判据还在）", {
    # `用 ``` 开头、``` 结尾` —— 两串长度相等，配成行内代码段。
    s <- "用 ``` 开头、``` 结尾就行。\n"
    identical(dsapp_md_repair_fences(s), s)
  })
  chk("★★ 四空格缩进的代码块也算代码（白名单不许动它）", {
    h <- dsapp_md_chat_html("段落\n\n    x = \"<h2>t</h2>\"\n",
                            NULL, NULL, cfg)
    !grepl("<h2", h, fixed = TRUE) && grepl("<pre", h, fixed = TRUE)
  })
  chk("★ 行内代码里的标签也不放行（`` `<h4>` `` 要按字面显示）", {
    h <- dsapp_md_chat_html("用 `<h4>` 做标题", NULL, NULL, cfg)
    !grepl("<h4", h, fixed = TRUE) && grepl("<code>&lt;h4&gt;</code>", h,
                                            fixed = TRUE)
  })

  # ---- (c) `.dsapp_md_code_lines()` 本身 -----------------------------------
  chk("★★★ 代码行判定：围栏内为 TRUE、围栏外为 FALSE、闭围栏那行也算", {
    m <- .dsapp_md_code_lines("前\n```\n中\n```\n后")
    identical(m, c(FALSE, TRUE, TRUE, TRUE, FALSE))
  })
  chk("★★ 未闭合的围栏一直到结尾都算代码", {
    m <- .dsapp_md_code_lines("前\n```\n中\n后")
    identical(m, c(FALSE, TRUE, TRUE, TRUE))
  })
  chk("★★ 缩进代码块只在「空行之后」才成立（`    x` 紧跟正文只是段落续行）", {
    # CommonMark 的规矩：缩进代码块**不能打断段落**。
    # ⚠️ 判反了的代价是"某个正常的四空格续行被当成代码，白名单在那一段失效"。
    m1 <- .dsapp_md_code_lines("正文\n    续行")
    m2 <- .dsapp_md_code_lines("正文\n\n    代码")
    identical(m1, c(FALSE, FALSE)) && identical(m2, c(FALSE, FALSE, TRUE))
  })

  # ---- (d) 三条**别的**路不许跟着变 -----------------------------------------
  #
  # ⚠️ 粘围栏修复只开在聊天那条路（`.dsapp_md_html_raw(repair = TRUE)`）。
  #    邮件正文 / 文件预览 / 论坛的内容不是"模型刚吐出来的话"，没有理由跟着改。
  #    这条断言钉住的是"少改一条路就少一处要论证的地方"。
  chk("★★ 邮件/预览/论坛那条路（dsapp_md_html）**不**做粘围栏修复", {
    # ⚠️ 判据是「那三个反引号还在不在正文里」——不是「有没有活 <h2>」。
    #    fence-aware 的 allow_tags 对**所有**路都生效（那是安全闸，不是渲染
    #    优化），所以老路上 `<h2>` 也已经是字面文字了。两条路真正的差别只有
    #    "围栏有没有被拆出来"。
    h <- dsapp_md_html(v154_glued)
    grepl("```python", h, fixed = TRUE) &&
      !grepl("```python", dsapp_md_chat_html(v154_glued, NULL, NULL, cfg),
             fixed = TRUE)
  })
  chk("★★ `.dsapp_md_html_raw()` 的 repair 默认是关的", {
    f <- get(".dsapp_md_html_raw", envir = globalenv())
    isFALSE(formals(f)$repair)
  })

  # ---- (e) V15.3 那两条铁律不许松 -------------------------------------------
  chk("★★★ 大写的 / 带属性的 / 不在表里的标签，代码区外也不放行", {
    h1 <- dsapp_md_html("<H4>a</H4>")
    h2 <- dsapp_md_html("<h4 onclick=\"alert(1)\">a</h4>")
    h3 <- dsapp_md_html("<script>alert(1)</script>")
    grepl("&lt;H4&gt;", h1, fixed = TRUE) &&
      grepl("&lt;h4 onclick", h2, fixed = TRUE) &&
      !grepl("<h4 onclick", h2, fixed = TRUE) &&
      grepl("&lt;script&gt;", h3, fixed = TRUE)
  })

  # ---- (e2) item 5：`<img>` 放行（只留五个属性）+ `data:` 通道 --------------
  #
  # ★★ 这一节松动了本文件开头那条铁律（"HTML 一律先转义、只还原**无属性**
  #    标签"）。所以逐条钉死，一条都不能省：
  #      · 只放行 img 一个标签；
  #      · 只认 src/alt/title/width/height，别的**丢掉**；
  #      · 值不是照抄，是"解回原义 → 重新转义 → 双引号拼出来"（值里带 `"` 也
  #        拼不出第二个属性）；
  #      · src 仍要过协议白名单（http(s) / 会话私有地址 / 聊天那条路的 data:）。
  v154_png <- paste0("data:image/png;base64,",
                     paste(rep("iVBORw0KGgo", 4), collapse = ""))

  chk("★★★ item 6 原文那种写法（单引号）真的渲染成 <img>", {
    h <- dsapp_md_chat_html(
      paste0("<img alt='五星红旗 PNG' src='", v154_png, "'>"), NULL, NULL, cfg)
    grepl("<img ", h, fixed = TRUE) &&
      grepl("data:image/png;base64,", h, fixed = TRUE) &&
      grepl('alt="五星红旗 PNG"', h, fixed = TRUE)
  })
  chk("★★★ 认不出来的属性一律丢掉（onerror / style / class / loading）", {
    h <- dsapp_md_chat_html(
      paste0('<img src="', v154_png,
             '" onerror="alert(1)" style="position:fixed" class="x" loading="eager">'),
      NULL, NULL, cfg)
    !grepl("onerror", h, fixed = TRUE) && !grepl("style=", h, fixed = TRUE) &&
      !grepl("class=", h, fixed = TRUE) && !grepl("loading=", h, fixed = TRUE) &&
      grepl("<img src=", h, fixed = TRUE)
  })
  chk("★★★ 属性值里塞引号逃不出去（值由我们重新拼，不照抄原文）", {
    h <- dsapp_md_chat_html("<img src='a.png\" onerror=\"alert(1)'>", NULL, NULL, cfg)
    !grepl("onerror", h, fixed = TRUE)
  })
  chk("★★★ 没有 src / src 不加引号的，整个标签退回字面文字", {
    h1 <- dsapp_md_html("<img alt='x' onerror='alert(1)'>")
    h2 <- dsapp_md_html("<img src=x onerror=alert(1)>")
    grepl("&lt;img alt='x' onerror='alert(1)'&gt;", h1, fixed = TRUE) &&
      grepl("&lt;img src=x onerror=alert(1)&gt;", h2, fixed = TRUE)
  })
  chk("★★★ 围栏里写 `<img>` 的 Python 源码保持字面（msg 391 的现场）", {
    src <- "```python\nparts.append(\"<img src='a.png'>\")\n```"
    h <- dsapp_md_chat_html(src, NULL, NULL, cfg)
    !grepl("<img ", h, fixed = TRUE) &&
      grepl("&lt;img src='a.png'&gt;", h, fixed = TRUE)
  })
  chk("★★ 行内代码段里的 `<img>` 也不许被重写", {
    # ⚠️ allow_tags 对行内代码无害（commonmark 会重新转义），但 allow_img 是
    #    **重写**：不跳过的话 `` `<img src='a.png'>` `` 会变成双引号 + 一个斜杠。
    h <- dsapp_md_chat_html("写法是 `<img src='a.png'>`", NULL, NULL, cfg)
    grepl("<code>&lt;img src='a.png'&gt;</code>", h, fixed = TRUE)
  })
  chk("★★ 单引号 src 也要过协议白名单（javascript: 不许过）", {
    h <- dsapp_md_chat_html("<img src='javascript:alert(1)'>", NULL, NULL, cfg)
    !grepl("javascript:", h, fixed = TRUE)
  })
  chk("★★★ svg 内联图不放行（DSAPP_MAIL_DATA_SRC_RE 故意不含 svg）", {
    h <- dsapp_md_chat_html(
      "<img src='data:image/svg+xml;base64,PHN2Zz48L3N2Zz4='>", NULL, NULL, cfg)
    !grepl("data:image/svg", h, fixed = TRUE)
  })
  # ⚠️⚠️ 这条是这一版**当场踩到**的回归，别再删：属性正则放宽到"单双引号都认"
  #    之后，它在**代码块里**也匹配上了 —— `dsapp_escape()` 不转义单引号，
  #    于是一段代码里的 `src='a.png'` 被当成真属性、白名单判不过、被换成空串，
  #    用户看到的代码**凭空少一截**（实测 `parts.append("<img src='a.png'>")`
  #    渲染成 `parts.append("<img >")`）。修法是**只在标签内部找属性**。
  chk("★★★ 代码块里单引号的 `src='…'` 不许被消毒链吃掉", {
    src <- "```python\nparts.append(\"<img src='a.png'>\")\n```"
    h <- dsapp_md_chat_html(src, NULL, NULL, cfg)
    grepl("src='a.png'", h, fixed = TRUE)
  })
  chk("★★★ 非聊天路径（邮件/预览/论坛）**不**放行 data: 图片", {
    h <- dsapp_md_html(paste0("<img src='", v154_png, "'>"))
    !grepl("data:image/png", h, fixed = TRUE)
  })
  chk("★★★ 体积闸门：超上限的 data: 图换成一行小字，不是留在 DOM 里", {
    big <- paste0("data:image/png;base64,", strrep("A", 50L))
    h <- dsapp_md_limit_data_imgs(paste0('<img src="', big, '" alt="x" />'), 20L)
    !grepl("<img", h, fixed = TRUE) && grepl("已省略", h, fixed = TRUE)
  })
  chk("★★ 体积闸门只管 data:；http 外链再长也不动它", {
    long <- paste0("https://x/", strrep("a", 50L), ".png")
    h <- dsapp_md_limit_data_imgs(paste0('<img src="', long, '" />'), 20L)
    grepl("<img", h, fixed = TRUE)
  })
  chk("★★ 体积闸门的上限就是 DSAPP_CHAT_INLINE_MAX（4MB 量级，不是随便一个数）",
      is.numeric(DSAPP_CHAT_INLINE_MAX) &&
        DSAPP_CHAT_INLINE_MAX >= 1024^2 && DSAPP_CHAT_INLINE_MAX <= 16 * 1024^2)
  chk("★★ 行内代码段配对：`` ` `` 用两个反引号包起来时里面那个不算闭合", {
    chk_inner <- dsapp_md_chat_html("``a`<img src='x.png'>``", NULL, NULL, cfg)
    # 整段都是行内代码 → 里面的 <img> 不许被重写
    !grepl("<img ", chk_inner, fixed = TRUE)
  })

  # ---- (g) item 1：模型服务被「去激活」的四条路 + 一条自愈 ------------------
  #
  # 用户原话：「上次更新后，我的应用模型似乎被去激活了，我重新点击了更新后才
  # 重新应用，**不要因为版本更新让用户付出额外的操作**」。
  #
  # ⚠️ 这一节的判据全部落在**库里的字节**上，不落在"界面看着对"。从前的自检
  #    在这一项上全绿，而用户是真的被卡住了 —— 因为"提示去设置页填 Key"和
  #    "Key 好好地躺在钥匙串里"可以同时成立。
  #
  # ⚠️ 用**自己的库**（v154t_cfg）。它要把 llm_api_key 手动抹成 NULL 来造现场，
  #    共用主 cfg 的话，万一自愈没生效，后面所有依赖主库设置的断言会跟着红
  #    一片 —— 那是自伤，指不到真正坏掉的地方。这个套路照 V13.6 item 1 那一节。
  v154t_cfg <- cfg
  v154t_cfg$db_path   <- file.path(tmp, "v154_item1.sqlite3")
  v154t_cfg$data_root <- file.path(tmp, "v154_item1_root")
  invisible(dsapp_init_dirs(v154t_cfg))
  v154t_con <- dsapp_db(v154t_cfg)
  v154t_uid <- as.integer(
    mkuser("V154甲", "v154a@selftest.local", "13800001541", "RNA",
           v154t_con)$user$id)
  v154t_key <- "sk-v154-relaykey-0123456789"
  v154t_col <- function() DBI::dbGetQuery(v154t_con,
    "SELECT llm_vendor, llm_api_key FROM users WHERE id = ?",
    params = list(v154t_uid))
  v154t_setcol <- function(v, k) invisible(DBI::dbExecute(v154t_con,
    "UPDATE users SET llm_vendor = ?, llm_api_key = ? WHERE id = ?",
    params = list(v, k, v154t_uid)))
  # ⚠️ 判据一律「**解密之后**的值」，不是密文本身 —— 密文是随机 IV 的，同一把
  #    Key 写两次得到的字符串完全不同。比字符串相等的写法**永远是 FALSE**，
  #    而它报出来是「Key 被清空了」，把人指到错的方向。（V13.6 那节踩过。）
  v154t_plain <- function() {
    k <- v154t_col()$llm_api_key[[1]]
    if (is.null(k) || is.na(k) || !nzchar(k)) "" else dsapp_sec_dec(k) %||% ""
  }

  # ---- 路径 3：UI 与服务端必须用**同一个**厂商回落 --------------------------
  chk("★★★ 停用的厂商回落到 deepseek（UI 与服务端共用这一个函数）", {
    identical(dsapp_vendor_active("yi"), "deepseek") &&
      identical(dsapp_vendor_active("relay"), "relay") &&
      identical(dsapp_vendor_active(NULL), "deepseek") &&
      identical(dsapp_vendor_active("   "), "deepseek")
  })
  chk("★★★ 目录里**没有**的厂商名也要回落（否则下拉框是空白的）", {
    # ⚠️ 这条是探针当场抓出来的：dsapp_vendor_enabled("不认识的") 返回 TRUE，
    #    因为它内部走 dsapp_vendor()，而那个函数对不认识的名字回落到 deepseek
    #    的目录项（enabled = TRUE）。于是"目录里已经没有的厂商名"原样通过 ——
    #    它进不了下拉框的 choices，selectInput 的 selected 指向一个不存在的
    #    选项，**控件显示空白**，而库里的值看着完全正常。
    #    那正是用户说的「模型被去激活了」的样子。
    identical(dsapp_vendor_active("no-such-vendor"), "deepseek") &&
      identical(dsapp_vendor_active("YI"), "deepseek")
  })
  chk("★★★ UI 和服务端读的是同一个函数（不许任何一侧再抄一份回落逻辑）", {
    # 从前回落只写在 mod_model_ui() 里，服务端照抄库里的原值 —— 两边不一致时
    # 切厂商 observer 会把一次「页面初始化」误判成「用户换了厂商」，
    # 顺手把 users.llm_api_key 抹成 NULL。这里钉住两处都调同一个函数。
    src <- paste(readLines("R/mod_model.R", warn = FALSE), collapse = "\n")
    grepl("dsapp_vendor_active(s$vendor)", src, fixed = TRUE) &&
      !grepl('if (!dsapp_vendor_enabled(vendor)) vendor <- "deepseek"',
             src, fixed = TRUE) &&
      !grepl('state$vendor   <- s$vendor %||% "deepseek"', src, fixed = TRUE)
  })

  # ---- 自愈：钥匙串里有、列被抹成 NULL（**用户报的那一条**）-----------------
  chk("★★★ 列被抹成 NULL 时，ensure 把它从钥匙串补回来", {
    invisible(dsapp_api_key_put(v154t_uid, "relay", v154t_key, con = v154t_con))
    v154t_setcol("relay", NA_character_)
    before_empty <- !nzchar(v154t_col()$llm_api_key[[1]] %||% "")
    got <- dsapp_api_key_ensure(v154t_uid, "relay", con = v154t_con)
    before_empty && identical(got, v154t_key) &&
      identical(v154t_plain(), v154t_key)
  })
  chk("★★ 自愈是幂等的（列本来就对的时候只是重写同一串）", {
    got <- dsapp_api_key_ensure(v154t_uid, "relay", con = v154t_con)
    identical(got, v154t_key) && identical(v154t_plain(), v154t_key)
  })

  # ---- 路径 2：厂商没变时，activate 不许把列抹掉 ----------------------------
  chk("★★★ 厂商没变 + 钥匙串行没了 → 列里那把 Key 必须留着", {
    # 造现场：钥匙串那一行没了（换过 data_root / 从老版本升上来 / 被外部库
    # 操作动过），而列里还有 Key，厂商没变。旧实现无条件清空 —— 用户什么都
    # 没干，Key 就没了。
    invisible(dsapp_api_key_forget(v154t_uid, "relay", con = v154t_con))
    v154t_setcol("relay", dsapp_sec_enc("sk-v154-only-copy"))
    invisible(dsapp_api_key_activate(v154t_uid, "relay", con = v154t_con))
    identical(v154t_plain(), "sk-v154-only-copy")
  })
  chk("★★★ 反面：真的换厂商时**必须**清空（否则会拿上一家的 Key 去请求）", {
    # 列里现在是 relay 的 Key，切到 zhipu（没有钥匙串行）—— 留着它就会拿着
    # relay 的凭据去请求 zhipu，回来的 401 里一个字都不提厂商。
    invisible(dsapp_api_key_activate(v154t_uid, "zhipu", con = v154t_con))
    !nzchar(v154t_plain())
  })
  chk("★★ 钥匙串有行时，activate 照常把它镜像进列（没被上面那条护栏挡住）", {
    invisible(dsapp_api_key_forget(v154t_uid, NULL, con = v154t_con))
    invisible(dsapp_api_key_put(v154t_uid, "relay", v154t_key, con = v154t_con))
    v154t_setcol("relay", NA_character_)
    invisible(dsapp_api_key_activate(v154t_uid, "relay", con = v154t_con))
    identical(v154t_plain(), v154t_key)
  })
  chk("★★★ 用户明确点「清除全部厂商」的那条路不受护栏影响", {
    # dsapp_settings_forget_key() 自己写 UPDATE，不走 activate()。这条钉的是
    # 「上面那条护栏不许把用户的明确意图也一起挡掉」——忘了保存的 Key 却还
    # 能用，是最难被发现的一种。
    invisible(dsapp_api_key_put(v154t_uid, "relay", v154t_key, con = v154t_con))
    n <- dsapp_settings_forget_key(v154t_uid, con = v154t_con)
    identical(as.integer(n), 1L) && !nzchar(v154t_plain()) &&
      is.null(dsapp_api_key_recall(v154t_uid, "relay", con = v154t_con))
  })

  # ---- 自愈的判据是「解得开」，不是「行存在」 ------------------------------
  chk("★★★ 钥匙串被换过（密文解不开）时，**不许**往列里补", {
    # ⚠️ 这是这一节最容易被写假的一条。上一版探针我塞的是没有 `v1:` 前缀的
    #    字符串，而 dsapp_sec_dec() 对没有前缀的输入走「老明文」那一支、
    #    原样返回 —— 于是「解得开」这条路**根本没走到**，断言却全绿。
    #    这里用真密文：先拿当前钥匙串加一次，再把钥匙串换掉。
    invisible(dsapp_api_key_forget(v154t_uid, NULL, con = v154t_con))
    invisible(dsapp_api_key_put(v154t_uid, "relay", v154t_key, con = v154t_con))
    ct <- DBI::dbGetQuery(v154t_con,
      "SELECT api_key FROM user_api_keys WHERE user_id = ? AND vendor = 'relay'",
      params = list(v154t_uid))$api_key[[1]]
    is_ct <- is.character(ct) && length(ct) == 1L && !is.na(ct) &&
      startsWith(ct, "v1:")                 # 前提：真的是密文
    v154t_setcol("relay", NA_character_)
    # 换钥匙串：磁盘上写一把新的，进程内缓存也清掉（不然读到的是旧的）
    #
    # ⚠️⚠️ 换的必须是**主 cfg** 那把，不是 v154t_cfg 那把。这里踩过一次：
    #    `dsapp_api_key_put()` 里那句是 `dsapp_sec_enc(k)` —— **没有** cfg
    #    参数，于是它走默认的 `dsapp_config()`，用的是主 data_root 的钥匙串。
    #    换 v154t 那把的话，上面存进去的密文照样能被主钥匙串解开，
    #    recall 返回真 Key、ensure 顺手把列补回来，这条断言就红了 ——
    #    而红的原因和被验的代码毫无关系（纯纯是我换错了文件）。
    #    （这个"put 不认 con 之外的 cfg"本身是个既有的小坑，不在本版范围内。）
    # ⚠️ 换主钥匙串会波及后面所有要解密的断言，所以**跑完必须原样写回去**；
    #    文件本来不存在的话，收尾时把它删掉。
    kf <- dsapp_keyring_path()
    kf_had <- file.exists(kf)
    kf_old <- if (kf_had) readBin(kf, "raw", n = 4096L) else raw(0)
    old <- dsapp_keyring()
    writeBin(openssl::rand_bytes(32L), kf)
    rm(list = ls(envir = .dsapp_keyring_cache), envir = .dsapp_keyring_cache)
    swapped <- !identical(old, dsapp_keyring())
    # 收尾动作定义在这里、无论断言成败都要跑到（下面用 on.exit 不成立：
    # 这里是自检的顶层脚本，on.exit 在顶层块里不会执行 —— 本仓踩过）。
    rec <- tryCatch(dsapp_api_key_recall(v154t_uid, "relay", con = v154t_con),
                    error = function(e) NULL)
    out <- tryCatch(dsapp_api_key_ensure(v154t_uid, "relay", con = v154t_con),
                    error = function(e) "")
    # ---- 把主钥匙串原样装回去（下面的断言还要用它解主库里的密文）---------
    if (kf_had) writeBin(kf_old, kf) else unlink(kf)
    rm(list = ls(envir = .dsapp_keyring_cache), envir = .dsapp_keyring_cache)
    restored <- identical(dsapp_keyring(), old)
    # 补不回来 = 列还是空的、返回值也是空的（调用方照常提示去设置页填）
    # ⚠️ 这一条是"一串 &&"，红的时候只会甩一句标签，指不到是哪一节塌的。
    #    所以五节的实际值都通过 extra 打出来 —— 下次谁改坏了，日志里直接
    #    看得到是"前提：密文"没成立，还是"钥匙串没换成"。
    is_ct && swapped && restored &&
      (is.null(rec) || !nzchar(rec$api_key %||% "")) &&
      !nzchar(v154t_plain()) && !nzchar(out)
  }, extra = sprintf("密文=%s 换串=%s 已还原=%s recall=%s 列=%s 返回=%s [ct=%s rec=%s col=%s]",
                     is_ct, swapped, restored,
                     is.null(rec) || !nzchar(rec$api_key %||% ""),
                     !nzchar(v154t_plain()), !nzchar(out),
                     substr(if (is.na(ct)) "NA" else ct, 1, 12),
                     if (is.null(rec)) "NULL" else rec$api_key %||% "",
                     substr(v154t_col()$llm_api_key[[1]] %||% "NULL", 1, 12)))

  # ---- 路径 4：空厂商一个字节都不许写进 state -------------------------------
  chk("★★★ 状态同步那段 observe 里有空厂商的闸门（%||% 挡不住空串）", {
    src <- paste(readLines("R/mod_model.R", warn = FALSE), collapse = "\n")
    # 判据是"闸门真的在"，不是"有没有某一行字符串" —— 所以钉的是那个形状：
    # 读 input$vendor → 判空 → return，且**判空在读之后**（读 = 建立依赖）。
    grepl("v <- input$vendor\n      if (is.null(v) || !nzchar(v)) return()",
          src, fixed = TRUE)
  })

  # ---- (f) 线上那 5 条真实形状（脱敏后的最小复现）---------------------------
  #
  # ⚠️ 这四条是**真实消息的首行形状**（把正文换成了占位符）。它们一起说明
  #    "粘围栏"不是孤例，而是那个模型在这一类任务里的习惯写法。
  chk("★★ 四条真实消息的粘围栏首行，形状都认得出来", {
    heads <- c(
      "占位。```python",
      "占位。```python",
      "占位。```bash",
      "占位。```r")
    all(vapply(heads, function(hd) {
      txt <- paste0(hd, "\nx <- 1\n```")
      r <- dsapp_md_repair_fences(txt)
      grepl("\n```", r, fixed = TRUE) &&
        !grepl(paste0("占位。```"), r, fixed = TRUE)
    }, logical(1)))
  })
}

# =============================================================================
section("Test_V15.4 item 7：管理与后台合并成「后台管理」")
# =============================================================================
#
# 用户原话：「请合并管理和后台界面，生成一个"后台管理"界面，原有的组间请以
#           合理的分类生成子界面」，追问里选的是「两种管理员都能进，但是
#           进去后看到的界面不一样」+「4 组」。
#
# ⚠️⚠️ 这一节的**核心断言是"跑"出来的，不是读源码**。合并这件事有两个
#    不报错的坏法，读源码一条都查不出来：
#      · 某张卡在新分组里**被漏掉** = 功能悄悄消失（页面照样打得开）；
#      · 同一张卡被塞进了**两个**子页 = 同一块 UI 渲染两遍，两个同 id 的
#        input 并存，谁赢看顺序。
#    所以下面的判据是"14 张卡的卡头，在合并后的页面上**各出现恰好一次**"。
v154_bs_src <- paste(readLines("R/mod_backstage.R", warn = FALSE), collapse = "\n")
v154_mp_src <- paste(readLines("R/mod_prompt.R", warn = FALSE), collapse = "\n")
v154_pr_src <- paste(readLines("R/prompts.R", warn = FALSE), collapse = "\n")
# V16.6 item 1：信息同步跳板那张表所在的文件（下面 schema 版本那条要用）
v166_ss_src <- paste(readLines("R/syncservers.R", warn = FALSE), collapse = "\n")
v154_dep    <- paste(readLines("deploy.sh", warn = FALSE), collapse = "\n")

# 14 张卡的卡头文字。这是从**合并前**那两页抄下来的资产清单 ——
# 故意抄死在这里，而不是从代码里现算：现算的话"漏了一张卡"会跟着一起漏，
# 断言永远为真（那正是这一节要防的事）。
V154_CARDS <- c("服务器健康", "平台用量", "磁盘占用", "平台账号概览",
                "用户", "团队", "登录锁定", "用户活跃情况",
                "各用户的任务运行情况", "操作日志", "应用报错日志",
                "token 用量", "可调用硬件资源", "文件管理区的归属",
                # ★ V16.6 item 1：第 15 张卡（后台页的「信息同步跳板」）
                "信息同步跳板")
# 9 张平台专属（合并前就是 `if (platform)` 守着的那些 + V16.6 的跳板卡）
V154_PLATFORM_ONLY <- c("服务器健康", "平台用量", "磁盘占用", "平台账号概览",
                        "用户活跃情况", "应用报错日志", "可调用硬件资源",
                        "文件管理区的归属", "信息同步跳板")

v154_headers <- function(scope) {
  h <- as.character(mod_backstage_ui("admin", scope = scope))
  m <- regmatches(h, gregexpr('(?s)<div class="card-header[^>]*>.*?</div>',
                              h, perl = TRUE))[[1]]
  trimws(gsub("\\s+", " ", gsub("<[^>]*>", "", m)))
}
# 卡头右边常常跟着一行小字说明（"停用后该账号无法登录…"），所以判据是
# "以标题开头、后面要么到头要么跟一个空格"，**不能**用 startsWith 了事：
# "用户活跃情况" 也以 "用户" 开头，纯前缀匹配会让两张卡互相顶替。
v154_has_card <- function(hd, title) {
  any(startsWith(hd, title) &
        (nchar(hd) == nchar(title) |
           substr(hd, nchar(title) + 1L, nchar(title) + 1L) == " "))
}
v154_tabs <- function(scope) {
  h <- as.character(mod_backstage_ui("admin", scope = scope))
  unique(sub('data-value="([a-z]+)"', "\\1",
             regmatches(h, gregexpr('data-value="[a-z]+"', h))[[1]]))
}

chk("★ 两个新文件都在 app.R 的 source 列表里（漏了的表现是整页空白）", {
  grepl('"mod_backstage.R"', v138_src_app, fixed = TRUE) &&
    grepl('"mod_prompt.R"', v138_src_app, fixed = TRUE)
})
chk("★ 两个新文件也都在 deploy.sh 的清单里（漏了线上就没有这一页）", {
  grepl("R/mod_backstage.R", v154_dep, fixed = TRUE) &&
    grepl("R/mod_prompt.R", v154_dep, fixed = TRUE)
})
chk("★ mod_backstage.R 排在两个 cards 文件**后面**（source 是顺序执行的）", {
  # ⚠️ 它在自己的 UI 函数里**现调** mod_admin_cards() / mod_htadmin_cards()。
  #    排在前面的话那两条函数还没定义 —— 报错是在**渲染时**抛的，
  #    表现是"点后台管理一片空白"，不是启动失败。
  i_bs <- regexpr('"mod_backstage.R"', v138_src_app, fixed = TRUE)
  i_ad <- regexpr('"mod_admin.R"', v138_src_app, fixed = TRUE)
  i_ht <- regexpr('"mod_htadmin.R"', v138_src_app, fixed = TRUE)
  i_bs > 0 && i_ad > 0 && i_ht > 0 && i_bs > i_ad && i_bs > i_ht
})
chk("★ 旧的两个整页 UI 函数**删干净了**（不许留没人调的空壳）", {
  # 留着的话，下一个人会照着"还有 mod_admin_ui 这个入口"去改它，
  # 而页面根本不走那条路 —— 改了没反应，且不报错。
  !grepl("mod_admin_ui <- function", v138_src_admin, fixed = TRUE) &&
    !grepl("mod_htadmin_ui <- function", v138_src_ht, fixed = TRUE) &&
    !grepl("mod_admin_ui(", v138_src_app, fixed = TRUE) &&
    !grepl("mod_htadmin_ui(", v138_src_app, fixed = TRUE)
})
chk("★★★ 15 张卡在合并后的页面上**各出现恰好一次**", {
  hd <- v154_headers("platform")
  # 16 = 15 张卡 + 提示词编辑器那张（item 8 的新能力，不是这 15 张之一）
  length(hd) == 16L &&
    all(vapply(V154_CARDS, function(t) sum(v154_has_card(hd, t)) == 1L,
               logical(1)))
})
chk("★★★ 项目管理员：9 张平台专属的卡一张都不在，另外 6 张一张不少", {
  hd <- v154_headers("project")
  length(hd) == 6L &&
    all(vapply(V154_CARDS, function(t) {
      n <- sum(v154_has_card(hd, t))
      if (t %in% V154_PLATFORM_ONLY) n == 0L else n == 1L
    }, logical(1)))
})
chk("★★★ scope 认不出来时，渲染出来的东西和 project **一模一样**", {
  # ⚠️ 这是本仓库最容易搞反、搞反了最要命的一处。判据写成"显式相等"
  #    （`identical(scope, "platform")`）而不是"不等于 project 就算平台"。
  #
  # ⚠️ 比的**不能是整段 HTML**：navset 的 `data-tabsetid` 是每次渲染新发的
  #    一个随机号（两次调用必然不同），逐字节比永远是 FALSE —— 而它红了
  #    看起来像"权限判断反了"。所以比的是**内容和页签**这两件真的会变的事。
  identical(v154_headers(""), v154_headers("project")) &&
    identical(v154_tabs(""), v154_tabs("project")) &&
    identical(v154_tabs(""), c("users", "runs", "res"))
})
chk("★★ 子页签：平台管理员 6 个（含提示词和同步），项目管理员 3 个", {
  tp <- v154_tabs("platform")
  tj <- v154_tabs("project")
  setequal(tp, c("overview", "users", "runs", "res", "sync", "prompt")) &&
    setequal(tj, c("users", "runs", "res"))
})
chk("★★ 三个 server 都是**平级**注册、且都无条件（注册≠渲染）", {
  # ⚠️ 判据写成"这一行顶着两个空格、前面没有 if" —— 用 `if (is_admin) {...}`
  #    包起来的话注册与否取决于**渲染那一刻**的身份，而 state$user 是登录
  #    快照：登录时是普通用户的人被提成管理员之后刷新，页面出来了但点不动。
  grepl("\n  mod_prompt_server(\"prompt\", state)\n", v138_src_app, fixed = TRUE) &&
    grepl("\n  mod_htadmin_server(\"htadmin\", state, engine)\n", v138_src_app,
          fixed = TRUE) &&
    grepl("\n  mod_admin_server(\"admin\", state, engine)\n", v138_src_app,
          fixed = TRUE)
})
chk("★★ 后台管理那一页只有一个入口，且 value 仍然是 \"admin\"", {
  # `nav_select("nav","admin")` / data-nav 全仓多处认这个字符串，改了就
  # 是"点了没反应、也不报错"。标题改了、value 没改，这两半都要钉住。
  n <- length(gregexpr('nav_panel("后台管理", value = "admin"',
                       v138_src_app, fixed = TRUE)[[1]])
  n == 1L &&
    identical(vapply(Filter(function(x) identical(x$value, "admin"),
                            DSAPP_NAV_ITEMS),
                     function(x) x$label, character(1)), "后台管理")
})

# =============================================================================
section("Test_V15.4 item 8：系统提示词可改（只有平台管理员）")
# =============================================================================
#
# 用户原话：「现在系统默认的提示词是什么？在"后台管理"界面中显示，并支持
#           超级管理员自定义修改」，追问里选的是「分节编辑那 10 个常量段」。
#
# ⚠️⚠️ 这一层改的是**每一个请求**发给模型的东西。所以最要紧的一条不变量是：
#     **表里没有行时，拼出来的提示词必须与改动前逐字节相同**。没有这条的话，
#     "没生效"和"生效了但内容一样"就分不出来 —— 新增一层全局配置最怕这个。
#     下面的做法是**自比**：先留一份基线，塞一条覆盖 → 必须变，删掉 → 必须
#     变回**逐字节相同**的那一份。不需要另写一份"老代码"参考实现。
chk("★★★ 提示词覆盖表是旁挂的，且 schema 版本抬到了 17", {
  db_src <- paste(readLines("R/db.R", warn = FALSE), collapse = "\n")
  # 旁挂表 + 版本号加一的既有形状（mail_queue / lit_subs / model_param_limits）。
  # ⚠️ 版本号不改的话，老库不会重新对账，这张表**根本不会被建** ——
  #    表现是"打开提示词页，右栏是空的"，而没有任何报错。
  # ★ V16.5 item 3：15 → 16（第二张旁挂表 prompt_custom）。这一条盯的是
  #    "两张表**都在**建表函数那条路上"，所以两个 CREATE TABLE 一起查。
  # ★ V16.6 item 1：16 → 17（第三张旁挂表 sync_servers + app_settings，
  #    外加 users 上三个新列）。**这条断言的名字里也写着版本号** ——
  #    只改数字不改名字的话，红的那条会叫"…抬到了 16"而实际值是 17，
  #    报错方向指错（本仓栽过：120→180 漏了两条字面量，红的那条名叫
  #    「顶格写」，报错指向排版）。
  identical(DSAPP_SCHEMA_VERSION, 17L) &&
    grepl("dsapp_db_schema_prompt <- function(con)", v154_pr_src,
          fixed = TRUE) &&
    grepl("dsapp_db_schema_prompt(con)", db_src, fixed = TRUE) &&
    grepl("CREATE TABLE IF NOT EXISTS prompt_overrides", v154_pr_src,
          fixed = TRUE) &&
    grepl("key        TEXT PRIMARY KEY", v154_pr_src, fixed = TRUE) &&
    # ★ V16.5 item 3：新表 prompt_custom 必须**挂在** dsapp_db_schema_prompt
    #   那条路上（它自己建自己那张，由前者调用）—— 挂空了的话这张表永远
    #   不会被建，而"没建"的症状是"新增分类点了没反应、也不报错"。
    grepl("dsapp_db_schema_prompt_custom <- function(con)", v154_pr_src,
          fixed = TRUE) &&
    grepl("CREATE TABLE IF NOT EXISTS prompt_custom", v154_pr_src,
          fixed = TRUE) &&
    grepl("dsapp_db_schema_prompt_custom(con)", v154_pr_src, fixed = TRUE) &&
    # ★ V16.6 item 1：第三张旁挂表 sync_servers（+ app_settings KV）。
    #   同样的形状：建表函数自己一个、db.R 里挂一次。
    #   ⚠️ 它挂在 tryCatch 里，**不是 silent**：这张表建不出来的话，
    #      后台那张卡是空白的，而用户看到的是"管理员页少了一块"。
    grepl("dsapp_db_schema_sync_servers <- function(con)", v166_ss_src,
          fixed = TRUE) &&
    grepl("CREATE TABLE IF NOT EXISTS sync_servers", v166_ss_src,
          fixed = TRUE) &&
    grepl("CREATE TABLE IF NOT EXISTS app_settings", v166_ss_src,
          fixed = TRUE) &&
    grepl("dsapp_db_schema_sync_servers(con)", db_src, fixed = TRUE)
})
chk("★★ 12 节的清单和默认值表，key 集合完全相同", {
  # ⚠️ 少一节的表现是界面上那一节是**空的** —— 管理员会以为"默认提示词里
  #    没有这一段"，然后照着空白去写。
  # ★ V15.5 item 2：10 → 11，多出来的是 DSPROMPT_WORKFLOW（「工作方式」）。
  # ★ V16.5 item 4：11 → 12，多出来的是 DSPROMPT_PLOTTING（「科研绘图」）。
  k1 <- vapply(DSAPP_PROMPT_PARTS, function(p) p$key, character(1))
  length(k1) == 12L && setequal(k1, names(DSAPP_PROMPT_DEFAULTS)) &&
    length(unique(k1)) == 12L
})
chk("★★ 只有 10 节可改，另外 2 节标着 derived（拼出来的那两节）", {
  # ★ V15.5 item 2：8 → 9（WORKFLOW 是可改的叶子节）。
  # ★ V16.5 item 4：9 → 10（PLOTTING 也是可改的叶子节）。
  d <- vapply(DSAPP_PROMPT_PARTS, function(p) isTRUE(p$derived), logical(1))
  sum(d) == 2L &&
    setequal(vapply(DSAPP_PROMPT_PARTS[d], function(p) p$key, character(1)),
             c("DSPROMPT_CODE_RULES", "DSPROMPT_CODE_RULES_AGENT"))
})
chk("★★★ 10 节**每一节**都真的会进提示词（漏一节 = 界面上能改、改了不生效）", {
  # ⚠️⚠️ 这一条**故意**不是"数一数 build_system_prompt 里调了几次
  #    dsapp_prompt_part()"。那是个纯文本判据，而漏掉一节恰恰不会报错：
  #    界面上那一节能改、也显示"已修改"，模型收到的还是内置那份。
  #    （实测：写成数调用次数的时候，HEAD 那一节因为走的是变量 `head_key`，
  #      数出来是 5 不是 8 —— 这种判据连"数对了没有"都要靠人去核。）
  #    所以改成**行为**判据：往每一节里塞一个只属于它的标记，再看它该出现的
  #    场景里有没有、不该出现的场景里有没有混进去。
  SCN <- list(DSPROMPT_IDENTITY              = c("chat", "agent", "debug", "plan"),
              DSPROMPT_CAPABILITIES          = c("chat", "agent", "debug", "plan"),
              # ★ V15.5 item 2：WORKFLOW（工作方式）也挂在**所有**场景上 ——
              #    它讲的是"怎么理解任务、怎么省资源、出错怎么修"，这四条场景
              #    一个都躲不掉，所以这里写死四个场景名。
              DSPROMPT_WORKFLOW              = c("chat", "agent", "debug", "plan"),
              # ⚠️ debug 场景**只是"能力清单 + 交互约定"**，代码铁律一节都不进
              #    （R/prompts.R 里那三个分支之一）。这条表是**跑出来核过的**：
              #    一开始我按"debug 也是手动模式"写成了 c("chat","debug")，
              #    当场被下面这半边否定断言抓住。
              DSPROMPT_CODE_RULES_HEAD       = "chat",
              DSPROMPT_CODE_RULES_HEAD_AGENT = "agent",
              DSPROMPT_CODE_RULES_TAIL       = c("chat", "agent"),
              DSPROMPT_EXECUTION             = "chat",
              DSPROMPT_EXECUTION_AGENT       = "agent",
              DSPROMPT_INTERACTION           = c("chat", "agent", "debug", "plan"),
              # ★ V16.5 item 4：科研绘图（PLOTTING）挂在**所有**场景上 ——
              #    它是"图该怎么画"的领域规范，写方案（plan）和排错（debug）
              #    一样躲不掉；而且它默认就是开的（默认正文来自那份 .md），
              #    只在 chat 里生效的话，"自动执行时画的图不走这套规范"这句
              #    就成了真的。
              DSPROMPT_PLOTTING              = c("chat", "agent", "debug", "plan"))
  con <- dsapp_db(cfg)
  ok <- TRUE
  for (k in names(SCN)) {
    mk <- paste0("★标记-", k, "★")
    dsapp_prompt_put(k, mk, user_id = 1L, con = con)
    for (sc in SCN[[k]]) {
      if (!grepl(mk, build_system_prompt(sc, cfg), fixed = TRUE)) ok <- FALSE
    }
    # 不该出现的地方也不能出现 —— 只查"在的都在"的话，把某一节错挂到所有
    # 场景上（比如 plan 也收到"代码不会自动执行"）照样绿。
    for (sc in setdiff(c("chat", "agent", "debug", "plan"), SCN[[k]])) {
      if (grepl(mk, build_system_prompt(sc, cfg), fixed = TRUE)) ok <- FALSE
    }
    dsapp_prompt_clear(k, con = con)
  }
  # 收尾：9 行都删干净（后面的断言依赖"表是空的"）
  n_left <- DBI::dbGetQuery(con,
    "SELECT COUNT(*) AS n FROM prompt_overrides")$n
  ok && as.integer(n_left) == 0L
})
chk("★★★ 拼出来的那两节是**现拼**的，改了 HEAD 它跟着变", {
  # ⚠️ 这是写完当场抓到的一个真 bug：DSPROMPT_CODE_RULES 那个常数是源码里
  #    就拼好的，`DSAPP_PROMPT_DEFAULTS[["DSPROMPT_CODE_RULES"]]` 读它 ——
  #    管理员改了 HEAD 之后，界面上显示"已自定义"，而右栏那个只读框里还是
  #    **老文本**，他会以为自己没保存上。dsapp_prompt_get() 必须现拼。
  before <- dsapp_prompt_get("DSPROMPT_CODE_RULES")
  dsapp_prompt_put("DSPROMPT_CODE_RULES_HEAD", "★哨兵-HEAD★")
  mid <- dsapp_prompt_get("DSPROMPT_CODE_RULES")
  dsapp_prompt_clear("DSPROMPT_CODE_RULES_HEAD")
  after <- dsapp_prompt_get("DSPROMPT_CODE_RULES")
  grepl("★哨兵-HEAD★", mid, fixed = TRUE) &&
    identical(before, after) && !identical(before, mid)
})
chk("★★★ 改一节 → 提示词真变；恢复默认 → **逐字节**变回原来那份", {
  # ⚠️⚠️ 这是 item 8 的核心不变量。改动**之前**先确认连的是自检自己的临时库：
  #    自检曾经因为顶层 `{ }` 里的 on.exit 不执行而泄漏过 DSAPP_DATA_ROOT，
  #    把一次写操作落进了生产库。写库之前先证明这个库是临时的。
  ok_db <- startsWith(normalizePath(cfg$db_path, mustWork = FALSE),
                      normalizePath(tmp, mustWork = FALSE))
  if (!ok_db) {
    cat("      \033[31m库不在临时目录里，跳过写库断言（这本身是个问题！）\033[0m\n")
  }
  ok_db && {
    con <- dsapp_db(cfg)
    dsapp_prompt_clear_cache()
    g0 <- build_system_prompt("chat", cfg)
    dsapp_prompt_put("DSPROMPT_IDENTITY", "★哨兵-身份★", user_id = 1L, con = con)
    g1 <- build_system_prompt("chat", cfg)
    # 另一个进程看到的是库里那一份（进程内缓存要能重新灌）
    dsapp_prompt_clear_cache(); dsapp_prompt_load(con)
    g1b <- build_system_prompt("chat", cfg)
    dsapp_prompt_clear("DSPROMPT_IDENTITY", con = con)
    g2 <- build_system_prompt("chat", cfg)
    n_row <- DBI::dbGetQuery(con,
      "SELECT COUNT(*) AS n FROM prompt_overrides WHERE key = 'DSPROMPT_IDENTITY'")$n
    grepl("★哨兵-身份★", g1, fixed = TRUE) &&
      !grepl("★哨兵-身份★", g0, fixed = TRUE) &&
      identical(g1, g1b) &&          # 灌一次缓存就够，不是"只有本进程知道"
      identical(g0, g2) &&           # ★ 逐字节复原
      as.integer(n_row) == 0L        # 恢复默认 = 删行，不留残余
  }
})
chk("★★ 覆盖成**空串** = 这一节别注入（不是「没改过」）", {
  # ⚠️ 这里**不能**用 `%||%`：空串在它眼里和 NULL 一样，两边各自读都通，
  #    只有一起看才发现少了一节。
  con <- dsapp_db(cfg)
  g0 <- build_system_prompt("chat", cfg)
  dsapp_prompt_put("DSPROMPT_INTERACTION", "", user_id = 1L, con = con)
  g1 <- build_system_prompt("chat", cfg)
  dsapp_prompt_clear("DSPROMPT_INTERACTION", con = con)
  g2 <- build_system_prompt("chat", cfg)
  nchar(g1) < nchar(g0) && identical(g0, g2) &&
    !identical(g0, g1)
})
chk("★★ 段名不认识时 put/clear 都返回 FALSE（不许静默成功）", {
  # 静默成功的表现是：界面上说"已保存"，而库里什么都没有。
  !isTRUE(dsapp_prompt_put("DSPROMPT_没这一节", "x")) &&
    !isTRUE(dsapp_prompt_clear("DSPROMPT_没这一节")) &&
    is.null(dsapp_prompt_get("DSPROMPT_没这一节"))
})
chk("★★ 12 节默认值逐个对得上（表空时 get 就是内置默认）", {
  dsapp_prompt_clear_cache()
  all(vapply(names(DSAPP_PROMPT_DEFAULTS), function(k) {
    identical(dsapp_prompt_get(k), DSAPP_PROMPT_DEFAULTS[[k]])
  }, logical(1)))
})
chk("★★ 编辑器：10 节都列出来，两个 derived 标成只读", {
  grepl("DSAPP_PROMPT_PARTS", v154_mp_src, fixed = TRUE) &&
    grepl("（只读）", v154_mp_src, fixed = TRUE) &&
    grepl("selectInput(ns(\"pp_part\")", v154_mp_src, fixed = TRUE) &&
    grepl("size = length(ch)", v154_mp_src, fixed = TRUE)
})
chk("★★★ 列表框的 choices 方向没反：**值是常量名、显示的是中文标签**", {
  # ★★★ 这条是 2026-09-29 补的，起因是一个**真被抓到的 bug**：
  #     第一版把方向写反了（值 = 中文标签、名字 = 常量名）。Shiny 的
  #     selectInput 对有名向量的约定是「名字显示给用户、值是 input 收到的」，
  #     反过来的症状是这一版最难看出来的一种 ——
  #       · 左边 10 行显示的是 `DSPROMPT_IDENTITY` 这种常量名；
  #       · 点任何一行，input$pp_part 收到中文标签，cur_key() 那句
  #         "不认识的 key 回落到第一节"把它静默吃掉 → **点「代码铁律」，
  #         编辑框里出来的是「身份」**，保存也确实写库成功（写的正是身份）；
  #       · 只读那两节切过去照样有 textarea（因为根本没切过去）。
  #     全程不报错，是 tests/ui_v154/probe_v154.py 抓出来的。
  #
  # ⚠️ 所以这里断的是**渲染出来的 HTML**，不是源码里有没有那句 selectInput
  #    —— 上一版断言只查了"有没有这个词"，它对这个 bug 完全失明。
  #    （selftest-green-is-not-coverage，这一版第三次。）
  # ⚠️ `selectInput` 在 **shiny** 里，不在 htmltools 里（第一版写成
  #    htmltools::selectInput，报的是 "'selectInput' is not an exported
  #    object from 'namespace:htmltools'" —— 而这条断言**照样是红的**，
  #    只是红的原因和它要查的东西无关）。
  ch <- dsapp_prompt_choices(NULL)
  h  <- as.character(shiny::selectInput("pp_part", NULL, choices = ch,
                                        selectize = FALSE,
                                        size = length(ch)))
  opt <- regmatches(h, gregexpr("<option[^>]*>[^<]*</option>", h))[[1]]
  val <- sub('^<option value="([^"]*)".*$', "\\1", opt)
  txt <- sub("^.*>(.*)</option>$", "\\1", opt)
  identical(val, vapply(DSAPP_PROMPT_PARTS, function(p) p$key, character(1))) &&
    !any(grepl("^DSPROMPT_", txt)) &&
    sum(grepl("（只读）", txt, fixed = TRUE)) == 2L &&
    all(vapply(DSAPP_PROMPT_PARTS, function(p) p$label, character(1)) %in%
          sub("（只读）$", "", txt))
})
chk("★★ 「已改」那个后缀只出现在**真的改过**的那一节上", {
  # 顺带钉住另一头：rows 为空时一节都不该标「已改」，塞一行之后只有它标。
  # ⚠️ 标记错了的症状是"管理员以为自己改过这一节" —— 与事实相反，且不报错。
  a <- dsapp_prompt_choices(NULL)
  b <- dsapp_prompt_choices(data.frame(key = "DSPROMPT_EXECUTION",
                                       stringsAsFactors = FALSE))
  !any(grepl("已改", names(a), fixed = TRUE)) &&
    sum(grepl("已改", names(b), fixed = TRUE)) == 1L &&
    names(b)[grepl("已改", names(b), fixed = TRUE)] ==
      names(b)[b == "DSPROMPT_EXECUTION"]
})
chk("★★★ 编辑器的**每一条写库的路**都先过 guard() 再记一笔审计", {
  # 这个页签只对平台管理员渲染，但那只挡"看不见"：一个被降级的人在他开着的
  # 标签页里按钮还能点。写操作一共两条（保存 / 恢复默认），各要一次 guard。
  n_guard <- length(gregexpr("if (!guard()) return(invisible(NULL))",
                             v154_mp_src, fixed = TRUE)[[1]])
  n_audit <- length(gregexpr("audit(\"prompt_", v154_mp_src, fixed = TRUE)[[1]])
  n_guard >= 2L && n_audit >= 2L &&
    grepl("dsapp_user_is_platform_admin(me())", v154_mp_src, fixed = TRUE) &&
    grepl("dsapp_user_by_id(uid, con = dsapp_db(cfg))", v154_mp_src,
          fixed = TRUE)
})
chk("★★ 编辑器和它的 server 在同一个命名空间下（NS(\"prompt\") == \"prompt\"）", {
  # ⚠️ 对不上的症状是"按钮点了没反应、也不报错"（input 名对不上，
  #    observer 永远不触发）—— 而这一页全是按钮。
  grepl('mod_prompt_ui(NS("prompt"))', v154_bs_src, fixed = TRUE) &&
    grepl('mod_prompt_server("prompt", state)', v138_src_app, fixed = TRUE) &&
    grepl("mod_prompt_server <- function(id, state)", v154_mp_src, fixed = TRUE) &&
    # ⚠️ 认的是 `<- session$ns`（不为对齐写成几个空格）—— 写死 `ns <- session$ns`
    #    这种带单空格的形状，会被"对齐过的赋值"（`ns  <- session$ns`）
    #    判成没有，而这条红了看起来像"命名空间没对上"。
    grepl("<- session$ns", v154_mp_src, fixed = TRUE)
})
chk("★★ 拼装后的全文里 {{MAXITER}}/{{MAXWALL}} 用当前值填掉，不留占位符", {
  # 这一格是 item 8「现在系统默认的提示词是什么」的正面回答，
  # 留一个 {{MAXITER}} 在上面等于没回答。
  p <- build_system_prompt("agent", cfg)
  !grepl("{{MAXITER}}", p, fixed = TRUE) &&
    !grepl("{{MAXWALL}}", p, fixed = TRUE)
})
chk("★★ 思考中的活人感提示词：至少 12 条、互不相同、界面只用一条通道轮换", {
  length(DSAPP_THINK_QUIPS) >= 12L &&
    length(unique(DSAPP_THINK_QUIPS)) == length(DSAPP_THINK_QUIPS) &&
    all(nzchar(DSAPP_THINK_QUIPS))
})

