section("Test_V16.5 item 3：超管能**新增**系统提示词的分类")
# =============================================================================
#
# 用户原话：「系统提示词需要能新增分类」。
#
# ⚠️ 最要紧的不变量和覆盖层那条是**同一个**：表里没有行时，拼出来的提示词
#    必须与这一层不存在时**逐字节相同**。做法也是自比（留基线 → 加 → 必须变
#    → 删 → 必须逐字节变回），不另写一份参考实现。
chk("★ （前置）自定义分类表是空的、而且读出来是 0 行的表不是 NULL", {
  # ⚠️ 返回 NULL 的话，调用方每一处都得写 is.null —— 漏一处就是
  #    "nrow(NULL)" 报错，而报错的地方离现场很远。
  r <- dsapp_prompt_custom()
  is.data.frame(r) && nrow(r) == 0L && identical(nrow(dsapp_prompt_custom_empty()), 0L)
})
chk("★★★ 加一节 → 进每一类请求；删掉 → **逐字节**变回原来那份", {
  # ⚠️⚠️ 写库之前先证明这个库是临时的：自检曾经因为顶层 `{ }` 里的 on.exit
  #    不执行而泄漏过 DSAPP_DATA_ROOT，把一次写操作落进了生产库。
  ok_db <- startsWith(normalizePath(cfg$db_path, mustWork = FALSE),
                      normalizePath(tmp, mustWork = FALSE))
  if (!ok_db) {
    cat("      \033[31m库不在临时目录里，跳过写库断言（这本身是个问题！）\033[0m\n")
  }
  ok_db && {
    con <- dsapp_db(cfg)
    g0 <- build_system_prompt("chat", cfg)
    k1 <- dsapp_prompt_custom_add("哨兵分类甲", "★哨兵-自定甲★",
                                  user_id = 1L, con = con)
    k2 <- dsapp_prompt_custom_add("哨兵分类乙", "★哨兵-自定乙★",
                                  user_id = 1L, con = con)
    hit <- vapply(c("chat", "agent", "debug", "plan"), function(sc) {
      p <- build_system_prompt(sc, cfg)
      grepl("★哨兵-自定甲★", p, fixed = TRUE) &&
        grepl("★哨兵-自定乙★", p, fixed = TRUE)
    }, logical(1))
    # 顺序按 pos：甲在乙前面（不是按 key 的字符串序 —— 那个会把 _10 排到 _2 前）
    p <- build_system_prompt("chat", cfg)
    ordered <- regexpr("★哨兵-自定甲★", p, fixed = TRUE)[1] <
      regexpr("★哨兵-自定乙★", p, fixed = TRUE)[1]
    dsapp_prompt_custom_del(k1, con = con)
    dsapp_prompt_custom_del(k2, con = con)
    g1 <- build_system_prompt("chat", cfg)
    n_left <- DBI::dbGetQuery(con,
      "SELECT COUNT(*) AS n FROM prompt_custom")$n
    nzchar(k1) && nzchar(k2) && k1 != k2 && all(hit) && ordered &&
      identical(g0, g1) && as.integer(n_left) == 0L
  }
})
chk("★★★ 第 10 节排在最后，不是排在第 2 节前面（按 pos，不按 key 的字符串序）", {
  # ⚠️ 这条针对一个**真会踩**的坑：key 是 TEXT，`DSPROMPT_CUSTOM_10` 按字符串
  #    比 `DSPROMPT_CUSTOM_2` **小** —— 加满十节之后第 10 节会跳到第 2 节
  #    前面去（左栏、提示词里都是），而没有任何报错。
  #    判据走**真实那条路**：连着加十节，看读回来的顺序和拼进提示词的先后。
  #    （⚠️ 别自己写一句 ORDER BY 去查临时表 —— 那验的是 SQLite 不是我们的
  #      代码，我们的 SQL 真写错了它也照样绿。）
  con <- dsapp_db(cfg)
  ks <- vapply(1:10, function(i)
    dsapp_prompt_custom_add(sprintf("哨兵%d", i), sprintf("★哨兵-%02d★", i),
                            user_id = 1L, con = con), character(1))
  r <- dsapp_prompt_custom()
  p <- build_system_prompt("chat", cfg)
  i2  <- regexpr("★哨兵-02★", p, fixed = TRUE)[1]
  i10 <- regexpr("★哨兵-10★", p, fixed = TRUE)[1]
  ok <- identical(tail(r$key, 1), "DSPROMPT_CUSTOM_10") &&
    identical(r$key, sprintf("DSPROMPT_CUSTOM_%d", 1:10)) &&
    i2 > 0 && i10 > i2
  for (k in ks) dsapp_prompt_custom_del(k, con = con)
  ok
})
chk("★★ 改名不换 key、不丢正文（界面上显示的是名字，库里认的是 key）", {
  con <- dsapp_db(cfg)
  k <- dsapp_prompt_custom_add("哨兵-原名", "★哨兵-正文不动★",
                               user_id = 1L, con = con)
  ok1 <- isTRUE(dsapp_prompt_custom_put(k, "哨兵-新名", "★哨兵-正文不动★",
                                        user_id = 1L, con = con))
  r <- dsapp_prompt_custom()
  i <- match(k, r$key)
  ok2 <- !is.na(i) && identical(as.character(r$label[i]), "哨兵-新名") &&
    identical(as.character(r$body[i]), "★哨兵-正文不动★")
  dsapp_prompt_custom_del(k, con = con)
  nzchar(k) && ok1 && ok2
})
chk("★★ 空名字 / 不存在的 key：都不许静默成功", {
  # 静默成功的表现是界面上说"已保存 / 已新增"，而库里什么都没有。
  con <- dsapp_db(cfg)
  !nzchar(dsapp_prompt_custom_add("   ", "x", con = con)) &&
    !nzchar(dsapp_prompt_custom_add("", "x", con = con)) &&
    !isTRUE(dsapp_prompt_custom_put("DSPROMPT_CUSTOM_999", "名", "正文", con = con)) &&
    !isTRUE(dsapp_prompt_custom_put("DSPROMPT_IDENTITY", "名", "正文", con = con)) &&
    !isTRUE(dsapp_prompt_custom_del("DSPROMPT_CUSTOM_999", con = con)) &&
    is.null(dsapp_prompt_custom_get("DSPROMPT_CUSTOM_999")) &&
    nrow(dsapp_prompt_custom(con)) == 0L
})
chk("★★ 正文留空的那一节不进提示词，但**还在**左栏（不是被删了）", {
  con <- dsapp_db(cfg)
  g0 <- build_system_prompt("chat", cfg)
  k <- dsapp_prompt_custom_add("哨兵-空的", "", user_id = 1L, con = con)
  g1 <- build_system_prompt("chat", cfg)
  ok <- identical(g0, g1) && nrow(dsapp_prompt_custom()) == 1L
  dsapp_prompt_custom_del(k, con = con)
  nzchar(k) && ok
})
chk("★★★ 列表框的 choices 方向没反：**值是 key、显示的是「自定义 · 名字」**", {
  # 方向写反的症状见 dsapp_prompt_choices() 上面那段 ⚠️⚠️：点自定义那一行，
  # 右栏出来的是「身份」，保存写的也是身份，全程不报错。
  con <- dsapp_db(cfg)
  k <- dsapp_prompt_custom_add("哨兵-方向", "★哨兵-方向★",
                               user_id = 1L, con = con)
  ch <- dsapp_prompt_custom_choices(dsapp_prompt_custom(con))
  h  <- as.character(shiny::selectInput("pp_part", NULL, choices = ch,
                                        selectize = FALSE, size = length(ch)))
  opt <- regmatches(h, gregexpr("<option[^>]*>[^<]*</option>", h))[[1]]
  val <- sub('^<option value="([^"]*)".*$', "\\1", opt)
  txt <- sub("^.*>(.*)</option>$", "\\1", opt)
  dsapp_prompt_custom_del(k, con = con)
  identical(val, k) && identical(txt, "自定义 · 哨兵-方向") &&
    identical(names(dsapp_prompt_custom_choices(NULL)), character(0))
})
chk("★★★ 子进程那半截：没人显式 load 过时，第一次用到会**自己灌**", {
  # ⚠️⚠️ 这条挡的是一个**真窟窿**（V15.4 带进来、V16.5 加自定义分类时才发现）：
  #    app.R 只在应用进程启动时调一次 dsapp_prompt_load()，而自动执行是在
  #    R/detach.R 的 .dsapp_agent_worker 那个**另一个 R 进程**里拼系统提示词的
  #    —— 它从来不调 load，于是超管改的提示词在挂机续跑那一侧一个字都不变。
  #    判据：清掉"灌过"的标记 + 清掉缓存（= 新进程刚开始的样子），再拼一次，
  #    必须能看见库里那一行。不自己灌的话这里拼出来的是内置默认。
  con <- dsapp_db(cfg)
  dsapp_prompt_put("DSPROMPT_IDENTITY", "★哨兵-子进程★", user_id = 1L, con = con)
  dsapp_prompt_clear_cache()
  .dsapp_prompt_loaded$v <- FALSE          # 模拟"这个进程还没灌过"
  got <- grepl("★哨兵-子进程★", build_system_prompt("chat", cfg), fixed = TRUE)
  dsapp_prompt_clear("DSPROMPT_IDENTITY", con = con)
  dsapp_prompt_clear_cache()
  .dsapp_prompt_loaded$v <- FALSE
  dsapp_prompt_load(con)                   # 收尾：把状态恢复成"灌过了"
  got
})
chk("★★ 编辑器里「新增分类」那条路也过 guard() + 记一笔审计", {
  # 和 V15.4 那条同一件事：页签只对平台管理员渲染，那只挡"看不见" ——
  # 一个被降级的人在他开着的标签页里按钮还能点，所以写库第一句必须是 guard()。
  n_audit <- length(gregexpr("audit(\"prompt_custom_", v154_mp_src,
                             fixed = TRUE)[[1]])
  grepl('actionButton(ns("pp_add")', v154_mp_src, fixed = TRUE) &&
    grepl('actionButton(ns("pp_confirm_add")', v154_mp_src, fixed = TRUE) &&
    grepl('actionButton(ns("pp_del")', v154_mp_src, fixed = TRUE) &&
    grepl('actionButton(ns("pp_confirm_del")', v154_mp_src, fixed = TRUE) &&
    grepl("dsapp_prompt_custom_add(", v154_mp_src, fixed = TRUE) &&
    grepl("dsapp_prompt_custom_del(", v154_mp_src, fixed = TRUE) &&
    # 四条写库的路（新增 / 保存自定义 / 删除 / 内置节保存走原来那条）——
    # 数出来必须 ≥ 5，因为 V15.4 那两条也还算在里面。
    length(gregexpr("if (!guard()) return(invisible(NULL))", v154_mp_src,
                    fixed = TRUE)[[1]]) >= 5L &&
    n_audit >= 3L
})
