  as.integer(DBI::dbGetQuery(con,
    "SELECT COUNT(*) AS n FROM prompt_custom")$n) == 0L &&
    as.integer(DBI::dbGetQuery(con,
      "SELECT COUNT(*) AS n FROM prompt_overrides")$n) == 0L
})

