    identical(dsapp_ctx_limit("deepseek", "deepseek-flash", NA), w) &&
    identical(dsapp_ctx_limit("deepseek", "deepseek-flash", ""), w)
})
chk("★★ 用户填了就按用户填的来", {
  identical(dsapp_ctx_limit("deepseek", "deepseek-flash", 32000), 32000)
})
# ⚠️ 这一条是本项最容易写反的地方：NULL 在 dsapp_ctx_is_follow 里是 **TRUE**
#    （和 dsapp_maxtok_is_unlimited 刻意相反）。写反的症状是"默认那一档
#    不跟随模型、而是变成一个写死的数"，而界面上完全看不出来。
chk("★★★ NULL 算「跟随模型」（和 dsapp_maxtok_is_unlimited 刻意相反）", {
  isTRUE(dsapp_ctx_is_follow(NULL)) && isTRUE(dsapp_ctx_is_follow(0)) &&
    isTRUE(dsapp_ctx_is_follow(NA)) && isTRUE(dsapp_ctx_is_follow("")) &&
    !isTRUE(dsapp_ctx_is_follow(8192)) &&
    # 那一侧 NULL 是 FALSE，两边必须不一样 —— 一样的话说明有人把它们统一了
    !isTRUE(dsapp_maxtok_is_unlimited(NULL))
})

# ---- token 估算 ----------------------------------------------------------
chk("★★ 中文按 1 字 1 token、英文按 4 字符 1 token（估算，不是分词）", {
  n_cn <- dsapp_ctx_token_est(paste(rep("中", 1000), collapse = ""))
  n_en <- dsapp_ctx_token_est(paste(rep("a", 4000), collapse = ""))
  n_cn >= 1000 && n_cn <= 1100 && n_en >= 1000 && n_en <= 1100
})
chk("★ 估算在空输入上不炸（NULL / 空串 / character(0) / 全空白）", {
  all(vapply(list(NULL, "", character(0), "   ", NA_character_),
             function(x) isTRUE(dsapp_ctx_token_est(x) >= 0), logical(1)))
})
chk("★★ 同样的字符数下，中文估出来的 token 明显更多（这就是要分开算的理由）", {
  cn <- dsapp_ctx_token_est(paste(rep("中", 400), collapse = ""))
  en <- dsapp_ctx_token_est(paste(rep("a", 400), collapse = ""))
  cn > 3 * en
})

# ---- 预算推导 ------------------------------------------------------------
chk("★★★ 1M 窗口的预算**明显大于**老的写死值 48000 字符", {
  lim <- dsapp_ctx_limit("deepseek", "deepseek-flash", NULL)
  dsapp_ctx_char_budget(lim, dsapp_ctx_out_reserve(lim)) > 48000
})
chk("★★★ 小窗口的预算**必须小于**它的窗口能装下的字符数（不许有地板顶穿）", {
  b <- dsapp_ctx_char_budget(8192, dsapp_ctx_out_reserve(8192))
  # 8192 token ≈ 13107 字符（比率 1.6）。预算超了的话，每一次请求都会超限，
  # 而且看起来像厂商的错。
  b <= 8192 * DSAPP_CTX_CHARS_PER_TOKEN
})
# ⚠️ 这一条第一版写的是「8192 时余量 == MIN_OUT」—— 那是把"下限"当成了
#    "结果"。8192/2 = 4096 > 2048，下限根本没轮到，写的是"典型值"不是
#    "边界"。真正要钉的是两件事：**大窗口有上限**（不然 1M 窗口留 512K
#    给回复，历史预算白白砍一半）、**小窗口余量不超过总量本身**
#    （不然 out + used ≤ limit 当场破）。
chk("★★ 回复余量：有下限、有上限，且永远不超过总上限", {
  r128 <- dsapp_ctx_out_reserve(131072)     # 典型的 128K
  r1m  <- dsapp_ctx_out_reserve(1048576)    # 1M：必须被 OUT_CAP 压住
  r8   <- dsapp_ctx_out_reserve(8192)       # 一半在上下限之间 → 取一半
  r2k  <- dsapp_ctx_out_reserve(2048)       # 一半触到下限 → 取一半
  r1k  <- dsapp_ctx_out_reserve(1024)       # 一半低于下限 → 被总量压住
  r128 == DSAPP_CTX_OUT_CAP && r1m == DSAPP_CTX_OUT_CAP &&
    r8 == 4096 && r2k == 1024 && r1k == 512 &&
    # 无论多小，余量本身都不许超过总量（后面那条不变式的半边）
    all(vapply(c(1024, 2048, 4096, 8192, 131072, 1048576),
               function(l) dsapp_ctx_out_reserve(l) <= max(l, 1), logical(1)))
})
# ⚠️★ 这一条是设计里最容易写错的一处：回复上限如果取"剩下的全部"，
#    1M 窗口 + 2 万历史会发出 max_tokens = 100 万，绝大多数厂商直接 400。
chk("★★★ 回复上限取的是**余量**，不是「剩下的全部」", {
  lim <- 1048576
  o <- dsapp_ctx_out_tokens(lim, 20000)
  o <= DSAPP_CTX_OUT_CAP
})
chk("★★ 上下文占满时回复被压到下限，但**不为 0 / 不为负**", {
  o <- dsapp_ctx_out_tokens(131072, 200000)
  o == DSAPP_CTX_MIN_OUT
})
chk("★ 坏输入不炸（NA / Inf / 负数 / NULL）", {
  ok <- TRUE
  for (l in list(NA, Inf, -1, NULL, 0)) {
    for (u in list(NA, -5, NULL, 1e9)) {
      r <- tryCatch(dsapp_ctx_out_tokens(l, u), error = function(e) e)
      if (inherits(r, "error") || !is.finite(r) || r < 1) ok <- FALSE
    }
  }
  ok
})

# ---- plan：唯一一处推导 --------------------------------------------------
mk_msgs <- function(n = 5, txt = "中") {
  lapply(seq_len(n), function(i) list(role = "user",
                                      content = paste(rep(txt, 100),
                                                      collapse = "")))
}
chk("★★★ dsapp_ctx_plan 的形状和分量都对", {
  p <- dsapp_ctx_plan(mk_msgs(3), "deepseek", "deepseek-flash", NULL)
  is.list(p) &&
    identical(sort(names(p)), sort(c("limit", "used", "out", "pct"))) &&
    p$limit == 1048576 && p$used > 0 && p$out >= DSAPP_CTX_MIN_OUT &&
    p$pct >= 0 && p$pct <= 100
})
# ⚠️⚠️ 这一条是这次改动**唯一**要保证的事，所以它必须先说清楚"保证的是
#    哪一条路"。历史那一半不是 plan 裁的，是 dsapp_build_context() 按
#    字符预算裁的（plan 只是**量**一下裁完的结果）。所以：
#      · 生产那条路（历史已经按预算裁过）→ out + used ≤ limit **必须**成立；
#      · 直接把一个没裁过的超长历史喂进 plan → 谁也保证不了，这时能保证的
#        只有"回复额度不为 0、不为负"。
#    第一版把两件事混在一起测（拿 400 条消息直接喂 plan），红的样子看起来
#    像"预算算错了"，其实测的是"plan 不会替 build_context 干活"。
#    ★ 而"预算裁过的历史一定装得下"这件事，靠的是 DSAPP_CTX_CHARS_PER_TOKEN
#      是估算器的**上界**（=1.0）。那条断言在下面单独钉。
chk("★★★ plan 里 out + used 不超过 limit（这是整个改动的**唯一**保证）", {
  ok <- TRUE
  # ⚠️ 1024 / 2048 也进来了：那两档够不着（量程的下限是 DSAPP_CTX_MIN_TOTAL
  #    4096），但 dsapp_ctx_limit() 会把它们抬到 4096，所以它们**也必须**
  #    成立 —— 不然一个旧快照就能让这条等式破掉，而旧快照是会发生的
  #    （后台进程读的是离开页面那一刻存的 params）。
  for (lim in c(1024, 2048, 4096, 8192, 32768, 131072, 1048576)) {
    # 按 dsapp_build_context() 的口径裁一份"刚好塞满预算"的历史（全中文，
    # 这是最坏情况：1 字 1 token）
    b <- dsapp_ctx_char_budget(lim, dsapp_ctx_out_reserve(lim))
    msgs <- list(list(role = "system", content = paste(rep("中", b), collapse = "")),
                 list(role = "user", content = "接着写"))
    p <- dsapp_ctx_plan(msgs, "deepseek", "deepseek-flash", lim)
    if (p$used + p$out > p$limit) ok <- FALSE
  }
  ok
})
chk("★★★ 字符预算是估算器的**上界**（不是「典型中英混排比」）", {
  # 全中文是最坏情况：估算器给 1 字 1 token。预算按 ratio 算出来的字符数，
  # 估算回去**必须**不超过 inner。ratio > 1 的话这里是红的。
  ok <- TRUE
  for (lim in c(1024, 2048, 8192, 131072, 1048576)) {
    rs <- dsapp_ctx_out_reserve(lim)
    b  <- dsapp_ctx_char_budget(lim, rs)
    if (dsapp_ctx_token_est(paste(rep("中", b), collapse = "")) > lim - rs) ok <- FALSE
  }
  ok
})
# 反过来那一半：没裁过的历史喂进来，plan 也不许算出 0 / 负数。
chk("★★ ★ 历史没裁过（超长）时，回复额度至少不为 0", {
  p <- dsapp_ctx_plan(mk_msgs(400), "deepseek", "deepseek-flash", 8192)
  p$out >= 1 && p$out <= p$limit
})
chk("★ plan 的 pct 是整数百分比，且不超过 100", {
  p <- dsapp_ctx_plan(mk_msgs(2000), "deepseek", "deepseek-flash", 8192)
  p$pct >= 0 && p$pct <= 100 && p$pct == as.integer(p$pct)
})

# ---- 接线：三处必须同一个源 ----------------------------------------------
chk("★★★ 发请求那一处用的是 plan$out，不是用户填的那个数", {
  grepl("max_tokens = plan$out", strip_comments(src_chat), fixed = TRUE) &&
